window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["PSA"]={"book":"PSA","editions":{"hbo-source":[[1,1,"אַ֥שְֽׁרֵי־הָ⁠אִ֗ישׁ אֲשֶׁ֤ר ׀ לֹ֥א הָלַךְ֮ בַּ⁠עֲצַ֪ת רְשָׁ֫עִ֥ים וּ⁠בְ⁠דֶ֣רֶךְ חַ֭טָּאִים לֹ֥א עָמָ֑ד וּ⁠בְ⁠מוֹשַׁ֥ב לֵ֝צִ֗ים לֹ֣א יָשָֽׁב׃","ʼa֥şĕֽ̌réy-há⁠ʼi֗yş̌ ʼàşě֤r ׀ lò֥ʼ hálakĕ֮ bȧ⁠ʻàẕa֪ţ rĕşá̌֫ʻi֥ym ẇ⁠bĕ⁠de֣rekĕ ẖa֭tá̇ʼiym lò֥ʼ ʻámá֑d ẇ⁠bĕ⁠mwòşǎ֥b lé֝ẕi֗ym lò֣ʼ yáşáֽ̌b׃"],[1,2,"כִּ֤י אִ֥ם בְּ⁠תוֹרַ֥ת יְהוָ֗ה חֶ֫פְצ֥⁠וֹ וּֽ⁠בְ⁠תוֹרָת֥⁠וֹ יֶהְגֶּ֗ה יוֹמָ֥ם וָ⁠לָֽיְלָה׃","ki֤̇y ʼi֥m bĕ̇⁠ţwòra֥ţ yĕhwá֗h ẖe֫pĕẕ֥⁠wò ẇֽ⁠bĕ⁠ţwòráţ֥⁠wò yehĕgė֗h ywòmá֥m wá⁠láֽyĕláh׃"],[1,3,"וְֽ⁠הָיָ֗ה כְּ⁠עֵץ֮ שָׁת֪וּל עַֽל־פַּלְגֵ֫י מָ֥יִם אֲשֶׁ֤ר פִּרְי֨⁠וֹ ׀ יִתֵּ֬ן בְּ⁠עִתּ֗⁠וֹ וְ⁠עָלֵ֥⁠הוּ לֹֽא־יִבּ֑וֹל וְ⁠כֹ֖ל אֲשֶׁר־יַעֲשֶׂ֣ה יַצְלִֽיחַ׃","wĕֽ⁠háyá֗h kĕ̇⁠ʻéẕ֮ şá̌ţ֪ẇl ʻaֽl-pȧlĕgé֫y má֥yim ʼàşě֤r pi̇rĕy֨⁠wò ׀ yiţé̇֬n bĕ̇⁠ʻiţ̇֗⁠wò wĕ⁠ʻálé֥⁠hẇ lòֽʼ-yiḃ֑wòl wĕ⁠kò֖l ʼàşěr-yaʻàşê֣h yaẕĕliֽyẖa׃"],[1,4,"לֹא־כֵ֥ן הָ⁠רְשָׁעִ֑ים כִּ֥י אִם־כַּ֝⁠מֹּ֗ץ אֲֽשֶׁר־תִּדְּפֶ֥⁠נּוּ רֽוּחַ׃","lòʼ-ké֥n há⁠rĕşá̌ʻi֑ym ki֥̇y ʼim-kȧ֝⁠mò̇֗ẕ ʼàֽşěr-ţi̇dĕ̇pe֥⁠ṅẇ rֽẇẖa׃"],[1,5,"עַל־כֵּ֤ן ׀ לֹא־יָקֻ֣מוּ רְ֭שָׁעִים בַּ⁠מִּשְׁפָּ֑ט וְ֝⁠חַטָּאִ֗ים בַּ⁠עֲדַ֥ת צַדִּיקִֽים׃","ʻal-ké֤̇n ׀ lòʼ-yáqu֣mẇ rĕ֭şá̌ʻiym bȧ⁠mi̇şĕ̌pá֑̇t wĕ֝⁠ẖatá̇ʼi֗ym bȧ⁠ʻàda֥ţ ẕadi̇yqiֽym׃"],[1,6,"כִּֽי־יוֹדֵ֣עַ יְ֭הוָה דֶּ֣רֶךְ צַדִּיקִ֑ים וְ⁠דֶ֖רֶךְ רְשָׁעִ֣ים תֹּאבֵֽד׃","kiֽ̇y-ywòdé֣ʻa yĕ֭hwáh dė֣rekĕ ẕadi̇yqi֑ym wĕ⁠de֖rekĕ rĕşá̌ʻi֣ym ţò̇ʼbéֽd׃"],[2,1,"לָ֭⁠מָּה רָגְשׁ֣וּ גוֹיִ֑ם וּ֝⁠לְאֻמִּ֗ים יֶהְגּוּ־רִֽיק׃","lá֭⁠má̇h rágĕş֣̌ẇ gwòyi֑m ẇ֝⁠lĕʼumi̇֗ym yehĕġẇ-riֽyq׃"],[2,2,"יִ֥תְיַצְּב֨וּ ׀ מַלְכֵי־אֶ֗רֶץ וְ⁠רוֹזְנִ֥ים נֽוֹסְדוּ־יָ֑חַד עַל־יְ֝הוָה וְ⁠עַל־מְשִׁיחֽ⁠וֹ׃","yi֥ţĕyaẕĕ̇b֨ẇ ׀ malĕkéy-ʼe֗reẕ wĕ⁠rwòzĕni֥ym nֽwòsĕdẇ-yá֑ẖad ʻal-yĕ֝hwáh wĕ⁠ʻal-mĕşǐyẖֽ⁠wò׃"],[2,3,"נְֽ֭נַתְּקָה אֶת־מֽוֹסְרוֹתֵ֑י⁠מוֹ וְ⁠נַשְׁלִ֖יכָה מִמֶּ֣⁠נּוּ עֲבֹתֵֽי⁠מוֹ׃","nĕֽ֭naţĕ̇qáh ʼeţ-mֽwòsĕrwòţé֑y⁠mwò wĕ⁠naşĕ̌li֖ykáh mimė֣⁠ṅẇ ʻàbòţéֽy⁠mwò׃"],[2,4,"יוֹשֵׁ֣ב בַּ⁠שָּׁמַ֣יִם יִשְׂחָ֑ק אֲ֝דֹנָ֗⁠י יִלְעַג־לָֽ⁠מוֹ׃","ywòşé֣̌b bȧ⁠şá̇̌ma֣yim yişĕ̂ẖá֑q ʼà֝dòná֗⁠y yilĕʻag-láֽ⁠mwò׃"],[2,5,"אָ֤ז יְדַבֵּ֣ר אֵלֵ֣י⁠מוֹ בְ⁠אַפּ֑⁠וֹ וּֽ⁠בַ⁠חֲרוֹנ֥⁠וֹ יְבַהֲלֵֽ⁠מוֹ׃","ʼá֤z yĕdabé֣̇r ʼélé֣y⁠mwò bĕ⁠ʼaṗ֑⁠wò ẇֽ⁠ba⁠ẖàrwòn֥⁠wò yĕbahàléֽ⁠mwò׃"],[2,6,"וַ֭⁠אֲנִי נָסַ֣כְתִּי מַלְכִּ֑⁠י עַל־צִ֝יּ֗וֹן הַר־קָדְשִֽׁ⁠י׃","wa֭⁠ʼàniy nása֣kĕţi̇y malĕki֑̇⁠y ʻal-ẕi֝ẏ֗wòn har-qádĕşǐֽ⁠y׃"],[2,7,"אֲסַפְּרָ֗ה אֶֽ֫ל חֹ֥ק יְֽהוָ֗ה אָמַ֘ר אֵלַ֥⁠י בְּנִ֥⁠י אַ֑תָּה אֲ֝נִ֗י הַ⁠יּ֥וֹם יְלִדְתִּֽי⁠ךָ׃","ʼàsapĕ̇rá֗h ʼeֽ֫l ẖò֥q yĕֽhwá֗h ʼáma֘r ʼéla֥⁠y bĕ̇ni֥⁠y ʼa֑ţá̇h ʼà֝ni֗y ha⁠ẏ֥wòm yĕlidĕţiֽ̇y⁠ká׃"],[2,8,"שְׁאַ֤ל מִמֶּ֗⁠נִּי וְ⁠אֶתְּנָ֣ה ג֭וֹיִם נַחֲלָתֶ֑⁠ךָ וַ֝⁠אֲחֻזָּתְ⁠ךָ֗ אַפְסֵי־אָֽרֶץ׃","şĕ̌ʼa֤l mimė֗⁠ni̇y wĕ⁠ʼeţĕ̇ná֣h g֭wòyim naẖàláţe֑⁠ká wa֝⁠ʼàẖuzá̇ţĕ⁠ká֗ ʼapĕséy-ʼáֽreẕ׃"],[2,9,"תְּ֭רֹעֵ⁠ם בְּ⁠שֵׁ֣בֶט בַּרְזֶ֑ל כִּ⁠כְלִ֖י יוֹצֵ֣ר תְּנַפְּצֵֽ⁠ם׃","ţĕ֭̇ròʻé⁠m bĕ̇⁠şé֣̌bet bȧrĕze֑l ki̇⁠kĕli֖y ywòẕé֣r ţĕ̇napĕ̇ẕéֽ⁠m׃"],[2,10,"וְ֭⁠עַתָּה מְלָכִ֣ים הַשְׂכִּ֑ילוּ הִ֝וָּסְר֗וּ שֹׁ֣פְטֵי אָֽרֶץ׃","wĕ֭⁠ʻaţá̇h mĕláki֣ym haşĕ̂ki֑̇ylẇ hi֝wá̇sĕr֗ẇ şò֣̌pĕtéy ʼáֽreẕ׃"],[2,11,"עִבְד֣וּ אֶת־יְהוָ֣ה בְּ⁠יִרְאָ֑ה וְ֝⁠גִ֗ילוּ בִּ⁠רְעָדָֽה׃","ʻibĕd֣ẇ ʼeţ-yĕhwá֣h bĕ̇⁠yirĕʼá֑h wĕ֝⁠gi֗ylẇ bi̇⁠rĕʻádáֽh׃"],[2,12,"נַשְּׁקוּ־בַ֡ר פֶּן־יֶאֱנַ֤ף ׀ וְ⁠תֹ֬אבְדוּ דֶ֗רֶךְ כִּֽי־יִבְעַ֣ר כִּ⁠מְעַ֣ט אַפּ֑⁠וֹ אַ֝שְׁרֵ֗י כָּל־ח֥וֹסֵי בֽ⁠וֹ׃","naşĕ̇̌qẇ-ba֡r pėn-yeʼèna֤p ׀ wĕ⁠ţò֬ʼbĕdẇ de֗rekĕ kiֽ̇y-yibĕʻa֣r ki̇⁠mĕʻa֣t ʼaṗ֑⁠wò ʼa֝şĕ̌ré֗y ká̇l-ẖ֥wòséy bֽ⁠wò׃"],[3,1,"יְ֭הוָה מָֽה־רַבּ֣וּ צָרָ֑⁠י רַ֝בִּ֗ים קָמִ֥ים עָלָֽ⁠י׃","yĕ֭hwáh máֽh-raḃ֣ẇ ẕárá֑⁠y ra֝bi̇֗ym qámi֥ym ʻáláֽ⁠y׃"],[3,2,"רַבִּים֮ אֹמְרִ֪ים לְ⁠נַ֫פְשִׁ֥⁠י אֵ֤ין יְֽשׁוּעָ֓תָ⁠ה לּ֬⁠וֹ בֵֽ⁠אלֹהִ֬ים סֶֽלָה׃","rabi̇ym֮ ʼòmĕri֪ym lĕ⁠na֫pĕşǐ֥⁠y ʼé֤yn yĕֽş̌ẇʻá֓ţá⁠h l̇֬⁠wò béֽ⁠ʼlòhi֬ym seֽláh׃"],[3,3,"וְ⁠אַתָּ֣ה יְ֭הוָה מָגֵ֣ן בַּעֲדִ֑⁠י כְּ֝בוֹדִ֗⁠י וּ⁠מֵרִ֥ים רֹאשִֽׁ⁠י׃","wĕ⁠ʼaţá֣̇h yĕ֭hwáh mágé֣n bȧʻàdi֑⁠y kĕ̇֝bwòdi֗⁠y ẇ⁠méri֥ym ròʼşǐֽ⁠y׃"],[3,4,"ק֭וֹלִ⁠י אֶל־יְהוָ֣ה אֶקְרָ֑א וַ⁠יַּֽעֲנֵ֨⁠נִי מֵ⁠הַ֖ר קָדְשׁ֣⁠וֹ סֶֽלָה׃","q֭wòli⁠y ʼel-yĕhwá֣h ʼeqĕrá֑ʼ wa⁠yȧֽʻàné֨⁠niy mé⁠ha֖r qádĕş֣̌⁠wò seֽláh׃"],[3,5,"אֲנִ֥י שָׁכַ֗בְתִּי וָֽ⁠אִ֫ישָׁ֥נָ⁠ה הֱקִיצ֑וֹתִי כִּ֖י יְהוָ֣ה יִסְמְכֵֽ⁠נִי׃","ʼàni֥y şá̌ka֗bĕţi̇y wáֽ⁠ʼi֫yşá֥̌ná⁠h hèqiyẕ֑wòţiy ki֖̇y yĕhwá֣h yisĕmĕkéֽ⁠niy׃"],[3,6,"לֹֽא־אִ֭ירָא מֵ⁠רִבְב֥וֹת עָ֑ם אֲשֶׁ֥ר סָ֝בִ֗יב שָׁ֣תוּ עָלָֽ⁠י׃","lòֽʼ-ʼi֭yráʼ mé⁠ribĕb֥wòţ ʻá֑m ʼàşě֥r sá֝bi֗yb şá֣̌ţẇ ʻáláֽ⁠y׃"],[3,7,"ק֘וּמָ֤⁠ה יְהוָ֨ה ׀ הוֹשִׁ֘יעֵ֤⁠נִי אֱלֹהַ֗⁠י כִּֽי־הִכִּ֣יתָ אֶת־כָּל־אֹיְבַ֣⁠י לֶ֑חִי שִׁנֵּ֖י רְשָׁעִ֣ים שִׁבַּֽרְתָּ׃","q֘ẇmá֤⁠h yĕhwá֨h ׀ hwòşǐ֘yʻé֤⁠niy ʼèlòha֗⁠y kiֽ̇y-hiki֣̇yţá ʼeţ-ká̇l-ʼòyĕba֣⁠y le֑ẖiy şǐné֖̇y rĕşá̌ʻi֣ym şǐbȧֽrĕţá̇׃"],[3,8,"לַ⁠יהוָ֥ה הַ⁠יְשׁוּעָ֑ה עַֽל־עַמְּ⁠ךָ֖ בִרְכָתֶ֣⁠ךָ סֶּֽלָה׃","la⁠yhwá֥h ha⁠yĕş̌ẇʻá֑h ʻaֽl-ʻamĕ̇⁠ká֖ birĕkáţe֣⁠ká sėֽláh׃"],[4,1,"בְּ⁠קָרְאִ֡⁠י עֲנֵ֤⁠נִי ׀ אֱלֹ֘הֵ֤י צִדְקִ֗⁠י בַּ֭⁠צָּר הִרְחַ֣בְתָּ לִּ֑⁠י חָ֝נֵּ֗⁠נִי וּ⁠שְׁמַ֥ע תְּפִלָּתִֽ⁠י׃","bĕ̇⁠qárĕʼi֡⁠y ʻàné֤⁠niy ׀ ʼèlò֘hé֤y ẕidĕqi֗⁠y bȧ֭⁠ẕá̇r hirĕẖa֣bĕţá̇ li֑̇⁠y ẖá֝né̇֗⁠niy ẇ⁠şĕ̌ma֥ʻ ţĕ̇pilá̇ţiֽ⁠y׃"],[4,2,"בְּנֵ֥י אִ֡ישׁ עַד־מֶ֬ה כְבוֹדִ֣⁠י לִ֭⁠כְלִמָּה תֶּאֱהָב֣וּ⁠ן רִ֑יק תְּבַקְשׁ֖וּ כָזָ֣ב סֶֽלָה׃","bĕ̇né֥y ʼi֡yş̌ ʻad-me֬h kĕbwòdi֣⁠y li֭⁠kĕlimá̇h ţėʼèháb֣ẇ⁠n ri֑yq ţĕ̇baqĕş֖̌ẇ kázá֣b seֽláh׃"],[4,3,"וּ⁠דְע֗וּ כִּֽי־הִפְלָ֣ה יְ֭הוָה חָסִ֣יד ל֑⁠וֹ יְהוָ֥ה יִ֝שְׁמַ֗ע בְּ⁠קָרְאִ֥⁠י אֵלָֽי⁠ו׃","ẇ⁠dĕʻ֗ẇ kiֽ̇y-hipĕlá֣h yĕ֭hwáh ẖási֣yd l֑⁠wò yĕhwá֥h yi֝şĕ̌ma֗ʻ bĕ̇⁠qárĕʼi֥⁠y ʼéláֽy⁠w׃"],[4,4,"רִגְז֗וּ וְֽ⁠אַל־תֶּ֫חֱטָ֥אוּ אִמְר֣וּ בִ֭⁠לְבַבְ⁠כֶם עַֽל־מִשְׁכַּבְ⁠כֶ֗ם וְ⁠דֹ֣מּוּ סֶֽלָה׃","rigĕz֗ẇ wĕֽ⁠ʼal-ţė֫ẖètá֥ʼẇ ʼimĕr֣ẇ bi֭⁠lĕbabĕ⁠kem ʻaֽl-mişĕ̌kȧbĕ⁠ke֗m wĕ⁠dò֣ṁẇ seֽláh׃"],[4,5,"זִבְח֥וּ זִבְחֵי־צֶ֑דֶק וּ֝⁠בִטְח֗וּ אֶל־יְהוָֽה׃","zibĕẖ֥ẇ zibĕẖéy-ẕe֑deq ẇ֝⁠bitĕẖ֗ẇ ʼel-yĕhwáֽh׃"],[4,6,"רַבִּ֥ים אֹמְרִים֮ מִֽי־יַרְאֵ֪⁠נ֫וּ ט֥וֹב נְֽסָ⁠ה־עָ֭לֵי⁠נוּ א֨וֹר פָּנֶ֬י⁠ךָ יְהוָֽה׃","rabi֥̇ym ʼòmĕriym֮ miֽy-yarĕʼé֪⁠n֫ẇ t֥wòb nĕֽsá⁠h-ʻá֭léy⁠nẇ ʼ֨wòr pá̇ne֬y⁠ká yĕhwáֽh׃"],[4,7,"נָתַ֣תָּה שִׂמְחָ֣ה בְ⁠לִבִּ֑⁠י מֵ⁠עֵ֬ת דְּגָנָ֖⁠ם וְ⁠תִֽירוֹשָׁ֣⁠ם רָֽבּוּ׃","náţa֣ţá̇h şîmĕẖá֣h bĕ⁠libi֑̇⁠y mé⁠ʻé֬ţ dĕ̇gáná֖⁠m wĕ⁠ţiֽyrwòşá֣̌⁠m ráֽḃẇ׃"],[4,8,"בְּ⁠שָׁל֣וֹם יַחְדָּו֮ אֶשְׁכְּבָ֪ה וְ⁠אִ֫ישָׁ֥ן כִּֽי־אַתָּ֣ה יְהוָ֣ה לְ⁠בָדָ֑ד לָ֝⁠בֶ֗טַח תּוֹשִׁיבֵֽ⁠נִי׃","bĕ̇⁠şá̌l֣wòm yaẖĕdá̇w֮ ʼeşĕ̌kĕ̇bá֪h wĕ⁠ʼi֫yşá֥̌n kiֽ̇y-ʼaţá֣̇h yĕhwá֣h lĕ⁠bádá֑d lá֝⁠be֗taẖ ţ̇wòşǐybéֽ⁠niy׃"],[5,1,"אֲמָרַ֖⁠י הַאֲזִ֥ינָ⁠ה ׀ יְהוָ֗ה בִּ֣ינָ⁠ה הֲגִֽיגִ⁠י׃","ʼàmára֖⁠y haʼàzi֥yná⁠h ׀ yĕhwá֗h bi֣̇yná⁠h hàgiֽygi⁠y׃"],[5,2,"הַקְשִׁ֤יבָ⁠ה ׀ לְ⁠ק֬וֹל שַׁוְעִ֗⁠י מַלְכִּ֥⁠י וֵ⁠אלֹהָ֑⁠י כִּֽי־אֵ֝לֶ֗י⁠ךָ אֶתְפַּלָּֽל׃","haqĕşǐ֤ybá⁠h ׀ lĕ⁠q֬wòl şǎwĕʻi֗⁠y malĕki֥̇⁠y wé⁠ʼlòhá֑⁠y kiֽ̇y-ʼé֝le֗y⁠ká ʼeţĕpȧláֽ̇l׃"],[5,3,"יְֽהוָ֗ה בֹּ֭קֶר תִּשְׁמַ֣ע קוֹלִ֑⁠י בֹּ֥קֶר אֶֽעֱרָךְ־לְ֝⁠ךָ֗ וַ⁠אֲצַפֶּֽה׃","yĕֽhwá֗h bò֭̇qer ţi̇şĕ̌ma֣ʻ qwòli֑⁠y bò֥̇qer ʼeֽʻèrákĕ-lĕ֝⁠ká֗ wa⁠ʼàẕapėֽh׃"],[5,4,"כִּ֤י ׀ לֹ֤א אֵֽל־חָפֵ֘ץ רֶ֥שַׁע ׀ אָ֑תָּה לֹ֖א יְגֻרְ⁠ךָ֣ רָֽע׃","ki֤̇y ׀ lò֤ʼ ʼéֽl-ẖápé֘ẕ re֥şǎʻ ׀ ʼá֑ţá̇h lò֖ʼ yĕgurĕ⁠ká֣ ráֽʻ׃"],[5,5,"לֹֽא־יִתְיַצְּב֣וּ הֽ֭וֹלְלִים לְ⁠נֶ֣גֶד עֵינֶ֑י⁠ךָ שָׂ֝נֵ֗אתָ כָּל־פֹּ֥עֲלֵי אָֽוֶן׃","lòֽʼ-yiţĕyaẕĕ̇b֣ẇ hֽ֭wòlĕliym lĕ⁠ne֣ged ʻéyne֑y⁠ká şá̂֝né֗ʼţá ká̇l-pò֥̇ʻàléy ʼáֽwen׃"],[5,6,"תְּאַבֵּד֮ דֹּבְרֵ֪י כָ֫זָ֥ב אִישׁ־דָּמִ֥ים וּ⁠מִרְמָ֗ה יְתָ֘עֵ֥ב ׀ יְהוָֽה׃","ţĕ̇ʼabé̇d֮ dò̇bĕré֪y ká֫zá֥b ʼiyş̌-dá̇mi֥ym ẇ⁠mirĕmá֗h yĕţá֘ʻé֥b ׀ yĕhwáֽh׃"],[5,7,"וַ⁠אֲנִ֗י בְּ⁠רֹ֣ב חַ֭סְדְּ⁠ךָ אָב֣וֹא בֵיתֶ֑⁠ךָ אֶשְׁתַּחֲוֶ֥ה אֶל־הֵֽיכַל־קָ֝דְשְׁ⁠ךָ֗ בְּ⁠יִרְאָתֶֽ⁠ךָ׃","wa⁠ʼàni֗y bĕ̇⁠rò֣b ẖa֭sĕdĕ̇⁠ká ʼáb֣wòʼ béyţe֑⁠ká ʼeşĕ̌ţȧẖàwe֥h ʼel-hֽéykal-qá֝dĕşĕ̌⁠ká֗ bĕ̇⁠yirĕʼáţeֽ⁠ká׃"],[5,8,"יְהוָ֤ה ׀ נְחֵ֬⁠נִי בְ⁠צִדְקָתֶ֗⁠ךָ לְמַ֥עַן שׁוֹרְרָ֑⁠י הושר לְ⁠פָנַ֣⁠י דַּרְכֶּֽ⁠ךָ׃","yĕhwá֤h ׀ nĕẖé֬⁠niy bĕ⁠ẕidĕqáţe֗⁠ká lĕma֥ʻan ş̌wòrĕrá֑⁠y hwşr lĕ⁠pána֣⁠y dȧrĕkėֽ⁠ká׃"],[5,9,"כִּ֤י אֵ֪ין בְּ⁠פִ֡י⁠הוּ נְכוֹנָה֮ קִרְבָּ֪⁠ם הַ֫וּ֥וֹת קֶֽבֶר־פָּת֥וּחַ גְּרוֹנָ֑⁠ם לְ֝שׁוֹנָ֗⁠ם יַחֲלִֽיקוּ⁠ן׃","ki֤̇y ʼé֪yn bĕ̇⁠pi֡y⁠hẇ nĕkwònáh֮ qirĕbá֪̇⁠m ha֫ẇ֥wòţ qeֽber-pá̇ţ֥ẇẖa gĕ̇rwòná֑⁠m lĕ֝ş̌wòná֗⁠m yaẖàliֽyqẇ⁠n׃"],[5,10,"הַֽאֲשִׁימֵ֨⁠ם ׀ אֱֽלֹהִ֗ים יִפְּלוּ֮ מִֽ⁠מֹּעֲצ֪וֹתֵ֫י⁠הֶ֥ם בְּ⁠רֹ֣ב פִּ֭שְׁעֵי⁠הֶם הַדִּיחֵ֑⁠מוֹ כִּי־מָ֥רוּ בָֽ⁠ךְ׃","haֽʼàşǐymé֨⁠m ׀ ʼèֽlòhi֗ym yipĕ̇lẇ֮ miֽ⁠mò̇ʻàẕ֪wòţé֫y⁠he֥m bĕ̇⁠rò֣b pi֭̇şĕ̌ʻéy⁠hem hadi̇yẖé֑⁠mwò ki̇y-má֥rẇ báֽ⁠kĕ׃"],[5,11,"וְ⁠יִשְׂמְח֨וּ כָל־ח֪וֹסֵי בָ֡⁠ךְ לְ⁠עוֹלָ֣ם יְ֭רַנֵּנוּ וְ⁠תָסֵ֣ךְ עָלֵ֑י⁠מוֹ וְֽ⁠יַעְלְצ֥וּ בְ֝⁠ךָ֗ אֹהֲבֵ֥י שְׁמֶֽ⁠ךָ׃","wĕ⁠yişĕ̂mĕẖ֨ẇ kál-ẖ֪wòséy bá֡⁠kĕ lĕ⁠ʻwòlá֣m yĕ֭rané̇nẇ wĕ⁠ţásé֣kĕ ʻálé֑y⁠mwò wĕֽ⁠yaʻĕlĕẕ֥ẇ bĕ֝⁠ká֗ ʼòhàbé֥y şĕ̌meֽ⁠ká׃"],[5,12,"כִּֽי־אַתָּה֮ תְּבָרֵ֪ךְ צַ֫דִּ֥יק יְהוָ֑ה כַּ֝⁠צִּנָּ֗ה רָצ֥וֹן תַּעְטְרֶֽ⁠נּוּ׃","kiֽ̇y-ʼaţá̇h֮ ţĕ̇báré֪kĕ ẕa֫di֥̇yq yĕhwá֑h kȧ֝⁠ẕi̇ná̇֗h ráẕ֥wòn ţȧʻĕtĕreֽ⁠ṅẇ׃"],[6,1,"יְֽהוָ֗ה אַל־בְּ⁠אַפְּ⁠ךָ֥ תוֹכִיחֵ֑⁠נִי וְֽ⁠אַל־בַּ⁠חֲמָתְ⁠ךָ֥ תְיַסְּרֵֽ⁠נִי׃","yĕֽhwá֗h ʼal-bĕ̇⁠ʼapĕ̇⁠ká֥ ţwòkiyẖé֑⁠niy wĕֽ⁠ʼal-bȧ⁠ẖàmáţĕ⁠ká֥ ţĕyasĕ̇réֽ⁠niy׃"],[6,2,"חָנֵּ֥⁠נִי יְהוָה֮ כִּ֤י אֻמְלַ֫ל אָ֥נִי רְפָאֵ֥⁠נִי יְהוָ֑ה כִּ֖י נִבְהֲל֣וּ עֲצָמָֽ⁠י׃","ẖáné֥̇⁠niy yĕhwáh֮ ki֤̇y ʼumĕla֫l ʼá֥niy rĕpáʼé֥⁠niy yĕhwá֑h ki֖̇y nibĕhàl֣ẇ ʻàẕámֽá⁠y׃"],[6,3,"וְ֭⁠נַפְשִׁ⁠י נִבְהֲלָ֣ה מְאֹ֑ד ו⁠את יְ֝הוָ֗ה עַד־מָתָֽי׃","wĕ֭⁠napĕşǐ⁠y nibĕhàlá֣h mĕʼò֑d w⁠ʼţ yĕ֝hwá֗h ʻad-máţáֽy׃"],[6,4,"שׁוּבָ֣⁠ה יְ֭הוָה חַלְּצָ֣⁠ה נַפְשִׁ֑⁠י ה֝וֹשִׁיעֵ֗⁠נִי לְמַ֣עַן חַסְדֶּֽ⁠ךָ׃","ş̌ẇbá֣⁠h yĕ֭hwáh ẖalĕ̇ẕá֣⁠h napĕşǐ֑⁠y h֝wòşǐyʻé֗⁠niy lĕma֣ʻan ẖasĕdėֽ⁠ká׃"],[6,5,"כִּ֤י אֵ֣ין בַּ⁠מָּ֣וֶת זִכְרֶ֑⁠ךָ בִּ֝⁠שְׁא֗וֹל מִ֣י יֽוֹדֶה־לָּֽ⁠ךְ׃","ki֤̇y ʼé֣yn bȧ⁠má֣̇weţ zikĕre֑⁠ká bi̇֝⁠şĕ̌ʼ֗wòl mi֣y yֽwòdeh-láֽ̇⁠kĕ׃"],[6,6,"יָגַ֤עְתִּי ׀ בְּֽ⁠אַנְחָתִ֗⁠י אַשְׂחֶ֣ה בְ⁠כָל־לַ֭יְלָה מִטָּתִ֑⁠י בְּ֝⁠דִמְעָתִ֗⁠י עַרְשִׂ֥⁠י אַמְסֶֽה׃","yága֤ʻĕţi̇y ׀ bĕֽ̇⁠ʼanĕẖáţi֗⁠y ʼaşĕ̂ẖe֣h bĕ⁠kál-la֭yĕláh mitá̇ţi֑⁠y bĕ̇֝⁠dimĕʻáţi֗⁠y ʻarĕşî֥⁠y ʼamĕseֽh׃"],[6,7,"עָֽשְׁשָׁ֣ה מִ⁠כַּ֣עַס עֵינִ֑⁠י עָֽ֝תְקָ֗ה בְּ⁠כָל־צוֹרְרָֽ⁠י׃","ʻáֽşĕ̌şá֣̌h mi⁠kȧ֣ʻas ʻéyni֑⁠y ʻáֽ֝ţĕqá֗h bĕ̇⁠kál-ẕwòrĕráֽ⁠y׃"],[6,8,"ס֣וּרוּ מִ֭מֶּ⁠נִּי כָּל־פֹּ֣עֲלֵי אָ֑וֶן כִּֽי־שָׁמַ֥ע יְ֝הוָ֗ה ק֣וֹל בִּכְיִֽ⁠י׃","s֣ẇrẇ mi֭mė⁠ni̇y ká̇l-pò֣̇ʻàléy ʼá֑wen kiֽ̇y-şá̌ma֥ʻ yĕ֝hwá֗h q֣wòl bi̇kĕyiֽ⁠y׃"],[6,9,"שָׁמַ֣ע יְ֭הוָה תְּחִנָּתִ֑⁠י יְ֝הוָ֗ה תְּֽפִלָּתִ֥⁠י יִקָּֽח׃","şá̌ma֣ʻ yĕ֭hwáh ţĕ̇ẖiná̇ţi֑⁠y yĕ֝hwá֗h ţĕֽ̇pilá̇ţi֥⁠y yiqáֽ̇ẖ׃"],[6,10,"יֵבֹ֤שׁוּ ׀ וְ⁠יִבָּהֲל֣וּ מְ֭אֹד כָּל־אֹיְבָ֑⁠י יָ֝שֻׁ֗בוּ יֵבֹ֥שׁוּ רָֽגַע׃","yébò֤ş̌ẇ ׀ wĕ⁠yibá̇hàl֣ẇ mĕ֭ʼòd ká̇l-ʼòyĕbá֑⁠y yá֝şǔ֗bẇ yébò֥ş̌ẇ ráֽgaʻ׃"],[7,1,"יְהוָ֣ה אֱ֭לֹהַ⁠י בְּ⁠ךָ֣ חָסִ֑יתִי הוֹשִׁיעֵ֥⁠נִי מִ⁠כָּל־רֹ֝דְפַ֗⁠י וְ⁠הַצִּילֵֽ⁠נִי׃","yĕhwá֣h ʼè֭lòha⁠y bĕ̇⁠ká֣ ẖási֑yţiy hwòşǐyʻé֥⁠niy mi⁠ká̇l-rò֝dĕpa֗⁠y wĕ⁠haẕi̇yléֽ⁠niy׃"],[7,2,"פֶּן־יִטְרֹ֣ף כְּ⁠אַרְיֵ֣ה נַפְשִׁ֑⁠י פֹּ֝רֵ֗ק וְ⁠אֵ֣ין מַצִּֽיל׃","pėn-yitĕrò֣p kĕ̇⁠ʼarĕyé֣h napĕşǐ֑⁠y pò̇֝ré֗q wĕ⁠ʼé֣yn maẕiֽ̇yl׃"],[7,3,"יְהוָ֣ה אֱ֭לֹהַ⁠י אִם־עָשִׂ֣יתִי זֹ֑את אִֽם־יֶשׁ־עָ֥וֶל בְּ⁠כַפָּֽ⁠י׃","yĕhwá֣h ʼè֭lòha⁠y ʼim-ʻáşî֣yţiy zò֑ʼţ ʼiֽm-yeş̌-ʻá֥wel bĕ̇⁠kapáֽ̇⁠y׃"],[7,4,"אִם־גָּ֭מַלְתִּי שֽׁוֹלְמִ֥⁠י רָ֑ע וָ⁠אֲחַלְּצָ֖⁠ה צוֹרְרִ֣⁠י רֵיקָֽם׃","ʼim-gá֭̇malĕţi̇y şֽ̌wòlĕmi֥⁠y rá֑ʻ wá⁠ʼàẖalĕ̇ẕá֖⁠h ẕwòrĕri֣⁠y réyqáֽm׃"],[7,5,"יִֽרַדֹּ֥ף אוֹיֵ֨ב ׀ נַפְשִׁ֡⁠י וְ⁠יַשֵּׂ֗ג וְ⁠יִרְמֹ֣ס לָ⁠אָ֣רֶץ חַיָּ֑⁠י וּ⁠כְבוֹדִ֓⁠י ׀ לֶ⁠עָפָ֖ר יַשְׁכֵּ֣ן סֶֽלָה׃","yiֽradò֥̇p ʼwòyé֨b ׀ napĕşǐ֡⁠y wĕ⁠yaşé̇̂֗g wĕ⁠yirĕmò֣s lá⁠ʼá֣reẕ ẖayá֑̇⁠y ẇ⁠kĕbwòdi֓⁠y ׀ le⁠ʻápá֖r yaşĕ̌ké֣̇n seֽláh׃"],[7,6,"ק֘וּמָ֤⁠ה יְהוָ֨ה ׀ בְּ⁠אַפֶּ֗⁠ךָ הִ֭נָּשֵׂא בְּ⁠עַבְר֣וֹת צוֹרְרָ֑⁠י וְ⁠ע֥וּרָ⁠ה אֵ֝לַ֗⁠י מִשְׁפָּ֥ט צִוִּֽיתָ׃","q֘ẇmá֤⁠h yĕhwá֨h ׀ bĕ̇⁠ʼapė֗⁠ká hi֭ná̇şé̂ʼ bĕ̇⁠ʻabĕr֣wòţ ẕwòrĕrá֑⁠y wĕ⁠ʻ֥ẇrá⁠h ʼé֝la֗⁠y mişĕ̌pá֥̇t ẕiwiֽ̇yţá׃"],[7,7,"וַ⁠עֲדַ֣ת לְ֭אֻמִּים תְּסוֹבְבֶ֑⁠ךָּ וְ֝⁠עָלֶ֗י⁠הָ לַ⁠מָּר֥וֹם שֽׁוּבָ⁠ה׃","wa⁠ʻàda֣ţ lĕ֭ʼumi̇ym ţĕ̇swòbĕbe֑⁠ká̇ wĕ֝⁠ʻále֗y⁠há la⁠má̇r֥wòm şֽ̌ẇbá⁠h׃"],[7,8,"יְהוָה֮ יָדִ֪ין עַ֫מִּ֥ים שָׁפְטֵ֥⁠נִי יְהוָ֑ה כְּ⁠צִדְקִ֖⁠י וּ⁠כְ⁠תֻמִּ֣⁠י עָלָֽ⁠י׃","yĕhwáh֮ yádi֪yn ʻa֫mi֥̇ym şá̌pĕté֥⁠niy yĕhwá֑h kĕ̇⁠ẕidĕqi֖⁠y ẇ⁠kĕ⁠ţumi֣̇⁠y ʻáláֽ⁠y׃"],[7,9,"יִגְמָר־נָ֬א רַ֨ע ׀ רְשָׁעִים֮ וּ⁠תְכוֹנֵ֪ן צַ֫דִּ֥יק וּ⁠בֹחֵ֣ן לִ֭בּ֗וֹת וּ⁠כְלָי֗וֹת אֱלֹהִ֥ים צַדִּֽיק׃","yigĕmár-ná֬ʼ ra֨ʻ ׀ rĕşá̌ʻiym֮ ẇ⁠ţĕkwòné֪n ẕa֫di֥̇yq ẇ⁠bòẖé֣n li֭ḃ֗wòţ ẇ⁠kĕláy֗wòţ ʼèlòhi֥ym ẕaḋֽiyq׃"],[7,10,"מָֽגִנִּ֥⁠י עַל־אֱלֹהִ֑ים מ֝וֹשִׁ֗יעַ יִשְׁרֵי־לֵֽב׃","máֽgini֥̇⁠y ʻal-ʼèlòhi֑ym m֝wòşǐ֗yʻa yişĕ̌réy-léֽb׃"],[7,11,"אֱ֭לֹהִים שׁוֹפֵ֣ט צַדִּ֑יק וְ֝⁠אֵ֗ל זֹעֵ֥ם בְּ⁠כָל־יֽוֹם׃","ʼè֭lòhiym ş̌wòpé֣t ẕadi֑̇yq wĕ֝⁠ʼé֗l zòʻé֥m bĕ̇⁠kál-yֽwòm׃"],[7,12,"אִם־לֹ֣א יָ֭שׁוּב חַרְבּ֣⁠וֹ יִלְט֑וֹשׁ קַשְׁתּ֥⁠וֹ דָ֝רַ֗ךְ וַֽ⁠יְכוֹנְנֶֽ⁠הָ׃","ʼim-lò֣ʼ yá֭ş̌ẇb ẖarĕḃ֣⁠wò yilĕt֑wòş̌ qaşĕ̌ţ֥̇⁠wò dá֝ra֗kĕ waֽ⁠yĕkwònĕneֽ⁠há׃"],[7,13,"וְ֭⁠ל⁠וֹ הֵכִ֣ין כְּלֵי־מָ֑וֶת חִ֝צָּ֗י⁠ו לְֽ⁠דֹלְקִ֥ים יִפְעָֽל׃","wĕ֭⁠l⁠wò héki֣yn kĕ̇léy-má֑weţ ẖi֝ẕá̇֗y⁠w lĕֽ⁠dòlĕqi֥ym yipĕʻáֽl׃"],[7,14,"הִנֵּ֥ה יְחַבֶּל־אָ֑וֶן וְ⁠הָרָ֥ה עָ֝מָ֗ל וְ⁠יָ֣לַד שָֽׁקֶר׃","hiné֥̇h yĕẖabėl-ʼá֑wen wĕ⁠hárá֥h ʻá֝má֗l wĕ⁠yá֣lad şáֽ̌qer׃"],[7,15,"בּ֣וֹר כָּ֭רָֽה וַֽ⁠יַּחְפְּרֵ֑⁠הוּ וַ֝⁠יִּפֹּ֗ל בְּ⁠שַׁ֣חַת יִפְעָֽל׃","ḃ֣wòr ká֭̇ráֽh waֽ⁠yȧẖĕpĕ̇ré֑⁠hẇ wa֝⁠yi̇pò̇֗l bĕ̇⁠şǎ֣ẖaţ yipĕʻáֽl׃"],[7,16,"יָשׁ֣וּב עֲמָל֣⁠וֹ בְ⁠רֹאשׁ֑⁠וֹ וְ⁠עַ֥ל קָ֝דְקֳד֗⁠וֹ חֲמָס֥⁠וֹ יֵרֵֽד׃","yáş֣̌ẇb ʻàmál֣⁠wò bĕ⁠ròʼş֑̌⁠wò wĕ⁠ʻa֥l qá֝dĕqod֗⁠wò ẖàmás֥⁠wò yéréֽd׃"],[7,17,"אוֹדֶ֣ה יְהוָ֣ה כְּ⁠צִדְק֑⁠וֹ וַ֝⁠אֲזַמְּרָ֗ה שֵֽׁם־יְהוָ֥ה עֶלְיֽוֹן׃","ʼwòde֣h yĕhwá֣h kĕ̇⁠ẕidĕq֑⁠wò wa֝⁠ʼàzamĕ̇rá֗h şéֽ̌m-yĕhwá֥h ʻelĕyֽwòn׃"],[8,1,"יְהוָ֤ה אֲדֹנֵ֗י⁠נוּ מָֽה־אַדִּ֣יר שִׁ֭מְ⁠ךָ בְּ⁠כָל־הָ⁠אָ֑רֶץ אֲשֶׁ֥ר תְּנָ֥⁠ה ה֝וֹדְ⁠ךָ֗ עַל־הַ⁠שָּׁמָֽיִם׃","yĕhwá֤h ʼàdòné֗y⁠nẇ máֽh-ʼadi֣̇yr şǐ֭mĕ⁠ká bĕ̇⁠kál-há⁠ʼá֑reẕ ʼàşě֥r ţĕ̇ná֥⁠h h֝wòdĕ⁠ká֗ ʻal-ha⁠şá̇̌máֽyim׃"],[8,2,"מִ⁠פִּ֤י עֽוֹלְלִ֨ים ׀ וְֽ⁠יֹנְקִים֮ יִסַּ֪דְתָּ֫ עֹ֥ז לְמַ֥עַן צוֹרְרֶ֑י⁠ךָ לְ⁠הַשְׁבִּ֥ית א֝וֹיֵ֗ב וּ⁠מִתְנַקֵּֽם׃","mi⁠pi֤̇y ʻֽwòlĕli֨ym ׀ wĕֽ⁠yònĕqiym֮ yisȧ֪dĕţá̇֫ ʻò֥z lĕma֥ʻan ẕwòrĕre֑y⁠ká lĕ⁠haşĕ̌bi֥̇yţ ʼ֝wòyé֗b ẇ⁠miţĕnaqéֽ̇m׃"],[8,3,"כִּֽי־אֶרְאֶ֣ה שָׁ֭מֶי⁠ךָ מַעֲשֵׂ֣י אֶצְבְּעֹתֶ֑י⁠ךָ יָרֵ֥חַ וְ֝⁠כוֹכָבִ֗ים אֲשֶׁ֣ר כּוֹנָֽנְתָּה׃","kiֽ̇y-ʼerĕʼe֣h şá֭̌mey⁠ká maʻàşé֣̂y ʼeẕĕbĕ̇ʻòţe֑y⁠ká yáré֥ẖa wĕ֝⁠kwòkábi֗ym ʼàşě֣r k̇wònáֽnĕţá̇h׃"],[8,4,"מָֽה־אֱנ֥וֹשׁ כִּֽי־תִזְכְּרֶ֑⁠נּוּ וּ⁠בֶן־אָ֝דָ֗ם כִּ֣י תִפְקְדֶֽ⁠נּוּ׃","máֽh-ʼèn֥wòş̌ kiֽ̇y-ţizĕkĕ̇re֑⁠ṅẇ ẇ⁠ben-ʼá֝dá֗m ki֣̇y ţipĕqĕdeֽ⁠ṅẇ׃"],[8,5,"וַ⁠תְּחַסְּרֵ֣⁠הוּ מְּ֭עַט מֵ⁠אֱלֹהִ֑ים וְ⁠כָב֖וֹד וְ⁠הָדָ֣ר תְּעַטְּרֵֽ⁠הוּ׃","wa⁠ţĕ̇ẖasĕ̇ré֣⁠hẇ mĕ֭̇ʻat mé⁠ʼèlòhi֑ym wĕ⁠káb֖wòd wĕ⁠hádá֣r ţĕ̇ʻatĕ̇réֽ⁠hẇ׃"],[8,6,"תַּ֭מְשִׁילֵ⁠הוּ בְּ⁠מַעֲשֵׂ֣י יָדֶ֑י⁠ךָ כֹּ֝ל שַׁ֣תָּה תַֽחַת־רַגְלָֽי⁠ו׃","ţȧ֭mĕşǐylé⁠hẇ bĕ̇⁠maʻàşé֣̂y yáde֑y⁠ká kò̇֝l şǎ֣ţá̇h ţaֽẖaţ-ragĕláֽy⁠w׃"],[8,7,"צֹנֶ֣ה וַ⁠אֲלָפִ֣ים כֻּלָּ֑⁠ם וְ֝⁠גַ֗ם בַּהֲמ֥וֹת שָׂדָֽי׃","ẕòne֣h wa⁠ʼàlápi֣ym ku̇lá֑̇⁠m wĕ֝⁠ga֗m bȧhàm֥wòţ şá̂dáֽy׃"],[8,8,"צִפּ֣וֹר שָׁ֭מַיִם וּ⁠דְגֵ֣י הַ⁠יָּ֑ם עֹ֝בֵ֗ר אָרְח֥וֹת יַמִּֽים׃","ẕiṗ֣wòr şá֭̌mayim ẇ⁠dĕgé֣y ha⁠yá֑̇m ʻò֝bé֗r ʼárĕẖ֥wòţ yamiֽ̇ym׃"],[8,9,"יְהוָ֥ה אֲדֹנֵ֑י⁠נוּ מָֽה־אַדִּ֥יר שִׁ֝מְ⁠ךָ֗ בְּ⁠כָל־הָ⁠אָֽרֶץ׃","yĕhwá֥h ʼàdòné֑y⁠nẇ máֽh-ʼadi֥̇yr şǐ֝mĕ⁠ká֗ bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[9,1,"אוֹדֶ֣ה יְ֭הוָה בְּ⁠כָל־לִבִּ֑⁠י אֲ֝סַפְּרָ֗ה כָּל־נִפְלְאוֹתֶֽי⁠ךָ׃","ʼwòde֣h yĕ֭hwáh bĕ̇⁠kál-libi֑̇⁠y ʼà֝sapĕ̇rá֗h ká̇l-nipĕlĕʼwòţeֽy⁠ká׃"],[9,2,"אֶשְׂמְחָ֣ה וְ⁠אֶעֶלְצָ֣ה בָ֑⁠ךְ אֲזַמְּרָ֖ה שִׁמְ⁠ךָ֣ עֶלְיֽוֹן׃","ʼeşĕ̂mĕẖá֣h wĕ⁠ʼeʻelĕẕá֣h bá֑⁠kĕ ʼàzamĕ̇rá֖h şǐmĕ⁠ká֣ ʻelĕyֽwòn׃"],[9,3,"בְּ⁠שׁוּב־אוֹיְבַ֥⁠י אָח֑וֹר יִכָּשְׁל֥וּ וְ֝⁠יֹאבְד֗וּ מִ⁠פָּנֶֽי⁠ךָ׃","bĕ̇⁠ş̌ẇb-ʼwòyĕba֥⁠y ʼáẖ֑wòr yiká̇şĕ̌l֥ẇ wĕ֝⁠yòʼbĕd֗ẇ mi⁠pá̇neֽy⁠ká׃"],[9,4,"כִּֽי־עָ֭שִׂיתָ מִשְׁפָּטִ֣⁠י וְ⁠דִינִ֑⁠י יָשַׁ֥בְתָּ לְ֝⁠כִסֵּ֗א שׁוֹפֵ֥ט צֶֽדֶק׃","kiֽ̇y-ʻá֭şîyţá mişĕ̌pá̇ti֣⁠y wĕ⁠diyni֑⁠y yáşǎ֥bĕţá̇ lĕ֝⁠kisé̇֗ʼ ş̌wòpé֥t ẕeֽdeq׃"],[9,5,"גָּעַ֣רְתָּ ג֭וֹיִם אִבַּ֣דְתָּ רָשָׁ֑ע שְׁמָ֥⁠ם מָ֝חִ֗יתָ לְ⁠עוֹלָ֥ם וָ⁠עֶֽד׃","gá̇ʻa֣rĕţá̇ g֭wòyim ʼibȧ֣dĕţá̇ ráşá֑̌ʻ şĕ̌má֥⁠m má֝ẖi֗yţá lĕ⁠ʻwòlá֥m wá⁠ʻeֽd׃"],[9,6,"הָֽ⁠אוֹיֵ֨ב ׀ תַּ֥מּוּ חֳרָב֗וֹת לָ֫⁠נֶ֥צַח וְ⁠עָרִ֥ים נָתַ֑שְׁתָּ אָבַ֖ד זִכְרָ֣⁠ם הֵֽמָּה׃","háֽ⁠ʼwòyé֨b ׀ ţȧ֥ṁẇ ẖoráb֗wòţ lá֫⁠ne֥ẕaẖ wĕ⁠ʻári֥ym náţa֑şĕ̌ţá̇ ʼába֖d zikĕrá֣⁠m héֽmá̇h׃"],[9,7,"וַֽ֭⁠יהוָה לְ⁠עוֹלָ֣ם יֵשֵׁ֑ב כּוֹנֵ֖ן לַ⁠מִּשְׁפָּ֣ט כִּסְאֽ⁠וֹ׃","waֽ֭⁠yhwáh lĕ⁠ʻwòlá֣m yéşé֑̌b k̇wòné֖n la⁠mi̇şĕ̌pá֣̇t ki̇sĕʼֽ⁠wò׃"],[9,8,"וְ⁠ה֗וּא יִשְׁפֹּֽט־תֵּבֵ֥ל בְּ⁠צֶ֑דֶק יָדִ֥ין לְ֝אֻמִּ֗ים בְּ⁠מֵישָׁרִֽים׃","wĕ⁠h֗ẇʼ yişĕ̌pòֽ̇t-ţé̇bé֥l bĕ̇⁠ẕe֑deq yádi֥yn lĕ֝ʼumi̇֗ym bĕ̇⁠méyşá̌rֽiym׃"],[9,9,"וִ֘⁠יהִ֤י יְהוָ֣ה מִשְׂגָּ֣ב לַ⁠דָּ֑ךְ מִ֝שְׂגָּ֗ב לְ⁠עִתּ֥וֹת בַּצָּרָֽה׃","wi֘⁠yhi֤y yĕhwá֣h mişĕ̂gá֣̇b la⁠dá֑̇kĕ mi֝şĕ̂gá̇֗b lĕ⁠ʻiţ֥̇wòţ bȧẕá̇ráֽh׃"],[9,10,"וְ⁠יִבְטְח֣וּ בְ֭⁠ךָ יוֹדְעֵ֣י שְׁמֶ֑⁠ךָ כִּ֤י לֹֽא־עָזַ֖בְתָּ דֹרְשֶׁ֣י⁠ךָ יְהוָֽה׃","wĕ⁠yibĕtĕẖ֣ẇ bĕ֭⁠ká ywòdĕʻé֣y şĕ̌me֑⁠ká ki֤̇y lòֽʼ-ʻáza֖bĕţá̇ dòrĕşě֣y⁠ká yĕhwáֽh׃"],[9,11,"זַמְּר֗וּ לַ֭⁠יהוָה יֹשֵׁ֣ב צִיּ֑וֹן הַגִּ֥ידוּ בָ֝⁠עַמִּ֗ים עֲלִֽילוֹתָֽי⁠ו׃","zamĕ̇r֗ẇ la֭⁠yhwáh yòşé֣̌b ẕiẏ֑wòn hagi֥̇ydẇ bá֝⁠ʻami̇֗ym ʻàliֽylwòţáֽy⁠w׃"],[9,12,"כִּֽי־דֹרֵ֣שׁ דָּ֭מִים אוֹתָ֣⁠ם זָכָ֑ר לֹֽא־שָׁ֝כַ֗ח צַעֲקַ֥ת עניים׃","kiֽ̇y-dòré֣ş̌ dá֭̇miym ʼwòţá֣⁠m záká֑r lòֽʼ-şá̌֝ka֗ẖ ẕaʻàqa֥ţ ʻnyym׃"],[9,13,"חָֽנְנֵ֬⁠נִי יְהוָ֗ה רְאֵ֣ה עָ֭נְיִ⁠י מִ⁠שֹּׂנְאָ֑⁠י מְ֝רוֹמְמִ֗⁠י מִ⁠שַּׁ֥עֲרֵי מָֽוֶת׃","ẖáֽnĕné֬⁠niy yĕhwá֗h rĕʼé֣h ʻá֭nĕyi⁠y mi⁠şò̇̂nĕʼá֑⁠y mĕ֝rwòmĕmi֗⁠y mi⁠şȧ֥̌ʻàréy máֽweţ׃"],[9,14,"לְמַ֥עַן אֲסַפְּרָ֗ה כָּֽל־תְּהִלָּ֫תֶ֥י⁠ךָ בְּ⁠שַֽׁעֲרֵ֥י בַת־צִיּ֑וֹן אָ֝גִ֗ילָה בִּ⁠ישׁוּעָתֶֽ⁠ךָ׃","lĕma֥ʻan ʼàsapĕ̇rá֗h káֽ̇l-ţĕ̇hilá̇֫ţe֥y⁠ká bĕ̇⁠şǎֽʻàré֥y baţ-ẕiẏ֑wòn ʼá֝gi֗yláh bi̇⁠yş̌ẇʻáţeֽ⁠ká׃"],[9,15,"טָבְע֣וּ ג֭וֹיִם בְּ⁠שַׁ֣חַת עָשׂ֑וּ בְּ⁠רֶֽשֶׁת־ז֥וּ טָ֝מָ֗נוּ נִלְכְּדָ֥ה רַגְלָֽ⁠ם׃","tábĕʻ֣ẇ g֭wòyim bĕ̇⁠şǎ֣ẖaţ ʻáş֑̂ẇ bĕ̇⁠reֽşěţ-z֥ẇ tá֝má֗nẇ nilĕkĕ̇dá֥h ragĕláֽ⁠m׃"],[9,16,"נ֤וֹדַ֨ע ׀ יְהוָה֮ מִשְׁפָּ֪ט עָ֫שָׂ֥ה בְּ⁠פֹ֣עַל כַּ֭פָּי⁠ו נוֹקֵ֣שׁ רָשָׁ֑ע הִגָּי֥וֹן סֶֽלָה׃","n֤wòda֨ʻ ׀ yĕhwáh֮ mişĕ̌pá֪̇t ʻá֫şá֥̂h bĕ̇⁠pò֣ʻal kȧ֭pá̇y⁠w nwòqé֣ş̌ ráşá֑̌ʻ higá̇y֥wòn seֽláh׃"],[9,17,"יָשׁ֣וּבוּ רְשָׁעִ֣ים לִ⁠שְׁא֑וֹלָ⁠ה כָּל־גּ֝וֹיִ֗ם שְׁכֵחֵ֥י אֱלֹהִֽים׃","yáş֣̌ẇbẇ rĕşá̌ʻi֣ym li⁠şĕ̌ʼ֑wòlá⁠h ká̇l-ġ֝wòyi֗m şĕ̌kéẖé֥y ʼèlòhiֽym׃"],[9,18,"כִּ֤י לֹ֣א לָ֭⁠נֶצַח יִשָּׁכַ֣ח אֶבְי֑וֹן תִּקְוַ֥ת ענוים תֹּאבַ֥ד לָ⁠עַֽד׃","ki֤̇y lò֣ʼ lá֭⁠neẕaẖ yişá̇̌ka֣ẖ ʼebĕy֑wòn ţi̇qĕwa֥ţ ʻnwym ţò̇ʼba֥d lá⁠ʻaֽd׃"],[9,19,"קוּמָ֣⁠ה יְ֭הוָה אַל־יָעֹ֣ז אֱנ֑וֹשׁ יִשָּׁפְט֥וּ ג֝וֹיִ֗ם עַל־פָּנֶֽי⁠ךָ׃","qẇmá֣⁠h yĕ֭hwáh ʼal-yáʻò֣z ʼèn֑wòş̌ yişá̇̌pĕt֥ẇ g֝wòyi֗m ʻal-pá̇neֽy⁠ká׃"],[9,20,"שִׁ֘יתָ֤⁠ה יְהוָ֨ה ׀ מוֹרָ֗ה לָ֫⁠הֶ֥ם יֵדְע֥וּ גוֹיִ֑ם אֱנ֖וֹשׁ הֵ֣מָּה סֶּֽלָה׃","şǐ֘yţá֤⁠h yĕhwá֨h ׀ mwòrá֗h lá֫⁠he֥m yédĕʻ֥ẇ gwòyi֑m ʼèn֖wòş̌ hé֣má̇h sėֽláh׃"],[10,1,"לָ⁠מָ֣ה יְ֭הוָה תַּעֲמֹ֣ד בְּ⁠רָח֑וֹק תַּ֝עְלִ֗ים לְ⁠עִתּ֥וֹת בַּצָּרָֽה׃","lá⁠má֣h yĕ֭hwáh ţȧʻàmò֣d bĕ̇⁠ráẖ֑wòq ţȧ֝ʻĕli֗ym lĕ⁠ʻiţ֥̇wòţ bȧẕá̇rֽáh׃"],[10,2,"בְּ⁠גַאֲוַ֣ת רָ֭שָׁע יִדְלַ֣ק עָנִ֑י יִתָּפְשׂ֓וּ ׀ בִּ⁠מְזִמּ֖וֹת ז֣וּ חָשָֽׁבוּ׃","bĕ̇⁠gaʼàwa֣ţ rá֭şá̌ʻ yidĕla֣q ʻáni֑y yiţá̇pĕş̂֓ẇ ׀ bi̇⁠mĕziṁ֖wòţ z֣ẇ ẖáşáֽ̌bẇ׃"],[10,3,"כִּֽי־הִלֵּ֣ל רָ֭שָׁע עַל־תַּאֲוַ֣ת נַפְשׁ֑⁠וֹ וּ⁠בֹצֵ֥עַ בֵּ֝רֵ֗ךְ נִ֘אֵ֥ץ ׀ יְהוָֽה׃","kiֽ̇y-hilé֣̇l rá֭şá̌ʻ ʻal-ţȧʼàwa֣ţ napĕş֑̌⁠wò ẇ⁠bòẕé֥ʻa bé̇֝ré֗kĕ ni֘ʼé֥ẕ ׀ yĕhwáֽh׃"],[10,4,"רָשָׁ֗ע כְּ⁠גֹ֣בַהּ אַ֭פּ⁠וֹ בַּל־יִדְרֹ֑שׁ אֵ֥ין אֱ֝לֹהִ֗ים כָּל־מְזִמּוֹתָֽי⁠ו׃","ráşá̌֗ʻ kĕ̇⁠gò֣baḣ ʼa֭ṗ⁠wò bȧl-yidĕrò֑ş̌ ʼé֥yn ʼè֝lòhi֗ym ká̇l-mĕziṁwòţáֽy⁠w׃"],[10,5,"יָ֘חִ֤ילוּ דרכ⁠ו ׀ בְּ⁠כָל־עֵ֗ת מָר֣וֹם מִ֭שְׁפָּטֶי⁠ךָ מִ⁠נֶּגְדּ֑⁠וֹ כָּל־צ֝וֹרְרָ֗י⁠ו יָפִ֥יחַ בָּ⁠הֶֽם׃","yá֘ẖi֤ylẇ drk⁠w ׀ bĕ̇⁠kál-ʻé֗ţ már֣wòm mi֭şĕ̌pá̇tey⁠ká mi⁠nėgĕḋ֑⁠wò ká̇l-ẕ֝wòrĕrá֗y⁠w yápi֥yẖa bá̇⁠heֽm׃"],[10,6,"אָמַ֣ר בְּ֭⁠לִבּ⁠וֹ בַּל־אֶמּ֑וֹט לְ⁠דֹ֥ר וָ֝⁠דֹ֗ר אֲשֶׁ֣ר לֹֽא־בְ⁠רָֽע׃","ʼáma֣r bĕ֭̇⁠liḃ⁠wò bȧl-ʼeṁ֑wòt lĕ⁠dò֥r wá֝⁠dò֗r ʼàşě֣r lòֽʼ-bĕ⁠ráֽʻ׃"],[10,7,"אָלָ֤ה פִּ֣י⁠הוּ מָ֭לֵא וּ⁠מִרְמ֣וֹת וָ⁠תֹ֑ךְ תַּ֥חַת לְ֝שׁוֹנ֗⁠וֹ עָמָ֥ל וָ⁠אָֽוֶן׃","ʼálá֤h pi֣̇y⁠hẇ má֭léʼ ẇ⁠mirĕm֣wòţ wá⁠ţò֑kĕ ţȧ֥ẖaţ lĕ֝ş̌wòn֗⁠wò ʻámá֥l wá⁠ʼáֽwen׃"],[10,8,"יֵשֵׁ֤ב ׀ בְּ⁠מַאְרַ֬ב חֲצֵרִ֗ים בַּֽ֭⁠מִּסְתָּרִים יַהֲרֹ֣ג נָקִ֑י עֵ֝ינָ֗י⁠ו לְֽ⁠חֵלְכָ֥ה יִצְפֹּֽנוּ׃","yéşé֤̌b ׀ bĕ̇⁠maʼĕra֬b ẖàẕéri֗ym bȧֽ֭⁠mi̇sĕţá̇riym yahàrò֣g náqi֑y ʻé֝yná֗y⁠w lĕֽ⁠ẖélĕká֥h yiẕĕpòֽ̇nẇ׃"],[10,9,"יֶאֱרֹ֬ב בַּ⁠מִּסְתָּ֨ר ׀ כְּ⁠אַרְיֵ֬ה בְ⁠סֻכֹּ֗⁠ה יֶ֭אֱרֹב לַ⁠חֲט֣וֹף עָנִ֑י יַחְטֹ֥ף עָ֝נִ֗י בְּ⁠מָשְׁכ֥⁠וֹ בְ⁠רִשְׁתּֽ⁠וֹ׃","yeʼèrò֬b bȧ⁠mi̇sĕţá̇֨r ׀ kĕ̇⁠ʼarĕyé֬h bĕ⁠sukò̇֗⁠h ye֭ʼèròb la⁠ẖàt֣wòp ʻáni֑y yaẖĕtò֥p ʻá֝ni֗y bĕ̇⁠máşĕ̌k֥⁠wò bĕ⁠rişĕ̌ţֽ̇⁠wò׃"],[10,10,"ו⁠דכה יָשֹׁ֑חַ וְ⁠נָפַ֥ל בַּ֝⁠עֲצוּמָ֗י⁠ו חלכאים׃","w⁠dkh yáşò֑̌ẖa wĕ⁠nápa֥l bȧ֝⁠ʻàẕẇmá֗y⁠w ẖlkʼym׃"],[10,11,"אָמַ֣ר בְּ֭⁠לִבּ⁠וֹ שָׁ֣כַֽח אֵ֑ל הִסְתִּ֥יר פָּ֝נָ֗י⁠ו בַּל־רָאָ֥ה לָ⁠נֶֽצַח׃","ʼáma֣r bĕ֭̇⁠liḃ⁠wò şá֣̌kaֽẖ ʼé֑l hisĕţi֥̇yr pá̇֝ná֗y⁠w bȧl-ráʼá֥h lá⁠neֽẕaẖ׃"],[10,12,"קוּמָ֤⁠ה יְהוָ֗ה אֵ֭ל נְשָׂ֣א יָדֶ֑⁠ךָ אַל־תִּשְׁכַּ֥ח עניים׃","qẇmá֤⁠h yĕhwá֗h ʼé֭l nĕşá֣̂ʼ yáde֑⁠ká ʼal-ţi̇şĕ̌kȧ֥ẖ ʻnyym׃"],[10,13,"עַל־מֶ֤ה ׀ נִאֵ֖ץ רָשָׁ֥ע ׀ אֱלֹהִ֑ים אָמַ֥ר בְּ֝⁠לִבּ֗⁠וֹ לֹ֣א תִּדְרֹֽשׁ׃","ʻal-me֤h ׀ niʼé֖ẕ ráşá֥̌ʻ ׀ ʼèlòhi֑ym ʼáma֥r bĕ̇֝⁠liḃ֗⁠wò lò֣ʼ ţi̇dĕròֽş̌׃"],[10,14,"רָאִ֡תָה כִּֽי־אַתָּ֤ה ׀ עָ֘מָ֤ל וָ⁠כַ֨עַס ׀ תַּבִּיט֮ לָ⁠תֵ֪ת בְּ⁠יָ֫דֶ֥⁠ךָ עָ֭לֶי⁠ךָ יַעֲזֹ֣ב חֵלֶ֑כָה יָ֝ת֗וֹם אַתָּ֤ה ׀ הָיִ֬יתָ עוֹזֵֽר׃","ráʼi֡ţáh kiֽ̇y-ʼaţá֤̇h ׀ ʻá֘má֤l wá⁠ka֨ʻas ׀ ţȧbi̇yt֮ lá⁠ţé֪ţ bĕ̇⁠yá֫de֥⁠ká ʻá֭ley⁠ká yaʻàzò֣b ẖéle֑káh yá֝ţ֗wòm ʼaţá֤̇h ׀ háyi֬yţá ʻwòzéֽr׃"],[10,15,"שְׁ֭בֹר זְר֣וֹעַ רָשָׁ֑ע וָ֝⁠רָ֗ע תִּֽדְרוֹשׁ־רִשְׁע֥⁠וֹ בַל־תִּמְצָֽא׃","şĕ֭̌bòr zĕr֣wòʻa ráşá֑̌ʻ wá֝⁠rá֗ʻ ţiֽ̇dĕrwòş̌-rişĕ̌ʻ֥⁠wò bal-ţi̇mĕẕáֽʼ׃"],[10,16,"יְהוָ֣ה מֶ֭לֶךְ עוֹלָ֣ם וָ⁠עֶ֑ד אָבְד֥וּ ג֝וֹיִ֗ם מֵֽ⁠אַרְצֽ⁠וֹ׃","yĕhwá֣h me֭lekĕ ʻwòlá֣m wá⁠ʻe֑d ʼábĕd֥ẇ g֝wòyi֗m méֽ⁠ʼarĕẕֽ⁠wò׃"],[10,17,"תַּאֲוַ֬ת עֲנָוִ֣ים שָׁמַ֣עְתָּ יְהוָ֑ה תָּכִ֥ין לִ֝בָּ֗⁠ם תַּקְשִׁ֥יב אָזְנֶֽ⁠ךָ׃","ţȧʼàwa֬ţ ʻànáwi֣ym şá̌ma֣ʻĕţá̇ yĕhwá֑h ţá̇ki֥yn li֝bá̇֗⁠m ţȧqĕşǐ֥yb ʼázĕneֽ⁠ká׃"],[10,18,"לִ⁠שְׁפֹּ֥ט יָת֗וֹם וָ֫⁠דָ֥ךְ בַּל־יוֹסִ֥יף ע֑וֹד לַ⁠עֲרֹ֥ץ אֱ֝נ֗וֹשׁ מִן־הָ⁠אָֽרֶץ׃","li⁠şĕ̌pò֥̇t yáţ֗wòm wá֫⁠dá֥kĕ bȧl-ywòsi֥yp ʻ֑wòd la⁠ʻàrò֥ẕ ʼè֝n֗wòş̌ min-há⁠ʼáֽreẕ׃"],[11,1,"לַ⁠מְנַצֵּ֗חַ לְ⁠דָ֫וִ֥ד בַּֽ⁠יהוָ֨ה ׀ חָסִ֗יתִי אֵ֭יךְ תֹּאמְר֣וּ לְ⁠נַפְשִׁ֑⁠י נודו הַרְ⁠כֶ֥ם צִפּֽוֹר׃","la⁠mĕnaẕé̇֗ẖa lĕ⁠dá֫wi֥d bȧֽ⁠yhwá֨h ׀ ẖási֗yţiy ʼé֭ykĕ ţò̇ʼmĕr֣ẇ lĕ⁠napĕşǐ֑⁠y nwdw harĕ⁠ke֥m ẕiṗֽwòr׃"],[11,2,"כִּ֤י הִנֵּ֪ה הָ⁠רְשָׁעִ֡ים יִדְרְכ֬וּ⁠ן קֶ֗שֶׁת כּוֹנְנ֣וּ חִצָּ֣⁠ם עַל־יֶ֑תֶר לִ⁠יר֥וֹת בְּמוֹ־אֹ֝֗פֶל לְ⁠יִשְׁרֵי־לֵֽב׃","ki֤̇y hiné֪̇h há⁠rĕşá̌ʻi֡ym yidĕrĕk֬ẇ⁠n qe֗şěţ k̇wònĕn֣ẇ ẖiẕá֣̇⁠m ʻal-ye֑ţer li⁠yr֥wòţ bĕ̇mwò-ʼò֝֗pel lĕ⁠yişĕ̌réy-léֽb׃"],[11,3,"כִּ֣י הַ֭⁠שָּׁתוֹת יֵֽהָרֵס֑וּ⁠ן צַ֝דִּ֗יק מַה־פָּעָֽל׃","ki֣̇y ha֭⁠şá̇̌ţwòţ yéֽhárés֑ẇ⁠n ẕa֝di̇֗yq mah-pá̇ʻáֽl׃"],[11,4,"יְהוָ֤ה ׀ בְּֽ⁠הֵ֘יכַ֤ל קָדְשׁ֗⁠וֹ יְהוָה֮ בַּ⁠שָּׁמַ֪יִם כִּ֫סְא֥⁠וֹ עֵינָ֥י⁠ו יֶחֱז֑וּ עַפְעַפָּ֥י⁠ו יִ֝בְחֲנ֗וּ בְּנֵ֣י אָדָֽם׃","yĕhwá֤h ׀ bĕֽ̇⁠hé֘yka֤l qádĕş̌֗⁠wò yĕhwáh֮ bȧ⁠şá̇̌ma֪yim ki̇֫sĕʼ֥⁠wò ʻéyná֥y⁠w yeẖèz֑ẇ ʻapĕʻapá֥̇y⁠w yi֝bĕẖàn֗ẇ bĕ̇né֣y ʼádáֽm׃"],[11,5,"יְהוָה֮ צַדִּ֪יק יִ֫בְחָ֥ן וְ֭⁠רָשָׁע וְ⁠אֹהֵ֣ב חָמָ֑ס שָֽׂנְאָ֥ה נַפְשֽׁ⁠וֹ׃","yĕhwáh֮ ẕadi֪̇yq yi֫bĕẖá֥n wĕ֭⁠ráşá̌ʻ wĕ⁠ʼòhé֣b ẖámá֑s şáֽ̂nĕʼá֥h napĕşֽ̌⁠wò׃"],[11,6,"יַמְטֵ֥ר עַל־רְשָׁעִ֗ים פַּ֫חִ֥ים אֵ֣שׁ וְ֭⁠גָפְרִית וְ⁠ר֥וּחַ זִלְעָפ֗וֹת מְנָ֣ת כּוֹסָֽ⁠ם׃","yamĕté֥r ʻal-rĕşá̌ʻi֗ym pȧ֫ẖi֥ym ʼé֣ş̌ wĕ֭⁠gápĕriyţ wĕ⁠r֥ẇẖa zilĕʻáp֗wòţ mĕná֣ţ k̇wòsáֽ⁠m׃"],[11,7,"כִּֽי־צַדִּ֣יק יְ֭הוָה צְדָק֣וֹת אָהֵ֑ב יָ֝שָׁ֗ר יֶחֱז֥וּ פָנֵֽי⁠מוֹ׃","kiֽ̇y-ẕadi֣̇yq yĕ֭hwáh ẕĕdáq֣wòţ ʼáhé֑b yá֝şá̌֗r yeẖèz֥ẇ pánéֽy⁠mwò׃"],[12,1,"הוֹשִׁ֣יעָ⁠ה יְ֭הוָה כִּי־גָמַ֣ר חָסִ֑יד כִּי־פַ֥סּוּ אֱ֝מוּנִ֗ים מִ⁠בְּנֵ֥י אָדָֽם׃","hwòşǐ֣yʻá⁠h yĕ֭hwáh ki̇y-gáma֣r ẖási֑yd ki̇y-pa֥ṡẇ ʼè֝mẇni֗ym mi⁠bĕ̇né֥y ʼádáֽm׃"],[12,2,"שָׁ֤וְא ׀ יְֽדַבְּרוּ֮ אִ֤ישׁ אֶת־רֵ֫עֵ֥⁠הוּ שְׂפַ֥ת חֲלָק֑וֹת בְּ⁠לֵ֖ב וָ⁠לֵ֣ב יְדַבֵּֽרוּ׃","şá֤̌wĕʼ ׀ yĕֽdabĕ̇rẇ֮ ʼi֤yş̌ ʼeţ-ré֫ʻé֥⁠hẇ şĕ̂pa֥ţ ẖàláq֑wòţ bĕ̇⁠lé֖b wá⁠lé֣b yĕdabéֽ̇rẇ׃"],[12,3,"יַכְרֵ֣ת יְ֭הוָה כָּל־שִׂפְתֵ֣י חֲלָק֑וֹת לָ֝שׁ֗וֹן מְדַבֶּ֥רֶת גְּדֹלֽוֹת׃","yakĕré֣ţ yĕ֭hwáh ká̇l-şîpĕţé֣y ẖàláq֑wòţ lá֝ş̌֗wòn mĕdabė֥reţ gĕ̇dòlֽwòţ׃"],[12,4,"אֲשֶׁ֤ר אָֽמְר֨וּ ׀ לִ⁠לְשֹׁנֵ֣⁠נוּ נַ֭גְבִּיר שְׂפָתֵ֣י⁠נוּ אִתָּ֑⁠נוּ מִ֖י אָד֣וֹן לָֽ⁠נוּ׃","ʼàşě֤r ʼáֽmĕr֨ẇ ׀ li⁠lĕşò̌né֣⁠nẇ na֭gĕbi̇yr şĕ̂páţé֣y⁠nẇ ʼiţá֑̇⁠nẇ mi֖y ʼád֣wòn láֽ⁠nẇ׃"],[12,5,"מִ⁠שֹּׁ֥ד עֲנִיִּים֮ מֵ⁠אַנְקַ֪ת אֶבְי֫וֹנִ֥ים עַתָּ֣ה אָ֭קוּם יֹאמַ֣ר יְהוָ֑ה אָשִׁ֥ית בְּ֝⁠יֵ֗שַׁע יָפִ֥יחַֽ לֽ⁠וֹ׃","mi⁠şò֥̇̌d ʻàniyi̇ym֮ mé⁠ʼanĕqa֪ţ ʼebĕy֫wòni֥ym ʻaţá֣̇h ʼá֭qẇm yòʼma֣r yĕhwá֑h ʼáşǐ֥yţ bĕ̇֝⁠yé֗şǎʻ yápi֥yẖaֽ lֽ⁠wò׃"],[12,6,"אִֽמֲר֣וֹת יְהוָה֮ אֲמָר֪וֹת טְהֹ֫ר֥וֹת כֶּ֣סֶף צָ֭רוּף בַּ⁠עֲלִ֣יל לָ⁠אָ֑רֶץ מְ֝זֻקָּ֗ק שִׁבְעָתָֽיִם׃","ʼiֽmàr֣wòţ yĕhwáh֮ ʼàmár֪wòţ tĕhò֫r֥wòţ kė֣sep ẕá֭rẇp bȧ⁠ʻàli֣yl lá⁠ʼá֑reẕ mĕ֝zuqá̇֗q şǐbĕʻáţáֽyim׃"],[12,7,"אַתָּֽה־יְהוָ֥ה תִּשְׁמְרֵ֑⁠ם תִּצְּרֶ֓⁠נּוּ ׀ מִן־הַ⁠דּ֖וֹר ז֣וּ לְ⁠עוֹלָֽם׃","ʼaţáֽ̇h-yĕhwá֥h ţi̇şĕ̌mĕré֑⁠m ţi̇ẕĕ̇re֓⁠ṅẇ ׀ min-ha⁠ḋ֖wòr z֣ẇ lĕ⁠ʻwòláֽm׃"],[12,8,"סָבִ֗יב רְשָׁעִ֥ים יִתְהַלָּכ֑וּ⁠ן כְּ⁠רֻ֥ם זֻ֝לּ֗וּת לִ⁠בְנֵ֥י אָדָֽם׃","sábi֗yb rĕşá̌ʻi֥ym yiţĕhalá̇k֑ẇ⁠n kĕ̇⁠ru֥m zu֝l̇֗ẇţ li⁠bĕné֥y ʼádáֽm׃"],[13,1,"עַד־אָ֣נָה יְ֭הוָה תִּשְׁכָּחֵ֣⁠נִי נֶ֑צַח עַד־אָ֓נָה ׀ תַּסְתִּ֖יר אֶת־פָּנֶ֣י⁠ךָ מִמֶּֽ⁠נִּי׃","ʻad-ʼá֣náh yĕ֭hwáh ţi̇şĕ̌ká̇ẖé֣⁠niy ne֑ẕaẖ ʻad-ʼá֓náh ׀ ţȧsĕţi֖̇yr ʼeţ-pá̇ne֣y⁠ká mimėֽ⁠ni̇y׃"],[13,2,"עַד־אָ֨נָה אָשִׁ֪ית עֵצ֡וֹת בְּ⁠נַפְשִׁ֗⁠י יָג֣וֹן בִּ⁠לְבָבִ֣⁠י יוֹמָ֑ם עַד־אָ֓נָה ׀ יָר֖וּם אֹיְבִ֣⁠י עָלָֽ⁠י׃","ʻad-ʼá֨náh ʼáşǐ֪yţ ʻéẕ֡wòţ bĕ̇⁠napĕşǐ֗⁠y yág֣wòn bi̇⁠lĕbábi֣⁠y ywòmá֑m ʻad-ʼá֓náh ׀ yár֖ẇm ʼòyĕbi֣⁠y ʻáláֽ⁠y׃"],[13,3,"הַבִּ֣יטָֽ⁠ה עֲ֭נֵ⁠נִי יְהוָ֣ה אֱלֹהָ֑⁠י הָאִ֥ירָ⁠ה עֵ֝ינַ֗⁠י פֶּן־אִישַׁ֥ן הַ⁠מָּֽוֶת׃","habi֣̇ytáֽ⁠h ʻà֭né⁠niy yĕhwá֣h ʼèlòhá֑⁠y háʼi֥yrá⁠h ʻé֝yna֗⁠y pėn-ʼiyşǎ֥n ha⁠máֽ̇weţ׃"],[13,4,"פֶּן־יֹאמַ֣ר אֹיְבִ֣⁠י יְכָלְתִּ֑י⁠ו צָרַ֥⁠י יָ֝גִ֗ילוּ כִּ֣י אֶמּֽוֹט׃","pėn-yòʼma֣r ʼòyĕbi֣⁠y yĕkálĕţi֑̇y⁠w ẕára֥⁠y yá֝gi֗ylẇ ki֣̇y ʼeṁֽwòt׃"],[13,5,"וַ⁠אֲנִ֤י ׀ בְּ⁠חַסְדְּ⁠ךָ֣ בָטַחְתִּי֮ יָ֤גֵ֥ל לִבִּ֗⁠י בִּֽ⁠ישׁוּעָ֫תֶ֥⁠ךָ","wa⁠ʼàni֤y ׀ bĕ̇⁠ẖasĕdĕ̇⁠ká֣ bátaẖĕţi̇y֮ yá֤gé֥l libi̇֗⁠y biֽ̇⁠yş̌ẇʻá֫ţe֥⁠ká"],[13,6,"אָשִׁ֥ירָה לַ⁠יהוָ֑ה כִּ֖י גָמַ֣ל עָלָֽ⁠י׃","ʼáşǐ֥yráh la⁠yhwá֑h ki֖̇y gáma֣l ʻáláֽ⁠y׃"],[14,1,"לַ⁠מְנַצֵּ֗חַ לְ⁠דָ֫וִ֥ד אָ֘מַ֤ר נָבָ֣ל בְּ֭⁠לִבּ⁠וֹ אֵ֣ין אֱלֹהִ֑ים הִֽשְׁחִ֗יתוּ הִֽתְעִ֥יבוּ עֲלִילָ֗ה אֵ֣ין עֹֽשֵׂה־טֽוֹב׃","la⁠mĕnaẕé̇֗ẖa lĕ⁠dá֫wi֥d ʼá֘ma֤r nábá֣l bĕ֭̇⁠liḃ⁠wò ʼé֣yn ʼèlòhi֑ym hiֽşĕ̌ẖi֗yţẇ hiֽţĕʻi֥ybẇ ʻàliylá֗h ʼé֣yn ʻòֽşé̂h-tֽwòb׃"],[14,2,"יְֽהוָ֗ה מִ⁠שָּׁמַיִם֮ הִשְׁקִ֪יף עַֽל־בְּנֵי־אָ֫דָ֥ם לִ֭⁠רְאוֹת הֲ⁠יֵ֣שׁ מַשְׂכִּ֑יל דֹּ֝רֵשׁ אֶת־אֱלֹהִֽים׃","yĕֽhwá֗h mi⁠şá̇̌mayim֮ hişĕ̌qi֪yp ʻaֽl-bĕ̇néy-ʼá֫dá֥m li֭⁠rĕʼwòţ hà⁠yé֣ş̌ maşĕ̂ki֑̇yl dò̇֝réş̌ ʼeţ-ʼèlòhiֽym׃"],[14,3,"הַ⁠כֹּ֥ל סָר֮ יַחְדָּ֪ו נֶ֫אֱלָ֥חוּ אֵ֤ין עֹֽשֵׂה־ט֑וֹב אֵ֝֗ין גַּם־אֶחָֽד׃","ha⁠kò֥̇l sár֮ yaẖĕdá֪̇w ne֫ʼèlá֥ẖẇ ʼé֤yn ʻòֽşé̂h-t֑wòb ʼé֝֗yn gȧm-ʼeẖáֽd׃"],[14,4,"הֲ⁠לֹ֥א יָדְעוּ֮ כָּל־פֹּ֪עֲלֵ֫י אָ֥וֶן אֹכְלֵ֣י עַ֭מִּ⁠י אָ֣כְלוּ לֶ֑חֶם יְ֝הוָ֗ה לֹ֣א קָרָֽאוּ׃","hà⁠lò֥ʼ yádĕʻẇ֮ ká̇l-pò֪̇ʻàlé֫y ʼá֥wen ʼòkĕlé֣y ʻa֭mi̇⁠y ʼá֣kĕlẇ le֑ẖem yĕ֝hwá֗h lò֣ʼ qáráֽʼẇ׃"],[14,5,"שָׁ֤ם ׀ פָּ֣חֲדוּ פָ֑חַד כִּֽי־אֱ֝לֹהִ֗ים בְּ⁠ד֣וֹר צַדִּֽיק׃","şá֤̌m ׀ pá֣̇ẖàdẇ pá֑ẖad kiֽ̇y-ʼè֝lòhi֗ym bĕ̇⁠d֣wòr ẕadiֽ̇yq׃"],[14,6,"עֲצַת־עָנִ֥י תָבִ֑ישׁוּ כִּ֖י יְהוָ֣ה מַחְסֵֽ⁠הוּ׃","ʻàẕaţ-ʻáni֥y ţábi֑yş̌ẇ ki֖̇y yĕhwá֣h maẖĕséֽ⁠hẇ׃"],[14,7,"מִ֥י יִתֵּ֣ן מִ⁠צִּיּוֹן֮ יְשׁוּעַ֪ת יִשְׂרָ֫אֵ֥ל בְּ⁠שׁ֣וּב יְ֭הוָה שְׁב֣וּת עַמּ֑⁠וֹ יָגֵ֥ל יַ֝עֲקֹ֗ב יִשְׂמַ֥ח יִשְׂרָֽאֵל׃","mi֥y yiţé֣̇n mi⁠ẕi̇ẏwòn֮ yĕş̌ẇʻa֪ţ yişĕ̂rá֫ʼé֥l bĕ̇⁠ş֣̌ẇb yĕ֭hwáh şĕ̌b֣ẇţ ʻaṁ֑⁠wò yágé֥l ya֝ʻàqò֗b yişĕ̂ma֥ẖ yişĕ̂ráֽʼél׃"],[15,1,"מִזְמ֗וֹר לְ⁠דָ֫וִ֥ד יְ֭הֹוָה מִי־יָג֣וּר בְּ⁠אָהֳלֶ֑⁠ךָ מִֽי־יִ֝שְׁכֹּ֗ן בְּ⁠הַ֣ר קָדְשֶֽׁ⁠ךָ׃","mizĕm֗wòr lĕ⁠dá֫wi֥d yĕ֭hòwáh miy-yág֣ẇr bĕ̇⁠ʼáhole֑⁠ká miֽy-yi֝şĕ̌kò̇֗n bĕ̇⁠ha֣r qádĕşěֽ⁠ká׃"],[15,2,"הוֹלֵ֣ךְ תָּ֭מִים וּ⁠פֹעֵ֥ל צֶ֑דֶק וְ⁠דֹבֵ֥ר אֱ֝מֶ֗ת בִּ⁠לְבָבֽ⁠וֹ׃","hwòlé֣kĕ ţá֭̇miym ẇ⁠pòʻé֥l ẕe֑deq wĕ⁠dòbé֥r ʼè֝me֗ţ bi̇⁠lĕbábֽ⁠wò׃"],[15,3,"לֹֽא־רָגַ֨ל ׀ עַל־לְשֹׁנ֗⁠וֹ לֹא־עָשָׂ֣ה לְ⁠רֵעֵ֣⁠הוּ רָעָ֑ה וְ֝⁠חֶרְפָּ֗ה לֹא־נָשָׂ֥א עַל־קְרֹֽב⁠וֹ׃","lòֽʼ-rága֨l ׀ ʻal-lĕşò̌n֗⁠wò lòʼ-ʻáşá֣̂h lĕ⁠réʻé֣⁠hẇ ráʻá֑h wĕ֝⁠ẖerĕpá̇֗h lòʼ-náşá֥̂ʼ ʻal-qĕròֽb⁠wò׃"],[15,4,"נִבְזֶ֤ה ׀ בְּֽ⁠עֵ֘ינָ֤י⁠ו נִמְאָ֗ס וְ⁠אֶת־יִרְאֵ֣י יְהוָ֣ה יְכַבֵּ֑ד נִשְׁבַּ֥ע לְ֝⁠הָרַ֗ע וְ⁠לֹ֣א יָמִֽר׃","nibĕze֤h ׀ bĕֽ̇⁠ʻé֘yná֤y⁠w nimĕʼá֗s wĕ⁠ʼeţ-yirĕʼé֣y yĕhwá֣h yĕkabé֑̇d nişĕ̌bȧ֥ʻ lĕ֝⁠hára֗ʻ wĕ⁠lò֣ʼ yámiֽr׃"],[15,5,"כַּסְפּ֤⁠וֹ ׀ לֹא־נָתַ֣ן בְּ⁠נֶשֶׁךְ֮ וְ⁠שֹׁ֥חַד עַל־נָקִ֗י לֹ֥א לָ֫קָ֥ח עֹֽשֵׂה־אֵ֑לֶּה לֹ֖א יִמּ֣וֹט לְ⁠עוֹלָֽם׃","kȧsĕṗ֤⁠wò ׀ lòʼ-náţa֣n bĕ̇⁠neşěkĕ֮ wĕ⁠şò֥̌ẖad ʻal-náqi֗y lò֥ʼ lá֫qá֥ẖ ʻòֽşé̂h-ʼé֑lėh lò֖ʼ yiṁ֣wòt lĕ⁠ʻwòláֽm׃"],[16,1,"מִכְתָּ֥ם לְ⁠דָוִ֑ד שָֽׁמְרֵ֥⁠נִי אֵ֝֗ל כִּֽי־חָסִ֥יתִי בָֽ⁠ךְ׃","mikĕţá֥̇m lĕ⁠dáwi֑d şáֽ̌mĕré֥⁠niy ʼé֝֗l kiֽ̇y-ẖási֥yţiy báֽ⁠kĕ׃"],[16,2,"אָמַ֣רְתְּ לַֽ֭⁠יהוָה אֲדֹנָ֣⁠י אָ֑תָּה ט֝וֹבָתִ֗⁠י בַּל־עָלֶֽי⁠ךָ׃","ʼáma֣rĕţĕ̇ laֽ֭⁠yhwáh ʼàdòná֣⁠y ʼá֑ţá̇h t֝wòbáţi֗⁠y bȧl-ʻáleֽy⁠ká׃"],[16,3,"לִ֭⁠קְדוֹשִׁים אֲשֶׁר־בָּ⁠אָ֣רֶץ הֵ֑מָּה וְ֝⁠אַדִּירֵ֗י כָּל־חֶפְצִ⁠י־בָֽ⁠ם׃","li֭⁠qĕdwòşǐym ʼàşěr-bá̇⁠ʼá֣reẕ hé֑má̇h wĕ֝⁠ʼadi̇yré֗y ká̇l-ẖepĕẕi⁠y-báֽ⁠m׃"],[16,4,"יִרְבּ֥וּ עַצְּבוֹתָ⁠ם֮ אַחֵ֪ר מָ֫הָ֥רוּ בַּל־אַסִּ֣יךְ נִסְכֵּי⁠הֶ֣ם מִ⁠דָּ֑ם וּֽ⁠בַל־אֶשָּׂ֥א אֶת־שְׁ֝מוֹתָ֗⁠ם עַל־שְׂפָתָֽ⁠י׃","yirĕḃ֥ẇ ʻaẕĕ̇bwòţá⁠m֮ ʼaẖé֪r má֫há֥rẇ bȧl-ʼasi֣̇ykĕ nisĕké̇y⁠he֣m mi⁠dá֑̇m ẇֽ⁠bal-ʼeşá֥̇̂ʼ ʼeţ-şĕ̌֝mwòţá֗⁠m ʻal-şĕ̂páţáֽ⁠y׃"],[16,5,"יְֽהוָ֗ה מְנָת־חֶלְקִ֥⁠י וְ⁠כוֹסִ֑⁠י אַ֝תָּ֗ה תּוֹמִ֥יךְ גּוֹרָלִֽ⁠י׃","yĕֽhwá֗h mĕnáţ-ẖelĕqi֥⁠y wĕ⁠kwòsi֑⁠y ʼa֝ţá̇֗h ţ̇wòmi֥ykĕ ġwòráliֽ⁠y׃"],[16,6,"חֲבָלִ֣ים נָֽפְלוּ־לִ֭⁠י בַּ⁠נְּעִמִ֑ים אַף־נַ֝חֲלָ֗ת שָֽׁפְרָ֥ה עָלָֽ⁠י׃","ẖàbáli֣ym náֽpĕlẇ-li֭⁠y bȧ⁠nĕ̇ʻimi֑ym ʼap-na֝ẖàlá֗ţ şáֽ̌pĕrá֥h ʻálֽá⁠y׃"],[16,7,"אֲבָרֵ֗ךְ אֶת־יְ֭הוָה אֲשֶׁ֣ר יְעָצָ֑⁠נִי אַף־לֵ֝יל֗וֹת יִסְּר֥וּ⁠נִי כִלְיוֹתָֽ⁠י׃","ʼàbáré֗kĕ ʼeţ-yĕ֭hwáh ʼàşě֣r yĕʻáẕá֑⁠niy ʼap-lé֝yl֗wòţ yisĕ̇r֥ẇ⁠niy kilĕywòţáֽ⁠y׃"],[16,8,"שִׁוִּ֬יתִי יְהוָ֣ה לְ⁠נֶגְדִּ֣⁠י תָמִ֑יד כִּ֥י מִֽ֝⁠ימִינִ֗⁠י בַּל־אֶמּֽוֹט׃","şǐwi̇֬yţiy yĕhwá֣h lĕ⁠negĕdi֣̇⁠y ţámi֑yd ki֥̇y miֽ֝⁠ymiyni֗⁠y bȧl-ʼeṁֽwòt׃"],[16,9,"לָ⁠כֵ֤ן ׀ שָׂמַ֣ח לִ֭בִּ⁠י וַ⁠יָּ֣גֶל כְּבוֹדִ֑⁠י אַף־בְּ֝שָׂרִ֗⁠י יִשְׁכֹּ֥ן לָ⁠בֶֽטַח׃","lá⁠ké֤n ׀ şá̂ma֣ẖ li֭bi̇⁠y wa⁠yá֣̇gel kĕ̇bwòdi֑⁠y ʼap-bĕ̇֝şá̂ri֗⁠y yişĕ̌kò֥̇n lá⁠beֽtaẖ׃"],[16,10,"כִּ֤י ׀ לֹא־תַעֲזֹ֣ב נַפְשִׁ֣⁠י לִ⁠שְׁא֑וֹל לֹֽא־תִתֵּ֥ן חֲ֝סִידְ⁠ךָ֗ לִ⁠רְא֥וֹת שָֽׁחַת׃","ki֤̇y ׀ lòʼ-ţaʻàzò֣b napĕşǐ֣⁠y li⁠şĕ̌ʼ֑wòl lòֽʼ-ţiţé֥̇n ẖà֝siydĕ⁠ká֗ li⁠rĕʼ֥wòţ şáֽ̌ẖaţ׃"],[16,11,"תּֽוֹדִיעֵ⁠נִי֮ אֹ֤רַח חַ֫יִּ֥ים שֹׂ֣בַע שְׂ֭מָחוֹת אֶת־פָּנֶ֑י⁠ךָ נְעִמ֖וֹת בִּ⁠ימִינְ⁠ךָ֣ נֶֽצַח׃","ţֽ̇wòdiyʻé⁠niy֮ ʼò֤raẖ ẖa֫yi֥̇ym şò֣̂baʻ şĕ֭̂máẖwòţ ʼeţ-pá̇ne֑y⁠ká nĕʻim֖wòţ bi̇⁠ymiynĕ⁠ká֣ neֽẕaẖ׃"],[17,1,"תְּפִלָּ֗ה לְ⁠דָ֫וִ֥ד שִׁמְעָ֤⁠ה יְהוָ֨ה ׀ צֶ֗דֶק הַקְשִׁ֥יבָ⁠ה רִנָּתִ֗⁠י הַאֲזִ֥ינָ⁠ה תְפִלָּתִ֑⁠י בְּ֝⁠לֹ֗א שִׂפְתֵ֥י מִרְמָֽה׃","ţĕ̇pilá̇֗h lĕ⁠dá֫wi֥d şǐmĕʻá֤⁠h yĕhwá֨h ׀ ẕe֗deq haqĕşǐ֥ybá⁠h riná̇ţi֗⁠y haʼàzi֥yná⁠h ţĕpilá̇ţi֑⁠y bĕ̇֝⁠lò֗ʼ şîpĕţé֥y mirĕmáֽh׃"],[17,2,"מִ֭⁠לְּ⁠פָנֶי⁠ךָ מִשְׁפָּטִ֣⁠י יֵצֵ֑א עֵ֝ינֶ֗י⁠ךָ תֶּחֱזֶ֥ינָה מֵישָׁרִֽים׃","mi֭⁠lĕ̇⁠páney⁠ká mişĕ̌pá̇ti֣⁠y yéẕé֑ʼ ʻé֝yne֗y⁠ká ţėẖèze֥ynáh méyşá̌riֽym׃"],[17,3,"בָּ֘חַ֤נְתָּ לִבִּ֨⁠י ׀ פָּ֘קַ֤דְתָּ לַּ֗יְלָה צְרַפְתַּ֥⁠נִי בַל־תִּמְצָ֑א זַ֝מֹּתִ֗י בַּל־יַעֲבָר־פִּֽ⁠י׃","bá̇֘ẖa֤nĕţá̇ libi̇֨⁠y ׀ pá̇֘qa֤dĕţá̇ lȧ֗yĕláh ẕĕrapĕţȧ֥⁠niy bal-ţi̇mĕẕá֑ʼ za֝mò̇ţi֗y bȧl-yaʻàbár-piֽ̇⁠y׃"],[17,4,"לִ⁠פְעֻלּ֣וֹת אָ֭דָם בִּ⁠דְבַ֣ר שְׂפָתֶ֑י⁠ךָ אֲנִ֥י שָׁ֝מַ֗רְתִּי אָרְח֥וֹת פָּרִֽיץ׃","li⁠pĕʻul֣̇wòţ ʼá֭dám bi̇⁠dĕba֣r şĕ̂páţe֑y⁠ká ʼàni֥y şá̌֝ma֗rĕţi̇y ʼárĕẖ֥wòţ pá̇riֽyẕ׃"],[17,5,"תָּמֹ֣ךְ אֲ֭שֻׁרַ⁠י בְּ⁠מַעְגְּלוֹתֶ֑י⁠ךָ בַּל־נָמ֥וֹטּוּ פְעָמָֽ⁠י׃","ţá̇mò֣kĕ ʼà֭şǔra⁠y bĕ̇⁠maʻĕgĕ̇lwòţe֑y⁠ká bȧl-nám֥wòṫẇ pĕʻámáֽ⁠y׃"],[17,6,"אֲנִֽי־קְרָאתִ֣י⁠ךָ כִֽי־תַעֲנֵ֣⁠נִי אֵ֑ל הַֽט־אָזְנְ⁠ךָ֥ לִ֝֗⁠י שְׁמַ֣ע אִמְרָתִֽ⁠י׃","ʼàniֽy-qĕráʼţi֣y⁠ká kiֽy-ţaʻàné֣⁠niy ʼé֑l haֽt-ʼázĕnĕ⁠ká֥ li֝֗⁠y şĕ̌ma֣ʻ ʼimĕráţiֽ⁠y׃"],[17,7,"הַפְלֵ֣ה חֲ֭סָדֶי⁠ךָ מוֹשִׁ֣יעַ חוֹסִ֑ים מִ֝⁠מִּתְקוֹמְמִ֗ים בִּֽ⁠ימִינֶֽ⁠ךָ׃","hapĕlé֣h ẖà֭sádey⁠ká mwòşǐ֣yʻa ẖwòsi֑ym mi֝⁠mi̇ţĕqwòmĕmi֗ym biֽ̇⁠ymiyneֽ⁠ká׃"],[17,8,"שָׁ֭מְרֵ⁠נִי כְּ⁠אִישׁ֣וֹן בַּת־עָ֑יִן בְּ⁠צֵ֥ל כְּ֝נָפֶ֗י⁠ךָ תַּסְתִּירֵֽ⁠נִי׃","şá֭̌mĕré⁠niy kĕ̇⁠ʼiyş֣̌wòn bȧţ-ʻá֑yin bĕ̇⁠ẕé֥l kĕ̇֝nápe֗y⁠ká ţȧsĕţi̇yréֽ⁠niy׃"],[17,9,"מִ⁠פְּנֵ֣י רְ֭שָׁעִים ז֣וּ שַׁדּ֑וּ⁠נִי אֹיְבַ֥⁠י בְּ֝⁠נֶ֗פֶשׁ יַקִּ֥יפוּ עָלָֽ⁠י׃","mi⁠pĕ̇né֣y rĕ֭şá̌ʻiym z֣ẇ şǎḋ֑ẇ⁠niy ʼòyĕba֥⁠y bĕ̇֝⁠ne֗peş̌ yaqi֥̇ypẇ ʻáláֽ⁠y׃"],[17,10,"חֶלְבָּ֥⁠מוֹ סָּגְר֑וּ פִּ֝֗י⁠מוֹ דִּבְּר֥וּ בְ⁠גֵאֽוּת׃","ẖelĕbá֥̇⁠mwò sá̇gĕr֑ẇ pi̇֝֗y⁠mwò di̇bĕ̇r֥ẇ bĕ⁠géʼֽẇţ׃"],[17,11,"אַ֭שֻּׁרֵי⁠נוּ עַתָּ֣ה סבבו⁠ני עֵינֵי⁠הֶ֥ם יָ֝שִׁ֗יתוּ לִ⁠נְט֥וֹת בָּ⁠אָֽרֶץ׃","ʼa֭şu̇̌réy⁠nẇ ʻaţá֣̇h sbbw⁠ny ʻéynéy⁠he֥m yá֝şǐ֗yţẇ li⁠nĕt֥wòţ bá̇⁠ʼáֽreẕ׃"],[17,12,"דִּמְיֹנ֗⁠וֹ כְּ֭⁠אַרְיֵה יִכְס֣וֹף לִ⁠טְר֑וֹף וְ֝⁠כִ⁠כְפִ֗יר יֹשֵׁ֥ב בְּ⁠מִסְתָּרִֽים׃","di̇mĕyòn֗⁠wò kĕ֭̇⁠ʼarĕyéh yikĕs֣wòp li⁠tĕr֑wòp wĕ֝⁠ki⁠kĕpi֗yr yòşé֥̌b bĕ̇⁠misĕţá̇rֽiym׃"],[17,13,"קוּמָ֤⁠ה יְהוָ֗ה קַדְּמָ֣⁠ה פָ֭נָי⁠ו הַכְרִיעֵ֑⁠הוּ פַּלְּטָ֥⁠ה נַ֝פְשִׁ֗⁠י מֵ⁠רָשָׁ֥ע חַרְבֶּֽ⁠ךָ׃","qẇmá֤⁠h yĕhwá֗h qadĕ̇má֣⁠h pá֭náy⁠w hakĕriyʻé֑⁠hẇ pȧlĕ̇tá֥⁠h na֝pĕşǐ֗⁠y mé⁠ráşá֥̌ʻ ẖarĕbėֽ⁠ká׃"],[17,14,"מִֽ⁠מְתִ֥ים יָדְ⁠ךָ֨ ׀ יְהוָ֡ה מִֽ⁠מְתִ֬ים מֵ⁠חֶ֗לֶד חֶלְקָ֥⁠ם בַּֽ⁠חַיִּים֮ ו⁠צפינ⁠ך תְּמַלֵּ֪א בִ֫טְנָ֥⁠ם יִשְׂבְּע֥וּ בָנִ֑ים וְ⁠הִנִּ֥יחוּ יִ֝תְרָ֗⁠ם לְ⁠עוֹלְלֵי⁠הֶֽם׃","miֽ⁠mĕţi֥ym yádĕ⁠ká֨ ׀ yĕhwá֡h miֽ⁠mĕţi֬ym mé⁠ẖe֗led ẖelĕqá֥⁠m bȧֽ⁠ẖayi̇ym֮ w⁠ẕpyn⁠k ţĕ̇malé֪̇ʼ bi֫tĕná֥⁠m yişĕ̂bĕ̇ʻ֥ẇ báni֑ym wĕ⁠hini֥̇yẖẇ yi֝ţĕrá֗⁠m lĕ⁠ʻwòlĕléy⁠hֽem׃"],[17,15,"אֲנִ֗י בְּ֭⁠צֶדֶק אֶחֱזֶ֣ה פָנֶ֑י⁠ךָ אֶשְׂבְּעָ֥ה בְ֝⁠הָקִ֗יץ תְּמוּנָתֶֽ⁠ךָ׃","ʼàni֗y bĕ֭̇⁠ẕedeq ʼeẖèze֣h páne֑y⁠ká ʼeşĕ̂bĕ̇ʻá֥h bĕ֝⁠háqi֗yẕ ţĕ̇mẇnáţeֽ⁠ká׃"],[18,1,"וַ⁠יֹּאמַ֡ר אֶרְחָמְ⁠ךָ֖ יְהוָ֣ה חִזְקִֽ⁠י׃","wa⁠yò̇ʼma֡r ʼerĕẖámĕ⁠ká֖ yĕhwá֣h ẖizĕqiֽ⁠y׃"],[18,2,"יְהוָ֤ה ׀ סַֽלְעִ֥⁠י וּ⁠מְצוּדָתִ֗⁠י וּ⁠מְפַ֫לְטִ֥⁠י אֵלִ֣⁠י צ֭וּרִ⁠י אֶֽחֱסֶה־בּ֑⁠וֹ מָֽגִנִּ֥⁠י וְ⁠קֶֽרֶן־יִ֝שְׁעִ֗⁠י מִשְׂגַּבִּֽ⁠י׃","yĕhwá֤h ׀ saֽlĕʻi֥⁠y ẇ⁠mĕẕẇdáţi֗⁠y ẇ⁠mĕpa֫lĕti֥⁠y ʼéli֣⁠y ẕ֭ẇri⁠y ʼeֽẖèseh-ḃ֑⁠wò máֽgini֥̇⁠y wĕ⁠qeֽren-yi֝şĕ̌ʻi֗⁠y mişĕ̂gȧbiֽ̇⁠y׃"],[18,3,"מְ֭הֻלָּל אֶקְרָ֣א יְהוָ֑ה וּ⁠מִן־אֹ֝יְבַ֗⁠י אִוָּשֵֽׁעַ׃","mĕ֭hulá̇l ʼeqĕrá֣ʼ yĕhwá֑h ẇ⁠min-ʼò֝yĕba֗⁠y ʼiwá̇şéֽ̌ʻa׃"],[18,4,"אֲפָפ֥וּ⁠נִי חֶבְלֵי־מָ֑וֶת וְֽ⁠נַחֲלֵ֖י בְלִיַּ֣עַל יְבַֽעֲתֽוּ⁠נִי׃","ʼàpáp֥ẇ⁠niy ẖebĕléy-má֑weţ wĕֽ⁠naẖàlé֖y bĕliyȧ֣ʻal yĕbaֽʻàţֽẇ⁠niy׃"],[18,5,"חֶבְלֵ֣י שְׁא֣וֹל סְבָב֑וּ⁠נִי קִ֝דְּמ֗וּ⁠נִי מ֣וֹקְשֵׁי מָֽוֶת׃","ẖebĕlé֣y şĕ̌ʼ֣wòl sĕbáb֑ẇ⁠niy qi֝dĕ̇m֗ẇ⁠niy m֣wòqĕşé̌y máֽweţ׃"],[18,6,"בַּ⁠צַּר־לִ֤⁠י ׀ אֶֽקְרָ֣א יְהוָה֮ וְ⁠אֶל־אֱלֹהַ֪⁠י אֲשַׁ֫וֵּ֥עַ יִשְׁמַ֣ע מֵ⁠הֵיכָל֣⁠וֹ קוֹלִ֑⁠י וְ֝⁠שַׁוְעָתִ֗⁠י לְ⁠פָנָ֤י⁠ו ׀ תָּב֬וֹא בְ⁠אָזְנָֽי⁠ו׃","bȧ⁠ẕȧr-li֤⁠y ׀ ʼeֽqĕrá֣ʼ yĕhwáh֮ wĕ⁠ʼel-ʼèlòha֪⁠y ʼàşǎ֫wé֥̇ʻa yişĕ̌ma֣ʻ mé⁠héykál֣⁠wò qwòli֑⁠y wĕ֝⁠şǎwĕʻáţi֗⁠y lĕ⁠páná֤y⁠w ׀ ţá̇b֬wòʼ bĕ⁠ʼázĕnáֽy⁠w׃"],[18,7,"וַ⁠תִּגְעַ֬שׁ וַ⁠תִּרְעַ֨שׁ ׀ הָ⁠אָ֗רֶץ וּ⁠מוֹסְדֵ֣י הָרִ֣ים יִרְגָּ֑זוּ וַ֝⁠יִּתְגָּֽעֲשׁ֗וּ כִּי־חָ֥רָה לֽ⁠וֹ׃","wa⁠ţi̇gĕʻa֬ş̌ wa⁠ţi̇rĕʻa֨ş̌ ׀ há⁠ʼá֗reẕ ẇ⁠mwòsĕdé֣y hári֣ym yirĕgá֑̇zẇ wa֝⁠yi̇ţĕgáֽ̇ʻàş̌֗ẇ ki̇y-ẖá֥ráh lֽ⁠wò׃"],[18,8,"עָ֘לָ֤ה עָשָׁ֨ן ׀ בְּ⁠אַפּ֗⁠וֹ וְ⁠אֵשׁ־מִ⁠פִּ֥י⁠ו תֹּאכֵ֑ל גֶּ֝חָלִ֗ים בָּעֲר֥וּ מִמֶּֽ⁠נּוּ׃","ʻá֘lá֤h ʻáşá̌֨n ׀ bĕ̇⁠ʼaṗ֗⁠wò wĕ⁠ʼéş̌-mi⁠pi֥̇y⁠w ţò̇ʼké֑l gė֝ẖáli֗ym bá̇ʻàr֥ẇ mimėֽ⁠ṅẇ׃"],[18,9,"וַ⁠יֵּ֣ט שָׁ֭מַיִם וַ⁠יֵּרַ֑ד וַ֝⁠עֲרָפֶ֗ל תַּ֣חַת רַגְלָֽי⁠ו׃","wa⁠yé֣̇t şá֭̌mayim wa⁠yé̇ra֑d wa֝⁠ʻàrápe֗l ţȧ֣ẖaţ ragĕlֽáy⁠w׃"],[18,10,"וַ⁠יִּרְכַּ֣ב עַל־כְּ֭רוּב וַ⁠יָּעֹ֑ף וַ֝⁠יֵּ֗דֶא עַל־כַּנְפֵי־רֽוּחַ׃","wa⁠yi̇rĕkȧ֣b ʻal-kĕ֭̇rẇb wa⁠yá̇ʻò֑p wa֝⁠yé̇֗deʼ ʻal-kȧnĕpéy-rֽẇẖa׃"],[18,11,"יָ֤שֶׁת חֹ֨שֶׁךְ ׀ סִתְר֗⁠וֹ סְבִֽיבוֹתָ֥י⁠ו סֻכָּת֑⁠וֹ חֶשְׁכַת־מַ֝֗יִם עָבֵ֥י שְׁחָקִֽים׃","yá֤şěţ ẖò֨şěkĕ ׀ siţĕr֗⁠wò sĕbiֽybwòţá֥y⁠w suká̇ţ֑⁠wò ẖeşĕ̌kaţ-ma֝֗yim ʻábé֥y şĕ̌ẖáqiֽym׃"],[18,12,"מִ⁠נֹּ֗גַהּ נֶ֫גְדּ֥⁠וֹ עָבָ֥י⁠ו עָבְר֑וּ בָּ֝רָ֗ד וְ⁠גַֽחֲלֵי־אֵֽשׁ׃","mi⁠nò̇֗gaḣ ne֫gĕḋ֥⁠wò ʻábá֥y⁠w ʻábĕr֑ẇ bá̇֝rá֗d wĕ⁠gaֽẖàléy-ʼéֽş̌׃"],[18,13,"וַ⁠יַּרְעֵ֬ם בַּ⁠שָּׁמַ֨יִם ׀ יְֽהוָ֗ה וְ֭⁠עֶלְיוֹן יִתֵּ֣ן קֹל֑⁠וֹ בָּ֝רָ֗ד וְ⁠גַֽחֲלֵי־אֵֽשׁ׃","wa⁠yȧrĕʻé֬m bȧ⁠şá̇̌ma֨yim ׀ yĕֽhwá֗h wĕ֭⁠ʻelĕywòn yiţé֣̇n qòl֑⁠wò bá̇֝rá֗d wĕ⁠gaֽẖàléy-ʼéֽş̌׃"],[18,14,"וַ⁠יִּשְׁלַ֣ח חִ֭צָּי⁠ו וַ⁠יְפִיצֵ֑⁠ם וּ⁠בְרָקִ֥ים רָ֝ב וַ⁠יְהֻמֵּֽ⁠ם׃","wa⁠yi̇şĕ̌la֣ẖ ẖi֭ẕá̇y⁠w wa⁠yĕpiyẕé֑⁠m ẇ⁠bĕráqi֥ym rá֝b wa⁠yĕhuméֽ̇⁠m׃"],[18,15,"וַ⁠יֵּ֤רָא֨וּ ׀ אֲפִ֥יקֵי מַ֗יִם וַֽ⁠יִּגָּלוּ֮ מוֹסְד֪וֹת תֵּ֫בֵ֥ל מִ⁠גַּעֲרָ֣תְ⁠ךָ֣ יְהוָ֑ה מִ֝⁠נִּשְׁמַ֗ת ר֣וּחַ אַפֶּֽ⁠ךָ׃","wa⁠yé֤̇ráʼ֨ẇ ׀ ʼàpi֥yqéy ma֗yim waֽ⁠yi̇gá̇lẇ֮ mwòsĕd֪wòţ ţé̇֫bé֥l mi⁠gȧʻàrá֣ţĕ⁠ká֣ yĕhwá֑h mi֝⁠ni̇şĕ̌ma֗ţ r֣ẇẖa ʼapėֽ⁠ká׃"],[18,16,"יִשְׁלַ֣ח מִ֭⁠מָּרוֹם יִקָּחֵ֑⁠נִי יַֽ֝מְשֵׁ֗⁠נִי מִ⁠מַּ֥יִם רַבִּֽים׃","yişĕ̌la֣ẖ mi֭⁠má̇rwòm yiqá̇ẖé֑⁠niy yaֽ֝mĕşé̌֗⁠niy mi⁠mȧ֥yim rabiֽ̇ym׃"],[18,17,"יַצִּילֵ֗⁠נִי מֵ⁠אֹיְבִ֥⁠י עָ֑ז וּ֝⁠מִ⁠שֹּׂנְאַ֗⁠י כִּֽי־אָמְצ֥וּ מִמֶּֽ⁠נִּי׃","yaẕi̇ylé֗⁠niy mé⁠ʼòyĕbi֥⁠y ʻá֑z ẇ֝⁠mi⁠şò̇̂nĕʼa֗⁠y kiֽ̇y-ʼámĕẕ֥ẇ mimėֽ⁠ni̇y׃"],[18,18,"יְקַדְּמ֥וּ⁠נִי בְ⁠יוֹם־אֵידִ֑⁠י וַֽ⁠יְהִי־יְהוָ֖ה לְ⁠מִשְׁעָ֣ן לִֽ⁠י׃","yĕqadĕ̇m֥ẇ⁠niy bĕ⁠ywòm-ʼéydi֑⁠y waֽ⁠yĕhiy-yĕhwá֖h lĕ⁠mişĕ̌ʻá֣n liֽ⁠y׃"],[18,19,"וַ⁠יּוֹצִיאֵ֥⁠נִי לַ⁠מֶּרְחָ֑ב יְ֝חַלְּצֵ֗⁠נִי כִּ֘י חָ֥פֵֽץ בִּֽ⁠י׃","wa⁠ẏwòẕiyʼé֥⁠niy la⁠mėrĕẖá֑b yĕ֝ẖalĕ̇ẕé֗⁠niy ki̇֘y ẖá֥péֽẕ biֽ̇⁠y׃"],[18,20,"יִגְמְלֵ֣⁠נִי יְהוָ֣ה כְּ⁠צִדְקִ֑⁠י כְּ⁠בֹ֥ר יָ֝דַ֗⁠י יָשִׁ֥יב לִֽ⁠י׃","yigĕmĕlé֣⁠niy yĕhwá֣h kĕ̇⁠ẕidĕqi֑⁠y kĕ̇⁠bò֥r yá֝da֗⁠y yáşǐ֥yb liֽ⁠y׃"],[18,21,"כִּֽי־שָׁ֭מַרְתִּי דַּרְכֵ֣י יְהוָ֑ה וְ⁠לֹֽא־רָ֝שַׁ֗עְתִּי מֵ⁠אֱלֹהָֽ⁠י׃","kiֽ̇y-şá֭̌marĕţi̇y dȧrĕké֣y yĕhwá֑h wĕ⁠lòֽʼ-rá֝şǎ֗ʻĕţi̇y mé⁠ʼèlòháֽ⁠y׃"],[18,22,"כִּ֣י כָל־מִשְׁפָּטָ֣י⁠ו לְ⁠נֶגְדִּ֑⁠י וְ֝⁠חֻקֹּתָ֗י⁠ו לֹא־אָסִ֥יר מֶֽנִּ⁠י׃","ki֣̇y kál-mişĕ̌pá̇tá֣y⁠w lĕ⁠negĕdi֑̇⁠y wĕ֝⁠ẖuqò̇ţá֗y⁠w lòʼ-ʼási֥yr meֽni̇⁠y׃"],[18,23,"וָ⁠אֱהִ֣י תָמִ֣ים עִמּ֑⁠וֹ וָ֝⁠אֶשְׁתַּמֵּ֗ר מֵ⁠עֲוֺנִֽ⁠י׃","wá⁠ʼèhi֣y ţámi֣ym ʻiṁ֑⁠wò wá֝⁠ʼeşĕ̌ţȧmé̇֗r mé⁠ʻàwֺniֽ⁠y׃"],[18,24,"וַ⁠יָּֽשֶׁב־יְהוָ֣ה לִ֣⁠י כְ⁠צִדְקִ֑⁠י כְּ⁠בֹ֥ר יָ֝דַ֗⁠י לְ⁠נֶ֣גֶד עֵינָֽי⁠ו׃","wa⁠yáֽ̇şěb-yĕhwá֣h li֣⁠y kĕ⁠ẕidĕqi֑⁠y kĕ̇⁠bò֥r yá֝da֗⁠y lĕ⁠ne֣ged ʻéynáֽy⁠w׃"],[18,25,"עִם־חָסִ֥יד תִּתְחַסָּ֑ד עִם־גְּבַ֥ר תָּ֝מִ֗ים תִּתַּמָּֽם׃","ʻim-ẖási֥yd ţi̇ţĕẖasá֑̇d ʻim-gĕ̇ba֥r ţá̇֝mi֗ym ţi̇ţȧmáֽ̇m׃"],[18,26,"עִם־נָבָ֥ר תִּתְבָּרָ֑ר וְ⁠עִם־עִ֝קֵּ֗שׁ תִּתְפַּתָּֽל׃","ʻim-nábá֥r ţi̇ţĕbá̇rá֑r wĕ⁠ʻim-ʻi֝qé̇֗ş̌ ţi̇ţĕpȧţáֽ̇l׃"],[18,27,"כִּֽי־אַ֭תָּה עַם־עָנִ֣י תוֹשִׁ֑יעַ וְ⁠עֵינַ֖יִם רָמ֣וֹת תַּשְׁפִּֽיל׃","kiֽ̇y-ʼa֭ţá̇h ʻam-ʻáni֣y ţwòşǐ֑yʻa wĕ⁠ʻéyna֖yim rám֣wòţ ţȧşĕ̌piֽ̇yl׃"],[18,28,"כִּֽי־אַ֭תָּה תָּאִ֣יר נֵרִ֑⁠י יְהוָ֥ה אֱ֝לֹהַ֗⁠י יַגִּ֥יהַּ חָשְׁכִּֽ⁠י׃","kiֽ̇y-ʼa֭ţá̇h ţá̇ʼi֣yr néri֑⁠y yĕhwá֥h ʼè֝lòha֗⁠y yagi֥̇yhȧ ẖáşĕ̌kiֽ̇⁠y׃"],[18,29,"כִּֽי־בְ֭⁠ךָ אָרֻ֣ץ גְּד֑וּד וּ֝⁠בֵֽ⁠אלֹהַ֗⁠י אֲדַלֶּג־שֽׁוּר׃","kiֽ̇y-bĕ֭⁠ká ʼáru֣ẕ gĕ̇d֑ẇd ẇ֝⁠béֽ⁠ʼlòha֗⁠y ʼàdalėg-şֽ̌ẇr׃"],[18,30,"הָ⁠אֵל֮ תָּמִ֪ים דַּ֫רְכּ֥⁠וֹ אִמְרַֽת־יְהוָ֥ה צְרוּפָ֑ה מָגֵ֥ן ה֝֗וּא לְ⁠כֹ֤ל ׀ הַ⁠חֹסִ֬ים בּֽ⁠וֹ׃","há⁠ʼél֮ ţá̇mi֪ym dȧ֫rĕk֥̇⁠wò ʼimĕraֽţ-yĕhwá֥h ẕĕrẇpá֑h mágé֥n h֝֗ẇʼ lĕ⁠kò֤l ׀ ha⁠ẖòsi֬ym ḃֽ⁠wò׃"],[18,31,"כִּ֤י מִ֣י אֱ֭לוֹהַּ מִ⁠בַּלְעֲדֵ֣י יְהוָ֑ה וּ⁠מִ֥י צ֝֗וּר זוּלָתִ֥⁠י אֱלֹהֵֽי⁠נוּ׃","ki֤̇y mi֣y ʼè֭lwòhȧ mi⁠bȧlĕʻàdé֣y yĕhwá֑h ẇ⁠mi֥y ẕ֝֗ẇr zẇláţi֥⁠y ʼèlòhéֽy⁠nẇ׃"],[18,32,"הָ֭⁠אֵל הַ⁠מְאַזְּרֵ֣⁠נִי חָ֑יִל וַ⁠יִּתֵּ֖ן תָּמִ֣ים דַּרְכִּֽ⁠י׃","há֭⁠ʼél ha⁠mĕʼazĕ̇ré֣⁠niy ẖá֑yil wa⁠yi̇ţé֖̇n ţá̇mi֣ym dȧrĕkiֽ̇⁠y׃"],[18,33,"מְשַׁוֶּ֣ה רַ֭גְלַ⁠י כָּ⁠אַיָּל֑וֹת וְ⁠עַ֥ל בָּ֝מֹתַ֗⁠י יַעֲמִידֵֽ⁠נִי׃","mĕşǎwė֣h ra֭gĕla⁠y ká̇⁠ʼayá̇l֑wòţ wĕ⁠ʻa֥l bá̇֝mòţa֗⁠y yaʻàmiydéֽ⁠niy׃"],[18,34,"מְלַמֵּ֣ד יָ֭דַ⁠י לַ⁠מִּלְחָמָ֑ה וְֽ⁠נִחֲתָ֥ה קֶֽשֶׁת־נְ֝חוּשָׁ֗ה זְרוֹעֹתָֽ⁠י׃","mĕlamé֣̇d yá֭da⁠y la⁠mi̇lĕẖámá֑h wĕֽ⁠niẖàţá֥h qeֽşěţ-nĕ֝ẖẇşá̌֗h zĕrwòʻòţáֽ⁠y׃"],[18,35,"וַ⁠תִּתֶּן־לִ⁠י֮ מָגֵ֪ן יִ֫שְׁעֶ֥⁠ךָ וִֽ⁠ימִינְ⁠ךָ֥ תִסְעָדֵ֑⁠נִי וְֽ⁠עַנְוַתְ⁠ךָ֥ תַרְבֵּֽ⁠נִי׃","wa⁠ţi̇ţėn-li⁠y֮ mágé֪n yi֫şĕ̌ʻe֥⁠ká wiֽ⁠ymiynĕ⁠ká֥ ţisĕʻádé֑⁠niy wĕֽ⁠ʻanĕwaţĕ⁠ká֥ ţarĕbéֽ̇⁠niy׃"],[18,36,"תַּרְחִ֣יב צַעֲדִ֣⁠י תַחְתָּ֑⁠י וְ⁠לֹ֥א מָ֝עֲד֗וּ קַרְסֻלָּֽ⁠י׃","ţȧrĕẖi֣yb ẕaʻàdi֣⁠y ţaẖĕţá֑̇⁠y wĕ⁠lò֥ʼ má֝ʻàd֗ẇ qarĕsuláֽ̇⁠y׃"],[18,37,"אֶרְדּ֣וֹף א֭וֹיְבַ⁠י וְ⁠אַשִּׂיגֵ֑⁠ם וְ⁠לֹֽא־אָ֝שׁוּב עַד־כַּלּוֹתָֽ⁠ם׃","ʼerĕḋ֣wòp ʼ֭wòyĕba⁠y wĕ⁠ʼaşi̇̂ygé֑⁠m wĕ⁠lòֽʼ-ʼá֝ş̌ẇb ʻad-kȧl̇wòţáֽ⁠m׃"],[18,38,"אֶ֭מְחָצֵ⁠ם וְ⁠לֹא־יֻ֣כְלוּ ק֑וּם יִ֝פְּל֗וּ תַּ֣חַת רַגְלָֽ⁠י׃","ʼe֭mĕẖáẕé⁠m wĕ⁠lòʼ-yu֣kĕlẇ q֑ẇm yi֝pĕ̇l֗ẇ ţȧ֣ẖaţ ragĕláֽ⁠y׃"],[18,39,"וַ⁠תְּאַזְּרֵ֣⁠נִי חַ֭יִל לַ⁠מִּלְחָמָ֑ה תַּכְרִ֖יעַ קָמַ֣⁠י תַּחְתָּֽ⁠י׃","wa⁠ţĕ̇ʼazĕ̇ré֣⁠niy ẖa֭yil la⁠mi̇lĕẖámá֑h ţȧkĕri֖yʻa qáma֣⁠y ţȧẖĕţáֽ̇⁠y׃"],[18,40,"וְֽ⁠אֹיְבַ֗⁠י נָתַ֣תָּה לִּ֣⁠י עֹ֑רֶף וּ֝⁠מְשַׂנְאַ֗⁠י אַצְמִיתֵֽ⁠ם׃","wĕֽ⁠ʼòyĕba֗⁠y náţa֣ţá̇h li֣̇⁠y ʻò֑rep ẇ֝⁠mĕşânĕʼa֗⁠y ʼaẕĕmiyţéֽ⁠m׃"],[18,41,"יְשַׁוְּע֥וּ וְ⁠אֵין־מוֹשִׁ֑יעַ עַל־יְ֝הוָ֗ה וְ⁠לֹ֣א עָנָֽ⁠ם׃","yĕşǎwĕ̇ʻ֥ẇ wĕ⁠ʼéyn-mwòşǐ֑yʻa ʻal-yĕ֝hwá֗h wĕ⁠lò֣ʼ ʻánáֽ⁠m׃"],[18,42,"וְֽ⁠אֶשְׁחָקֵ֗⁠ם כְּ⁠עָפָ֥ר עַל־פְּנֵי־ר֑וּחַ כְּ⁠טִ֖יט חוּצ֣וֹת אֲרִיקֵֽ⁠ם׃","wĕֽ⁠ʼeşĕ̌ẖáqé֗⁠m kĕ̇⁠ʻápá֥r ʻal-pĕ̇néy-r֑ẇẖa kĕ̇⁠ti֖yt ẖẇẕ֣wòţ ʼàriyqéֽ⁠m׃"],[18,43,"תְּפַלְּטֵ⁠נִי֮ מֵ⁠רִ֪יבֵ֫י עָ֥ם תְּ֭שִׂימֵ⁠נִי לְ⁠רֹ֣אשׁ גּוֹיִ֑ם עַ֖ם לֹא־יָדַ֣עְתִּי יַֽעַבְדֽוּ⁠נִי׃","ţĕ̇palĕ̇té⁠niy֮ mé⁠ri֪ybé֫y ʻá֥m ţĕ֭̇şîymé⁠niy lĕ⁠rò֣ʼş̌ ġwòyi֑m ʻa֖m lòʼ-yáda֣ʻĕţi̇y yaֽʻabĕdֽẇ⁠niy׃"],[18,44,"לְ⁠שֵׁ֣מַֽע אֹ֭זֶן יִשָּׁ֣מְעוּ לִ֑⁠י בְּנֵֽי־נֵ֝כָ֗ר יְכַחֲשׁוּ־לִֽ⁠י׃","lĕ⁠şé֣̌maֽʻ ʼò֭zen yişá֣̇̌mĕʻẇ li֑⁠y bĕ̇néֽy-né֝ká֗r yĕkaẖàş̌ẇ-liֽ⁠y׃"],[18,45,"בְּנֵי־נֵכָ֥ר יִבֹּ֑לוּ וְ֝⁠יַחְרְג֗וּ מִֽ⁠מִּסְגְּרֽוֹתֵי⁠הֶֽם׃","bĕ̇néy-néká֥r yibò֑̇lẇ wĕ֝⁠yaẖĕrĕg֗ẇ miֽ⁠mi̇sĕgĕ̇rֽwòţéy⁠heֽm׃"],[18,46,"חַי־יְ֭הוָה וּ⁠בָר֣וּךְ צוּרִ֑⁠י וְ֝⁠יָר֗וּם אֱלוֹהֵ֥י יִשְׁעִֽ⁠י׃","ẖay-yĕ֭hwáh ẇ⁠bár֣ẇkĕ ẕẇri֑⁠y wĕ֝⁠yár֗ẇm ʼèlwòhé֥y yişĕ̌ʻiֽ⁠y׃"],[18,47,"הָ⁠אֵ֗ל הַ⁠נּוֹתֵ֣ן נְקָמ֣וֹת לִ֑⁠י וַ⁠יַּדְבֵּ֖ר עַמִּ֣ים תַּחְתָּֽ⁠י׃","há⁠ʼé֗l ha⁠ṅwòţé֣n nĕqám֣wòţ li֑⁠y wa⁠yȧdĕbé֖̇r ʻami֣̇ym ţȧẖĕţáֽ̇⁠y׃"],[18,48,"מְפַלְּטִ֗⁠י מֵ⁠אֹ֫יְבָ֥⁠י אַ֣ף מִן־קָ֭מַ⁠י תְּרוֹמְמֵ֑⁠נִי מֵ⁠אִ֥ישׁ חָ֝מָ֗ס תַּצִּילֵֽ⁠נִי׃","mĕpalĕ̇ti֗⁠y mé⁠ʼò֫yĕbá֥⁠y ʼa֣p min-qá֭ma⁠y ţĕ̇rwòmĕmé֑⁠niy mé⁠ʼi֥yş̌ ẖá֝má֗s ţȧẕi̇yléֽ⁠niy׃"],[18,49,"עַל־כֵּ֤ן ׀ אוֹדְ⁠ךָ֖ בַ⁠גּוֹיִ֥ם ׀ יְהוָ֑ה וּ⁠לְ⁠שִׁמְ⁠ךָ֥ אֲזַמֵּֽרָה׃","ʻal-ké֤̇n ׀ ʼwòdĕ⁠ká֖ ba⁠ġwòyi֥m ׀ yĕhwá֑h ẇ⁠lĕ⁠şǐmĕ⁠ká֥ ʼàzaméֽ̇ráh׃"],[18,50,"מגדל יְשׁוּע֪וֹת מַ֫לְכּ֥⁠וֹ וְ⁠עֹ֤שֶׂה חֶ֨סֶד ׀ לִ⁠מְשִׁיח֗⁠וֹ לְ⁠דָוִ֥ד וּ⁠לְ⁠זַרְע֗⁠וֹ עַד־עוֹלָֽם׃","mgdl yĕş̌ẇʻ֪wòţ ma֫lĕk֥̇⁠wò wĕ⁠ʻò֤şêh ẖe֨sed ׀ li⁠mĕşǐyẖ֗⁠wò lĕ⁠dáwi֥d ẇ⁠lĕ⁠zarĕʻ֗⁠wò ʻad-ʻwòláֽm׃"],[19,1,"הַ⁠שָּׁמַ֗יִם מְֽסַפְּרִ֥ים כְּבֽוֹד־אֵ֑ל וּֽ⁠מַעֲשֵׂ֥ה יָ֝דָ֗י⁠ו מַגִּ֥יד הָ⁠רָקִֽיעַ׃","ha⁠şá̇̌ma֗yim mĕֽsapĕ̇ri֥ym kĕ̇bֽwòd-ʼé֑l ẇֽ⁠maʻàşé֥̂h yá֝dá֗y⁠w magi֥̇yd há⁠ráqiֽyʻa׃"],[19,2,"י֣וֹם לְ֭⁠יוֹם יַבִּ֣יעַֽ אֹ֑מֶר וְ⁠לַ֥יְלָה לְּ֝⁠לַ֗יְלָה יְחַוֶּה־דָּֽעַת׃","y֣wòm lĕ֭⁠ywòm yabi֣̇yʻaֽ ʼò֑mer wĕ⁠la֥yĕláh lĕ̇֝⁠la֗yĕláh yĕẖawėh-dáֽ̇ʻaţ׃"],[19,3,"אֵֽין־אֹ֭מֶר וְ⁠אֵ֣ין דְּבָרִ֑ים בְּ֝לִ֗י נִשְׁמָ֥ע קוֹלָֽ⁠ם׃","ʼéֽyn-ʼò֭mer wĕ⁠ʼé֣yn dĕ̇bári֑ym bĕ̇֝li֗y nişĕ̌má֥ʻ qwòláֽ⁠m׃"],[19,4,"בְּ⁠כָל־הָ⁠אָ֨רֶץ ׀ יָ֘צָ֤א קַוָּ֗⁠ם וּ⁠בִ⁠קְצֵ֣ה תֵ֭בֵל מִלֵּי⁠הֶ֑ם לַ֝⁠שֶּׁ֗מֶשׁ שָֽׂם־אֹ֥הֶל בָּ⁠הֶֽם׃","bĕ̇⁠kál-há⁠ʼá֨reẕ ׀ yá֘ẕá֤ʼ qawá̇֗⁠m ẇ⁠bi⁠qĕẕé֣h ţé֭bél milé̇y⁠he֑m la֝⁠şė̌֗meş̌ şáֽ̂m-ʼò֥hel bá̇⁠heֽm׃"],[19,5,"וְ⁠ה֗וּא כְּ֭⁠חָתָן יֹצֵ֣א מֵ⁠חֻפָּת֑⁠וֹ יָשִׂ֥ישׂ כְּ֝⁠גִבּ֗וֹר לָ⁠ר֥וּץ אֹֽרַח׃","wĕ⁠h֗ẇʼ kĕ֭̇⁠ẖáţán yòẕé֣ʼ mé⁠ẖupá̇ţ֑⁠wò yáşî֥yş̂ kĕ̇֝⁠giḃ֗wòr lá⁠r֥ẇẕ ʼòֽraẖ׃"],[19,6,"מִ⁠קְצֵ֤ה הַ⁠שָּׁמַ֨יִם ׀ מֽוֹצָא֗⁠וֹ וּ⁠תְקוּפָת֥⁠וֹ עַל־קְצוֹתָ֑⁠ם וְ⁠אֵ֥ין נִ֝סְתָּ֗ר מֵֽ⁠חַמָּת⁠וֹ׃","mi⁠qĕẕé֤h ha⁠şá̇̌ma֨yim ׀ mֽwòẕáʼ֗⁠wò ẇ⁠ţĕqẇpáţ֥⁠wò ʻal-qĕẕwòţá֑⁠m wĕ⁠ʼé֥yn ni֝sĕţá̇֗r méֽ⁠ẖamá̇ţ⁠wò׃"],[19,7,"תּ֘וֹרַ֤ת יְהוָ֣ה תְּ֭מִימָה מְשִׁ֣יבַת נָ֑פֶשׁ עֵד֥וּת יְהוָ֥ה נֶ֝אֱמָנָ֗ה מַחְכִּ֥ימַת פֶּֽתִי׃","ţ̇֘wòra֤ţ yĕhwá֣h ţĕ֭̇miymáh mĕşǐ֣ybaţ ná֑peş̌ ʻéd֥ẇţ yĕhwá֥h ne֝ʼèmáná֗h maẖĕki֥̇ymaţ pėֽţiy׃"],[19,8,"פִּקּ֘וּדֵ֤י יְהוָ֣ה יְ֭שָׁרִים מְשַׂמְּחֵי־לֵ֑ב מִצְוַ֥ת יְהוָ֥ה בָּ֝רָ֗ה מְאִירַ֥ת עֵינָֽיִם׃","pi̇q̇֘ẇdé֤y yĕhwá֣h yĕ֭şá̌riym mĕşâmĕ̇ẖéy-lé֑b miẕĕwa֥ţ yĕhwá֥h bá̇֝rá֗h mĕʼiyra֥ţ ʻéynáֽyim׃"],[19,9,"יִרְאַ֤ת יְהוָ֨ה ׀ טְהוֹרָה֮ עוֹמֶ֪דֶת לָ֫⁠עַ֥ד מִֽשְׁפְּטֵי־יְהוָ֥ה אֱמֶ֑ת צָֽדְק֥וּ יַחְדָּֽו׃","yirĕʼa֤ţ yĕhwá֨h ׀ tĕhwòráh֮ ʻwòme֪deţ lá֫⁠ʻa֥d miֽşĕ̌pĕ̇téy-yĕhwá֥h ʼème֑ţ ẕáֽdĕq֥ẇ yaẖĕdáֽ̇w׃"],[19,10,"הַֽ⁠נֶּחֱמָדִ֗ים מִ֭⁠זָּהָב וּ⁠מִ⁠פַּ֣ז רָ֑ב וּ⁠מְתוּקִ֥ים מִ֝⁠דְּבַ֗שׁ וְ⁠נֹ֣פֶת צוּפִֽים׃","haֽ⁠nėẖèmádi֗ym mi֭⁠zá̇háb ẇ⁠mi⁠pȧ֣z rá֑b ẇ⁠mĕţẇqi֥ym mi֝⁠dĕ̇ba֗ş̌ wĕ⁠nò֣peţ ẕẇpiֽym׃"],[19,11,"גַּֽם־עַ֭בְדְּ⁠ךָ נִזְהָ֣ר בָּ⁠הֶ֑ם בְּ֝⁠שָׁמְרָ֗⁠ם עֵ֣קֶב רָֽב׃","gȧֽm-ʻa֭bĕdĕ̇⁠ká nizĕhá֣r bá̇⁠he֑m bĕ̇֝⁠şá̌mĕrá֗⁠m ʻé֣qeb ráֽb׃"],[19,12,"שְׁגִיא֥וֹת מִֽי־יָבִ֑ין מִֽ⁠נִּסְתָּר֥וֹת נַקֵּֽ⁠נִי׃","şĕ̌giyʼ֥wòţ miֽy-yábi֑yn miֽ⁠ni̇sĕţá̇r֥wòţ naqéֽ̇⁠niy׃"],[19,13,"גַּ֤ם מִ⁠זֵּדִ֨ים ׀ חֲשֹׂ֬ךְ עַבְדֶּ֗⁠ךָ אַֽל־יִמְשְׁלוּ־בִ֣⁠י אָ֣ז אֵיתָ֑ם וְ֝⁠נִקֵּ֗יתִי מִ⁠פֶּ֥שַֽׁע רָֽב׃","gȧ֤m mi⁠zé̇di֨ym ׀ ẖàşò̂֬kĕ ʻabĕdė֗⁠ká ʼaֽl-yimĕşĕ̌lẇ-bi֣⁠y ʼá֣z ʼéyţá֑m wĕ֝⁠niqé̇֗yţiy mi⁠pė֥şǎֽʻ ráֽb׃"],[19,14,"יִֽהְי֥וּ לְ⁠רָצ֨וֹן ׀ אִמְרֵי־פִ֡⁠י וְ⁠הֶגְי֣וֹן לִבִּ֣⁠י לְ⁠פָנֶ֑י⁠ךָ יְ֝הוָ֗ה צוּרִ֥⁠י וְ⁠גֹאֲלִֽ⁠י׃","yiֽhĕy֥ẇ lĕ⁠ráẕ֨wòn ׀ ʼimĕréy-pi֡⁠y wĕ⁠hegĕy֣wòn libi֣̇⁠y lĕ⁠páne֑y⁠ká yĕ֝hwá֗h ẕẇri֥⁠y wĕ⁠gòʼàliֽ⁠y׃"],[20,1,"יַֽעַנְ⁠ךָ֣ יְ֭הוָה בְּ⁠י֣וֹם צָרָ֑ה יְ֝שַׂגֶּבְ⁠ךָ֗ שֵׁ֤ם ׀ אֱלֹהֵ֬י יַעֲקֹֽב׃","yaֽʻanĕ⁠ká֣ yĕ֭hwáh bĕ̇⁠y֣wòm ẕárá֑h yĕ֝şâgėbĕ⁠ká֗ şé֤̌m ׀ ʼèlòhé֬y yaʻàqòֽb׃"],[20,2,"יִשְׁלַֽח־עֶזְרְ⁠ךָ֥ מִ⁠קֹּ֑דֶשׁ וּ֝⁠מִ⁠צִּיּ֗וֹן יִסְעָדֶֽ⁠ךָּ׃","yişĕ̌laֽẖ-ʻezĕrĕ⁠ká֥ mi⁠qò֑̇deş̌ ẇ֝⁠mi⁠ẕi̇ẏ֗wòn yisĕʻádeֽ⁠ká̇׃"],[20,3,"יִזְכֹּ֥ר כָּל־מִנְחֹתֶ֑⁠ךָ וְ⁠עוֹלָתְ⁠ךָ֖ יְדַשְּׁנֶ֣⁠ה סֶֽלָה׃","yizĕkò֥̇r ká̇l-minĕẖòţe֑⁠ká wĕ⁠ʻwòláţĕ⁠ká֖ yĕdaşĕ̇̌ne֣⁠h seֽláh׃"],[20,4,"יִֽתֶּן־לְ⁠ךָ֥ כִ⁠לְבָבֶ֑⁠ךָ וְֽ⁠כָל־עֲצָתְ⁠ךָ֥ יְמַלֵּֽא׃","yiֽţėn-lĕ⁠ká֥ ki⁠lĕbábe֑⁠ká wĕֽ⁠kál-ʻàẕáţĕ⁠ká֥ yĕmaléֽ̇ʼ׃"],[20,5,"נְרַנְּנָ֤ה ׀ בִּ֘⁠ישׁ֤וּעָתֶ֗⁠ךָ וּ⁠בְ⁠שֵֽׁם־אֱלֹהֵ֥י⁠נוּ נִדְגֹּ֑ל יְמַלֵּ֥א יְ֝הוָ֗ה כָּל־מִשְׁאֲלוֹתֶֽי⁠ךָ׃","nĕranĕ̇ná֤h ׀ bi̇֘⁠yş֤̌ẇʻáţe֗⁠ká ẇ⁠bĕ⁠şéֽ̌m-ʼèlòhé֥y⁠nẇ nidĕgò֑̇l yĕmalé֥̇ʼ yĕ֝hwá֗h ká̇l-mişĕ̌ʼàlwòţeֽy⁠ká׃"],[20,6,"עַתָּ֤ה יָדַ֗עְתִּי כִּ֤י הוֹשִׁ֥יעַ ׀ יְהוָ֗ה מְשִׁ֫יח֥⁠וֹ יַ֭עֲנֵ⁠הוּ מִ⁠שְּׁמֵ֣י קָדְשׁ֑⁠וֹ בִּ֝⁠גְבֻר֗וֹת יֵ֣שַׁע יְמִינֽ⁠וֹ׃","ʻaţá֤̇h yáda֗ʻĕţi̇y ki֤̇y hwòşǐ֥yʻa ׀ yĕhwá֗h mĕşǐ֫yẖ֥⁠wò ya֭ʻàné⁠hẇ mi⁠şĕ̇̌mé֣y qádĕş֑̌⁠wò bi̇֝⁠gĕbur֗wòţ yé֣şǎʻ yĕmiynֽ⁠wò׃"],[20,7,"אֵ֣לֶּה בָ֭⁠רֶכֶב וְ⁠אֵ֣לֶּה בַ⁠סּוּסִ֑ים וַ⁠אֲנַ֓חְנוּ ׀ בְּ⁠שֵׁם־יְהוָ֖ה אֱלֹהֵ֣י⁠נוּ נַזְכִּֽיר׃","ʼé֣lėh bá֭⁠rekeb wĕ⁠ʼé֣lėh ba⁠ṡẇsi֑ym wa⁠ʼàna֓ẖĕnẇ ׀ bĕ̇⁠şé̌m-yĕhwá֖h ʼèlòhé֣y⁠nẇ nazĕkiֽ̇yr׃"],[20,8,"הֵ֭מָּה כָּרְע֣וּ וְ⁠נָפָ֑לוּ וַ⁠אֲנַ֥חְנוּ קַּ֝֗מְנוּ וַ⁠נִּתְעוֹדָֽד׃","hé֭má̇h ká̇rĕʻ֣ẇ wĕ⁠nápá֑lẇ wa⁠ʼàna֥ẖĕnẇ qȧ֝֗mĕnẇ wa⁠ni̇ţĕʻwòdáֽd׃"],[20,9,"יְהוָ֥ה הוֹשִׁ֑יעָ⁠ה הַ֝⁠מֶּ֗לֶךְ יַעֲנֵ֥⁠נוּ בְ⁠יוֹם־קָרְאֵֽ⁠נוּ׃","yĕhwá֥h hwòşǐ֑yʻá⁠h ha֝⁠mė֗lekĕ yaʻàné֥⁠nẇ bĕ⁠ywòm-qárĕʼéֽ⁠nẇ׃"],[21,1,"יְֽהוָ֗ה בְּ⁠עָזְּ⁠ךָ֥ יִשְׂמַח־מֶ֑לֶךְ וּ֝⁠בִ⁠ישׁ֥וּעָתְ⁠ךָ֗ מַה־יגיל מְאֹֽד׃","yĕֽhwá֗h bĕ̇⁠ʻázĕ̇⁠ká֥ yişĕ̂maẖ-me֑lekĕ ẇ֝⁠bi⁠yş֥̌ẇʻáţĕ⁠ká֗ mah-ygyl mĕʼòֽd׃"],[21,2,"תַּאֲוַ֣ת לִ֭בּ⁠וֹ נָתַ֣תָּה לּ֑⁠וֹ וַ⁠אֲרֶ֥שֶׁת שְׂ֝פָתָ֗י⁠ו בַּל־מָנַ֥עְתָּ סֶּֽלָה׃","ţȧʼàwa֣ţ li֭ḃ⁠wò náţa֣ţá̇h l֑̇⁠wò wa⁠ʼàre֥şěţ şĕ̂֝páţá֗y⁠w bȧl-mána֥ʻĕţá̇ sėֽláh׃"],[21,3,"כִּֽי־תְ֭קַדְּמֶ⁠נּוּ בִּרְכ֣וֹת ט֑וֹב תָּשִׁ֥ית לְ֝⁠רֹאשׁ֗⁠וֹ עֲטֶ֣רֶת פָּֽז׃","kiֽ̇y-ţĕ֭qadĕ̇me⁠ṅẇ bi̇rĕk֣wòţ t֑wòb ţá̇şǐ֥yţ lĕ֝⁠ròʼş̌֗⁠wò ʻàte֣reţ páֽ̇z׃"],[21,4,"חַיִּ֤ים ׀ שָׁאַ֣ל מִ֭מְּ⁠ךָ נָתַ֣תָּה לּ֑⁠וֹ אֹ֥רֶךְ יָ֝מִ֗ים עוֹלָ֥ם וָ⁠עֶֽד׃","ẖayi֤̇ym ׀ şá̌ʼa֣l mi֭mĕ̇⁠ká náţa֣ţá̇h l֑̇⁠wò ʼò֥rekĕ yá֝mi֗ym ʻwòlá֥m wá⁠ʻeֽd׃"],[21,5,"גָּד֣וֹל כְּ֭בוֹד⁠וֹ בִּ⁠ישׁוּעָתֶ֑⁠ךָ ה֥וֹד וְ֝⁠הָדָר תְּשַׁוֶּ֥ה עָלָֽי⁠ו׃","gá̇d֣wòl kĕ֭̇bwòd⁠wò bi̇⁠yş̌ẇʻáţe֑⁠ká h֥wòd wĕ֝⁠hádár ţĕ̇şǎwė֥h ʻáláֽy⁠w׃"],[21,6,"כִּֽי־תְשִׁיתֵ֣⁠הוּ בְרָכ֣וֹת לָ⁠עַ֑ד תְּחַדֵּ֥⁠הוּ בְ֝⁠שִׂמְחָ֗ה אֶת־פָּנֶֽי⁠ךָ׃","kiֽ̇y-ţĕşǐyţé֣⁠hẇ bĕrák֣wòţ lá⁠ʻa֑d ţĕ̇ẖadé֥̇⁠hẇ bĕ֝⁠şîmĕẖá֗h ʼeţ-pá̇neֽy⁠ká׃"],[21,7,"כִּֽי־הַ֭⁠מֶּלֶךְ בֹּטֵ֣חַ בַּ⁠יהוָ֑ה וּ⁠בְ⁠חֶ֥סֶד עֶ֝לְי֗וֹן בַּל־יִמּֽוֹט׃","kiֽ̇y-ha֭⁠mėlekĕ bò̇té֣ẖa bȧ⁠yhwá֑h ẇ⁠bĕ⁠ẖe֥sed ʻe֝lĕy֗wòn bȧl-yiṁֽwòt׃"],[21,8,"תִּמְצָ֣א יָ֭דְ⁠ךָ לְ⁠כָל־אֹיְבֶ֑י⁠ךָ יְ֝מִֽינְ⁠ךָ תִּמְצָ֥א שֹׂנְאֶֽי⁠ךָ׃","ţi̇mĕẕá֣ʼ yá֭dĕ⁠ká lĕ⁠kál-ʼòyĕbe֑y⁠ká yĕ֝miֽynĕ⁠ká ţi̇mĕẕá֥ʼ şò̂nĕʼeֽy⁠ká׃"],[21,9,"תְּשִׁיתֵ֤⁠מוֹ ׀ כְּ⁠תַנּ֥וּר אֵשׁ֮ לְ⁠עֵ֪ת פָּ֫נֶ֥י⁠ךָ יְ֭הוָה בְּ⁠אַפּ֣⁠וֹ יְבַלְּעֵ֑⁠ם וְֽ⁠תֹאכְלֵ֥⁠ם אֵֽשׁ׃","ţĕ̇şǐyţé֤⁠mwò ׀ kĕ̇⁠ţaṅ֥ẇr ʼéş֮̌ lĕ⁠ʻé֪ţ pá̇֫ne֥y⁠ká yĕ֭hwáh bĕ̇⁠ʼaṗ֣⁠wò yĕbalĕ̇ʻé֑⁠m wĕֽ⁠ţòʼkĕlé֥⁠m ʼéֽş̌׃"],[21,10,"פִּ֭רְיָ⁠מוֹ מֵ⁠אֶ֣רֶץ תְּאַבֵּ֑ד וְ֝⁠זַרְעָ֗⁠ם מִ⁠בְּנֵ֥י אָדָֽם׃","pi֭̇rĕyá⁠mwò mé⁠ʼe֣reẕ ţĕ̇ʼabé֑̇d wĕ֝⁠zarĕʻá֗⁠m mi⁠bĕ̇né֥y ʼádáֽm׃"],[21,11,"כִּי־נָט֣וּ עָלֶ֣י⁠ךָ רָעָ֑ה חָֽשְׁב֥וּ מְ֝זִמָּ֗ה בַּל־יוּכָֽלוּ׃","ki̇y-nát֣ẇ ʻále֣y⁠ká ráʻá֑h ẖáֽşĕ̌b֥ẇ mĕ֝zimá̇֗h bȧl-yẇkáֽlẇ׃"],[21,12,"כִּ֭י תְּשִׁיתֵ֣⁠מוֹ שֶׁ֑כֶם בְּ֝⁠מֵֽיתָרֶ֗י⁠ךָ תְּכוֹנֵ֥ן עַל־פְּנֵי⁠הֶֽם׃","ki֭̇y ţĕ̇şǐyţé֣⁠mwò şě֑kem bĕ̇֝⁠méֽyţáre֗y⁠ká ţĕ̇kwòné֥n ʻal-pĕ̇néy⁠heֽm׃"],[21,13,"ר֣וּמָ⁠ה יְהוָ֣ה בְּ⁠עֻזֶּ֑⁠ךָ נָשִׁ֥ירָה וּֽ֝⁠נְזַמְּרָה גְּבוּרָתֶֽ⁠ךָ׃","r֣ẇmá⁠h yĕhwá֣h bĕ̇⁠ʻuzė֑⁠ká náşǐ֥yráh ẇֽ֝⁠nĕzamĕ̇ráh gĕ̇bẇráţeֽ⁠ká׃"],[22,1,"אֵלִ֣⁠י אֵ֭לִ⁠י לָ⁠מָ֣ה עֲזַבְתָּ֑⁠נִי רָח֥וֹק מִֽ֝⁠ישׁוּעָתִ֗⁠י דִּבְרֵ֥י שַׁאֲגָתִֽ⁠י׃","ʼéli֣⁠y ʼé֭li⁠y lá⁠má֣h ʻàzabĕţá֑̇⁠niy ráẖ֥wòq miֽ֝⁠yş̌ẇʻáţi֗⁠y di̇bĕré֥y şǎʼàgáţiֽ⁠y׃"],[22,2,"אֱֽלֹהַ֗⁠י אֶקְרָ֣א י֭וֹמָם וְ⁠לֹ֣א תַעֲנֶ֑ה וְ֝⁠לַ֗יְלָה וְֽ⁠לֹא־דֽוּמִיָּ֥ה לִֽ⁠י׃","ʼèֽlòha֗⁠y ʼeqĕrá֣ʼ y֭wòmám wĕ⁠lò֣ʼ ţaʻàne֑h wĕ֝⁠la֗yĕláh wĕֽ⁠lòʼ-dֽẇmiyá֥̇h liֽ⁠y׃"],[22,3,"וְ⁠אַתָּ֥ה קָד֑וֹשׁ י֝וֹשֵׁ֗ב תְּהִלּ֥וֹת יִשְׂרָאֵֽל׃","wĕ⁠ʼaţá֥̇h qád֑wòş̌ y֝wòşé̌֗b ţĕ̇hil֥̇wòţ yişĕ̂ráʼéֽl׃"],[22,4,"בְּ֭⁠ךָ בָּטְח֣וּ אֲבֹתֵ֑י⁠נוּ בָּ֝טְח֗וּ וַֽ⁠תְּפַלְּטֵֽ⁠מוֹ׃","bĕ֭̇⁠ká bá̇tĕẖ֣ẇ ʼàbòţé֑y⁠nẇ bá̇֝tĕẖ֗ẇ waֽ⁠ţĕ̇palĕ̇téֽ⁠mwò׃"],[22,5,"אֵלֶ֣י⁠ךָ זָעֲק֣וּ וְ⁠נִמְלָ֑טוּ בְּ⁠ךָ֖ בָטְח֣וּ וְ⁠לֹא־בֽוֹשׁוּ׃","ʼéle֣y⁠ká záʻàq֣ẇ wĕ⁠nimĕlá֑tẇ bĕ̇⁠ká֖ bátĕẖ֣ẇ wĕ⁠lòʼ-bֽwòş̌ẇ׃"],[22,6,"וְ⁠אָנֹכִ֣י תוֹלַ֣עַת וְ⁠לֹא־אִ֑ישׁ חֶרְפַּ֥ת אָ֝דָ֗ם וּ⁠בְז֥וּי עָֽם׃","wĕ⁠ʼánòki֣y ţwòla֣ʻaţ wĕ⁠lòʼ-ʼi֑yş̌ ẖerĕpȧ֥ţ ʼá֝dá֗m ẇ⁠bĕz֥ẇy ʻáֽm׃"],[22,7,"כָּל־רֹ֭אַ⁠י יַלְעִ֣גוּ לִ֑⁠י יַפְטִ֥ירוּ בְ֝⁠שָׂפָ֗ה יָנִ֥יעוּ רֹֽאשׁ׃","ká̇l-rò֭ʼa⁠y yalĕʻi֣gẇ li֑⁠y yapĕti֥yrẇ bĕ֝⁠şá̂pá֗h yáni֥yʻẇ ròֽʼş̌׃"],[22,8,"גֹּ֣ל אֶל־יְהוָ֣ה יְפַלְּטֵ֑⁠הוּ יַ֝צִּילֵ֗⁠הוּ כִּ֘י חָ֥פֵֽץ בּֽ⁠וֹ׃","gò֣̇l ʼel-yĕhwá֣h yĕpalĕ̇té֑⁠hẇ ya֝ẕi̇ylé֗⁠hẇ ki̇֘y ẖá֥péֽẕ ḃֽ⁠wò׃"],[22,9,"כִּֽי־אַתָּ֣ה גֹחִ֣⁠י מִ⁠בָּ֑טֶן מַ֝בְטִיחִ֗⁠י עַל־שְׁדֵ֥י אִמִּֽ⁠י׃","kiֽ̇y-ʼaţá֣̇h gòẖi֣⁠y mi⁠bá֑̇ten ma֝bĕtiyẖi֗⁠y ʻal-şĕ̌dé֥y ʼimiֽ̇⁠y׃"],[22,10,"עָ֭לֶי⁠ךָ הָשְׁלַ֣כְתִּי מֵ⁠רָ֑חֶם מִ⁠בֶּ֥טֶן אִ֝מִּ֗⁠י אֵ֣לִ⁠י אָֽתָּה׃","ʻá֭ley⁠ká háşĕ̌la֣kĕţi̇y mé⁠rá֑ẖem mi⁠bė֥ten ʼi֝mi̇֗⁠y ʼé֣li⁠y ʼáֽţá̇h׃"],[22,11,"אַל־תִּרְחַ֣ק מִ֭מֶּ⁠נִּי כִּי־צָרָ֣ה קְרוֹבָ֑ה כִּי־אֵ֥ין עוֹזֵֽר׃","ʼal-ţi̇rĕẖa֣q mi֭mė⁠ni̇y ki̇y-ẕárá֣h qĕrwòbá֑h ki̇y-ʼé֥yn ʻwòzéֽr׃"],[22,12,"סְ֭בָבוּ⁠נִי פָּרִ֣ים רַבִּ֑ים אַבִּירֵ֖י בָשָׁ֣ן כִּתְּרֽוּ⁠נִי׃","sĕ֭bábẇ⁠niy pá̇ri֣ym rabi֑̇ym ʼabi̇yré֖y báşá֣̌n ki̇ţĕ̇rֽẇ⁠niy׃"],[22,13,"פָּצ֣וּ עָלַ֣⁠י פִּי⁠הֶ֑ם אַ֝רְיֵ֗ה טֹרֵ֥ף וְ⁠שֹׁאֵֽג׃","pá̇ẕ֣ẇ ʻála֣⁠y pi̇y⁠he֑m ʼa֝rĕyé֗h tòré֥p wĕ⁠şò̌ʼéֽg׃"],[22,14,"כַּ⁠מַּ֥יִם נִשְׁפַּכְתִּי֮ וְ⁠הִתְפָּֽרְד֗וּ כָּֽל־עַצְמ֫וֹתָ֥⁠י הָיָ֣ה לִ֭בִּ⁠י כַּ⁠דּוֹנָ֑ג נָ֝מֵ֗ס בְּ⁠ת֣וֹךְ מֵעָֽ⁠י׃","kȧ⁠mȧ֥yim nişĕ̌pȧkĕţi̇y֮ wĕ⁠hiţĕpáֽ̇rĕd֗ẇ káֽ̇l-ʻaẕĕm֫wòţá֥⁠y háyá֣h li֭bi̇⁠y kȧ⁠ḋwòná֑g ná֝mé֗s bĕ̇⁠ţ֣wòkĕ méʻáֽ⁠y׃"],[22,15,"יָ֘בֵ֤שׁ כַּ⁠חֶ֨רֶשׂ ׀ כֹּחִ֗⁠י וּ֭⁠לְשׁוֹנִ⁠י מֻדְבָּ֣ק מַלְקוֹחָ֑⁠י וְֽ⁠לַ⁠עֲפַר־מָ֥וֶת תִּשְׁפְּתֵֽ⁠נִי׃","yá֘bé֤ş̌ kȧ⁠ẖe֨reş̂ ׀ kò̇ẖi֗⁠y ẇ֭⁠lĕş̌wòni⁠y mudĕbá֣̇q malĕqwòẖá֑⁠y wĕֽ⁠la⁠ʻàpar-má֥weţ ţi̇şĕ̌pĕ̇ţéֽ⁠niy׃"],[22,16,"כִּ֥י סְבָב֗וּ⁠נִי כְּלָ֫בִ֥ים עֲדַ֣ת מְ֭רֵעִים הִקִּיפ֑וּ⁠נִי כָּ֝⁠אֲרִ֗י יָדַ֥⁠י וְ⁠רַגְלָֽ⁠י׃","ki֥̇y sĕbáb֗ẇ⁠niy kĕ̇lá֫bi֥ym ʻàda֣ţ mĕ֭réʻiym hiqi̇yp֑ẇ⁠niy ká̇֝⁠ʼàri֗y yáda֥⁠y wĕ⁠ragĕláֽ⁠y׃"],[22,17,"אֲסַפֵּ֥ר כָּל־עַצְמוֹתָ֑⁠י הֵ֥מָּה יַ֝בִּ֗יטוּ יִרְאוּ־בִֽ⁠י׃","ʼàsapé֥̇r ká̇l-ʻaẕĕmwòţá֑⁠y hé֥má̇h ya֝bi̇֗ytẇ yirĕʼẇ-biֽ⁠y׃"],[22,18,"יְחַלְּק֣וּ בְגָדַ֣⁠י לָ⁠הֶ֑ם וְ⁠עַל־לְ֝בוּשִׁ֗⁠י יַפִּ֥ילוּ גוֹרָֽל׃","yĕẖalĕ̇q֣ẇ bĕgáda֣⁠y lá⁠he֑m wĕ⁠ʻal-lĕ֝bẇşǐ֗⁠y yapi֥̇ylẇ gwòráֽl׃"],[22,19,"וְ⁠אַתָּ֣ה יְ֭הוָה אַל־תִּרְחָ֑ק אֱ֝יָלוּתִ֗⁠י לְ⁠עֶזְרָ֥תִ⁠י חֽוּשָׁ⁠ה׃","wĕ⁠ʼaţá֣̇h yĕ֭hwáh ʼal-ţi̇rĕẖá֑q ʼè֝yálẇţi֗⁠y lĕ⁠ʻezĕrá֥ţi⁠y ẖֽẇşá̌⁠h׃"],[22,20,"הַצִּ֣ילָ⁠ה מֵ⁠חֶ֣רֶב נַפְשִׁ֑⁠י מִ⁠יַּד־כֶּ֝֗לֶב יְחִידָתִֽ⁠י׃","haẕi֣̇ylá⁠h mé⁠ẖe֣reb napĕşǐ֑⁠y mi⁠yȧd-kė֝֗leb yĕẖiydáţiֽ⁠y׃"],[22,21,"ה֭וֹשִׁיעֵ⁠נִי מִ⁠פִּ֣י אַרְיֵ֑ה וּ⁠מִ⁠קַּרְנֵ֖י רֵמִ֣ים עֲנִיתָֽ⁠נִי׃","h֭wòşǐyʻé⁠niy mi⁠pi֣̇y ʼarĕyé֑h ẇ⁠mi⁠qȧrĕné֖y rémi֣ym ʻàniyţáֽ⁠niy׃"],[22,22,"אֲסַפְּרָ֣ה שִׁמְ⁠ךָ֣ לְ⁠אֶחָ֑⁠י בְּ⁠ת֖וֹךְ קָהָ֣ל אֲהַלְלֶֽ⁠ךָּ׃","ʼàsapĕ̇rá֣h şǐmĕ⁠ká֣ lĕ⁠ʼeẖá֑⁠y bĕ̇⁠ţ֖wòkĕ qáhá֣l ʼàhalĕleֽ⁠ká̇׃"],[22,23,"יִרְאֵ֤י יְהוָ֨ה ׀ הַֽלְל֗וּ⁠הוּ כָּל־זֶ֣רַע יַעֲקֹ֣ב כַּבְּד֑וּ⁠הוּ וְ⁠ג֥וּרוּ מִ֝מֶּ֗⁠נּוּ כָּל־זֶ֥רַע יִשְׂרָאֵֽל׃","yirĕʼé֤y yĕhwá֨h ׀ haֽlĕl֗ẇ⁠hẇ ká̇l-ze֣raʻ yaʻàqò֣b kȧbĕ̇d֑ẇ⁠hẇ wĕ⁠g֥ẇrẇ mi֝mė֗⁠ṅẇ ká̇l-ze֥raʻ yişĕ̂ráʼéֽl׃"],[22,24,"כִּ֤י לֹֽא־בָזָ֨ה וְ⁠לֹ֪א שִׁקַּ֡ץ עֱנ֬וּת עָנִ֗י וְ⁠לֹא־הִסְתִּ֣יר פָּנָ֣י⁠ו מִמֶּ֑⁠נּוּ וּֽ⁠בְ⁠שַׁוְּע֖⁠וֹ אֵלָ֣י⁠ו שָׁמֵֽעַ׃","ki֤̇y lòֽʼ-bázá֨h wĕ⁠lò֪ʼ şǐqȧ֡ẕ ʻèn֬ẇţ ʻáni֗y wĕ⁠lòʼ-hisĕţi֣̇yr pá̇ná֣y⁠w mimė֑⁠ṅẇ ẇֽ⁠bĕ⁠şǎwĕ̇ʻ֖⁠wò ʼélá֣y⁠w şá̌méֽʻa׃"],[22,25,"מֵ֥⁠אִתְּ⁠ךָ֗ תְֽהִלָּ֫תִ֥⁠י בְּ⁠קָהָ֥ל רָ֑ב נְדָרַ֥⁠י אֲ֝שַׁלֵּ֗ם נֶ֣גֶד יְרֵאָֽי⁠ו׃","mé֥⁠ʼiţĕ̇⁠ká֗ ţĕֽhilá̇֫ţi֥⁠y bĕ̇⁠qáhá֥l rá֑b nĕdára֥⁠y ʼà֝şǎlé̇֗m ne֣ged yĕréʼáֽy⁠w׃"],[22,26,"יֹאכְל֬וּ עֲנָוִ֨ים ׀ וְ⁠יִשְׂבָּ֗עוּ יְהַֽלְל֣וּ יְ֭הוָה דֹּ֣רְשָׁ֑י⁠ו יְחִ֖י לְבַבְ⁠כֶ֣ם לָ⁠עַֽד׃","yòʼkĕl֬ẇ ʻànáwi֨ym ׀ wĕ⁠yişĕ̂bá̇֗ʻẇ yĕhaֽlĕl֣ẇ yĕ֭hwáh dò֣̇rĕşá֑̌y⁠w yĕẖi֖y lĕbabĕ⁠ke֣m lá⁠ʻaֽd׃"],[22,27,"יִזְכְּר֤וּ ׀ וְ⁠יָשֻׁ֣בוּ אֶל־יְ֭הוָה כָּל־אַפְסֵי־אָ֑רֶץ וְ⁠יִֽשְׁתַּחֲו֥וּ לְ֝⁠פָנֶ֗י⁠ךָ כָּֽל־מִשְׁפְּח֥וֹת גּוֹיִֽם׃","yizĕkĕ̇r֤ẇ ׀ wĕ⁠yáşǔ֣bẇ ʼel-yĕ֭hwáh ká̇l-ʼapĕséy-ʼá֑reẕ wĕ⁠yiֽşĕ̌ţȧẖàw֥ẇ lĕ֝⁠páne֗y⁠ká káֽ̇l-mişĕ̌pĕ̇ẖ֥wòţ ġwòyiֽm׃"],[22,28,"כִּ֣י לַ֭⁠יהוָה הַ⁠מְּלוּכָ֑ה וּ֝⁠מֹשֵׁ֗ל בַּ⁠גּוֹיִֽם׃","ki֣̇y la֭⁠yhwáh ha⁠mĕ̇lẇká֑h ẇ֝⁠mòşé̌֗l bȧ⁠ġwòyiֽm׃"],[22,29,"אָכְל֬וּ וַ⁠יִּֽשְׁתַּחֲוּ֨וּ ׀ כָּֽל־דִּשְׁנֵי־אֶ֗רֶץ לְ⁠פָנָ֣י⁠ו יִ֭כְרְעוּ כָּל־יוֹרְדֵ֣י עָפָ֑ר וְ֝⁠נַפְשׁ֗⁠וֹ לֹ֣א חִיָּֽה׃","ʼákĕl֬ẇ wa⁠yiֽ̇şĕ̌ţȧẖàẇ֨ẇ ׀ káֽ̇l-di̇şĕ̌néy-ʼe֗reẕ lĕ⁠páná֣y⁠w yi֭kĕrĕʻẇ ká̇l-ywòrĕdé֣y ʻápá֑r wĕ֝⁠napĕş̌֗⁠wò lò֣ʼ ẖiyáֽ̇h׃"],[22,30,"זֶ֥רַע יַֽעַבְדֶ֑⁠נּוּ יְסֻפַּ֖ר לַֽ⁠אדֹנָ֣⁠י לַ⁠דּֽוֹר׃","ze֥raʻ yaֽʻabĕde֑⁠ṅẇ yĕsupȧ֖r laֽ⁠ʼdòná֣⁠y la⁠ḋֽwòr׃"],[22,31,"יָ֭בֹאוּ וְ⁠יַגִּ֣ידוּ צִדְקָת֑⁠וֹ לְ⁠עַ֥ם נ֝וֹלָ֗ד כִּ֣י עָשָֽׂה׃","yá֭bòʼẇ wĕ⁠yagi֣̇ydẇ ẕidĕqáţ֑⁠wò lĕ⁠ʻa֥m n֝wòlá֗d ki֣̇y ʻáşáֽ̂h׃"],[23,1,"מִזְמ֥וֹר לְ⁠דָוִ֑ד יְהוָ֥ה רֹ֝עִ֗⁠י לֹ֣א אֶחְסָֽר׃","mizĕm֥wòr lĕ⁠dáwi֑d yĕhwá֥h rò֝ʻi֗⁠y lò֣ʼ ʼeẖĕsáֽr׃"],[23,2,"בִּ⁠נְא֣וֹת דֶּ֭שֶׁא יַרְבִּיצֵ֑⁠נִי עַל־מֵ֖י מְנֻח֣וֹת יְנַהֲלֵֽ⁠נִי׃","bi̇⁠nĕʼ֣wòţ dė֭şěʼ yarĕbi̇yẕé֑⁠niy ʻal-mé֖y mĕnuẖ֣wòţ yĕnahàléֽ⁠niy׃"],[23,3,"נַפְשִׁ֥⁠י יְשׁוֹבֵ֑ב יַֽנְחֵ֥⁠נִי בְ⁠מַעְגְּלֵי־צֶ֝֗דֶק לְמַ֣עַן שְׁמֽ⁠וֹ׃","napĕşǐ֥⁠y yĕş̌wòbé֑b yaֽnĕẖé֥⁠niy bĕ⁠maʻĕgĕ̇léy-ẕe֝֗deq lĕma֣ʻan şĕ̌mֽ⁠wò׃"],[23,4,"גַּ֤ם כִּֽי־אֵלֵ֨ךְ בְּ⁠גֵ֪יא צַלְמָ֡וֶת לֹא־אִ֘ירָ֤א רָ֗ע כִּי־אַתָּ֥ה עִמָּדִ֑⁠י שִׁבְטְ⁠ךָ֥ וּ֝⁠מִשְׁעַנְתֶּ֗⁠ךָ הֵ֣מָּה יְנַֽחֲמֻֽ⁠נִי׃","gȧ֤m kiֽ̇y-ʼélé֨kĕ bĕ̇⁠gé֪yʼ ẕalĕmá֡weţ lòʼ-ʼi֘yrá֤ʼ rá֗ʻ ki̇y-ʼaţá֥̇h ʻimá̇di֑⁠y şǐbĕtĕ⁠ká֥ ẇ֝⁠mişĕ̌ʻanĕţė֗⁠ká hé֣má̇h yĕnaֽẖàmuֽ⁠niy׃"],[23,5,"תַּעֲרֹ֬ךְ לְ⁠פָנַ֨⁠י ׀ שֻׁלְחָ֗ן נֶ֥גֶד צֹרְרָ֑⁠י דִּשַּׁ֖נְתָּ בַ⁠שֶּׁ֥מֶן רֹ֝אשִׁ֗⁠י כּוֹסִ֥⁠י רְוָיָֽה׃","ţȧʻàrò֬kĕ lĕ⁠pána֨⁠y ׀ şǔlĕẖá֗n ne֥ged ẕòrĕrá֑⁠y di̇şȧ֖̌nĕţá̇ ba⁠şė֥̌men rò֝ʼşǐ֗⁠y k̇wòsi֥⁠y rĕwáyáֽh׃"],[23,6,"אַ֤ךְ ׀ ט֤וֹב וָ⁠חֶ֣סֶד יִ֭רְדְּפוּ⁠נִי כָּל־יְמֵ֣י חַיָּ֑⁠י וְ⁠שַׁבְתִּ֥י בְּ⁠בֵית־יְ֝הוָ֗ה לְ⁠אֹ֣רֶךְ יָמִֽים׃","ʼa֤kĕ ׀ t֤wòb wá⁠ẖe֣sed yi֭rĕdĕ̇pẇ⁠niy ká̇l-yĕmé֣y ẖayá֑̇⁠y wĕ⁠şǎbĕţi֥̇y bĕ̇⁠béyţ-yĕ֝hwá֗h lĕ⁠ʼò֣rekĕ yámiֽym׃"],[24,1,"לְ⁠דָוִ֗ד מִ֫זְמ֥וֹר לַֽ֭⁠יהוָה הָ⁠אָ֣רֶץ וּ⁠מְלוֹאָ֑⁠הּ תֵּ֝בֵ֗ל וְ⁠יֹ֣שְׁבֵי בָֽ⁠הּ׃","lĕ⁠dáwi֗d mi֫zĕm֥wòr laֽ֭⁠yhwáh há⁠ʼá֣reẕ ẇ⁠mĕlwòʼá֑⁠ḣ ţé̇֝bé֗l wĕ⁠yò֣şĕ̌béy báֽ⁠ḣ׃"],[24,2,"כִּי־ה֭וּא עַל־יַמִּ֣ים יְסָדָ֑⁠הּ וְ⁠עַל־נְ֝הָר֗וֹת יְכוֹנְנֶֽ⁠הָ׃","ki̇y-h֭ẇʼ ʻal-yami֣̇ym yĕsádá֑⁠ḣ wĕ⁠ʻal-nĕ֝hár֗wòţ yĕkwònĕneֽ⁠há׃"],[24,3,"מִֽי־יַעֲלֶ֥ה בְ⁠הַר־יְהוָ֑ה וּ⁠מִי־יָ֝קוּם בִּ⁠מְק֥וֹם קָדְשֽׁ⁠וֹ׃","miֽy-yaʻàle֥h bĕ⁠har-yĕhwá֑h ẇ⁠miy-yá֝qẇm bi̇⁠mĕq֥wòm qádĕşֽ̌⁠wò׃"],[24,4,"נְקִ֥י כַפַּ֗יִם וּֽ⁠בַר־לֵ֫בָ֥ב אֲשֶׁ֤ר ׀ לֹא־נָשָׂ֣א לַ⁠שָּׁ֣וְא נַפְשִׁ֑⁠י וְ⁠לֹ֖א נִשְׁבַּ֣ע לְ⁠מִרְמָֽה׃","nĕqi֥y kapȧ֗yim ẇֽ⁠bar-lé֫bá֥b ʼàşě֤r ׀ lòʼ-náşá֣̂ʼ la⁠şá֣̇̌wĕʼ napĕşǐ֑⁠y wĕ⁠lò֖ʼ nişĕ̌bȧ֣ʻ lĕ⁠mirĕmáֽh׃"],[24,5,"יִשָּׂ֣א בְ֭רָכָה מֵ⁠אֵ֣ת יְהוָ֑ה וּ֝⁠צְדָקָ֗ה מֵ⁠אֱלֹהֵ֥י יִשְׁעֽ⁠וֹ׃","yişá֣̇̂ʼ bĕ֭rákáh mé⁠ʼé֣ţ yĕhwá֑h ẇ֝⁠ẕĕdáqá֗h mé⁠ʼèlòhé֥y yişĕ̌ʻֽ⁠wò׃"],[24,6,"זֶ֭ה דּ֣וֹר דרש⁠ו מְבַקְשֵׁ֨י פָנֶ֖י⁠ךָ יַעֲקֹ֣ב סֶֽלָה׃","ze֭h ḋ֣wòr drş⁠w mĕbaqĕşé̌֨y páne֖y⁠ká yaʻàqò֣b seֽláh׃"],[24,7,"שְׂא֤וּ שְׁעָרִ֨ים ׀ רָֽאשֵׁי⁠כֶ֗ם וְֽ֭⁠הִנָּשְׂאוּ פִּתְחֵ֣י עוֹלָ֑ם וְ֝⁠יָב֗וֹא מֶ֣לֶךְ הַ⁠כָּבֽוֹד׃","şĕ̂ʼ֤ẇ şĕ̌ʻári֨ym ׀ ráֽʼşé̌y⁠ke֗m wĕֽ֭⁠hiná̇şĕ̂ʼẇ pi̇ţĕẖé֣y ʻwòlá֑m wĕ֝⁠yáb֗wòʼ me֣lekĕ ha⁠ká̇bֽwòd׃"],[24,8,"מִ֥י זֶה֮ מֶ֤לֶךְ הַ⁠כָּ֫ב֥וֹד יְ֭הוָה עִזּ֣וּז וְ⁠גִבּ֑וֹר יְ֝הוָ֗ה גִּבּ֥וֹר מִלְחָמָֽה׃","mi֥y zeh֮ me֤lekĕ ha⁠ká̇֫b֥wòd yĕ֭hwáh ʻiż֣ẇz wĕ⁠giḃ֑wòr yĕ֝hwá֗h gi̇ḃ֥wòr milĕẖámáֽh׃"],[24,9,"שְׂא֤וּ שְׁעָרִ֨ים ׀ רָֽאשֵׁי⁠כֶ֗ם וּ֭⁠שְׂאוּ פִּתְחֵ֣י עוֹלָ֑ם וְ֝⁠יָבֹא מֶ֣לֶךְ הַ⁠כָּבֽוֹד׃","şĕ̂ʼ֤ẇ şĕ̌ʻári֨ym ׀ ráֽʼşé̌y⁠ke֗m ẇ֭⁠şĕ̂ʼẇ pi̇ţĕẖé֣y ʻwòlá֑m wĕ֝⁠yábòʼ me֣lekĕ ha⁠ká̇bֽwòd׃"],[24,10,"מִ֤י ה֣וּא זֶה֮ מֶ֤לֶךְ הַ⁠כָּ֫ב֥וֹד יְהוָ֥ה צְבָא֑וֹת ה֤וּא מֶ֖לֶךְ הַ⁠כָּב֣וֹד סֶֽלָה׃","mi֤y h֣ẇʼ zeh֮ me֤lekĕ ha⁠ká̇֫b֥wòd yĕhwá֥h ẕĕbáʼ֑wòţ h֤ẇʼ me֖lekĕ ha⁠ká̇b֣wòd seֽláh׃"],[25,1,"לְ⁠דָוִ֡ד אֵלֶ֥י⁠ךָ יְ֝הוָ֗ה נַפְשִׁ֥⁠י אֶשָּֽׂא׃","lĕ⁠dáwi֡d ʼéle֥y⁠ká yĕ֝hwá֗h napĕşǐ֥⁠y ʼeşáֽ̇̂ʼ׃"],[25,2,"אֱֽלֹהַ֗⁠י בְּ⁠ךָ֣ בָ֭טַחְתִּי אַל־אֵב֑וֹשָׁה אַל־יַֽעַלְצ֖וּ אֹיְבַ֣⁠י לִֽ⁠י׃","ʼèֽlòha֗⁠y bĕ̇⁠ká֣ bá֭taẖĕţi̇y ʼal-ʼéb֑wòşá̌h ʼal-yaֽʻalĕẕ֖ẇ ʼòyĕba֣⁠y liֽ⁠y׃"],[25,3,"גַּ֣ם כָּל־קֹ֭וֶי⁠ךָ לֹ֣א יֵבֹ֑שׁוּ יֵ֝בֹ֗שׁוּ הַ⁠בּוֹגְדִ֥ים רֵיקָֽם׃","gȧ֣m ká̇l-qò֭wey⁠ká lò֣ʼ yébò֑ş̌ẇ yé֝bò֗ş̌ẇ ha⁠ḃwògĕdi֥ym réyqáֽm׃"],[25,4,"דְּרָכֶ֣י⁠ךָ יְ֭הוָה הוֹדִיעֵ֑⁠נִי אֹ֖רְחוֹתֶ֣י⁠ךָ לַמְּדֵֽ⁠נִי׃","dĕ̇ráke֣y⁠ká yĕ֭hwáh hwòdiyʻé֑⁠niy ʼò֖rĕẖwòţe֣y⁠ká lamĕ̇déֽ⁠niy׃"],[25,5,"הַדְרִ֘יכֵ֤⁠נִי בַ⁠אֲמִתֶּ֨⁠ךָ ׀ וְֽ⁠לַמְּדֵ֗⁠נִי כִּֽי־אַ֭תָּה אֱלֹהֵ֣י יִשְׁעִ֑⁠י אוֹתְ⁠ךָ֥ קִ֝וִּ֗יתִי כָּל־הַ⁠יּֽוֹם׃","hadĕri֘yké֤⁠niy ba⁠ʼàmiţė֨⁠ká ׀ wĕֽ⁠lamĕ̇dé֗⁠niy kiֽ̇y-ʼa֭ţá̇h ʼèlòhé֣y yişĕ̌ʻi֑⁠y ʼwòţĕ⁠ká֥ qi֝wi̇֗yţiy ká̇l-ha⁠ẏֽwòm׃"],[25,6,"זְכֹר־רַחֲמֶ֣י⁠ךָ יְ֭הוָה וַ⁠חֲסָדֶ֑י⁠ךָ כִּ֖י מֵ⁠עוֹלָ֣ם הֵֽמָּה׃","zĕkòr-raẖàme֣y⁠ká yĕ֭hwáh wa⁠ẖàsáde֑y⁠ká ki֖̇y mé⁠ʻwòlá֣m héֽmá̇h׃"],[25,7,"חַטֹּ֤אות נְעוּרַ֨⁠י ׀ וּ⁠פְשָׁעַ֗⁠י אַל־תִּ֫זְכֹּ֥ר כְּ⁠חַסְדְּ⁠ךָ֥ זְכָר־לִ⁠י־אַ֑תָּה לְמַ֖עַן טוּבְ⁠ךָ֣ יְהוָֽה׃","ẖatò֤̇ʼwţ nĕʻẇra֨⁠y ׀ ẇ⁠pĕşá̌ʻa֗⁠y ʼal-ţi̇֫zĕkò֥̇r kĕ̇⁠ẖasĕdĕ̇⁠ká֥ zĕkár-li⁠y-ʼa֑ţá̇h lĕma֖ʻan tẇbĕ⁠ká֣ yĕhwáֽh׃"],[25,8,"טוֹב־וְ⁠יָשָׁ֥ר יְהוָ֑ה עַל־כֵּ֤ן יוֹרֶ֖ה חַטָּאִ֣ים בַּ⁠דָּֽרֶךְ׃","twòb-wĕ⁠yáşá֥̌r yĕhwá֑h ʻal-ké֤̇n ywòre֖h ẖatá̇ʼi֣ym bȧ⁠dáֽ̇rekĕ׃"],[25,9,"יַדְרֵ֣ךְ עֲ֭נָוִים בַּ⁠מִּשְׁפָּ֑ט וִֽ⁠ילַמֵּ֖ד עֲנָוִ֣ים דַּרְכּֽ⁠וֹ׃","yadĕré֣kĕ ʻà֭náwiym bȧ⁠mi̇şĕ̌pá֑̇t wiֽ⁠ylamé֖̇d ʻànáwi֣ym dȧrĕkֽ̇⁠wò׃"],[25,10,"כָּל־אָרְח֣וֹת יְ֭הוָה חֶ֣סֶד וֶ⁠אֱמֶ֑ת לְ⁠נֹצְרֵ֥י בְ֝רִית֗⁠וֹ וְ⁠עֵדֹתָֽי⁠ו׃","ká̇l-ʼárĕẖ֣wòţ yĕ֭hwáh ẖe֣sed we⁠ʼème֑ţ lĕ⁠nòẕĕré֥y bĕ֝riyţ֗⁠wò wĕ⁠ʻédòţáֽy⁠w׃"],[25,11,"לְמַֽעַן־שִׁמְ⁠ךָ֥ יְהוָ֑ה וְֽ⁠סָלַחְתָּ֥ לַ֝⁠עֲוֺנִ֗⁠י כִּ֣י רַב־הֽוּא׃","lĕmaֽʻan-şǐmĕ⁠ká֥ yĕhwá֑h wĕֽ⁠sálaẖĕţá֥̇ la֝⁠ʻàwֺni֗⁠y ki֣̇y rab-hֽẇʼ׃"],[25,12,"מִי־זֶ֣ה הָ֭⁠אִישׁ יְרֵ֣א יְהוָ֑ה י֝וֹרֶ֗⁠נּוּ בְּ⁠דֶ֣רֶךְ יִבְחָֽר׃","miy-ze֣h há֭⁠ʼiyş̌ yĕré֣ʼ yĕhwá֑h y֝wòre֗⁠ṅẇ bĕ̇⁠de֣rekĕ yibĕẖáֽr׃"],[25,13,"נַ֭פְשׁ⁠וֹ בְּ⁠ט֣וֹב תָּלִ֑ין וְ֝⁠זַרְע֗⁠וֹ יִ֣ירַשׁ אָֽרֶץ׃","na֭pĕş̌⁠wò bĕ̇⁠t֣wòb ţá̇li֑yn wĕ֝⁠zarĕʻ֗⁠wò yi֣yraş̌ ʼáֽreẕ׃"],[25,14,"ס֣וֹד יְ֭הוָה לִ⁠ירֵאָ֑י⁠ו וּ֝⁠בְרִית֗⁠וֹ לְ⁠הוֹדִיעָֽ⁠ם׃","s֣wòd yĕ֭hwáh li⁠yréʼá֑y⁠w ẇ֝⁠bĕriyţ֗⁠wò lĕ⁠hwòdiyʻáֽ⁠m׃"],[25,15,"עֵינַ֣⁠י תָּ֭מִיד אֶל־יְהוָ֑ה כִּ֤י הֽוּא־יוֹצִ֖יא מֵ⁠רֶ֣שֶׁת רַגְלָֽ⁠י׃","ʻéyna֣⁠y ţá֭̇miyd ʼel-yĕhwá֑h ki֤̇y hֽẇʼ-ywòẕi֖yʼ mé⁠re֣şěţ ragĕláֽ⁠y׃"],[25,16,"פְּנֵה־אֵלַ֥⁠י וְ⁠חָנֵּ֑⁠נִי כִּֽי־יָחִ֖יד וְ⁠עָנִ֣י אָֽנִי׃","pĕ̇néh-ʼéla֥⁠y wĕ⁠ẖáné֑̇⁠niy kiֽ̇y-yáẖi֖yd wĕ⁠ʻáni֣y ʼáֽniy׃"],[25,17,"צָר֣וֹת לְבָבִ֣⁠י הִרְחִ֑יבוּ מִ֝⁠מְּצֽוּקוֹתַ֗⁠י הוֹצִיאֵֽ⁠נִי׃","ẕár֣wòţ lĕbábi֣⁠y hirĕẖi֑ybẇ mi֝⁠mĕ̇ẕֽẇqwòţa֗⁠y hwòẕiyʼéֽ⁠niy׃"],[25,18,"רְאֵ֣ה עָ֭נְיִ⁠י וַ⁠עֲמָלִ֑⁠י וְ֝⁠שָׂ֗א לְ⁠כָל־חַטֹּאותָֽ⁠י׃","rĕʼé֣h ʻá֭nĕyi⁠y wa⁠ʻàmáli֑⁠y wĕ֝⁠şá̂֗ʼ lĕ⁠kál-ẖatò̇ʼwţáֽ⁠y׃"],[25,19,"רְאֵֽה־אוֹיְבַ֥⁠י כִּי־רָ֑בּוּ וְ⁠שִׂנְאַ֖ת חָמָ֣ס שְׂנֵאֽוּ⁠נִי׃","rĕʼéֽh-ʼwòyĕba֥⁠y ki̇y-rá֑ḃẇ wĕ⁠şînĕʼa֖ţ ẖámá֣s şĕ̂néʼֽẇ⁠niy׃"],[25,20,"שָׁמְרָ֣⁠ה נַ֭פְשִׁ⁠י וְ⁠הַצִּילֵ֑⁠נִי אַל־אֵ֝ב֗וֹשׁ כִּֽי־חָסִ֥יתִי בָֽ⁠ךְ׃","şá̌mĕrá֣⁠h na֭pĕşǐ⁠y wĕ⁠haẕi̇ylé֑⁠niy ʼal-ʼé֝b֗wòş̌ kiֽ̇y-ẖási֥yţiy báֽ⁠kĕ׃"],[25,21,"תֹּם־וָ⁠יֹ֥שֶׁר יִצְּר֑וּ⁠נִי כִּ֝֗י קִוִּיתִֽי⁠ךָ׃","ţò̇m-wá⁠yò֥şěr yiẕĕ̇r֑ẇ⁠niy ki̇֝֗y qiwi̇yţiֽy⁠ká׃"],[25,22,"פְּדֵ֣ה אֱ֭לֹהִים אֶת־יִשְׂרָאֵ֑ל מִ֝⁠כֹּ֗ל צָֽרוֹתָי⁠ו׃","pĕ̇dé֣h ʼè֭lòhiym ʼeţ-yişĕ̂ráʼé֑l mi֝⁠kò̇֗l ẕáֽrwòţáy⁠w׃"],[26,1,"לְ⁠דָוִ֨ד ׀ שָׁפְטֵ֤⁠נִי יְהוָ֗ה כִּֽי־אֲ֭נִי בְּ⁠תֻמִּ֣⁠י הָלַ֑כְתִּי וּ⁠בַ⁠יהוָ֥ה בָּ֝טַ֗חְתִּי לֹ֣א אֶמְעָֽד׃","lĕ⁠dáwi֨d ׀ şá̌pĕté֤⁠niy yĕhwá֗h kiֽ̇y-ʼà֭niy bĕ̇⁠ţumi֣̇⁠y hála֑kĕţi̇y ẇ⁠ba⁠yhwá֥h bá̇֝ta֗ẖĕţi̇y lò֣ʼ ʼemĕʻáֽd׃"],[26,2,"בְּחָנֵ֣⁠נִי יְהוָ֣ה וְ⁠נַסֵּ֑⁠נִי צרופ⁠ה כִלְיוֹתַ֣⁠י וְ⁠לִבִּֽ⁠י׃","bĕ̇ẖáné֣⁠niy yĕhwá֣h wĕ⁠nasé֑̇⁠niy ẕrwp⁠h kilĕywòţa֣⁠y wĕ⁠libiֽ̇⁠y׃"],[26,3,"כִּֽי־חַ֭סְדְּ⁠ךָ לְ⁠נֶ֣גֶד עֵינָ֑⁠י וְ֝⁠הִתְהַלַּ֗כְתִּי בַּ⁠אֲמִתֶּֽ⁠ךָ׃","kiֽ̇y-ẖa֭sĕdĕ̇⁠ká lĕ⁠ne֣ged ʻéyná֑⁠y wĕ֝⁠hiţĕhalȧ֗kĕţi̇y bȧ⁠ʼàmiţėֽ⁠ká׃"],[26,4,"לֹא־יָ֭שַׁבְתִּי עִם־מְתֵי־שָׁ֑וְא וְ⁠עִ֥ם נַ֝עֲלָמִ֗ים לֹ֣א אָבֽוֹא׃","lòʼ-yá֭şǎbĕţi̇y ʻim-mĕţéy-şá֑̌wĕʼ wĕ⁠ʻi֥m na֝ʻàlámi֗ym lò֣ʼ ʼábֽwòʼ׃"],[26,5,"שָׂ֭נֵאתִי קְהַ֣ל מְרֵעִ֑ים וְ⁠עִם־רְ֝שָׁעִ֗ים לֹ֣א אֵשֵֽׁב׃","şá֭̂néʼţiy qĕha֣l mĕréʻi֑ym wĕ⁠ʻim-rĕ֝şá̌ʻi֗ym lò֣ʼ ʼéşéֽ̌b׃"],[26,6,"אֶרְחַ֣ץ בְּ⁠נִקָּי֣וֹן כַּפָּ֑⁠י וַ⁠אֲסֹבְבָ֖ה אֶת־מִזְבַּחֲ⁠ךָ֣ יְהוָֽה׃","ʼerĕẖa֣ẕ bĕ̇⁠niqá̇y֣wòn kȧpá֑̇⁠y wa⁠ʼàsòbĕbá֖h ʼeţ-mizĕbȧẖà⁠ká֣ yĕhwáֽh׃"],[26,7,"לַ֭⁠שְׁמִעַ בְּ⁠ק֣וֹל תּוֹדָ֑ה וּ֝⁠לְ⁠סַפֵּ֗ר כָּל־נִפְלְאוֹתֶֽי⁠ךָ׃","la֭⁠şĕ̌miʻa bĕ̇⁠q֣wòl ţ̇wòdá֑h ẇ֝⁠lĕ⁠sapé̇֗r ká̇l-nipĕlĕʼwòţeֽy⁠ká׃"],[26,8,"יְֽהוָ֗ה אָ֭הַבְתִּי מְע֣וֹן בֵּיתֶ֑⁠ךָ וּ֝⁠מְק֗וֹם מִשְׁכַּ֥ן כְּבוֹדֶֽ⁠ךָ׃","yĕֽhwá֗h ʼá֭habĕţi̇y mĕʻ֣wòn bé̇yţe֑⁠ká ẇ֝⁠mĕq֗wòm mişĕ̌kȧ֥n kĕ̇bwòdeֽ⁠ká׃"],[26,9,"אַל־תֶּאֱסֹ֣ף עִם־חַטָּאִ֣ים נַפְשִׁ֑⁠י וְ⁠עִם־אַנְשֵׁ֖י דָמִ֣ים חַיָּֽ⁠י׃","ʼal-ţėʼèsò֣p ʻim-ẖatá̇ʼi֣ym napĕşǐ֑⁠y wĕ⁠ʻim-ʼanĕşé֖̌y dámi֣ym ẖayáֽ̇⁠y׃"],[26,10,"אֲשֶׁר־בִּ⁠ידֵי⁠הֶ֥ם זִמָּ֑ה וִֽ֝⁠ימִינָ֗⁠ם מָ֣לְאָה שֹּֽׁחַד׃","ʼàşěr-bi̇⁠ydéy⁠he֥m zimá֑̇h wiֽ֝⁠ymiyná֗⁠m má֣lĕʼáh şòֽ̇̌ẖad׃"],[26,11,"וַ֭⁠אֲנִי בְּ⁠תֻמִּ֥⁠י אֵלֵ֗ךְ פְּדֵ֣⁠נִי וְ⁠חָנֵּֽ⁠נִי׃","wa֭⁠ʼàniy bĕ̇⁠ţumi֥̇⁠y ʼélé֗kĕ pĕ̇dé֣⁠niy wĕ⁠ẖánéֽ̇⁠niy׃"],[26,12,"רַ֭גְלִ⁠י עָֽמְדָ֣ה בְ⁠מִישׁ֑וֹר בְּ֝⁠מַקְהֵלִ֗ים אֲבָרֵ֥ךְ יְהוָֽה׃","ra֭gĕli⁠y ʻáֽmĕdá֣h bĕ⁠miyş֑̌wòr bĕ̇֝⁠maqĕhéli֗ym ʼàbáré֥kĕ yĕhwáֽh׃"],[27,1,"לְ⁠דָוִ֨ד ׀ יְהוָ֤ה ׀ אוֹרִ֣⁠י וְ֭⁠יִשְׁעִ⁠י מִ⁠מִּ֣י אִירָ֑א יְהוָ֥ה מָֽעוֹז־חַ֝יַּ֗⁠י מִ⁠מִּ֥י אֶפְחָֽד׃","lĕ⁠dáwi֨d ׀ yĕhwá֤h ׀ ʼwòri֣⁠y wĕ֭⁠yişĕ̌ʻi⁠y mi⁠mi֣̇y ʼiyrá֑ʼ yĕhwá֥h máֽʻwòz-ẖa֝yȧ֗⁠y mi⁠mi֥̇y ʼepĕẖáֽd׃"],[27,2,"בִּ⁠קְרֹ֤ב עָלַ֨⁠י ׀ מְרֵעִים֮ לֶ⁠אֱכֹ֪ל אֶת־בְּשָׂ֫רִ֥⁠י צָרַ֣⁠י וְ⁠אֹיְבַ֣⁠י לִ֑⁠י הֵ֖מָּה כָשְׁל֣וּ וְ⁠נָפָֽלוּ׃","bi̇⁠qĕrò֤b ʻála֨⁠y ׀ mĕréʻiym֮ le⁠ʼèkò֪l ʼeţ-bĕ̇şá̂֫ri֥⁠y ẕára֣⁠y wĕ⁠ʼòyĕba֣⁠y li֑⁠y hé֖má̇h káşĕ̌l֣ẇ wĕ⁠nápáֽlẇ׃"],[27,3,"אִם־תַּחֲנֶ֬ה עָלַ֨⁠י ׀ מַחֲנֶה֮ לֹֽא־יִירָ֪א לִ֫בִּ֥⁠י אִם־תָּק֣וּם עָ֭לַ⁠י מִלְחָמָ֑ה בְּ֝⁠זֹ֗את אֲנִ֣י בוֹטֵֽחַ׃","ʼim-ţȧẖàne֬h ʻála֨⁠y ׀ maẖàneh֮ lòֽʼ-yiyrá֪ʼ li֫bi֥̇⁠y ʼim-ţá̇q֣ẇm ʻá֭la⁠y milĕẖámá֑h bĕ̇֝⁠zò֗ʼţ ʼàni֣y bwòtéֽẖa׃"],[27,4,"אַחַ֤ת ׀ שָׁאַ֣לְתִּי מֵֽ⁠אֵת־יְהוָה֮ אוֹתָ֪⁠הּ אֲבַ֫קֵּ֥שׁ שִׁבְתִּ֣⁠י בְּ⁠בֵית־יְ֭הוָה כָּל־יְמֵ֣י חַיַּ֑⁠י לַ⁠חֲז֥וֹת בְּ⁠נֹֽעַם־יְ֝הוָ֗ה וּ⁠לְ⁠בַקֵּ֥ר בְּ⁠הֵיכָלֽ⁠וֹ׃","ʼaẖa֤ţ ׀ şá̌ʼa֣lĕţi̇y méֽ⁠ʼéţ-yĕhwáh֮ ʼwòţá֪⁠ḣ ʼàba֫qé֥̇ş̌ şǐbĕţi֣̇⁠y bĕ̇⁠béyţ-yĕ֭hwáh ká̇l-yĕmé֣y ẖayȧ֑⁠y la⁠ẖàz֥wòţ bĕ̇⁠nòֽʻam-yĕ֝hwá֗h ẇ⁠lĕ⁠baqé֥̇r bĕ̇⁠héykálֽ⁠wò׃"],[27,5,"כִּ֤י יִצְפְּנֵ֨⁠נִי ׀ בְּ⁠סֻכֹּ⁠ה֮ בְּ⁠י֪וֹם רָ֫עָ֥ה יַ֭סְתִּרֵ⁠נִי בְּ⁠סֵ֣תֶר אָהֳל֑⁠וֹ בְּ֝⁠צ֗וּר יְרוֹמְמֵֽ⁠נִי׃","ki֤̇y yiẕĕpĕ̇né֨⁠niy ׀ bĕ̇⁠sukò̇⁠h֮ bĕ̇⁠y֪wòm rá֫ʻá֥h ya֭sĕţi̇ré⁠niy bĕ̇⁠sé֣ţer ʼáhol֑⁠wò bĕ̇֝⁠ẕ֗ẇr yĕrwòmĕméֽ⁠niy׃"],[27,6,"וְ⁠עַתָּ֨ה יָר֪וּם רֹאשִׁ֡⁠י עַ֤ל אֹֽיְבַ֬⁠י סְֽבִיבוֹתַ֗⁠י וְ⁠אֶזְבְּחָ֣ה בְ֭⁠אָהֳל⁠וֹ זִבְחֵ֣י תְרוּעָ֑ה אָשִׁ֥ירָה וַ֝⁠אֲזַמְּרָ֗ה לַ⁠יהוָֽה׃","wĕ⁠ʻaţá̇֨h yár֪ẇm ròʼşǐ֡⁠y ʻa֤l ʼòֽyĕba֬⁠y sĕֽbiybwòţa֗⁠y wĕ⁠ʼezĕbĕ̇ẖá֣h bĕ֭⁠ʼáhol⁠wò zibĕẖé֣y ţĕrẇʻá֑h ʼáşǐ֥yráh wa֝⁠ʼàzamĕ̇rá֗h la⁠yhwáֽh׃"],[27,7,"שְׁמַע־יְהוָ֖ה קוֹלִ֥⁠י אֶקְרָ֗א וְ⁠חָנֵּ֥⁠נִי וַ⁠עֲנֵֽ⁠נִי׃","şĕ̌maʻ-yĕhwá֖h qwòli֥⁠y ʼeqĕrá֗ʼ wĕ⁠ẖáné֥̇⁠niy wa⁠ʻànéֽ⁠niy׃"],[27,8,"לְ⁠ךָ֤ ׀ אָמַ֣ר לִ֭בִּ⁠י בַּקְּשׁ֣וּ פָנָ֑⁠י אֶת־פָּנֶ֖י⁠ךָ יְהוָ֣ה אֲבַקֵּֽשׁ׃","lĕ⁠ká֤ ׀ ʼáma֣r li֭bi̇⁠y bȧqĕ̇ş֣̌ẇ páná֑⁠y ʼeţ-pá̇ne֖y⁠ká yĕhwá֣h ʼàbaqéֽ̇ş̌׃"],[27,9,"אַל־תַּסְתֵּ֬ר פָּנֶ֨י⁠ךָ ׀ מִמֶּ⁠נִּי֮ אַֽל־תַּט־בְּ⁠אַ֗ף עַ֫בְדֶּ֥⁠ךָ עֶזְרָתִ֥⁠י הָיִ֑יתָ אַֽל־תִּטְּשֵׁ֥⁠נִי וְ⁠אַל־תַּֽ֝עַזְבֵ֗⁠נִי אֱלֹהֵ֥י יִשְׁעִֽ⁠י׃","ʼal-ţȧsĕţé̇֬r pá̇ne֨y⁠ká ׀ mimė⁠ni̇y֮ ʼaֽl-ţȧt-bĕ̇⁠ʼa֗p ʻa֫bĕdė֥⁠ká ʻezĕráţi֥⁠y háyi֑yţá ʼaֽl-ţi̇tĕ̇şé֥̌⁠niy wĕ⁠ʼal-ţȧֽ֝ʻazĕbé֗⁠niy ʼèlòhé֥y yişĕ̌ʻiֽ⁠y׃"],[27,10,"כִּי־אָבִ֣⁠י וְ⁠אִמִּ֣⁠י עֲזָב֑וּ⁠נִי וַֽ⁠יהוָ֣ה יַֽאַסְפֵֽ⁠נִי׃","ki̇y-ʼábi֣⁠y wĕ⁠ʼimi֣̇⁠y ʻàzáb֑ẇ⁠niy waֽ⁠yhwá֣h yaֽʼasĕpéֽ⁠niy׃"],[27,11,"ה֤וֹרֵ֥⁠נִי יְהוָ֗ה דַּ֫רְכֶּ֥⁠ךָ וּ֭⁠נְחֵ⁠נִי בְּ⁠אֹ֣רַח מִישׁ֑וֹר לְ֝מַ֗עַן שׁוֹרְרָֽ⁠י׃","h֤wòré֥⁠niy yĕhwá֗h dȧ֫rĕkė֥⁠ká ẇ֭⁠nĕẖé⁠niy bĕ̇⁠ʼò֣raẖ miyş֑̌wòr lĕ֝ma֗ʻan ş̌wòrĕráֽ⁠y׃"],[27,12,"אַֽל־תִּ֭תְּנֵ⁠נִי בְּ⁠נֶ֣פֶשׁ צָרָ֑⁠י כִּ֥י קָֽמוּ־בִ֥⁠י עֵֽדֵי־שֶׁ֝֗קֶר וִ⁠יפֵ֥חַ חָמָֽס׃","ʼaֽl-ţi֭̇ţĕ̇né⁠niy bĕ̇⁠ne֣peş̌ ẕárá֑⁠y ki֥̇y qáֽmẇ-bi֥⁠y ʻéֽdéy-şě֝֗qer wi⁠ypé֥ẖa ẖámáֽs׃"],[27,13,"לׅׄוּלֵׅׄ֗אׅׄ הֶ֭אֱמַנְתִּי לִ⁠רְא֥וֹת בְּֽ⁠טוּב־יְהוָ֗ה בְּ⁠אֶ֣רֶץ חַיִּֽים׃","lׅׄẇléׅׄ֗ʼׅׄ he֭ʼèmanĕţi̇y li⁠rĕʼ֥wòţ bĕֽ̇⁠tẇb-yĕhwá֗h bĕ̇⁠ʼe֣reẕ ẖayiֽ̇ym׃"],[27,14,"קַוֵּ֗ה אֶל־יְה֫וָ֥ה חֲ֭זַק וְ⁠יַאֲמֵ֣ץ לִבֶּ֑⁠ךָ וְ֝⁠קַוֵּ֗ה אֶל־יְהוָֽה׃","qawé̇֗h ʼel-yĕh֫wá֥h ẖà֭zaq wĕ⁠yaʼàmé֣ẕ libė֑⁠ká wĕ֝⁠qawé̇֗h ʼel-yĕhwáֽh׃"],[28,1,"לְ⁠דָוִ֡ד אֵ֘לֶ֤י⁠ךָ יְהוָ֨ה ׀ אֶקְרָ֗א צוּרִ⁠י֮ אַֽל־תֶּחֱרַ֪שׁ מִ֫מֶּ֥⁠נִּי פֶּן־תֶּֽחֱשֶׁ֥ה מִמֶּ֑⁠נִּי וְ֝⁠נִמְשַׁ֗לְתִּי עִם־י֥וֹרְדֵי בֽוֹר׃","lĕ⁠dáwi֡d ʼé֘le֤y⁠ká yĕhwá֨h ׀ ʼeqĕrá֗ʼ ẕẇri⁠y֮ ʼaֽl-ţėẖèra֪ş̌ mi֫mė֥⁠ni̇y pėn-ţėֽẖèşě֥h mimė֑⁠ni̇y wĕ֝⁠nimĕşǎ֗lĕţi̇y ʻim-y֥wòrĕdéy bֽwòr׃"],[28,2,"שְׁמַ֤ע ק֣וֹל תַּ֭חֲנוּנַ⁠י בְּ⁠שַׁוְּעִ֣⁠י אֵלֶ֑י⁠ךָ בְּ⁠נָשְׂאִ֥⁠י יָ֝דַ֗⁠י אֶל־דְּבִ֥יר קָדְשֶֽׁ⁠ךָ׃","şĕ̌ma֤ʻ q֣wòl ţȧ֭ẖànẇna⁠y bĕ̇⁠şǎwĕ̇ʻi֣⁠y ʼéle֑y⁠ká bĕ̇⁠náşĕ̂ʼi֥⁠y yá֝da֗⁠y ʼel-dĕ̇bi֥yr qádĕşěֽ⁠ká׃"],[28,3,"אַל־תִּמְשְׁכֵ֣⁠נִי עִם־רְשָׁעִים֮ וְ⁠עִם־פֹּ֪עֲלֵ֫י אָ֥וֶן דֹּבְרֵ֣י שָׁ֭לוֹם עִם־רֵֽעֵי⁠הֶ֑ם וְ֝⁠רָעָ֗ה בִּ⁠לְבָבָֽ⁠ם׃","ʼal-ţi̇mĕşĕ̌ké֣⁠niy ʻim-rĕşá̌ʻiym֮ wĕ⁠ʻim-pò֪̇ʻàlé֫y ʼá֥wen dò̇bĕré֣y şá֭̌lwòm ʻim-réֽʻéy⁠he֑m wĕ֝⁠ráʻá֗h bi̇⁠lĕbábáֽ⁠m׃"],[28,4,"תֶּן־לָ⁠הֶ֣ם כְּ⁠פָעֳלָ⁠ם֮ וּ⁠כְ⁠רֹ֪עַ מַֽעַלְלֵ֫י⁠הֶ֥ם כְּ⁠מַעֲשֵׂ֣ה יְ֭דֵי⁠הֶם תֵּ֣ן לָ⁠הֶ֑ם הָשֵׁ֖ב גְּמוּלָ֣⁠ם לָ⁠הֶֽם׃","ţėn-lá⁠he֣m kĕ̇⁠páʻolá⁠m֮ ẇ⁠kĕ⁠rò֪ʻa maֽʻalĕlé֫y⁠he֥m kĕ̇⁠maʻàşé֣̂h yĕ֭déy⁠hem ţé֣̇n lá⁠he֑m háşé֖̌b gĕ̇mẇlá֣⁠m lá⁠heֽm׃"],[28,5,"כִּ֤י לֹ֤א יָבִ֡ינוּ אֶל־פְּעֻלֹּ֣ת יְ֭הוָה וְ⁠אֶל־מַעֲשֵׂ֣ה יָדָ֑י⁠ו יֶ֝הֶרְסֵ֗⁠ם וְ⁠לֹ֣א יִבְנֵֽ⁠ם׃","ki֤̇y lò֤ʼ yábi֡ynẇ ʼel-pĕ̇ʻulò֣̇ţ yĕ֭hwáh wĕ⁠ʼel-maʻàşé֣̂h yádá֑y⁠w ye֝herĕsé֗⁠m wĕ⁠lò֣ʼ yibĕnéֽ⁠m׃"],[28,6,"בָּר֥וּךְ יְהוָ֑ה כִּי־שָׁ֝מַע ק֣וֹל תַּחֲנוּנָֽ⁠י׃","bá̇r֥ẇkĕ yĕhwá֑h ki̇y-şá̌֝maʻ q֣wòl ţȧẖànẇnáֽ⁠y׃"],[28,7,"יְהוָ֤ה ׀ עֻזִּ֥⁠י וּ⁠מָגִנִּ⁠י֮ בּ֤⁠וֹ בָטַ֥ח לִבִּ֗⁠י וְֽ⁠נֶ֫עֱזָ֥רְתִּי וַ⁠יַּעֲלֹ֥ז לִבִּ֑⁠י וּֽ⁠מִ⁠שִּׁירִ֥⁠י אֲהוֹדֶֽ⁠נּוּ׃","yĕhwá֤h ׀ ʻuzi֥̇⁠y ẇ⁠mágini̇⁠y֮ ḃ֤⁠wò báta֥ẖ libi̇֗⁠y wĕֽ⁠ne֫ʻèzá֥rĕţi̇y wa⁠yȧʻàlò֥z libi֑̇⁠y ẇֽ⁠mi⁠şi̇̌yri֥⁠y ʼàhwòdeֽ⁠ṅẇ׃"],[28,8,"יְהוָ֥ה עֹֽז־לָ֑⁠מוֹ וּ⁠מָ֘ע֤וֹז יְשׁוּע֖וֹת מְשִׁיח֣⁠וֹ הֽוּא׃","yĕhwá֥h ʻòֽz-lá֑⁠mwò ẇ⁠má֘ʻ֤wòz yĕş̌ẇʻ֖wòţ mĕşǐyẖ֣⁠wò hֽẇʼ׃"],[28,9,"הוֹשִׁ֤יעָ⁠ה ׀ אֶת־עַמֶּ֗⁠ךָ וּ⁠בָרֵ֥ךְ אֶת־נַחֲלָתֶ֑⁠ךָ וּֽ⁠רְעֵ֥⁠ם וְ֝⁠נַשְּׂאֵ֗⁠ם עַד־הָ⁠עוֹלָֽם׃","hwòşǐ֤yʻá⁠h ׀ ʼeţ-ʻamė֗⁠ká ẇ⁠báré֥kĕ ʼeţ-naẖàláţe֑⁠ká ẇֽ⁠rĕʻé֥⁠m wĕ֝⁠naşĕ̇̂ʼé֗⁠m ʻad-há⁠ʻwòláֽm׃"],[29,1,"מִזְמ֗וֹר לְ⁠דָ֫וִ֥ד הָב֣וּ לַֽ֭⁠יהוָה בְּנֵ֣י אֵלִ֑ים הָב֥וּ לַ֝⁠יהוָ֗ה כָּב֥וֹד וָ⁠עֹֽז׃","mizĕm֗wòr lĕ⁠dá֫wi֥d háb֣ẇ lֽa֭⁠yhwáh bĕ̇né֣y ʼéli֑ym háb֥ẇ la֝⁠yhwá֗h ká̇b֥wòd wá⁠ʻòֽz׃"],[29,2,"הָב֣וּ לַֽ֭⁠יהוָה כְּב֣וֹד שְׁמ֑⁠וֹ הִשְׁתַּחֲו֥וּ לַ֝⁠יהוָ֗ה בְּ⁠הַדְרַת־קֹֽדֶשׁ׃","háb֣ẇ laֽ֭⁠yhwáh kĕ̇b֣wòd şĕ̌m֑⁠wò hişĕ̌ţȧẖàw֥ẇ la֝⁠yhwá֗h bĕ̇⁠hadĕraţ-qòֽdeş̌׃"],[29,3,"ק֥וֹל יְהוָ֗ה עַל־הַ֫⁠מָּ֥יִם אֵֽל־הַ⁠כָּב֥וֹד הִרְעִ֑ים יְ֝הוָ֗ה עַל־מַ֥יִם רַבִּֽים׃","q֥wòl yĕhwá֗h ʻal-ha֫⁠má֥̇yim ʼéֽl-ha⁠ká̇b֥wòd hirĕʻi֑ym yĕ֝hwá֗h ʻal-ma֥yim rabiֽ̇ym׃"],[29,4,"קוֹל־יְהוָ֥ה בַּ⁠כֹּ֑חַ ק֥וֹל יְ֝הוָ֗ה בֶּ⁠הָדָֽר׃","qwòl-yĕhwá֥h bȧ⁠kò֑̇ẖa q֥wòl yĕ֝hwá֗h bė⁠hádáֽr׃"],[29,5,"ק֣וֹל יְ֭הוָה שֹׁבֵ֣ר אֲרָזִ֑ים וַ⁠יְשַׁבֵּ֥ר יְ֝הוָ֗ה אֶת־אַרְזֵ֥י הַ⁠לְּבָנֽוֹן׃","q֣wòl yĕ֭hwáh şò̌bé֣r ʼàrázi֑ym wa⁠yĕşǎbé֥̇r yĕ֝hwá֗h ʼeţ-ʼarĕzé֥y ha⁠lĕ̇bánֽwòn׃"],[29,6,"וַ⁠יַּרְקִידֵ֥⁠ם כְּמוֹ־עֵ֑גֶל לְבָנ֥וֹן וְ֝⁠שִׂרְיֹ֗ן כְּמ֣וֹ בֶן־רְאֵמִֽים׃","wa⁠yȧrĕqiydé֥⁠m kĕ̇mwò-ʻé֑gel lĕbán֥wòn wĕ֝⁠şîrĕyò֗n kĕ̇m֣wò ben-rĕʼémiֽym׃"],[29,7,"קוֹל־יְהוָ֥ה חֹצֵ֗ב לַהֲב֥וֹת אֵֽשׁ׃","qwòl-yĕhwá֥h ẖòẕé֗b lahàb֥wòţ ʼéֽş̌׃"],[29,8,"ק֣וֹל יְ֭הוָה יָחִ֣יל מִדְבָּ֑ר יָחִ֥יל יְ֝הוָ֗ה מִדְבַּ֥ר קָדֵֽשׁ׃","q֣wòl yĕ֭hwáh yáẖi֣yl midĕbá֑̇r yáẖi֥yl yĕ֝hwá֗h midĕbȧ֥r qádéֽş̌׃"],[29,9,"ק֤וֹל יְהוָ֨ה ׀ יְחוֹלֵ֣ל אַיָּלוֹת֮ וַֽ⁠יֶּחֱשֹׂ֪ף יְעָ֫ר֥וֹת וּ⁠בְ⁠הֵיכָל֑⁠וֹ כֻּ֝לּ֗⁠וֹ אֹמֵ֥ר כָּבֽוֹד׃","q֤wòl yĕhwá֨h ׀ yĕẖwòlé֣l ʼayá̇lwòţ֮ waֽ⁠yėẖèşò֪̂p yĕʻá֫r֥wòţ ẇ⁠bĕ⁠héykál֑⁠wò ku̇֝l̇֗⁠wò ʼòmé֥r ká̇bֽwòd׃"],[29,10,"יְ֭הוָה לַ⁠מַּבּ֣וּל יָשָׁ֑ב וַ⁠יֵּ֥שֶׁב יְ֝הוָ֗ה מֶ֣לֶךְ לְ⁠עוֹלָֽם׃","yĕ֭hwáh la⁠mȧḃ֣ẇl yáşá֑̌b wa⁠yé֥̇şěb yĕ֝hwá֗h me֣lekĕ lĕ⁠ʻwòláֽm׃"],[29,11,"יְֽהוָ֗ה עֹ֭ז לְ⁠עַמּ֣⁠וֹ יִתֵּ֑ן יְהוָ֓ה ׀ יְבָרֵ֖ךְ אֶת־עַמּ֣⁠וֹ בַ⁠שָּׁלֽוֹם׃","yĕֽhwá֗h ʻò֭z lĕ⁠ʻaṁ֣⁠wò yiţé֑̇n yĕhwá֓h ׀ yĕbáré֖kĕ ʼeţ-ʻaṁ֣⁠wò ba⁠şá̇̌lֽwòm׃"],[30,1,"אֲרוֹמִמְ⁠ךָ֣ יְ֭הוָה כִּ֣י דִלִּיתָ֑⁠נִי וְ⁠לֹא־שִׂמַּ֖חְתָּ אֹיְבַ֣⁠י לִֽ⁠י׃","ʼàrwòmimĕ⁠ká֣ yĕ֭hwáh ki֣̇y dili̇yţá֑⁠niy wĕ⁠lòʼ-şîmȧ֖ẖĕţá̇ ʼòyĕba֣⁠y liֽ⁠y׃"],[30,2,"יְהוָ֥ה אֱלֹהָ֑⁠י שִׁוַּ֥עְתִּי אֵ֝לֶ֗י⁠ךָ וַ⁠תִּרְפָּאֵֽ⁠נִי׃","yĕhwá֥h ʼèlòhá֑⁠y şǐwȧ֥ʻĕţi̇y ʼé֝le֗y⁠ká wa⁠ţi̇rĕpá̇ʼéֽ⁠niy׃"],[30,3,"יְֽהוָ֗ה הֶֽעֱלִ֣יתָ מִן־שְׁא֣וֹל נַפְשִׁ֑⁠י חִ֝יִּיתַ֗⁠נִי מ⁠יורדי־בֽוֹר׃","yĕֽhwá֗h heֽʻèli֣yţá min-şĕ̌ʼ֣wòl napĕşǐ֑⁠y ẖi֝yi̇yţa֗⁠niy m⁠ywrdy-bֽwòr׃"],[30,4,"זַמְּר֣וּ לַ⁠יהוָ֣ה חֲסִידָ֑י⁠ו וְ֝⁠הוֹד֗וּ לְ⁠זֵ֣כֶר קָדְשֽׁ⁠וֹ׃","zamĕ̇r֣ẇ la⁠yhwá֣h ẖàsiydá֑y⁠w wĕ֝⁠hwòd֗ẇ lĕ⁠zé֣ker qádĕşֽ̌⁠wò׃"],[30,5,"כִּ֤י רֶ֨גַע ׀ בְּ⁠אַפּ⁠וֹ֮ חַיִּ֪ים בִּ⁠רְצ֫וֹנ֥⁠וֹ בָּ֭⁠עֶרֶב יָלִ֥ין בֶּ֗כִי וְ⁠לַ⁠בֹּ֥קֶר רִנָּֽה׃","ki֤̇y re֨gaʻ ׀ bĕ̇⁠ʼaṗ⁠wò֮ ẖayi֪̇ym bi̇⁠rĕẕ֫wòn֥⁠wò bá֭̇⁠ʻereb yáli֥yn bė֗kiy wĕ⁠la⁠bò֥̇qer rináֽ̇h׃"],[30,6,"וַ֭⁠אֲנִי אָמַ֣רְתִּי בְ⁠שַׁלְוִ֑⁠י בַּל־אֶמּ֥וֹט לְ⁠עוֹלָֽם׃","wa֭⁠ʼàniy ʼáma֣rĕţi̇y bĕ⁠şǎlĕwi֑⁠y bȧl-ʼeṁ֥wòt lĕ⁠ʻwòláֽm׃"],[30,7,"יְֽהוָ֗ה בִּ⁠רְצוֹנְ⁠ךָ֮ הֶעֱמַ֪דְתָּה לְֽ⁠הַרְרִ֫⁠י עֹ֥ז הִסְתַּ֥רְתָּ פָנֶ֗י⁠ךָ הָיִ֥יתִי נִבְהָֽל׃","yĕֽhwá֗h bi̇⁠rĕẕwònĕ⁠ká֮ heʻèma֪dĕţá̇h lĕֽ⁠harĕri֫⁠y ʻò֥z hisĕţȧ֥rĕţá̇ páne֗y⁠ká háyi֥yţiy nibĕháֽl׃"],[30,8,"אֵלֶ֣י⁠ךָ יְהוָ֣ה אֶקְרָ֑א וְ⁠אֶל־אֲ֝דֹנָ֗⁠י אֶתְחַנָּֽן׃","ʼéle֣y⁠ká yĕhwá֣h ʼeqĕrá֑ʼ wĕ⁠ʼel-ʼà֝dòná֗⁠y ʼeţĕẖanáֽ̇n׃"],[30,9,"מַה־בֶּ֥צַע בְּ⁠דָמִ⁠י֮ בְּ⁠רִדְתִּ֪⁠י אֶ֫ל־שָׁ֥חַת הֲ⁠יוֹדְ⁠ךָ֥ עָפָ֑ר הֲ⁠יַגִּ֥יד אֲמִתֶּֽ⁠ךָ׃","mah-bė֥ẕaʻ bĕ̇⁠dámi⁠y֮ bĕ̇⁠ridĕţi֪̇⁠y ʼe֫l-şá֥̌ẖaţ hà⁠ywòdĕ⁠ká֥ ʻápá֑r hà⁠yagi֥̇yd ʼàmiţėֽ⁠ká׃"],[30,10,"שְׁמַע־יְהוָ֥ה וְ⁠חָנֵּ֑⁠נִי יְ֝הוָה הֱֽיֵה־עֹזֵ֥ר לִֽ⁠י׃","şĕ̌maʻ-yĕhwá֥h wĕ⁠ẖáné֑̇⁠niy yĕ֝hwáh hèֽyéh-ʻòzé֥r liֽ⁠y׃"],[30,11,"הָפַ֣כְתָּ מִסְפְּדִ⁠י֮ לְ⁠מָח֪וֹל לִ֥⁠י פִּתַּ֥חְתָּ שַׂקִּ֑⁠י וַֽ⁠תְּאַזְּרֵ֥⁠נִי שִׂמְחָֽה׃","hápa֣kĕţá̇ misĕpĕ̇di⁠y֮ lĕ⁠máẖ֪wòl li֥⁠y pi̇ţȧ֥ẖĕţá̇ şâqi֑̇⁠y waֽ⁠ţĕ̇ʼazĕ̇ré֥⁠niy şîmĕẖáֽh׃"],[30,12,"לְמַ֤עַן ׀ יְזַמֶּרְ⁠ךָ֣ כָ֭בוֹד וְ⁠לֹ֣א יִדֹּ֑ם יְהוָ֥ה אֱ֝לֹהַ֗⁠י לְ⁠עוֹלָ֥ם אוֹדֶֽ⁠ךָּ׃","lĕma֤ʻan ׀ yĕzamėrĕ⁠ká֣ ká֭bwòd wĕ⁠lò֣ʼ yidò֑̇m yĕhwá֥h ʼè֝lòha֗⁠y lĕ⁠ʻwòlá֥m ʼwòdeֽ⁠ká̇׃"],[31,1,"בְּ⁠ךָ֖ יְהוָ֣ה חָ֭סִיתִי אַל־אֵב֣וֹשָׁה לְ⁠עוֹלָ֑ם בְּ⁠צִדְקָתְ⁠ךָ֥ פַלְּטֵֽ⁠נִי׃","bĕ̇⁠ká֖ yĕhwá֣h ẖá֭siyţiy ʼal-ʼéb֣wòşá̌h lĕ⁠ʻwòlá֑m bĕ̇⁠ẕidĕqáţĕ⁠ká֥ palĕ̇téֽ⁠niy׃"],[31,2,"הַטֵּ֤ה אֵלַ֨⁠י ׀ אָזְנְ⁠ךָ֮ מְהֵרָ֪ה הַצִּ֫ילֵ֥⁠נִי הֱיֵ֤ה לִ֨⁠י ׀ לְֽ⁠צוּר־מָ֭עוֹז לְ⁠בֵ֥ית מְצוּד֗וֹת לְ⁠הוֹשִׁיעֵֽ⁠נִי׃","haté֤̇h ʼéla֨⁠y ׀ ʼázĕnĕ⁠ká֮ mĕhérá֪h haẕi̇֫ylé֥⁠niy hèyé֤h li֨⁠y ׀ lĕֽ⁠ẕẇr-má֭ʻwòz lĕ⁠bé֥yţ mĕẕẇd֗wòţ lĕ⁠hwòşǐyʻéֽ⁠niy׃"],[31,3,"כִּֽי־סַלְעִ֣⁠י וּ⁠מְצוּדָתִ֣⁠י אָ֑תָּה וּ⁠לְמַ֥עַן שִׁ֝מְ⁠ךָ֗ תַּֽנְחֵ֥⁠נִי וּֽ⁠תְנַהֲלֵֽ⁠נִי׃","kiֽ̇y-salĕʻi֣⁠y ẇ⁠mĕẕẇdáţi֣⁠y ʼá֑ţá̇h ẇ⁠lĕma֥ʻan şǐ֝mĕ⁠ká֗ ţȧֽnĕẖé֥⁠niy ẇֽ⁠ţĕnahàléֽ⁠niy׃"],[31,4,"תּוֹצִיאֵ֗⁠נִי מֵ⁠רֶ֣שֶׁת ז֭וּ טָ֣מְנוּ לִ֑⁠י כִּֽי־אַ֝תָּה מָֽעוּזִּֽ⁠י׃","ţ̇wòẕiyʼé֗⁠niy mé⁠re֣şěţ z֭ẇ tá֣mĕnẇ li֑⁠y kiֽ̇y-ʼa֝ţá̇h máֽʻẇziֽ̇⁠y׃"],[31,5,"בְּ⁠יָדְ⁠ךָ֮ אַפְקִ֪יד ר֫וּחִ֥⁠י פָּדִ֖יתָה אוֹתִ֥⁠י יְהוָ֗ה אֵ֣ל אֱמֶֽת׃","bĕ̇⁠yádĕ⁠ká֮ ʼapĕqi֪yd r֫ẇẖi֥⁠y pá̇di֖yţáh ʼwòţi֥⁠y yĕhwá֗h ʼé֣l ʼèmeֽţ׃"],[31,6,"שָׂנֵ֗אתִי הַ⁠שֹּׁמְרִ֥ים הַבְלֵי־שָׁ֑וְא וַ֝⁠אֲנִ֗י אֶל־יְהוָ֥ה בָּטָֽחְתִּי׃","şá̂né֗ʼţiy ha⁠şò̇̌mĕri֥ym habĕléy-şá֑̌wĕʼ wa֝⁠ʼàni֗y ʼel-yĕhwá֥h bá̇táֽẖĕţi̇y׃"],[31,7,"אָגִ֥ילָה וְ⁠אֶשְׂמְחָ֗ה בְּ⁠חַ֫סְדֶּ֥⁠ךָ אֲשֶׁ֣ר רָ֭אִיתָ אֶת־עָנְיִ֑⁠י יָ֝דַ֗עְתָּ בְּ⁠צָר֥וֹת נַפְשִֽׁ⁠י׃","ʼági֥yláh wĕ⁠ʼeşĕ̂mĕẖá֗h bĕ̇⁠ẖa֫sĕdė֥⁠ká ʼàşě֣r rá֭ʼiyţá ʼeţ-ʻánĕyi֑⁠y yá֝da֗ʻĕţá̇ bĕ̇⁠ẕár֥wòţ napĕşǐֽ⁠y׃"],[31,8,"וְ⁠לֹ֣א הִ֭סְגַּרְתַּ⁠נִי בְּ⁠יַד־אוֹיֵ֑ב הֶֽעֱמַ֖דְתָּ בַ⁠מֶּרְחָ֣ב רַגְלָֽ⁠י׃","wĕ⁠lò֣ʼ hi֭sĕgȧrĕţȧ⁠niy bĕ̇⁠yad-ʼwòyé֑b heֽʻèma֖dĕţá̇ ba⁠mėrĕẖá֣b ragĕláֽ⁠y׃"],[31,9,"חָנֵּ֥⁠נִי יְהוָה֮ כִּ֤י צַ֫ר־לִ֥⁠י עָשְׁשָׁ֖ה בְ⁠כַ֥עַס עֵינִ֗⁠י נַפְשִׁ֥⁠י וּ⁠בִטְנִֽ⁠י׃","ẖáné֥̇⁠niy yĕhwáh֮ ki֤̇y ẕa֫r-li֥⁠y ʻáşĕ̌şá֖̌h bĕ⁠ka֥ʻas ʻéyni֗⁠y napĕşǐ֥⁠y ẇ⁠bitĕniֽ⁠y׃"],[31,10,"כִּ֤י כָל֪וּ בְ⁠יָג֡וֹן חַיַּ⁠י֮ וּ⁠שְׁנוֹתַ֪⁠י בַּ⁠אֲנָ֫חָ֥ה כָּשַׁ֣ל בַּ⁠עֲוֺנִ֣⁠י כֹחִ֑⁠י וַ⁠עֲצָמַ֥⁠י עָשֵֽׁשׁוּ׃","ki֤̇y kál֪ẇ bĕ⁠yág֡wòn ẖayȧ⁠y֮ ẇ⁠şĕ̌nwòţa֪⁠y bȧ⁠ʼàná֫ẖá֥h ká̇şǎ֣l bȧ⁠ʻàwֺni֣⁠y kòẖi֑⁠y wa⁠ʻàẕáma֥⁠y ʻáşéֽ̌ş̌ẇ׃"],[31,11,"מִ⁠כָּל־צֹרְרַ֨⁠י הָיִ֪יתִי חֶרְפָּ֡ה וְ⁠לִ⁠שֲׁכֵנַ֨⁠י ׀ מְאֹד֮ וּ⁠פַ֪חַד לִֽ⁠מְיֻדָּ֫עָ֥⁠י רֹאַ֥⁠י בַּ⁠ח֑וּץ נָדְד֥וּ מִמֶּֽ⁠נִּי׃","mi⁠ká̇l-ẕòrĕra֨⁠y háyi֪yţiy ẖerĕpá̇֡h wĕ⁠li⁠şà̌kéna֨⁠y ׀ mĕʼòd֮ ẇ⁠pa֪ẖad liֽ⁠mĕyudá̇֫ʻá֥⁠y ròʼa֥⁠y bȧ⁠ẖ֑ẇẕ nádĕd֥ẇ mimėֽ⁠ni̇y׃"],[31,12,"נִ֭שְׁכַּחְתִּי כְּ⁠מֵ֣ת מִ⁠לֵּ֑ב הָ֝יִ֗יתִי כִּ⁠כְלִ֥י אֹבֵֽד׃","ni֭şĕ̌kȧẖĕţi̇y kĕ̇⁠mé֣ţ mi⁠lé֑̇b há֝yi֗yţiy ki̇⁠kĕli֥y ʼòbéֽd׃"],[31,13,"כִּ֤י שָׁמַ֨עְתִּי ׀ דִּבַּ֥ת רַבִּים֮ מָג֪וֹר מִ⁠סָּ֫בִ֥יב בְּ⁠הִוָּסְדָ֣⁠ם יַ֣חַד עָלַ֑⁠י לָ⁠קַ֖חַת נַפְשִׁ֣⁠י זָמָֽמוּ׃","ki֤̇y şá̌ma֨ʻĕţi̇y ׀ di̇bȧ֥ţ rabi̇ym֮ mág֪wòr mi⁠sá̇֫bi֥yb bĕ̇⁠hiwá̇sĕdá֣⁠m ya֣ẖad ʻála֑⁠y lá⁠qa֖ẖaţ napĕşǐ֣⁠y zámáֽmẇ׃"],[31,14,"וַ⁠אֲנִ֤י ׀ עָלֶ֣י⁠ךָ בָטַ֣חְתִּי יְהוָ֑ה אָ֝מַ֗רְתִּי אֱלֹהַ֥⁠י אָֽתָּה׃","wa⁠ʼàni֤y ׀ ʻále֣y⁠ká báta֣ẖĕţi̇y yĕhwá֑h ʼá֝ma֗rĕţi̇y ʼèlòha֥⁠y ʼáֽţá̇h׃"],[31,15,"בְּ⁠יָדְ⁠ךָ֥ עִתֹּתָ֑⁠י הַצִּ֘ילֵ֤⁠נִי מִ⁠יַּד־א֝וֹיְבַ֗⁠י וּ⁠מֵ⁠רֹדְפָֽ⁠י׃","bĕ̇⁠yádĕ⁠ká֥ ʻiţò̇ţá֑⁠y haẕi̇֘ylé֤⁠niy mi⁠yȧd-ʼ֝wòyĕba֗⁠y ẇ⁠mé⁠ròdĕpáֽ⁠y׃"],[31,16,"הָאִ֣ירָ⁠ה פָ֭נֶי⁠ךָ עַל־עַבְדֶּ֑⁠ךָ ה֖וֹשִׁיעֵ֣⁠נִי בְ⁠חַסְדֶּֽ⁠ךָ׃","háʼi֣yrá⁠h pá֭ney⁠ká ʻal-ʻabĕdė֑⁠ká h֖wòşǐyʻé֣⁠niy bĕ⁠ẖasĕdėֽ⁠ká׃"],[31,17,"יְֽהוָ֗ה אַל־אֵ֭בוֹשָׁה כִּ֣י קְרָאתִ֑י⁠ךָ יֵבֹ֥שׁוּ רְ֝שָׁעִ֗ים יִדְּמ֥וּ לִ⁠שְׁאֽוֹל׃","yĕֽhwá֗h ʼal-ʼé֭bwòşá̌h ki֣̇y qĕráʼţi֑y⁠ká yébò֥ş̌ẇ rĕ֝şá̌ʻi֗ym yidĕ̇m֥ẇ li⁠şĕ̌ʼֽwòl׃"],[31,18,"תֵּ֥אָלַ֗מְנָה שִׂפְתֵ֫י שָׁ֥קֶר הַ⁠דֹּבְר֖וֹת עַל־צַדִּ֥יק עָתָ֗ק בְּ⁠גַאֲוָ֥ה וָ⁠בֽוּז׃","ţé֥̇ʼála֗mĕnáh şîpĕţé֫y şá֥̌qer ha⁠dò̇bĕr֖wòţ ʻal-ẕadi֥̇yq ʻáţá֗q bĕ̇⁠gaʼàwá֥h wá⁠bֽẇz׃"],[31,19,"מָ֤ה רַֽב־טוּבְ⁠ךָ֮ אֲשֶׁר־צָפַ֪נְתָּ לִּֽ⁠ירֵ֫אֶ֥י⁠ךָ פָּ֭עַלְתָּ לַ⁠חֹסִ֣ים בָּ֑⁠ךְ נֶ֝֗גֶד בְּנֵ֣י אָדָם׃","má֤h raֽb-tẇbĕ⁠ká֮ ʼàşěr-ẕápa֪nĕţá̇ liֽ̇⁠yré֫ʼe֥y⁠ká pá֭̇ʻalĕţá̇ la⁠ẖòsi֣ym bá֑̇⁠kĕ ne֝֗ged bĕ̇né֣y ʼádám׃"],[31,20,"תַּסְתִּירֵ֤⁠ם ׀ בְּ⁠סֵ֥תֶר פָּנֶי⁠ךָ֮ מֵֽ⁠רֻכְסֵ֫י אִ֥ישׁ תִּצְפְּנֵ֥⁠ם בְּ⁠סֻכָּ֗ה מֵ⁠רִ֥יב לְשֹׁנֽוֹת׃","ţȧsĕţi̇yré֤⁠m ׀ bĕ̇⁠sé֥ţer pá̇ney⁠ká֮ méֽ⁠rukĕsé֫y ʼi֥yş̌ ţi̇ẕĕpĕ̇né֥⁠m bĕ̇⁠suká̇֗h mé⁠ri֥yb lĕşò̌nֽwòţ׃"],[31,21,"בָּר֥וּךְ יְהוָ֑ה כִּ֥י הִפְלִ֘יא חַסְדּ֥⁠וֹ לִ֝֗⁠י בְּ⁠עִ֣יר מָצֽוֹר׃","bá̇r֥ẇkĕ yĕhwá֑h ki֥̇y hipĕli֘yʼ ẖasĕḋ֥⁠wò li֝֗⁠y bĕ̇⁠ʻi֣yr máẕֽwòr׃"],[31,22,"וַ⁠אֲנִ֤י ׀ אָ֘מַ֤רְתִּי בְ⁠חָפְזִ֗⁠י נִגְרַזְתִּי֮ מִ⁠נֶּ֪גֶד עֵ֫ינֶ֥י⁠ךָ אָכֵ֗ן שָׁ֭מַעְתָּ ק֥וֹל תַּחֲנוּנַ֗⁠י בְּ⁠שַׁוְּעִ֥⁠י אֵלֶֽי⁠ךָ׃","wa⁠ʼàni֤y ׀ ʼá֘ma֤rĕţi̇y bĕ⁠ẖápĕzi֗⁠y nigĕrazĕţi̇y֮ mi⁠nė֪ged ʻé֫yne֥y⁠ká ʼáké֗n şá֭̌maʻĕţá̇ q֥wòl ţȧẖànẇna֗⁠y bĕ̇⁠şǎwĕ̇ʻi֥⁠y ʼéleֽy⁠ká׃"],[31,23,"אֶֽהֱב֥וּ אֶת־יְהוָ֗ה כָּֽל־חֲסִ֫ידָ֥י⁠ו אֱ֭מוּנִים נֹצֵ֣ר יְהוָ֑ה וּ⁠מְשַׁלֵּ֥ם עַל־יֶ֝֗תֶר עֹשֵׂ֥ה גַאֲוָֽה׃","ʼֽehèb֥ẇ ʼeţ-yĕhwá֗h káֽ̇l-ẖàsi֫ydá֥y⁠w ʼè֭mẇniym nòẕé֣r yĕhwá֑h ẇ⁠mĕşǎlé֥̇m ʻal-ye֝֗ţer ʻòşé֥̂h gaʼàwáֽh׃"],[31,24,"חִ֭זְקוּ וְ⁠יַאֲמֵ֣ץ לְבַבְ⁠כֶ֑ם כָּל־הַ֝⁠מְיַחֲלִ֗ים לַ⁠יהוָֽה׃","ẖi֭zĕqẇ wĕ⁠yaʼàmé֣ẕ lĕbabĕ⁠ke֑m ká̇l-ha֝⁠mĕyaẖàli֗ym la⁠yhwáֽh׃"],[32,1,"לְ⁠דָוִ֗ד מַ֫שְׂכִּ֥יל אַשְׁרֵ֥י נְֽשׂוּי־פֶּ֗שַׁע כְּס֣וּי חֲטָאָֽה׃","lĕ⁠dáwi֗d ma֫şĕ̂ki֥̇yl ʼaşĕ̌ré֥y nĕֽş̂ẇy-pė֗şǎʻ kĕ̇s֣ẇy ẖàtáʼáֽh׃"],[32,2,"אַ֥שְֽׁרֵי אָדָ֗ם לֹ֤א יַחְשֹׁ֬ב יְהוָ֣ה ל֣⁠וֹ עָוֺ֑ן וְ⁠אֵ֖ין בְּ⁠רוּח֣⁠וֹ רְמִיָּה׃","ʼa֥şĕֽ̌réy ʼádá֗m lò֤ʼ yaẖĕşò̌֬b yĕhwá֣h l֣⁠wò ʻáwֺ֑n wĕ⁠ʼé֖yn bĕ̇⁠rẇẖ֣⁠wò rĕmiyá̇h׃"],[32,3,"כִּֽי־הֶ֭חֱרַשְׁתִּי בָּל֣וּ עֲצָמָ֑⁠י בְּ֝⁠שַׁאֲגָתִ֗⁠י כָּל־הַ⁠יּֽוֹם׃","kiֽ̇y-he֭ẖèraşĕ̌ţi̇y bá̇l֣ẇ ʻàẕámá֑⁠y bĕ̇֝⁠şǎʼàgáţi֗⁠y ká̇l-ha⁠ẏֽwòm׃"],[32,4,"כִּ֤י ׀ יוֹמָ֣ם וָ⁠לַיְלָה֮ תִּכְבַּ֥ד עָלַ֗⁠י יָ֫דֶ֥⁠ךָ נֶהְפַּ֥ךְ לְשַׁדִּ֑⁠י בְּ⁠חַרְבֹ֖נֵי קַ֣יִץ סֶֽלָה׃","ki֤̇y ׀ ywòmá֣m wá⁠layĕláh֮ ţi̇kĕbȧ֥d ʻála֗⁠y yá֫de֥⁠ká nehĕpȧ֥kĕ lĕşǎdi֑̇⁠y bĕ̇⁠ẖarĕbò֖néy qa֣yiẕ seֽláh׃"],[32,5,"חַטָּאתִ֨⁠י אוֹדִ֪יעֲ⁠ךָ֡ וַ⁠עֲוֺ֘נִ֤⁠י לֹֽא־כִסִּ֗יתִי אָמַ֗רְתִּי אוֹדֶ֤ה עֲלֵ֣י פְ֭שָׁעַ⁠י לַ⁠יהוָ֑ה וְ⁠אַתָּ֨ה נָ֘שָׂ֤אתָ עֲוֺ֖ן חַטָּאתִ֣⁠י סֶֽלָה׃","ẖatá̇ʼţi֨⁠y ʼwòdi֪yʻà⁠ká֡ wa⁠ʻàwֺ֘ni֤⁠y lòֽʼ-kisi̇֗yţiy ʼáma֗rĕţi̇y ʼwòde֤h ʻàlé֣y pĕ֭şá̌ʻa⁠y la⁠yhwá֑h wĕ⁠ʼaţá̇֨h ná֘şá֤̂ʼţá ʻàwֺ֖n ẖatá̇ʼţi֣⁠y seֽláh׃"],[32,6,"עַל־זֹ֡את יִתְפַּלֵּ֬ל כָּל־חָסִ֨יד ׀ אֵלֶי⁠ךָ֮ לְ⁠עֵ֪ת מְ֫צֹ֥א רַ֗ק לְ֭⁠שֵׁטֶף מַ֣יִם רַבִּ֑ים אֵ֝לָ֗י⁠ו לֹ֣א יַגִּֽיעוּ׃","ʻal-zò֡ʼţ yiţĕpȧlé̇֬l ká̇l-ẖási֨yd ׀ ʼéley⁠ká֮ lĕ⁠ʻé֪ţ mĕ֫ẕò֥ʼ ra֗q lĕ֭⁠şé̌tep ma֣yim rabi֑̇ym ʼé֝lá֗y⁠w lò֣ʼ yagiֽ̇yʻẇ׃"],[32,7,"אַתָּ֤ה ׀ סֵ֥תֶר לִ⁠י֮ מִ⁠צַּ֪ר תִּ֫צְּרֵ֥⁠נִי רָנֵּ֥י פַלֵּ֑ט תְּס֖וֹבְבֵ֣⁠נִי סֶֽלָה׃","ʼaţá֤̇h ׀ sé֥ţer li⁠y֮ mi⁠ẕȧ֪r ţi̇֫ẕĕ̇ré֥⁠niy ráné֥̇y palé֑̇t ţĕ̇s֖wòbĕbé֣⁠niy seֽláh׃"],[32,8,"אַשְׂכִּֽילְ⁠ךָ֨ ׀ וְֽ⁠אוֹרְ⁠ךָ֗ בְּ⁠דֶֽרֶךְ־ז֥וּ תֵלֵ֑ךְ אִֽיעֲצָ֖ה עָלֶ֣י⁠ךָ עֵינִֽ⁠י׃","ʼaşĕ̂kiֽ̇ylĕ⁠ká֨ ׀ wĕֽ⁠ʼwòrĕ⁠ká֗ bĕ̇⁠deֽrekĕ-z֥ẇ ţélé֑kĕ ʼiֽyʻàẕá֖h ʻále֣y⁠ká ʻéyniֽ⁠y׃"],[32,9,"אַל־תִּֽהְי֤וּ ׀ כְּ⁠ס֥וּס כְּ⁠פֶרֶד֮ אֵ֤ין הָ֫בִ֥ין בְּ⁠מֶֽתֶג־וָ⁠רֶ֣סֶן עֶדְי֣⁠וֹ לִ⁠בְל֑וֹם בַּ֝֗ל קְרֹ֣ב אֵלֶֽי⁠ךָ׃","ʼal-ţiֽ̇hĕy֤ẇ ׀ kĕ̇⁠s֥ẇs kĕ̇⁠pered֮ ʼé֤yn há֫bi֥yn bĕ̇⁠meֽţeg-wá⁠re֣sen ʻedĕy֣⁠wò li⁠bĕl֑wòm bȧ֝֗l qĕrò֣b ʼéleֽy⁠ká׃"],[32,10,"רַבִּ֥ים מַכְאוֹבִ֗ים לָ⁠רָ֫שָׁ֥ע וְ⁠הַ⁠בּוֹטֵ֥חַ בַּ⁠יהוָ֑ה חֶ֝֗סֶד יְסוֹבְבֶֽ⁠נּוּ׃","rabi֥̇ym makĕʼwòbi֗ym lá⁠rá֫şá֥̌ʻ wĕ⁠ha⁠ḃwòté֥ẖa bȧ⁠yhwá֑h ẖe֝֗sed yĕswòbĕbeֽ⁠ṅẇ׃"],[32,11,"שִׂמְח֬וּ בַֽ⁠יהוָ֣ה וְ֭⁠גִילוּ צַדִּיקִ֑ים וְ֝⁠הַרְנִ֗ינוּ כָּל־יִשְׁרֵי־לֵֽב׃","şîmĕẖ֬ẇ baֽ⁠yhwá֣h wĕ֭⁠giylẇ ẕadi̇yqi֑ym wĕ֝⁠harĕni֗ynẇ ká̇l-yişĕ̌réy-léֽb׃"],[33,1,"רַנְּנ֣וּ צַ֭דִּיקִים בַּֽ⁠יהוָ֑ה לַ֝⁠יְשָׁרִ֗ים נָאוָ֥ה תְהִלָּֽה׃","ranĕ̇n֣ẇ ẕa֭di̇yqiym bȧֽ⁠yhwá֑h la֝⁠yĕşá̌ri֗ym náʼwá֥h ţĕhiláֽ̇h׃"],[33,2,"הוֹד֣וּ לַ⁠יהוָ֣ה בְּ⁠כִנּ֑וֹר בְּ⁠נֵ֥בֶל עָ֝שׂ֗וֹר זַמְּרוּ־לֽ⁠וֹ׃","hwòd֣ẇ la⁠yhwá֣h bĕ̇⁠kiṅ֑wòr bĕ̇⁠né֥bel ʻá֝ş̂֗wòr zamĕ̇rẇ-lֽ⁠wò׃"],[33,3,"שִֽׁירוּ־ל֭⁠וֹ שִׁ֣יר חָדָ֑שׁ הֵיטִ֥יבוּ נַ֝גֵּ֗ן בִּ⁠תְרוּעָֽה׃","şǐֽyrẇ-l֭⁠wò şǐ֣yr ẖádá֑ş̌ héyti֥ybẇ na֝gé̇֗n bi̇⁠ţĕrẇʻáֽh׃"],[33,4,"כִּֽי־יָשָׁ֥ר דְּבַר־יְהוָ֑ה וְ⁠כָל־מַ֝עֲשֵׂ֗⁠הוּ בֶּ⁠אֱמוּנָֽה׃","kiֽ̇y-yáşá֥̌r dĕ̇bar-yĕhwá֑h wĕ⁠kál-ma֝ʻàşé̂֗⁠hẇ bė⁠ʼèmẇnáֽh׃"],[33,5,"אֹ֭הֵב צְדָקָ֣ה וּ⁠מִשְׁפָּ֑ט חֶ֥סֶד יְ֝הוָ֗ה מָלְאָ֥ה הָ⁠אָֽרֶץ׃","ʼò֭héb ẕĕdáqá֣h ẇ⁠mişĕ̌pá֑̇t ẖe֥sed yĕ֝hwá֗h málĕʼá֥h há⁠ʼáֽreẕ׃"],[33,6,"בִּ⁠דְבַ֣ר יְ֭הוָה שָׁמַ֣יִם נַעֲשׂ֑וּ וּ⁠בְ⁠ר֥וּחַ פִּ֝֗י⁠ו כָּל־צְבָאָֽ⁠ם׃","bi̇⁠dĕba֣r yĕ֭hwáh şá̌ma֣yim naʻàş֑̂ẇ ẇ⁠bĕ⁠r֥ẇẖa pi̇֝֗y⁠w ká̇l-ẕĕbáʼáֽ⁠m׃"],[33,7,"כֹּנֵ֣ס כַּ֭⁠נֵּד מֵ֣י הַ⁠יָּ֑ם נֹתֵ֖ן בְּ⁠אֹצָר֣וֹת תְּהוֹמֽוֹת׃","kò̇né֣s kȧ֭⁠né̇d mé֣y ha⁠yá֑̇m nòţé֖n bĕ̇⁠ʼòẕár֣wòţ ţĕ̇hwòmֽwòţ׃"],[33,8,"יִֽירְא֣וּ מֵ֭⁠יְהוָה כָּל־הָ⁠אָ֑רֶץ מִמֶּ֥⁠נּוּ יָ֝ג֗וּרוּ כָּל־יֹשְׁבֵ֥י תֵבֵֽל׃","yiֽyrĕʼ֣ẇ mé֭⁠yĕhwáh ká̇l-há⁠ʼá֑reẕ mimė֥⁠ṅẇ yá֝g֗ẇrẇ ká̇l-yòşĕ̌bé֥y ţébéֽl׃"],[33,9,"כִּ֤י ה֣וּא אָמַ֣ר וַ⁠יֶּ֑הִי הֽוּא־צִ֝וָּ֗ה וַֽ⁠יַּעֲמֹֽד׃","ki֤̇y h֣ẇʼ ʼáma֣r wa⁠yė֑hiy hֽẇʼ-ẕi֝wá̇֗h wֽa⁠yȧʻàmòֽd׃"],[33,10,"יְֽהוָ֗ה הֵפִ֥יר עֲצַת־גּוֹיִ֑ם הֵ֝נִ֗יא מַחְשְׁב֥וֹת עַמִּֽים׃","yĕֽhwá֗h hépi֥yr ʻàẕaţ-ġwòyi֑m hé֝ni֗yʼ maẖĕşĕ̌b֥wòţ ʻamiֽ̇ym׃"],[33,11,"עֲצַ֣ת יְ֭הוָה לְ⁠עוֹלָ֣ם תַּעֲמֹ֑ד מַחְשְׁב֥וֹת לִ֝בּ֗⁠וֹ לְ⁠דֹ֣ר וָ⁠דֹֽר׃","ʻàẕa֣ţ yĕ֭hwáh lĕ⁠ʻwòlá֣m ţȧʻàmò֑d maẖĕşĕ̌b֥wòţ li֝ḃ֗⁠wò lĕ⁠dò֣r wá⁠dòֽr׃"],[33,12,"אַשְׁרֵ֣י הַ֭⁠גּוֹי אֲשֶׁר־יְהוָ֣ה אֱלֹהָ֑י⁠ו הָ⁠עָ֓ם ׀ בָּחַ֖ר לְ⁠נַחֲלָ֣ה לֽ⁠וֹ׃","ʼaşĕ̌ré֣y ha֭⁠ġwòy ʼàşěr-yĕhwá֣h ʼèlòhá֑y⁠w há⁠ʻá֓m ׀ bá̇ẖa֖r lĕ⁠naẖàlá֣h lֽ⁠wò׃"],[33,13,"מִ֭⁠שָּׁמַיִם הִבִּ֣יט יְהוָ֑ה רָ֝אָ֗ה אֶֽת־כָּל־בְּנֵ֥י הָ⁠אָדָֽם׃","mi֭⁠şá̇̌mayim hibi֣̇yt yĕhwá֑h rá֝ʼá֗h ʼeֽţ-ká̇l-bĕ̇né֥y há⁠ʼádáֽm׃"],[33,14,"מִֽ⁠מְּכוֹן־שִׁבְתּ֥⁠וֹ הִשְׁגִּ֑יחַ אֶ֖ל כָּל־יֹשְׁבֵ֣י הָ⁠אָֽרֶץ׃","miֽ⁠mĕ̇kwòn-şǐbĕţ֥̇⁠wò hişĕ̌gi֑̇yẖa ʼe֖l ká̇l-yòşĕ̌bé֣y há⁠ʼáֽreẕ׃"],[33,15,"הַ⁠יֹּצֵ֣ר יַ֣חַד לִבָּ֑⁠ם הַ֝⁠מֵּבִ֗ין אֶל־כָּל־מַעֲשֵׂי⁠הֶֽם׃","ha⁠yò̇ẕé֣r ya֣ẖad libá֑̇⁠m ha֝⁠mé̇bi֗yn ʼel-ká̇l-maʻàşé̂y⁠heֽm׃"],[33,16,"אֵֽין־הַ֭⁠מֶּלֶךְ נוֹשָׁ֣ע בְּ⁠רָב־חָ֑יִל גִּ֝בּ֗וֹר לֹֽא־יִנָּצֵ֥ל בְּ⁠רָב־כֹּֽחַ׃","ʼéֽyn-ha֭⁠mėlekĕ nwòşá֣̌ʻ bĕ̇⁠ráb-ẖá֑yil gi̇֝ḃ֗wòr lòֽʼ-yiná̇ẕé֥l bĕ̇⁠ráb-kòֽ̇ẖa׃"],[33,17,"שֶׁ֣קֶר הַ֭⁠סּוּס לִ⁠תְשׁוּעָ֑ה וּ⁠בְ⁠רֹ֥ב חֵ֝יל֗⁠וֹ לֹ֣א יְמַלֵּֽט׃","şě֣qer ha֭⁠ṡẇs li⁠ţĕş̌ẇʻá֑h ẇ⁠bĕ⁠rò֥b ẖé֝yl֗⁠wò lò֣ʼ yĕmaléֽ̇t׃"],[33,18,"הִנֵּ֤ה עֵ֣ין יְ֭הוָה אֶל־יְרֵאָ֑י⁠ו לַֽ⁠מְיַחֲלִ֥ים לְ⁠חַסְדּֽ⁠וֹ׃","hiné֤̇h ʻé֣yn yĕ֭hwáh ʼel-yĕréʼá֑y⁠w laֽ⁠mĕyaẖàli֥ym lĕ⁠ẖasĕḋֽ⁠wò׃"],[33,19,"לְ⁠הַצִּ֣יל מִ⁠מָּ֣וֶת נַפְשָׁ֑⁠ם וּ֝⁠לְ⁠חַיּוֹתָ֗⁠ם בָּ⁠רָעָֽב׃","lĕ⁠haẕi֣̇yl mi⁠má֣̇weţ napĕşá֑̌⁠m ẇ֝⁠lĕ⁠ẖaẏwòţá֗⁠m bá̇⁠ráʻáֽb׃"],[33,20,"נַ֭פְשֵׁ⁠נוּ חִכְּתָ֣ה לַֽ⁠יהוָ֑ה עֶזְרֵ֖⁠נוּ וּ⁠מָגִנֵּ֣⁠נוּ הֽוּא׃","na֭pĕşé̌⁠nẇ ẖikĕ̇ţá֣h laֽ⁠yhwá֑h ʻezĕré֖⁠nẇ ẇ⁠máginé֣̇⁠nẇ hֽẇʼ׃"],[33,21,"כִּי־ב֭⁠וֹ יִשְׂמַ֣ח לִבֵּ֑⁠נוּ כִּ֤י בְ⁠שֵׁ֖ם קָדְשׁ֣⁠וֹ בָטָֽחְנוּ׃","ki̇y-b֭⁠wò yişĕ̂ma֣ẖ libé֑̇⁠nẇ ki֤̇y bĕ⁠şé֖̌m qádĕş֣̌⁠wò bátáֽẖĕnẇ׃"],[33,22,"יְהִֽי־חַסְדְּ⁠ךָ֣ יְהוָ֣ה עָלֵ֑י⁠נוּ כַּ֝⁠אֲשֶׁ֗ר יִחַ֥לְנוּ לָֽ⁠ךְ׃","yĕhiֽy-ẖasĕdĕ̇⁠ká֣ yĕhwá֣h ʻálé֑y⁠nẇ kȧ֝⁠ʼàşě֗r yiẖa֥lĕnẇ láֽ⁠kĕ׃"],[34,1,"אֲבָרֲכָ֣ה אֶת־יְהוָ֣ה בְּ⁠כָל־עֵ֑ת תָּ֝מִ֗יד תְּֽהִלָּת֥⁠וֹ בְּ⁠פִֽ⁠י׃","ʼàbáràká֣h ʼeţ-yĕhwá֣h bĕ̇⁠kál-ʻé֑ţ ţá̇֝mi֗yd ţĕֽ̇hilá̇ţ֥⁠wò bĕ̇⁠piֽ⁠y׃"],[34,2,"בַּ֭⁠יהוָה תִּתְהַלֵּ֣ל נַפְשִׁ֑⁠י יִשְׁמְע֖וּ עֲנָוִ֣ים וְ⁠יִשְׂמָֽחוּ׃","bȧ֭⁠yhwáh ţi̇ţĕhalé֣̇l napĕşǐ֑⁠y yişĕ̌mĕʻ֖ẇ ʻànáwi֣ym wĕ⁠yişĕ̂máֽẖẇ׃"],[34,3,"גַּדְּל֣וּ לַ⁠יהוָ֣ה אִתִּ֑⁠י וּ⁠נְרוֹמְמָ֖ה שְׁמ֣⁠וֹ יַחְדָּֽו׃","gȧdĕ̇l֣ẇ la⁠yhwá֣h ʼiţi֑̇⁠y ẇ⁠nĕrwòmĕmá֖h şĕ̌m֣⁠wò yaẖĕdáֽ̇w׃"],[34,4,"דָּרַ֣שְׁתִּי אֶת־יְהוָ֣ה וְ⁠עָנָ֑⁠נִי וּ⁠מִ⁠כָּל־מְ֝גוּרוֹתַ֗⁠י הִצִּילָֽ⁠נִי׃","dá̇ra֣şĕ̌ţi̇y ʼeţ-yĕhwá֣h wĕ⁠ʻáná֑⁠niy ẇ⁠mi⁠ká̇l-mĕ֝gẇrwòţa֗⁠y hiẕi̇yláֽ⁠niy׃"],[34,5,"הִבִּ֣יטוּ אֵלָ֣י⁠ו וְ⁠נָהָ֑רוּ וּ֝⁠פְנֵי⁠הֶ֗ם אַל־יֶחְפָּֽרוּ׃","hibi֣̇ytẇ ʼélá֣y⁠w wĕ⁠náhá֑rẇ ẇ֝⁠pĕnéy⁠he֗m ʼal-yeẖĕpáֽ̇rẇ׃"],[34,6,"זֶ֤ה עָנִ֣י קָ֭רָא וַ⁠יהוָ֣ה שָׁמֵ֑עַ וּ⁠מִ⁠כָּל־צָ֝רוֹתָ֗י⁠ו הוֹשִׁיעֽ⁠וֹ׃","ze֤h ʻáni֣y qá֭ráʼ wa⁠yhwá֣h şá̌mé֑ʻa ẇ⁠mi⁠ká̇l-ẕá֝rwòţá֗y⁠w hwòşǐyʻֽ⁠wò׃"],[34,7,"חֹנֶ֤ה מַלְאַךְ־יְהוָ֓ה סָ֘בִ֤יב לִֽ⁠ירֵאָ֗י⁠ו וַֽ⁠יְחַלְּצֵֽ⁠ם׃","ẖòne֤h malĕʼakĕ-yĕhwá֓h sá֘bi֤yb liֽ⁠yréʼá֗y⁠w waֽ⁠yĕẖalĕ̇ẕéֽ⁠m׃"],[34,8,"טַעֲמ֣וּ וּ֭⁠רְאוּ כִּי־ט֣וֹב יְהוָ֑ה אַֽשְׁרֵ֥י הַ֝⁠גֶּ֗בֶר יֶחֱסֶה־בּֽ⁠וֹ׃","taʻàm֣ẇ ẇ֭⁠rĕʼẇ ki̇y-t֣wòb yĕhwá֑h ʼaֽşĕ̌ré֥y ha֝⁠gė֗ber yeẖèseh-ḃֽ⁠wò׃"],[34,9,"יְר֣אוּ אֶת־יְהוָ֣ה קְדֹשָׁ֑י⁠ו כִּי־אֵ֥ין מַ֝חְס֗וֹר לִ⁠ירֵאָֽי⁠ו׃","yĕr֣ʼẇ ʼeţ-yĕhwá֣h qĕdòşá֑̌y⁠w ki̇y-ʼé֥yn ma֝ẖĕs֗wòr li⁠yréʼáֽy⁠w׃"],[34,10,"כְּ֭פִירִים רָשׁ֣וּ וְ⁠רָעֵ֑בוּ וְ⁠דֹרְשֵׁ֥י יְ֝הוָ֗ה לֹא־יַחְסְר֥וּ כָל־טֽוֹב׃","kĕ֭̇piyriym ráş֣̌ẇ wĕ⁠ráʻé֑bẇ wĕ⁠dòrĕşé֥̌y yĕ֝hwá֗h lòʼ-yaẖĕsĕr֥ẇ kál-tֽwòb׃"],[34,11,"לְֽכוּ־בָ֭נִים שִׁמְעוּ־לִ֑⁠י יִֽרְאַ֥ת יְ֝הוָ֗ה אֲלַמֶּדְ⁠כֶֽם׃","lĕֽkẇ-bá֭niym şǐmĕʻẇ-li֑⁠y yiֽrĕʼa֥ţ yĕ֝hwá֗h ʼàlamėdĕ⁠keֽm׃"],[34,12,"מִֽי־הָ֭⁠אִישׁ הֶ⁠חָפֵ֣ץ חַיִּ֑ים אֹהֵ֥ב יָ֝מִ֗ים לִ⁠רְא֥וֹת טֽוֹב׃","miֽy-há֭⁠ʼiyş̌ he⁠ẖápé֣ẕ ẖayi֑̇ym ʼòhé֥b yá֝mi֗ym li⁠rĕʼ֥wòţ tֽwòb׃"],[34,13,"נְצֹ֣ר לְשׁוֹנְ⁠ךָ֣ מֵ⁠רָ֑ע וּ֝⁠שְׂפָתֶ֗י⁠ךָ מִ⁠דַּבֵּ֥ר מִרְמָֽה׃","nĕẕò֣r lĕş̌wònĕ⁠ká֣ mé⁠rá֑ʻ ẇ֝⁠şĕ̂páţe֗y⁠ká mi⁠dȧbé֥̇r mirĕmáֽh׃"],[34,14,"ס֣וּר מֵ֭⁠רָע וַ⁠עֲשֵׂה־ט֑וֹב בַּקֵּ֖שׁ שָׁל֣וֹם וְ⁠רָדְפֵֽ⁠הוּ׃","s֣ẇr mé֭⁠ráʻ wa⁠ʻàşé̂h-t֑wòb bȧqé֖̇ş̌ şá̌l֣wòm wĕ⁠rádĕpéֽ⁠hẇ׃"],[34,15,"עֵינֵ֣י יְ֭הוָה אֶל־צַדִּיקִ֑ים וְ֝⁠אָזְנָ֗י⁠ו אֶל־שַׁוְעָתָֽ⁠ם׃","ʻéyné֣y yĕ֭hwáh ʼel-ẕadi̇yqi֑ym wĕ֝⁠ʼázĕná֗y⁠w ʼel-şǎwĕʻáţáֽ⁠m׃"],[34,16,"פְּנֵ֣י יְ֭הוָה בְּ⁠עֹ֣שֵׂי רָ֑ע לְ⁠הַכְרִ֖ית מֵ⁠אֶ֣רֶץ זִכְרָֽ⁠ם׃","pĕ̇né֣y yĕ֭hwáh bĕ̇⁠ʻò֣şé̂y rá֑ʻ lĕ⁠hakĕri֖yţ mé⁠ʼe֣reẕ zikĕráֽ⁠m׃"],[34,17,"צָעֲק֣וּ וַ⁠יהוָ֣ה שָׁמֵ֑עַ וּ⁠מִ⁠כָּל־צָ֝רוֹתָ֗⁠ם הִצִּילָֽ⁠ם׃","ẕáʻàq֣ẇ wa⁠yhwá֣h şá̌mé֑ʻa ẇ⁠mi⁠ká̇l-ẕá֝rwòţá֗⁠m hiẕi̇yláֽ⁠m׃"],[34,18,"קָר֣וֹב יְ֭הוָה לְ⁠נִשְׁבְּרֵי־לֵ֑ב וְֽ⁠אֶת־דַּכְּאֵי־ר֥וּחַ יוֹשִֽׁיעַ׃","qár֣wòb yĕ֭hwáh lĕ⁠nişĕ̌bĕ̇réy-lé֑b wĕֽ⁠ʼeţ-dȧkĕ̇ʼéy-r֥ẇẖa ywòşǐֽyʻa׃"],[34,19,"רַ֭בּוֹת רָע֣וֹת צַדִּ֑יק וּ֝⁠מִ⁠כֻּלָּ֗⁠ם יַצִּילֶ֥⁠נּוּ יְהוָֽה׃","ra֭ḃwòţ ráʻ֣wòţ ẕadi֑̇yq ẇ֝⁠mi⁠ku̇lá̇֗⁠m yaẕi̇yle֥⁠ṅẇ yĕhwáֽh׃"],[34,20,"שֹׁמֵ֥ר כָּל־עַצְמוֹתָ֑י⁠ו אַחַ֥ת מֵ֝⁠הֵ֗נָּה לֹ֣א נִשְׁבָּֽרָה׃","şò̌mé֥r ká̇l-ʻaẕĕmwòţá֑y⁠w ʼaẖa֥ţ mé֝⁠hé֗ná̇h lò֣ʼ nişĕ̌báֽ̇ráh׃"],[34,21,"תְּמוֹתֵ֣ת רָשָׁ֣ע רָעָ֑ה וְ⁠שֹׂנְאֵ֖י צַדִּ֣יק יֶאְשָֽׁמוּ׃","ţĕ̇mwòţé֣ţ ráşá֣̌ʻ ráʻá֑h wĕ⁠şò̂nĕʼé֖y ẕadi֣̇yq yeʼĕşáֽ̌mẇ׃"],[34,22,"פּוֹדֶ֣ה יְ֭הוָה נֶ֣פֶשׁ עֲבָדָ֑י⁠ו וְ⁠לֹ֥א יֶ֝אְשְׁמ֗וּ כָּֽל־הַ⁠חֹסִ֥ים בּֽ⁠וֹ׃","ṗwòde֣h yĕ֭hwáh ne֣peş̌ ʻàbádá֑y⁠w wĕ⁠lò֥ʼ ye֝ʼĕşĕ̌m֗ẇ káֽ̇l-ha⁠ẖòsi֥ym ḃֽ⁠wò׃"],[35,1,"לְ⁠דָוִ֨ד ׀ רִיבָ֣⁠ה יְ֭הוָה אֶת־יְרִיבַ֑⁠י לְ֝חַ֗ם אֶת־לֹֽחֲמָֽ⁠י׃","lĕ⁠dáwi֨d ׀ riybá֣⁠h yĕ֭hwáh ʼeţ-yĕriyba֑⁠y lĕ֝ẖa֗m ʼeţ-lòֽẖàmáֽ⁠y׃"],[35,2,"הַחֲזֵ֣ק מָגֵ֣ן וְ⁠צִנָּ֑ה וְ֝⁠ק֗וּמָ⁠ה בְּ⁠עֶזְרָתִֽ⁠י׃","haẖàzé֣q mágé֣n wĕ⁠ẕiná֑̇h wĕ֝⁠q֗ẇmá⁠h bĕ̇⁠ʻezĕráţiֽ⁠y׃"],[35,3,"וְ⁠הָ֘רֵ֤ק חֲנִ֣ית וּ֭⁠סְגֹר לִ⁠קְרַ֣את רֹדְפָ֑⁠י אֱמֹ֥ר לְ֝⁠נַפְשִׁ֗⁠י יְֽשֻׁעָתֵ֥⁠ךְ אָֽנִי׃","wĕ⁠há֘ré֤q ẖàni֣yţ ẇ֭⁠sĕgòr li⁠qĕra֣ʼţ ròdĕpá֑⁠y ʼèmò֥r lĕ֝⁠napĕşǐ֗⁠y yĕֽşǔʻáţé֥⁠kĕ ʼáֽniy׃"],[35,4,"יֵבֹ֣שׁוּ וְ⁠יִכָּלְמוּ֮ מְבַקְשֵׁ֪י נַ֫פְשִׁ֥⁠י יִסֹּ֣גוּ אָח֣וֹר וְ⁠יַחְפְּר֑וּ חֹ֝שְׁבֵ֗י רָעָתִֽ⁠י׃","yébò֣ş̌ẇ wĕ⁠yiká̇lĕmẇ֮ mĕbaqĕşé֪̌y na֫pĕşǐ֥⁠y yisò֣̇gẇ ʼáẖ֣wòr wĕ⁠yaẖĕpĕ̇r֑ẇ ẖò֝şĕ̌bé֗y ráʻáţiֽ⁠y׃"],[35,5,"יִֽהְי֗וּ כְּ⁠מֹ֥ץ לִ⁠פְנֵי־ר֑וּחַ וּ⁠מַלְאַ֖ךְ יְהוָ֣ה דּוֹחֶֽה׃","yiֽhĕy֗ẇ kĕ̇⁠mò֥ẕ li⁠pĕnéy-r֑ẇẖa ẇ⁠malĕʼa֖kĕ yĕhwá֣h ḋwòẖeֽh׃"],[35,6,"יְֽהִי־דַרְכָּ֗⁠ם חֹ֥שֶׁךְ וַ⁠חֲלַקְלַקּ֑וֹת וּ⁠מַלְאַ֥ךְ יְ֝הוָ֗ה רֹדְפָֽ⁠ם׃","yĕֽhiy-darĕká̇֗⁠m ẖò֥şěkĕ wa⁠ẖàlaqĕlaq֑̇wòţ ẇ⁠malĕʼa֥kĕ yĕ֝hwá֗h ròdĕpáֽ⁠m׃"],[35,7,"כִּֽי־חִנָּ֣ם טָֽמְנוּ־לִ֭⁠י שַׁ֣חַת רִשְׁתָּ֑⁠ם חִ֝נָּ֗ם חָפְר֥וּ לְ⁠נַפְשִֽׁ⁠י׃","kiֽ̇y-ẖiná֣̇m táֽmĕnẇ-li֭⁠y şǎ֣ẖaţ rişĕ̌ţá֑̇⁠m ẖi֝ná̇֗m ẖápĕr֥ẇ lĕ⁠napĕşǐֽ⁠y׃"],[35,8,"תְּבוֹאֵ֣⁠הוּ שׁוֹאָה֮ לֹֽא־יֵ֫דָ֥ע וְ⁠רִשְׁתּ֣⁠וֹ אֲשֶׁר־טָמַ֣ן תִּלְכְּד֑⁠וֹ בְּ֝⁠שׁוֹאָ֗ה יִפָּל־בָּֽ⁠הּ׃","ţĕ̇bwòʼé֣⁠hẇ ş̌wòʼáh֮ lòֽʼ-yé֫dá֥ʻ wĕ⁠rişĕ̌ţ֣̇⁠wò ʼàşěr-táma֣n ţi̇lĕkĕ̇d֑⁠wò bĕ̇֝⁠ş̌wòʼá֗h yipá̇l-báֽ̇⁠ḣ׃"],[35,9,"וְ֭⁠נַפְשִׁ⁠י תָּגִ֣יל בַּ⁠יהוָ֑ה תָּ֝שִׂישׂ בִּ⁠ישׁוּעָתֽ⁠וֹ׃","wĕ֭⁠napĕşǐ⁠y ţá̇gi֣yl bȧ⁠yhwá֑h ţá̇֝şîyş̂ bi̇⁠yş̌ẇʻáţֽ⁠wò׃"],[35,10,"כָּ֥ל עַצְמוֹתַ֨⁠י ׀ תֹּאמַרְנָה֮ יְהוָ֗ה מִ֥י כָ֫מ֥וֹ⁠ךָ מַצִּ֣יל עָ֭נִי מֵ⁠חָזָ֣ק מִמֶּ֑⁠נּוּ וְ⁠עָנִ֥י וְ֝⁠אֶבְי֗וֹן מִ⁠גֹּזְלֽ⁠וֹ׃","ká֥̇l ʻaẕĕmwòţa֨⁠y ׀ ţò̇ʼmarĕnáh֮ yĕhwá֗h mi֥y ká֫m֥wò⁠ká maẕi֣̇yl ʻá֭niy mé⁠ẖázá֣q mimė֑⁠ṅẇ wĕ⁠ʻáni֥y wĕ֝⁠ʼebĕy֗wòn mi⁠gò̇zĕlֽ⁠wò׃"],[35,11,"יְ֭קוּמוּ⁠ן עֵדֵ֣י חָמָ֑ס אֲשֶׁ֥ר לֹא־יָ֝דַ֗עְתִּי יִשְׁאָלֽוּ⁠נִי׃","yĕ֭qẇmẇ⁠n ʻédé֣y ẖámá֑s ʼàşě֥r lòʼ-yá֝da֗ʻĕţi̇y yişĕ̌ʼálֽẇ⁠niy׃"],[35,12,"יְשַׁלְּמ֣וּ⁠נִי רָ֭עָה תַּ֥חַת טוֹבָ֗ה שְׁכ֣וֹל לְ⁠נַפְשִֽׁ⁠י׃","yĕşǎlĕ̇m֣ẇ⁠niy rá֭ʻáh ţȧ֥ẖaţ twòbá֗h şĕ̌k֣wòl lĕ⁠napĕşǐֽ⁠y׃"],[35,13,"וַ⁠אֲנִ֤י ׀ בַּ⁠חֲלוֹתָ֡⁠ם לְב֬וּשִׁ⁠י שָׂ֗ק עִנֵּ֣יתִי בַ⁠צּ֣וֹם נַפְשִׁ֑⁠י וּ֝⁠תְפִלָּתִ֗⁠י עַל־חֵיקִ֥⁠י תָשֽׁוּב׃","wa⁠ʼàni֤y ׀ bȧ⁠ẖàlwòţá֡⁠m lĕb֬ẇşǐ⁠y şá̂֗q ʻiné֣̇yţiy ba⁠ẕ֣̇wòm napĕşǐ֑⁠y ẇ֝⁠ţĕpilá̇ţi֗⁠y ʻal-ẖéyqi֥⁠y ţáşֽ̌ẇb׃"],[35,14,"כְּ⁠רֵֽעַ־כְּ⁠אָ֣ח לִ֭⁠י הִתְהַלָּ֑כְתִּי כַּ⁠אֲבֶל־אֵ֝֗ם קֹדֵ֥ר שַׁחֽוֹתִי׃","kĕ̇⁠réֽʻa-kĕ̇⁠ʼá֣ẖ li֭⁠y hiţĕhalá֑̇kĕţi̇y kȧ⁠ʼàbel-ʼé֝֗m qòdé֥r şǎẖֽwòţiy׃"],[35,15,"וּ⁠בְ⁠צַלְעִ⁠י֮ שָׂמְח֪וּ וְֽ⁠נֶאֱ֫סָ֥פוּ נֶאֶסְפ֬וּ עָלַ֣⁠י נֵ֭כִים וְ⁠לֹ֣א יָדַ֑עְתִּי קָֽרְע֥וּ וְ⁠לֹא־דָֽמּוּ׃","ẇ⁠bĕ⁠ẕalĕʻi⁠y֮ şá̂mĕẖ֪ẇ wĕֽ⁠neʼè֫sá֥pẇ neʼesĕp֬ẇ ʻála֣⁠y né֭kiym wĕ⁠lò֣ʼ yáda֑ʻĕţi̇y qáֽrĕʻ֥ẇ wĕ⁠lòʼ-dáֽṁẇ׃"],[35,16,"בְּ֭⁠חַנְפֵי לַעֲגֵ֣י מָע֑וֹג חָרֹ֖ק עָלַ֣⁠י שִׁנֵּֽי⁠מוֹ׃","bĕ֭̇⁠ẖanĕpéy laʻàgé֣y máʻ֑wòg ẖárò֖q ʻála֣⁠y şǐnéֽ̇y⁠mwò׃"],[35,17,"אֲדֹנָ⁠י֮ כַּ⁠מָּ֪ה תִּ֫רְאֶ֥ה הָשִׁ֣יבָ⁠ה נַ֭פְשִׁ⁠י מִ⁠שֹּׁאֵי⁠הֶ֑ם מִ֝⁠כְּפִירִ֗ים יְחִידָתִֽ⁠י׃","ʼàdòná⁠y֮ kȧ⁠má֪̇h ţi̇֫rĕʼe֥h háşǐ֣ybá⁠h na֭pĕşǐ⁠y mi⁠şò̇̌ʼéy⁠he֑m mi֝⁠kĕ̇piyri֗ym yĕẖiydáţiֽ⁠y׃"],[35,18,"א֭וֹדְ⁠ךָ בְּ⁠קָהָ֣ל רָ֑ב בְּ⁠עַ֖ם עָצ֣וּם אֲהַֽלְלֶֽ⁠ךָּ׃","ʼ֭wòdĕ⁠ká bĕ̇⁠qáhá֣l rá֑b bĕ̇⁠ʻa֖m ʻáẕ֣ẇm ʼàhaֽlĕleֽ⁠ká̇׃"],[35,19,"אַֽל־יִשְׂמְחוּ־לִ֣⁠י אֹיְבַ֣⁠י שֶׁ֑קֶר שֹׂנְאַ֥⁠י חִ֝נָּ֗ם יִקְרְצוּ־עָֽיִן׃","ʼaֽl-yişĕ̂mĕẖẇ-li֣⁠y ʼòyĕba֣⁠y şě֑qer şò̂nĕʼa֥⁠y ẖi֝ná̇֗m yiqĕrĕẕẇ-ʻáֽyin׃"],[35,20,"כִּ֤י לֹ֥א שָׁל֗וֹם יְדַ֫בֵּ֥רוּ וְ⁠עַ֥ל רִגְעֵי־אֶ֑רֶץ דִּבְרֵ֥י מִ֝רְמוֹת יַחֲשֹׁבֽוּ⁠ן׃","ki֤̇y lò֥ʼ şá̌l֗wòm yĕda֫bé֥̇rẇ wĕ⁠ʻa֥l rigĕʻéy-ʼe֑reẕ di̇bĕré֥y mi֝rĕmwòţ yaẖàşò̌bֽẇ⁠n׃"],[35,21,"וַ⁠יַּרְחִ֥יבוּ עָלַ֗⁠י פִּ֫י⁠הֶ֥ם אָ֭מְרוּ הֶאָ֣ח ׀ הֶאָ֑ח רָאֲתָ֥ה עֵינֵֽי⁠נוּ׃","wa⁠yȧrĕẖi֥ybẇ ʻála֗⁠y pi̇֫y⁠he֥m ʼá֭mĕrẇ heʼá֣ẖ ׀ heʼá֑ẖ ráʼàţá֥h ʻéynéֽy⁠nẇ׃"],[35,22,"רָאִ֣יתָה יְ֭הוָה אַֽל־תֶּחֱרַ֑שׁ אֲ֝דֹנָ֗⁠י אֲל־תִּרְחַ֥ק מִמֶּֽ⁠נִּי׃","ráʼi֣yţáh yĕ֭hwáh ʼaֽl-ţėẖèra֑ş̌ ʼà֝dòná֗⁠y ʼàl-ţi̇rĕẖa֥q mimėֽ⁠ni̇y׃"],[35,23,"הָעִ֣ירָ⁠ה וְ֭⁠הָקִיצָ⁠ה לְ⁠מִשְׁפָּטִ֑⁠י אֱלֹהַ֖⁠י וַֽ⁠אדֹנָ֣⁠י לְ⁠רִיבִֽ⁠י׃","háʻi֣yrá⁠h wĕ֭⁠háqiyẕá⁠h lĕ⁠mişĕ̌pá̇ti֑⁠y ʼèlòha֖⁠y waֽ⁠ʼdòná֣⁠y lĕ⁠riybiֽ⁠y׃"],[35,24,"שָׁפְטֵ֣⁠נִי כְ֭⁠צִדְקְ⁠ךָ יְהוָ֥ה אֱלֹהָ֗⁠י וְ⁠אַל־יִשְׂמְחוּ־לִֽ⁠י׃","şá̌pĕté֣⁠niy kĕ֭⁠ẕidĕqĕ⁠ká yĕhwá֥h ʼèlòhá֗⁠y wĕ⁠ʼal-yişĕ̂mĕẖẇ-liֽ⁠y׃"],[35,25,"אַל־יֹאמְר֣וּ בְ֭⁠לִבָּ⁠ם הֶאָ֣ח נַפְשֵׁ֑⁠נוּ אַל־יֹ֝אמְר֗וּ בִּֽלַּעֲנֽוּ⁠הוּ׃","ʼal-yòʼmĕr֣ẇ bĕ֭⁠libá̇⁠m heʼá֣ẖ napĕşé֑̌⁠nẇ ʼal-yò֝ʼmĕr֗ẇ biֽ̇lȧʻànֽẇ⁠hẇ׃"],[35,26,"יֵ֘בֹ֤שׁוּ וְ⁠יַחְפְּר֨וּ ׀ יַחְדָּו֮ שְׂמֵחֵ֪י רָעָ֫תִ֥⁠י יִֽלְבְּשׁוּ־בֹ֥שֶׁת וּ⁠כְלִמָּ֑ה הַֽ⁠מַּגְדִּילִ֥ים עָלָֽ⁠י׃","yé֘bò֤ş̌ẇ wĕ⁠yaẖĕpĕ̇r֨ẇ ׀ yaẖĕdá̇w֮ şĕ̂méẖé֪y ráʻá֫ţi֥⁠y yiֽlĕbĕ̇ş̌ẇ-bò֥şěţ ẇ⁠kĕlimá֑̇h haֽ⁠mȧgĕdi̇yli֥ym ʻáláֽ⁠y׃"],[35,27,"יָרֹ֣נּוּ וְ⁠יִשְׂמְחוּ֮ חֲפֵצֵ֪י צִ֫דְקִ֥⁠י וְ⁠יֹאמְר֣וּ תָ֭מִיד יִגְדַּ֣ל יְהוָ֑ה הֶ֝⁠חָפֵ֗ץ שְׁל֣וֹם עַבְדּֽ⁠וֹ׃","yárò֣ṅẇ wĕ⁠yişĕ̂mĕẖẇ֮ ẖàpéẕé֪y ẕi֫dĕqi֥⁠y wĕ⁠yòʼmĕr֣ẇ ţá֭miyd yigĕdȧ֣l yĕhwá֑h he֝⁠ẖápé֗ẕ şĕ̌l֣wòm ʻabĕḋֽ⁠wò׃"],[35,28,"וּ֭⁠לְשׁוֹנִ⁠י תֶּהְגֶּ֣ה צִדְקֶ֑⁠ךָ כָּל־הַ֝⁠יּוֹם תְּהִלָּתֶֽ⁠ךָ׃","ẇ֭⁠lĕş̌wòni⁠y ţėhĕgė֣h ẕidĕqe֑⁠ká ká̇l-ha֝⁠ẏwòm ţĕ̇hilá̇ţeֽ⁠ká׃"],[36,1,"נְאֻֽם־פֶּ֣שַׁע לָ֭⁠רָשָׁע בְּ⁠קֶ֣רֶב לִבִּ֑⁠י אֵֽין־פַּ֥חַד אֱ֝לֹהִ֗ים לְ⁠נֶ֣גֶד עֵינָֽי⁠ו׃","nĕʼuֽm-pė֣şǎʻ lá֭⁠ráşá̌ʻ bĕ̇⁠qe֣reb libi֑̇⁠y ʼéֽyn-pȧ֥ẖad ʼè֝lòhi֗ym lĕ⁠ne֣ged ʻéynáֽy⁠w׃"],[36,2,"כִּֽי־הֶחֱלִ֣יק אֵלָ֣י⁠ו בְּ⁠עֵינָ֑י⁠ו לִ⁠מְצֹ֖א עֲוֺנ֣⁠וֹ לִ⁠שְׂנֹֽא׃","kiֽ̇y-heẖèli֣yq ʼélá֣y⁠w bĕ̇⁠ʻéyná֑y⁠w li⁠mĕẕò֖ʼ ʻàwֺn֣⁠wò li⁠şĕ̂nòֽʼ׃"],[36,3,"דִּבְרֵי־פִ֭י⁠ו אָ֣וֶן וּ⁠מִרְמָ֑ה חָדַ֖ל לְ⁠הַשְׂכִּ֣יל לְ⁠הֵיטִֽיב׃","di̇bĕréy-pi֭y⁠w ʼá֣wen ẇ⁠mirĕmá֑h ẖáda֖l lĕ⁠haşĕ̂ki֣̇yl lĕ⁠héytiֽyb׃"],[36,4,"אָ֤וֶן ׀ יַחְשֹׁ֗ב עַֽל־מִשְׁכָּ֫ב֥⁠וֹ יִ֭תְיַצֵּב עַל־דֶּ֣רֶךְ לֹא־ט֑וֹב רָ֝֗ע לֹ֣א יִמְאָֽס׃","ʼá֤wen ׀ yaẖĕşò̌֗b ʻaֽl-mişĕ̌ká̇֫b֥⁠wò yi֭ţĕyaẕé̇b ʻal-dė֣rekĕ lòʼ-t֑wòb rá֝֗ʻ lò֣ʼ yimĕʼáֽs׃"],[36,5,"יְ֭הוָה בְּ⁠הַ⁠שָּׁמַ֣יִם חַסְדֶּ֑⁠ךָ אֱ֝מֽוּנָתְ⁠ךָ֗ עַד־שְׁחָקִֽים׃","yĕ֭hwáh bĕ̇⁠ha⁠şá̇̌ma֣yim ẖasĕdė֑⁠ká ʼè֝mֽẇnáţĕ⁠ká֗ ʻad-şĕ̌ẖáqiֽym׃"],[36,6,"צִדְקָֽתְ⁠ךָ֨ ׀ כְּֽ⁠הַרְרֵי־אֵ֗ל מִ֭שְׁפָּטֶ⁠ךָ תְּה֣וֹם רַבָּ֑ה אָ֤דָֽם־וּ⁠בְהֵמָ֖ה תוֹשִׁ֣יעַ יְהוָֽה׃","ẕidĕqáֽţĕ⁠ká֨ ׀ kĕֽ̇⁠harĕréy-ʼé֗l mi֭şĕ̌pá̇te⁠ká ţĕ̇h֣wòm rabá֑̇h ʼá֤dáֽm-ẇ⁠bĕhémá֖h ţwòşǐ֣yʻa yĕhwáֽh׃"],[36,7,"מַה־יָּקָ֥ר חַסְדְּ⁠ךָ֗ אֱלֹ֫הִ֥ים וּ⁠בְנֵ֥י אָדָ֑ם בְּ⁠צֵ֥ל כְּ֝נָפֶ֗י⁠ךָ יֶחֱסָיֽוּ⁠ן׃","mah-yá̇qá֥r ẖasĕdĕ̇⁠ká֗ ʼèlò֫hi֥ym ẇ⁠bĕné֥y ʼádá֑m bĕ̇⁠ẕé֥l kĕ̇֝nápe֗y⁠ká yeẖèsáyֽẇ⁠n׃"],[36,8,"יִ֭רְוְיֻ⁠ן מִ⁠דֶּ֣שֶׁן בֵּיתֶ֑⁠ךָ וְ⁠נַ֖חַל עֲדָנֶ֣י⁠ךָ תַשְׁקֵֽ⁠ם׃","yi֭rĕwĕyu⁠n mi⁠dė֣şěn bé̇yţe֑⁠ká wĕ⁠na֖ẖal ʻàdáne֣y⁠ká ţaşĕ̌qéֽ⁠m׃"],[36,9,"כִּֽי־עִ֭מְּ⁠ךָ מְק֣וֹר חַיִּ֑ים בְּ֝⁠אוֹרְ⁠ךָ֗ נִרְאֶה־אֽוֹר׃","kiֽ̇y-ʻi֭mĕ̇⁠ká mĕq֣wòr ẖayi֑̇ym bĕ̇֝⁠ʼwòrĕ⁠ká֗ nirĕʼeh-ʼֽwòr׃"],[36,10,"מְשֹׁ֣ךְ חַ֭סְדְּ⁠ךָ לְ⁠יֹדְעֶ֑י⁠ךָ וְ֝⁠צִדְקָֽתְ⁠ךָ֗ לְ⁠יִשְׁרֵי־לֵֽב׃","mĕşò֣̌kĕ ẖa֭sĕdĕ̇⁠ká lĕ⁠yòdĕʻe֑y⁠ká wĕ֝⁠ẕidĕqáֽţĕ⁠ká֗ lĕ⁠yişĕ̌réy-léֽb׃"],[36,11,"אַל־תְּ֭בוֹאֵ⁠נִי רֶ֣גֶל גַּאֲוָ֑ה וְ⁠יַד־רְ֝שָׁעִ֗ים אַל־תְּנִדֵֽ⁠נִי׃","ʼal-ţĕ֭̇bwòʼé⁠niy re֣gel gȧʼàwá֑h wĕ⁠yad-rĕ֝şá̌ʻi֗ym ʼal-ţĕ̇nidéֽ⁠niy׃"],[36,12,"שָׁ֣ם נָ֭פְלוּ פֹּ֣עֲלֵי אָ֑וֶן דֹּ֝ח֗וּ וְ⁠לֹא־יָ֥כְלוּ קֽוּם׃","şá֣̌m ná֭pĕlẇ pò֣̇ʻàléy ʼá֑wen dò̇֝ẖ֗ẇ wĕ⁠lòʼ-yá֥kĕlẇ qֽẇm׃"],[37,1,"לְ⁠דָוִ֨ד ׀ אַל־תִּתְחַ֥ר בַּ⁠מְּרֵעִ֑ים אַל־תְּ֝קַנֵּ֗א בְּ⁠עֹשֵׂ֥י עַוְלָֽה׃","lĕ⁠dáwi֨d ׀ ʼal-ţi̇ţĕẖa֥r bȧ⁠mĕ̇réʻi֑ym ʼal-ţĕ̇֝qané̇֗ʼ bĕ̇⁠ʻòşé֥̂y ʻawĕláֽh׃"],[37,2,"כִּ֣י כֶ֭⁠חָצִיר מְהֵרָ֣ה יִמָּ֑לוּ וּ⁠כְ⁠יֶ֥רֶק דֶּ֝֗שֶׁא יִבּוֹלֽוּ⁠ן׃","ki֣̇y ke֭⁠ẖáẕiyr mĕhérá֣h yimá֑̇lẇ ẇ⁠kĕ⁠ye֥req dė֝֗şěʼ yiḃwòlֽẇ⁠n׃"],[37,3,"בְּטַ֣ח בַּֽ֭⁠יהוָה וַ⁠עֲשֵׂה־ט֑וֹב שְׁכָן־אֶ֝֗רֶץ וּ⁠רְעֵ֥ה אֱמוּנָֽה׃","bĕ̇ta֣ẖ bȧֽ֭⁠yhwáh wa⁠ʻàşé̂h-t֑wòb şĕ̌kán-ʼe֝֗reẕ ẇ⁠rĕʻé֥h ʼèmẇnáֽh׃"],[37,4,"וְ⁠הִתְעַנַּ֥ג עַל־יְהוָ֑ה וְ⁠יִֽתֶּן־לְ֝⁠ךָ֗ מִשְׁאֲלֹ֥ת לִבֶּֽ⁠ךָ׃","wĕ⁠hiţĕʻanȧ֥g ʻal-yĕhwá֑h wĕ⁠yiֽţėn-lĕ֝⁠ká֗ mişĕ̌ʼàlò֥ţ libėֽ⁠ká׃"],[37,5,"גּ֣וֹל עַל־יְהוָ֣ה דַּרְכֶּ֑⁠ךָ וּ⁠בְטַ֥ח עָ֝לָ֗י⁠ו וְ⁠ה֣וּא יַעֲשֶֽׂה׃","ġ֣wòl ʻal-yĕhwá֣h dȧrĕkė֑⁠ká ẇ⁠bĕta֥ẖ ʻá֝lá֗y⁠w wĕ⁠h֣ẇʼ yaʻàşêֽh׃"],[37,6,"וְ⁠הוֹצִ֣יא כָ⁠א֣וֹר צִדְקֶ֑⁠ךָ וּ֝⁠מִשְׁפָּטֶ֗⁠ךָ כַּֽ⁠צָּהֳרָֽיִם׃","wĕ⁠hwòẕi֣yʼ ká⁠ʼ֣wòr ẕidĕqe֑⁠ká ẇ֝⁠mişĕ̌pá̇te֗⁠ká kȧֽ⁠ẕá̇horáֽyim׃"],[37,7,"דּ֤וֹם ׀ לַ⁠יהוָה֮ וְ⁠הִתְח֪וֹלֵ֫ל ל֥⁠וֹ אַל־תִּ֭תְחַר בְּ⁠מַצְלִ֣יחַ דַּרְכּ֑⁠וֹ בְּ֝⁠אִ֗ישׁ עֹשֶׂ֥ה מְזִמּֽוֹת׃","ḋ֤wòm ׀ la⁠yhwáh֮ wĕ⁠hiţĕẖ֪wòlé֫l l֥⁠wò ʼal-ţi֭̇ţĕẖar bĕ̇⁠maẕĕli֣yẖa dȧrĕk֑̇⁠wò bĕ̇֝⁠ʼi֗yş̌ ʻòşê֥h mĕziṁֽwòţ׃"],[37,8,"הֶ֣רֶף מֵ֭⁠אַף וַ⁠עֲזֹ֣ב חֵמָ֑ה אַל־תִּ֝תְחַ֗ר אַךְ־לְ⁠הָרֵֽעַ׃","he֣rep mé֭⁠ʼap wa⁠ʻàzò֣b ẖémá֑h ʼal-ţi̇֝ţĕẖa֗r ʼakĕ-lĕ⁠háréֽʻa׃"],[37,9,"כִּֽי־מְ֭רֵעִים יִכָּרֵת֑וּ⁠ן וְ⁠קֹוֵ֥י יְ֝הוָ֗ה הֵ֣מָּה יִֽירְשׁוּ־אָֽרֶץ׃","kiֽ̇y-mĕ֭réʻiym yiká̇réţ֑ẇ⁠n wĕ⁠qòwé֥y yĕ֝hwá֗h hé֣má̇h yiֽyrĕş̌ẇ-ʼáֽreẕ׃"],[37,10,"וְ⁠ע֣וֹד מְ֭עַט וְ⁠אֵ֣ין רָשָׁ֑ע וְ⁠הִתְבּוֹנַ֖נְתָּ עַל־מְקוֹמ֣⁠וֹ וְ⁠אֵינֶֽ⁠נּוּ׃","wĕ⁠ʻ֣wòd mĕ֭ʻat wĕ⁠ʼé֣yn ráşá֑̌ʻ wĕ⁠hiţĕḃwòna֖nĕţá̇ ʻal-mĕqwòm֣⁠wò wĕ⁠ʼéyneֽ⁠ṅẇ׃"],[37,11,"וַ⁠עֲנָוִ֥ים יִֽירְשׁוּ־אָ֑רֶץ וְ֝⁠הִתְעַנְּג֗וּ עַל־רֹ֥ב שָׁלֽוֹם׃","wa⁠ʻànáwi֥ym yiֽyrĕş̌ẇ-ʼá֑reẕ wĕ֝⁠hiţĕʻanĕ̇g֗ẇ ʻal-rò֥b şá̌lֽwòm׃"],[37,12,"זֹמֵ֣ם רָ֭שָׁע לַ⁠צַּדִּ֑יק וְ⁠חֹרֵ֖ק עָלָ֣י⁠ו שִׁנָּֽי⁠ו׃","zòmé֣m rá֭şá̌ʻ la⁠ẕȧdi֑̇yq wĕ⁠ẖòré֖q ʻálá֣y⁠w şǐnáֽ̇y⁠w׃"],[37,13,"אֲדֹנָ֥⁠י יִשְׂחַק־ל֑⁠וֹ כִּֽי־רָ֝אָ֗ה כִּֽי־יָבֹ֥א יוֹמֽ⁠וֹ׃","ʼàdòná֥⁠y yişĕ̂ẖaq-l֑⁠wò kiֽ̇y-rá֝ʼá֗h kiֽ̇y-yábò֥ʼ ywòmֽ⁠wò׃"],[37,14,"חֶ֤רֶב ׀ פָּֽתְח֣וּ רְשָׁעִים֮ וְ⁠דָרְכ֪וּ קַ֫שְׁתָּ֥⁠ם לְ֭⁠הַפִּיל עָנִ֣י וְ⁠אֶבְי֑וֹן לִ֝⁠טְב֗וֹחַ יִשְׁרֵי־דָֽרֶךְ׃","ẖe֤reb ׀ páֽ̇ţĕẖ֣ẇ rĕşá̌ʻiym֮ wĕ⁠dárĕk֪ẇ qa֫şĕ̌ţá֥̇⁠m lĕ֭⁠hapi̇yl ʻáni֣y wĕ⁠ʼebĕy֑wòn li֝⁠tĕb֗wòẖa yişĕ̌réy-dáֽrekĕ׃"],[37,15,"חַ֭רְבָּ⁠ם תָּב֣וֹא בְ⁠לִבָּ֑⁠ם וְ֝⁠קַשְּׁתוֹתָ֗⁠ם תִּשָּׁבַֽרְנָה׃","ẖa֭rĕbá̇⁠m ţá̇b֣wòʼ bĕ⁠libá֑̇⁠m wĕ֝⁠qaşĕ̇̌ţwòţá֗⁠m ţi̇şá̇̌baֽrĕnáh׃"],[37,16,"טוֹב־מְ֭עַט לַ⁠צַּדִּ֑יק מֵ֝⁠הֲמ֗וֹן רְשָׁעִ֥ים רַבִּֽים׃","twòb-mĕ֭ʻat la⁠ẕȧdi֑̇yq mé֝⁠hàm֗wòn rĕşá̌ʻi֥ym rabiֽ̇ym׃"],[37,17,"כִּ֤י זְרוֹע֣וֹת רְ֭שָׁעִים תִּשָּׁבַ֑רְנָה וְ⁠סוֹמֵ֖ךְ צַדִּיקִ֣ים יְהוָֽה׃","ki֤̇y zĕrwòʻ֣wòţ rĕ֭şá̌ʻiym ţi̇şá̇̌ba֑rĕnáh wĕ⁠swòmé֖kĕ ẕadi̇yqi֣ym yĕhwáֽh׃"],[37,18,"יוֹדֵ֣עַ יְ֭הוָה יְמֵ֣י תְמִימִ֑ם וְ֝⁠נַחֲלָתָ֗⁠ם לְ⁠עוֹלָ֥ם תִּהְיֶֽה׃","ywòdé֣ʻa yĕ֭hwáh yĕmé֣y ţĕmiymi֑m wĕ֝⁠naẖàláţá֗⁠m lĕ⁠ʻwòlá֥m ţi̇hĕyeֽh׃"],[37,19,"לֹֽא־יֵ֭בֹשׁוּ בְּ⁠עֵ֣ת רָעָ֑ה וּ⁠בִ⁠ימֵ֖י רְעָב֣וֹן יִשְׂבָּֽעוּ׃","lòֽʼ-yé֭bòş̌ẇ bĕ̇⁠ʻé֣ţ ráʻá֑h ẇ⁠bi⁠ymé֖y rĕʻáb֣wòn yişĕ̂báֽ̇ʻẇ׃"],[37,20,"כִּ֤י רְשָׁעִ֨ים ׀ יֹאבֵ֗דוּ וְ⁠אֹיְבֵ֣י יְ֭הוָה כִּ⁠יקַ֣ר כָּרִ֑ים כָּל֖וּ בֶ⁠עָשָׁ֣ן כָּֽלוּ׃","ki֤̇y rĕşá̌ʻi֨ym ׀ yòʼbé֗dẇ wĕ⁠ʼòyĕbé֣y yĕ֭hwáh ki̇⁠yqa֣r ká̇ri֑ym ká̇l֖ẇ be⁠ʻáşá֣̌n káֽ̇lẇ׃"],[37,21,"לֹוֶ֣ה רָ֭שָׁע וְ⁠לֹ֣א יְשַׁלֵּ֑ם וְ֝⁠צַדִּ֗יק חוֹנֵ֥ן וְ⁠נוֹתֵֽן׃","lòwe֣h rá֭şá̌ʻ wĕ⁠lò֣ʼ yĕşǎlé֑̇m wĕ֝⁠ẕadi̇֗yq ẖwòné֥n wĕ⁠nwòţéֽn׃"],[37,22,"כִּ֣י מְ֭בֹרָכָי⁠ו יִ֣ירְשׁוּ אָ֑רֶץ וּ֝⁠מְקֻלָּלָ֗י⁠ו יִכָּרֵֽתוּ׃","ki֣̇y mĕ֭bòrákáy⁠w yi֣yrĕş̌ẇ ʼá֑reẕ ẇ֝⁠mĕqulá̇lá֗y⁠w yiká̇réֽţẇ׃"],[37,23,"מֵ֭⁠יְהוָה מִֽצְעֲדֵי־גֶ֥בֶר כּוֹנָ֗נוּ וְ⁠דַרְכּ֥⁠וֹ יֶחְפָּֽץ׃","mé֭⁠yĕhwáh miֽẕĕʻàdéy-ge֥ber k̇wòná֗nẇ wĕ⁠darĕk֥̇⁠wò yeẖĕpáֽ̇ẕ׃"],[37,24,"כִּֽי־יִפֹּ֥ל לֹֽא־יוּטָ֑ל כִּֽי־יְ֝הוָ֗ה סוֹמֵ֥ךְ יָדֽ⁠וֹ׃","kiֽ̇y-yipò֥̇l lòֽʼ-yẇtá֑l kiֽ̇y-yĕ֝hwá֗h swòmé֥kĕ yádֽ⁠wò׃"],[37,25,"נַ֤עַר ׀ הָיִ֗יתִי גַּם־זָ֫קַ֥נְתִּי וְֽ⁠לֹא־רָ֭אִיתִי צַדִּ֣יק נֶעֱזָ֑ב וְ֝⁠זַרְע֗⁠וֹ מְבַקֶּשׁ־לָֽחֶם׃","na֤ʻar ׀ háyi֗yţiy gȧm-zá֫qa֥nĕţi̇y wĕֽ⁠lòʼ-rá֭ʼiyţiy ẕadi֣̇yq neʻèzá֑b wĕ֝⁠zarĕʻ֗⁠wò mĕbaqėş̌-láֽẖem׃"],[37,26,"כָּל־הַ֭⁠יּוֹם חוֹנֵ֣ן וּ⁠מַלְוֶ֑ה וְ֝⁠זַרְע֗⁠וֹ לִ⁠בְרָכָֽה׃","ká̇l-ha֭⁠ẏwòm ẖwòné֣n ẇ⁠malĕwe֑h wĕ֝⁠zarĕʻ֗⁠wò li⁠bĕrákáֽh׃"],[37,27,"ס֣וּר מֵ֭⁠רָע וַ⁠עֲשֵׂה־ט֗וֹב וּ⁠שְׁכֹ֥ן לְ⁠עוֹלָֽם׃","s֣ẇr mé֭⁠ráʻ wa⁠ʻàşé̂h-t֗wòb ẇ⁠şĕ̌kò֥n lĕ⁠ʻwòláֽm׃"],[37,28,"כִּ֤י יְהוָ֨ה ׀ אֹ֘הֵ֤ב מִשְׁפָּ֗ט וְ⁠לֹא־יַעֲזֹ֣ב אֶת־חֲ֭סִידָי⁠ו לְ⁠עוֹלָ֣ם נִשְׁמָ֑רוּ וְ⁠זֶ֖רַע רְשָׁעִ֣ים נִכְרָֽת׃","ki֤̇y yĕhwá֨h ׀ ʼò֘hé֤b mişĕ̌pá̇֗t wĕ⁠lòʼ-yaʻàzò֣b ʼeţ-ẖà֭siydáy⁠w lĕ⁠ʻwòlá֣m nişĕ̌má֑rẇ wĕ⁠ze֖raʻ rĕşá̌ʻi֣ym nikĕráֽţ׃"],[37,29,"צַדִּיקִ֥ים יִֽירְשׁוּ־אָ֑רֶץ וְ⁠יִשְׁכְּנ֖וּ לָ⁠עַ֣ד עָלֶֽי⁠הָ׃","ẕadi̇yqi֥ym yiֽyrĕş̌ẇ-ʼá֑reẕ wĕ⁠yişĕ̌kĕ̇n֖ẇ lá⁠ʻa֣d ʻáleֽy⁠há׃"],[37,30,"פִּֽי־צַ֭דִּיק יֶהְגֶּ֣ה חָכְמָ֑ה וּ֝⁠לְשׁוֹנ֗⁠וֹ תְּדַבֵּ֥ר מִשְׁפָּֽט׃","piֽ̇y-ẕa֭di̇yq yehĕgė֣h ẖákĕmá֑h ẇ֝⁠lĕş̌wòn֗⁠wò ţĕ̇dabé֥̇r mişĕ̌páֽ̇t׃"],[37,31,"תּוֹרַ֣ת אֱלֹהָ֣י⁠ו בְּ⁠לִבּ֑⁠וֹ לֹ֖א תִמְעַ֣ד אֲשֻׁרָי⁠ו׃","ţ̇wòra֣ţ ʼèlòhá֣y⁠w bĕ̇⁠liḃ֑⁠wò lò֖ʼ ţimĕʻa֣d ʼàşǔráy⁠w׃"],[37,32,"צוֹפֶ֣ה רָ֭שָׁע לַ⁠צַּדִּ֑יק וּ֝⁠מְבַקֵּ֗שׁ לַ⁠הֲמִית⁠וֹ׃","ẕwòpe֣h rá֭şá̌ʻ la⁠ẕȧdi֑̇yq ẇ֝⁠mĕbaqé̇֗ş̌ la⁠hàmiyţ⁠wò׃"],[37,33,"יְ֭הוָה לֹא־יַעַזְבֶ֣⁠נּוּ בְ⁠יָד֑⁠וֹ וְ⁠לֹ֥א יַ֝רְשִׁיעֶ֗⁠נּוּ בְּ⁠הִשָּׁפְטֽ⁠וֹ׃","yĕ֭hwáh lòʼ-yaʻazĕbe֣⁠ṅẇ bĕ⁠yád֑⁠wò wĕ⁠lò֥ʼ ya֝rĕşǐyʻe֗⁠ṅẇ bĕ̇⁠hişá̇̌pĕtֽ⁠wò׃"],[37,34,"קַוֵּ֤ה אֶל־יְהוָ֨ה ׀ וּ⁠שְׁמֹ֬ר דַּרְכּ֗⁠וֹ וִֽ֭⁠ירוֹמִמְ⁠ךָ לָ⁠רֶ֣שֶׁת אָ֑רֶץ בְּ⁠הִכָּרֵ֖ת רְשָׁעִ֣ים תִּרְאֶֽה׃","qawé֤̇h ʼel-yĕhwá֨h ׀ ẇ⁠şĕ̌mò֬r dȧrĕk̇֗⁠wò wiֽ֭⁠yrwòmimĕ⁠ká lá⁠re֣şěţ ʼá֑reẕ bĕ̇⁠hiká̇ré֖ţ rĕşá̌ʻi֣ym ţi̇rĕʼeֽh׃"],[37,35,"רָ֭אִיתִי רָשָׁ֣ע עָרִ֑יץ וּ֝⁠מִתְעָרֶ֗ה כְּ⁠אֶזְרָ֥ח רַעֲנָֽן׃","rá֭ʼiyţiy ráşá֣̌ʻ ʻári֑yẕ ẇ֝⁠miţĕʻáre֗h kĕ̇⁠ʼezĕrá֥ẖ raʻànáֽn׃"],[37,36,"וַ֭⁠יַּֽעֲבֹר וְ⁠הִנֵּ֣ה אֵינֶ֑⁠נּוּ וָֽ֝⁠אֲבַקְשֵׁ֗⁠הוּ וְ⁠לֹ֣א נִמְצָֽא׃","wa֭⁠ẏֽaʻàbòr wĕ⁠hiné֣̇h ʼéyne֑⁠ṅẇ wáֽ֝⁠ʼàbaqĕşé̌֗⁠hẇ wĕ⁠lò֣ʼ nimĕẕáֽʼ׃"],[37,37,"שְׁמָר־תָּ֭ם וּ⁠רְאֵ֣ה יָשָׁ֑ר כִּֽי־אַחֲרִ֖ית לְ⁠אִ֣ישׁ שָׁלֽוֹם׃","şĕ̌már-ţá֭̇m ẇ⁠rĕʼé֣h yáşá֑̌r kiֽ̇y-ʼaẖàri֖yţ lĕ⁠ʼi֣yş̌ şá̌lֽwòm׃"],[37,38,"וּֽ֭⁠פֹשְׁעִים נִשְׁמְד֣וּ יַחְדָּ֑ו אַחֲרִ֖ית רְשָׁעִ֣ים נִכְרָֽתָה׃","ẇֽ֭⁠pòşĕ̌ʻiym nişĕ̌mĕd֣ẇ yaẖĕdá֑̇w ʼaẖàri֖yţ rĕşá̌ʻi֣ym nikĕráֽţáh׃"],[37,39,"וּ⁠תְשׁוּעַ֣ת צַ֭דִּיקִים מֵ⁠יְהוָ֑ה מָֽ֝עוּזָּ֗⁠ם בְּ⁠עֵ֣ת צָרָֽה׃","ẇ⁠ţĕş̌ẇʻa֣ţ ẕa֭di̇yqiym mé⁠yĕhwá֑h máֽ֝ʻẇzá̇֗⁠m bĕ̇⁠ʻé֣ţ ẕáráֽh׃"],[37,40,"וַֽ⁠יַּעְזְרֵ֥⁠ם יְהוָ֗ה וַֽ⁠יְפַ֫לְּטֵ֥⁠ם יְפַלְּטֵ֣⁠ם מֵ֭⁠רְשָׁעִים וְ⁠יוֹשִׁיעֵ֑⁠ם כִּי־חָ֥סוּ בֽ⁠וֹ׃","waֽ⁠yȧʻĕzĕré֥⁠m yĕhwá֗h waֽ⁠yĕpa֫lĕ̇té֥⁠m yĕpalĕ̇té֣⁠m mé֭⁠rĕşá̌ʻiym wĕ⁠ywòşǐyʻé֑⁠m ki̇y-ẖá֥sẇ bֽ⁠wò׃"],[38,1,"יְֽהוָ֗ה אַל־בְּ⁠קֶצְפְּ⁠ךָ֥ תוֹכִיחֵ֑⁠נִי וּֽ⁠בַ⁠חֲמָתְ⁠ךָ֥ תְיַסְּרֵֽ⁠נִי׃","yĕֽhwá֗h ʼal-bĕ̇⁠qeẕĕpĕ̇⁠ká֥ ţwòkiyẖé֑⁠niy ẇֽ⁠ba⁠ẖàmáţĕ⁠ká֥ ţĕyasĕ̇réֽ⁠niy׃"],[38,2,"כִּֽי־חִ֭צֶּי⁠ךָ נִ֣חֲתוּ בִ֑⁠י וַ⁠תִּנְחַ֖ת עָלַ֣⁠י יָדֶֽ⁠ךָ׃","kiֽ̇y-ẖi֭ẕėy⁠ká ni֣ẖàţẇ bi֑⁠y wa⁠ţi̇nĕẖa֖ţ ʻála֣⁠y yádeֽ⁠ká׃"],[38,3,"אֵין־מְתֹ֣ם בִּ֭⁠בְשָׂרִ⁠י מִ⁠פְּנֵ֣י זַעְמֶ֑⁠ךָ אֵין־שָׁל֥וֹם בַּ֝⁠עֲצָמַ֗⁠י מִ⁠פְּנֵ֥י חַטָּאתִֽ⁠י׃","ʼéyn-mĕţò֣m bi֭̇⁠bĕşá̂ri⁠y mi⁠pĕ̇né֣y zaʻĕme֑⁠ká ʼéyn-şá̌l֥wòm bȧ֝⁠ʻàẕáma֗⁠y mi⁠pĕ̇né֥y ẖatá̇ʼţiֽ⁠y׃"],[38,4,"כִּ֣י עֲ֭וֺנֹתַ⁠י עָבְר֣וּ רֹאשִׁ֑⁠י כְּ⁠מַשָּׂ֥א כָ֝בֵ֗ד יִכְבְּד֥וּ מִמֶּֽ⁠נִּי׃","ki֣̇y ʻà֭wֺnòţa⁠y ʻábĕr֣ẇ ròʼşǐ֑⁠y kĕ̇⁠maşá֥̇̂ʼ ká֝bé֗d yikĕbĕ̇d֥ẇ mimėֽ⁠ni̇y׃"],[38,5,"הִבְאִ֣ישׁוּ נָ֭מַקּוּ חַבּוּרֹתָ֑⁠י מִ֝⁠פְּנֵ֗י אִוַּלְתִּֽ⁠י׃","hibĕʼi֣yş̌ẇ ná֭maq̇ẇ ẖaḃẇròţá֑⁠y mi֝⁠pĕ̇né֗y ʼiwȧlĕţiֽ̇⁠y׃"],[38,6,"נַעֲוֵ֣יתִי שַׁחֹ֣תִי עַד־מְאֹ֑ד כָּל־הַ֝⁠יּ֗וֹם קֹדֵ֥ר הִלָּֽכְתִּי׃","naʻàwé֣yţiy şǎẖò֣ţiy ʻad-mĕʼò֑d ká̇l-ha֝⁠ẏ֗wòm qòdé֥r hiláֽ̇kĕţi̇y׃"],[38,7,"כִּֽי־כְ֭סָלַ⁠י מָלְא֣וּ נִקְלֶ֑ה וְ⁠אֵ֥ין מְ֝תֹ֗ם בִּ⁠בְשָׂרִֽ⁠י׃","kiֽ̇y-kĕ֭sála⁠y málĕʼ֣ẇ niqĕle֑h wĕ⁠ʼé֥yn mĕ֝ţò֗m bi̇⁠bĕşá̂riֽ⁠y׃"],[38,8,"נְפוּג֣וֹתִי וְ⁠נִדְכֵּ֣יתִי עַד־מְאֹ֑ד שָׁ֝אַ֗גְתִּי מִֽ⁠נַּהֲמַ֥ת לִבִּֽ⁠י׃","nĕpẇg֣wòţiy wĕ⁠nidĕké֣̇yţiy ʻad-mĕʼò֑d şá̌֝ʼa֗gĕţi̇y miֽ⁠nȧhàma֥ţ libiֽ̇⁠y׃"],[38,9,"אֲֽדֹנָ⁠י נֶגְדְּ⁠ךָ֥ כָל־תַּאֲוָתִ֑⁠י וְ֝⁠אַנְחָתִ֗⁠י מִמְּ⁠ךָ֥ לֹא־נִסְתָּֽרָה׃","ʼàֽdòná⁠y negĕdĕ̇⁠ká֥ kál-ţȧʼàwáţi֑⁠y wĕ֝⁠ʼanĕẖáţi֗⁠y mimĕ̇⁠ká֥ lòʼ-nisĕţáֽ̇ráh׃"],[38,10,"לִבִּ֣⁠י סְ֭חַרְחַר עֲזָבַ֣⁠נִי כֹחִ֑⁠י וְֽ⁠אוֹר־עֵינַ֥⁠י גַּם־הֵ֝֗ם אֵ֣ין אִתִּֽ⁠י׃","libi֣̇⁠y sĕ֭ẖarĕẖar ʻàzába֣⁠niy kòẖi֑⁠y wĕֽ⁠ʼwòr-ʻéyna֥⁠y gȧm-hé֝֗m ʼé֣yn ʼiţiֽ̇⁠y׃"],[38,11,"אֹֽהֲבַ֨⁠י ׀ וְ⁠רֵעַ֗⁠י מִ⁠נֶּ֣גֶד נִגְעִ֣⁠י יַעֲמֹ֑דוּ וּ֝⁠קְרוֹבַ֗⁠י מֵ⁠רָחֹ֥ק עָמָֽדוּ׃","ʼòֽhàba֨⁠y ׀ wĕ⁠réʻa֗⁠y mi⁠nė֣ged nigĕʻi֣⁠y yaʻàmò֑dẇ ẇ֝⁠qĕrwòba֗⁠y mé⁠ráẖò֥q ʻámáֽdẇ׃"],[38,12,"וַ⁠יְנַקְשׁ֤וּ ׀ מְבַקְשֵׁ֬י נַפְשִׁ֗⁠י וְ⁠דֹרְשֵׁ֣י רָ֭עָתִ⁠י דִּבְּר֣וּ הַוּ֑וֹת וּ֝⁠מִרְמ֗וֹת כָּל־הַ⁠יּ֥וֹם יֶהְגּֽוּ׃","wa⁠yĕnaqĕş֤̌ẇ ׀ mĕbaqĕşé̌֬y napĕşǐ֗⁠y wĕ⁠dòrĕşé֣̌y rá֭ʻáţi⁠y di̇bĕ̇r֣ẇ haẇ֑wòţ ẇ֝⁠mirĕm֗wòţ ká̇l-ha⁠ẏ֥wòm yehĕġֽẇ׃"],[38,13,"וַ⁠אֲנִ֣י כְ֭⁠חֵרֵשׁ לֹ֣א אֶשְׁמָ֑ע וּ֝⁠כְ⁠אִלֵּ֗ם לֹ֣א יִפְתַּח־פִּֽי⁠ו׃","wa⁠ʼàni֣y kĕ֭⁠ẖéréş̌ lò֣ʼ ʼeşĕ̌má֑ʻ ẇ֝⁠kĕ⁠ʼilé̇֗m lò֣ʼ yipĕţȧẖ-piֽ̇y⁠w׃"],[38,14,"וָ⁠אֱהִ֗י כְּ֭⁠אִישׁ אֲשֶׁ֣ר לֹא־שֹׁמֵ֑עַ וְ⁠אֵ֥ין בְּ֝⁠פִ֗י⁠ו תּוֹכָחֽוֹת׃","wá⁠ʼèhi֗y kĕ֭̇⁠ʼiyş̌ ʼàşě֣r lòʼ-şò̌mé֑ʻa wĕ⁠ʼé֥yn bĕ̇֝⁠pi֗y⁠w ţ̇wòkáẖֽwòţ׃"],[38,15,"כִּֽי־לְ⁠ךָ֣ יְהוָ֣ה הוֹחָ֑לְתִּי אַתָּ֥ה תַ֝עֲנֶ֗ה אֲדֹנָ֥⁠י אֱלֹהָֽ⁠י׃","kiֽ̇y-lĕ⁠ká֣ yĕhwá֣h hwòẖá֑lĕţi̇y ʼaţá֥̇h ţa֝ʻàne֗h ʼàdòná֥⁠y ʼèlòháֽ⁠y׃"],[38,16,"כִּֽי־אָ֭מַרְתִּי פֶּן־יִשְׂמְחוּ־לִ֑⁠י בְּ⁠מ֥וֹט רַ֝גְלִ֗⁠י עָלַ֥⁠י הִגְדִּֽילוּ׃","kiֽ̇y-ʼá֭marĕţi̇y pėn-yişĕ̂mĕẖẇ-li֑⁠y bĕ̇⁠m֥wòt ra֝gĕli֗⁠y ʻála֥⁠y higĕdiֽ̇ylẇ׃"],[38,17,"כִּֽי־אֲ֭נִי לְ⁠צֶ֣לַע נָכ֑וֹן וּ⁠מַכְאוֹבִ֖⁠י נֶגְדִּ֣⁠י תָמִֽיד׃","kiֽ̇y-ʼà֭niy lĕ⁠ẕe֣laʻ nák֑wòn ẇ⁠makĕʼwòbi֖⁠y negĕdi֣̇⁠y ţámiֽyd׃"],[38,18,"כִּֽי־עֲוֺנִ֥⁠י אַגִּ֑יד אֶ֝דְאַ֗ג מֵֽ⁠חַטָּאתִֽ⁠י׃","kiֽ̇y-ʻàwֺni֥⁠y ʼagi֑̇yd ʼe֝dĕʼa֗g méֽ⁠ẖatá̇ʼţiֽ⁠y׃"],[38,19,"וְֽ֭⁠אֹיְבַ⁠י חַיִּ֣ים עָצֵ֑מוּ וְ⁠רַבּ֖וּ שֹׂנְאַ֣⁠י שָֽׁקֶר׃","wĕֽ֭⁠ʼòyĕba⁠y ẖayi֣̇ym ʻáẕé֑mẇ wĕ⁠raḃ֖ẇ şò̂nĕʼa֣⁠y şáֽ̌qer׃"],[38,20,"וּ⁠מְשַׁלְּמֵ֣י רָ֭עָה תַּ֣חַת טוֹבָ֑ה יִ֝שְׂטְנ֗וּ⁠נִי תַּ֣חַת רדופ⁠י־טֽוֹב׃","ẇ⁠mĕşǎlĕ̇mé֣y rá֭ʻáh ţȧ֣ẖaţ twòbá֑h yi֝şĕ̂tĕn֗ẇ⁠niy ţȧ֣ẖaţ rdwp⁠y-tֽwòb׃"],[38,21,"אַל־תַּֽעַזְבֵ֥⁠נִי יְהוָ֑ה אֱ֝לֹהַ֗⁠י אַל־תִּרְחַ֥ק מִמֶּֽ⁠נִּי׃","ʼal-ţȧֽʻazĕbé֥⁠niy yĕhwá֑h ʼè֝lòha֗⁠y ʼal-ţi̇rĕẖa֥q mimėֽ⁠ni̇y׃"],[38,22,"ח֥וּשָׁ⁠ה לְ⁠עֶזְרָתִ֑⁠י אֲ֝דֹנָ֗⁠י תְּשׁוּעָתִֽ⁠י׃","ẖ֥ẇşá̌⁠h lĕ⁠ʻezĕráţi֑⁠y ʼà֝dòná֗⁠y ţĕ̇ş̌ẇʻáţiֽ⁠y׃"],[39,1,"אָמַ֗רְתִּי אֶֽשְׁמְרָ֣ה דְרָכַ⁠י֮ מֵ⁠חֲט֪וֹא בִ⁠לְשׁ֫וֹנִ֥⁠י אֶשְׁמְרָ֥ה לְ⁠פִ֥⁠י מַחְס֑וֹם בְּ⁠עֹ֖ד רָשָׁ֣ע לְ⁠נֶגְדִּֽ⁠י׃","ʼáma֗rĕţi̇y ʼeֽşĕ̌mĕrá֣h dĕráka⁠y֮ mé⁠ẖàt֪wòʼ bi⁠lĕş̌֫wòni֥⁠y ʼeşĕ̌mĕrá֥h lĕ⁠pi֥⁠y maẖĕs֑wòm bĕ̇⁠ʻò֖d ráşá֣̌ʻ lĕ⁠negĕdiֽ̇⁠y׃"],[39,2,"נֶאֱלַ֣מְתִּי ד֭וּמִיָּה הֶחֱשֵׁ֣יתִי מִ⁠טּ֑וֹב וּ⁠כְאֵבִ֥⁠י נֶעְכָּֽר׃","neʼèla֣mĕţi̇y d֭ẇmiyá̇h heẖèşé֣̌yţiy mi⁠ṫ֑wòb ẇ⁠kĕʼébi֥⁠y neʻĕkáֽ̇r׃"],[39,3,"חַם־לִבִּ֨⁠י ׀ בְּ⁠קִרְבִּ֗⁠י בַּ⁠הֲגִיגִ֥⁠י תִבְעַר־אֵ֑שׁ דִּ֝בַּ֗רְתִּי בִּ⁠לְשֽׁוֹנִ⁠י׃","ẖam-libi̇֨⁠y ׀ bĕ̇⁠qirĕbi̇֗⁠y bȧ⁠hàgiygi֥⁠y ţibĕʻar-ʼé֑ş̌ di̇֝bȧ֗rĕţi̇y bi̇⁠lĕşֽ̌wòni⁠y׃"],[39,4,"הוֹדִ֘יעֵ֤⁠נִי יְהוָ֨ה ׀ קִצִּ֗⁠י וּ⁠מִדַּ֣ת יָמַ֣⁠י מַה־הִ֑יא אֵ֝דְעָ֗ה מֶה־חָדֵ֥ל אָֽנִי׃","hwòdi֘yʻé֤⁠niy yĕhwá֨h ׀ qiẕi̇֗⁠y ẇ⁠midȧ֣ţ yáma֣⁠y mah-hi֑yʼ ʼé֝dĕʻá֗h meh-ẖádé֥l ʼáֽniy׃"],[39,5,"הִנֵּ֤ה טְפָח֨וֹת ׀ נָ֘תַ֤תָּה יָמַ֗⁠י וְ⁠חֶלְדִּ֣⁠י כְ⁠אַ֣יִן נֶגְדֶּ֑⁠ךָ אַ֥ךְ כָּֽל־הֶ֥בֶל כָּל־אָ֝דָ֗ם נִצָּ֥ב סֶֽלָה׃","hiné֤̇h tĕpáẖ֨wòţ ׀ ná֘ţa֤ţá̇h yáma֗⁠y wĕ⁠ẖelĕdi֣̇⁠y kĕ⁠ʼa֣yin negĕdė֑⁠ká ʼa֥kĕ káֽ̇l-he֥bel ká̇l-ʼá֝dá֗m niẕá֥̇b seֽláh׃"],[39,6,"אַךְ־בְּ⁠צֶ֤לֶם ׀ יִֽתְהַלֶּךְ־אִ֗ישׁ אַךְ־הֶ֥בֶל יֶהֱמָי֑וּ⁠ן יִ֝צְבֹּ֗ר וְֽ⁠לֹא־יֵדַ֥ע מִי־אֹסְפָֽ⁠ם׃","ʼakĕ-bĕ̇⁠ẕe֤lem ׀ yiֽţĕhalėkĕ-ʼi֗yş̌ ʼakĕ-he֥bel yehèmáy֑ẇ⁠n yi֝ẕĕbò̇֗r wĕֽ⁠lòʼ-yéda֥ʻ miy-ʼòsĕpáֽ⁠m׃"],[39,7,"וְ⁠עַתָּ֣ה מַה־קִּוִּ֣יתִי אֲדֹנָ֑⁠י תּ֝וֹחַלְתִּ֗⁠י לְ⁠ךָ֣ הִֽיא׃","wĕ⁠ʻaţá֣̇h mah-qi̇wi֣̇yţiy ʼàdòná֑⁠y ţ̇֝wòẖalĕţi̇֗⁠y lĕ⁠ká֣ hiֽyʼ׃"],[39,8,"מִ⁠כָּל־פְּשָׁעַ֥⁠י הַצִּילֵ֑⁠נִי חֶרְפַּ֥ת נָ֝בָ֗ל אַל־תְּשִׂימֵֽ⁠נִי׃","mi⁠ká̇l-pĕ̇şá̌ʻa֥⁠y haẕi̇ylé֑⁠niy ẖerĕpȧ֥ţ ná֝bá֗l ʼal-ţĕ̇şîyméֽ⁠niy׃"],[39,9,"נֶ֭אֱלַמְתִּי לֹ֣א אֶפְתַּח־פִּ֑⁠י כִּ֖י אַתָּ֣ה עָשִֽׂיתָ׃","ne֭ʼèlamĕţi̇y lò֣ʼ ʼepĕţȧẖ-pi֑̇⁠y ki֖̇y ʼaţá֣̇h ʻáşîֽyţá׃"],[39,10,"הָסֵ֣ר מֵ⁠עָלַ֣⁠י נִגְעֶ֑⁠ךָ מִ⁠תִּגְרַ֥ת יָ֝דְ⁠ךָ֗ אֲנִ֣י כָלִֽיתִי׃","hásé֣r mé⁠ʻála֣⁠y nigĕʻe֑⁠ká mi⁠ţi̇gĕra֥ţ yá֝dĕ⁠ká֗ ʼàni֣y káliֽyţiy׃"],[39,11,"בְּֽ⁠תוֹכָ֘ח֤וֹת עַל־עָוֺ֨ן ׀ יִסַּ֬רְתָּ אִ֗ישׁ וַ⁠תֶּ֣מֶס כָּ⁠עָ֣שׁ חֲמוּד֑⁠וֹ אַ֤ךְ הֶ֖בֶל כָּל־אָדָ֣ם סֶֽלָה׃","bĕֽ̇⁠ţwòká֘ẖ֤wòţ ʻal-ʻáwֺ֨n ׀ yisȧ֬rĕţá̇ ʼi֗yş̌ wa⁠ţė֣mes ká̇⁠ʻá֣ş̌ ẖàmẇd֑⁠wò ʼa֤kĕ he֖bel ká̇l-ʼádá֣m seֽláh׃"],[39,12,"שִֽׁמְעָ֥⁠ה־תְפִלָּתִ֨⁠י ׀ יְהוָ֡ה וְ⁠שַׁוְעָתִ֨⁠י ׀ הַאֲזִינָ⁠ה֮ אֶֽל־דִּמְעָתִ֗⁠י אַֽל־תֶּ֫חֱרַ֥שׁ כִּ֤י גֵ֣ר אָנֹכִ֣י עִמָּ֑⁠ךְ תּ֝וֹשָׁ֗ב כְּ⁠כָל־אֲבוֹתָֽ⁠י׃","şǐֽmĕʻá֥⁠h-ţĕpilá̇ţi֨⁠y ׀ yĕhwá֡h wĕ⁠şǎwĕʻáţi֨⁠y ׀ haʼàziyná⁠h֮ ʼeֽl-di̇mĕʻáţi֗⁠y ʼaֽl-ţė֫ẖèra֥ş̌ ki֤̇y gé֣r ʼánòki֣y ʻimá֑̇⁠kĕ ţ̇֝wòşá̌֗b kĕ̇⁠kál-ʼàbwòţáֽ⁠y׃"],[39,13,"הָשַׁ֣ע מִמֶּ֣⁠נִּי וְ⁠אַבְלִ֑יגָה בְּ⁠טֶ֖רֶם אֵלֵ֣ךְ וְ⁠אֵינֶֽ⁠נִּי׃","háşǎ֣ʻ mimė֣⁠ni̇y wĕ⁠ʼabĕli֑ygáh bĕ̇⁠te֖rem ʼélé֣kĕ wĕ⁠ʼéyneֽ⁠ni̇y׃"],[40,1,"קַוֺּ֣ה קִוִּ֣יתִי יְהוָ֑ה וַ⁠יֵּ֥ט אֵ֝לַ֗⁠י וַ⁠יִּשְׁמַ֥ע שַׁוְעָתִֽ⁠י׃","qaẇֺ֣h qiwi֣̇yţiy yĕhwá֑h wa⁠yé֥̇t ʼé֝la֗⁠y wa⁠yi̇şĕ̌ma֥ʻ şǎwĕʻáţiֽ⁠y׃"],[40,2,"וַ⁠יַּעֲלֵ֤⁠נִי ׀ מִ⁠בּ֥וֹר שָׁאוֹן֮ מִ⁠טִּ֪יט הַ⁠יָּ֫וֵ֥ן וַ⁠יָּ֖קֶם עַל־סֶ֥לַע רַגְלַ֗⁠י כּוֹנֵ֥ן אֲשֻׁרָֽ⁠י׃","wa⁠yȧʻàlé֤⁠niy ׀ mi⁠ḃ֥wòr şá̌ʼwòn֮ mi⁠ti֪̇yt ha⁠yá̇֫wé֥n wa⁠yá֖̇qem ʻal-se֥laʻ ragĕla֗⁠y k̇wòné֥n ʼàşǔráֽ⁠y׃"],[40,3,"וַ⁠יִּתֵּ֬ן בְּ⁠פִ֨⁠י ׀ שִׁ֥יר חָדָשׁ֮ תְּהִלָּ֪ה לֵֽ⁠אלֹ֫הֵ֥י⁠נוּ יִרְא֣וּ רַבִּ֣ים וְ⁠יִירָ֑אוּ וְ֝⁠יִבְטְח֗וּ בַּ⁠יהוָֽה׃","wa⁠yi̇ţé̇֬n bĕ̇⁠pi֨⁠y ׀ şǐ֥yr ẖádáş֮̌ ţĕ̇hilá֪̇h léֽ⁠ʼlò֫hé֥y⁠nẇ yirĕʼ֣ẇ rabi֣̇ym wĕ⁠yiyrá֑ʼẇ wĕ֝⁠yibĕtĕẖ֗ẇ bȧ⁠yhwáֽh׃"],[40,4,"אַ֥שְֽׁרֵי הַ⁠גֶּ֗בֶר אֲשֶׁר־שָׂ֣ם יְ֭הֹוָה מִבְטַח֑⁠וֹ וְֽ⁠לֹא־פָנָ֥ה אֶל־רְ֝הָבִ֗ים וְ⁠שָׂטֵ֥י כָזָֽב׃","ʼa֥şĕֽ̌réy ha⁠gė֗ber ʼàşěr-şá֣̂m yĕ֭hòwáh mibĕtaẖ֑⁠wò wĕֽ⁠lòʼ-páná֥h ʼel-rĕ֝hábi֗ym wĕ⁠şá̂té֥y kázáֽb׃"],[40,5,"רַבּ֤וֹת עָשִׂ֨יתָ ׀ אַתָּ֤ה ׀ יְהוָ֣ה אֱלֹהַ⁠י֮ נִֽפְלְאֹתֶ֥י⁠ךָ וּ⁠מַחְשְׁבֹתֶ֗י⁠ךָ אֵ֫לֵ֥י⁠נוּ אֵ֤ין ׀ עֲרֹ֬ךְ אֵלֶ֗י⁠ךָ אַגִּ֥ידָה וַ⁠אֲדַבֵּ֑רָה עָ֝צְמ֗וּ מִ⁠סַּפֵּֽר׃","raḃ֤wòţ ʻáşî֨yţá ׀ ʼaţá֤̇h ׀ yĕhwá֣h ʼèlòha⁠y֮ niֽpĕlĕʼòţe֥y⁠ká ẇ⁠maẖĕşĕ̌bòţe֗y⁠ká ʼé֫lé֥y⁠nẇ ʼé֤yn ׀ ʻàrò֬kĕ ʼéle֗y⁠ká ʼagi֥̇ydáh wa⁠ʼàdabé֑̇ráh ʻá֝ẕĕm֗ẇ mi⁠sȧpéֽ̇r׃"],[40,6,"זֶ֤בַח וּ⁠מִנְחָ֨ה ׀ לֹֽא־חָפַ֗צְתָּ אָ֭זְנַיִם כָּרִ֣יתָ לִּ֑⁠י עוֹלָ֥ה וַ֝⁠חֲטָאָ֗ה לֹ֣א שָׁאָֽלְתָּ׃","ze֤baẖ ẇ⁠minĕẖá֨h ׀ lòֽʼ-ẖápa֗ẕĕţá̇ ʼá֭zĕnayim ká̇ri֣yţá li֑̇⁠y ʻwòlá֥h wa֝⁠ẖàtáʼá֗h lò֣ʼ şá̌ʼáֽlĕţá̇׃"],[40,7,"אָ֣ז אָ֭מַרְתִּי הִנֵּה־בָ֑אתִי בִּ⁠מְגִלַּת־סֵ֝֗פֶר כָּת֥וּב עָלָֽ⁠י׃","ʼá֣z ʼá֭marĕţi̇y hiné̇h-bá֑ʼţiy bi̇⁠mĕgilȧţ-sé֝֗per ká̇ţ֥ẇb ʻáláֽ⁠y׃"],[40,8,"לַֽ⁠עֲשֽׂוֹת־רְצוֹנְ⁠ךָ֣ אֱלֹהַ֣⁠י חָפָ֑צְתִּי וְ֝⁠ת֥וֹרָתְ⁠ךָ֗ בְּ⁠ת֣וֹךְ מֵעָֽ⁠י׃","laֽ⁠ʻàşֽ̂wòţ-rĕẕwònĕ⁠ká֣ ʼèlòha֣⁠y ẖápá֑ẕĕţi̇y wĕ֝⁠ţ֥wòráţĕ⁠ká֗ bĕ̇⁠ţ֣wòkĕ méʻáֽ⁠y׃"],[40,9,"בִּשַּׂ֤רְתִּי צֶ֨דֶק ׀ בְּ⁠קָ֘הָ֤ל רָ֗ב הִנֵּ֣ה שְׂ֭פָתַ⁠י לֹ֣א אֶכְלָ֑א יְ֝הוָ֗ה אַתָּ֥ה יָדָֽעְתָּ׃","bi̇şȧ֤̂rĕţi̇y ẕe֨deq ׀ bĕ̇⁠qá֘há֤l rá֗b hiné֣̇h şĕ֭̂páţa⁠y lò֣ʼ ʼekĕlá֑ʼ yĕ֝hwá֗h ʼaţá֥̇h yádáֽʻĕţá̇׃"],[40,10,"צִדְקָתְ⁠ךָ֬ לֹא־כִסִּ֨יתִי ׀ בְּ⁠ת֬וֹךְ לִבִּ֗⁠י אֱמוּנָתְ⁠ךָ֣ וּ⁠תְשׁוּעָתְ⁠ךָ֣ אָמָ֑רְתִּי לֹא־כִחַ֥דְתִּי חַסְדְּ⁠ךָ֥ וַ֝⁠אֲמִתְּ⁠ךָ֗ לְ⁠קָהָ֥ל רָֽב׃","ẕidĕqáţĕ⁠ká֬ lòʼ-kisi̇֨yţiy ׀ bĕ̇⁠ţ֬wòkĕ libi̇֗⁠y ʼèmẇnáţĕ⁠ká֣ ẇ⁠ţĕş̌ẇʻáţĕ⁠ká֣ ʼámá֑rĕţi̇y lòʼ-kiẖa֥dĕţi̇y ẖasĕdĕ̇⁠ká֥ wa֝⁠ʼàmiţĕ̇⁠ká֗ lĕ⁠qáhá֥l ráֽb׃"],[40,11,"אַתָּ֤ה יְהוָ֗ה לֹא־תִכְלָ֣א רַחֲמֶ֣י⁠ךָ מִמֶּ֑⁠נִּי חַסְדְּ⁠ךָ֥ וַ֝⁠אֲמִתְּ⁠ךָ֗ תָּמִ֥יד יִצְּרֽוּ⁠נִי׃","ʼaţá֤̇h yĕhwá֗h lòʼ-ţikĕlá֣ʼ raẖàme֣y⁠ká mimė֑⁠ni̇y ẖasĕdĕ̇⁠ká֥ wa֝⁠ʼàmiţĕ̇⁠ká֗ ţá̇mi֥yd yiẕĕ̇rֽẇ⁠niy׃"],[40,12,"כִּ֤י אָפְפ֥וּ־עָלַ֨⁠י ׀ רָע֡וֹת עַד־אֵ֬ין מִסְפָּ֗ר הִשִּׂיג֣וּ⁠נִי עֲ֭וֺנֹתַ⁠י וְ⁠לֹא־יָכֹ֣לְתִּי לִ⁠רְא֑וֹת עָצְמ֥וּ מִ⁠שַּֽׂעֲר֥וֹת רֹ֝אשִׁ֗⁠י וְ⁠לִבִּ֥⁠י עֲזָבָֽ⁠נִי׃","ki֤̇y ʼápĕp֥ẇ-ʻála֨⁠y ׀ ráʻ֡wòţ ʻad-ʼé֬yn misĕpá̇֗r hişi̇̂yg֣ẇ⁠niy ʻà֭wֺnòţa⁠y wĕ⁠lòʼ-yákò֣lĕţi̇y li⁠rĕʼ֑wòţ ʻáẕĕm֥ẇ mi⁠şȧֽ̂ʻàr֥wòţ rò֝ʼşǐ֗⁠y wĕ⁠libi֥̇⁠y ʻàzábáֽ⁠niy׃"],[40,13,"רְצֵ֣ה יְ֭הוָה לְ⁠הַצִּילֵ֑⁠נִי יְ֝הוָ֗ה לְ⁠עֶזְרָ֥תִ⁠י חֽוּשָׁ⁠ה׃","rĕẕé֣h yĕ֭hwáh lĕ⁠haẕi̇ylé֑⁠niy yĕ֝hwá֗h lĕ⁠ʻezĕrá֥ţi⁠y ẖֽẇşá̌⁠h׃"],[40,14,"יֵ֘בֹ֤שׁוּ וְ⁠יַחְפְּר֨וּ ׀ יַחַד֮ מְבַקְשֵׁ֥י נַפְשִׁ֗⁠י לִ⁠סְפּ֫וֹתָ֥⁠הּ יִסֹּ֣גוּ אָ֭חוֹר וְ⁠יִכָּלְמ֑וּ חֲ֝פֵצֵ֗י רָעָתִֽ⁠י׃","yé֘bò֤ş̌ẇ wĕ⁠yaẖĕpĕ̇r֨ẇ ׀ yaẖad֮ mĕbaqĕşé֥̌y napĕşǐ֗⁠y li⁠sĕṗ֫wòţá֥⁠ḣ yisò֣̇gẇ ʼá֭ẖwòr wĕ⁠yiká̇lĕm֑ẇ ẖà֝péẕé֗y ráʻáţiֽ⁠y׃"],[40,15,"יָ֭שֹׁמּוּ עַל־עֵ֣קֶב בָּשְׁתָּ֑⁠ם הָ⁠אֹמְרִ֥ים לִ֝֗⁠י הֶ֘אָ֥ח ׀ הֶאָֽח׃","yá֭şò̌ṁẇ ʻal-ʻé֣qeb bá̇şĕ̌ţá֑̇⁠m há⁠ʼòmĕri֥ym li֝֗⁠y he֘ʼá֥ẖ ׀ heʼáֽẖ׃"],[40,16,"יָ֘שִׂ֤ישׂוּ וְ⁠יִשְׂמְח֨וּ ׀ בְּ⁠ךָ֗ כָּֽל־מְבַ֫קְשֶׁ֥י⁠ךָ יֹאמְר֣וּ תָ֭מִיד יִגְדַּ֣ל יְהוָ֑ה אֹֽ֝הֲבֵ֗י תְּשׁוּעָתֶֽ⁠ךָ׃","yá֘şî֤yş̂ẇ wĕ⁠yişĕ̂mĕẖ֨ẇ ׀ bĕ̇⁠ká֗ káֽ̇l-mĕba֫qĕşě֥y⁠ká yòʼmĕr֣ẇ ţá֭miyd yigĕdȧ֣l yĕhwá֑h ʼòֽ֝hàbé֗y ţĕ̇ş̌ẇʻáţeֽ⁠ká׃"],[40,17,"וַ⁠אֲנִ֤י ׀ עָנִ֣י וְ⁠אֶבְיוֹן֮ אֲדֹנָ֪⁠י יַחֲשָׁ֫ב לִ֥⁠י עֶזְרָתִ֣⁠י וּ⁠מְפַלְטִ֣⁠י אַ֑תָּה אֱ֝לֹהַ֗⁠י אַל־תְּאַחַֽר׃","wa⁠ʼàni֤y ׀ ʻáni֣y wĕ⁠ʼebĕywòn֮ ʼàdòná֪⁠y yaẖàşá̌֫b li֥⁠y ʻezĕráţi֣⁠y ẇ⁠mĕpalĕti֣⁠y ʼa֑ţá̇h ʼè֝lòha֗⁠y ʼal-ţĕ̇ʼaẖaֽr׃"],[41,1,"אַ֭שְׁרֵי מַשְׂכִּ֣יל אֶל־דָּ֑ל בְּ⁠י֥וֹם רָ֝עָ֗ה יְֽמַלְּטֵ֥⁠הוּ יְהוָֽה׃","ʼa֭şĕ̌réy maşĕ̂ki֣̇yl ʼel-dá֑̇l bĕ̇⁠y֥wòm rá֝ʻá֗h yĕֽmalĕ̇té֥⁠hẇ yĕhwáֽh׃"],[41,2,"יְהוָ֤ה ׀ יִשְׁמְרֵ֣⁠הוּ וִֽ֭⁠יחַיֵּ⁠הוּ יאשר בָּ⁠אָ֑רֶץ וְ⁠אַֽל־תִּ֝תְּנֵ֗⁠הוּ בְּ⁠נֶ֣פֶשׁ אֹיְבָֽי⁠ו׃","yĕhwá֤h ׀ yişĕ̌mĕré֣⁠hẇ wiֽ֭⁠yẖayé̇⁠hẇ yʼşr bá̇⁠ʼá֑reẕ wĕ⁠ʼaֽl-ţi̇֝ţĕ̇né֗⁠hẇ bĕ̇⁠ne֣peş̌ ʼòyĕbáֽy⁠w׃"],[41,3,"יְֽהוָ֗ה יִ֭סְעָדֶ⁠נּוּ עַל־עֶ֣רֶשׂ דְּוָ֑י כָּל־מִ֝שְׁכָּב֗⁠וֹ הָפַ֥כְתָּ בְ⁠חָלְיֽ⁠וֹ׃","yĕֽhwá֗h yi֭sĕʻáde⁠ṅẇ ʻal-ʻe֣reş̂ dĕ̇wá֑y ká̇l-mi֝şĕ̌ká̇b֗⁠wò hápa֥kĕţá̇ bĕ⁠ẖálĕyֽ⁠wò׃"],[41,4,"אֲֽנִי־אָ֭מַרְתִּי יְהוָ֣ה חָנֵּ֑⁠נִי רְפָאָ֥⁠ה נַ֝פְשִׁ֗⁠י כִּי־חָטָ֥אתִי לָֽ⁠ךְ׃","ʼàֽniy-ʼá֭marĕţi̇y yĕhwá֣h ẖáné֑̇⁠niy rĕpáʼá֥⁠h na֝pĕşǐ֗⁠y ki̇y-ẖátá֥ʼţiy láֽ⁠kĕ׃"],[41,5,"אוֹיְבַ֗⁠י יֹאמְר֣וּ רַ֣ע לִ֑⁠י מָתַ֥י יָ֝מ֗וּת וְ⁠אָבַ֥ד שְׁמֽ⁠וֹ׃","ʼwòyĕba֗⁠y yòʼmĕr֣ẇ ra֣ʻ li֑⁠y máţa֥y yá֝m֗ẇţ wĕ⁠ʼába֥d şĕ̌mֽ⁠wò׃"],[41,6,"וְ⁠אִם־בָּ֤א לִ⁠רְא֨וֹת ׀ שָׁ֤וְא יְדַבֵּ֗ר לִבּ֗⁠וֹ יִקְבָּץ־אָ֥וֶן ל֑⁠וֹ יֵצֵ֖א לַ⁠ח֣וּץ יְדַבֵּֽר׃","wĕ⁠ʼim-bá֤̇ʼ li⁠rĕʼ֨wòţ ׀ şá֤̌wĕʼ yĕdabé̇֗r liḃ֗⁠wò yiqĕbá̇ẕ-ʼá֥wen l֑⁠wò yéẕé֖ʼ la⁠ẖ֣ẇẕ yĕdabéֽ̇r׃"],[41,7,"יַ֗חַד עָלַ֣⁠י יִ֭תְלַחֲשׁוּ כָּל־שֹׂנְאָ֑⁠י עָלַ֓⁠י ׀ יַחְשְׁב֖וּ רָעָ֣ה לִֽ⁠י׃","ya֗ẖad ʻála֣⁠y yi֭ţĕlaẖàş̌ẇ ká̇l-şò̂nĕʼá֑⁠y ʻála֓⁠y ׀ yaẖĕşĕ̌b֖ẇ ráʻá֣h liֽ⁠y׃"],[41,8,"דְּֽבַר־בְּ֭לִיַּעַל יָצ֣וּק בּ֑⁠וֹ וַ⁠אֲשֶׁ֥ר שָׁ֝כַ֗ב לֹא־יוֹסִ֥יף לָ⁠קֽוּם׃","dĕֽ̇bar-bĕ֭̇liyȧʻal yáẕ֣ẇq ḃ֑⁠wò wa⁠ʼàşě֥r şá̌֝ka֗b lòʼ-ywòsi֥yp lá⁠qֽẇm׃"],[41,9,"גַּם־אִ֤ישׁ שְׁלוֹמִ֨⁠י ׀ אֲשֶׁר־בָּטַ֣חְתִּי ב֭⁠וֹ אוֹכֵ֣ל לַחְמִ֑⁠י הִגְדִּ֖יל עָלַ֣⁠י עָקֵֽב׃","gȧm-ʼi֤yş̌ şĕ̌lwòmi֨⁠y ׀ ʼàşěr-bá̇ta֣ẖĕţi̇y b֭⁠wò ʼwòké֣l laẖĕmi֑⁠y higĕdi֖̇yl ʻála֣⁠y ʻáqéֽb׃"],[41,10,"וְ⁠אַתָּ֤ה יְהוָ֗ה חָנֵּ֥⁠נִי וַ⁠הֲקִימֵ֑⁠נִי וַֽ⁠אֲשַׁלְּמָ֥ה לָ⁠הֶֽם׃","wĕ⁠ʼaţá֤̇h yĕhwá֗h ẖáné֥̇⁠niy wa⁠hàqiymé֑⁠niy waֽ⁠ʼàşǎlĕ̇má֥h lá⁠heֽm׃"],[41,11,"בְּ⁠זֹ֣את יָ֭דַעְתִּי כִּֽי־חָפַ֣צְתָּ בִּ֑⁠י כִּ֤י לֹֽא־יָרִ֖יעַ אֹיְבִ֣⁠י עָלָֽ⁠י׃","bĕ̇⁠zò֣ʼţ yá֭daʻĕţi̇y kiֽ̇y-ẖápa֣ẕĕţá̇ bi֑̇⁠y ki֤̇y lòֽʼ-yári֖yʻa ʼòyĕbi֣⁠y ʻáláֽ⁠y׃"],[41,12,"וַ⁠אֲנִ֗י בְּ֭⁠תֻמִּ⁠י תָּמַ֣כְתָּ בִּ֑⁠י וַ⁠תַּצִּיבֵ֖⁠נִי לְ⁠פָנֶ֣י⁠ךָ לְ⁠עוֹלָֽם׃","wa⁠ʼàni֗y bĕ֭̇⁠ţumi̇⁠y ţá̇ma֣kĕţá̇ bi֑̇⁠y wa⁠ţȧẕi̇ybé֖⁠niy lĕ⁠páne֣y⁠ká lĕ⁠ʻwòláֽm׃"],[41,13,"בָּ֘ר֤וּךְ יְהוָ֨ה ׀ אֱלֹ֘הֵ֤י יִשְׂרָאֵ֗ל מֵֽ֭⁠הָ⁠עוֹלָם וְ⁠עַ֥ד הָ⁠עוֹלָ֗ם אָ֘מֵ֥ן ׀ וְ⁠אָמֵֽן׃","bá̇֘r֤ẇkĕ yĕhwá֨h ׀ ʼèlò֘hé֤y yişĕ̂ráʼé֗l méֽ֭⁠há⁠ʻwòlám wĕ⁠ʻa֥d há⁠ʻwòlá֗m ʼá֘mé֥n ׀ wĕ⁠ʼáméֽn׃"],[42,1,"כְּ⁠אַיָּ֗ל תַּעֲרֹ֥ג עַל־אֲפִֽיקֵי־מָ֑יִם כֵּ֤ן נַפְשִׁ֨⁠י תַעֲרֹ֖ג אֵלֶ֣י⁠ךָ אֱלֹהִֽים׃","kĕ̇⁠ʼayá̇֗l ţȧʻàrò֥g ʻal-ʼàpiֽyqéy-má֑yim ké֤̇n napĕşǐ֨⁠y ţaʻàrò֖g ʼéle֣y⁠ká ʼèlòhiֽym׃"],[42,2,"צָמְאָ֬ה נַפְשִׁ֨⁠י ׀ לֵ⁠אלֹהִים֮ לְ⁠אֵ֪ל חָ֥י מָתַ֥י אָב֑וֹא וְ֝⁠אֵרָאֶ֗ה פְּנֵ֣י אֱלֹהִֽים׃","ẕámĕʼá֬h napĕşǐ֨⁠y ׀ lé⁠ʼlòhiym֮ lĕ⁠ʼé֪l ẖá֥y máţa֥y ʼáb֑wòʼ wĕ֝⁠ʼéráʼe֗h pĕ̇né֣y ʼèlòhiֽym׃"],[42,3,"הָֽיְתָה־לִּ֬⁠י דִמְעָתִ֣⁠י לֶ֭חֶם יוֹמָ֣ם וָ⁠לָ֑יְלָה בֶּ⁠אֱמֹ֥ר אֵלַ֥⁠י כָּל־הַ֝⁠יּ֗וֹם אַיֵּ֥ה אֱלֹהֶֽי⁠ךָ׃","háֽyĕţáh-li̇֬⁠y dimĕʻáţi֣⁠y le֭ẖem ywòmá֣m wá⁠lá֑yĕláh bė⁠ʼèmò֥r ʼéla֥⁠y ká̇l-ha֝⁠ẏ֗wòm ʼayé֥̇h ʼèlòheֽy⁠ká׃"],[42,4,"אֵ֤לֶּה אֶזְכְּרָ֨ה ׀ וְ⁠אֶשְׁפְּכָ֬ה עָלַ֨⁠י ׀ נַפְשִׁ֗⁠י כִּ֤י אֶֽעֱבֹ֨ר ׀ בַּ⁠סָּךְ֮ אֶדַּדֵּ֗⁠ם עַד־בֵּ֥ית אֱלֹ֫הִ֥ים בְּ⁠קוֹל־רִנָּ֥ה וְ⁠תוֹדָ֗ה הָמ֥וֹן חוֹגֵֽג׃","ʼé֤lėh ʼezĕkĕ̇rá֨h ׀ wĕ⁠ʼeşĕ̌pĕ̇ká֬h ʻála֨⁠y ׀ napĕşǐ֗⁠y ki֤̇y ʼeֽʻèbò֨r ׀ bȧ⁠sá̇kĕ֮ ʼedȧdé̇֗⁠m ʻad-bé֥̇yţ ʼèlò֫hi֥ym bĕ̇⁠qwòl-riná֥̇h wĕ⁠ţwòdá֗h hám֥wòn ẖwògéֽg׃"],[42,5,"מַה־תִּשְׁתּ֬וֹחֲחִ֨י ׀ נַפְשִׁ⁠י֮ וַ⁠תֶּהֱמִ֪י עָ֫לָ֥⁠י הוֹחִ֣ילִי לֵֽ֭⁠אלֹהִים כִּי־ע֥וֹד אוֹדֶ֗⁠נּוּ יְשׁוּע֥וֹת פָּנָֽי⁠ו׃","mah-ţi̇şĕ̌ţ̇֬wòẖàẖi֨y ׀ napĕşǐ⁠y֮ wa⁠ţėhèmi֪y ʻá֫lá֥⁠y hwòẖi֣yliy léֽ֭⁠ʼlòhiym ki̇y-ʻ֥wòd ʼwòde֗⁠ṅẇ yĕş̌ẇʻ֥wòţ pá̇náֽy⁠w׃"],[42,6,"אֱֽלֹהַ֗⁠י עָלַ⁠י֮ נַפְשִׁ֪⁠י תִשְׁתּ֫וֹחָ֥ח עַל־כֵּ֗ן אֶ֭זְכָּרְ⁠ךָ מֵ⁠אֶ֣רֶץ יַרְדֵּ֑ן וְ֝⁠חֶרְמוֹנִ֗ים מֵ⁠הַ֥ר מִצְעָֽר׃","ʼèֽlòha֗⁠y ʻála⁠y֮ napĕşǐ֪⁠y ţişĕ̌ţ̇֫wòẖá֥ẖ ʻal-ké̇֗n ʼe֭zĕká̇rĕ⁠ká mé⁠ʼe֣reẕ yarĕdé֑̇n wĕ֝⁠ẖerĕmwòni֗ym mé⁠ha֥r miẕĕʻáֽr׃"],[42,7,"תְּהֽוֹם־אֶל־תְּה֣וֹם ק֭וֹרֵא לְ⁠ק֣וֹל צִנּוֹרֶ֑י⁠ךָ כָּֽל־מִשְׁבָּרֶ֥י⁠ךָ וְ֝⁠גַלֶּ֗י⁠ךָ עָלַ֥⁠י עָבָֽרוּ׃","ţĕ̇hֽwòm-ʼel-ţĕ̇h֣wòm q֭wòréʼ lĕ⁠q֣wòl ẕiṅwòre֑y⁠ká káֽ̇l-mişĕ̌bá̇re֥y⁠ká wĕ֝⁠galė֗y⁠ká ʻála֥⁠y ʻábáֽrẇ׃"],[42,8,"יוֹמָ֤ם ׀ יְצַוֶּ֬ה יְהוָ֨ה ׀ חַסְדּ֗⁠וֹ וּ֭⁠בַ⁠לַּיְלָה שיר⁠ה עִמִּ֑⁠י תְּ֝פִלָּ֗ה לְ⁠אֵ֣ל חַיָּֽ⁠י׃","ywòmá֤m ׀ yĕẕawė֬h yĕhwá֨h ׀ ẖasĕḋ֗⁠wò ẇ֭⁠ba⁠lȧyĕláh şyr⁠h ʻimi֑̇⁠y ţĕ̇֝pilá̇֗h lĕ⁠ʼé֣l ẖayáֽ̇⁠y׃"],[42,9,"אוֹמְרָ֤ה ׀ לְ⁠אֵ֥ל סַלְעִ⁠י֮ לָ⁠מָ֪ה שְׁכַ֫חְתָּ֥⁠נִי לָֽ⁠מָּה־קֹדֵ֥ר אֵלֵ֗ךְ בְּ⁠לַ֣חַץ אוֹיֵֽב׃","ʼwòmĕrá֤h ׀ lĕ⁠ʼé֥l salĕʻi⁠y֮ lá⁠má֪h şĕ̌ka֫ẖĕţá֥̇⁠niy láֽ⁠má̇h-qòdé֥r ʼélé֗kĕ bĕ̇⁠la֣ẖaẕ ʼwòyéֽb׃"],[42,10,"בְּ⁠רֶ֤צַח ׀ בְּֽ⁠עַצְמוֹתַ֗⁠י חֵרְפ֥וּ⁠נִי צוֹרְרָ֑⁠י בְּ⁠אָמְרָ֥⁠ם אֵלַ֥⁠י כָּל־הַ֝⁠יּ֗וֹם אַיֵּ֥ה אֱלֹהֶֽי⁠ךָ׃","bĕ̇⁠re֤ẕaẖ ׀ bĕֽ̇⁠ʻaẕĕmwòţa֗⁠y ẖérĕp֥ẇ⁠niy ẕwòrĕrá֑⁠y bĕ̇⁠ʼámĕrá֥⁠m ʼéla֥⁠y ká̇l-ha֝⁠ẏ֗wòm ʼayé֥̇h ʼèlòheֽy⁠ká׃"],[42,11,"מַה־תִּשְׁתּ֬וֹחֲחִ֨י ׀ נַפְשִׁ⁠י֮ וּֽ⁠מַה־תֶּהֱמִ֪י עָ֫לָ֥⁠י הוֹחִ֣ילִי לֵֽ֭⁠אלֹהִים כִּי־ע֣וֹד אוֹדֶ֑⁠נּוּ יְשׁוּעֹ֥ת פָּ֝נַ֗⁠י וֵֽ⁠אלֹהָֽ⁠י׃","mah-ţi̇şĕ̌ţ̇֬wòẖàẖi֨y ׀ napĕşǐ⁠y֮ ẇֽ⁠mah-ţėhèmi֪y ʻá֫lá֥⁠y hwòẖi֣yliy lֽé֭⁠ʼlòhiym ki̇y-ʻ֣wòd ʼwòde֑⁠ṅẇ yĕş̌ẇʻò֥ţ pá̇֝na֗⁠y wéֽ⁠ʼlòháֽ⁠y׃"],[43,1,"שָׁפְטֵ֤⁠נִי אֱלֹהִ֨ים ׀ וְ⁠רִ֘יבָ֤⁠ה רִיבִ֗⁠י מִ⁠גּ֥וֹי לֹא־חָסִ֑יד מֵ֤⁠אִישׁ־מִרְמָ֖ה וְ⁠עַוְלָ֣ה תְפַלְּטֵֽ⁠נִי׃","şá̌pĕté֤⁠niy ʼèlòhi֨ym ׀ wĕ⁠ri֘ybá֤⁠h riybi֗⁠y mi⁠ġ֥wòy lòʼ-ẖási֑yd mé֤⁠ʼiyş̌-mirĕmá֖h wĕ⁠ʻawĕlá֣h ţĕpalĕ̇téֽ⁠niy׃"],[43,2,"כִּֽי־אַתָּ֤ה ׀ אֱלֹהֵ֣י מָֽעוּזִּ⁠י֮ לָ⁠מָ֪ה זְנַ֫חְתָּ֥⁠נִי לָֽ⁠מָּה־קֹדֵ֥ר אֶתְהַלֵּ֗ךְ בְּ⁠לַ֣חַץ אוֹיֵֽב׃","kiֽ̇y-ʼaţá֤̇h ׀ ʼèlòhé֣y máֽʻẇzi̇⁠y֮ lá⁠má֪h zĕna֫ẖĕţá֥̇⁠niy láֽ⁠má̇h-qòdé֥r ʼeţĕhalé̇֗kĕ bĕ̇⁠la֣ẖaẕ ʼwòyéֽb׃"],[43,3,"שְׁלַח־אוֹרְ⁠ךָ֣ וַ֭⁠אֲמִתְּ⁠ךָ הֵ֣מָּה יַנְח֑וּ⁠נִי יְבִיא֥וּ⁠נִי אֶל־הַֽר־קָ֝דְשְׁ⁠ךָ֗ וְ⁠אֶל־מִשְׁכְּנוֹתֶֽי⁠ךָ׃","şĕ̌laẖ-ʼwòrĕ⁠ká֣ wa֭⁠ʼàmiţĕ̇⁠ká hé֣má̇h yanĕẖ֑ẇ⁠niy yĕbiyʼ֥ẇ⁠niy ʼel-haֽr-qá֝dĕşĕ̌⁠ká֗ wĕ⁠ʼel-mişĕ̌kĕ̇nwòţeֽy⁠ká׃"],[43,4,"וְ⁠אָב֤וֹאָה ׀ אֶל־מִזְבַּ֬ח אֱלֹהִ֗ים אֶל־אֵל֮ שִׂמְחַ֪ת גִּ֫ילִ֥⁠י וְ⁠אוֹדְ⁠ךָ֥ בְ⁠כִנּ֗וֹר אֱלֹהִ֥ים אֱלֹהָֽ⁠י׃","wĕ⁠ʼáb֤wòʼáh ׀ ʼel-mizĕbȧ֬ẖ ʼèlòhi֗ym ʼel-ʼél֮ şîmĕẖa֪ţ gi̇֫yli֥⁠y wĕ⁠ʼwòdĕ⁠ká֥ bĕ⁠kiṅ֗wòr ʼèlòhi֥ym ʼèlòháֽ⁠y׃"],[43,5,"מַה־תִּשְׁתּ֬וֹחֲחִ֨י ׀ נַפְשִׁ⁠י֮ וּֽ⁠מַה־תֶּהֱמִ֪י עָ֫לָ֥⁠י הוֹחִ֣ילִי לֵֽ֭⁠אלֹהִים כִּי־ע֣וֹד אוֹדֶ֑⁠נּוּ יְשׁוּעֹ֥ת פָּ֝נַ֗⁠י וֵֽ⁠אלֹהָֽ⁠י׃","mah-ţi̇şĕ̌ţ̇֬wòẖàẖi֨y ׀ napĕşǐ⁠y֮ ẇֽ⁠mah-ţėhèmi֪y ʻá֫lá֥⁠y hwòẖi֣yliy lֽé֭⁠ʼlòhiym ki̇y-ʻ֣wòd ʼwòde֑⁠ṅẇ yĕş̌ẇʻò֥ţ pá̇֝na֗⁠y wéֽ⁠ʼlòháֽ⁠y׃"],[44,1,"אֱלֹהִ֤ים ׀ בְּ⁠אָזְנֵ֬י⁠נוּ שָׁמַ֗עְנוּ אֲבוֹתֵ֥י⁠נוּ סִפְּרוּ־לָ֑⁠נוּ פֹּ֥עַל פָּעַ֥לְתָּ בִֽ֝⁠ימֵי⁠הֶ֗ם בִּ֣⁠ימֵי קֶֽדֶם׃","ʼèlòhi֤ym ׀ bĕ̇⁠ʼázĕné֬y⁠nẇ şá̌ma֗ʻĕnẇ ʼàbwòţé֥y⁠nẇ sipĕ̇rẇ-lá֑⁠nẇ pò֥̇ʻal pá̇ʻa֥lĕţá̇ biֽ֝⁠yméy⁠he֗m bi֣̇⁠yméy qeֽdem׃"],[44,2,"אַתָּ֤ה ׀ יָדְ⁠ךָ֡ גּוֹיִ֣ם ה֭וֹרַשְׁתָּ וַ⁠תִּטָּעֵ֑⁠ם תָּרַ֥ע לְ֝אֻמִּ֗ים וַֽ⁠תְּשַׁלְּחֵֽ⁠ם׃","ʼaţá֤̇h ׀ yádĕ⁠ká֡ ġwòyi֣m h֭wòraşĕ̌ţá̇ wa⁠ţi̇tá̇ʻé֑⁠m ţá̇ra֥ʻ lĕ֝ʼumi̇֗ym waֽ⁠ţĕ̇şǎlĕ̇ẖéֽ⁠m׃"],[44,3,"כִּ֤י לֹ֪א בְ⁠חַרְבָּ֡⁠ם יָ֥רְשׁוּ אָ֗רֶץ וּ⁠זְרוֹעָ⁠ם֮ לֹא־הוֹשִׁ֪יעָ֫ה לָּ֥⁠מוֹ כִּֽי־יְמִֽינְ⁠ךָ֣ וּ֭⁠זְרוֹעֲ⁠ךָ וְ⁠א֥וֹר פָּנֶ֗י⁠ךָ כִּ֣י רְצִיתָֽ⁠ם׃","ki֤̇y lò֪ʼ bĕ⁠ẖarĕbá̇֡⁠m yá֥rĕş̌ẇ ʼá֗reẕ ẇ⁠zĕrwòʻá⁠m֮ lòʼ-hwòşǐ֪yʻá֫h lá֥̇⁠mwò kiֽ̇y-yĕmiֽynĕ⁠ká֣ ẇ֭⁠zĕrwòʻà⁠ká wĕ⁠ʼ֥wòr pá̇ne֗y⁠ká ki֣̇y rĕẕiyţáֽ⁠m׃"],[44,4,"אַתָּה־ה֣וּא מַלְכִּ֣⁠י אֱלֹהִ֑ים צַ֝וֵּ֗ה יְשׁוּע֥וֹת יַעֲקֹֽב׃","ʼaţá̇h-h֣ẇʼ malĕki֣̇⁠y ʼèlòhi֑ym ẕa֝wé̇֗h yĕş̌ẇʻ֥wòţ yaʻàqòֽb׃"],[44,5,"בְּ֭⁠ךָ צָרֵ֣י⁠נוּ נְנַגֵּ֑חַ בְּ֝⁠שִׁמְ⁠ךָ֗ נָב֥וּס קָמֵֽי⁠נוּ׃","bĕ֭̇⁠ká ẕáré֣y⁠nẇ nĕnagé֑̇ẖa bĕ̇֝⁠şǐmĕ⁠ká֗ náb֥ẇs qáméֽy⁠nẇ׃"],[44,6,"כִּ֤י לֹ֣א בְ⁠קַשְׁתִּ֣⁠י אֶבְטָ֑ח וְ֝⁠חַרְבִּ֗⁠י לֹ֣א תוֹשִׁיעֵֽ⁠נִי׃","ki֤̇y lò֣ʼ bĕ⁠qaşĕ̌ţi֣̇⁠y ʼebĕtá֑ẖ wĕ֝⁠ẖarĕbi̇֗⁠y lò֣ʼ ţwòşǐyʻéֽ⁠niy׃"],[44,7,"כִּ֣י ה֭וֹשַׁעְתָּ⁠נוּ מִ⁠צָּרֵ֑י⁠נוּ וּ⁠מְשַׂנְאֵ֥י⁠נוּ הֱבִישֽׁוֹתָ׃","ki֣̇y h֭wòşǎʻĕţá̇⁠nẇ mi⁠ẕá̇ré֑y⁠nẇ ẇ⁠mĕşânĕʼé֥y⁠nẇ hèbiyşֽ̌wòţá׃"],[44,8,"בֵּֽ֭⁠אלֹהִים הִלַּלְ֣נוּ כָל־הַ⁠יּ֑וֹם וְ⁠שִׁמְ⁠ךָ֓ ׀ לְ⁠עוֹלָ֖ם נוֹדֶ֣ה סֶֽלָה׃","béֽ֭̇⁠ʼlòhiym hilȧlĕ֣nẇ kál-ha⁠ẏ֑wòm wĕ⁠şǐmĕ⁠ká֓ ׀ lĕ⁠ʻwòlá֖m nwòde֣h seֽláh׃"],[44,9,"אַף־זָ֭נַחְתָּ וַ⁠תַּכְלִימֵ֑⁠נוּ וְ⁠לֹא־תֵ֝צֵ֗א בְּ⁠צִבְאוֹתֵֽי⁠נוּ׃","ʼap-zá֭naẖĕţá̇ wa⁠ţȧkĕliymé֑⁠nẇ wĕ⁠lòʼ-ţé֝ẕé֗ʼ bĕ̇⁠ẕibĕʼwòţéֽy⁠nẇ׃"],[44,10,"תְּשִׁיבֵ֣⁠נוּ אָ֭חוֹר מִנִּי־צָ֑ר וּ֝⁠מְשַׂנְאֵ֗י⁠נוּ שָׁ֣סוּ לָֽ⁠מוֹ׃","ţĕ̇şǐybé֣⁠nẇ ʼá֭ẖwòr mini̇y-ẕá֑r ẇ֝⁠mĕşânĕʼé֗y⁠nẇ şá֣̌sẇ láֽ⁠mwò׃"],[44,11,"תִּ֭תְּנֵ⁠נוּ כְּ⁠צֹ֣אן מַאֲכָ֑ל וּ֝⁠בַ⁠גּוֹיִ֗ם זֵרִיתָֽ⁠נוּ׃","ţi֭̇ţĕ̇né⁠nẇ kĕ̇⁠ẕò֣ʼn maʼàká֑l ẇ֝⁠ba⁠ġwòyi֗m zériyţáֽ⁠nẇ׃"],[44,12,"תִּמְכֹּֽר־עַמְּ⁠ךָ֥ בְ⁠לֹא־ה֑וֹן וְ⁠לֹ֥א־רִ֝בִּ֗יתָ בִּ⁠מְחִירֵי⁠הֶֽם׃","ţi̇mĕkòֽ̇r-ʻamĕ̇⁠ká֥ bĕ⁠lòʼ-h֑wòn wĕ⁠lò֥ʼ-ri֝bi̇֗yţá bi̇⁠mĕẖiyréy⁠heֽm׃"],[44,13,"תְּשִׂימֵ֣⁠נוּ חֶ֭רְפָּה לִ⁠שְׁכֵנֵ֑י⁠נוּ לַ֥עַג וָ֝⁠קֶ֗לֶס לִ⁠סְבִיבוֹתֵֽי⁠נוּ׃","ţĕ̇şîymé֣⁠nẇ ẖe֭rĕpá̇h li⁠şĕ̌kéné֑y⁠nẇ la֥ʻag wá֝⁠qe֗les li⁠sĕbiybwòţéֽy⁠nẇ׃"],[44,14,"תְּשִׂימֵ֣⁠נוּ מָ֭שָׁל בַּ⁠גּוֹיִ֑ם מְנֽוֹד־רֹ֝֗אשׁ בַּל־אֻמִּֽים׃","ţĕ̇şîymé֣⁠nẇ má֭şá̌l bȧ⁠ġwòyi֑m mĕnֽwòd-rò֝֗ʼş̌ bȧl-ʼumiֽ̇ym׃"],[44,15,"כָּל־הַ֭⁠יּוֹם כְּלִמָּתִ֣⁠י נֶגְדִּ֑⁠י וּ⁠בֹ֖שֶׁת פָּנַ֣⁠י כִּסָּֽתְ⁠נִי׃","ká̇l-ha֭⁠ẏwòm kĕ̇limá̇ţi֣⁠y negĕdi֑̇⁠y ẇ⁠bò֖şěţ pá̇na֣⁠y ki̇sáֽ̇ţĕ⁠niy׃"],[44,16,"מִ֭⁠קּוֹל מְחָרֵ֣ף וּ⁠מְגַדֵּ֑ף מִ⁠פְּנֵ֥י א֝וֹיֵ֗ב וּ⁠מִתְנַקֵּֽם׃","mi֭⁠q̇wòl mĕẖáré֣p ẇ⁠mĕgadé֑̇p mi⁠pĕ̇né֥y ʼ֝wòyé֗b ẇ⁠miţĕnaqéֽ̇m׃"],[44,17,"כָּל־זֹ֣את בָּ֭אַתְ⁠נוּ וְ⁠לֹ֣א שְׁכַחֲנ֑וּ⁠ךָ וְ⁠לֹֽא־שִׁ֝קַּ֗רְנוּ בִּ⁠בְרִיתֶֽ⁠ךָ׃","ká̇l-zò֣ʼţ bá֭̇ʼaţĕ⁠nẇ wĕ⁠lò֣ʼ şĕ̌kaẖàn֑ẇ⁠ká wĕ⁠lòֽʼ-şǐ֝qȧ֗rĕnẇ bi̇⁠bĕriyţeֽ⁠ká׃"],[44,18,"לֹא־נָס֣וֹג אָח֣וֹר לִבֵּ֑⁠נוּ וַ⁠תֵּ֥ט אֲשֻׁרֵ֗י⁠נוּ מִנִּ֥י אָרְחֶֽ⁠ךָ׃","lòʼ-nás֣wòg ʼáẖ֣wòr libé֑̇⁠nẇ wa⁠ţé֥̇t ʼàşǔré֗y⁠nẇ mini֥̇y ʼárĕẖeֽ⁠ká׃"],[44,19,"כִּ֣י דִ֭כִּיתָ⁠נוּ בִּ⁠מְק֣וֹם תַּנִּ֑ים וַ⁠תְּכַ֖ס עָלֵ֣י⁠נוּ בְ⁠צַלְמָֽוֶת׃","ki֣̇y di֭ki̇yţá⁠nẇ bi̇⁠mĕq֣wòm ţȧni֑̇ym wa⁠ţĕ̇ka֖s ʻálé֣y⁠nẇ bĕ⁠ẕalĕmáֽweţ׃"],[44,20,"אִם־שָׁ֭כַחְנוּ שֵׁ֣ם אֱלֹהֵ֑י⁠נוּ וַ⁠נִּפְרֹ֥שׂ כַּ֝פֵּ֗י⁠נוּ לְ⁠אֵ֣ל זָֽר׃","ʼim-şá֭̌kaẖĕnẇ şé֣̌m ʼèlòhé֑y⁠nẇ wa⁠ni̇pĕrò֥ş̂ kȧ֝pé̇֗y⁠nẇ lĕ⁠ʼé֣l záֽr׃"],[44,21,"הֲ⁠לֹ֣א אֱ֭לֹהִים יַֽחֲקָר־זֹ֑את כִּֽי־ה֥וּא יֹ֝דֵ֗עַ תַּעֲלֻמ֥וֹת לֵֽב׃","hà⁠lò֣ʼ ʼè֭lòhiym yaֽẖàqár-zò֑ʼţ kiֽ̇y-h֥ẇʼ yò֝dé֗ʻa ţȧʻàlum֥wòţ léֽb׃"],[44,22,"כִּֽי־עָ֭לֶי⁠ךָ הֹרַ֣גְנוּ כָל־הַ⁠יּ֑וֹם נֶ֝חְשַׁ֗בְנוּ כְּ⁠צֹ֣אן טִבְחָֽה׃","kiֽ̇y-ʻá֭ley⁠ká hòra֣gĕnẇ kál-ha⁠ẏ֑wòm ne֝ẖĕşǎ֗bĕnẇ kĕ̇⁠ẕò֣ʼn tibĕẖáֽh׃"],[44,23,"ע֤וּרָ⁠ה ׀ לָ֖⁠מָּה תִישַׁ֥ן ׀ אֲדֹנָ֑⁠י הָ֝קִ֗יצָ⁠ה אַל־תִּזְנַ֥ח לָ⁠נֶֽצַח׃","ʻ֤ẇrá⁠h ׀ lá֖⁠má̇h ţiyşǎ֥n ׀ ʼàdòná֑⁠y há֝qi֗yẕá⁠h ʼal-ţi̇zĕna֥ẖ lá⁠neֽẕaẖ׃"],[44,24,"לָֽ⁠מָּה־פָנֶ֥י⁠ךָ תַסְתִּ֑יר תִּשְׁכַּ֖ח עָנְיֵ֣⁠נוּ וְֽ⁠לַחֲצֵֽ⁠נוּ׃","láֽ⁠má̇h-páne֥y⁠ká ţasĕţi֑̇yr ţi̇şĕ̌kȧ֖ẖ ʻánĕyé֣⁠nẇ wĕֽ⁠laẖàẕéֽ⁠nẇ׃"],[44,25,"כִּ֤י שָׁ֣חָה לֶ⁠עָפָ֣ר נַפְשֵׁ֑⁠נוּ דָּבְקָ֖ה לָ⁠אָ֣רֶץ בִּטְנֵֽ⁠נוּ׃","ki֤̇y şá֣̌ẖáh le⁠ʻápá֣r napĕşé֑̌⁠nẇ dá̇bĕqá֖h lá⁠ʼá֣reẕ bi̇tĕnéֽ⁠nẇ׃"],[44,26,"ק֭וּמָֽ⁠ה עֶזְרָ֣תָ⁠ה לָּ֑⁠נוּ וּ֝⁠פְדֵ֗⁠נוּ לְמַ֣עַן חַסְדֶּֽ⁠ךָ׃","q֭ẇmáֽ⁠h ʻezĕrá֣ţá⁠h lá֑̇⁠nẇ ẇ֝⁠pĕdé֗⁠nẇ lĕma֣ʻan ẖasĕdėֽ⁠ká׃"],[45,1,"רָ֘חַ֤שׁ לִבִּ֨⁠י ׀ דָּ֘בָ֤ר ט֗וֹב אֹמֵ֣ר אָ֭נִי מַעֲשַׂ֣⁠י לְ⁠מֶ֑לֶךְ לְ֝שׁוֹנִ֗⁠י עֵ֤ט ׀ סוֹפֵ֬ר מָהִֽיר׃","rá֘ẖa֤ş̌ libi̇֨⁠y ׀ dá̇֘bá֤r t֗wòb ʼòmé֣r ʼá֭niy maʻàşâ֣⁠y lĕ⁠me֑lekĕ lĕ֝ş̌wòni֗⁠y ʻé֤t ׀ swòpé֬r máhiֽyr׃"],[45,2,"יָפְיָפִ֡יתָ מִ⁠בְּנֵ֬י אָדָ֗ם ה֣וּצַק חֵ֭ן בְּ⁠שְׂפְתוֹתֶ֑י⁠ךָ עַל־כֵּ֤ן בֵּֽרַכְ⁠ךָ֖ אֱלֹהִ֣ים לְ⁠עוֹלָֽם׃","yápĕyápi֡yţá mi⁠bĕ̇né֬y ʼádá֗m h֣ẇẕaq ẖé֭n bĕ̇⁠şĕ̂pĕţwòţe֑y⁠ká ʻal-ké֤̇n béֽ̇rakĕ⁠ká֖ ʼèlòhi֣ym lĕ⁠ʻwòláֽm׃"],[45,3,"חֲגֽוֹר־חַרְבְּ⁠ךָ֣ עַל־יָרֵ֣ךְ גִּבּ֑וֹר ה֝וֹדְ⁠ךָ֗ וַ⁠הֲדָרֶֽ⁠ךָ׃","ẖàgֽwòr-ẖarĕbĕ̇⁠ká֣ ʻal-yáré֣kĕ gi̇ḃ֑wòr h֝wòdĕ⁠ká֗ wa⁠hàdáreֽ⁠ká׃"],[45,4,"וַ⁠הֲדָ֬רְ⁠ךָ֨ ׀ צְלַ֬ח רְכַ֗ב עַֽל־דְּבַר־אֱ֭מֶת וְ⁠עַנְוָה־צֶ֑דֶק וְ⁠תוֹרְ⁠ךָ֖ נוֹרָא֣וֹת יְמִינֶֽ⁠ךָ׃","wa⁠hàdá֬rĕ⁠ká֨ ׀ ẕĕla֬ẖ rĕka֗b ʻaֽl-dĕ̇bar-ʼè֭meţ wĕ⁠ʻanĕwáh-ẕe֑deq wĕ⁠ţwòrĕ⁠ká֖ nwòráʼ֣wòţ yĕmiyneֽ⁠ká׃"],[45,5,"חִצֶּ֗י⁠ךָ שְׁנ֫וּנִ֥ים עַ֭מִּים תַּחְתֶּ֣י⁠ךָ יִפְּל֑וּ בְּ֝⁠לֵ֗ב אוֹיְבֵ֥י הַ⁠מֶּֽלֶךְ׃","ẖiẕė֗y⁠ká şĕ̌n֫ẇni֥ym ʻa֭mi̇ym ţȧẖĕţė֣y⁠ká yipĕ̇l֑ẇ bĕ̇֝⁠lé֗b ʼwòyĕbé֥y ha⁠mėֽlekĕ׃"],[45,6,"כִּסְאֲ⁠ךָ֣ אֱ֭לֹהִים עוֹלָ֣ם וָ⁠עֶ֑ד שֵׁ֥בֶט מִ֝ישֹׁ֗ר שֵׁ֣בֶט מַלְכוּתֶֽ⁠ךָ׃","ki̇sĕʼà⁠ká֣ ʼè֭lòhiym ʻwòlá֣m wá⁠ʻe֑d şé֥̌bet mi֝yşò̌֗r şé֣̌bet malĕkẇţeֽ⁠ká׃"],[45,7,"אָהַ֣בְתָּ צֶּדֶק֮ וַ⁠תִּשְׂנָ֫א רֶ֥שַׁע עַל־כֵּ֤ן ׀ מְשָׁחֲ⁠ךָ֡ אֱלֹהִ֣ים אֱ֭לֹהֶי⁠ךָ שֶׁ֥מֶן שָׂשׂ֗וֹן מֵֽ⁠חֲבֵרֶֽי⁠ךָ׃","ʼáha֣bĕţá̇ ẕėdeq֮ wa⁠ţi̇şĕ̂ná֫ʼ re֥şǎʻ ʻal-ké֤̇n ׀ mĕşá̌ẖà⁠ká֡ ʼèlòhi֣ym ʼè֭lòhey⁠ká şě֥men şá̂ş̂֗wòn méֽ⁠ẖàbéreֽy⁠ká׃"],[45,8,"מֹר־וַ⁠אֲהָל֣וֹת קְ֭צִיעוֹת כָּל־בִּגְדֹתֶ֑י⁠ךָ מִֽן־הֵ֥יכְלֵי שֵׁ֝֗ן מִנִּ֥י שִׂמְּחֽוּ⁠ךָ׃","mòr-wa⁠ʼàhál֣wòţ qĕ֭ẕiyʻwòţ ká̇l-bi̇gĕdòţe֑y⁠ká miֽn-hé֥ykĕléy şé̌֝֗n mini֥̇y şîmĕ̇ẖֽẇ⁠ká׃"],[45,9,"בְּנ֣וֹת מְ֭לָכִים בְּ⁠יִקְּרוֹתֶ֑י⁠ךָ נִצְּבָ֥ה שֵׁגַ֥ל לִֽ֝⁠ימִינְ⁠ךָ֗ בְּ⁠כֶ֣תֶם אוֹפִֽיר׃","bĕ̇n֣wòţ mĕ֭lákiym bĕ̇⁠yiqĕ̇rwòţe֑y⁠ká niẕĕ̇bá֥h şé̌ga֥l liֽ֝⁠ymiynĕ⁠ká֗ bĕ̇⁠ke֣ţem ʼwòpiֽyr׃"],[45,10,"שִׁמְעִי־בַ֣ת וּ֭⁠רְאִי וְ⁠הַטִּ֣י אָזְנֵ֑⁠ךְ וְ⁠שִׁכְחִ֥י עַ֝מֵּ֗⁠ךְ וּ⁠בֵ֥ית אָבִֽי⁠ךְ׃","şǐmĕʻiy-ba֣ţ ẇ֭⁠rĕʼiy wĕ⁠hati֣̇y ʼázĕné֑⁠kĕ wĕ⁠şǐkĕẖi֥y ʻa֝mé̇֗⁠kĕ ẇ⁠bé֥yţ ʼábiֽy⁠kĕ׃"],[45,11,"וְ⁠יִתְאָ֣ו הַ⁠מֶּ֣לֶךְ יָפְיֵ֑⁠ךְ כִּי־ה֥וּא אֲ֝דֹנַ֗יִ⁠ךְ וְ⁠הִשְׁתַּֽחֲוִי־לֽ⁠וֹ׃","wĕ⁠yiţĕʼá֣w ha⁠mė֣lekĕ yápĕyé֑⁠kĕ ki̇y-h֥ẇʼ ʼà֝dòna֗yi⁠kĕ wĕ⁠hişĕ̌ţȧֽẖàwiy-lֽ⁠wò׃"],[45,12,"וּ⁠בַֽת־צֹ֨ר ׀ בְּ֭⁠מִנְחָה פָּנַ֥יִ⁠ךְ יְחַלּ֗וּ עֲשִׁ֣ירֵי עָֽם׃","ẇ⁠baֽţ-ẕò֨r ׀ bĕ֭̇⁠minĕẖáh pá̇na֥yi⁠kĕ yĕẖal̇֗ẇ ʻàşǐ֣yréy ʻáֽm׃"],[45,13,"כָּל־כְּבוּדָּ֣ה בַת־מֶ֣לֶךְ פְּנִ֑ימָה מִֽ⁠מִּשְׁבְּצ֖וֹת זָהָ֣ב לְבוּשָֽׁ⁠הּ׃","ká̇l-kĕ̇bẇdá֣̇h baţ-me֣lekĕ pĕ̇ni֑ymáh miֽ⁠mi̇şĕ̌bĕ̇ẕ֖wòţ záhá֣b lĕbẇşáֽ̌⁠ḣ׃"],[45,14,"לִ⁠רְקָמוֹת֮ תּוּבַ֪ל לַ֫⁠מֶּ֥לֶךְ בְּתוּל֣וֹת אַ֭חֲרֶי⁠הָ רֵעוֹתֶ֑י⁠הָ מ֖וּבָא֣וֹת לָֽ⁠ךְ׃","li⁠rĕqámwòţ֮ ţ̇ẇba֪l la֫⁠mė֥lekĕ bĕ̇ţẇl֣wòţ ʼa֭ẖàrey⁠há réʻwòţe֑y⁠há m֖ẇbáʼ֣wòţ láֽ⁠kĕ׃"],[45,15,"תּ֭וּבַלְנָה בִּ⁠שְׂמָחֹ֣ת וָ⁠גִ֑יל תְּ֝בֹאֶ֗ינָה בְּ⁠הֵ֣יכַל מֶֽלֶךְ׃","ţ֭̇ẇbalĕnáh bi̇⁠şĕ̂máẖò֣ţ wá⁠gi֑yl ţĕ̇֝bòʼe֗ynáh bĕ̇⁠hé֣ykal meֽlekĕ׃"],[45,16,"תַּ֣חַת אֲ֭בֹתֶי⁠ךָ יִהְי֣וּ בָנֶ֑י⁠ךָ תְּשִׁיתֵ֥⁠מוֹ לְ֝⁠שָׂרִ֗ים בְּ⁠כָל־הָ⁠אָֽרֶץ׃","ţȧ֣ẖaţ ʼà֭bòţey⁠ká yihĕy֣ẇ báne֑y⁠ká ţĕ̇şǐyţé֥⁠mwò lĕ֝⁠şá̂ri֗ym bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[45,17,"אַזְכִּ֣ירָה שִׁ֭מְ⁠ךָ בְּ⁠כָל־דֹּ֣ר וָ⁠דֹ֑ר עַל־כֵּ֥ן עַמִּ֥ים יְ֝הוֹדֻ֗⁠ךָ לְ⁠עֹלָ֥ם וָ⁠עֶֽד׃","ʼazĕki֣̇yráh şǐ֭mĕ⁠ká bĕ̇⁠kál-dò֣̇r wá⁠dò֑r ʻal-ké֥̇n ʻami֥̇ym yĕ֝hwòdu֗⁠ká lĕ⁠ʻòlá֥m wá⁠ʻeֽd׃"],[46,1,"אֱלֹהִ֣ים לָ֭⁠נוּ מַחֲסֶ֣ה וָ⁠עֹ֑ז עֶזְרָ֥ה בְ֝⁠צָר֗וֹת נִמְצָ֥א מְאֹֽד׃","ʼèlòhi֣ym lá֭⁠nẇ maẖàse֣h wá⁠ʻò֑z ʻezĕrá֥h bĕ֝⁠ẕár֗wòţ nimĕẕá֥ʼ mĕʼòֽd׃"],[46,2,"עַל־כֵּ֣ן לֹא־נִ֭ירָא בְּ⁠הָמִ֣יר אָ֑רֶץ וּ⁠בְ⁠מ֥וֹט הָ֝רִ֗ים בְּ⁠לֵ֣ב יַמִּֽים׃","ʻal-ké֣̇n lòʼ-ni֭yráʼ bĕ̇⁠hámi֣yr ʼá֑reẕ ẇ⁠bĕ⁠m֥wòt há֝ri֗ym bĕ̇⁠lé֣b yamiֽ̇ym׃"],[46,3,"יֶהֱמ֣וּ יֶחְמְר֣וּ מֵימָ֑י⁠ו יִֽרְעֲשֽׁוּ־הָרִ֖ים בְּ⁠גַאֲוָת֣⁠וֹ סֶֽלָה׃","yehèm֣ẇ yeẖĕmĕr֣ẇ méymá֑y⁠w yiֽrĕʻàşֽ̌ẇ-hári֖ym bĕ̇⁠gaʼàwáţ֣⁠wò seֽláh׃"],[46,4,"נָהָ֗ר פְּלָגָ֗י⁠ו יְשַׂמְּח֥וּ עִיר־אֱלֹהִ֑ים קְ֝דֹ֗שׁ מִשְׁכְּנֵ֥י עֶלְיֽוֹן׃","náhá֗r pĕ̇lágá֗y⁠w yĕşâmĕ̇ẖ֥ẇ ʻiyr-ʼèlòhi֑ym qĕ֝dò֗ş̌ mişĕ̌kĕ̇né֥y ʻelĕyֽwòn׃"],[46,5,"אֱלֹהִ֣ים בְּ֭⁠קִרְבָּ⁠הּ בַּל־תִּמּ֑וֹט יַעְזְרֶ֥⁠הָ אֱ֝לֹהִ֗ים לִ⁠פְנ֥וֹת בֹּֽקֶר׃","ʼèlòhi֣ym bĕ֭̇⁠qirĕbá̇⁠ḣ bȧl-ţi̇ṁ֑wòt yaʻĕzĕre֥⁠há ʼè֝lòhi֗ym li⁠pĕn֥wòţ bòֽ̇qer׃"],[46,6,"הָמ֣וּ ג֭וֹיִם מָ֣טוּ מַמְלָכ֑וֹת נָתַ֥ן בְּ֝⁠קוֹל֗⁠וֹ תָּמ֥וּג אָֽרֶץ׃","hám֣ẇ g֭wòyim má֣tẇ mamĕlák֑wòţ náţa֥n bĕ̇֝⁠qwòl֗⁠wò ţá̇m֥ẇg ʼáֽreẕ׃"],[46,7,"יְהוָ֣ה צְבָא֣וֹת עִמָּ֑⁠נוּ מִשְׂגָּֽב־לָ֝⁠נוּ אֱלֹהֵ֖י יַעֲקֹ֣ב סֶֽלָה׃","yĕhwá֣h ẕĕbáʼ֣wòţ ʻimá֑̇⁠nẇ mişĕ̂gáֽ̇b-lá֝⁠nẇ ʼèlòhé֖y yaʻàqò֣b seֽláh׃"],[46,8,"לְֽכוּ־חֲ֭זוּ מִפְעֲל֣וֹת יְהוָ֑ה אֲשֶׁר־שָׂ֖ם שַׁמּ֣וֹת בָּ⁠אָֽרֶץ׃","lĕֽkẇ-ẖà֭zẇ mipĕʻàl֣wòţ yĕhwá֑h ʼàşěr-şá֖̂m şǎṁ֣wòţ bá̇⁠ʼáֽreẕ׃"],[46,9,"מַשְׁבִּ֥ית מִלְחָמוֹת֮ עַד־קְצֵ֪ה הָ֫⁠אָ֥רֶץ קֶ֣שֶׁת יְ֭שַׁבֵּר וְ⁠קִצֵּ֣ץ חֲנִ֑ית עֲ֝גָל֗וֹת יִשְׂרֹ֥ף בָּ⁠אֵֽשׁ׃","maşĕ̌bi֥̇yţ milĕẖámwòţ֮ ʻad-qĕẕé֪h há֫⁠ʼá֥reẕ qe֣şěţ yĕ֭şǎbé̇r wĕ⁠qiẕé֣̇ẕ ẖàni֑yţ ʻà֝gál֗wòţ yişĕ̂rò֥p bá̇⁠ʼéֽş̌׃"],[46,10,"הַרְפּ֣וּ וּ֭⁠דְעוּ כִּי־אָנֹכִ֣י אֱלֹהִ֑ים אָר֥וּם בַּ֝⁠גּוֹיִ֗ם אָר֥וּם בָּ⁠אָֽרֶץ׃","harĕṗ֣ẇ ẇ֭⁠dĕʻẇ ki̇y-ʼánòki֣y ʼèlòhi֑ym ʼár֥ẇm bȧ֝⁠ġwòyi֗m ʼár֥ẇm bá̇⁠ʼáֽreẕ׃"],[46,11,"יְהוָ֣ה צְבָא֣וֹת עִמָּ֑⁠נוּ מִשְׂגָּֽב־לָ֝⁠נוּ אֱלֹהֵ֖י יַעֲקֹ֣ב סֶֽלָה׃","yĕhwá֣h ẕĕbáʼ֣wòţ ʻimá֑̇⁠nẇ mişĕ̂gáֽ̇b-lá֝⁠nẇ ʼèlòhé֖y yaʻàqò֣b seֽláh׃"],[47,1,"כָּֽל־הָ֭⁠עַמִּים תִּקְעוּ־כָ֑ף הָרִ֥יעוּ לֵ֝⁠אלֹהִ֗ים בְּ⁠ק֣וֹל רִנָּֽה׃","káֽ̇l-há֭⁠ʻami̇ym ţi̇qĕʻẇ-ká֑p hári֥yʻẇ lé֝⁠ʼlòhi֗ym bĕ̇⁠q֣wòl rináֽ̇h׃"],[47,2,"כִּֽי־יְהוָ֣ה עֶלְי֣וֹן נוֹרָ֑א מֶ֥לֶךְ גָּ֝דוֹל עַל־כָּל־הָ⁠אָֽרֶץ׃","kiֽ̇y-yĕhwá֣h ʻelĕy֣wòn nwòrá֑ʼ me֥lekĕ gá̇֝dwòl ʻal-ká̇l-há⁠ʼáֽreẕ׃"],[47,3,"יַדְבֵּ֣ר עַמִּ֣ים תַּחְתֵּ֑י⁠נוּ וּ֝⁠לְאֻמִּ֗ים תַּ֣חַת רַגְלֵֽי⁠נוּ׃","yadĕbé֣̇r ʻami֣̇ym ţȧẖĕţé֑̇y⁠nẇ ẇ֝⁠lĕʼumi̇֗ym ţȧ֣ẖaţ ragĕléֽy⁠nẇ׃"],[47,4,"יִבְחַר־לָ֥⁠נוּ אֶת־נַחֲלָתֵ֑⁠נוּ אֶ֥ת גְּא֨וֹן יַעֲקֹ֖ב אֲשֶׁר־אָהֵ֣ב סֶֽלָה׃","yibĕẖar-lá֥⁠nẇ ʼeţ-naẖàláţé֑⁠nẇ ʼe֥ţ gĕ̇ʼ֨wòn yaʻàqò֖b ʼàşěr-ʼáhé֣b seֽláh׃"],[47,5,"עָלָ֣ה אֱ֭לֹהִים בִּ⁠תְרוּעָ֑ה יְ֝הֹוָ֗ה בְּ⁠ק֣וֹל שׁוֹפָֽר׃","ʻálá֣h ʼè֭lòhiym bi̇⁠ţĕrẇʻá֑h yĕ֝hòwá֗h bĕ̇⁠q֣wòl ş̌wòpáֽr׃"],[47,6,"זַמְּר֣וּ אֱלֹהִ֣ים זַמֵּ֑רוּ זַמְּר֖וּ לְ⁠מַלְכֵּ֣⁠נוּ זַמֵּֽרוּ׃","zamĕ̇r֣ẇ ʼèlòhi֣ym zamé֑̇rẇ zamĕ̇r֖ẇ lĕ⁠malĕké֣̇⁠nẇ zaméֽ̇rẇ׃"],[47,7,"כִּ֤י מֶ֖לֶךְ כָּל־הָ⁠אָ֥רֶץ אֱלֹהִ֗ים זַמְּר֥וּ מַשְׂכִּֽיל׃","ki֤̇y me֖lekĕ ká̇l-há⁠ʼá֥reẕ ʼèlòhi֗ym zamĕ̇r֥ẇ maşĕ̂kiֽ̇yl׃"],[47,8,"מָלַ֣ךְ אֱ֭לֹהִים עַל־גּוֹיִ֑ם אֱ֝לֹהִ֗ים יָשַׁ֤ב ׀ עַל־כִּסֵּ֬א קָדְשֽׁ⁠וֹ׃","mála֣kĕ ʼè֭lòhiym ʻal-ġwòyi֑m ʼè֝lòhi֗ym yáşǎ֤b ׀ ʻal-ki̇sé̇֬ʼ qádĕşֽ̌⁠wò׃"],[47,9,"נְדִ֘יבֵ֤י עַמִּ֨ים ׀ נֶאֱסָ֗פוּ עַם֮ אֱלֹהֵ֪י אַבְרָ֫הָ֥ם כִּ֣י לֵֽ֭⁠אלֹהִים מָֽגִנֵּי־אֶ֗רֶץ מְאֹ֣ד נַעֲלָֽה׃","nĕdi֘ybé֤y ʻami̇֨ym ׀ neʼèsá֗pẇ ʻam֮ ʼèlòhé֪y ʼabĕrá֫há֥m ki֣̇y léֽ֭⁠ʼlòhiym máֽginé̇y-ʼe֗reẕ mĕʼò֣d naʻàláֽh׃"],[48,1,"גָּ֘ד֤וֹל יְהוָ֣ה וּ⁠מְהֻלָּ֣ל מְאֹ֑ד בְּ⁠עִ֥יר אֱ֝לֹהֵ֗י⁠נוּ הַר־קָדְשֽׁ⁠וֹ׃","gá̇֘d֤wòl yĕhwá֣h ẇ⁠mĕhulá֣̇l mĕʼò֑d bĕ̇⁠ʻi֥yr ʼè֝lòhé֗y⁠nẇ har-qádĕşֽ̌⁠wò׃"],[48,2,"יְפֵ֥ה נוֹף֮ מְשׂ֪וֹשׂ כָּל־הָ֫⁠אָ֥רֶץ הַר־צִ֭יּוֹן יַרְכְּתֵ֣י צָפ֑וֹן קִ֝רְיַ֗ת מֶ֣לֶךְ רָֽב׃","yĕpé֥h nwòp֮ mĕş֪̂wòş̂ ká̇l-há֫⁠ʼá֥reẕ har-ẕi֭ẏwòn yarĕkĕ̇ţé֣y ẕáp֑wòn qi֝rĕya֗ţ me֣lekĕ ráֽb׃"],[48,3,"אֱלֹהִ֥ים בְּ⁠אַרְמְנוֹתֶ֗י⁠הָ נוֹדַ֥ע לְ⁠מִשְׂגָּֽב׃","ʼèlòhi֥ym bĕ̇⁠ʼarĕmĕnwòţe֗y⁠há nwòda֥ʻ lĕ⁠mişĕ̂gáֽ̇b׃"],[48,4,"כִּֽי־הִנֵּ֣ה הַ֭⁠מְּלָכִים נֽוֹעֲד֑וּ עָבְר֥וּ יַחְדָּֽו׃","kiֽ̇y-hiné֣̇h ha֭⁠mĕ̇lákiym nֽwòʻàd֑ẇ ʻábĕr֥ẇ yaẖĕdáֽ̇w׃"],[48,5,"הֵ֣מָּה רָ֭אוּ כֵּ֣ן תָּמָ֑הוּ נִבְהֲל֥וּ נֶחְפָּֽזוּ׃","hé֣má̇h rá֭ʼẇ ké֣̇n ţá̇má֑hẇ nibĕhàl֥ẇ neẖĕpáֽ̇zẇ׃"],[48,6,"רְ֭עָדָה אֲחָזָ֣תַ⁠ם שָׁ֑ם חִ֝֗יל כַּ⁠יּוֹלֵֽדָה׃","rĕ֭ʻádáh ʼàẖázá֣ţa⁠m şá֑̌m ẖi֝֗yl kȧ⁠ẏwòléֽdáh׃"],[48,7,"בְּ⁠ר֥וּחַ קָדִ֑ים תְּ֝שַׁבֵּ֗ר אֳנִיּ֥וֹת תַּרְשִֽׁישׁ׃","bĕ̇⁠r֥ẇẖa qádi֑ym ţĕ̇֝şǎbé̇֗r ʼoniẏ֥wòţ ţȧrĕşǐֽyş̌׃"],[48,8,"כַּ⁠אֲשֶׁ֤ר שָׁמַ֨עְנוּ ׀ כֵּ֤ן רָאִ֗ינוּ בְּ⁠עִיר־יְהוָ֣ה צְ֭בָאוֹת בְּ⁠עִ֣יר אֱלֹהֵ֑י⁠נוּ אֱלֹ֘הִ֤ים יְכוֹנְנֶ֖⁠הָ עַד־עוֹלָ֣ם סֶֽלָה׃","kȧ⁠ʼàşě֤r şá̌ma֨ʻĕnẇ ׀ ké֤̇n ráʼi֗ynẇ bĕ̇⁠ʻiyr-yĕhwá֣h ẕĕ֭báʼwòţ bĕ̇⁠ʻi֣yr ʼèlòhé֑y⁠nẇ ʼèlò֘hi֤ym yĕkwònĕne֖⁠há ʻad-ʻwòlá֣m seֽláh׃"],[48,9,"דִּמִּ֣ינוּ אֱלֹהִ֣ים חַסְדֶּ֑⁠ךָ בְּ֝⁠קֶ֗רֶב הֵיכָלֶֽ⁠ךָ׃","di̇mi֣̇ynẇ ʼèlòhi֣ym ẖasĕdė֑⁠ká bĕ̇֝⁠qe֗reb héykáleֽ⁠ká׃"],[48,10,"כְּ⁠שִׁמְ⁠ךָ֤ אֱלֹהִ֗ים כֵּ֣ן תְּ֭הִלָּתְ⁠ךָ עַל־קַצְוֵי־אֶ֑רֶץ צֶ֝֗דֶק מָלְאָ֥ה יְמִינֶֽ⁠ךָ׃","kĕ̇⁠şǐmĕ⁠ká֤ ʼèlòhi֗ym ké֣̇n ţĕ֭̇hilá̇ţĕ⁠ká ʻal-qaẕĕwéy-ʼe֑reẕ ẕe֝֗deq málĕʼá֥h yĕmiyneֽ⁠ká׃"],[48,11,"יִשְׂמַ֤ח ׀ הַר־צִיּ֗וֹן תָּ֭גֵלְנָה בְּנ֣וֹת יְהוּדָ֑ה לְ֝מַ֗עַן מִשְׁפָּטֶֽי⁠ךָ׃","yişĕ̂ma֤ẖ ׀ har-ẕiẏ֗wòn ţá֭̇gélĕnáh bĕ̇n֣wòţ yĕhẇdá֑h lĕ֝ma֗ʻan mişĕ̌pá̇teֽy⁠ká׃"],[48,12,"סֹ֣בּוּ צִ֭יּוֹן וְ⁠הַקִּיפ֑וּ⁠הָ סִ֝פְר֗וּ מִגְדָּלֶֽי⁠הָ׃","sò֣ḃẇ ẕi֭ẏwòn wĕ⁠haqi̇yp֑ẇ⁠há si֝pĕr֗ẇ migĕdá̇leֽy⁠há׃"],[48,13,"שִׁ֤יתוּ לִבְּ⁠כֶ֨ם ׀ לְֽ⁠חֵילָ֗⁠ה פַּסְּג֥וּ אַרְמְנוֹתֶ֑י⁠הָ לְמַ֥עַן תְּ֝סַפְּר֗וּ לְ⁠ד֣וֹר אַחֲרֽוֹן׃","şǐ֤yţẇ libĕ̇⁠ke֨m ׀ lĕֽ⁠ẖéylá֗⁠h pȧsĕ̇g֥ẇ ʼarĕmĕnwòţe֑y⁠há lĕma֥ʻan ţĕ̇֝sapĕ̇r֗ẇ lĕ⁠d֣wòr ʼaẖàrֽwòn׃"],[48,14,"כִּ֤י זֶ֨ה ׀ אֱלֹהִ֣ים אֱ֭לֹהֵי⁠נוּ עוֹלָ֣ם וָ⁠עֶ֑ד ה֖וּא יְנַהֲגֵ֣⁠נוּ עַל־מֽוּת׃","ki֤̇y ze֨h ׀ ʼèlòhi֣ym ʼè֭lòhéy⁠nẇ ʻwòlá֣m wá⁠ʻe֑d h֖ẇʼ yĕnahàgé֣⁠nẇ ʻal-mֽẇţ׃"],[49,1,"שִׁמְעוּ־זֹ֭את כָּל־הָֽ⁠עַמִּ֑ים הַ֝אֲזִ֗ינוּ כָּל־יֹ֥שְׁבֵי חָֽלֶד׃","şǐmĕʻẇ-zò֭ʼţ ká̇l-háֽ⁠ʻami֑̇ym ha֝ʼàzi֗ynẇ ká̇l-yò֥şĕ̌béy ẖáֽled׃"],[49,2,"גַּם־בְּנֵ֣י אָ֭דָם גַּם־בְּנֵי־אִ֑ישׁ יַ֝֗חַד עָשִׁ֥יר וְ⁠אֶבְיֽוֹן׃","gȧm-bĕ̇né֣y ʼá֭dám gȧm-bĕ̇néy-ʼi֑yş̌ ya֝֗ẖad ʻáşǐ֥yr wĕ⁠ʼebĕyֽwòn׃"],[49,3,"פִּ֭⁠י יְדַבֵּ֣ר חָכְמ֑וֹת וְ⁠הָג֖וּת לִבִּ֣⁠י תְבוּנֽוֹת׃","pi֭̇⁠y yĕdabé֣̇r ẖákĕm֑wòţ wĕ⁠hág֖ẇţ libi֣̇⁠y ţĕbẇnֽwòţ׃"],[49,4,"אַטֶּ֣ה לְ⁠מָשָׁ֣ל אָזְנִ֑⁠י אֶפְתַּ֥ח בְּ֝⁠כִנּ֗וֹר חִידָתִֽ⁠י׃","ʼatė֣h lĕ⁠máşá֣̌l ʼázĕni֑⁠y ʼepĕţȧ֥ẖ bĕ̇֝⁠kiṅ֗wòr ẖiydáţֽi⁠y׃"],[49,5,"לָ֣⁠מָּה אִ֭ירָא בִּ֣⁠ימֵי רָ֑ע עֲוֺ֖ן עֲקֵבַ֣⁠י יְסוּבֵּֽ⁠נִי׃","lá֣⁠má̇h ʼi֭yráʼ bi֣̇⁠yméy rá֑ʻ ʻàwֺ֖n ʻàqéba֣⁠y yĕsẇbéֽ̇⁠niy׃"],[49,6,"הַ⁠בֹּטְחִ֥ים עַל־חֵילָ֑⁠ם וּ⁠בְ⁠רֹ֥ב עָ֝שְׁרָ֗⁠ם יִתְהַלָּֽלוּ׃","ha⁠bò̇tĕẖi֥ym ʻal-ẖéylá֑⁠m ẇ⁠bĕ⁠rò֥b ʻá֝şĕ̌rá֗⁠m yiţĕhaláֽ̇lẇ׃"],[49,7,"אָ֗ח לֹא־פָדֹ֣ה יִפְדֶּ֣ה אִ֑ישׁ לֹא־יִתֵּ֖ן לֵ⁠אלֹהִ֣ים כָּפְרֽ⁠וֹ׃","ʼá֗ẖ lòʼ-pádò֣h yipĕdė֣h ʼi֑yş̌ lòʼ-yiţé֖̇n lé⁠ʼlòhi֣ym ká̇pĕrֽ⁠wò׃"],[49,8,"וְ֭⁠יֵקַר פִּדְי֥וֹן נַפְשָׁ֗⁠ם וְ⁠חָדַ֥ל לְ⁠עוֹלָֽם׃","wĕ֭⁠yéqar pi̇dĕy֥wòn napĕşá̌֗⁠m wĕ⁠ẖáda֥l lĕ⁠ʻwòláֽm׃"],[49,9,"וִֽ⁠יחִי־ע֥וֹד לָ⁠נֶ֑צַח לֹ֖א יִרְאֶ֣ה הַ⁠שָּֽׁחַת׃","wiֽ⁠yẖiy-ʻ֥wòd lá⁠ne֑ẕaẖ lò֖ʼ yirĕʼe֣h ha⁠şáֽ̇̌ẖaţ׃"],[49,10,"כִּ֤י יִרְאֶ֨ה ׀ חֲכָ֘מִ֤ים יָמ֗וּתוּ יַ֤חַד כְּסִ֣יל וָ⁠בַ֣עַר יֹאבֵ֑דוּ וְ⁠עָזְב֖וּ לַ⁠אֲחֵרִ֣ים חֵילָֽ⁠ם׃","ki֤̇y yirĕʼe֨h ׀ ẖàká֘mi֤ym yám֗ẇţẇ ya֤ẖad kĕ̇si֣yl wá⁠ba֣ʻar yòʼbé֑dẇ wĕ⁠ʻázĕb֖ẇ la⁠ʼàẖéri֣ym ẖéyláֽ⁠m׃"],[49,11,"קִרְבָּ֤⁠ם בָּתֵּ֨י⁠מוֹ ׀ לְֽ⁠עוֹלָ֗ם מִ֭שְׁכְּנֹתָ⁠ם לְ⁠דֹ֣ר וָ⁠דֹ֑ר קָֽרְא֥וּ בִ֝⁠שְׁמוֹתָ֗⁠ם עֲלֵ֣י אֲדָמֽוֹת׃","qirĕbá֤̇⁠m bá̇ţé̇֨y⁠mwò ׀ lĕֽ⁠ʻwòlá֗m mi֭şĕ̌kĕ̇nòţá⁠m lĕ⁠dò֣r wá⁠dò֑r qáֽrĕʼ֥ẇ bi֝⁠şĕ̌mwòţá֗⁠m ʻàlé֣y ʼàdámֽwòţ׃"],[49,12,"וְ⁠אָדָ֣ם בִּ֭⁠יקָר בַּל־יָלִ֑ין נִמְשַׁ֖ל כַּ⁠בְּהֵמ֣וֹת נִדְמֽוּ׃","wĕ⁠ʼádá֣m bi֭̇⁠yqár bȧl-yáli֑yn nimĕşǎ֖l kȧ⁠bĕ̇hém֣wòţ nidĕmֽẇ׃"],[49,13,"זֶ֣ה דַ֭רְכָּ⁠ם כֵּ֣סֶל לָ֑⁠מוֹ וְ⁠אַחֲרֵי⁠הֶ֓ם ׀ בְּ⁠פִי⁠הֶ֖ם יִרְצ֣וּ סֶֽלָה׃","ze֣h da֭rĕká̇⁠m ké֣̇sel lá֑⁠mwò wĕ⁠ʼaẖàréy⁠he֓m ׀ bĕ̇⁠piy⁠he֖m yirĕẕ֣ẇ seֽláh׃"],[49,14,"כַּ⁠צֹּ֤אן ׀ לִֽ⁠שְׁא֣וֹל שַׁתּוּ֮ מָ֤וֶת יִ֫רְעֵ֥⁠ם וַ⁠יִּרְדּ֘וּ בָ֤⁠ם יְשָׁרִ֨ים ׀ לַ⁠בֹּ֗קֶר ו⁠ציר⁠ם לְ⁠בַלּ֥וֹת שְׁא֗וֹל מִ⁠זְּבֻ֥ל לֽ⁠וֹ׃","kȧ⁠ẕò֤̇ʼn ׀ liֽ⁠şĕ̌ʼ֣wòl şǎţ̇ẇ֮ má֤weţ yi֫rĕʻé֥⁠m wa⁠yi̇rĕḋ֘ẇ bá֤⁠m yĕşá̌ri֨ym ׀ la⁠bò̇֗qer w⁠ẕyr⁠m lĕ⁠bal֥̇wòţ şĕ̌ʼ֗wòl mi⁠zĕ̇bu֥l lֽ⁠wò׃"],[49,15,"אַךְ־אֱלֹהִ֗ים יִפְדֶּ֣ה נַ֭פְשִׁ⁠י מִֽ⁠יַּד־שְׁא֑וֹל כִּ֖י יִקָּחֵ֣⁠נִי סֶֽלָה׃","ʼakĕ-ʼèlòhi֗ym yipĕdė֣h na֭pĕşǐ⁠y miֽ⁠yȧd-şĕ̌ʼ֑wòl ki֖̇y yiqá̇ẖé֣⁠niy seֽláh׃"],[49,16,"אַל־תִּ֭ירָא כִּֽי־יַעֲשִׁ֣ר אִ֑ישׁ כִּֽי־יִ֝רְבֶּה כְּב֣וֹד בֵּיתֽ⁠וֹ׃","ʼal-ţi֭̇yráʼ kiֽ̇y-yaʻàşǐ֣r ʼi֑yş̌ kiֽ̇y-yi֝rĕbėh kĕ̇b֣wòd bé̇yţֽ⁠wò׃"],[49,17,"כִּ֤י לֹ֣א בְ֭⁠מוֹת⁠וֹ יִקַּ֣ח הַ⁠כֹּ֑ל לֹא־יֵרֵ֖ד אַחֲרָ֣י⁠ו כְּבוֹדֽ⁠וֹ׃","ki֤̇y lò֣ʼ bĕ֭⁠mwòţ⁠wò yiqȧ֣ẖ ha⁠kò֑̇l lòʼ-yéré֖d ʼaẖàrá֣y⁠w kĕ̇bwòdֽ⁠wò׃"],[49,18,"כִּֽי־נַ֭פְשׁ⁠וֹ בְּ⁠חַיָּ֣י⁠ו יְבָרֵ֑ךְ וְ֝⁠יוֹדֻ֗⁠ךָ כִּי־תֵיטִ֥יב לָֽ⁠ךְ׃","kiֽ̇y-na֭pĕş̌⁠wò bĕ̇⁠ẖayá֣̇y⁠w yĕbáré֑kĕ wĕ֝⁠ywòdu֗⁠ká ki̇y-ţéyti֥yb láֽ⁠kĕ׃"],[49,19,"תָּ֭בוֹא עַד־דּ֣וֹר אֲבוֹתָ֑י⁠ו עַד־נֵ֝֗צַח לֹ֣א יִרְאוּ־אֽוֹר׃","ţá֭̇bwòʼ ʻad-ḋ֣wòr ʼàbwòţá֑y⁠w ʻad-né֝֗ẕaẖ lò֣ʼ yirĕʼẇ-ʼֽwòr׃"],[49,20,"אָדָ֣ם בִּ֭⁠יקָר וְ⁠לֹ֣א יָבִ֑ין נִמְשַׁ֖ל כַּ⁠בְּהֵמ֣וֹת נִדְמֽוּ׃","ʼádá֣m bi֭̇⁠yqár wĕ⁠lò֣ʼ yábi֑yn nimĕşǎ֖l kȧ⁠bĕ̇hém֣wòţ nidĕmֽẇ׃"],[50,1,"מִזְמ֗וֹר לְ⁠אָ֫סָ֥ף אֵ֤ל ׀ אֱֽלֹהִ֡ים יְֽהוָ֗ה דִּבֶּ֥ר וַ⁠יִּקְרָא־אָ֑רֶץ מִ⁠מִּזְרַח־שֶׁ֝֗מֶשׁ עַד־מְבֹאֽ⁠וֹ׃","mizĕm֗wòr lĕ⁠ʼá֫sá֥p ʼé֤l ׀ ʼèֽlòhi֡ym yĕֽhwá֗h di̇bė֥r wa⁠yi̇qĕráʼ-ʼá֑reẕ mi⁠mi̇zĕraẖ-şě֝֗meş̌ ʻad-mĕbòʼֽ⁠wò׃"],[50,2,"מִ⁠צִּיּ֥וֹן מִכְלַל־יֹ֗פִי אֱלֹהִ֥ים הוֹפִֽיעַ׃","mi⁠ẕi̇ẏ֥wòn mikĕlal-yò֗piy ʼèlòhi֥ym hwòpiֽyʻa׃"],[50,3,"יָ֤בֹ֥א אֱלֹהֵ֗י⁠נוּ וְֽ⁠אַל־יֶ֫חֱרַ֥שׁ אֵשׁ־לְ⁠פָנָ֥י⁠ו תֹּאכֵ֑ל וּ֝⁠סְבִיבָ֗י⁠ו נִשְׂעֲרָ֥ה מְאֹֽד׃","yá֤bò֥ʼ ʼèlòhé֗y⁠nẇ wĕֽ⁠ʼal-ye֫ẖèra֥ş̌ ʼéş̌-lĕ⁠páná֥y⁠w ţò̇ʼké֑l ẇ֝⁠sĕbiybá֗y⁠w nişĕ̂ʻàrá֥h mĕʼòֽd׃"],[50,4,"יִקְרָ֣א אֶל־הַ⁠שָּׁמַ֣יִם מֵ⁠עָ֑ל וְ⁠אֶל־הָ֝⁠אָ֗רֶץ לָ⁠דִ֥ין עַמּֽ⁠וֹ׃","yiqĕrá֣ʼ ʼel-ha⁠şá̇̌ma֣yim mé⁠ʻá֑l wĕ⁠ʼel-há֝⁠ʼá֗reẕ lá⁠di֥yn ʻaṁֽ⁠wò׃"],[50,5,"אִסְפוּ־לִ֥⁠י חֲסִידָ֑⁠י כֹּרְתֵ֖י בְרִיתִ֣⁠י עֲלֵי־זָֽבַח׃","ʼisĕpẇ-li֥⁠y ẖàsiydá֑⁠y kò̇rĕţé֖y bĕriyţi֣⁠y ʻàléy-záֽbaẖ׃"],[50,6,"וַ⁠יַּגִּ֣ידוּ שָׁמַ֣יִם צִדְק֑⁠וֹ כִּֽי־אֱלֹהִ֓ים ׀ שֹׁפֵ֖ט ה֣וּא סֶֽלָה׃","wa⁠yȧgi֣̇ydẇ şá̌ma֣yim ẕidĕq֑⁠wò kiֽ̇y-ʼèlòhi֓ym ׀ şò̌pé֖t h֣ẇʼ seֽláh׃"],[50,7,"שִׁמְעָ֤⁠ה עַמִּ֨⁠י ׀ וַ⁠אֲדַבֵּ֗רָה יִ֭שְׂרָאֵל וְ⁠אָעִ֣ידָה בָּ֑⁠ךְ אֱלֹהִ֖ים אֱלֹהֶ֣י⁠ךָ אָנֹֽכִי׃","şǐmĕʻá֤⁠h ʻami̇֨⁠y ׀ wa⁠ʼàdabé̇֗ráh yi֭şĕ̂ráʼél wĕ⁠ʼáʻi֣ydáh bá֑̇⁠kĕ ʼèlòhi֖ym ʼèlòhe֣y⁠ká ʼánòֽkiy׃"],[50,8,"לֹ֣א עַל־זְ֭בָחֶי⁠ךָ אוֹכִיחֶ֑⁠ךָ וְ⁠עוֹלֹתֶ֖י⁠ךָ לְ⁠נֶגְדִּ֣⁠י תָמִֽיד׃","lò֣ʼ ʻal-zĕ֭báẖey⁠ká ʼwòkiyẖe֑⁠ká wĕ⁠ʻwòlòţe֖y⁠ká lĕ⁠negĕdi֣̇⁠y ţámiֽyd׃"],[50,9,"לֹא־אֶקַּ֣ח מִ⁠בֵּיתְ⁠ךָ֣ פָ֑ר מִ֝⁠מִּכְלְאֹתֶ֗י⁠ךָ עַתּוּדִֽים׃","lòʼ-ʼeqȧ֣ẖ mi⁠bé̇yţĕ⁠ká֣ pá֑r mi֝⁠mi̇kĕlĕʼòţe֗y⁠ká ʻaţ̇ẇdiֽym׃"],[50,10,"כִּי־לִ֥⁠י כָל־חַיְת⁠וֹ־יָ֑עַר בְּ֝הֵמ֗וֹת בְּ⁠הַרְרֵי־אָֽלֶף׃","ki̇y-li֥⁠y kál-ẖayĕţ⁠wò-yá֑ʻar bĕ̇֝hém֗wòţ bĕ̇⁠harĕréy-ʼáֽlep׃"],[50,11,"יָ֭דַעְתִּי כָּל־ע֣וֹף הָרִ֑ים וְ⁠זִ֥יז שָׂ֝דַ֗י עִמָּדִֽ⁠י׃","yá֭daʻĕţi̇y ká̇l-ʻ֣wòp hári֑ym wĕ⁠zi֥yz şá̂֝da֗y ʻimá̇diֽ⁠y׃"],[50,12,"אִם־אֶ֭רְעַב לֹא־אֹ֣מַר לָ֑⁠ךְ כִּי־לִ֥⁠י תֵ֝בֵ֗ל וּ⁠מְלֹאָֽ⁠הּ׃","ʼim-ʼe֭rĕʻab lòʼ-ʼò֣mar lá֑⁠kĕ ki̇y-li֥⁠y ţé֝bé֗l ẇ⁠mĕlòʼáֽ⁠ḣ׃"],[50,13,"הַֽ֭⁠אוֹכַל בְּשַׂ֣ר אַבִּירִ֑ים וְ⁠דַ֖ם עַתּוּדִ֣ים אֶשְׁתֶּֽה׃","haֽ֭⁠ʼwòkal bĕ̇şâ֣r ʼabi̇yri֑ym wĕ⁠da֖m ʻaţ̇ẇdi֣ym ʼeşĕ̌ţėֽh׃"],[50,14,"זְבַ֣ח לֵ⁠אלֹהִ֣ים תּוֹדָ֑ה וְ⁠שַׁלֵּ֖ם לְ⁠עֶלְי֣וֹן נְדָרֶֽי⁠ךָ׃","zĕba֣ẖ lé⁠ʼlòhi֣ym ţ̇wòdá֑h wĕ⁠şǎlé֖̇m lĕ⁠ʻelĕy֣wòn nĕdáreֽy⁠ká׃"],[50,15,"וּ֭⁠קְרָאֵ⁠נִי בְּ⁠י֣וֹם צָרָ֑ה אֲ֝חַלֶּצְ⁠ךָ֗ וּֽ⁠תְכַבְּדֵֽ⁠נִי׃","ẇ֭⁠qĕráʼé⁠niy bĕ̇⁠y֣wòm ẕárá֑h ʼà֝ẖalėẕĕ⁠ká֗ ẇֽ⁠ţĕkabĕ̇déֽ⁠niy׃"],[50,16,"וְ⁠לָ֤⁠רָשָׁ֨ע ׀ אָ֘מַ֤ר אֱלֹהִ֗ים מַה־לְּ֭⁠ךָ לְ⁠סַפֵּ֣ר חֻקָּ֑⁠י וַ⁠תִּשָּׂ֖א בְרִיתִ֣⁠י עֲלֵי־פִֽי⁠ךָ׃","wĕ⁠lá֤⁠ráşá̌֨ʻ ׀ ʼá֘ma֤r ʼèlòhi֗ym mah-lĕ֭̇⁠ká lĕ⁠sapé֣̇r ẖuqá֑̇⁠y wa⁠ţi̇şá֖̇̂ʼ bĕriyţi֣⁠y ʻàléy-piֽy⁠ká׃"],[50,17,"וְ֭⁠אַתָּה שָׂנֵ֣אתָ מוּסָ֑ר וַ⁠תַּשְׁלֵ֖ךְ דְּבָרַ֣⁠י אַחֲרֶֽי⁠ךָ׃","wĕ֭⁠ʼaţá̇h şá̂né֣ʼţá mẇsá֑r wa⁠ţȧşĕ̌lé֖kĕ dĕ̇bára֣⁠y ʼaẖàreֽy⁠ká׃"],[50,18,"אִם־רָאִ֣יתָ גַ֭נָּב וַ⁠תִּ֣רֶץ עִמּ֑⁠וֹ וְ⁠עִ֖ם מְנָאֲפִ֣ים חֶלְקֶֽ⁠ךָ׃","ʼim-ráʼi֣yţá ga֭ná̇b wa⁠ţi֣̇reẕ ʻiṁ֑⁠wò wĕ⁠ʻi֖m mĕnáʼàpi֣ym ẖelĕqeֽ⁠ká׃"],[50,19,"פִּ֭י⁠ךָ שָׁלַ֣חְתָּ בְ⁠רָעָ֑ה וּ֝⁠לְשׁוֹנְ⁠ךָ֗ תַּצְמִ֥יד מִרְמָֽה׃","pi֭̇y⁠ká şá̌la֣ẖĕţá̇ bĕ⁠ráʻá֑h ẇ֝⁠lĕş̌wònĕ⁠ká֗ ţȧẕĕmi֥yd mirĕmáֽh׃"],[50,20,"תֵּ֭שֵׁב בְּ⁠אָחִ֣י⁠ךָ תְדַבֵּ֑ר בְּ⁠בֶֽן־אִ֝מְּ⁠ךָ֗ תִּתֶּן־דֹּֽפִי׃","ţé֭̇şé̌b bĕ̇⁠ʼáẖi֣y⁠ká ţĕdabé֑̇r bĕ̇⁠beֽn-ʼi֝mĕ̇⁠ká֗ ţi̇ţėn-dòֽ̇piy׃"],[50,21,"אֵ֤לֶּה עָשִׂ֨יתָ ׀ וְֽ⁠הֶחֱרַ֗שְׁתִּי דִּמִּ֗יתָ הֱֽיוֹת־אֶֽהְיֶ֥ה כָמ֑וֹ⁠ךָ אוֹכִיחֲ⁠ךָ֖ וְ⁠אֶֽעֶרְכָ֣ה לְ⁠עֵינֶֽי⁠ךָ׃","ʼé֤lėh ʻáşî֨yţá ׀ wĕֽ⁠heẖèra֗şĕ̌ţi̇y di̇mi̇֗yţá hèֽywòţ-ʼeֽhĕye֥h kám֑wò⁠ká ʼwòkiyẖà⁠ká֖ wĕ⁠ʼeֽʻerĕká֣h lĕ⁠ʻéyneֽy⁠ká׃"],[50,22,"בִּֽינוּ־נָ֣א זֹ֭את שֹׁכְחֵ֣י אֱל֑וֹהַּ פֶּן־אֶ֝טְרֹ֗ף וְ⁠אֵ֣ין מַצִּֽיל׃","biֽ̇ynẇ-ná֣ʼ zò֭ʼţ şò̌kĕẖé֣y ʼèl֑wòhȧ pėn-ʼe֝tĕrò֗p wĕ⁠ʼé֣yn maẕiֽ̇yl׃"],[50,23,"זֹבֵ֥חַ תּוֹדָ֗ה יְֽכַ֫בְּדָ֥⁠נְנִי וְ⁠שָׂ֥ם דֶּ֑רֶךְ אַ֝רְאֶ֗⁠נּוּ בְּ⁠יֵ֣שַׁע אֱלֹהִֽים׃","zòbé֥ẖa ţ̇wòdá֗h yĕֽka֫bĕ̇dá֥⁠nĕniy wĕ⁠şá֥̂m dė֑rekĕ ʼa֝rĕʼe֗⁠ṅẇ bĕ̇⁠yé֣şǎʻ ʼèlòhiֽym׃"],[51,1,"חָנֵּ֣⁠נִי אֱלֹהִ֣ים כְּ⁠חַסְדֶּ֑⁠ךָ כְּ⁠רֹ֥ב רַ֝חֲמֶ֗י⁠ךָ מְחֵ֣ה פְשָׁעָֽ⁠י׃","ẖáné֣̇⁠niy ʼèlòhi֣ym kĕ̇⁠ẖasĕdė֑⁠ká kĕ̇⁠rò֥b ra֝ẖàme֗y⁠ká mĕẖé֣h pĕşá̌ʻáֽ⁠y׃"],[51,2,"הרבה כַּבְּסֵ֣⁠נִי מֵ⁠עֲוֺנִ֑⁠י וּֽ⁠מֵ⁠חַטָּאתִ֥⁠י טַהֲרֵֽ⁠נִי׃","hrbh kȧbĕ̇sé֣⁠niy mé⁠ʻàwֺni֑⁠y ẇֽ⁠mé⁠ẖatá̇ʼţi֥⁠y tahàréֽ⁠niy׃"],[51,3,"כִּֽי־פְ֭שָׁעַ⁠י אֲנִ֣י אֵדָ֑ע וְ⁠חַטָּאתִ֖⁠י נֶגְדִּ֣⁠י תָמִֽיד׃","kiֽ̇y-pĕ֭şá̌ʻa⁠y ʼàni֣y ʼédá֑ʻ wĕ⁠ẖatá̇ʼţi֖⁠y negĕdi֣̇⁠y ţámiֽyd׃"],[51,4,"לְ⁠ךָ֤ לְ⁠בַדְּ⁠ךָ֨ ׀ חָטָאתִי֮ וְ⁠הָ⁠רַ֥ע בְּ⁠עֵינֶ֗י⁠ךָ עָ֫שִׂ֥יתִי לְ֭מַעַן תִּצְדַּ֥ק בְּ⁠דָבְרֶ֗⁠ךָ תִּזְכֶּ֥ה בְ⁠שָׁפְטֶֽ⁠ךָ׃","lĕ⁠ká֤ lĕ⁠badĕ̇⁠ká֨ ׀ ẖátáʼţiy֮ wĕ⁠há⁠ra֥ʻ bĕ̇⁠ʻéyne֗y⁠ká ʻá֫şî֥yţiy lĕ֭maʻan ţi̇ẕĕdȧ֥q bĕ̇⁠dábĕre֗⁠ká ţi̇zĕkė֥h bĕ⁠şá̌pĕteֽ⁠ká׃"],[51,5,"הֵן־בְּ⁠עָו֥וֹן חוֹלָ֑לְתִּי וּ֝⁠בְ⁠חֵ֗טְא יֶֽחֱמַ֥תְ⁠נִי אִמִּֽ⁠י׃","hén-bĕ̇⁠ʻáw֥wòn ẖwòlá֑lĕţi̇y ẇ֝⁠bĕ⁠ẖé֗tĕʼ yeֽẖèma֥ţĕ⁠niy ʼimiֽ̇⁠y׃"],[51,6,"הֵן־אֱ֭מֶת חָפַ֣צְתָּ בַ⁠טֻּח֑וֹת וּ֝⁠בְ⁠סָתֻ֗ם חָכְמָ֥ה תוֹדִיעֵֽ⁠נִי׃","hén-ʼè֭meţ ẖápa֣ẕĕţá̇ ba⁠tu̇ẖ֑wòţ ẇ֝⁠bĕ⁠sáţu֗m ẖákĕmá֥h ţwòdiyʻéֽ⁠niy׃"],[51,7,"תְּחַטְּאֵ֣⁠נִי בְ⁠אֵז֣וֹב וְ⁠אֶטְהָ֑ר תְּ֝כַבְּסֵ֗⁠נִי וּ⁠מִ⁠שֶּׁ֥לֶג אַלְבִּֽין׃","ţĕ̇ẖatĕ̇ʼé֣⁠niy bĕ⁠ʼéz֣wòb wĕ⁠ʼetĕhá֑r ţĕ̇֝kabĕ̇sé֗⁠niy ẇ⁠mi⁠şė֥̌leg ʼalĕbiֽ̇yn׃"],[51,8,"תַּ֭שְׁמִיעֵ⁠נִי שָׂשׂ֣וֹן וְ⁠שִׂמְחָ֑ה תָּ֝גֵ֗לְנָה עֲצָמ֥וֹת דִּכִּֽיתָ׃","ţȧ֭şĕ̌miyʻé⁠niy şá̂ş֣̂wòn wĕ⁠şîmĕẖá֑h ţá̇֝gé֗lĕnáh ʻàẕám֥wòţ di̇kiֽ̇yţá׃"],[51,9,"הַסְתֵּ֣ר פָּ֭נֶי⁠ךָ מֵ⁠חֲטָאָ֑⁠י וְֽ⁠כָל־עֲוֺ֖נֹתַ֣⁠י מְחֵֽה׃","hasĕţé֣̇r pá֭̇ney⁠ká mé⁠ẖàtáʼá֑⁠y wĕֽ⁠kál-ʻàwֺ֖nòţa֣⁠y mĕẖéֽh׃"],[51,10,"לֵ֣ב טָ֭הוֹר בְּרָא־לִ֣⁠י אֱלֹהִ֑ים וְ⁠ר֥וּחַ נָ֝כ֗וֹן חַדֵּ֥שׁ בְּ⁠קִרְבִּֽ⁠י׃","lé֣b tá֭hwòr bĕ̇ráʼ-li֣⁠y ʼèlòhi֑ym wĕ⁠r֥ẇẖa ná֝k֗wòn ẖadé֥̇ş̌ bĕ̇⁠qirĕbiֽ̇⁠y׃"],[51,11,"אַל־תַּשְׁלִיכֵ֥⁠נִי מִ⁠לְּ⁠פָנֶ֑י⁠ךָ וְ⁠ר֥וּחַ קָ֝דְשְׁ⁠ךָ֗ אַל־תִּקַּ֥ח מִמֶּֽ⁠נִּי׃","ʼal-ţȧşĕ̌liyké֥⁠niy mi⁠lĕ̇⁠páne֑y⁠ká wĕ⁠r֥ẇẖa qá֝dĕşĕ̌⁠ká֗ ʼal-ţi̇qȧ֥ẖ mimėֽ⁠ni̇y׃"],[51,12,"הָשִׁ֣יבָ⁠ה לִּ֭⁠י שְׂשׂ֣וֹן יִשְׁעֶ֑⁠ךָ וְ⁠ר֖וּחַ נְדִיבָ֣ה תִסְמְכֵֽ⁠נִי׃","háşǐ֣ybá⁠h li֭̇⁠y şĕ̂ş֣̂wòn yişĕ̌ʻe֑⁠ká wĕ⁠r֖ẇẖa nĕdiybá֣h ţisĕmĕkéֽ⁠niy׃"],[51,13,"אֲלַמְּדָ֣ה פֹשְׁעִ֣ים דְּרָכֶ֑י⁠ךָ וְ֝⁠חַטָּאִ֗ים אֵלֶ֥י⁠ךָ יָשֽׁוּבוּ׃","ʼàlamĕ̇dá֣h pòşĕ̌ʻi֣ym dĕ̇ráke֑y⁠ká wĕ֝⁠ẖatá̇ʼi֗ym ʼéle֥y⁠ká yáşֽ̌ẇbẇ׃"],[51,14,"הַצִּ֘ילֵ֤⁠נִי מִ⁠דָּמִ֨ים ׀ אֱֽלֹהִ֗ים אֱלֹהֵ֥י תְּשׁוּעָתִ֑⁠י תְּרַנֵּ֥ן לְ֝שׁוֹנִ֗⁠י צִדְקָתֶֽ⁠ךָ׃","haẕi̇֘ylé֤⁠niy mi⁠dá̇mi֨ym ׀ ʼèֽlòhi֗ym ʼèlòhé֥y ţĕ̇ş̌ẇʻáţi֑⁠y ţĕ̇rané֥̇n lĕ֝ş̌wòni֗⁠y ẕidĕqáţeֽ⁠ká׃"],[51,15,"אֲ֭דֹנָ⁠י שְׂפָתַ֣⁠י תִּפְתָּ֑ח וּ֝⁠פִ֗⁠י יַגִּ֥יד תְּהִלָּתֶֽ⁠ךָ׃","ʼà֭dòná⁠y şĕ̂páţa֣⁠y ţi̇pĕţá֑̇ẖ ẇ֝⁠pi֗⁠y yagi֥̇yd ţĕ̇hilá̇ţeֽ⁠ká׃"],[51,16,"כִּ֤י ׀ לֹא־תַחְפֹּ֣ץ זֶ֣בַח וְ⁠אֶתֵּ֑נָה ע֝וֹלָ֗ה לֹ֣א תִרְצֶֽה׃","ki֤̇y ׀ lòʼ-ţaẖĕpò֣̇ẕ ze֣baẖ wĕ⁠ʼeţé֑̇náh ʻ֝wòlá֗h lò֣ʼ ţirĕẕeֽh׃"],[51,17,"זִֽבְחֵ֣י אֱלֹהִים֮ ר֪וּחַ נִשְׁבָּ֫רָ֥ה לֵב־נִשְׁבָּ֥ר וְ⁠נִדְכֶּ֑ה אֱ֝לֹהִ֗ים לֹ֣א תִבְזֶֽה׃","ziֽbĕẖé֣y ʼèlòhiym֮ r֪ẇẖa nişĕ̌bá̇֫rá֥h léb-nişĕ̌bá֥̇r wĕ⁠nidĕkė֑h ʼè֝lòhi֗ym lò֣ʼ ţibĕzeֽh׃"],[51,18,"הֵיטִ֣יבָ⁠ה בִ֭⁠רְצוֹנְ⁠ךָ אֶת־צִיּ֑וֹן תִּ֝בְנֶ֗ה חוֹמ֥וֹת יְרוּשָׁלִָֽם׃","héyti֣ybá⁠h bi֭⁠rĕẕwònĕ⁠ká ʼeţ-ẕiẏ֑wòn ţi̇֝bĕne֗h ẖwòm֥wòţ yĕrẇşá̌liáֽm׃"],[51,19,"אָ֤ז תַּחְפֹּ֣ץ זִבְחֵי־צֶ֭דֶק עוֹלָ֣ה וְ⁠כָלִ֑יל אָ֤ז יַעֲל֖וּ עַל־מִזְבַּחֲ⁠ךָ֣ פָרִֽים׃","ʼá֤z ţȧẖĕpò֣̇ẕ zibĕẖéy-ẕe֭deq ʻwòlá֣h wĕ⁠káli֑yl ʼá֤z yaʻàl֖ẇ ʻal-mizĕbȧẖà⁠ká֣ páriֽym׃"],[52,1,"מַה־תִּתְהַלֵּ֣ל בְּ֭⁠רָעָה הַ⁠גִּבּ֑וֹר חֶ֥סֶד אֵ֝֗ל כָּל־הַ⁠יּֽוֹם׃","mah-ţi̇ţĕhalé֣̇l bĕ֭̇⁠ráʻáh ha⁠gi̇ḃ֑wòr ẖe֥sed ʼé֝֗l ká̇l-ha⁠ẏֽwòm׃"],[52,2,"הַ֭וּוֹת תַּחְשֹׁ֣ב לְשׁוֹנֶ֑⁠ךָ כְּ⁠תַ֥עַר מְ֝לֻטָּ֗שׁ עֹשֵׂ֥ה רְמִיָּֽה׃","ha֭ẇwòţ ţȧẖĕşò֣̌b lĕş̌wòne֑⁠ká kĕ̇⁠ţa֥ʻar mĕ֝lutá̇֗ş̌ ʻòşé֥̂h rĕmiyáֽ̇h׃"],[52,3,"אָהַ֣בְתָּ רָּ֣ע מִ⁠טּ֑וֹב שֶׁ֓קֶר ׀ מִ⁠דַּבֵּ֖ר צֶ֣דֶק סֶֽלָה׃","ʼáha֣bĕţá̇ rá֣̇ʻ mi⁠ṫ֑wòb şě֓qer ׀ mi⁠dȧbé֖̇r ẕe֣deq seֽláh׃"],[52,4,"אָהַ֥בְתָּ כָֽל־דִּבְרֵי־בָ֗לַע לְשׁ֣וֹן מִרְמָֽה׃","ʼáha֥bĕţá̇ káֽl-di̇bĕréy-bá֗laʻ lĕş֣̌wòn mirĕmáֽh׃"],[52,5,"גַּם־אֵל֮ יִתָּצְ⁠ךָ֪ לָ֫⁠נֶ֥צַח יַחְתְּ⁠ךָ֣ וְ⁠יִסָּחֲ⁠ךָ֣ מֵ⁠אֹ֑הֶל וְ⁠שֵֽׁרֶשְׁ⁠ךָ֨ מֵ⁠אֶ֖רֶץ חַיִּ֣ים סֶֽלָה׃","gȧm-ʼél֮ yiţá̇ẕĕ⁠ká֪ lá֫⁠ne֥ẕaẖ yaẖĕţĕ̇⁠ká֣ wĕ⁠yisá̇ẖà⁠ká֣ mé⁠ʼò֑hel wĕ⁠şéֽ̌reşĕ̌⁠ká֨ mé⁠ʼe֖reẕ ẖayi֣̇ym seֽláh׃"],[52,6,"וְ⁠יִרְא֖וּ צַדִּיקִ֥ים וְ⁠יִירָ֗אוּ וְ⁠עָלָ֥י⁠ו יִשְׂחָֽקוּ׃","wĕ⁠yirĕʼ֖ẇ ẕadi̇yqi֥ym wĕ⁠yiyrá֗ʼẇ wĕ⁠ʻálá֥y⁠w yişĕ̂ẖáֽqẇ׃"],[52,7,"הִנֵּ֤ה הַ⁠גֶּ֗בֶר לֹ֤א יָשִׂ֥ים אֱלֹהִ֗ים מָֽע֫וּזּ֥⁠וֹ וַ֭⁠יִּבְטַח בְּ⁠רֹ֣ב עָשְׁר֑⁠וֹ יָ֝עֹ֗ז בְּ⁠הַוָּתֽ⁠וֹ׃","hiné֤̇h ha⁠gė֗ber lò֤ʼ yáşî֥ym ʼèlòhi֗ym máֽʻ֫ẇż֥⁠wò wa֭⁠yi̇bĕtaẖ bĕ̇⁠rò֣b ʻáşĕ̌r֑⁠wò yá֝ʻò֗z bĕ̇⁠hawá̇ţֽ⁠wò׃"],[52,8,"וַ⁠אֲנִ֤י ׀ כְּ⁠זַ֣יִת רַ֭עֲנָן בְּ⁠בֵ֣ית אֱלֹהִ֑ים בָּטַ֥חְתִּי בְ⁠חֶֽסֶד־אֱ֝לֹהִ֗ים עוֹלָ֥ם וָ⁠עֶֽד׃","wa⁠ʼàni֤y ׀ kĕ̇⁠za֣yiţ ra֭ʻànán bĕ̇⁠bé֣yţ ʼèlòhi֑ym bá̇ta֥ẖĕţi̇y bĕ⁠ẖeֽsed-ʼè֝lòhi֗ym ʻwòlá֥m wá⁠ʻeֽd׃"],[52,9,"אוֹדְ⁠ךָ֣ לְ֭⁠עוֹלָם כִּ֣י עָשִׂ֑יתָ וַ⁠אֲקַוֶּ֖ה שִׁמְ⁠ךָ֥ כִֽי־ט֝֗וֹב נֶ֣גֶד חֲסִידֶֽי⁠ךָ׃","ʼwòdĕ⁠ká֣ lĕ֭⁠ʻwòlám ki֣̇y ʻáşî֑yţá wa⁠ʼàqawė֖h şǐmĕ⁠ká֥ kiֽy-t֝֗wòb ne֣ged ẖàsiydeֽy⁠ká׃"],[53,1,"אָ֘מַ֤ר נָבָ֣ל בְּ֭⁠לִבּ⁠וֹ אֵ֣ין אֱלֹהִ֑ים הִֽ֝שְׁחִ֗יתוּ וְ⁠הִֽתְעִ֥יבוּ עָ֝֗וֶל אֵ֣ין עֹֽשֵׂה־טֽוֹב׃","ʼá֘ma֤r nábá֣l bĕ֭̇⁠liḃ⁠wò ʼé֣yn ʼèlòhi֑ym hiֽ֝şĕ̌ẖi֗yţẇ wĕ⁠hiֽţĕʻi֥ybẇ ʻá֝֗wel ʼé֣yn ʻòֽşé̂h-tֽwòb׃"],[53,2,"אֱֽלֹהִ֗ים מִ⁠שָּׁמַיִם֮ הִשְׁקִ֪יף עַֽל־בְּנֵ֫י אָדָ֥ם לִ֭⁠רְאוֹת הֲ⁠יֵ֣שׁ מַשְׂכִּ֑יל דֹּ֝רֵ֗שׁ אֶת־אֱלֹהִֽים׃","ʼèֽlòhi֗ym mi⁠şá̇̌mayim֮ hişĕ̌qi֪yp ʻaֽl-bĕ̇né֫y ʼádá֥m li֭⁠rĕʼwòţ hà⁠yé֣ş̌ maşĕ̂ki֑̇yl dò̇֝ré֗ş̌ ʼeţ-ʼèlòhiֽym׃"],[53,3,"כֻּלּ֥⁠וֹ סָג֮ יַחְדָּ֪ו נֶ֫אֱלָ֥חוּ אֵ֤ין עֹֽשֵׂה־ט֑וֹב אֵ֝֗ין גַּם־אֶחָֽד׃","ku̇l֥̇⁠wò ság֮ yaẖĕdá֪̇w ne֫ʼèlá֥ẖẇ ʼé֤yn ʻòֽşé̂h-t֑wòb ʼé֝֗yn gȧm-ʼeẖáֽd׃"],[53,4,"הֲ⁠לֹ֥א יָדְעוּ֮ פֹּ֤עֲלֵ֫י אָ֥וֶן אֹכְלֵ֣י עַ֭מִּ⁠י אָ֣כְלוּ לֶ֑חֶם אֱ֝לֹהִ֗ים לֹ֣א קָרָֽאוּ׃","hà⁠lò֥ʼ yádĕʻẇ֮ pò֤̇ʻàlé֫y ʼá֥wen ʼòkĕlé֣y ʻa֭mi̇⁠y ʼá֣kĕlẇ le֑ẖem ʼè֝lòhi֗ym lò֣ʼ qáráֽʼẇ׃"],[53,5,"שָׁ֤ם ׀ פָּֽחֲדוּ־פַחַד֮ לֹא־הָ֪יָה֫ פָ֥חַד כִּֽי־אֱלֹהִ֗ים פִּ֭זַּר עַצְמ֣וֹת חֹנָ֑⁠ךְ הֱ֝בִשֹׁ֗תָה כִּֽי־אֱלֹהִ֥ים מְאָסָֽ⁠ם׃","şá֤̌m ׀ páֽ̇ẖàdẇ-paẖad֮ lòʼ-há֪yáh֫ pá֥ẖad kiֽ̇y-ʼèlòhi֗ym pi֭̇zȧr ʻaẕĕm֣wòţ ẖòná֑⁠kĕ hè֝bişò̌֗ţáh kiֽ̇y-ʼèlòhi֥ym mĕʼásáֽ⁠m׃"],[53,6,"מִ֥י יִתֵּ֣ן מִ⁠צִּיּוֹן֮ יְשֻׁע֪וֹת יִשְׂרָ֫אֵ֥ל בְּ⁠שׁ֣וּב אֱ֭לֹהִים שְׁב֣וּת עַמּ֑⁠וֹ יָגֵ֥ל יַ֝עֲקֹ֗ב יִשְׂמַ֥ח יִשְׂרָאֵֽל׃","mi֥y yiţé֣̇n mi⁠ẕi̇ẏwòn֮ yĕşǔʻ֪wòţ yişĕ̂rá֫ʼé֥l bĕ̇⁠ş֣̌ẇb ʼè֭lòhiym şĕ̌b֣ẇţ ʻaṁ֑⁠wò yágé֥l ya֝ʻàqò֗b yişĕ̂ma֥ẖ yişĕ̂ráʼéֽl׃"],[54,1,"אֱ֭לֹהִים בְּ⁠שִׁמְ⁠ךָ֣ הוֹשִׁיעֵ֑⁠נִי וּ⁠בִ⁠גְבוּרָתְ⁠ךָ֥ תְדִינֵֽ⁠נִי׃","ʼè֭lòhiym bĕ̇⁠şǐmĕ⁠ká֣ hwòşǐyʻé֑⁠niy ẇ⁠bi⁠gĕbẇráţĕ⁠ká֥ ţĕdiynéֽ⁠niy׃"],[54,2,"אֱ֭לֹהִים שְׁמַ֣ע תְּפִלָּתִ֑⁠י הַ֝אֲזִ֗ינָ⁠ה לְ⁠אִמְרֵי־פִֽ⁠י׃","ʼè֭lòhiym şĕ̌ma֣ʻ ţĕ̇pilá̇ţi֑⁠y ha֝ʼàzi֗yná⁠h lĕ⁠ʼimĕréy-piֽ⁠y׃"],[54,3,"כִּ֤י זָרִ֨ים ׀ קָ֤מוּ עָלַ֗⁠י וְֽ֭⁠עָרִיצִים בִּקְשׁ֣וּ נַפְשִׁ֑⁠י לֹ֤א שָׂ֨מוּ אֱלֹהִ֖ים לְ⁠נֶגְדָּ֣⁠ם סֶֽלָה׃","ki֤̇y zári֨ym ׀ qá֤mẇ ʻála֗⁠y wĕֽ֭⁠ʻáriyẕiym bi̇qĕş֣̌ẇ napĕşǐ֑⁠y lò֤ʼ şá̂֨mẇ ʼèlòhi֖ym lĕ⁠negĕdá֣̇⁠m seֽláh׃"],[54,4,"הִנֵּ֣ה אֱ֭לֹהִים עֹזֵ֣ר לִ֑⁠י אֲ֝דֹנָ֗⁠י בְּֽ⁠סֹמְכֵ֥י נַפְשִֽׁ⁠י׃","hiné֣̇h ʼè֭lòhiym ʻòzé֣r li֑⁠y ʼà֝dòná֗⁠y bĕֽ̇⁠sòmĕké֥y napĕşǐֽ⁠y׃"],[54,5,"ישוב הָ֭⁠רַע לְ⁠שֹׁרְרָ֑⁠י בַּ֝⁠אֲמִתְּ⁠ךָ֗ הַצְמִיתֵֽ⁠ם׃","yşwb há֭⁠raʻ lĕ⁠şò̌rĕrá֑⁠y bȧ֝⁠ʼàmiţĕ̇⁠ká֗ haẕĕmiyţéֽ⁠m׃"],[54,6,"בִּ⁠נְדָבָ֥ה אֶזְבְּחָה־לָּ֑⁠ךְ א֤וֹדֶה שִּׁמְ⁠ךָ֖ יְהוָ֣ה כִּי־טֽוֹב׃","bi̇⁠nĕdábá֥h ʼezĕbĕ̇ẖáh-lá֑̇⁠kĕ ʼ֤wòdeh şi̇̌mĕ⁠ká֖ yĕhwá֣h ki̇y-tֽwòb׃"],[54,7,"כִּ֣י מִ⁠כָּל־צָ֭רָה הִצִּילָ֑⁠נִי וּ֝⁠בְ⁠אֹיְבַ֗⁠י רָאֲתָ֥ה עֵינִֽ⁠י׃","ki֣̇y mi⁠ká̇l-ẕá֭ráh hiẕi̇ylá֑⁠niy ẇ֝⁠bĕ⁠ʼòyĕba֗⁠y ráʼàţá֥h ʻéyniֽ⁠y׃"],[55,1,"הַאֲזִ֣ינָ⁠ה אֱ֭לֹהִים תְּפִלָּתִ֑⁠י וְ⁠אַל־תִּ֝תְעַלַּ֗ם מִ⁠תְּחִנָּתִֽ⁠י׃","haʼàzi֣yná⁠h ʼè֭lòhiym ţĕ̇pilá̇ţi֑⁠y wĕ⁠ʼal-ţi̇֝ţĕʻalȧ֗m mi⁠ţĕ̇ẖiná̇ţiֽ⁠y׃"],[55,2,"הַקְשִׁ֣יבָ⁠ה לִּ֣⁠י וַ⁠עֲנֵ֑⁠נִי אָרִ֖יד בְּ⁠שִׂיחִ֣⁠י וְ⁠אָהִֽימָה׃","haqĕşǐ֣ybá⁠h li֣̇⁠y wa⁠ʻàné֑⁠niy ʼári֖yd bĕ̇⁠şîyẖi֣⁠y wĕ⁠ʼáhiֽymáh׃"],[55,3,"מִ⁠קּ֤וֹל אוֹיֵ֗ב מִ⁠פְּנֵ֣י עָקַ֣ת רָשָׁ֑ע כִּי־יָמִ֥יטוּ עָלַ֥⁠י אָ֝֗וֶן וּ⁠בְ⁠אַ֥ף יִשְׂטְמֽוּ⁠נִי׃","mi⁠q֤̇wòl ʼwòyé֗b mi⁠pĕ̇né֣y ʻáqa֣ţ ráşá֑̌ʻ ki̇y-yámi֥ytẇ ʻála֥⁠y ʼá֝֗wen ẇ⁠bĕ⁠ʼa֥p yişĕ̂tĕmֽẇ⁠niy׃"],[55,4,"לִ֭בִּ⁠י יָחִ֣יל בְּ⁠קִרְבִּ֑⁠י וְ⁠אֵימ֥וֹת מָ֝֗וֶת נָפְל֥וּ עָלָֽ⁠י׃","li֭bi̇⁠y yáẖi֣yl bĕ̇⁠qirĕbi֑̇⁠y wĕ⁠ʼéym֥wòţ má֝֗weţ nápĕl֥ẇ ʻáláֽ⁠y׃"],[55,5,"יִרְאָ֣ה וָ֭⁠רַעַד יָ֣בֹא בִ֑⁠י וַ֝⁠תְּכַסֵּ֗⁠נִי פַּלָּצֽוּת׃","yirĕʼá֣h wá֭⁠raʻad yá֣bòʼ bi֑⁠y wa֝⁠ţĕ̇kasé̇֗⁠niy pȧlá̇ẕֽẇţ׃"],[55,6,"וָ⁠אֹמַ֗ר מִֽי־יִתֶּן־לִּ֣⁠י אֵ֭בֶר כַּ⁠יּוֹנָ֗ה אָע֥וּפָה וְ⁠אֶשְׁכֹּֽנָה׃","wá⁠ʼòma֗r miֽy-yiţėn-li֣̇⁠y ʼé֭ber kȧ⁠ẏwòná֗h ʼáʻ֥ẇpáh wĕ⁠ʼeşĕ̌kòֽ̇náh׃"],[55,7,"הִ֭נֵּה אַרְחִ֣יק נְדֹ֑ד אָלִ֖ין בַּ⁠מִּדְבָּ֣ר סֶֽלָה׃","hi֭né̇h ʼarĕẖi֣yq nĕdò֑d ʼáli֖yn bȧ⁠mi̇dĕbá֣̇r seֽláh׃"],[55,8,"אָחִ֣ישָׁה מִפְלָ֣ט לִ֑⁠י מֵ⁠ר֖וּחַ סֹעָ֣ה מִ⁠סָּֽעַר׃","ʼáẖi֣yşá̌h mipĕlá֣t li֑⁠y mé⁠r֖ẇẖa sòʻá֣h mi⁠sáֽ̇ʻar׃"],[55,9,"בַּלַּ֣ע אֲ֭דֹנָ⁠י פַּלַּ֣ג לְשׁוֹנָ֑⁠ם כִּֽי־רָאִ֨יתִי חָמָ֖ס וְ⁠רִ֣יב בָּ⁠עִֽיר׃","bȧlȧ֣ʻ ʼà֭dòná⁠y pȧlȧ֣g lĕş̌wòná֑⁠m kiֽ̇y-ráʼi֨yţiy ẖámá֖s wĕ⁠ri֣yb bá̇⁠ʻiֽyr׃"],[55,10,"יוֹמָ֤ם וָ⁠לַ֗יְלָה יְסוֹבְבֻ֥⁠הָ עַל־חוֹמֹתֶ֑י⁠הָ וְ⁠אָ֖וֶן וְ⁠עָמָ֣ל בְּ⁠קִרְבָּֽ⁠הּ׃","ywòmá֤m wá⁠la֗yĕláh yĕswòbĕbu֥⁠há ʻal-ẖwòmòţe֑y⁠há wĕ⁠ʼá֖wen wĕ⁠ʻámá֣l bĕ̇⁠qirĕbáֽ̇⁠ḣ׃"],[55,11,"הַוּ֥וֹת בְּ⁠קִרְבָּ֑⁠הּ וְֽ⁠לֹא־יָמִ֥ישׁ מֵ֝⁠רְחֹבָ֗⁠הּ תֹּ֣ךְ וּ⁠מִרְמָֽה׃","haẇ֥wòţ bĕ̇⁠qirĕbá֑̇⁠ḣ wĕֽ⁠lòʼ-yámi֥yş̌ mé֝⁠rĕẖòbá֗⁠ḣ ţò֣̇kĕ ẇ⁠mirĕmáֽh׃"],[55,12,"כִּ֤י לֹֽא־אוֹיֵ֥ב יְחָֽרְפֵ֗⁠נִי וְ⁠אֶ֫שָּׂ֥א לֹֽא־מְ֭שַׂנְאִ⁠י עָלַ֣⁠י הִגְדִּ֑יל וְ⁠אֶסָּתֵ֥ר מִמֶּֽ⁠נּוּ׃","ki֤̇y lòֽʼ-ʼwòyé֥b yĕẖáֽrĕpé֗⁠niy wĕ⁠ʼe֫şá֥̇̂ʼ lòֽʼ-mĕ֭şânĕʼi⁠y ʻála֣⁠y higĕdi֑̇yl wĕ⁠ʼesá̇ţé֥r mimėֽ⁠ṅẇ׃"],[55,13,"וְ⁠אַתָּ֣ה אֱנ֣וֹשׁ כְּ⁠עֶרְכִּ֑⁠י אַ֝לּוּפִ֗⁠י וּ⁠מְיֻדָּֽעִ⁠י׃","wĕ⁠ʼaţá֣̇h ʼèn֣wòş̌ kĕ̇⁠ʻerĕki֑̇⁠y ʼa֝l̇ẇpi֗⁠y ẇ⁠mĕyudáֽ̇ʻi⁠y׃"],[55,14,"אֲשֶׁ֣ר יַ֭חְדָּו נַמְתִּ֣יק ס֑וֹד בְּ⁠בֵ֥ית אֱ֝לֹהִ֗ים נְהַלֵּ֥ךְ בְּ⁠רָֽגֶשׁ׃","ʼàşě֣r ya֭ẖĕdá̇w namĕţi֣̇yq s֑wòd bĕ̇⁠bé֥yţ ʼè֝lòhi֗ym nĕhalé֥̇kĕ bĕ̇⁠ráֽgeş̌׃"],[55,15,"ישימות עָלֵ֗י⁠מוֹ יֵרְד֣וּ שְׁא֣וֹל חַיִּ֑ים כִּֽי־רָע֖וֹת בִּ⁠מְגוּרָ֣⁠ם בְּ⁠קִרְבָּֽ⁠ם׃","yşymwţ ʻálé֗y⁠mwò yérĕd֣ẇ şĕ̌ʼ֣wòl ẖayi֑̇ym kiֽ̇y-ráʻ֖wòţ bi̇⁠mĕgẇrá֣⁠m bĕ̇⁠qirĕbáֽ̇⁠m׃"],[55,16,"אֲ֭נִי אֶל־אֱלֹהִ֣ים אֶקְרָ֑א וַ֝⁠יהוָ֗ה יוֹשִׁיעֵֽ⁠נִי׃","ʼà֭niy ʼel-ʼèlòhi֣ym ʼeqĕrá֑ʼ wa֝⁠yhwá֗h ywòşǐyʻéֽ⁠niy׃"],[55,17,"עֶ֤רֶב וָ⁠בֹ֣קֶר וְ֭⁠צָהֳרַיִם אָשִׂ֣יחָה וְ⁠אֶהֱמֶ֑ה וַ⁠יִּשְׁמַ֥ע קוֹלִֽ⁠י׃","ʻe֤reb wá⁠bò֣qer wĕ֭⁠ẕáhorayim ʼáşî֣yẖáh wĕ⁠ʼehème֑h wa⁠yi̇şĕ̌ma֥ʻ qwòliֽ⁠y׃"],[55,18,"פָּ֘דָ֤ה בְ⁠שָׁל֣וֹם נַ֭פְשִׁ⁠י מִ⁠קֲּרָב־לִ֑⁠י כִּֽי־בְ֝⁠רַבִּ֗ים הָי֥וּ עִמָּדִֽ⁠י׃","pá̇֘dá֤h bĕ⁠şá̌l֣wòm na֭pĕşǐ⁠y mi⁠qà̇ráb-li֑⁠y kiֽ̇y-bĕ֝⁠rabi̇֗ym háy֥ẇ ʻimá̇diֽ⁠y׃"],[55,19,"יִשְׁמַ֤ע ׀ אֵ֨ל ׀ וְֽ⁠יַעֲנֵ⁠ם֮ וְ⁠יֹ֤שֵׁ֥ב קֶ֗דֶם סֶ֥לָה אֲשֶׁ֤ר אֵ֣ין חֲלִיפ֣וֹת לָ֑⁠מוֹ וְ⁠לֹ֖א יָרְא֣וּ אֱלֹהִֽים׃","yişĕ̌ma֤ʻ ׀ ʼé֨l ׀ wֽĕ⁠yaʻàné⁠m֮ wĕ⁠yò֤şé֥̌b qe֗dem se֥láh ʼàşě֤r ʼé֣yn ẖàliyp֣wòţ lá֑⁠mwò wĕ⁠lò֖ʼ yárĕʼ֣ẇ ʼèlòhiֽym׃"],[55,20,"שָׁלַ֣ח יָ֭דָי⁠ו בִּ⁠שְׁלֹמָ֗י⁠ו חִלֵּ֥ל בְּרִיתֽ⁠וֹ׃","şá̌la֣ẖ yá֭dáy⁠w bi̇⁠şĕ̌lòmá֗y⁠w ẖilé֥̇l bĕ̇riyţֽ⁠wò׃"],[55,21,"חָלְק֤וּ ׀ מַחְמָאֹ֣ת פִּי⁠ו֮ וּֽ⁠קֲרָב־לִ֫בּ֥⁠וֹ רַכּ֖וּ דְבָרָ֥י⁠ו מִ⁠שֶּׁ֗מֶן וְ⁠הֵ֣מָּה פְתִחֽוֹת׃","ẖálĕq֤ẇ ׀ maẖĕmáʼò֣ţ pi̇y⁠w֮ ẇֽ⁠qàráb-li֫ḃ֥⁠wò rak֖̇ẇ dĕbárá֥y⁠w mi⁠şė̌֗men wĕ⁠hé֣má̇h pĕţiẖֽwòţ׃"],[55,22,"הַשְׁלֵ֤ךְ עַל־יְהוָ֨ה ׀ יְהָבְ⁠ךָ֮ וְ⁠ה֪וּא יְכַ֫לְכְּלֶ֥⁠ךָ לֹא־יִתֵּ֖ן לְ⁠עוֹלָ֥ם מ֗וֹט לַ⁠צַּדִּֽיק׃","haşĕ̌lé֤kĕ ʻal-yĕhwá֨h ׀ yĕhábĕ⁠ká֮ wĕ⁠h֪ẇʼ yĕka֫lĕkĕ̇le֥⁠ká lòʼ-yiţé֖̇n lĕ⁠ʻwòlá֥m m֗wòt la⁠ẕȧdiֽ̇yq׃"],[55,23,"וְ⁠אַתָּ֤ה אֱלֹהִ֨ים ׀ תּוֹרִדֵ֬⁠ם ׀ לִ⁠בְאֵ֬ר שַׁ֗חַת אַנְשֵׁ֤י דָמִ֣ים וּ֭⁠מִרְמָה לֹא־יֶחֱצ֣וּ יְמֵי⁠הֶ֑ם וַ֝⁠אֲנִ֗י אֶבְטַח־בָּֽ⁠ךְ׃","wĕ⁠ʼaţá֤̇h ʼèlòhi֨ym ׀ ţ̇wòridé֬⁠m ׀ li⁠bĕʼé֬r şǎ֗ẖaţ ʼanĕşé֤̌y dámi֣ym ẇ֭⁠mirĕmáh lòʼ-yeẖèẕ֣ẇ yĕméy⁠he֑m wa֝⁠ʼàni֗y ʼebĕtaẖ-báֽ̇⁠kĕ׃"],[56,1,"חָנֵּ֣⁠נִי אֱ֭לֹהִים כִּֽי־שְׁאָפַ֣⁠נִי אֱנ֑וֹשׁ כָּל־הַ֝⁠יּ֗וֹם לֹחֵ֥ם יִלְחָצֵֽ⁠נִי׃","ẖáné֣̇⁠niy ʼè֭lòhiym kiֽ̇y-şĕ̌ʼápa֣⁠niy ʼèn֑wòş̌ ká̇l-ha֝⁠ẏ֗wòm lòẖé֥m yilĕẖáẕéֽ⁠niy׃"],[56,2,"שָׁאֲפ֣וּ שׁ֭וֹרְרַ⁠י כָּל־הַ⁠יּ֑וֹם כִּֽי־רַבִּ֨ים לֹחֲמִ֖ים לִ֣⁠י מָרֽוֹם׃","şá̌ʼàp֣ẇ ş֭̌wòrĕra⁠y ká̇l-ha⁠ẏ֑wòm kiֽ̇y-rabi̇֨ym lòẖàmi֖ym li֣⁠y márֽwòm׃"],[56,3,"י֥וֹם אִירָ֑א אֲ֝נִ֗י אֵלֶ֥י⁠ךָ אֶבְטָֽח׃","y֥wòm ʼiyrá֑ʼ ʼà֝ni֗y ʼéle֥y⁠ká ʼebĕtáֽẖ׃"],[56,4,"בֵּ⁠אלֹהִים֮ אֲהַלֵּ֪ל דְּבָ֫ר֥⁠וֹ בֵּ⁠אלֹהִ֣ים בָּ֭טַחְתִּי לֹ֣א אִירָ֑א מַה־יַּעֲשֶׂ֖ה בָשָׂ֣ר לִֽ⁠י׃","bé̇⁠ʼlòhiym֮ ʼàhalé֪̇l dĕ̇bá֫r֥⁠wò bé̇⁠ʼlòhi֣ym bá֭̇taẖĕţi̇y lò֣ʼ ʼiyrá֑ʼ mah-yȧʻàşê֖h báşá֣̂r liֽ⁠y׃"],[56,5,"כָּל־הַ֭⁠יּוֹם דְּבָרַ֣⁠י יְעַצֵּ֑בוּ עָלַ֖⁠י כָּל־מַחְשְׁבֹתָ֣⁠ם לָ⁠רָֽע׃","ká̇l-ha֭⁠ẏwòm dĕ̇bára֣⁠y yĕʻaẕé֑̇bẇ ʻála֖⁠y ká̇l-maẖĕşĕ̌bòţá֣⁠m lá⁠ráֽʻ׃"],[56,6,"יָג֤וּרוּ ׀ יצפינו הֵ֭מָּה עֲקֵבַ֣⁠י יִשְׁמֹ֑רוּ כַּ֝⁠אֲשֶׁ֗ר קִוּ֥וּ נַפְשִֽׁ⁠י׃","yág֤ẇrẇ ׀ yẕpynw hé֭má̇h ʻàqéba֣⁠y yişĕ̌mò֑rẇ kȧ֝⁠ʼàşě֗r qiẇ֥ẇ napĕşǐֽ⁠y׃"],[56,7,"עַל־אָ֥וֶן פַּלֶּט־לָ֑⁠מוֹ בְּ֝⁠אַ֗ף עַמִּ֤ים ׀ הוֹרֵ֬ד אֱלֹהִֽים׃","ʻal-ʼá֥wen pȧlėt-lá֑⁠mwò bĕ̇֝⁠ʼa֗p ʻami֤̇ym ׀ hwòré֬d ʼèlòhiֽym׃"],[56,8,"נֹדִ⁠י֮ סָפַ֪רְתָּ֫ה אָ֥תָּה שִׂ֣ימָ⁠ה דִמְעָתִ֣⁠י בְ⁠נֹאדֶ֑⁠ךָ הֲ֝⁠לֹ֗א בְּ⁠סִפְרָתֶֽ⁠ךָ׃","nòdi⁠y֮ sápa֪rĕţá̇֫h ʼá֥ţá̇h şî֣ymá⁠h dimĕʻáţi֣⁠y bĕ⁠nòʼde֑⁠ká hà֝⁠lò֗ʼ bĕ̇⁠sipĕráţeֽ⁠ká׃"],[56,9,"אָ֥֨ז יָ֘שׁ֤וּבוּ אוֹיְבַ֣⁠י אָ֭חוֹר בְּ⁠י֣וֹם אֶקְרָ֑א זֶה־יָ֝דַ֗עְתִּי כִּֽי־אֱלֹהִ֥ים לִֽ⁠י׃","ʼá֥֨z yá֘ş֤̌ẇbẇ ʼwòyĕba֣⁠y ʼá֭ẖwòr bĕ̇⁠y֣wòm ʼeqĕrá֑ʼ zeh-yá֝da֗ʻĕţi̇y kiֽ̇y-ʼèlòhi֥ym liֽ⁠y׃"],[56,10,"בֵּֽ֭⁠אלֹהִים אֲהַלֵּ֣ל דָּבָ֑ר בַּ֝⁠יהוָ֗ה אֲהַלֵּ֥ל דָּבָֽר׃","béֽ֭̇⁠ʼlòhiym ʼàhalé֣̇l dá̇bá֑r bȧ֝⁠yhwá֗h ʼàhalé֥̇l dá̇báֽr׃"],[56,11,"בֵּֽ⁠אלֹהִ֣ים בָּ֭טַחְתִּי לֹ֣א אִירָ֑א מַה־יַּעֲשֶׂ֖ה אָדָ֣ם לִֽ⁠י׃","béֽ̇⁠ʼlòhi֣ym bá֭̇taẖĕţi̇y lò֣ʼ ʼiyrá֑ʼ mah-yȧʻàşê֖h ʼádá֣m liֽ⁠y׃"],[56,12,"עָלַ֣⁠י אֱלֹהִ֣ים נְדָרֶ֑י⁠ךָ אֲשַׁלֵּ֖ם תּוֹדֹ֣ת לָֽ⁠ךְ׃","ʻála֣⁠y ʼèlòhi֣ym nĕdáre֑y⁠ká ʼàşǎlé֖̇m ţ̇wòdò֣ţ láֽ⁠kĕ׃"],[56,13,"כִּ֤י הִצַּ֪לְתָּ נַפְשִׁ֡⁠י מִ⁠מָּוֶת֮ הֲ⁠לֹ֥א רַגְלַ֗⁠י מִ֫⁠דֶּ֥חִי לְ֭⁠הִֽתְהַלֵּךְ לִ⁠פְנֵ֣י אֱלֹהִ֑ים בְּ֝⁠א֗וֹר הַֽ⁠חַיִּֽים׃","ki֤̇y hiẕȧ֪lĕţá̇ napĕşǐ֡⁠y mi⁠má̇weţ֮ hà⁠lò֥ʼ ragĕla֗⁠y mi֫⁠dė֥ẖiy lĕ֭⁠hiֽţĕhalé̇kĕ li⁠pĕné֣y ʼèlòhi֑ym bĕ̇֝⁠ʼ֗wòr hֽa⁠ẖayiֽ̇ym׃"],[57,1,"חָנֵּ֤⁠נִי אֱלֹהִ֨ים ׀ חָנֵּ֗⁠נִי כִּ֥י בְ⁠ךָ֮ חָסָ֪יָה נַ֫פְשִׁ֥⁠י וּ⁠בְ⁠צֵֽל־כְּנָפֶ֥י⁠ךָ אֶחְסֶ֑ה עַ֝֗ד יַעֲבֹ֥ר הַוּֽוֹת׃","ẖáné֤̇⁠niy ʼèlòhi֨ym ׀ ẖáné̇֗⁠niy ki֥̇y bĕ⁠ká֮ ẖásá֪yáh na֫pĕşǐ֥⁠y ẇ⁠bĕ⁠ẕéֽl-kĕ̇nápe֥y⁠ká ʼeẖĕse֑h ʻa֝֗d yaʻàbò֥r haẇֽwòţ׃"],[57,2,"אֶ֭קְרָא לֵֽ⁠אלֹהִ֣ים עֶלְי֑וֹן לָ֝⁠אֵ֗ל גֹּמֵ֥ר עָלָֽ⁠י׃","ʼe֭qĕráʼ léֽ⁠ʼlòhi֣ym ʻelĕy֑wòn lá֝⁠ʼé֗l gò̇mé֥r ʻáláֽ⁠y׃"],[57,3,"יִשְׁלַ֤ח מִ⁠שָּׁמַ֨יִם ׀ וְֽ⁠יוֹשִׁיעֵ֗⁠נִי חֵרֵ֣ף שֹׁאֲפִ֣⁠י סֶ֑לָה יִשְׁלַ֥ח אֱ֝לֹהִ֗ים חַסְדּ֥⁠וֹ וַ⁠אֲמִתּֽ⁠וֹ׃","yişĕ̌la֤ẖ mi⁠şá̇̌ma֨yim ׀ wĕֽ⁠ywòşǐyʻé֗⁠niy ẖéré֣p şò̌ʼàpi֣⁠y se֑láh yişĕ̌la֥ẖ ʼè֝lòhi֗ym ẖasĕḋ֥⁠wò wa⁠ʼàmiţֽ̇⁠wò׃"],[57,4,"נַפְשִׁ֤⁠י ׀ בְּ⁠ת֥וֹךְ לְבָאִם֮ אֶשְׁכְּבָ֪ה לֹ֫הֲטִ֥ים בְּֽנֵי־אָדָ֗ם שִׁ֭נֵּי⁠הֶם חֲנִ֣ית וְ⁠חִצִּ֑ים וּ֝⁠לְשׁוֹנָ֗⁠ם חֶ֣רֶב חַדָּֽה׃","napĕşǐ֤⁠y ׀ bĕ̇⁠ţ֥wòkĕ lĕbáʼim֮ ʼeşĕ̌kĕ̇bá֪h lò֫hàti֥ym bĕֽ̇néy-ʼádá֗m şǐ֭né̇y⁠hem ẖàni֣yţ wĕ⁠ẖiẕi֑̇ym ẇ֝⁠lĕş̌wòná֗⁠m ẖe֣reb ẖadáֽ̇h׃"],[57,5,"ר֣וּמָ⁠ה עַל־הַ⁠שָּׁמַ֣יִם אֱלֹהִ֑ים עַ֖ל כָּל־הָ⁠אָ֣רֶץ כְּבוֹדֶֽ⁠ךָ׃","r֣ẇmá⁠h ʻal-ha⁠şá̇̌ma֣yim ʼèlòhi֑ym ʻa֖l ká̇l-há⁠ʼá֣reẕ kĕ̇bwòdeֽ⁠ká׃"],[57,6,"רֶ֤שֶׁת ׀ הֵכִ֣ינוּ לִ⁠פְעָמַ⁠י֮ כָּפַ֪ף נַ֫פְשִׁ֥⁠י כָּר֣וּ לְ⁠פָנַ֣⁠י שִׁיחָ֑ה נָפְל֖וּ בְ⁠תוֹכָ֣⁠הּ סֶֽלָה׃","re֤şěţ ׀ héki֣ynẇ li⁠pĕʻáma⁠y֮ ká̇pa֪p na֫pĕşǐ֥⁠y ká̇r֣ẇ lĕ⁠pána֣⁠y şǐyẖá֑h nápĕl֖ẇ bĕ⁠ţwòká֣⁠ḣ seֽláh׃"],[57,7,"נָ֘כ֤וֹן לִבִּ֣⁠י אֱ֭לֹהִים נָכ֣וֹן לִבִּ֑⁠י אָ֝שִׁ֗ירָה וַ⁠אֲזַמֵּֽרָה׃","ná֘k֤wòn libi֣̇⁠y ʼè֭lòhiym nák֣wòn libi֑̇⁠y ʼá֝şǐ֗yráh wa⁠ʼàzaméֽ̇ráh׃"],[57,8,"ע֤וּרָ⁠ה כְבוֹדִ֗⁠י ע֭וּרָֽ⁠ה הַ⁠נֵּ֥בֶל וְ⁠כִנּ֗וֹר אָעִ֥ירָה שָּֽׁחַר׃","ʻ֤ẇrá⁠h kĕbwòdi֗⁠y ʻ֭ẇráֽ⁠h ha⁠né֥̇bel wĕ⁠kiṅ֗wòr ʼáʻi֥yráh şáֽ̇̌ẖar׃"],[57,9,"אוֹדְ⁠ךָ֖ בָ⁠עַמִּ֥ים ׀ אֲדֹנָ֑⁠י אֲ֝זַמֶּרְ⁠ךָ֗ בַּל־אֻמִּֽים׃","ʼwòdĕ⁠ká֖ bá⁠ʻami֥̇ym ׀ ʼàdòná֑⁠y ʼà֝zamėrĕ⁠ká֗ bȧl-ʼumiֽ̇ym׃"],[57,10,"כִּֽי־גָדֹ֣ל עַד־שָׁמַ֣יִם חַסְדֶּ֑⁠ךָ וְֽ⁠עַד־שְׁחָקִ֥ים אֲמִתֶּֽ⁠ךָ׃","kiֽ̇y-gádò֣l ʻad-şá̌ma֣yim ẖasĕdė֑⁠ká wĕֽ⁠ʻad-şĕ̌ẖáqi֥ym ʼàmiţėֽ⁠ká׃"],[57,11,"ר֣וּמָ⁠ה עַל־שָׁמַ֣יִם אֱלֹהִ֑ים עַ֖ל כָּל־הָ⁠אָ֣רֶץ כְּבוֹדֶֽ⁠ךָ׃","r֣ẇmá⁠h ʻal-şá̌ma֣yim ʼèlòhi֑ym ʻa֖l ká̇l-há⁠ʼá֣reẕ kĕ̇bwòdeֽ⁠ká׃"],[58,1,"הַֽ⁠אֻמְנָ֗ם אֵ֣לֶם צֶ֭דֶק תְּדַבֵּר֑וּ⁠ן מֵישָׁרִ֥ים תִּ֝שְׁפְּט֗וּ בְּנֵ֣י אָדָֽם׃","haֽ⁠ʼumĕná֗m ʼé֣lem ẕe֭deq ţĕ̇dabé̇r֑ẇ⁠n méyşá̌ri֥ym ţi̇֝şĕ̌pĕ̇t֗ẇ bĕ̇né֣y ʼádáֽm׃"],[58,2,"אַף־בְּ⁠לֵב֮ עוֹלֹ֪ת תִּפְעָ֫ל֥וּ⁠ן בָּ⁠אָ֡רֶץ חֲמַ֥ס יְ֝דֵי⁠כֶ֗ם תְּפַלֵּֽסֽוּ⁠ן׃","ʼap-bĕ̇⁠léb֮ ʻwòlò֪ţ ţi̇pĕʻá֫l֥ẇ⁠n bá̇⁠ʼá֡reẕ ẖàma֥s yĕ֝déy⁠ke֗m ţĕ̇paléֽ̇sֽẇ⁠n׃"],[58,3,"זֹ֣רוּ רְשָׁעִ֣ים מֵ⁠רָ֑חֶם תָּע֥וּ מִ֝⁠בֶּ֗טֶן דֹּבְרֵ֥י כָזָֽב׃","zò֣rẇ rĕşá̌ʻi֣ym mé⁠rá֑ẖem ţá̇ʻ֥ẇ mi֝⁠bė֗ten dò̇bĕré֥y kázáֽb׃"],[58,4,"חֲמַת־לָ֗⁠מוֹ כִּ⁠דְמ֥וּת חֲמַת־נָחָ֑שׁ כְּמוֹ־פֶ֥תֶן חֵ֝רֵ֗שׁ יַאְטֵ֥ם אָזְנֽ⁠וֹ׃","ẖàmaţ-lá֗⁠mwò ki̇⁠dĕm֥ẇţ ẖàmaţ-náẖá֑ş̌ kĕ̇mwò-pe֥ţen ẖé֝ré֗ş̌ yaʼĕté֥m ʼázĕnֽ⁠wò׃"],[58,5,"אֲשֶׁ֣ר לֹא־יִ֭שְׁמַע לְ⁠ק֣וֹל מְלַחֲשִׁ֑ים חוֹבֵ֖ר חֲבָרִ֣ים מְחֻכָּֽם׃","ʼàşě֣r lòʼ-yi֭şĕ̌maʻ lĕ⁠q֣wòl mĕlaẖàşǐ֑ym ẖwòbé֖r ẖàbári֣ym mĕẖukáֽ̇m׃"],[58,6,"אֱֽלֹהִ֗ים הֲרָס־שִׁנֵּ֥י⁠מוֹ בְּ⁠פִ֑י⁠מוֹ מַלְתְּע֥וֹת כְּ֝פִירִ֗ים נְתֹ֣ץ ׀ יְהוָֽה׃","ʼèֽlòhi֗ym hàrás-şǐné֥̇y⁠mwò bĕ̇⁠pi֑y⁠mwò malĕţĕ̇ʻ֥wòţ kĕ̇֝piyri֗ym nĕţò֣ẕ ׀ yĕhwáֽh׃"],[58,7,"יִמָּאֲס֣וּ כְמוֹ־מַ֭יִם יִתְהַלְּכוּ־לָ֑⁠מוֹ יִדְרֹ֥ךְ חצ⁠ו כְּמ֣וֹ יִתְמֹלָֽלוּ׃","yimá̇ʼàs֣ẇ kĕmwò-ma֭yim yiţĕhalĕ̇kẇ-lá֑⁠mwò yidĕrò֥kĕ ẖẕ⁠w kĕ̇m֣wò yiţĕmòláֽlẇ׃"],[58,8,"כְּמ֣וֹ שַׁ֭בְּלוּל תֶּ֣מֶס יַהֲלֹ֑ךְ נֵ֥פֶל אֵ֝֗שֶׁת בַּל־חָ֥זוּ שָֽׁמֶשׁ׃","kĕ̇m֣wò şǎ֭bĕ̇lẇl ţė֣mes yahàlò֑kĕ né֥pel ʼé֝֗şěţ bȧl-ẖá֥zẇ şáֽ̌meş̌׃"],[58,9,"בְּ⁠טֶ֤רֶם יָבִ֣ינוּ סִּֽירֹתֵי⁠כֶ֣ם אָטָ֑ד כְּמוֹ־חַ֥י כְּמוֹ־חָ֝ר֗וֹן יִשְׂעָרֶֽ⁠נּוּ׃","bĕ̇⁠te֤rem yábi֣ynẇ siֽ̇yròţéy⁠ke֣m ʼátá֑d kĕ̇mwò-ẖa֥y kĕ̇mwò-ẖá֝r֗wòn yişĕ̂ʻáreֽ⁠ṅẇ׃"],[58,10,"יִשְׂמַ֣ח צַ֭דִּיק כִּי־חָזָ֣ה נָקָ֑ם פְּעָמָ֥י⁠ו יִ֝רְחַ֗ץ בְּ⁠דַ֣ם הָ⁠רָשָֽׁע׃","yişĕ̂ma֣ẖ ẕa֭di̇yq ki̇y-ẖázá֣h náqá֑m pĕ̇ʻámá֥y⁠w yi֝rĕẖa֗ẕ bĕ̇⁠da֣m há⁠ráşáֽ̌ʻ׃"],[58,11,"וְ⁠יֹאמַ֣ר אָ֭דָם אַךְ־פְּרִ֣י לַ⁠צַּדִּ֑יק אַ֥ךְ יֵשׁ־אֱ֝לֹהִ֗ים שֹׁפְטִ֥ים בָּ⁠אָֽרֶץ׃","wĕ⁠yòʼma֣r ʼá֭dám ʼakĕ-pĕ̇ri֣y la⁠ẕȧdi֑̇yq ʼa֥kĕ yéş̌-ʼè֝lòhi֗ym şò̌pĕti֥ym bá̇⁠ʼáֽreẕ׃"],[59,1,"הַצִּילֵ֖⁠נִי מֵ⁠אֹיְבַ֥⁠י ׀ אֱלֹהָ֑⁠י מִּ⁠מִתְקוֹמְמַ֥⁠י תְּשַׂגְּבֵֽ⁠נִי׃","haẕi̇ylé֖⁠niy mé⁠ʼòyĕba֥⁠y ׀ ʼèlòhá֑⁠y mi̇⁠miţĕqwòmĕma֥⁠y ţĕ̇şâgĕ̇béֽ⁠niy׃"],[59,2,"הַ֭צִּילֵ⁠נִי מִ⁠פֹּ֣עֲלֵי אָ֑וֶן וּֽ⁠מֵ⁠אַנְשֵׁ֥י דָ֝מִ֗ים הוֹשִׁיעֵֽ⁠נִי׃","ha֭ẕi̇ylé⁠niy mi⁠pò֣̇ʻàléy ʼá֑wen ẇֽ⁠mé⁠ʼanĕşé֥̌y dá֝mi֗ym hwòşǐyʻéֽ⁠niy׃"],[59,3,"כִּ֤י הִנֵּ֪ה אָֽרְב֡וּ לְ⁠נַפְשִׁ֗⁠י יָג֣וּרוּ עָלַ֣⁠י עַזִ֑ים לֹא־פִשְׁעִ֖⁠י וְ⁠לֹא־חַטָּאתִ֣⁠י יְהוָֽה׃","ki֤̇y hiné֪̇h ʼáֽrĕb֡ẇ lĕ⁠napĕşǐ֗⁠y yág֣ẇrẇ ʻála֣⁠y ʻazi֑ym lòʼ-pişĕ̌ʻi֖⁠y wĕ⁠lòʼ-ẖatá̇ʼţi֣⁠y yĕhwáֽh׃"],[59,4,"בְּֽלִי־עָ֭וֺן יְרוּצ֣וּ⁠ן וְ⁠יִכּוֹנָ֑נוּ ע֖וּרָ⁠ה לִ⁠קְרָאתִ֣⁠י וּ⁠רְאֵה׃","bĕֽ̇liy-ʻá֭wֺn yĕrẇẕ֣ẇ⁠n wĕ⁠yik̇wòná֑nẇ ʻ֖ẇrá⁠h li⁠qĕráʼţi֣⁠y ẇ⁠rĕʼéh׃"],[59,5,"וְ⁠אַתָּ֤ה יְהוָֽה־אֱלֹהִ֥ים ׀ צְבָא֡וֹת אֱלֹ֘הֵ֤י יִשְׂרָאֵ֗ל הָקִ֗יצָ⁠ה לִ⁠פְקֹ֥ד כָּֽל־הַ⁠גּוֹיִ֑ם אַל־תָּחֹ֨ן כָּל־בֹּ֖גְדֵי אָ֣וֶן סֶֽלָה׃","wĕ⁠ʼaţá֤̇h yĕhwáֽh-ʼèlòhi֥ym ׀ ẕĕbáʼ֡wòţ ʼèlò֘hé֤y yişĕ̂ráʼé֗l háqi֗yẕá⁠h li⁠pĕqò֥d káֽ̇l-ha⁠ġwòyi֑m ʼal-ţá̇ẖò֨n ká̇l-bò֖̇gĕdéy ʼá֣wen seֽláh׃"],[59,6,"יָשׁ֣וּבוּ לָ֭⁠עֶרֶב יֶהֱמ֥וּ כַ⁠כָּ֗לֶב וִ⁠יס֥וֹבְבוּ עִֽיר׃","yáş֣̌ẇbẇ lá֭⁠ʻereb yehèm֥ẇ ka⁠ká̇֗leb wi⁠ys֥wòbĕbẇ ʻiֽyr׃"],[59,7,"הִנֵּ֤ה ׀ יַבִּ֘יע֤וּ⁠ן בְּ⁠פִי⁠הֶ֗ם חֲ֭רָבוֹת בְּ⁠שִׂפְתוֹתֵי⁠הֶ֑ם כִּי־מִ֥י שֹׁמֵֽעַ׃","hiné֤̇h ׀ yabi̇֘yʻ֤ẇ⁠n bĕ̇⁠piy⁠he֗m ẖà֭rábwòţ bĕ̇⁠şîpĕţwòţéy⁠he֑m ki̇y-mi֥y şò̌méֽʻa׃"],[59,8,"וְ⁠אַתָּ֣ה יְ֭הוָה תִּשְׂחַק־לָ֑⁠מוֹ תִּ֝לְעַ֗ג לְ⁠כָל־גּוֹיִֽם׃","wĕ⁠ʼaţá֣̇h yĕ֭hwáh ţi̇şĕ̂ẖaq-lá֑⁠mwò ţi̇֝lĕʻa֗g lĕ⁠kál-ġwòyiֽm׃"],[59,9,"עֻ֭זּ⁠וֹ אֵלֶ֣י⁠ךָ אֶשְׁמֹ֑רָה כִּֽי־אֱ֝לֹהִ֗ים מִשְׂגַּבִּֽ⁠י׃","ʻu֭ż⁠wò ʼéle֣y⁠ká ʼeşĕ̌mò֑ráh kiֽ̇y-ʼè֝lòhi֗ym mişĕ̂gȧbiֽ̇⁠y׃"],[59,10,"אֱלֹהֵ֣י חסד⁠ו יְקַדְּמֵ֑⁠נִי אֱ֝לֹהִ֗ים יַרְאֵ֥⁠נִי בְ⁠שֹׁרְרָֽ⁠י׃","ʼèlòhé֣y ẖsd⁠w yĕqadĕ̇mé֑⁠niy ʼè֝lòhi֗ym yarĕʼé֥⁠niy bĕ⁠şò̌rĕráֽ⁠y׃"],[59,11,"אַל־תַּהַרְגֵ֤⁠ם ׀ פֶּֽן־יִשְׁכְּח֬וּ עַמִּ֗⁠י הֲנִיעֵ֣⁠מוֹ בְ֭⁠חֵילְ⁠ךָ וְ⁠הוֹרִידֵ֑⁠מוֹ מָֽגִנֵּ֣⁠נוּ אֲדֹנָֽ⁠י׃","ʼal-ţȧharĕgé֤⁠m ׀ pėֽn-yişĕ̌kĕ̇ẖ֬ẇ ʻami̇֗⁠y hàniyʻé֣⁠mwò bĕ֭⁠ẖéylĕ⁠ká wĕ⁠hwòriydé֑⁠mwò máֽginé֣̇⁠nẇ ʼàdònáֽ⁠y׃"],[59,12,"חַטַּאת־פִּ֗י⁠מוֹ דְּֽבַר־שְׂפָ֫תֵ֥י⁠מוֹ וְ⁠יִלָּכְד֥וּ בִ⁠גְאוֹנָ֑⁠ם וּ⁠מֵ⁠אָלָ֖ה וּ⁠מִ⁠כַּ֣חַשׁ יְסַפֵּֽרוּ׃","ẖatȧʼţ-pi̇֗y⁠mwò dĕֽ̇bar-şĕ̂pá֫ţé֥y⁠mwò wĕ⁠yilá̇kĕd֥ẇ bi⁠gĕʼwòná֑⁠m ẇ⁠mé⁠ʼálá֖h ẇ⁠mi⁠kȧ֣ẖaş̌ yĕsapéֽ̇rẇ׃"],[59,13,"כַּלֵּ֥ה בְ⁠חֵמָה֮ כַּלֵּ֪ה וְֽ⁠אֵ֫ינֵ֥⁠מוֹ וְֽ⁠יֵדְע֗וּ כִּֽי־אֱ֭לֹהִים מֹשֵׁ֣ל בְּ⁠יַעֲקֹ֑ב לְ⁠אַפְסֵ֖י הָ⁠אָ֣רֶץ סֶֽלָה׃","kȧlé֥̇h bĕ⁠ẖémáh֮ kȧlé֪̇h wĕֽ⁠ʼé֫yné֥⁠mwò wĕֽ⁠yédĕʻ֗ẇ kiֽ̇y-ʼè֭lòhiym mòşé֣̌l bĕ̇⁠yaʻàqò֑b lĕ⁠ʼapĕsé֖y há⁠ʼá֣reẕ seֽláh׃"],[59,14,"וְ⁠יָשׁ֣וּבוּ לָ֭⁠עֶרֶב יֶהֱמ֥וּ כַ⁠כָּ֗לֶב וִ⁠יס֥וֹבְבוּ עִֽיר׃","wĕ⁠yáş֣̌ẇbẇ lá֭⁠ʻereb yehèm֥ẇ ka⁠ká̇֗leb wi⁠ys֥wòbĕbẇ ʻiֽyr׃"],[59,15,"הֵ֭מָּה ינועו⁠ן לֶ⁠אֱכֹ֑ל אִם־לֹ֥א יִ֝שְׂבְּע֗וּ וַ⁠יָּלִֽינוּ׃","hé֭má̇h ynwʻw⁠n le⁠ʼèkò֑l ʼim-lò֥ʼ yi֝şĕ̂bĕ̇ʻ֗ẇ wa⁠yá̇liֽynẇ׃"],[59,16,"וַ⁠אֲנִ֤י ׀ אָשִׁ֣יר עֻזֶּ⁠ךָ֮ וַ⁠אֲרַנֵּ֥ן לַ⁠בֹּ֗קֶר חַ֫סְדֶּ֥⁠ךָ כִּֽי־הָיִ֣יתָ מִשְׂגָּ֣ב לִ֑⁠י וּ֝⁠מָנ֗וֹס בְּ⁠י֣וֹם צַר־לִֽ⁠י׃","wa⁠ʼàni֤y ׀ ʼáşǐ֣yr ʻuzė⁠ká֮ wa⁠ʼàrané֥̇n la⁠bò̇֗qer ẖa֫sĕdė֥⁠ká kiֽ̇y-háyi֣yţá mişĕ̂gá֣̇b li֑⁠y ẇ֝⁠mán֗wòs bĕ̇⁠y֣wòm ẕar-liֽ⁠y׃"],[59,17,"עֻ֭זִּ⁠י אֵלֶ֣י⁠ךָ אֲזַמֵּ֑רָה כִּֽי־אֱלֹהִ֥ים מִ֝שְׂגַּבִּ֗⁠י אֱלֹהֵ֥י חַסְדִּֽ⁠י׃","ʻu֭zi̇⁠y ʼéle֣y⁠ká ʼàzamé֑̇ráh kiֽ̇y-ʼèlòhi֥ym mi֝şĕ̂gȧbi̇֗⁠y ʼèlòhé֥y ẖasĕdiֽ̇⁠y׃"],[60,1,"אֱ֭לֹהִים זְנַחְתָּ֣⁠נוּ פְרַצְתָּ֑⁠נוּ אָ֝נַ֗פְתָּ תְּשׁ֣וֹבֵ֥ב לָֽ⁠נוּ׃","ʼè֭lòhiym zĕnaẖĕţá֣̇⁠nẇ pĕraẕĕţá֑̇⁠nẇ ʼá֝na֗pĕţá̇ ţĕ̇ş֣̌wòbé֥b láֽ⁠nẇ׃"],[60,2,"הִרְעַ֣שְׁתָּה אֶ֣רֶץ פְּצַמְתָּ֑⁠הּ רְפָ֖⁠ה שְׁבָרֶ֣י⁠הָ כִי־מָֽטָה׃","hirĕʻa֣şĕ̌ţá̇h ʼe֣reẕ pĕ̇ẕamĕţá֑̇⁠ḣ rĕpá֖⁠h şĕ̌báre֣y⁠há kiy-máֽtáh׃"],[60,3,"הִרְאִ֣יתָה עַמְּ⁠ךָ֣ קָשָׁ֑ה הִ֝שְׁקִיתָ֗⁠נוּ יַ֣יִן תַּרְעֵלָֽה׃","hirĕʼi֣yţáh ʻamĕ̇⁠ká֣ qáşá֑̌h hi֝şĕ̌qiyţá֗⁠nẇ ya֣yin ţȧrĕʻéláֽh׃"],[60,4,"נָ֘תַ֤תָּה לִּ⁠ירֵאֶ֣י⁠ךָ נֵּ֭ס לְ⁠הִתְנוֹסֵ֑ס מִ֝⁠פְּנֵ֗י קֹ֣שֶׁט סֶֽלָה׃","ná֘ţa֤ţá̇h li̇⁠yréʼe֣y⁠ká né֭̇s lĕ⁠hiţĕnwòsé֑s mi֝⁠pĕ̇né֗y qò֣şět seֽláh׃"],[60,5,"לְ֭מַעַן יֵחָלְצ֣וּ⁠ן יְדִידֶ֑י⁠ךָ הוֹשִׁ֖יעָ⁠ה יְמִֽינְ⁠ךָ֣ ו⁠ענ⁠נו׃","lĕ֭maʻan yéẖálĕẕ֣ẇ⁠n yĕdiyde֑y⁠ká hwòşǐ֖yʻá⁠h yĕmiֽynĕ⁠ká֣ w⁠ʻn⁠nw׃"],[60,6,"אֱלֹהִ֤ים ׀ דִּבֶּ֥ר בְּ⁠קָדְשׁ֗⁠וֹ אֶ֫עְלֹ֥זָה אֲחַלְּקָ֥ה שְׁכֶ֑ם וְ⁠עֵ֖מֶק סֻכּ֣וֹת אֲמַדֵּֽד׃","ʼèlòhi֤ym ׀ di̇bė֥r bĕ̇⁠qádĕş̌֗⁠wò ʼe֫ʻĕlò֥záh ʼàẖalĕ̇qá֥h şĕ̌ke֑m wĕ⁠ʻé֖meq suk֣̇wòţ ʼàmadéֽ̇d׃"],[60,7,"לִ֤⁠י גִלְעָ֨ד ׀ וְ⁠לִ֬⁠י מְנַשֶּׁ֗ה וְ֭⁠אֶפְרַיִם מָע֣וֹז רֹאשִׁ֑⁠י יְ֝הוּדָ֗ה מְחֹֽקְקִ⁠י׃","li֤⁠y gilĕʻá֨d ׀ wĕ⁠li֬⁠y mĕnaşė̌֗h wĕ֭⁠ʼepĕrayim máʻ֣wòz ròʼşǐ֑⁠y yĕ֝hẇdá֗h mĕẖòֽqĕqi⁠y׃"],[60,8,"מוֹאָ֤ב ׀ סִ֬יר רַחְצִ֗⁠י עַל־אֱ֭דוֹם אַשְׁלִ֣יךְ נַעֲלִ֑⁠י עָ֝לַ֗⁠י פְּלֶ֣שֶׁת הִתְרֹעָֽעִֽי׃","mwòʼá֤b ׀ si֬yr raẖĕẕi֗⁠y ʻal-ʼè֭dwòm ʼaşĕ̌li֣ykĕ naʻàli֑⁠y ʻá֝la֗⁠y pĕ̇le֣şěţ hiţĕròʻáֽʻiֽy׃"],[60,9,"מִ֣י יֹ֭בִלֵ⁠נִי עִ֣יר מָצ֑וֹר מִ֖י נָחַ֣⁠נִי עַד־אֱדֽוֹם׃","mi֣y yò֭bilé⁠niy ʻi֣yr máẕ֑wòr mi֖y náẖa֣⁠niy ʻad-ʼèdֽwòm׃"],[60,10,"הֲ⁠לֹֽא־אַתָּ֣ה אֱלֹהִ֣ים זְנַחְתָּ֑⁠נוּ וְֽ⁠לֹא־תֵצֵ֥א אֱ֝לֹהִ֗ים בְּ⁠צִבְאוֹתֵֽי⁠נוּ׃","hà⁠lòֽʼ-ʼaţá֣̇h ʼèlòhi֣ym zĕnaẖĕţá֑̇⁠nẇ wĕֽ⁠lòʼ-ţéẕé֥ʼ ʼè֝lòhi֗ym bĕ̇⁠ẕibĕʼwòţéֽy⁠nẇ׃"],[60,11,"הָֽבָ⁠ה־לָּ֣⁠נוּ עֶזְרָ֣ת מִ⁠צָּ֑ר וְ֝⁠שָׁ֗וְא תְּשׁוּעַ֥ת אָדָם׃","háֽbá⁠h-lá֣̇⁠nẇ ʻezĕrá֣ţ mi⁠ẕá֑̇r wĕ֝⁠şá̌֗wĕʼ ţĕ̇ş̌ẇʻa֥ţ ʼádám׃"],[60,12,"בֵּֽ⁠אלֹהִ֥ים נַעֲשֶׂה־חָ֑יִל וְ֝⁠ה֗וּא יָב֥וּס צָרֵֽי⁠נוּ׃","béֽ̇⁠ʼlòhi֥ym naʻàşêh-ẖá֑yil wĕ֝⁠h֗ẇʼ yáb֥ẇs ẕáréֽy⁠nẇ׃"],[61,1,"שִׁמְעָ֣⁠ה אֱ֭לֹהִים רִנָּתִ֑⁠י הַ֝קְשִׁ֗יבָ⁠ה תְּפִלָּתִֽ⁠י׃","şǐmĕʻá֣⁠h ʼè֭lòhiym riná̇ţi֑⁠y ha֝qĕşǐ֗ybá⁠h ţĕ̇pilá̇ţiֽ⁠y׃"],[61,2,"מִ⁠קְצֵ֤ה הָ⁠אָ֨רֶץ ׀ אֵלֶ֣י⁠ךָ אֶ֭קְרָא בַּ⁠עֲטֹ֣ף לִבִּ֑⁠י בְּ⁠צוּר־יָר֖וּם מִמֶּ֣⁠נִּי תַנְחֵֽ⁠נִי׃","mi⁠qĕẕé֤h há⁠ʼá֨reẕ ׀ ʼéle֣y⁠ká ʼe֭qĕráʼ bȧ⁠ʻàtò֣p libi֑̇⁠y bĕ̇⁠ẕẇr-yár֖ẇm mimė֣⁠ni̇y ţanĕẖéֽ⁠niy׃"],[61,3,"כִּֽי־הָיִ֣יתָ מַחְסֶ֣ה לִ֑⁠י מִגְדַּל־עֹ֝֗ז מִ⁠פְּנֵ֥י אוֹיֵֽב׃","kiֽ̇y-háyi֣yţá maẖĕse֣h li֑⁠y migĕdȧl-ʻò֝֗z mi⁠pĕ̇né֥y ʼwòyéֽb׃"],[61,4,"אָג֣וּרָה בְ֭⁠אָהָלְ⁠ךָ עוֹלָמִ֑ים אֶֽחֱסֶ֨ה בְ⁠סֵ֖תֶר כְּנָפֶ֣י⁠ךָ סֶּֽלָה׃","ʼág֣ẇráh bĕ֭⁠ʼáhálĕ⁠ká ʻwòlámi֑ym ʼeֽẖèse֨h bĕ⁠sé֖ţer kĕ̇nápe֣y⁠ká sėֽláh׃"],[61,5,"כִּֽי־אַתָּ֣ה אֱ֭לֹהִים שָׁמַ֣עְתָּ לִ⁠נְדָרָ֑⁠י נָתַ֥תָּ יְ֝רֻשַּׁ֗ת יִרְאֵ֥י שְׁמֶֽ⁠ךָ׃","kiֽ̇y-ʼaţá֣̇h ʼè֭lòhiym şá̌ma֣ʻĕţá̇ li⁠nĕdárá֑⁠y náţa֥ţá̇ yĕ֝ruşȧ̌֗ţ yirĕʼé֥y şĕ̌meֽ⁠ká׃"],[61,6,"יָמִ֣ים עַל־יְמֵי־מֶ֣לֶךְ תּוֹסִ֑יף שְׁ֝נוֹתָ֗י⁠ו כְּמוֹ־דֹ֥ר וָ⁠דֹֽר׃","yámi֣ym ʻal-yĕméy-me֣lekĕ ţ̇wòsi֑yp şĕ̌֝nwòţá֗y⁠w kĕ̇mwò-dò֥r wá⁠dòֽr׃"],[61,7,"יֵשֵׁ֣ב ע֭וֹלָם לִ⁠פְנֵ֣י אֱלֹהִ֑ים חֶ֥סֶד וֶ֝⁠אֱמֶ֗ת מַ֣ן יִנְצְרֻֽ⁠הוּ׃","yéşé֣̌b ʻ֭wòlám li⁠pĕné֣y ʼèlòhi֑ym ẖe֥sed we֝⁠ʼème֗ţ ma֣n yinĕẕĕruֽ⁠hẇ׃"],[61,8,"כֵּ֤ן אֲזַמְּרָ֣ה שִׁמְ⁠ךָ֣ לָ⁠עַ֑ד לְֽ⁠שַׁלְּמִ֥⁠י נְדָרַ֗⁠י י֣וֹם ׀ יֽוֹם׃","ké֤̇n ʼàzamĕ̇rá֣h şǐmĕ⁠ká֣ lá⁠ʻa֑d lĕֽ⁠şǎlĕ̇mi֥⁠y nĕdára֗⁠y y֣wòm ׀ yֽwòm׃"],[62,1,"אַ֣ךְ אֶל־אֱ֭לֹהִים דּֽוּמִיָּ֣ה נַפְשִׁ֑⁠י מִ֝מֶּ֗⁠נּוּ יְשׁוּעָתִֽ⁠י׃","ʼa֣kĕ ʼel-ʼè֭lòhiym ḋֽẇmiyá֣̇h napĕşǐ֑⁠y mi֝mė֗⁠ṅẇ yĕş̌ẇʻáţiֽ⁠y׃"],[62,2,"אַךְ־ה֣וּא צ֭וּרִ⁠י וִֽ⁠ישׁוּעָתִ֑⁠י מִ֝שְׂגַּבִּ֗⁠י לֹא־אֶמּ֥וֹט רַבָּֽה׃","ʼakĕ-h֣ẇʼ ẕ֭ẇri⁠y wiֽ⁠yş̌ẇʻáţi֑⁠y mi֝şĕ̂gȧbi̇֗⁠y lòʼ-ʼeṁ֥wòt rabáֽ̇h׃"],[62,3,"עַד־אָ֤נָה ׀ תְּהֽוֹתְת֣וּ עַל אִישׁ֮ תְּרָצְּח֪וּ כֻ֫לְּ⁠כֶ֥ם כְּ⁠קִ֥יר נָט֑וּי גָּ֝דֵ֗ר הַ⁠דְּחוּיָֽה׃","ʻad-ʼá֤náh ׀ ţĕ̇hֽwòţĕţ֣ẇ ʻal ʼiyş֮̌ ţĕ̇ráẕĕ̇ẖ֪ẇ ku֫lĕ̇⁠ke֥m kĕ̇⁠qi֥yr nát֑ẇy gá̇֝dé֗r ha⁠dĕ̇ẖẇyֽáh׃"],[62,4,"אַ֤ךְ מִ⁠שְּׂאֵת֨⁠וֹ ׀ יָעֲצ֣וּ לְ⁠הַדִּיחַ֮ יִרְצ֪וּ כָ֫זָ֥ב בְּ⁠פִ֥י⁠ו יְבָרֵ֑כוּ וּ֝⁠בְ⁠קִרְבָּ֗⁠ם יְקַלְלוּ־סֶֽלָה׃","ʼa֤kĕ mi⁠şĕ̇̂ʼéţ֨⁠wò ׀ yáʻàẕ֣ẇ lĕ⁠hadi̇yẖa֮ yirĕẕ֪ẇ ká֫zá֥b bĕ̇⁠pi֥y⁠w yĕbáré֑kẇ ẇ֝⁠bĕ⁠qirĕbá̇֗⁠m yĕqalĕlẇ-seֽláh׃"],[62,5,"אַ֣ךְ לֵ֭⁠אלֹהִים דּ֣וֹמִּי נַפְשִׁ֑⁠י כִּי־מִ֝מֶּ֗⁠נּוּ תִּקְוָתִֽ⁠י׃","ʼa֣kĕ lé֭⁠ʼlòhiym ḋ֣wòmi̇y napĕşǐ֑⁠y ki̇y-mi֝mė֗⁠ṅẇ ţi̇qĕwáţiֽ⁠y׃"],[62,6,"אַךְ־ה֣וּא צ֭וּרִ⁠י וִֽ⁠ישׁוּעָתִ֑⁠י מִ֝שְׂגַּבִּ֗⁠י לֹ֣א אֶמּֽוֹט׃","ʼakĕ-h֣ẇʼ ẕ֭ẇri⁠y wiֽ⁠yş̌ẇʻáţi֑⁠y mi֝şĕ̂gȧbi̇֗⁠y lò֣ʼ ʼeṁֽwòt׃"],[62,7,"עַל־אֱ֭לֹהִים יִשְׁעִ֣⁠י וּ⁠כְבוֹדִ֑⁠י צוּר־עֻזִּ֥⁠י מַ֝חְסִ֗⁠י בֵּֽ⁠אלֹהִֽים׃","ʻal-ʼè֭lòhiym yişĕ̌ʻi֣⁠y ẇ⁠kĕbwòdi֑⁠y ẕẇr-ʻuzi֥̇⁠y ma֝ẖĕsi֗⁠y béֽ̇⁠ʼlòhiֽym׃"],[62,8,"בִּטְח֘וּ ב֤⁠וֹ בְ⁠כָל־עֵ֨ת ׀ עָ֗ם שִׁפְכֽוּ־לְ⁠פָנָ֥י⁠ו לְבַבְ⁠כֶ֑ם אֱלֹהִ֖ים מַחֲסֶה־לָּ֣⁠נוּ סֶֽלָה׃","bi̇tĕẖ֘ẇ b֤⁠wò bĕ⁠kál-ʻé֨ţ ׀ ʻá֗m şǐpĕkֽẇ-lĕ⁠páná֥y⁠w lĕbabĕ⁠ke֑m ʼèlòhi֖ym maẖàseh-lá֣̇⁠nẇ seֽláh׃"],[62,9,"אַ֤ךְ ׀ הֶ֥בֶל בְּנֵֽי־אָדָם֮ כָּזָ֪ב בְּנֵ֫י אִ֥ישׁ בְּ⁠מֹאזְנַ֥יִם לַ⁠עֲל֑וֹת הֵ֝֗מָּה מֵ⁠הֶ֥בֶל יָֽחַד׃","ʼa֤kĕ ׀ he֥bel bĕ̇néֽy-ʼádám֮ ká̇zá֪b bĕ̇né֫y ʼi֥yş̌ bĕ̇⁠mòʼzĕna֥yim la⁠ʻàl֑wòţ hé֝֗má̇h mé⁠he֥bel yáֽẖad׃"],[62,10,"אַל־תִּבְטְח֣וּ בְ⁠עֹשֶׁק֮ וּ⁠בְ⁠גָזֵ֪ל אַל־תֶּ֫הְבָּ֥לוּ חַ֤יִל ׀ כִּֽי־יָנ֑וּב אַל־תָּשִׁ֥יתוּ לֵֽב׃","ʼal-ţi̇bĕtĕẖ֣ẇ bĕ⁠ʻòşěq֮ ẇ⁠bĕ⁠gázé֪l ʼal-ţė֫hĕbá֥̇lẇ ẖa֤yil ׀ kiֽ̇y-yán֑ẇb ʼal-ţá̇şǐ֥yţẇ léֽb׃"],[62,11,"אַחַ֤ת ׀ דִּבֶּ֬ר אֱלֹהִ֗ים שְׁתַּֽיִם־ז֥וּ שָׁמָ֑עְתִּי כִּ֥י עֹ֝֗ז לֵ⁠אלֹהִֽים׃","ʼaẖa֤ţ ׀ di̇bė֬r ʼèlòhi֗ym şĕ̌ţȧֽyim-z֥ẇ şá̌má֑ʻĕţi̇y ki֥̇y ʻò֝֗z lé⁠ʼlòhiֽym׃"],[62,12,"וּ⁠לְ⁠ךָֽ־אֲדֹנָ֥⁠י חָ֑סֶד כִּֽי־אַתָּ֨ה תְשַׁלֵּ֖ם לְ⁠אִ֣ישׁ כְּֽ⁠מַעֲשֵֽׂ⁠הוּ׃","ẇ⁠lĕ⁠káֽ-ʼàdòná֥⁠y ẖá֑sed kiֽ̇y-ʼaţá̇֨h ţĕşǎlé֖̇m lĕ⁠ʼi֣yş̌ kĕֽ̇⁠maʻàşéֽ̂⁠hẇ׃"],[63,1,"אֱלֹהִ֤ים ׀ אֵלִ֥⁠י אַתָּ֗ה אֲֽשַׁחֲ֫רֶ֥⁠ךָּ צָמְאָ֬ה לְ⁠ךָ֨ ׀ נַפְשִׁ֗⁠י כָּמַ֣הּ לְ⁠ךָ֣ בְשָׂרִ֑⁠י בְּ⁠אֶֽרֶץ־צִיָּ֖ה וְ⁠עָיֵ֣ף בְּלִי־מָֽיִם׃","ʼèlòhi֤ym ׀ ʼéli֥⁠y ʼaţá̇֗h ʼàֽşǎẖà֫re֥⁠ká̇ ẕámĕʼá֬h lĕ⁠ká֨ ׀ napĕşǐ֗⁠y ká̇ma֣ḣ lĕ⁠ká֣ bĕşá̂ri֑⁠y bĕ̇⁠ʼeֽreẕ-ẕiyá֖̇h wĕ⁠ʻáyé֣p bĕ̇liy-máֽyim׃"],[63,2,"כֵּ֭ן בַּ⁠קֹּ֣דֶשׁ חֲזִיתִ֑י⁠ךָ לִ⁠רְא֥וֹת עֻ֝זְּ⁠ךָ֗ וּ⁠כְבוֹדֶֽ⁠ךָ׃","ké֭̇n bȧ⁠qò֣̇deş̌ ẖàziyţi֑y⁠ká li⁠rĕʼ֥wòţ ʻu֝zĕ̇⁠ká֗ ẇ⁠kĕbwòdeֽ⁠ká׃"],[63,3,"כִּי־ט֣וֹב חַ֭סְדְּ⁠ךָ מֵֽ⁠חַיִּ֗ים שְׂפָתַ֥⁠י יְשַׁבְּחֽוּ⁠נְךָ׃","ki̇y-t֣wòb ẖa֭sĕdĕ̇⁠ká méֽ⁠ẖayi̇֗ym şĕ̂páţa֥⁠y yĕşǎbĕ̇ẖֽẇ⁠nĕká׃"],[63,4,"כֵּ֣ן אֲבָרֶכְ⁠ךָ֣ בְ⁠חַיָּ֑⁠י בְּ֝⁠שִׁמְ⁠ךָ אֶשָּׂ֥א כַפָּֽ⁠י׃","ké֣̇n ʼàbárekĕ⁠ká֣ bĕ⁠ẖayá֑̇⁠y bĕ̇֝⁠şǐmĕ⁠ká ʼeşá֥̇̂ʼ kapáֽ̇⁠y׃"],[63,5,"כְּמ֤וֹ חֵ֣לֶב וָ֭⁠דֶשֶׁן תִּשְׂבַּ֣ע נַפְשִׁ֑⁠י וְ⁠שִׂפְתֵ֥י רְ֝נָנ֗וֹת יְהַלֶּל־פִּֽ⁠י׃","kĕ̇m֤wò ẖé֣leb wá֭⁠deşěn ţi̇şĕ̂bȧ֣ʻ napĕşǐ֑⁠y wĕ⁠şîpĕţé֥y rĕ֝nán֗wòţ yĕhalėl-piֽ̇⁠y׃"],[63,6,"אִם־זְכַרְתִּ֥י⁠ךָ עַל־יְצוּעָ֑⁠י בְּ֝⁠אַשְׁמֻר֗וֹת אֶהְגֶּה־בָּֽ⁠ךְ׃","ʼim-zĕkarĕţi֥̇y⁠ká ʻal-yĕẕẇʻá֑⁠y bĕ̇֝⁠ʼaşĕ̌mur֗wòţ ʼehĕgėh-báֽ̇⁠kĕ׃"],[63,7,"כִּֽי־הָיִ֣יתָ עֶזְרָ֣תָ⁠ה לִּ֑⁠י וּ⁠בְ⁠צֵ֖ל כְּנָפֶ֣י⁠ךָ אֲרַנֵּֽן׃","kiֽ̇y-háyi֣yţá ʻezĕrá֣ţá⁠h li֑̇⁠y ẇ⁠bĕ⁠ẕé֖l kĕ̇nápe֣y⁠ká ʼàranéֽ̇n׃"],[63,8,"דָּבְקָ֣ה נַפְשִׁ֣⁠י אַחֲרֶ֑י⁠ךָ בִּ֝֗⁠י תָּמְכָ֥ה יְמִינֶֽ⁠ךָ׃","dá̇bĕqá֣h napĕşǐ֣⁠y ʼaẖàre֑y⁠ká bi̇֝֗⁠y ţá̇mĕká֥h yĕmiyneֽ⁠ká׃"],[63,9,"וְ⁠הֵ֗מָּה לְ֭⁠שׁוֹאָה יְבַקְשׁ֣וּ נַפְשִׁ֑⁠י יָ֝בֹ֗אוּ בְּֽ⁠תַחְתִּיּ֥וֹת הָ⁠אָֽרֶץ׃","wĕ⁠hé֗má̇h lĕ֭⁠ş̌wòʼáh yĕbaqĕş֣̌ẇ napĕşǐ֑⁠y yá֝bò֗ʼẇ bĕֽ̇⁠ţaẖĕţi̇ẏ֥wòţ há⁠ʼáֽreẕ׃"],[63,10,"יַגִּירֻ֥⁠הוּ עַל־יְדֵי־חָ֑רֶב מְנָ֖ת שֻׁעָלִ֣ים יִהְיֽוּ׃","yagi̇yru֥⁠hẇ ʻal-yĕdéy-ẖá֑reb mĕná֖ţ şǔʻáli֣ym yihĕyֽẇ׃"],[63,11,"וְ⁠הַ⁠מֶּלֶךְ֮ יִשְׂמַ֪ח בֵּ⁠אלֹ֫הִ֥ים יִ֭תְהַלֵּל כָּל־הַ⁠נִּשְׁבָּ֣ע בּ֑⁠וֹ כִּ֥י יִ֝סָּכֵ֗ר פִּ֣י דֽוֹבְרֵי־שָֽׁקֶר׃","wĕ⁠ha⁠mėlekĕ֮ yişĕ̂ma֪ẖ bé̇⁠ʼlò֫hi֥ym yi֭ţĕhalé̇l ká̇l-ha⁠ni̇şĕ̌bá֣̇ʻ ḃ֑⁠wò ki֥̇y yi֝sá̇ké֗r pi֣̇y dֽwòbĕréy-şáֽ̌qer׃"],[64,1,"שְׁמַע־אֱלֹהִ֣ים קוֹלִ֣⁠י בְ⁠שִׂיחִ֑⁠י מִ⁠פַּ֥חַד א֝וֹיֵ֗ב תִּצֹּ֥ר חַיָּֽ⁠י׃","şĕ̌maʻ-ʼèlòhi֣ym qwòli֣⁠y bĕ⁠şîyẖi֑⁠y mi⁠pȧ֥ẖad ʼ֝wòyé֗b ţi̇ẕò֥̇r ẖayáֽ̇⁠y׃"],[64,2,"תַּ֭סְתִּירֵ⁠נִי מִ⁠סּ֣וֹד מְרֵעִ֑ים מֵ֝⁠רִגְשַׁ֗ת פֹּ֣עֲלֵי אָֽוֶן׃","ţȧ֭sĕţi̇yré⁠niy mi⁠ṡ֣wòd mĕréʻi֑ym mé֝⁠rigĕşǎ֗ţ pò֣̇ʻàléy ʼáֽwen׃"],[64,3,"אֲשֶׁ֤ר שָׁנְנ֣וּ כַ⁠חֶ֣רֶב לְשׁוֹנָ֑⁠ם דָּרְכ֥וּ חִ֝צָּ֗⁠ם דָּבָ֥ר מָֽר׃","ʼàşě֤r şá̌nĕn֣ẇ ka⁠ẖe֣reb lĕş̌wòná֑⁠m dá̇rĕk֥ẇ ẖi֝ẕá̇֗⁠m dá̇bá֥r máֽr׃"],[64,4,"לִ⁠יר֣וֹת בַּ⁠מִּסְתָּרִ֣ים תָּ֑ם פִּתְאֹ֥ם יֹ֝רֻ֗⁠הוּ וְ⁠לֹ֣א יִירָֽאוּ׃","li⁠yr֣wòţ bȧ⁠mi̇sĕţá̇ri֣ym ţá֑̇m pi̇ţĕʼò֥m yò֝ru֗⁠hẇ wĕ⁠lò֣ʼ yiyráֽʼẇ׃"],[64,5,"יְחַזְּקוּ־לָ֨⁠מוֹ ׀ דָּ֘בָ֤ר רָ֗ע יְֽ֭סַפְּרוּ לִ⁠טְמ֣וֹן מוֹקְשִׁ֑ים אָ֝מְר֗וּ מִ֣י יִרְאֶה־לָּֽ⁠מוֹ׃","yĕẖazĕ̇qẇ-lá֨⁠mwò ׀ dá̇֘bá֤r rá֗ʻ yĕֽ֭sapĕ̇rẇ li⁠tĕm֣wòn mwòqĕşǐ֑ym ʼá֝mĕr֗ẇ mi֣y yirĕʼeh-láֽ̇⁠mwò׃"],[64,6,"יַֽחְפְּֽשׂוּ־עוֹלֹ֗ת תַּ֭מְנוּ חֵ֣פֶשׂ מְחֻפָּ֑שׂ וְ⁠קֶ֥רֶב אִ֝֗ישׁ וְ⁠לֵ֣ב עָמֹֽק׃","yaֽẖĕpĕֽ̇ş̂ẇ-ʻwòlò֗ţ ţȧ֭mĕnẇ ẖé֣peş̂ mĕẖupá֑̇ş̂ wĕ⁠qe֥reb ʼi֝֗yş̌ wĕ⁠lé֣b ʻámòֽq׃"],[64,7,"וַ⁠יֹּרֵ֗⁠ם אֱלֹ֫הִ֥ים חֵ֥ץ פִּתְא֑וֹם הָ֝י֗וּ מַכּוֹתָֽ⁠ם׃","wa⁠yò̇ré֗⁠m ʼèlò֫hi֥ym ẖé֥ẕ pi̇ţĕʼ֑wòm há֝y֗ẇ mak̇wòţáֽ⁠m׃"],[64,8,"וַ⁠יַּכְשִׁיל֣וּ⁠הוּ עָלֵ֣י⁠מוֹ לְשׁוֹנָ֑⁠ם יִ֝תְנֹדֲד֗וּ כָּל־רֹ֥אֵה בָֽ⁠ם׃","wa⁠yȧkĕşǐyl֣ẇ⁠hẇ ʻálé֣y⁠mwò lĕş̌wòná֑⁠m yi֝ţĕnòdàd֗ẇ ká̇l-rò֥ʼéh báֽ⁠m׃"],[64,9,"וַ⁠יִּֽירְא֗וּ כָּל־אָ֫דָ֥ם וַ֭⁠יַּגִּידוּ פֹּ֥עַל אֱלֹהִ֗ים וּֽ⁠מַעֲשֵׂ֥⁠הוּ הִשְׂכִּֽילוּ׃","wa⁠yiֽ̇yrĕʼ֗ẇ ká̇l-ʼá֫dá֥m wa֭⁠yȧgi̇ydẇ pò֥̇ʻal ʼèlòhi֗ym ẇֽ⁠maʻàşé֥̂⁠hẇ hişĕ̂kiֽ̇ylẇ׃"],[64,10,"יִשְׂמַ֬ח צַדִּ֣יק בַּ֭⁠יהוָה וְ⁠חָ֣סָה ב֑⁠וֹ וְ֝⁠יִתְהַֽלְל֗וּ כָּל־יִשְׁרֵי־לֵֽב׃","yişĕ̂ma֬ẖ ẕadi֣̇yq bȧ֭⁠yhwáh wĕ⁠ẖá֣sáh b֑⁠wò wĕ֝⁠yiţĕhaֽlĕl֗ẇ ká̇l-yişĕ̌réy-léֽb׃"],[65,1,"לְ⁠ךָ֤ דֻֽמִיָּ֬ה תְהִלָּ֓ה אֱלֹ֘הִ֥ים בְּ⁠צִיּ֑וֹן וּ֝⁠לְ⁠ךָ֗ יְשֻׁלַּם־נֶֽדֶר׃","lĕ⁠ká֤ duֽmiyá̇֬h ţĕhilá̇֓h ʼèlò֘hi֥ym bĕ̇⁠ẕiẏ֑wòn ẇ֝⁠lĕ⁠ká֗ yĕşǔlȧm-neֽder׃"],[65,2,"שֹׁמֵ֥עַ תְּפִלָּ֑ה עָ֝דֶ֗י⁠ךָ כָּל־בָּשָׂ֥ר יָבֹֽאוּ׃","şò̌mé֥ʻa ţĕ̇pilá֑̇h ʻá֝de֗y⁠ká ká̇l-bá̇şá֥̂r yábòֽʼẇ׃"],[65,3,"דִּבְרֵ֣י עֲ֭וֺנֹת גָּ֣בְרוּ מֶ֑נִּ⁠י פְּ֝שָׁעֵ֗י⁠נוּ אַתָּ֥ה תְכַפְּרֵֽ⁠ם׃","di̇bĕré֣y ʻà֭wֺnòţ gá֣̇bĕrẇ me֑ni̇⁠y pĕ̇֝şá̌ʻé֗y⁠nẇ ʼaţá֥̇h ţĕkapĕ̇réֽ⁠m׃"],[65,4,"אַשְׁרֵ֤י ׀ תִּֽבְחַ֣ר וּ⁠תְקָרֵב֮ יִשְׁכֹּ֪ן חֲצֵ֫רֶ֥י⁠ךָ נִ֭שְׂבְּעָה בְּ⁠ט֣וּב בֵּיתֶ֑⁠ךָ קְ֝דֹ֗שׁ הֵיכָלֶֽ⁠ךָ׃","ʼaşĕ̌ré֤y ׀ ţiֽ̇bĕẖa֣r ẇ⁠ţĕqáréb֮ yişĕ̌kò֪̇n ẖàẕé֫re֥y⁠ká ni֭şĕ̂bĕ̇ʻáh bĕ̇⁠t֣ẇb bé̇yţe֑⁠ká qĕ֝dò֗ş̌ héykáleֽ⁠ká׃"],[65,5,"נ֤וֹרָא֨וֹת ׀ בְּ⁠צֶ֣דֶק תַּ֭עֲנֵ⁠נוּ אֱלֹהֵ֣י יִשְׁעֵ֑⁠נוּ מִבְטָ֥ח כָּל־קַצְוֵי־אֶ֝֗רֶץ וְ⁠יָ֣ם רְחֹקִֽים׃","n֤wòráʼ֨wòţ ׀ bĕ̇⁠ẕe֣deq ţȧ֭ʻàné⁠nẇ ʼèlòhé֣y yişĕ̌ʻé֑⁠nẇ mibĕtá֥ẖ ká̇l-qaẕĕwéy-ʼe֝֗reẕ wĕ⁠yá֣m rĕẖòqiֽym׃"],[65,6,"מֵכִ֣ין הָרִ֣ים בְּ⁠כֹח֑⁠וֹ נֶ֝אְזָ֗ר בִּ⁠גְבוּרָֽה׃","méki֣yn hári֣ym bĕ̇⁠kòẖ֑⁠wò ne֝ʼĕzá֗r bi̇⁠gĕbẇráֽh׃"],[65,7,"מַשְׁבִּ֤יחַ ׀ שְׁא֣וֹן יַ֭מִּים שְׁא֥וֹן גַּלֵּי⁠הֶ֗ם וַ⁠הֲמ֥וֹן לְאֻמִּֽים׃","maşĕ̌bi֤̇yẖa ׀ şĕ̌ʼ֣wòn ya֭mi̇ym şĕ̌ʼ֥wòn gȧlé̇y⁠he֗m wa⁠hàm֥wòn lĕʼumiֽ̇ym׃"],[65,8,"וַ⁠יִּ֤ירְא֨וּ ׀ יֹשְׁבֵ֣י קְ֭צָוֺת מֵ⁠אוֹתֹתֶ֑י⁠ךָ מ֤וֹצָֽאֵי־בֹ֖קֶר וָ⁠עֶ֣רֶב תַּרְנִֽין׃","wa⁠yi֤̇yrĕʼ֨ẇ ׀ yòşĕ̌bé֣y qĕ֭ẕáwֺţ mé⁠ʼwòţòţe֑y⁠ká m֤wòẕáֽʼéy-bò֖qer wá⁠ʻe֣reb ţȧrĕniֽyn׃"],[65,9,"פָּקַ֥דְתָּ הָ⁠אָ֨רֶץ ׀ וַ⁠תְּשֹׁ֪קְקֶ֡⁠הָ רַבַּ֬ת תַּעְשְׁרֶ֗⁠נָּה פֶּ֣לֶג אֱ֭לֹהִים מָ֣לֵא מָ֑יִם תָּכִ֥ין דְּ֝גָנָ֗⁠ם כִּי־כֵ֥ן תְּכִינֶֽ⁠הָ׃","pá̇qa֥dĕţá̇ há⁠ʼá֨reẕ ׀ wa⁠ţĕ̇şò֪̌qĕqe֡⁠há rabȧ֬ţ ţȧʻĕşĕ̌re֗⁠ná̇h pė֣leg ʼè֭lòhiym má֣léʼ má֑yim ţá̇ki֥yn dĕ̇֝gáná֗⁠m ki̇y-ké֥n ţĕ̇kiyneֽ⁠há׃"],[65,10,"תְּלָמֶ֣י⁠הָ רַ֭וֵּה נַחֵ֣ת גְּדוּדֶ֑י⁠הָ בִּ⁠רְבִיבִ֥ים תְּ֝מֹגְגֶ֗⁠נָּה צִמְחָ֥⁠הּ תְּבָרֵֽךְ׃","ţĕ̇láme֣y⁠há ra֭wé̇h naẖé֣ţ gĕ̇dẇde֑y⁠há bi̇⁠rĕbiybi֥ym ţĕ̇֝mògĕge֗⁠ná̇h ẕimĕẖá֥⁠ḣ ţĕ̇báréֽkĕ׃"],[65,11,"עִ֭טַּרְתָּ שְׁנַ֣ת טוֹבָתֶ֑⁠ךָ וּ֝⁠מַעְגָּלֶ֗י⁠ךָ יִרְעֲפ֥וּ⁠ן דָּֽשֶׁן׃","ʻi֭tȧrĕţá̇ şĕ̌na֣ţ twòbáţe֑⁠ká ẇ֝⁠maʻĕgá̇le֗y⁠ká yirĕʻàp֥ẇ⁠n dáֽ̇şěn׃"],[65,12,"יִ֭רְעֲפוּ נְא֣וֹת מִדְבָּ֑ר וְ֝⁠גִ֗יל גְּבָע֥וֹת תַּחְגֹּֽרְנָה׃","yi֭rĕʻàpẇ nĕʼ֣wòţ midĕbá֑̇r wĕ֝⁠gi֗yl gĕ̇báʻ֥wòţ ţȧẖĕgòֽ̇rĕnáh׃"],[65,13,"לָבְשׁ֬וּ כָרִ֨ים ׀ הַ⁠צֹּ֗אן וַ⁠עֲמָקִ֥ים יַֽעַטְפוּ־בָ֑ר יִ֝תְרוֹעֲע֗וּ אַף־יָשִֽׁירוּ׃","lábĕş̌֬ẇ kári֨ym ׀ ha⁠ẕò̇֗ʼn wa⁠ʻàmáqi֥ym yaֽʻatĕpẇ-bá֑r yi֝ţĕrwòʻàʻ֗ẇ ʼap-yáşǐֽyrẇ׃"],[66,1,"לַ֭⁠מְנַצֵּחַ שִׁ֣יר מִזְמ֑וֹר הָרִ֥יעוּ לֵ֝⁠אלֹהִים כָּל־הָ⁠אָֽרֶץ׃","la֭⁠mĕnaẕé̇ẖa şǐ֣yr mizĕm֑wòr hári֥yʻẇ lé֝⁠ʼlòhiym ká̇l-há⁠ʼáֽreẕ׃"],[66,2,"זַמְּר֥וּ כְבֽוֹד־שְׁמ֑⁠וֹ שִׂ֥ימוּ כָ֝ב֗וֹד תְּהִלָּתֽ⁠וֹ׃","zamĕ̇r֥ẇ kĕbֽwòd-şĕ̌m֑⁠wò şî֥ymẇ ká֝b֗wòd ţĕ̇hilá̇ţֽ⁠wò׃"],[66,3,"אִמְר֣וּ לֵ֭⁠אלֹהִים מַה־נּוֹרָ֣א מַעֲשֶׂ֑י⁠ךָ בְּ⁠רֹ֥ב עֻ֝זְּ⁠ךָ֗ יְֽכַחֲשׁ֖וּ לְ⁠ךָ֣ אֹיְבֶֽי⁠ךָ׃","ʼimĕr֣ẇ lé֭⁠ʼlòhiym mah-ṅwòrá֣ʼ maʻàşê֑y⁠ká bĕ̇⁠rò֥b ʻu֝zĕ̇⁠ká֗ yĕֽkaẖàş֖̌ẇ lĕ⁠ká֣ ʼòyĕbeֽy⁠ká׃"],[66,4,"כָּל־הָ⁠אָ֤רֶץ ׀ יִשְׁתַּחֲו֣וּ לְ֭⁠ךָ וִֽ⁠יזַמְּרוּ־לָ֑⁠ךְ יְזַמְּר֖וּ שִׁמְ⁠ךָ֣ סֶֽלָה׃","ká̇l-há⁠ʼá֤reẕ ׀ yişĕ̌ţȧẖàw֣ẇ lĕ֭⁠ká wiֽ⁠yzamĕ̇rẇ-lá֑⁠kĕ yĕzamĕ̇r֖ẇ şǐmĕ⁠ká֣ seֽláh׃"],[66,5,"לְכ֣וּ וּ֭⁠רְאוּ מִפְעֲל֣וֹת אֱלֹהִ֑ים נוֹרָ֥א עֲ֝לִילָ֗ה עַל־בְּנֵ֥י אָדָֽם׃","lĕk֣ẇ ẇ֭⁠rĕʼẇ mipĕʻàl֣wòţ ʼèlòhi֑ym nwòrá֥ʼ ʻà֝liylá֗h ʻal-bĕ̇né֥y ʼádáֽm׃"],[66,6,"הָ֤פַךְ יָ֨ם ׀ לְֽ⁠יַבָּשָׁ֗ה בַּ֭⁠נָּהָר יַֽעַבְר֣וּ בְ⁠רָ֑גֶל שָׁ֝֗ם נִשְׂמְחָה־בּֽ⁠וֹ׃","há֤pakĕ yá֨m ׀ lĕֽ⁠yabá̇şá̌֗h bȧ֭⁠ná̇hár yaֽʻabĕr֣ẇ bĕ⁠rá֑gel şá̌֝֗m nişĕ̂mĕẖáh-ḃֽ⁠wò׃"],[66,7,"מֹ֘שֵׁ֤ל בִּ⁠גְבוּרָת֨⁠וֹ ׀ עוֹלָ֗ם עֵ֭ינָי⁠ו בַּ⁠גּוֹיִ֣ם תִּצְפֶּ֑ינָה הַ⁠סּוֹרְרִ֓ים ׀ אַל־ירימו לָ֣⁠מוֹ סֶֽלָה׃","mò֘şé֤̌l bi̇⁠gĕbẇráţ֨⁠wò ׀ ʻwòlá֗m ʻé֭ynáy⁠w bȧ⁠ġwòyi֣m ţi̇ẕĕpė֑ynáh ha⁠ṡwòrĕri֓ym ׀ ʼal-yrymw lá֣⁠mwò seֽláh׃"],[66,8,"בָּרְכ֖וּ עַמִּ֥ים ׀ אֱלֹהֵ֑י⁠נוּ וְ֝⁠הַשְׁמִ֗יעוּ ק֣וֹל תְּהִלָּתֽ⁠וֹ׃","bá̇rĕk֖ẇ ʻami֥̇ym ׀ ʼèlòhé֑y⁠nẇ wĕ֝⁠haşĕ̌mi֗yʻẇ q֣wòl ţĕ̇hilá̇ţֽ⁠wò׃"],[66,9,"הַ⁠שָּׂ֣ם נַ֭פְשֵׁ⁠נוּ בַּֽ⁠חַיִּ֑ים וְ⁠לֹֽא־נָתַ֖ן לַ⁠מּ֣וֹט רַגְלֵֽ⁠נוּ׃","ha⁠şá֣̇̂m na֭pĕşé̌⁠nẇ bȧֽ⁠ẖayi֑̇ym wĕ⁠lòֽʼ-náţa֖n la⁠ṁ֣wòt ragĕléֽ⁠nẇ׃"],[66,10,"כִּֽי־בְחַנְתָּ֥⁠נוּ אֱלֹהִ֑ים צְ֝רַפְתָּ֗⁠נוּ כִּ⁠צְרָף־כָּֽסֶף׃","kiֽ̇y-bĕẖanĕţá֥̇⁠nẇ ʼèlòhi֑ym ẕĕ֝rapĕţá̇֗⁠nẇ ki̇⁠ẕĕráp-káֽ̇sep׃"],[66,11,"הֲבֵאתָ֥⁠נוּ בַ⁠מְּצוּדָ֑ה שַׂ֖מְתָּ מוּעָקָ֣ה בְ⁠מָתְנֵֽי⁠נוּ׃","hàbéʼţá֥⁠nẇ ba⁠mĕ̇ẕẇdá֑h şâ֖mĕţá̇ mẇʻáqá֣h bĕ⁠máţĕnéֽy⁠nẇ׃"],[66,12,"הִרְכַּ֥בְתָּ אֱנ֗וֹשׁ לְ⁠רֹ֫אשֵׁ֥⁠נוּ בָּֽאנוּ־בָ⁠אֵ֥שׁ וּ⁠בַ⁠מַּ֑יִם וַ֝⁠תּוֹצִיאֵ֗⁠נוּ לָֽ⁠רְוָיָֽה׃","hirĕkȧ֥bĕţá̇ ʼèn֗wòş̌ lĕ⁠rò֫ʼşé֥̌⁠nẇ báֽ̇ʼnẇ-bá⁠ʼé֥ş̌ ẇ⁠ba⁠mȧ֑yim wa֝⁠ţ̇wòẕiyʼé֗⁠nẇ láֽ⁠rĕwáyáֽh׃"],[66,13,"אָב֣וֹא בֵיתְ⁠ךָ֣ בְ⁠עוֹל֑וֹת אֲשַׁלֵּ֖ם לְ⁠ךָ֣ נְדָרָֽ⁠י׃","ʼáb֣wòʼ béyţĕ⁠ká֣ bĕ⁠ʻwòl֑wòţ ʼàşǎlé֖̇m lĕ⁠ká֣ nĕdáráֽ⁠y׃"],[66,14,"אֲשֶׁר־פָּצ֥וּ שְׂפָתָ֑⁠י וְ⁠דִבֶּר־פִּ֝֗⁠י בַּ⁠צַּר־לִֽ⁠י׃","ʼàşěr-pá̇ẕ֥ẇ şĕ̂páţá֑⁠y wĕ⁠dibėr-pi̇֝֗⁠y bȧ⁠ẕȧr-liֽ⁠y׃"],[66,15,"עֹ֘ל֤וֹת מֵחִ֣ים אַעֲלֶה־לָּ֭⁠ךְ עִם־קְטֹ֣רֶת אֵילִ֑ים אֶ֥עֱשֶֽׂה בָקָ֖ר עִם־עַתּוּדִ֣ים סֶֽלָה׃","ʻò֘l֤wòţ méẖi֣ym ʼaʻàleh-lá֭̇⁠kĕ ʻim-qĕtò֣reţ ʼéyli֑ym ʼe֥ʻèşêֽh báqá֖r ʻim-ʻaţ̇ẇdi֣ym seֽláh׃"],[66,16,"לְכֽוּ־שִׁמְע֣וּ וַ֭⁠אֲסַפְּרָה כָּל־יִרְאֵ֣י אֱלֹהִ֑ים אֲשֶׁ֖ר עָשָׂ֣ה לְ⁠נַפְשִֽׁ⁠י׃","lĕkֽẇ-şǐmĕʻ֣ẇ wa֭⁠ʼàsapĕ̇ráh ká̇l-yirĕʼé֣y ʼèlòhi֑ym ʼàşě֖r ʻáşá֣̂h lĕ⁠napĕşǐֽ⁠y׃"],[66,17,"אֵלָ֥י⁠ו פִּֽ⁠י־קָרָ֑אתִי וְ֝⁠רוֹמַ֗ם תַּ֣חַת לְשׁוֹנִֽ⁠י׃","ʼélá֥y⁠w piֽ̇⁠y-qárá֑ʼţiy wĕ֝⁠rwòma֗m ţȧ֣ẖaţ lĕş̌wòniֽ⁠y׃"],[66,18,"אָ֭וֶן אִם־רָאִ֣יתִי בְ⁠לִבִּ֑⁠י לֹ֖א יִשְׁמַ֣ע ׀ אֲדֹנָֽ⁠י׃","ʼá֭wen ʼim-ráʼi֣yţiy bĕ⁠libi֑̇⁠y lò֖ʼ yişĕ̌ma֣ʻ ׀ ʼàdònáֽ⁠y׃"],[66,19,"אָ֭כֵן שָׁמַ֣ע אֱלֹהִ֑ים הִ֝קְשִׁ֗יב בְּ⁠ק֣וֹל תְּפִלָּתִֽ⁠י׃","ʼá֭kén şá̌ma֣ʻ ʼèlòhi֑ym hi֝qĕşǐ֗yb bĕ̇⁠q֣wòl ţĕ̇pilá̇ţiֽ⁠y׃"],[66,20,"בָּר֥וּךְ אֱלֹהִ֑ים אֲשֶׁ֥ר לֹֽא־הֵסִ֘יר תְּפִלָּתִ֥⁠י וְ֝⁠חַסְדּ֗⁠וֹ מֵ⁠אִתִּֽ⁠י׃","bá̇r֥ẇkĕ ʼèlòhi֑ym ʼàşě֥r lòֽʼ-hési֘yr ţĕ̇pilá̇ţi֥⁠y wĕ֝⁠ẖasĕḋ֗⁠wò mé⁠ʼiţiֽ̇⁠y׃"],[67,1,"אֱלֹהִ֗ים יְחָנֵּ֥⁠נוּ וִֽ⁠יבָרְכֵ֑⁠נוּ יָ֤אֵ֥ר פָּנָ֖י⁠ו אִתָּ֣⁠נוּ סֶֽלָה׃","ʼèlòhi֗ym yĕẖáné֥̇⁠nẇ wiֽ⁠ybárĕké֑⁠nẇ yá֤ʼé֥r pá̇ná֖y⁠w ʼiţá֣̇⁠nẇ seֽláh׃"],[67,2,"לָ⁠דַ֣עַת בָּ⁠אָ֣רֶץ דַּרְכֶּ֑⁠ךָ בְּ⁠כָל־גּ֝וֹיִ֗ם יְשׁוּעָתֶֽ⁠ךָ׃","lá⁠da֣ʻaţ bá̇⁠ʼá֣reẕ dȧrĕkė֑⁠ká bĕ̇⁠kál-ġ֝wòyi֗m yĕş̌ẇʻáţeֽ⁠ká׃"],[67,3,"יוֹד֖וּ⁠ךָ עַמִּ֥ים ׀ אֱלֹהִ֑ים י֝וֹד֗וּ⁠ךָ עַמִּ֥ים כֻּלָּֽ⁠ם׃","ywòd֖ẇ⁠ká ʻami֥̇ym ׀ ʼèlòhi֑ym y֝wòd֗ẇ⁠ká ʻami֥̇ym ku̇láֽ̇⁠m׃"],[67,4,"יִֽשְׂמְח֥וּ וִֽ⁠ירַנְּנ֗וּ לְאֻ֫מִּ֥ים כִּֽי־תִשְׁפֹּ֣ט עַמִּ֣ים מִישׁ֑וֹר וּ⁠לְאֻמִּ֓ים ׀ בָּ⁠אָ֖רֶץ תַּנְחֵ֣⁠ם סֶֽלָה׃","yiֽşĕ̂mĕẖ֥ẇ wiֽ⁠yranĕ̇n֗ẇ lĕʼu֫mi֥̇ym kiֽ̇y-ţişĕ̌pò֣̇t ʻami֣̇ym miyş֑̌wòr ẇ⁠lĕʼumi̇֓ym ׀ bá̇⁠ʼá֖reẕ ţȧnĕẖé֣⁠m seֽláh׃"],[67,5,"יוֹד֖וּ⁠ךָ עַמִּ֥ים ׀ אֱלֹהִ֑ים י֝וֹד֗וּ⁠ךָ עַמִּ֥ים כֻּלָּֽ⁠ם׃","ywòd֖ẇ⁠ká ʻami֥̇ym ׀ ʼèlòhi֑ym y֝wòd֗ẇ⁠ká ʻami֥̇ym ku̇láֽ̇⁠m׃"],[67,6,"אֶ֭רֶץ נָתְנָ֣ה יְבוּלָ֑⁠הּ יְ֝בָרְכֵ֗⁠נוּ אֱלֹהִ֥ים אֱלֹהֵֽי⁠נוּ׃","ʼe֭reẕ náţĕná֣h yĕbẇlá֑⁠ḣ yĕ֝bárĕké֗⁠nẇ ʼèlòhi֥ym ʼèlòhéֽy⁠nẇ׃"],[67,7,"יְבָרְכֵ֥⁠נוּ אֱלֹהִ֑ים וְ⁠יִֽירְא֥וּ אֹ֝ת֗⁠וֹ כָּל־אַפְסֵי־אָֽרֶץ׃","yĕbárĕké֥⁠nẇ ʼèlòhi֑ym wĕ⁠yiֽyrĕʼ֥ẇ ʼò֝ţ֗⁠wò ká̇l-ʼapĕséy-ʼáֽreẕ׃"],[68,1,"יָק֣וּם אֱ֭לֹהִים יָפ֣וּצוּ אוֹיְבָ֑י⁠ו וְ⁠יָנ֥וּסוּ מְ֝שַׂנְאָ֗י⁠ו מִ⁠פָּנָֽי⁠ו׃","yáq֣ẇm ʼè֭lòhiym yáp֣ẇẕẇ ʼwòyĕbá֑y⁠w wĕ⁠yán֥ẇsẇ mĕ֝şânĕʼá֗y⁠w mi⁠pá̇náֽy⁠w׃"],[68,2,"כְּ⁠הִנְדֹּ֥ף עָשָׁ֗ן תִּ֫נְדֹּ֥ף כְּ⁠הִמֵּ֣ס דּ֭וֹנַג מִ⁠פְּנֵי־אֵ֑שׁ יֹאבְד֥וּ רְ֝שָׁעִ֗ים מִ⁠פְּנֵ֥י אֱלֹהִֽים׃","kĕ̇⁠hinĕdò֥̇p ʻáşá̌֗n ţi̇֫nĕdò֥̇p kĕ̇⁠himé֣̇s ḋ֭wònag mi⁠pĕ̇néy-ʼé֑ş̌ yòʼbĕd֥ẇ rĕ֝şá̌ʻi֗ym mi⁠pĕ̇né֥y ʼèlòhiֽym׃"],[68,3,"וְֽ⁠צַדִּיקִ֗ים יִשְׂמְח֣וּ יַֽ֭עַלְצוּ לִ⁠פְנֵ֥י אֱלֹהִ֗ים וְ⁠יָשִׂ֥ישׂוּ בְ⁠שִׂמְחָֽה׃","wĕֽ⁠ẕadi̇yqi֗ym yişĕ̂mĕẖ֣ẇ yaֽ֭ʻalĕẕẇ li⁠pĕné֥y ʼèlòhi֗ym wĕ⁠yáşî֥yş̂ẇ bĕ⁠şîmĕẖáֽh׃"],[68,4,"שִׁ֤ירוּ ׀ לֵֽ⁠אלֹהִים֮ זַמְּר֪וּ שְׁ֫מ֥⁠וֹ סֹ֡לּוּ לָ⁠רֹכֵ֣ב בָּ֭⁠עֲרָבוֹת בְּ⁠יָ֥הּ שְׁמ֗⁠וֹ וְ⁠עִלְז֥וּ לְ⁠פָנָֽי⁠ו׃","şǐ֤yrẇ ׀ léֽ⁠ʼlòhiym֮ zamĕ̇r֪ẇ şĕ̌֫m֥⁠wò sò֡l̇ẇ lá⁠ròké֣b bá֭̇⁠ʻàrábwòţ bĕ̇⁠yá֥ḣ şĕ̌m֗⁠wò wĕ⁠ʻilĕz֥ẇ lĕ⁠pánáֽy⁠w׃"],[68,5,"אֲבִ֣י יְ֭תוֹמִים וְ⁠דַיַּ֣ן אַלְמָנ֑וֹת אֱ֝לֹהִ֗ים בִּ⁠מְע֥וֹן קָדְשֽׁ⁠וֹ׃","ʼàbi֣y yĕ֭ţwòmiym wĕ⁠dayȧ֣n ʼalĕmán֑wòţ ʼè֝lòhi֗ym bi̇⁠mĕʻ֥wòn qádĕşֽ̌⁠wò׃"],[68,6,"אֱלֹהִ֤ים ׀ מ֘וֹשִׁ֤יב יְחִידִ֨ים ׀ בַּ֗יְתָ⁠ה מוֹצִ֣יא אֲ֭סִירִים בַּ⁠כּוֹשָׁר֑וֹת אַ֥ךְ ס֝וֹרֲרִ֗ים שָׁכְנ֥וּ צְחִיחָֽה׃","ʼèlòhi֤ym ׀ m֘wòşǐ֤yb yĕẖiydi֨ym ׀ bȧ֗yĕţá⁠h mwòẕi֣yʼ ʼà֭siyriym bȧ⁠k̇wòşá̌r֑wòţ ʼa֥kĕ s֝wòràri֗ym şá̌kĕn֥ẇ ẕĕẖiyẖáֽh׃"],[68,7,"אֱֽלֹהִ֗ים בְּ֭⁠צֵאתְ⁠ךָ לִ⁠פְנֵ֣י עַמֶּ֑⁠ךָ בְּ⁠צַעְדְּ⁠ךָ֖ בִֽ⁠ישִׁימ֣וֹן סֶֽלָה׃","ʼèֽlòhi֗ym bĕ֭̇⁠ẕéʼţĕ⁠ká li⁠pĕné֣y ʻamė֑⁠ká bĕ̇⁠ẕaʻĕdĕ̇⁠ká֖ biֽ⁠yşǐym֣wòn seֽláh׃"],[68,8,"אֶ֤רֶץ רָעָ֨שָׁה ׀ אַף־שָׁמַ֣יִם נָטְפוּ֮ מִ⁠פְּנֵ֪י אֱלֹ֫הִ֥ים זֶ֥ה סִינַ֑י מִ⁠פְּנֵ֥י אֱ֝לֹהִ֗ים אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","ʼe֤reẕ ráʻá֨şá̌h ׀ ʼap-şá̌ma֣yim nátĕpẇ֮ mi⁠pĕ̇né֪y ʼèlò֫hi֥ym ze֥h siyna֑y mi⁠pĕ̇né֥y ʼè֝lòhi֗ym ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[68,9,"גֶּ֣שֶׁם נְ֭דָבוֹת תָּנִ֣יף אֱלֹהִ֑ים נַחֲלָתְ⁠ךָ֥ וְ֝⁠נִלְאָ֗ה אַתָּ֥ה כֽוֹנַנְתָּֽ⁠הּ׃","gė֣şěm nĕ֭dábwòţ ţá̇ni֣yp ʼèlòhi֑ym naẖàláţĕ⁠ká֥ wĕ֝⁠nilĕʼá֗h ʼaţá֥̇h kֽwònanĕţֽ̇á⁠ḣ׃"],[68,10,"חַיָּתְ⁠ךָ֥ יָֽשְׁבוּ־בָ֑⁠הּ תָּ֤כִ֥ין בְּ⁠טוֹבָתְ⁠ךָ֖ לֶ⁠עָנִ֣י אֱלֹהִֽים׃","ẖayá̇ţĕ⁠ká֥ yáֽşĕ̌bẇ-bá֑⁠ḣ ţá֤̇ki֥yn bĕ̇⁠twòbáţĕ⁠ká֖ le⁠ʻáni֣y ʼèlòhiֽym׃"],[68,11,"אֲדֹנָ֥⁠י יִתֶּן־אֹ֑מֶר הַֽ֝⁠מְבַשְּׂר֗וֹת צָבָ֥א רָֽב׃","ʼàdòná֥⁠y yiţėn-ʼò֑mer haֽ֝⁠mĕbaşĕ̇̂r֗wòţ ẕábá֥ʼ ráֽb׃"],[68,12,"מַלְכֵ֣י צְ֭בָאוֹת יִדֹּד֣וּ⁠ן יִדֹּד֑וּ⁠ן וּ⁠נְוַת בַּ֝֗יִת תְּחַלֵּ֥ק שָׁלָֽל׃","malĕké֣y ẕĕ֭báʼwòţ yidò̇d֣ẇ⁠n yidò̇d֑ẇ⁠n ẇ⁠nĕwaţ bȧ֝֗yiţ ţĕ̇ẖalé֥̇q şá̌láֽl׃"],[68,13,"אִֽם־תִּשְׁכְּבוּ⁠ן֮ בֵּ֪ין שְׁפַ֫תָּ֥יִם כַּנְפֵ֣י י֭וֹנָה נֶחְפָּ֣ה בַ⁠כֶּ֑סֶף וְ֝⁠אֶבְרוֹתֶ֗י⁠הָ בִּֽ⁠ירַקְרַ֥ק חָרֽוּץ׃","ʼiֽm-ţi̇şĕ̌kĕ̇bẇ⁠n֮ bé֪̇yn şĕ̌pa֫ţá֥̇yim kȧnĕpé֣y y֭wònáh neẖĕpá֣̇h ba⁠kė֑sep wĕ֝⁠ʼebĕrwòţe֗y⁠há biֽ̇⁠yraqĕra֥q ẖárֽẇẕ׃"],[68,14,"בְּ⁠פָ֘רֵ֤שׂ שַׁדַּ֓י מְלָ֘כִ֤ים בָּ֗⁠הּ תַּשְׁלֵ֥ג בְּ⁠צַלְמֽוֹן׃","bĕ̇⁠pá֘ré֤ş̂ şǎdȧ֓y mĕlá֘ki֤ym bá̇֗⁠ḣ ţȧşĕ̌lé֥g bĕ̇⁠ẕalĕmֽwòn׃"],[68,15,"הַר־אֱ֭לֹהִים הַר־בָּשָׁ֑ן הַ֥ר גַּ֝בְנֻנִּ֗ים הַר־בָּשָֽׁן׃","har-ʼè֭lòhiym har-bá̇şá֑̌n ha֥r gȧ֝bĕnuni̇֗ym har-bá̇şáֽ̌n׃"],[68,16,"לָ֤⁠מָּה ׀ תְּֽרַצְּדוּ⁠ן֮ הָרִ֪ים גַּבְנֻ֫נִּ֥ים הָ⁠הָ֗ר חָמַ֣ד אֱלֹהִ֣ים לְ⁠שִׁבְתּ֑⁠וֹ אַף־יְ֝הוָ֗ה יִשְׁכֹּ֥ן לָ⁠נֶֽצַח׃","lá֤⁠má̇h ׀ ţĕֽ̇raẕĕ̇dẇ⁠n֮ hári֪ym gȧbĕnu֫ni֥̇ym há⁠há֗r ẖáma֣d ʼèlòhi֣ym lĕ⁠şǐbĕţ֑̇⁠wò ʼap-yĕ֝hwá֗h yişĕ̌kò֥̇n lá⁠neֽẕaẖ׃"],[68,17,"רֶ֤כֶב אֱלֹהִ֗ים רִבֹּתַ֣יִם אַלְפֵ֣י שִׁנְאָ֑ן אֲדֹנָ֥⁠י בָ֝֗⁠ם סִינַ֥י בַּ⁠קֹּֽדֶשׁ׃","re֤keb ʼèlòhi֗ym ribò̇ţa֣yim ʼalĕpé֣y şǐnĕʼá֑n ʼàdòná֥⁠y bá֝֗⁠m siyna֥y bȧ⁠qòֽ̇deş̌׃"],[68,18,"עָ֘לִ֤יתָ לַ⁠מָּר֨וֹם ׀ שָׁ֘בִ֤יתָ שֶּׁ֗בִי לָקַ֣חְתָּ מַ֭תָּנוֹת בָּ⁠אָדָ֑ם וְ⁠אַ֥ף ס֝וֹרְרִ֗ים לִ⁠שְׁכֹּ֤ן ׀ יָ֬הּ אֱלֹהִֽים׃","ʻá֘li֤yţá la⁠má̇r֨wòm ׀ şá̌֘bi֤yţá şė̌֗biy láqa֣ẖĕţá̇ ma֭ţá̇nwòţ bá̇⁠ʼádá֑m wĕ⁠ʼa֥p s֝wòrĕri֗ym li⁠şĕ̌kò֤̇n ׀ yá֬ḣ ʼèlòhiֽym׃"],[68,19,"בָּ֤ר֣וּךְ אֲדֹנָ⁠י֮ י֤וֹם ׀ י֥וֹם יַֽעֲמָס־לָ֗⁠נוּ הָ֘⁠אֵ֤ל יְֽשׁוּעָתֵ֬⁠נוּ סֶֽלָה׃","bá֤̇r֣ẇkĕ ʼàdòná⁠y֮ y֤wòm ׀ y֥wòm yaֽʻàmás-lá֗⁠nẇ há֘⁠ʼé֤l yĕֽş̌ẇʻáţé֬⁠nẇ seֽláh׃"],[68,20,"הָ֤⁠אֵ֣ל ׀ לָ⁠נוּ֮ אֵ֤ל לְֽ⁠מוֹשָׁ֫ע֥וֹת וְ⁠לֵ⁠יהוִ֥ה אֲדֹנָ֑⁠י לַ֝⁠מָּ֗וֶת תּוֹצָאֽוֹת׃","há֤⁠ʼé֣l ׀ lá⁠nẇ֮ ʼé֤l lĕֽ⁠mwòşá̌֫ʻ֥wòţ wĕ⁠lé⁠yhwi֥h ʼàdòná֑⁠y la֝⁠má̇֗weţ ţ̇wòẕáʼֽwòţ׃"],[68,21,"אַךְ־אֱלֹהִ֗ים יִמְחַץ֮ רֹ֤אשׁ אֹ֫יְבָ֥י⁠ו קָדְקֹ֥ד שֵׂעָ֑ר מִ֝תְהַלֵּ֗ךְ בַּ⁠אֲשָׁמָֽי⁠ו׃","ʼakĕ-ʼèlòhi֗ym yimĕẖaẕ֮ rò֤ʼş̌ ʼò֫yĕbá֥y⁠w qádĕqò֥d şé̂ʻá֑r mi֝ţĕhalé̇֗kĕ bȧ⁠ʼàşá̌máֽy⁠w׃"],[68,22,"אָמַ֣ר אֲ֭דֹנָ⁠י מִ⁠בָּשָׁ֣ן אָשִׁ֑יב אָ֝שִׁ֗יב מִֽ⁠מְּצֻל֥וֹת יָֽם׃","ʼáma֣r ʼà֭dòná⁠y mi⁠bá̇şá֣̌n ʼáşǐ֑yb ʼá֝şǐ֗yb miֽ⁠mĕ̇ẕul֥wòţ yáֽm׃"],[68,23,"לְמַ֤עַן ׀ תִּֽמְחַ֥ץ רַגְלְ⁠ךָ֗ בְּ֫⁠דָ֥ם לְשׁ֥וֹן כְּלָבֶ֑י⁠ךָ מֵ⁠אֹיְבִ֥ים מִנֵּֽ⁠הוּ׃","lĕma֤ʻan ׀ ţiֽ̇mĕẖa֥ẕ ragĕlĕ⁠ká֗ bĕ̇֫⁠dá֥m lĕş֥̌wòn kĕ̇lábe֑y⁠ká mé⁠ʼòyĕbi֥ym minéֽ̇⁠hẇ׃"],[68,24,"רָא֣וּ הֲלִיכוֹתֶ֣י⁠ךָ אֱלֹהִ֑ים הֲלִ֘יכ֤וֹת אֵלִ֖⁠י מַלְכִּ֣⁠י בַ⁠קֹּֽדֶשׁ׃","ráʼ֣ẇ hàliykwòţe֣y⁠ká ʼèlòhi֑ym hàli֘yk֤wòţ ʼéli֖⁠y malĕki֣̇⁠y ba⁠qòֽ̇deş̌׃"],[68,25,"קִדְּמ֣וּ שָׁ֭רִים אַחַ֣ר נֹגְנִ֑ים בְּ⁠ת֥וֹךְ עֲ֝לָמ֗וֹת תּוֹפֵפֽוֹת׃","qidĕ̇m֣ẇ şá֭̌riym ʼaẖa֣r nògĕni֑ym bĕ̇⁠ţ֥wòkĕ ʻà֝lám֗wòţ ţ̇wòpépֽwòţ׃"],[68,26,"בְּֽ֭⁠מַקְהֵלוֹת בָּרְכ֣וּ אֱלֹהִ֑ים יְ֝הוָ֗ה מִ⁠מְּק֥וֹר יִשְׂרָאֵֽל׃","bĕֽ֭̇⁠maqĕhélwòţ bá̇rĕk֣ẇ ʼèlòhi֑ym yĕ֝hwá֗h mi⁠mĕ̇q֥wòr yişĕ̂ráʼéֽl׃"],[68,27,"שָׁ֤ם בִּנְיָמִ֨ן ׀ צָעִ֡יר רֹדֵ֗⁠ם שָׂרֵ֣י יְ֭הוּדָה רִגְמָתָ֑⁠ם שָׂרֵ֥י זְ֝בֻל֗וּן שָׂרֵ֥י נַפְתָּלִֽי׃","şá֤̌m bi̇nĕyámi֨n ׀ ẕáʻi֡yr ròdé֗⁠m şá̂ré֣y yĕ֭hẇdáh rigĕmáţá֑⁠m şá̂ré֥y zĕ֝bul֗ẇn şá̂ré֥y napĕţá̇liֽy׃"],[68,28,"צִוָּ֥ה אֱלֹהֶ֗י⁠ךָ עֻ֫זֶּ֥⁠ךָ עוּזָּ֥⁠ה אֱלֹהִ֑ים ז֝֗וּ פָּעַ֥לְתָּ לָּֽ⁠נוּ׃","ẕiwá֥̇h ʼèlòhe֗y⁠ká ʻu֫zė֥⁠ká ʻẇzá֥̇⁠h ʼèlòhi֑ym z֝֗ẇ pá̇ʻa֥lĕţá̇ láֽ̇⁠nẇ׃"],[68,29,"מֵֽ֭⁠הֵיכָלֶ⁠ךָ עַל־יְרוּשָׁלִָ֑ם לְ⁠ךָ֤ יוֹבִ֖ילוּ מְלָכִ֣ים שָֽׁי׃","méֽ֭⁠héykále⁠ká ʻal-yĕrẇşá̌liá֑m lĕ⁠ká֤ ywòbi֖ylẇ mĕláki֣ym şáֽ̌y׃"],[68,30,"גְּעַ֨ר חַיַּ֪ת קָנֶ֡ה עֲדַ֤ת אַבִּירִ֨ים ׀ בְּ⁠עֶגְלֵ֬י עַמִּ֗ים מִתְרַפֵּ֥ס בְּ⁠רַצֵּי־כָ֑סֶף בִּזַּ֥ר עַ֝מִּ֗ים קְרָב֥וֹת יֶחְפָּֽצוּ׃","gĕ̇ʻa֨r ẖayȧ֪ţ qáne֡h ʻàda֤ţ ʼabi̇yri֨ym ׀ bĕ̇⁠ʻegĕlé֬y ʻami̇֗ym miţĕrapé֥̇s bĕ̇⁠raẕé̇y-ká֑sep bi̇zȧ֥r ʻa֝mi̇֗ym qĕráb֥wòţ yeẖĕpáֽ̇ẕẇ׃"],[68,31,"יֶאֱתָ֣יוּ חַ֭שְׁמַנִּים מִנִּ֣י מִצְרָ֑יִם כּ֥וּשׁ תָּרִ֥יץ יָ֝דָ֗י⁠ו לֵ⁠אלֹהִֽים׃","yeʼèţá֣yẇ ẖa֭şĕ̌mani̇ym mini֣̇y miẕĕrá֑yim k֥̇ẇş̌ ţá̇ri֥yẕ yá֝dá֗y⁠w lé⁠ʼlòhiֽym׃"],[68,32,"מַמְלְכ֣וֹת הָ֭⁠אָרֶץ שִׁ֣ירוּ לֵ⁠אלֹהִ֑ים זַמְּר֖וּ אֲדֹנָ֣⁠י סֶֽלָה׃","mamĕlĕk֣wòţ há֭⁠ʼáreẕ şǐ֣yrẇ lé⁠ʼlòhi֑ym zamĕ̇r֖ẇ ʼàdòná֣⁠y seֽláh׃"],[68,33,"לָ֭⁠רֹכֵב בִּ⁠שְׁמֵ֣י שְׁמֵי־קֶ֑דֶם הֵ֥ן יִתֵּ֥ן בְּ֝⁠קוֹל⁠וֹ ק֣וֹל עֹֽז׃","lá֭⁠ròkéb bi̇⁠şĕ̌mé֣y şĕ̌méy-qe֑dem hé֥n yiţé֥̇n bĕ̇֝⁠qwòl⁠wò q֣wòl ʻòֽz׃"],[68,34,"תְּנ֥וּ עֹ֗ז לֵֽ⁠אלֹ֫הִ֥ים עַֽל־יִשְׂרָאֵ֥ל גַּאֲוָת֑⁠וֹ וְ֝⁠עֻזּ֗⁠וֹ בַּ⁠שְּׁחָקִֽים׃","ţĕ̇n֥ẇ ʻò֗z léֽ⁠ʼlò֫hi֥ym ʻaֽl-yişĕ̂ráʼé֥l gȧʼàwáţ֑⁠wò wĕ֝⁠ʻuż֗⁠wò bȧ⁠şĕ̇̌ẖáqiֽym׃"],[68,35,"נ֤וֹרָ֥א אֱלֹהִ֗ים מִֽ⁠מִּקְדָּ֫שֶׁ֥י⁠ךָ אֵ֤ל יִשְׂרָאֵ֗ל ה֤וּא נֹתֵ֨ן ׀ עֹ֖ז וְ⁠תַעֲצֻמ֥וֹת לָ⁠עָ֗ם בָּר֥וּךְ אֱלֹהִֽים׃","n֤wòrá֥ʼ ʼèlòhi֗ym miֽ⁠mi̇qĕdá̇֫şě֥y⁠ká ʼé֤l yişĕ̂ráʼé֗l h֤ẇʼ nòţé֨n ׀ ʻò֖z wĕ⁠ţaʻàẕum֥wòţ lá⁠ʻá֗m bá̇r֥ẇkĕ ʼèlòhiֽym׃"],[69,1,"הוֹשִׁיעֵ֥⁠נִי אֱלֹהִ֑ים כִּ֤י בָ֖אוּ מַ֣יִם עַד־נָֽפֶשׁ׃","hwòşǐyʻé֥⁠niy ʼèlòhi֑ym ki֤̇y bá֖ʼẇ ma֣yim ʻad-náֽpeş̌׃"],[69,2,"טָבַ֤עְתִּי ׀ בִּ⁠יוֵ֣ן מְ֭צוּלָה וְ⁠אֵ֣ין מָעֳמָ֑ד בָּ֥אתִי בְ⁠מַעֲמַקֵּי־מַ֝֗יִם וְ⁠שִׁבֹּ֥לֶת שְׁטָפָֽתְ⁠נִי׃","tába֤ʻĕţi̇y ׀ bi̇⁠ywé֣n mĕ֭ẕẇláh wĕ⁠ʼé֣yn máʻomá֑d bá֥̇ʼţiy bĕ⁠maʻàmaqé̇y-ma֝֗yim wĕ⁠şǐbò֥̇leţ şĕ̌tápáֽţĕ⁠niy׃"],[69,3,"יָגַ֣עְתִּי בְ⁠קָרְאִ⁠י֮ נִחַ֪ר גְּר֫וֹנִ֥⁠י כָּל֥וּ עֵינַ֑⁠י מְ֝יַחֵ֗ל לֵ⁠אלֹהָֽ⁠י׃","yága֣ʻĕţi̇y bĕ⁠qárĕʼi⁠y֮ niẖa֪r gĕ̇r֫wòni֥⁠y ká̇l֥ẇ ʻéyna֑⁠y mĕ֝yaẖé֗l lé⁠ʼlòháֽ⁠y׃"],[69,4,"רַבּ֤וּ ׀ מִ⁠שַּׂעֲר֣וֹת רֹאשִׁ⁠י֮ שֹׂנְאַ֪⁠י חִ֫נָּ֥ם עָצְמ֣וּ מַ֭צְמִיתַ⁠י אֹיְבַ֣⁠י שֶׁ֑קֶר אֲשֶׁ֥ר לֹא־גָ֝זַ֗לְתִּי אָ֣ז אָשִֽׁיב׃","raḃ֤ẇ ׀ mi⁠şȧ̂ʻàr֣wòţ ròʼşǐ⁠y֮ şò̂nĕʼa֪⁠y ẖi֫ná֥̇m ʻáẕĕm֣ẇ ma֭ẕĕmiyţa⁠y ʼòyĕba֣⁠y şě֑qer ʼàşě֥r lòʼ-gá֝za֗lĕţi̇y ʼá֣z ʼáşǐֽyb׃"],[69,5,"אֱֽלֹהִ֗ים אַתָּ֣ה יָ֭דַעְתָּ לְ⁠אִוַּלְתִּ֑⁠י וְ֝⁠אַשְׁמוֹתַ֗⁠י מִמְּ⁠ךָ֥ לֹא־נִכְחָֽדוּ׃","ʼèֽlòhi֗ym ʼaţá֣̇h yá֭daʻĕţá̇ lĕ⁠ʼiwȧlĕţi֑̇⁠y wĕ֝⁠ʼaşĕ̌mwòţa֗⁠y mimĕ̇⁠ká֥ lòʼ-nikĕẖáֽdẇ׃"],[69,6,"אַל־יֵ֘בֹ֤שׁוּ בִ֨⁠י ׀ קֹוֶי⁠ךָ֮ אֲדֹנָ֥⁠י יְהוִ֗ה צְבָ֫א֥וֹת אַל־יִכָּ֣לְמוּ בִ֣⁠י מְבַקְשֶׁ֑י⁠ךָ אֱ֝לֹהֵ֗י יִשְׂרָאֵֽל׃","ʼal-yé֘bò֤ş̌ẇ bi֨⁠y ׀ qòwey⁠ká֮ ʼàdòná֥⁠y yĕhwi֗h ẕĕbá֫ʼ֥wòţ ʼal-yiká֣̇lĕmẇ bi֣⁠y mĕbaqĕşě֑y⁠ká ʼè֝lòhé֗y yişĕ̂ráʼéֽl׃"],[69,7,"כִּֽי־עָ֭לֶי⁠ךָ נָשָׂ֣אתִי חֶרְפָּ֑ה כִּסְּתָ֖ה כְלִמָּ֣ה פָנָֽ⁠י׃","kiֽ̇y-ʻá֭ley⁠ká náşá֣̂ʼţiy ẖerĕpá֑̇h ki̇sĕ̇ţá֖h kĕlimá֣̇h pánáֽ⁠y׃"],[69,8,"מ֭וּזָר הָיִ֣יתִי לְ⁠אֶחָ֑⁠י וְ֝⁠נָכְרִ֗י לִ⁠בְנֵ֥י אִמִּֽ⁠י׃","m֭ẇzár háyi֣yţiy lĕ⁠ʼeẖá֑⁠y wĕ֝⁠nákĕri֗y li⁠bĕné֥y ʼimiֽ̇⁠y׃"],[69,9,"כִּֽי־קִנְאַ֣ת בֵּיתְ⁠ךָ֣ אֲכָלָ֑תְ⁠נִי וְ⁠חֶרְפּ֥וֹת ח֝וֹרְפֶ֗י⁠ךָ נָפְל֥וּ עָלָֽ⁠י׃","kiֽ̇y-qinĕʼa֣ţ bé̇yţĕ⁠ká֣ ʼàkálá֑ţĕ⁠niy wĕ⁠ẖerĕṗ֥wòţ ẖ֝wòrĕpe֗y⁠ká nápĕl֥ẇ ʻáláֽ⁠y׃"],[69,10,"וָ⁠אֶבְכֶּ֣ה בַ⁠צּ֣וֹם נַפְשִׁ֑⁠י וַ⁠תְּהִ֖י לַ⁠חֲרָפ֣וֹת לִֽ⁠י׃","wá⁠ʼebĕkė֣h ba⁠ẕ֣̇wòm napĕşǐ֑⁠y wa⁠ţĕ̇hi֖y la⁠ẖàráp֣wòţ liֽ⁠y׃"],[69,11,"וָ⁠אֶתְּנָ֣⁠ה לְבוּשִׁ֣⁠י שָׂ֑ק וָ⁠אֱהִ֖י לָ⁠הֶ֣ם לְ⁠מָשָֽׁל׃","wá⁠ʼeţĕ̇ná֣⁠h lĕbẇşǐ֣⁠y şá֑̂q wá⁠ʼèhi֖y lá⁠he֣m lĕ⁠máşáֽ̌l׃"],[69,12,"יָשִׂ֣יחוּ בִ֭⁠י יֹ֣שְׁבֵי שָׁ֑עַר וּ֝⁠נְגִינ֗וֹת שׁוֹתֵ֥י שֵׁכָֽר׃","yáşî֣yẖẇ bi֭⁠y yò֣şĕ̌béy şá֑̌ʻar ẇ֝⁠nĕgiyn֗wòţ ş̌wòţé֥y şé̌káֽr׃"],[69,13,"וַ⁠אֲנִ֤י תְפִלָּתִֽ⁠י־לְ⁠ךָ֨ ׀ יְהוָ֡ה עֵ֤ת רָצ֗וֹן אֱלֹהִ֥ים בְּ⁠רָב־חַסְדֶּ֑⁠ךָ עֲ֝נֵ֗⁠נִי בֶּ⁠אֱמֶ֥ת יִשְׁעֶֽ⁠ךָ׃","wa⁠ʼàni֤y ţĕpilá̇ţiֽ⁠y-lĕ⁠ká֨ ׀ yĕhwá֡h ʻé֤ţ ráẕ֗wòn ʼèlòhi֥ym bĕ̇⁠ráb-ẖasĕdė֑⁠ká ʻà֝né֗⁠niy bė⁠ʼème֥ţ yişĕ̌ʻeֽ⁠ká׃"],[69,14,"הַצִּילֵ֣⁠נִי מִ֭⁠טִּיט וְ⁠אַל־אֶטְבָּ֑עָה אִנָּצְלָ֥ה מִ֝⁠שֹּֽׂנְאַ֗⁠י וּ⁠מִ⁠מַּֽעֲמַקֵּי־מָֽיִם׃","haẕi̇ylé֣⁠niy mi֭⁠ti̇yt wĕ⁠ʼal-ʼetĕbá֑̇ʻáh ʼiná̇ẕĕlá֥h mi֝⁠şòֽ̇̂nĕʼa֗⁠y ẇ⁠mi⁠mȧֽʻàmaqé̇y-máֽyim׃"],[69,15,"אַל־תִּשְׁטְפֵ֤⁠נִי ׀ שִׁבֹּ֣לֶת מַ֭יִם וְ⁠אַל־תִּבְלָעֵ֣⁠נִי מְצוּלָ֑ה וְ⁠אַל־תֶּאְטַר־עָלַ֖⁠י בְּאֵ֣ר פִּֽי⁠הָ׃","ʼal-ţi̇şĕ̌tĕpé֤⁠niy ׀ şǐbò֣̇leţ ma֭yim wĕ⁠ʼal-ţi̇bĕláʻé֣⁠niy mĕẕẇlá֑h wĕ⁠ʼal-ţėʼĕtar-ʻála֖⁠y bĕ̇ʼé֣r piֽ̇y⁠há׃"],[69,16,"עֲנֵ֣⁠נִי יְ֭הוָה כִּי־ט֣וֹב חַסְדֶּ֑⁠ךָ כְּ⁠רֹ֥ב רַ֝חֲמֶ֗י⁠ךָ פְּנֵ֣ה אֵלָֽ⁠י׃","ʻàné֣⁠niy yĕ֭hwáh ki̇y-t֣wòb ẖasĕdė֑⁠ká kĕ̇⁠rò֥b ra֝ẖàme֗y⁠ká pĕ̇né֣h ʼéláֽ⁠y׃"],[69,17,"וְ⁠אַל־תַּסְתֵּ֣ר פָּ֭נֶי⁠ךָ מֵֽ⁠עַבְדֶּ֑⁠ךָ כִּֽי־צַר־לִ֝֗⁠י מַהֵ֥ר עֲנֵֽ⁠נִי׃","wĕ⁠ʼal-ţȧsĕţé֣̇r pá֭̇ney⁠ká méֽ⁠ʻabĕdė֑⁠ká kiֽ̇y-ẕar-li֝֗⁠y mahé֥r ʻànéֽ⁠niy׃"],[69,18,"קָרְבָ֣⁠ה אֶל־נַפְשִׁ֣⁠י גְאָלָ֑⁠הּ לְמַ֖עַן אֹיְבַ֣⁠י פְּדֵֽ⁠נִי׃","qárĕbá֣⁠h ʼel-napĕşǐ֣⁠y gĕʼálá֑⁠ḣ lĕma֖ʻan ʼòyĕba֣⁠y pĕ̇déֽ⁠niy׃"],[69,19,"אַתָּ֤ה יָדַ֗עְתָּ חֶרְפָּתִ֣⁠י וּ֭⁠בָשְׁתִּ⁠י וּ⁠כְלִמָּתִ֑⁠י נֶ֝גְדְּ⁠ךָ֗ כָּל־צוֹרְרָֽ⁠י׃","ʼaţá֤̇h yáda֗ʻĕţá̇ ẖerĕpá̇ţi֣⁠y ẇ֭⁠báşĕ̌ţi̇⁠y ẇ⁠kĕlimá̇ţi֑⁠y ne֝gĕdĕ̇⁠ká֗ ká̇l-ẕwòrĕráֽ⁠y׃"],[69,20,"חֶרְפָּ֤ה ׀ שָֽׁבְרָ֥ה לִבִּ֗⁠י וָֽ⁠אָ֫נ֥וּשָׁ⁠ה וָ⁠אֲקַוֶּ֣ה לָ⁠נ֣וּד וָ⁠אַ֑יִן וְ֝⁠לַ⁠מְנַחֲמִ֗ים וְ⁠לֹ֣א מָצָֽאתִי׃","ẖerĕpá֤̇h ׀ şáֽ̌bĕrá֥h libi̇֗⁠y wáֽ⁠ʼá֫n֥ẇşá̌⁠h wá⁠ʼàqawė֣h lá⁠n֣ẇd wá⁠ʼa֑yin wĕ֝⁠la⁠mĕnaẖàmi֗ym wĕ⁠lò֣ʼ máẕáֽʼţiy׃"],[69,21,"וַ⁠יִּתְּנ֣וּ בְּ⁠בָרוּתִ֣⁠י רֹ֑אשׁ וְ֝⁠לִ⁠צְמָאִ֗⁠י יַשְׁק֥וּ⁠נִי חֹֽמֶץ׃","wa⁠yi̇ţĕ̇n֣ẇ bĕ̇⁠bárẇţi֣⁠y rò֑ʼş̌ wĕ֝⁠li⁠ẕĕmáʼi֗⁠y yaşĕ̌q֥ẇ⁠niy ẖòֽmeẕ׃"],[69,22,"יְהִֽי־שֻׁלְחָנָ֣⁠ם לִ⁠פְנֵי⁠הֶ֣ם לְ⁠פָ֑ח וְ⁠לִ⁠שְׁלוֹמִ֥ים לְ⁠מוֹקֵֽשׁ׃","yĕhiֽy-şǔlĕẖáná֣⁠m li⁠pĕnéy⁠he֣m lĕ⁠pá֑ẖ wĕ⁠li⁠şĕ̌lwòmi֥ym lĕ⁠mwòqéֽş̌׃"],[69,23,"תֶּחְשַׁ֣כְנָה עֵ֭ינֵי⁠הֶם מֵ⁠רְא֑וֹת וּ֝⁠מָתְנֵ֗י⁠הֶם תָּמִ֥יד הַמְעַֽד׃","ţėẖĕşǎ֣kĕnáh ʻé֭ynéy⁠hem mé⁠rĕʼ֑wòţ ẇ֝⁠máţĕné֗y⁠hem ţá̇mi֥yd hamĕʻaֽd׃"],[69,24,"שְׁפָךְ־עֲלֵי⁠הֶ֥ם זַעְמֶ֑⁠ךָ וַ⁠חֲר֥וֹן אַ֝פְּ⁠ךָ֗ יַשִּׂיגֵֽ⁠ם׃","şĕ̌pákĕ-ʻàléy⁠he֥m zaʻĕme֑⁠ká wa⁠ẖàr֥wòn ʼa֝pĕ̇⁠ká֗ yaşi̇̂ygéֽ⁠m׃"],[69,25,"תְּהִי־טִֽירָתָ֥⁠ם נְשַׁמָּ֑ה בְּ֝⁠אָהֳלֵי⁠הֶ֗ם אַל־יְהִ֥י יֹשֵֽׁב׃","ţĕ̇hiy-tiֽyráţá֥⁠m nĕşǎmá֑̇h bĕ̇֝⁠ʼáholéy⁠he֗m ʼal-yĕhi֥y yòşéֽ̌b׃"],[69,26,"כִּֽי־אַתָּ֣ה אֲשֶׁר־הִכִּ֣יתָ רָדָ֑פוּ וְ⁠אֶל־מַכְא֖וֹב חֲלָלֶ֣י⁠ךָ יְסַפֵּֽרוּ׃","kiֽ̇y-ʼaţá֣̇h ʼàşěr-hiki֣̇yţá rádá֑pẇ wĕ⁠ʼel-makĕʼ֖wòb ẖàlále֣y⁠ká yĕsapéֽ̇rẇ׃"],[69,27,"תְּֽנָ⁠ה־עָ֭וֺן עַל־עֲוֺנָ֑⁠ם וְ⁠אַל־יָ֝בֹ֗אוּ בְּ⁠צִדְקָתֶֽ⁠ךָ׃","ţĕֽ̇ná⁠h-ʻá֭wֺn ʻal-ʻàwֺná֑⁠m wĕ⁠ʼal-yá֝bò֗ʼẇ bĕ̇⁠ẕidĕqáţeֽ⁠ká׃"],[69,28,"יִ֭מָּחֽוּ מִ⁠סֵּ֣פֶר חַיִּ֑ים וְ⁠עִ֥ם צַ֝דִּיקִ֗ים אַל־יִכָּתֵֽבוּ׃","yi֭má̇ẖֽẇ mi⁠sé֣̇per ẖayi֑̇ym wĕ⁠ʻi֥m ẕa֝di̇yqi֗ym ʼal-yiká̇ţéֽbẇ׃"],[69,29,"וַ֭⁠אֲנִי עָנִ֣י וְ⁠כוֹאֵ֑ב יְשׁוּעָתְ⁠ךָ֖ אֱלֹהִ֣ים תְּשַׂגְּבֵֽ⁠נִי׃","wa֭⁠ʼàniy ʻáni֣y wĕ⁠kwòʼé֑b yĕş̌ẇʻáţĕ⁠ká֖ ʼèlòhi֣ym ţĕ̇şâgĕ̇béֽ⁠niy׃"],[69,30,"אֲהַֽלְלָ֣ה שֵׁם־אֱלֹהִ֣ים בְּ⁠שִׁ֑יר וַ⁠אֲגַדְּלֶ֥⁠נּוּ בְ⁠תוֹדָֽה׃","ʼàhaֽlĕlá֣h şé̌m-ʼèlòhi֣ym bĕ̇⁠şǐ֑yr wa⁠ʼàgadĕ̇le֥⁠ṅẇ bĕ⁠ţwòdáֽh׃"],[69,31,"וְ⁠תִיטַ֣ב לַֽ֭⁠יהוָה מִ⁠שּׁ֥וֹר פָּ֗ר מַקְרִ֥ן מַפְרִֽיס׃","wĕ⁠ţiyta֣b laֽ֭⁠yhwáh mi⁠ş֥̇̌wòr pá̇֗r maqĕri֥n mapĕriֽys׃"],[69,32,"רָא֣וּ עֲנָוִ֣ים יִשְׂמָ֑חוּ דֹּרְשֵׁ֥י אֱ֝לֹהִ֗ים וִ⁠יחִ֥י לְבַבְ⁠כֶֽם׃","ráʼ֣ẇ ʻànáwi֣ym yişĕ̂má֑ẖẇ dò̇rĕşé֥̌y ʼè֝lòhi֗ym wi⁠yẖi֥y lĕbabĕ⁠keֽm׃"],[69,33,"כִּֽי־שֹׁמֵ֣עַ אֶל־אֶבְיוֹנִ֣ים יְהוָ֑ה וְ⁠אֶת־אֲ֝סִירָ֗י⁠ו לֹ֣א בָזָֽה׃","kiֽ̇y-şò̌mé֣ʻa ʼel-ʼebĕywòni֣ym yĕhwá֑h wĕ⁠ʼeţ-ʼà֝siyrá֗y⁠w lò֣ʼ bázáֽh׃"],[69,34,"יְֽ֭הַלְלוּ⁠הוּ שָׁמַ֣יִם וָ⁠אָ֑רֶץ יַ֝מִּ֗ים וְֽ⁠כָל־רֹמֵ֥שׂ בָּֽ⁠ם׃","yĕֽ֭halĕlẇ⁠hẇ şá̌ma֣yim wá⁠ʼá֑reẕ ya֝mi̇֗ym wĕֽ⁠kál-ròmé֥ş̂ báֽ̇⁠m׃"],[69,35,"כִּ֤י אֱלֹהִ֨ים ׀ י֘וֹשִׁ֤יעַ צִיּ֗וֹן וְ֭⁠יִבְנֶה עָרֵ֣י יְהוּדָ֑ה וְ⁠יָ֥שְׁבוּ שָׁ֝֗ם וִ⁠ירֵשֽׁוּ⁠הָ׃","ki֤̇y ʼèlòhi֨ym ׀ y֘wòşǐ֤yʻa ẕiẏ֗wòn wĕ֭⁠yibĕneh ʻáré֣y yĕhẇdá֑h wĕ⁠yá֥şĕ̌bẇ şá̌֝֗m wi⁠yréşֽ̌ẇ⁠há׃"],[69,36,"וְ⁠זֶ֣רַע עֲ֭בָדָי⁠ו יִנְחָל֑וּ⁠הָ וְ⁠אֹהֲבֵ֥י שְׁ֝מ֗⁠וֹ יִשְׁכְּנוּ־בָֽ⁠הּ׃","wĕ⁠ze֣raʻ ʻà֭bádáy⁠w yinĕẖál֑ẇ⁠há wĕ⁠ʼòhàbé֥y şĕ̌֝m֗⁠wò yişĕ̌kĕ̇nẇ-báֽ⁠ḣ׃"],[70,1,"אֱלֹהִ֥ים לְ⁠הַצִּילֵ֑⁠נִי יְ֝הוָ֗ה לְ⁠עֶזְרָ֥תִ⁠י חֽוּשָֽׁ⁠ה׃","ʼèlòhi֥ym lĕ⁠haẕi̇ylé֑⁠niy yĕ֝hwá֗h lĕ⁠ʻezĕrá֥ţi⁠y ẖֽẇşáֽ̌⁠h׃"],[70,2,"יֵבֹ֣שׁוּ וְ⁠יַחְפְּרוּ֮ מְבַקְשֵׁ֪י נַ֫פְשִׁ֥⁠י יִסֹּ֣גוּ אָ֭חוֹר וְ⁠יִכָּלְמ֑וּ חֲ֝פֵצֵ֗י רָעָתִֽ⁠י׃","yébò֣ş̌ẇ wĕ⁠yaẖĕpĕ̇rẇ֮ mĕbaqĕşé֪̌y na֫pĕşǐ֥⁠y yisò֣̇gẇ ʼá֭ẖwòr wĕ⁠yiká̇lĕm֑ẇ ẖà֝péẕé֗y ráʻáţiֽ⁠y׃"],[70,3,"יָ֭שׁוּבוּ עַל־עֵ֣קֶב בָּשְׁתָּ֑⁠ם הָ֝⁠אֹמְרִ֗ים הֶ֘אָ֥ח ׀ הֶאָֽח׃","yá֭ş̌ẇbẇ ʻal-ʻé֣qeb bá̇şĕ̌ţá֑̇⁠m há֝⁠ʼòmĕri֗ym he֘ʼá֥ẖ ׀ heʼáֽẖ׃"],[70,4,"יָ֘שִׂ֤ישׂוּ וְ⁠יִשְׂמְח֨וּ ׀ בְּ⁠ךָ֗ כָּֽל־מְבַ֫קְשֶׁ֥י⁠ךָ וְ⁠יֹאמְר֣וּ תָ֭מִיד יִגְדַּ֣ל אֱלֹהִ֑ים אֹ֝הֲבֵ֗י יְשׁוּעָתֶֽ⁠ךָ׃","yá֘şî֤yş̂ẇ wĕ⁠yişĕ̂mĕẖ֨ẇ ׀ bĕ̇⁠ká֗ káֽ̇l-mĕba֫qĕşě֥y⁠ká wĕ⁠yòʼmĕr֣ẇ ţá֭miyd yigĕdȧ֣l ʼèlòhi֑ym ʼò֝hàbé֗y yĕş̌ẇʻáţeֽ⁠ká׃"],[70,5,"וַ⁠אֲנִ֤י ׀ עָנִ֣י וְ⁠אֶבְיוֹן֮ אֱלֹהִ֪ים חֽוּשָׁ֫⁠ה־לִּ֥⁠י עֶזְרִ֣⁠י וּ⁠מְפַלְטִ֣⁠י אַ֑תָּה יְ֝הוָ֗ה אַל־תְּאַחַֽר׃","wa⁠ʼàni֤y ׀ ʻáni֣y wĕ⁠ʼebĕywòn֮ ʼèlòhi֪ym ẖֽẇşá̌֫⁠h-li֥̇⁠y ʻezĕri֣⁠y ẇ⁠mĕpalĕti֣⁠y ʼa֑ţá̇h yĕ֝hwá֗h ʼal-ţĕ̇ʼaẖaֽr׃"],[71,1,"בְּ⁠ךָֽ־יְהוָ֥ה חָסִ֑יתִי אַל־אֵב֥וֹשָׁה לְ⁠עוֹלָֽם׃","bĕ̇⁠káֽ-yĕhwá֥h ẖási֑yţiy ʼal-ʼéb֥wòşá̌h lĕ⁠ʻwòláֽm׃"],[71,2,"בְּ⁠צִדְקָתְ⁠ךָ֗ תַּצִּילֵ֥⁠נִי וּֽ⁠תְפַלְּטֵ֑⁠נִי הַטֵּֽה־אֵלַ֥⁠י אָ֝זְנְ⁠ךָ֗ וְ⁠הוֹשִׁיעֵֽ⁠נִי׃","bĕ̇⁠ẕidĕqáţĕ⁠ká֗ ţȧẕi̇ylé֥⁠niy ẇֽ⁠ţĕpalĕ̇té֑⁠niy hatéֽ̇h-ʼéla֥⁠y ʼá֝zĕnĕ⁠ká֗ wĕ⁠hwòşǐyʻéֽ⁠niy׃"],[71,3,"הֱיֵ֤ה לִ֨⁠י ׀ לְ⁠צ֥וּר מָע֡וֹן לָ⁠ב֗וֹא תָּמִ֗יד צִוִּ֥יתָ לְ⁠הוֹשִׁיעֵ֑⁠נִי כִּֽי־סַלְעִ֖⁠י וּ⁠מְצוּדָתִ֣⁠י אָֽתָּה׃","hèyé֤h li֨⁠y ׀ lĕ⁠ẕ֥ẇr máʻ֡wòn lá⁠b֗wòʼ ţá̇mi֗yd ẕiwi֥̇yţá lĕ⁠hwòşǐyʻé֑⁠niy kiֽ̇y-salĕʻi֖⁠y ẇ⁠mĕẕẇdáţi֣⁠y ʼáֽţá̇h׃"],[71,4,"אֱֽלֹהַ֗⁠י פַּ֭לְּטֵ⁠נִי מִ⁠יַּ֣ד רָשָׁ֑ע מִ⁠כַּ֖ף מְעַוֵּ֣ל וְ⁠חוֹמֵץ׃","ʼèֽlòha֗⁠y pȧ֭lĕ̇té⁠niy mi⁠yȧ֣d ráşá֑̌ʻ mi⁠kȧ֖p mĕʻawé֣̇l wĕ⁠ẖwòméẕ׃"],[71,5,"כִּֽי־אַתָּ֥ה תִקְוָתִ֑⁠י אֲדֹנָ֥⁠י יְ֝הוִ֗ה מִבְטַחִ֥⁠י מִ⁠נְּעוּרָֽ⁠י׃","kiֽ̇y-ʼaţá֥̇h ţiqĕwáţi֑⁠y ʼàdòná֥⁠y yĕ֝hwi֗h mibĕtaẖi֥⁠y mi⁠nĕ̇ʻẇráֽ⁠y׃"],[71,6,"עָלֶ֤י⁠ךָ ׀ נִסְמַ֬כְתִּי מִ⁠בֶּ֗טֶן מִ⁠מְּעֵ֣י אִ֭מִּ⁠י אַתָּ֣ה גוֹזִ֑⁠י בְּ⁠ךָ֖ תְהִלָּתִ֣⁠י תָמִֽיד׃","ʻále֤y⁠ká ׀ nisĕma֬kĕţi̇y mi⁠bė֗ten mi⁠mĕ̇ʻé֣y ʼi֭mi̇⁠y ʼaţá֣̇h gwòzi֑⁠y bĕ̇⁠ká֖ ţĕhilá̇ţi֣⁠y ţámiֽyd׃"],[71,7,"כְּ֭⁠מוֹפֵת הָיִ֣יתִי לְ⁠רַבִּ֑ים וְ֝⁠אַתָּ֗ה מַֽחֲסִ⁠י־עֹֽז׃","kĕ֭̇⁠mwòpéţ háyi֣yţiy lĕ⁠rabi֑̇ym wĕ֝⁠ʼaţá̇֗h maֽẖàsi⁠y-ʻòֽz׃"],[71,8,"יִמָּ֣לֵא פִ֭⁠י תְּהִלָּתֶ֑⁠ךָ כָּל־הַ֝⁠יּ֗וֹם תִּפְאַרְתֶּֽ⁠ךָ׃","yimá֣̇léʼ pi֭⁠y ţĕ̇hilá̇ţe֑⁠ká ká̇l-ha֝⁠ẏ֗wòm ţi̇pĕʼarĕţėֽ⁠ká׃"],[71,9,"אַֽל־תַּ֭שְׁלִיכֵ⁠נִי לְ⁠עֵ֣ת זִקְנָ֑ה כִּ⁠כְל֥וֹת כֹּ֝חִ֗⁠י אַֽל־תַּעַזְבֵֽ⁠נִי׃","ʼaֽl-ţȧ֭şĕ̌liyké⁠niy lĕ⁠ʻé֣ţ ziqĕná֑h ki̇⁠kĕl֥wòţ kò̇֝ẖi֗⁠y ʼֽal-ţȧʻazĕbéֽ⁠niy׃"],[71,10,"כִּֽי־אָמְר֣וּ אוֹיְבַ֣⁠י לִ֑⁠י וְ⁠שֹׁמְרֵ֥י נַ֝פְשִׁ֗⁠י נוֹעֲצ֥וּ יַחְדָּֽו׃","kiֽ̇y-ʼámĕr֣ẇ ʼwòyĕba֣⁠y li֑⁠y wĕ⁠şò̌mĕré֥y na֝pĕşǐ֗⁠y nwòʻàẕ֥ẇ yaẖĕdáֽ̇w׃"],[71,11,"לֵ֭⁠אמֹר אֱלֹהִ֣ים עֲזָב֑⁠וֹ רִֽדְפ֥וּ וְ֝⁠תִפְשׂ֗וּ⁠הוּ כִּי־אֵ֥ין מַצִּֽיל׃","lé֭⁠ʼmòr ʼèlòhi֣ym ʻàzáb֑⁠wò riֽdĕp֥ẇ wĕ֝⁠ţipĕş̂֗ẇ⁠hẇ ki̇y-ʼé֥yn maẕiֽ̇yl׃"],[71,12,"אֱ֭לֹהִים אַל־תִּרְחַ֣ק מִמֶּ֑⁠נִּי אֱ֝לֹהַ֗⁠י לְ⁠עֶזְרָ֥תִ⁠י חיש⁠ה׃","ʼè֭lòhiym ʼal-ţi̇rĕẖa֣q mimė֑⁠ni̇y ʼè֝lòha֗⁠y lĕ⁠ʻezĕrá֥ţi⁠y ẖyş⁠h׃"],[71,13,"יֵבֹ֣שׁוּ יִכְלוּ֮ שֹׂטְנֵ֪י נַ֫פְשִׁ֥⁠י יַֽעֲט֣וּ חֶ֭רְפָּה וּ⁠כְלִמָּ֑ה מְ֝בַקְשֵׁ֗י רָעָתִֽ⁠י׃","yébò֣ş̌ẇ yikĕlẇ֮ şò̂tĕné֪y na֫pĕşǐ֥⁠y yaֽʻàt֣ẇ ẖe֭rĕpá̇h ẇ⁠kĕlimá֑̇h mĕ֝baqĕşé̌֗y ráʻáţiֽ⁠y׃"],[71,14,"וַ֭⁠אֲנִי תָּמִ֣יד אֲיַחֵ֑ל וְ֝⁠הוֹסַפְתִּ֗י עַל־כָּל־תְּהִלָּתֶֽ⁠ךָ׃","wa֭⁠ʼàniy ţá̇mi֣yd ʼàyaẖé֑l wĕ֝⁠hwòsapĕţi̇֗y ʻal-ká̇l-ţĕ̇hilá̇ţeֽ⁠ká׃"],[71,15,"פִּ֤⁠י ׀ יְסַפֵּ֬ר צִדְקָתֶ֗⁠ךָ כָּל־הַ⁠יּ֥וֹם תְּשׁוּעָתֶ֑⁠ךָ כִּ֤י לֹ֖א יָדַ֣עְתִּי סְפֹרֽוֹת׃","pi֤̇⁠y ׀ yĕsapé̇֬r ẕidĕqáţe֗⁠ká ká̇l-ha⁠ẏ֥wòm ţĕ̇ş̌ẇʻáţe֑⁠ká ki֤̇y lò֖ʼ yáda֣ʻĕţi̇y sĕpòrֽwòţ׃"],[71,16,"אָב֗וֹא בִּ֭⁠גְבֻרוֹת אֲדֹנָ֣⁠י יְהוִ֑ה אַזְכִּ֖יר צִדְקָתְ⁠ךָ֣ לְ⁠בַדֶּֽ⁠ךָ׃","ʼáb֗wòʼ bi֭̇⁠gĕburwòţ ʼàdòná֣⁠y yĕhwi֑h ʼazĕki֖̇yr ẕidĕqáţĕ⁠ká֣ lĕ⁠badėֽ⁠ká׃"],[71,17,"אֱֽלֹהִ֗ים לִמַּדְתַּ֥⁠נִי מִ⁠נְּעוּרָ֑⁠י וְ⁠עַד־הֵ֝֗נָּה אַגִּ֥יד נִפְלְאוֹתֶֽי⁠ךָ׃","ʼèֽlòhi֗ym limȧdĕţȧ֥⁠niy mi⁠nĕ̇ʻẇrá֑⁠y wĕ⁠ʻad-hé֝֗ná̇h ʼagi֥̇yd nipĕlĕʼwòţeֽy⁠ká׃"],[71,18,"וְ⁠גַ֤ם עַד־זִקְנָ֨ה ׀ וְ⁠שֵׂיבָה֮ אֱלֹהִ֪ים אַֽל־תַּעַ֫זְבֵ֥⁠נִי עַד־אַגִּ֣יד זְרוֹעֲ⁠ךָ֣ לְ⁠ד֑וֹר לְ⁠כָל־יָ֝ב֗וֹא גְּבוּרָתֶֽ⁠ךָ׃","wĕ⁠ga֤m ʻad-ziqĕná֨h ׀ wĕ⁠şé̂ybáh֮ ʼèlòhi֪ym ʼaֽl-ţȧʻa֫zĕbé֥⁠niy ʻad-ʼagi֣̇yd zĕrwòʻà⁠ká֣ lĕ⁠d֑wòr lĕ⁠kál-yá֝b֗wòʼ gĕ̇bẇráţeֽ⁠ká׃"],[71,19,"וְ⁠צִדְקָתְ⁠ךָ֥ אֱלֹהִ֗ים עַד־מָ֫ר֥וֹם אֲשֶׁר־עָשִׂ֥יתָ גְדֹל֑וֹת אֱ֝לֹהִ֗ים מִ֣י כָמֽוֹ⁠ךָ׃","wĕ⁠ẕidĕqáţĕ⁠ká֥ ʼèlòhi֗ym ʻad-má֫r֥wòm ʼàşěr-ʻáşî֥yţá gĕdòl֑wòţ ʼè֝lòhi֗ym mi֣y kámֽwò⁠ká׃"],[71,20,"אֲשֶׁ֤ר הראית⁠נו ׀ צָר֥וֹת רַבּ֗וֹת וְ⁠רָ֫ע֥וֹת תָּשׁ֥וּב תחיי⁠נו וּֽ⁠מִ⁠תְּהֹמ֥וֹת הָ֝⁠אָ֗רֶץ תָּשׁ֥וּב תַּעֲלֵֽ⁠נִי׃","ʼàşě֤r hrʼyţ⁠nw ׀ ẕár֥wòţ raḃ֗wòţ wĕ⁠rá֫ʻ֥wòţ ţá̇ş֥̌ẇb ţẖyy⁠nw ẇֽ⁠mi⁠ţĕ̇hòm֥wòţ há֝⁠ʼá֗reẕ ţá̇ş֥̌ẇb ţȧʻàléֽ⁠niy׃"],[71,21,"תֶּ֤רֶב ׀ גְּֽדֻלָּתִ֗⁠י וְ⁠תִסֹּ֥ב תְּֽנַחֲמֵֽ⁠נִי׃","ţė֤reb ׀ gĕֽ̇dulá̇ţi֗⁠y wĕ⁠ţisò֥̇b ţĕֽ̇naẖàméֽ⁠niy׃"],[71,22,"גַּם־אֲנִ֤י ׀ אוֹדְ⁠ךָ֣ בִ⁠כְלִי־נֶבֶל֮ אֲמִתְּ⁠ךָ֪ אֱלֹ֫הָ֥⁠י אֲזַמְּרָ֣ה לְ⁠ךָ֣ בְ⁠כִנּ֑וֹר קְ֝ד֗וֹשׁ יִשְׂרָאֵֽל׃","gȧm-ʼàni֤y ׀ ʼwòdĕ⁠ká֣ bi⁠kĕliy-nebel֮ ʼàmiţĕ̇⁠ká֪ ʼèlò֫há֥⁠y ʼàzamĕ̇rá֣h lĕ⁠ká֣ bĕ⁠kiṅ֑wòr qĕ֝d֗wòş̌ yişĕ̂ráʼéֽl׃"],[71,23,"תְּרַנֵּ֣נָּ֣ה שְׂ֭פָתַ⁠י כִּ֣י אֲזַמְּרָה־לָּ֑⁠ךְ וְ֝⁠נַפְשִׁ֗⁠י אֲשֶׁ֣ר פָּדִֽיתָ׃","ţĕ̇rané֣̇ná֣̇h şĕ֭̂páţa⁠y ki֣̇y ʼàzamĕ̇ráh-lá֑̇⁠kĕ wĕ֝⁠napĕşǐ֗⁠y ʼàşě֣r pá̇diֽyţá׃"],[71,24,"גַּם־לְשׁוֹנִ֗⁠י כָּל־הַ֭⁠יּוֹם תֶּהְגֶּ֣ה צִדְקָתֶ֑⁠ךָ כִּי־בֹ֥שׁוּ כִֽי־חָ֝פְר֗וּ מְבַקְשֵׁ֥י רָעָתִֽ⁠י׃","gȧm-lĕş̌wòni֗⁠y ká̇l-ha֭⁠ẏwòm ţėhĕgė֣h ẕidĕqáţe֑⁠ká ki̇y-bò֥ş̌ẇ kiֽy-ẖá֝pĕr֗ẇ mĕbaqĕşé֥̌y ráʻáţiֽ⁠y׃"],[72,1,"לִ⁠שְׁלֹמֹ֨ה ׀ אֱֽלֹהִ֗ים מִ֭שְׁפָּטֶי⁠ךָ לְ⁠מֶ֣לֶךְ תֵּ֑ן וְ⁠צִדְקָתְ⁠ךָ֥ לְ⁠בֶן־מֶֽלֶךְ׃","li⁠şĕ̌lòmò֨h ׀ ʼèֽlòhi֗ym mi֭şĕ̌pá̇tey⁠ká lĕ⁠me֣lekĕ ţé֑̇n wĕ⁠ẕidĕqáţĕ⁠ká֥ lĕ⁠ben-meֽlekĕ׃"],[72,2,"יָדִ֣ין עַמְּ⁠ךָ֣ בְ⁠צֶ֑דֶק וַ⁠עֲנִיֶּ֥י⁠ךָ בְ⁠מִשְׁפָּֽט׃","yádi֣yn ʻamĕ̇⁠ká֣ bĕ⁠ẕe֑deq wa⁠ʻàniyė֥y⁠ká bĕ⁠mişĕ̌páֽ̇t׃"],[72,3,"יִשְׂא֤וּ הָרִ֓ים שָׁ֘ל֥וֹם לָ⁠עָ֑ם וּ֝⁠גְבָע֗וֹת בִּ⁠צְדָקָֽה׃","yişĕ̂ʼ֤ẇ hári֓ym şá̌֘l֥wòm lá⁠ʻá֑m ẇ֝⁠gĕbáʻ֗wòţ bi̇⁠ẕĕdáqáֽh׃"],[72,4,"יִשְׁפֹּ֤ט ׀ עֲֽנִיֵּי־עָ֗ם י֭וֹשִׁיעַ לִ⁠בְנֵ֣י אֶבְי֑וֹן וִֽ⁠ידַכֵּ֣א עוֹשֵֽׁק׃","yişĕ̌pò֤̇t ׀ ʻàֽniyé̇y-ʻá֗m y֭wòşǐyʻa li⁠bĕné֣y ʼebĕy֑wòn wiֽ⁠ydaké֣̇ʼ ʻwòşéֽ̌q׃"],[72,5,"יִֽירָא֥וּ⁠ךָ עִם־שָׁ֑מֶשׁ וְ⁠לִ⁠פְנֵ֥י יָ֝רֵ֗חַ דּ֣וֹר דּוֹרִֽים׃","yiֽyráʼ֥ẇ⁠ká ʻim-şá֑̌meş̌ wĕ⁠li⁠pĕné֥y yá֝ré֗ẖa ḋ֣wòr ḋwòriֽym׃"],[72,6,"יֵ֭רֵד כְּ⁠מָטָ֣ר עַל־גֵּ֑ז כִּ֝⁠רְבִיבִ֗ים זַרְזִ֥יף אָֽרֶץ׃","yé֭réd kĕ̇⁠mátá֣r ʻal-gé֑̇z ki̇֝⁠rĕbiybi֗ym zarĕzi֥yp ʼáֽreẕ׃"],[72,7,"יִֽפְרַח־בְּ⁠יָמָ֥י⁠ו צַדִּ֑יק וְ⁠רֹ֥ב שָׁ֝ל֗וֹם עַד־בְּלִ֥י יָרֵֽחַ׃","yiֽpĕraẖ-bĕ̇⁠yámá֥y⁠w ẕadi֑̇yq wĕ⁠rò֥b şá̌֝l֗wòm ʻad-bĕ̇li֥y yáréֽẖa׃"],[72,8,"וְ֭⁠יֵרְדְּ מִ⁠יָּ֣ם עַד־יָ֑ם וּ֝⁠מִ⁠נָּהָ֗ר עַד־אַפְסֵי־אָֽרֶץ׃","wĕ֭⁠yérĕdĕ̇ mi⁠yá֣̇m ʻad-yá֑m ẇ֝⁠mi⁠ná̇há֗r ʻad-ʼapĕséy-ʼáֽreẕ׃"],[72,9,"לְ֭⁠פָנָי⁠ו יִכְרְע֣וּ צִיִּ֑ים וְ֝⁠אֹיְבָ֗י⁠ו עָפָ֥ר יְלַחֵֽכוּ׃","lĕ֭⁠pánáy⁠w yikĕrĕʻ֣ẇ ẕiyi֑̇ym wĕ֝⁠ʼòyĕbá֗y⁠w ʻápá֥r yĕlaẖéֽkẇ׃"],[72,10,"מַלְכֵ֬י תַרְשִׁ֣ישׁ וְ֭⁠אִיִּים מִנְחָ֣ה יָשִׁ֑יבוּ מַלְכֵ֥י שְׁבָ֥א וּ֝⁠סְבָ֗א אֶשְׁכָּ֥ר יַקְרִֽיבוּ׃","malĕké֬y ţarĕşǐ֣yş̌ wĕ֭⁠ʼiyi̇ym minĕẖá֣h yáşǐ֑ybẇ malĕké֥y şĕ̌bá֥ʼ ẇ֝⁠sĕbá֗ʼ ʼeşĕ̌ká֥̇r yaqĕriֽybẇ׃"],[72,11,"וְ⁠יִשְׁתַּחֲווּ־ל֥⁠וֹ כָל־מְלָכִ֑ים כָּל־גּוֹיִ֥ם יַֽעַבְדֽוּ⁠הוּ׃","wĕ⁠yişĕ̌ţȧẖàwẇ-l֥⁠wò kál-mĕláki֑ym ká̇l-ġwòyi֥m yaֽʻabĕdֽẇ⁠hẇ׃"],[72,12,"כִּֽי־יַ֭צִּיל אֶבְי֣וֹן מְשַׁוֵּ֑עַ וְ֝⁠עָנִ֗י וְֽ⁠אֵין־עֹזֵ֥ר לֽ⁠וֹ׃","kiֽ̇y-ya֭ẕi̇yl ʼebĕy֣wòn mĕşǎwé֑̇ʻa wĕ֝⁠ʻáni֗y wĕֽ⁠ʼéyn-ʻòzé֥r lֽ⁠wò׃"],[72,13,"יָ֭חֹס עַל־דַּ֣ל וְ⁠אֶבְי֑וֹן וְ⁠נַפְשׁ֖וֹת אֶבְיוֹנִ֣ים יוֹשִֽׁיעַ׃","yá֭ẖòs ʻal-dȧ֣l wĕ⁠ʼebĕy֑wòn wĕ⁠napĕş֖̌wòţ ʼebĕywòni֣ym ywòşǐֽyʻa׃"],[72,14,"מִ⁠תּ֣וֹךְ וּ֭⁠מֵ⁠חָמָס יִגְאַ֣ל נַפְשָׁ֑⁠ם וְ⁠יֵיקַ֖ר דָּמָ֣⁠ם בְּ⁠עֵינָֽי⁠ו׃","mi⁠ţ֣̇wòkĕ ẇ֭⁠mé⁠ẖámás yigĕʼa֣l napĕşá֑̌⁠m wĕ⁠yéyqa֖r dá̇má֣⁠m bĕ̇⁠ʻéynáֽy⁠w׃"],[72,15,"וִ⁠יחִ֗י וְ⁠יִתֶּן־ל⁠וֹ֮ מִ⁠זְּהַ֪ב שְׁ֫בָ֥א וְ⁠יִתְפַּלֵּ֣ל בַּעֲד֣⁠וֹ תָמִ֑יד כָּל־הַ֝⁠יּ֗וֹם יְבָרֲכֶֽ⁠נְהֽוּ׃","wi⁠yẖi֗y wĕ⁠yiţėn-l⁠wò֮ mi⁠zĕ̇ha֪b şĕ̌֫bá֥ʼ wĕ⁠yiţĕpȧlé֣̇l bȧʻàd֣⁠wò ţámi֑yd ká̇l-ha֝⁠ẏ֗wòm yĕbáràkeֽ⁠nĕhֽẇ׃"],[72,16,"יְהִ֤י פִסַּת־בַּ֨ר ׀ בָּ⁠אָרֶץ֮ בְּ⁠רֹ֪אשׁ הָ֫רִ֥ים יִרְעַ֣שׁ כַּ⁠לְּבָנ֣וֹן פִּרְי֑⁠וֹ וְ⁠יָצִ֥יצוּ מֵ֝⁠עִ֗יר כְּ⁠עֵ֣שֶׂב הָ⁠אָֽרֶץ׃","yĕhi֤y pisȧţ-bȧ֨r ׀ bá̇⁠ʼáreẕ֮ bĕ̇⁠rò֪ʼş̌ há֫ri֥ym yirĕʻa֣ş̌ kȧ⁠lĕ̇bán֣wòn pi̇rĕy֑⁠wò wĕ⁠yáẕi֥yẕẇ mé֝⁠ʻi֗yr kĕ̇⁠ʻé֣şêb há⁠ʼáֽreẕ׃"],[72,17,"יְהִ֤י שְׁמ֨⁠וֹ לְֽ⁠עוֹלָ֗ם לִ⁠פְנֵי־שֶׁמֶשׁ֮ ינין שְׁ֫מ֥⁠וֹ וְ⁠יִתְבָּ֥רְכוּ ב֑⁠וֹ כָּל־גּוֹיִ֥ם יְאַשְּׁרֽוּ⁠הוּ׃","yĕhi֤y şĕ̌m֨⁠wò lĕֽ⁠ʻwòlá֗m li⁠pĕnéy-şěmeş֮̌ ynyn şĕ̌֫m֥⁠wò wĕ⁠yiţĕbá֥̇rĕkẇ b֑⁠wò ká̇l-ġwòyi֥m yĕʼaşĕ̇̌rֽẇ⁠hẇ׃"],[72,18,"בָּר֤וּךְ ׀ יְהוָ֣ה אֱ֭לֹהִים אֱלֹהֵ֣י יִשְׂרָאֵ֑ל עֹשֵׂ֖ה נִפְלָא֣וֹת לְ⁠בַדּֽ⁠וֹ׃","bá̇r֤ẇkĕ ׀ yĕhwá֣h ʼè֭lòhiym ʼèlòhé֣y yişĕ̂ráʼé֑l ʻòşé֖̂h nipĕláʼ֣wòţ lĕ⁠baḋֽ⁠wò׃"],[72,19,"וּ⁠בָר֤וּךְ ׀ שֵׁ֥ם כְּבוֹד֗⁠וֹ לְ⁠ע֫וֹלָ֥ם וְ⁠יִמָּלֵ֣א כְ֭בוֹד⁠וֹ אֶת־כֹּ֥ל הָ⁠אָ֗רֶץ אָ֘מֵ֥ן ׀ וְ⁠אָמֵֽן׃","ẇ⁠bár֤ẇkĕ ׀ şé֥̌m kĕ̇bwòd֗⁠wò lĕ⁠ʻ֫wòlá֥m wĕ⁠yimá̇lé֣ʼ kĕ֭bwòd⁠wò ʼeţ-kò֥̇l há⁠ʼá֗reẕ ʼá֘mé֥n ׀ wĕ⁠ʼáméֽn׃"],[72,20,"כָּלּ֥וּ תְפִלּ֑וֹת דָּ֝וִ֗ד בֶּן־יִשָֽׁי׃","ká̇l֥̇ẇ ţĕpil֑̇wòţ dá̇֝wi֗d bėn-yişáֽ̌y׃"],[73,1,"מִזְמ֗וֹר לְ⁠אָ֫סָ֥ף אַ֤ךְ ט֭וֹב לְ⁠יִשְׂרָאֵ֥ל אֱלֹהִ֗ים לְ⁠בָרֵ֥י לֵבָֽב׃","mizĕm֗wòr lĕ⁠ʼá֫sá֥p ʼa֤kĕ t֭wòb lĕ⁠yişĕ̂ráʼé֥l ʼèlòhi֗ym lĕ⁠báré֥y lébáֽb׃"],[73,2,"וַ⁠אֲנִ֗י כִּ֭⁠מְעַט נטוי רַגְלָ֑⁠י כְּ֝⁠אַ֗יִן שפכה אֲשֻׁרָֽ⁠י׃","wa⁠ʼàni֗y ki֭̇⁠mĕʻat ntwy ragĕlá֑⁠y kĕ̇֝⁠ʼa֗yin şpkh ʼàşǔráֽ⁠y׃"],[73,3,"כִּֽי־קִ֭נֵּאתִי בַּֽ⁠הוֹלְלִ֑ים שְׁל֖וֹם רְשָׁעִ֣ים אֶרְאֶֽה׃","kiֽ̇y-qi֭né̇ʼţiy bȧֽ⁠hwòlĕli֑ym şĕ̌l֖wòm rĕşá̌ʻi֣ym ʼerĕʼeֽh׃"],[73,4,"כִּ֤י אֵ֖ין חַרְצֻבּ֥וֹת לְ⁠מוֹתָ֗⁠ם וּ⁠בָרִ֥יא אוּלָֽ⁠ם׃","ki֤̇y ʼé֖yn ẖarĕẕuḃ֥wòţ lĕ⁠mwòţá֗⁠m ẇ⁠bári֥yʼ ʼẇláֽ⁠m׃"],[73,5,"בַּ⁠עֲמַ֣ל אֱנ֣וֹשׁ אֵינֵ֑⁠מוֹ וְ⁠עִם־אָ֝דָ֗ם לֹ֣א יְנֻגָּֽעוּ׃","bȧ⁠ʻàma֣l ʼèn֣wòş̌ ʼéyné֑⁠mwò wĕ⁠ʻim-ʼá֝dá֗m lò֣ʼ yĕnugáֽ̇ʻẇ׃"],[73,6,"לָ֭⁠כֵן עֲנָקַ֣תְ⁠מוֹ גַאֲוָ֑ה יַעֲטָף־שִׁ֝֗ית חָמָ֥ס לָֽ⁠מוֹ׃","lá֭⁠kén ʻànáqa֣ţĕ⁠mwò gaʼàwá֑h yaʻàtáp-şǐ֝֗yţ ẖámá֥s láֽ⁠mwò׃"],[73,7,"יָ֭צָא מֵ⁠חֵ֣לֶב עֵינֵ֑⁠מוֹ עָ֝בְר֗וּ מַשְׂכִּיּ֥וֹת לֵבָֽב׃","yá֭ẕáʼ mé⁠ẖé֣leb ʻéyné֑⁠mwò ʻá֝bĕr֗ẇ maşĕ̂ki̇ẏ֥wòţ lébáֽb׃"],[73,8,"יָמִ֤יקוּ ׀ וִ⁠ידַבְּר֣וּ בְ⁠רָ֣ע עֹ֑שֶׁק מִ⁠מָּר֥וֹם יְדַבֵּֽרוּ׃","yámi֤yqẇ ׀ wi⁠ydabĕ̇r֣ẇ bĕ⁠rá֣ʻ ʻò֑şěq mi⁠má̇r֥wòm yĕdabéֽ̇rẇ׃"],[73,9,"שַׁתּ֣וּ בַ⁠שָּׁמַ֣יִם פִּי⁠הֶ֑ם וּ֝⁠לְשׁוֹנָ֗⁠ם תִּֽהֲלַ֥ךְ בָּ⁠אָֽרֶץ׃","şǎţ֣̇ẇ ba⁠şá̇̌ma֣yim pi̇y⁠he֑m ẇ֝⁠lĕş̌wòná֗⁠m ţiֽ̇hàla֥kĕ bá̇⁠ʼáֽreẕ׃"],[73,10,"לָ⁠כֵ֤ן ׀ ישיב עַמּ֣⁠וֹ הֲלֹ֑ם וּ⁠מֵ֥י מָ֝לֵ֗א יִמָּ֥צוּ לָֽ⁠מוֹ׃","lá⁠ké֤n ׀ yşyb ʻaṁ֣⁠wò hàlò֑m ẇ⁠mé֥y má֝lé֗ʼ yimá֥̇ẕẇ láֽ⁠mwò׃"],[73,11,"וְֽ⁠אָמְר֗וּ אֵיכָ֥ה יָדַֽע־אֵ֑ל וְ⁠יֵ֖שׁ דֵּעָ֣ה בְ⁠עֶלְיֽוֹן׃","wĕֽ⁠ʼámĕr֗ẇ ʼéyká֥h yádaֽʻ-ʼé֑l wĕ⁠yé֖ş̌ dé̇ʻá֣h bĕ⁠ʻelĕyֽwòn׃"],[73,12,"הִנֵּה־אֵ֥לֶּה רְשָׁעִ֑ים וְ⁠שַׁלְוֵ֥י ע֝וֹלָ֗ם הִשְׂגּוּ־חָֽיִל׃","hiné̇h-ʼé֥lėh rĕşá̌ʻi֑ym wĕ⁠şǎlĕwé֥y ʻ֝wòlá֗m hişĕ̂ġẇ-ẖáֽyil׃"],[73,13,"אַךְ־רִ֭יק זִכִּ֣יתִי לְבָבִ֑⁠י וָ⁠אֶרְחַ֖ץ בְּ⁠נִקָּי֣וֹן כַּפָּֽ⁠י׃","ʼakĕ-ri֭yq ziki֣̇yţiy lĕbábi֑⁠y wá⁠ʼerĕẖa֖ẕ bĕ̇⁠niqá̇y֣wòn kȧpáֽ̇⁠y׃"],[73,14,"וָ⁠אֱהִ֣י נָ֭גוּעַ כָּל־הַ⁠יּ֑וֹם וְ֝⁠תוֹכַחְתִּ֗⁠י לַ⁠בְּקָרִֽים׃","wá⁠ʼèhi֣y ná֭gẇʻa ká̇l-ha⁠ẏ֑wòm wĕ֝⁠ţwòkaẖĕţi̇֗⁠y la⁠bĕ̇qáriֽym׃"],[73,15,"אִם־אָ֭מַרְתִּי אֲסַפְּרָ֥ה כְמ֑וֹ הִנֵּ֤ה ד֭וֹר בָּנֶ֣י⁠ךָ בָגָֽדְתִּי׃","ʼim-ʼá֭marĕţi̇y ʼàsapĕ̇rá֥h kĕm֑wò hiné֤̇h d֭wòr bá̇ne֣y⁠ká bágáֽdĕţi̇y׃"],[73,16,"וָֽ֭⁠אֲחַשְּׁבָ⁠ה לָ⁠דַ֣עַת זֹ֑את עָמָ֖ל היא בְ⁠עֵינָֽ⁠י׃","wáֽ֭⁠ʼàẖaşĕ̇̌bá⁠h lá⁠da֣ʻaţ zò֑ʼţ ʻámá֖l hyʼ bĕ⁠ʻéynáֽ⁠y׃"],[73,17,"עַד־אָ֭בוֹא אֶל־מִקְדְּשֵׁי־אֵ֑ל אָ֝בִ֗ינָה לְ⁠אַחֲרִיתָֽ⁠ם׃","ʻad-ʼá֭bwòʼ ʼel-miqĕdĕ̇şé̌y-ʼé֑l ʼá֝bi֗ynáh lĕ⁠ʼaẖàriyţáֽ⁠m׃"],[73,18,"אַ֣ךְ בַּ֭⁠חֲלָקוֹת תָּשִׁ֣ית לָ֑⁠מוֹ הִ֝פַּלְתָּ֗⁠ם לְ⁠מַשּׁוּאֽוֹת׃","ʼa֣kĕ bȧ֭⁠ẖàláqwòţ ţá̇şǐ֣yţ lá֑⁠mwò hi֝pȧlĕţá̇֗⁠m lĕ⁠maş̇̌ẇʼֽwòţ׃"],[73,19,"אֵ֤יךְ הָי֣וּ לְ⁠שַׁמָּ֣ה כְ⁠רָ֑גַע סָ֥פוּ תַ֝֗מּוּ מִן־בַּלָּהֽוֹת׃","ʼé֤ykĕ háy֣ẇ lĕ⁠şǎmá֣̇h kĕ⁠rá֑gaʻ sá֥pẇ ţa֝֗ṁẇ min-bȧlá̇hֽwòţ׃"],[73,20,"כַּ⁠חֲל֥וֹם מֵ⁠הָקִ֑יץ אֲ֝דֹנָ⁠י בָּ⁠עִ֤יר ׀ צַלְמָ֬⁠ם תִּבְזֶֽה׃","kȧ⁠ẖàl֥wòm mé⁠háqi֑yẕ ʼà֝dòná⁠y bá̇⁠ʻi֤yr ׀ ẕalĕmá֬⁠m ţi̇bĕzeֽh׃"],[73,21,"כִּ֭י יִתְחַמֵּ֣ץ לְבָבִ֑⁠י וְ֝⁠כִלְיוֹתַ֗⁠י אֶשְׁתּוֹנָֽן׃","ki֭̇y yiţĕẖamé֣̇ẕ lĕbábi֑⁠y wĕ֝⁠kilĕywòţa֗⁠y ʼeşĕ̌ţ̇wònáֽn׃"],[73,22,"וַ⁠אֲנִי־בַ֭עַר וְ⁠לֹ֣א אֵדָ֑ע בְּ֝הֵמ֗וֹת הָיִ֥יתִי עִמָּֽ⁠ךְ׃","wa⁠ʼàniy-ba֭ʻar wĕ⁠lò֣ʼ ʼédá֑ʻ bĕ̇֝hém֗wòţ háyi֥yţiy ʻimáֽ̇⁠kĕ׃"],[73,23,"וַ⁠אֲנִ֣י תָמִ֣יד עִמָּ֑⁠ךְ אָ֝חַ֗זְתָּ בְּ⁠יַד־יְמִינִֽ⁠י׃","wa⁠ʼàni֣y ţámi֣yd ʻimá֑̇⁠kĕ ʼá֝ẖa֗zĕţá̇ bĕ̇⁠yad-yĕmiyniֽ⁠y׃"],[73,24,"בַּ⁠עֲצָתְ⁠ךָ֥ תַנְחֵ֑⁠נִי וְ֝⁠אַחַ֗ר כָּב֥וֹד תִּקָּחֵֽ⁠נִי׃","bȧ⁠ʻàẕáţĕ⁠ká֥ ţanĕẖé֑⁠niy wĕ֝⁠ʼaẖa֗r ká̇b֥wòd ţi̇qá̇ẖéֽ⁠niy׃"],[73,25,"מִי־לִ֥⁠י בַ⁠שָּׁמָ֑יִם וְ֝⁠עִמְּ⁠ךָ֗ לֹא־חָפַ֥צְתִּי בָ⁠אָֽרֶץ׃","miy-li֥⁠y ba⁠şá̇̌má֑yim wĕ֝⁠ʻimĕ̇⁠ká֗ lòʼ-ẖápa֥ẕĕţi̇y bá⁠ʼáֽreẕ׃"],[73,26,"כָּלָ֥ה שְׁאֵרִ֗⁠י וּ⁠לְבָ֫בִ֥⁠י צוּר־לְבָבִ֥⁠י וְ⁠חֶלְקִ֗⁠י אֱלֹהִ֥ים לְ⁠עוֹלָֽם׃","ká̇lá֥h şĕ̌ʼéri֗⁠y ẇ⁠lĕbá֫bi֥⁠y ẕẇr-lĕbábi֥⁠y wĕ⁠ẖelĕqi֗⁠y ʼèlòhi֥ym lĕ⁠ʻwòláֽm׃"],[73,27,"כִּֽי־הִנֵּ֣ה רְחֵקֶ֣י⁠ךָ יֹאבֵ֑דוּ הִ֝צְמַ֗תָּה כָּל־זוֹנֶ֥ה מִמֶּֽ⁠ךָּ׃","kiֽ̇y-hiné֣̇h rĕẖéqe֣y⁠ká yòʼbé֑dẇ hi֝ẕĕma֗ţá̇h ká̇l-zwòne֥h mimėֽ⁠ká̇׃"],[73,28,"וַ⁠אֲנִ֤י ׀ קִֽרֲבַ֥ת אֱלֹהִ֗ים לִ֫⁠י־ט֥וֹב שַׁתִּ֤י ׀ בַּ⁠אדֹנָ֣⁠י יְהֹוִ֣ה מַחְסִ֑⁠י לְ֝⁠סַפֵּ֗ר כָּל־מַלְאֲכוֹתֶֽי⁠ךָ׃","wa⁠ʼàni֤y ׀ qiֽràba֥ţ ʼèlòhi֗ym li֫⁠y-t֥wòb şǎţi֤̇y ׀ bȧ⁠ʼdòná֣⁠y yĕhòwi֣h maẖĕsi֑⁠y lĕ֝⁠sapé̇֗r ká̇l-malĕʼàkwòţeֽy⁠ká׃"],[74,1,"מַשְׂכִּ֗יל לְ⁠אָ֫סָ֥ף לָ⁠מָ֣ה אֱ֭לֹהִים זָנַ֣חְתָּ לָ⁠נֶ֑צַח יֶעְשַׁ֥ן אַ֝פְּ⁠ךָ֗ בְּ⁠צֹ֣אן מַרְעִיתֶֽ⁠ךָ׃","maşĕ̂ki̇֗yl lĕ⁠ʼá֫sá֥p lá⁠má֣h ʼè֭lòhiym zána֣ẖĕţá̇ lá⁠ne֑ẕaẖ yeʻĕşǎ֥n ʼa֝pĕ̇⁠ká֗ bĕ̇⁠ẕò֣ʼn marĕʻiyţeֽ⁠ká׃"],[74,2,"זְכֹ֤ר עֲדָתְ⁠ךָ֨ ׀ קָ֘נִ֤יתָ קֶּ֗דֶם גָּ֭אַלְתָּ שֵׁ֣בֶט נַחֲלָתֶ֑⁠ךָ הַר־צִ֝יּ֗וֹן זֶ֤ה ׀ שָׁכַ֬נְתָּ בּֽ⁠וֹ׃","zĕkò֤r ʻàdáţĕ⁠ká֨ ׀ qá֘ni֤yţá qė֗dem gá֭̇ʼalĕţá̇ şé֣̌bet naẖàláţe֑⁠ká har-ẕi֝ẏ֗wòn ze֤h ׀ şá̌ka֬nĕţá̇ ḃֽ⁠wò׃"],[74,3,"הָרִ֣ימָ⁠ה פְ֭עָמֶי⁠ךָ לְ⁠מַשֻּׁא֣וֹת נֶ֑צַח כָּל־הֵרַ֖ע אוֹיֵ֣ב בַּ⁠קֹּֽדֶשׁ׃","hári֣ymá⁠h pĕ֭ʻámey⁠ká lĕ⁠maşu̇̌ʼ֣wòţ ne֑ẕaẖ ká̇l-héra֖ʻ ʼwòyé֣b bȧ⁠qòֽ̇deş̌׃"],[74,4,"שָׁאֲג֣וּ צֹ֭רְרֶי⁠ךָ בְּ⁠קֶ֣רֶב מוֹעֲדֶ֑⁠ךָ שָׂ֖מוּ אוֹתֹתָ֣⁠ם אֹתֽוֹת׃","şá̌ʼàg֣ẇ ẕò֭rĕrey⁠ká bĕ̇⁠qe֣reb mwòʻàde֑⁠ká şá֖̂mẇ ʼwòţòţá֣⁠m ʼòţֽwòţ׃"],[74,5,"יִ֭וָּדַע כְּ⁠מֵבִ֣יא לְ⁠מָ֑עְלָ⁠ה בִּֽ⁠סֲבָךְ־עֵ֝֗ץ קַרְדֻּמּֽוֹת׃","yi֭wá̇daʻ kĕ̇⁠mébi֣yʼ lĕ⁠má֑ʻĕlá⁠h biֽ̇⁠sàbákĕ-ʻé֝֗ẕ qarĕdu̇ṁֽwòţ׃"],[74,6,"ו⁠עת פִּתּוּחֶ֣י⁠הָ יָּ֑חַד בְּ⁠כַשִּׁ֥יל וְ֝⁠כֵֽילַפֹּ֗ת יַהֲלֹמֽוּ⁠ן׃","w⁠ʻţ pi̇ţ̇ẇẖe֣y⁠há yá֑̇ẖad bĕ̇⁠kaşi֥̇̌yl wĕ֝⁠kéֽylapò̇֗ţ yahàlòmֽẇ⁠n׃"],[74,7,"שִׁלְח֣וּ בָ֭⁠אֵשׁ מִקְדָּשֶׁ֑⁠ךָ לָ֝⁠אָ֗רֶץ חִלְּל֥וּ מִֽשְׁכַּן־שְׁמֶֽ⁠ךָ׃","şǐlĕẖ֣ẇ bá֭⁠ʼéş̌ miqĕdá̇şě֑⁠ká lá֝⁠ʼá֗reẕ ẖilĕ̇l֥ẇ miֽşĕ̌kȧn-şĕ̌meֽ⁠ká׃"],[74,8,"אָמְר֣וּ בְ֭⁠לִבָּ⁠ם נִינָ֣⁠ם יָ֑חַד שָׂרְפ֖וּ כָל־מוֹעֲדֵי־אֵ֣ל בָּ⁠אָֽרֶץ׃","ʼámĕr֣ẇ bĕ֭⁠libá̇⁠m niyná֣⁠m yá֑ẖad şá̂rĕp֖ẇ kál-mwòʻàdéy-ʼé֣l bá̇⁠ʼáֽreẕ׃"],[74,9,"אֽוֹתֹתֵ֗י⁠נוּ לֹ֥א רָ֫אִ֥ינוּ אֵֽין־ע֥וֹד נָבִ֑יא וְ⁠לֹֽא־אִ֝תָּ֗⁠נוּ יֹדֵ֥עַ עַד־מָֽה׃","ʼֽwòţòţé֗y⁠nẇ lò֥ʼ rá֫ʼi֥ynẇ ʼéֽyn-ʻ֥wòd nábi֑yʼ wĕ⁠lòֽʼ-ʼi֝ţá̇֗⁠nẇ yòdé֥ʻa ʻad-máֽh׃"],[74,10,"עַד־מָתַ֣י אֱ֭לֹהִים יְחָ֣רֶף צָ֑ר יְנָ֘אֵ֤ץ אוֹיֵ֖ב שִׁמְ⁠ךָ֣ לָ⁠נֶֽצַח׃","ʻad-máţa֣y ʼè֭lòhiym yĕẖá֣rep ẕá֑r yĕná֘ʼé֤ẕ ʼwòyé֖b şǐmĕ⁠ká֣ lá⁠neֽẕaẖ׃"],[74,11,"לָ֤⁠מָּה תָשִׁ֣יב יָ֭דְ⁠ךָ וִֽ⁠ימִינֶ֑⁠ךָ מִ⁠קֶּ֖רֶב חוק⁠ך כַלֵּֽה׃","lá֤⁠má̇h ţáşǐ֣yb yá֭dĕ⁠ká wiֽ⁠ymiyne֑⁠ká mi⁠qė֖reb ẖwq⁠k kaléֽ̇h׃"],[74,12,"וֵ֭⁠אלֹהִים מַלְכִּ֣⁠י מִ⁠קֶּ֑דֶם פֹּעֵ֥ל יְ֝שׁוּע֗וֹת בְּ⁠קֶ֣רֶב הָ⁠אָֽרֶץ׃","wé֭⁠ʼlòhiym malĕki֣̇⁠y mi⁠qė֑dem pò̇ʻé֥l yĕ֝ş̌ẇʻ֗wòţ bĕ̇⁠qe֣reb há⁠ʼáֽreẕ׃"],[74,13,"אַתָּ֤ה פוֹרַ֣רְתָּ בְ⁠עָזְּ⁠ךָ֣ יָ֑ם שִׁבַּ֖רְתָּ רָאשֵׁ֥י תַ֝נִּינִ֗ים עַל־הַ⁠מָּֽיִם׃","ʼaţá֤̇h pwòra֣rĕţá̇ bĕ⁠ʻázĕ̇⁠ká֣ yá֑m şǐbȧ֖rĕţá̇ ráʼşé֥̌y ţa֝ni̇yni֗ym ʻal-ha⁠máֽ̇yim׃"],[74,14,"אַתָּ֣ה רִ֭צַּצְתָּ רָאשֵׁ֣י לִוְיָתָ֑ן תִּתְּנֶ֥⁠נּוּ מַ֝אֲכָ֗ל לְ⁠עָ֣ם לְ⁠צִיִּֽים׃","ʼaţá֣̇h ri֭ẕȧẕĕţá̇ ráʼşé֣̌y liwĕyáţá֑n ţi̇ţĕ̇ne֥⁠ṅẇ ma֝ʼàká֗l lĕ⁠ʻá֣m lĕ⁠ẕiyiֽ̇ym׃"],[74,15,"אַתָּ֣ה בָ֭קַעְתָּ מַעְיָ֣ן וָ⁠נָ֑חַל אַתָּ֥ה ה֝וֹבַ֗שְׁתָּ נַהֲר֥וֹת אֵיתָֽן׃","ʼaţá֣̇h bá֭qaʻĕţá̇ maʻĕyá֣n wá⁠ná֑ẖal ʼaţá֥̇h h֝wòba֗şĕ̌ţá̇ nahàr֥wòţ ʼéyţáֽn׃"],[74,16,"לְ⁠ךָ֣ י֭וֹם אַף־לְ⁠ךָ֥ לָ֑יְלָה אַתָּ֥ה הֲ֝כִינ֗וֹתָ מָא֥וֹר וָ⁠שָֽׁמֶשׁ׃","lĕ⁠ká֣ y֭wòm ʼap-lĕ⁠ká֥ lá֑yĕláh ʼaţá֥̇h hà֝kiyn֗wòţá máʼ֥wòr wá⁠şáֽ̌meş̌׃"],[74,17,"אַתָּ֣ה הִ֭צַּבְתָּ כָּל־גְּבוּל֣וֹת אָ֑רֶץ קַ֥יִץ וָ֝⁠חֹ֗רֶף אַתָּ֥ה יְצַרְתָּ⁠ם׃","ʼaţá֣̇h hi֭ẕȧbĕţá̇ ká̇l-gĕ̇bẇl֣wòţ ʼá֑reẕ qa֥yiẕ wá֝⁠ẖò֗rep ʼaţá֥̇h yĕẕarĕţá̇⁠m׃"],[74,18,"זְכָר־זֹ֗את א֭וֹיֵב חֵרֵ֣ף ׀ יְהוָ֑ה וְ⁠עַ֥ם נָ֝בָ֗ל נִֽאֲצ֥וּ שְׁמֶֽ⁠ךָ׃","zĕkár-zò֗ʼţ ʼ֭wòyéb ẖéré֣p ׀ yĕhwá֑h wĕ⁠ʻa֥m ná֝bá֗l niֽʼàẕ֥ẇ şĕ̌meֽ⁠ká׃"],[74,19,"אַל־תִּתֵּ֣ן לְ֭⁠חַיַּת נֶ֣פֶשׁ תּוֹרֶ֑⁠ךָ חַיַּ֥ת עֲ֝נִיֶּ֗י⁠ךָ אַל־תִּשְׁכַּ֥ח לָ⁠נֶֽצַח׃","ʼal-ţi̇ţé֣̇n lĕ֭⁠ẖayȧţ ne֣peş̌ ţ̇wòre֑⁠ká ẖayȧ֥ţ ʻà֝niyė֗y⁠ká ʼal-ţi̇şĕ̌kȧ֥ẖ lá⁠neֽẕaẖ׃"],[74,20,"הַבֵּ֥ט לַ⁠בְּרִ֑ית כִּ֥י מָלְא֥וּ מַחֲשַׁכֵּי־אֶ֝֗רֶץ נְא֣וֹת חָמָֽס׃","habé֥̇t la⁠bĕ̇ri֑yţ ki֥̇y málĕʼ֥ẇ maẖàşǎké̇y-ʼe֝֗reẕ nĕʼ֣wòţ ẖámáֽs׃"],[74,21,"אַל־יָשֹׁ֣ב דַּ֣ךְ נִכְלָ֑ם עָנִ֥י וְ֝⁠אֶבְי֗וֹן יְֽהַלְל֥וּ שְׁמֶֽ⁠ךָ׃","ʼal-yáşò֣̌b dȧ֣kĕ nikĕlá֑m ʻáni֥y wĕ֝⁠ʼebĕy֗wòn yĕֽhalĕl֥ẇ şĕ̌meֽ⁠ká׃"],[74,22,"קוּמָ֣⁠ה אֱ֭לֹהִים רִיבָ֣⁠ה רִיבֶ֑⁠ךָ זְכֹ֥ר חֶרְפָּתְ⁠ךָ֥ מִנִּי־נָ֝בָ֗ל כָּל־הַ⁠יּֽוֹם׃","qẇmá֣⁠h ʼè֭lòhiym riybá֣⁠h riybe֑⁠ká zĕkò֥r ẖerĕpá̇ţĕ⁠ká֥ mini̇y-ná֝bá֗l ká̇l-ha⁠ẏֽwòm׃"],[74,23,"אַל־תִּ֭שְׁכַּח ק֣וֹל צֹרְרֶ֑י⁠ךָ שְׁא֥וֹן קָ֝מֶ֗י⁠ךָ עֹלֶ֥ה תָמִֽיד׃","ʼal-ţi֭̇şĕ̌kȧẖ q֣wòl ẕòrĕre֑y⁠ká şĕ̌ʼ֥wòn qá֝me֗y⁠ká ʻòle֥h ţámiֽyd׃"],[75,1,"ה֘וֹדִ֤ינוּ לְּ⁠ךָ֨ ׀ אֱֽלֹהִ֗ים ה֭וֹדִינוּ וְ⁠קָר֣וֹב שְׁמֶ֑⁠ךָ סִ֝פְּר֗וּ נִפְלְאוֹתֶֽי⁠ךָ׃","h֘wòdi֤ynẇ lĕ̇⁠ká֨ ׀ ʼèֽlòhi֗ym h֭wòdiynẇ wĕ⁠qár֣wòb şĕ̌me֑⁠ká si֝pĕ̇r֗ẇ nipĕlĕʼwòţeֽy⁠ká׃"],[75,2,"כִּ֭י אֶקַּ֣ח מוֹעֵ֑ד אֲ֝נִ֗י מֵישָׁרִ֥ים אֶשְׁפֹּֽט׃","ki֭̇y ʼeqȧ֣ẖ mwòʻé֑d ʼà֝ni֗y méyşá̌ri֥ym ʼeşĕ̌pòֽ̇t׃"],[75,3,"נְֽמֹגִ֗ים אֶ֥רֶץ וְ⁠כָל־יֹשְׁבֶ֑י⁠הָ אָנֹכִ֨י תִכַּ֖נְתִּי עַמּוּדֶ֣י⁠הָ סֶּֽלָה׃","nĕֽmògi֗ym ʼe֥reẕ wĕ⁠kál-yòşĕ̌be֑y⁠há ʼánòki֨y ţikȧ֖nĕţi̇y ʻaṁẇde֣y⁠há sėֽláh׃"],[75,4,"אָמַ֣רְתִּי לַֽ֭⁠הוֹלְלִים אַל־תָּהֹ֑לּוּ וְ֝⁠לָ⁠רְשָׁעִ֗ים אַל־תָּרִ֥ימוּ קָֽרֶן׃","ʼáma֣rĕţi̇y laֽ֭⁠hwòlĕliym ʼal-ţá̇hò֑l̇ẇ wĕ֝⁠lá⁠rĕşá̌ʻi֗ym ʼal-ţá̇ri֥ymẇ qáֽren׃"],[75,5,"אַל־תָּרִ֣ימוּ לַ⁠מָּר֣וֹם קַרְנְ⁠כֶ֑ם תְּדַבְּר֖וּ בְ⁠צַוָּ֣אר עָתָֽק׃","ʼal-ţá̇ri֣ymẇ la⁠má̇r֣wòm qarĕnĕ⁠ke֑m ţĕ̇dabĕ̇r֖ẇ bĕ⁠ẕawá֣̇ʼr ʻáţáֽq׃"],[75,6,"כִּ֤י לֹ֣א מִ֭⁠מּוֹצָא וּ⁠מִֽ⁠מַּעֲרָ֑ב וְ֝⁠לֹ֗א מִ⁠מִּדְבַּ֥ר הָרִֽים׃","ki֤̇y lò֣ʼ mi֭⁠ṁwòẕáʼ ẇ⁠miֽ⁠mȧʻàrá֑b wĕ֝⁠lò֗ʼ mi⁠mi̇dĕbȧ֥r háriֽym׃"],[75,7,"כִּֽי־אֱלֹהִ֥ים שֹׁפֵ֑ט זֶ֥ה יַ֝שְׁפִּ֗יל וְ⁠זֶ֣ה יָרִֽים׃","kiֽ̇y-ʼèlòhi֥ym şò̌pé֑t ze֥h ya֝şĕ̌pi̇֗yl wĕ⁠ze֣h yáriֽym׃"],[75,8,"כִּ֤י כ֪וֹס בְּֽ⁠יַד־יְהוָ֡ה וְ⁠יַ֤יִן חָמַ֨ר ׀ מָ֥לֵא מֶסֶךְ֮ וַ⁠יַּגֵּ֪ר מִ֫⁠זֶּ֥ה אַךְ־שְׁ֭מָרֶי⁠הָ יִמְצ֣וּ יִשְׁתּ֑וּ כֹּ֝֗ל רִשְׁעֵי־אָֽרֶץ׃","ki֤̇y k֪wòs bĕֽ̇⁠yad-yĕhwá֡h wĕ⁠ya֤yin ẖáma֨r ׀ má֥léʼ mesekĕ֮ wa⁠yȧgé֪̇r mi֫⁠zė֥h ʼakĕ-şĕ֭̌márey⁠há yimĕẕ֣ẇ yişĕ̌ţ֑̇ẇ kò̇֝֗l rişĕ̌ʻéy-ʼáֽreẕ׃"],[75,9,"וַ֭⁠אֲנִי אַגִּ֣יד לְ⁠עֹלָ֑ם אֲ֝זַמְּרָ֗ה לֵ⁠אלֹהֵ֥י יַעֲקֹֽב׃","wa֭⁠ʼàniy ʼagi֣̇yd lĕ⁠ʻòlá֑m ʼà֝zamĕ̇rá֗h lé⁠ʼlòhé֥y yaʻàqòֽb׃"],[75,10,"וְ⁠כָל־קַרְנֵ֣י רְשָׁעִ֣ים אֲגַדֵּ֑עַ תְּ֝רוֹמַ֗מְנָה קַֽרְנ֥וֹת צַדִּֽיק׃","wĕ⁠kál-qarĕné֣y rĕşá̌ʻi֣ym ʼàgadé֑̇ʻa ţĕ̇֝rwòma֗mĕnáh qaֽrĕn֥wòţ ẕadiֽ̇yq׃"],[76,1,"נוֹדָ֣ע בִּֽ⁠יהוּדָ֣ה אֱלֹהִ֑ים בְּ֝⁠יִשְׂרָאֵ֗ל גָּד֥וֹל שְׁמֽ⁠וֹ׃","nwòdá֣ʻ biֽ̇⁠yhẇdá֣h ʼèlòhi֑ym bĕ̇֝⁠yişĕ̂ráʼé֗l gá̇d֥wòl şĕ̌mֽ⁠wò׃"],[76,2,"וַ⁠יְהִ֣י בְ⁠שָׁלֵ֣ם סֻכּ֑⁠וֹ וּ⁠מְע֖וֹנָת֣⁠וֹ בְ⁠צִיּֽוֹן׃","wa⁠yĕhi֣y bĕ⁠şá̌lé֣m suk֑̇⁠wò ẇ⁠mĕʻ֖wònáţ֣⁠wò bĕ⁠ẕiẏֽwòn׃"],[76,3,"שָׁ֭מָּ⁠ה שִׁבַּ֣ר רִשְׁפֵי־קָ֑שֶׁת מָגֵ֬ן וְ⁠חֶ֖רֶב וּ⁠מִלְחָמָ֣ה סֶֽלָה׃","şá֭̌má̇⁠h şǐbȧ֣r rişĕ̌péy-qá֑şěţ mágé֬n wĕ⁠ẖe֖reb ẇ⁠milĕẖámá֣h seֽláh׃"],[76,4,"נָ֭אוֹר אַתָּ֥ה אַדִּ֗יר מֵֽ⁠הַרְרֵי־טָֽרֶף׃","ná֭ʼwòr ʼaţá֥̇h ʼadi̇֗yr méֽ⁠harĕréy-táֽrep׃"],[76,5,"אֶשְׁתּוֹלְל֨וּ ׀ אַבִּ֣ירֵי לֵ֭ב נָמ֣וּ שְׁנָתָ֑⁠ם וְ⁠לֹא־מָצְא֖וּ כָל־אַנְשֵׁי־חַ֣יִל יְדֵי⁠הֶֽם׃","ʼeşĕ̌ţ̇wòlĕl֨ẇ ׀ ʼabi֣̇yréy lé֭b nám֣ẇ şĕ̌náţá֑⁠m wĕ⁠lòʼ-máẕĕʼ֖ẇ kál-ʼanĕşé̌y-ẖa֣yil yĕdéy⁠heֽm׃"],[76,6,"מִ֭⁠גַּעֲרָ֣תְ⁠ךָ אֱלֹהֵ֣י יַעֲקֹ֑ב נִ֝רְדָּ֗ם וְ⁠רֶ֣כֶב וָ⁠סֽוּס׃","mi֭⁠gȧʻàrá֣ţĕ⁠ká ʼèlòhé֣y yaʻàqò֑b ni֝rĕdá̇֗m wĕ⁠re֣keb wá⁠sֽẇs׃"],[76,7,"אַתָּ֤ה ׀ נ֥וֹרָא אַ֗תָּה וּ⁠מִֽי־יַעֲמֹ֥ד לְ⁠פָנֶ֗י⁠ךָ מֵ⁠אָ֥ז אַפֶּֽ⁠ךָ׃","ʼaţá֤̇h ׀ n֥wòráʼ ʼa֗ţá̇h ẇ⁠miֽy-yaʻàmò֥d lĕ⁠páne֗y⁠ká mé⁠ʼá֥z ʼapėֽ⁠ká׃"],[76,8,"מִ֭⁠שָּׁמַיִם הִשְׁמַ֣עְתָּ דִּ֑ין אֶ֖רֶץ יָֽרְאָ֣ה וְ⁠שָׁקָֽטָה׃","mi֭⁠şá̇̌mayim hişĕ̌ma֣ʻĕţá̇ di֑̇yn ʼe֖reẕ yáֽrĕʼá֣h wĕ⁠şá̌qáֽtáh׃"],[76,9,"בְּ⁠קוּם־לַ⁠מִּשְׁפָּ֥ט אֱלֹהִ֑ים לְ⁠הוֹשִׁ֖יעַ כָּל־עַנְוֵי־אֶ֣רֶץ סֶֽלָה׃","bĕ̇⁠qẇm-la⁠mi̇şĕ̌pá֥̇t ʼèlòhi֑ym lĕ⁠hwòşǐ֖yʻa ká̇l-ʻanĕwéy-ʼe֣reẕ seֽláh׃"],[76,10,"כִּֽי־חֲמַ֣ת אָדָ֣ם תּוֹדֶ֑⁠ךָּ שְׁאֵרִ֖ית חֵמֹ֣ת תַּחְגֹּֽר׃","kiֽ̇y-ẖàma֣ţ ʼádá֣m ţ̇wòde֑⁠ká̇ şĕ̌ʼéri֖yţ ẖémò֣ţ ţȧẖĕgòֽ̇r׃"],[76,11,"נִֽדֲר֣וּ וְ⁠שַׁלְּמוּ֮ לַ⁠יהוָ֪ה אֱֽלֹהֵ֫י⁠כֶ֥ם כָּל־סְבִיבָ֑י⁠ו יוֹבִ֥ילוּ שַׁ֝֗י לַ⁠מּוֹרָֽא׃","niֽdàr֣ẇ wĕ⁠şǎlĕ̇mẇ֮ la⁠yhwá֪h ʼèֽlòhé֫y⁠ke֥m ká̇l-sĕbiybá֑y⁠w ywòbi֥ylẇ şǎ֝֗y la⁠ṁwòráֽʼ׃"],[76,12,"יִ֭בְצֹר ר֣וּחַ נְגִידִ֑ים נ֝וֹרָ֗א לְ⁠מַלְכֵי־אָֽרֶץ׃","yi֭bĕẕòr r֣ẇẖa nĕgiydi֑ym n֝wòrá֗ʼ lĕ⁠malĕkéy-ʼáֽreẕ׃"],[77,1,"קוֹלִ֣⁠י אֶל־אֱלֹהִ֣ים וְ⁠אֶצְעָ֑קָה קוֹלִ֥⁠י אֶל־אֱ֝לֹהִ֗ים וְ⁠הַאֲזִ֥ין אֵלָֽ⁠י׃","qwòli֣⁠y ʼel-ʼèlòhi֣ym wĕ⁠ʼeẕĕʻá֑qáh qwòli֥⁠y ʼel-ʼè֝lòhi֗ym wĕ⁠haʼàzi֥yn ʼéláֽ⁠y׃"],[77,2,"בְּ⁠י֥וֹם צָרָתִ⁠י֮ אֲדֹנָ֪⁠י דָּ֫רָ֥שְׁתִּי יָדִ֤⁠י ׀ לַ֣יְלָה נִ֭גְּרָה וְ⁠לֹ֣א תָפ֑וּג מֵאֲנָ֖ה הִנָּחֵ֣ם נַפְשִֽׁ⁠י׃","bĕ̇⁠y֥wòm ẕáráţi⁠y֮ ʼàdòná֪⁠y dá̇֫rá֥şĕ̌ţi̇y yádi֤⁠y ׀ la֣yĕláh ni֭gĕ̇ráh wĕ⁠lò֣ʼ ţáp֑ẇg méʼàná֖h hiná̇ẖé֣m napĕşǐֽ⁠y׃"],[77,3,"אֶזְכְּרָ֣ה אֱלֹהִ֣ים וְ⁠אֶֽהֱמָיָ֑ה אָשִׂ֓יחָה ׀ וְ⁠תִתְעַטֵּ֖ף רוּחִ֣⁠י סֶֽלָה׃","ʼezĕkĕ̇rá֣h ʼèlòhi֣ym wĕ⁠ʼeֽhèmáyá֑h ʼáşî֓yẖáh ׀ wĕ⁠ţiţĕʻaté֖̇p rẇẖi֣⁠y seֽláh׃"],[77,4,"אָ֭חַזְתָּ שְׁמֻר֣וֹת עֵינָ֑⁠י נִ֝פְעַ֗מְתִּי וְ⁠לֹ֣א אֲדַבֵּֽר׃","ʼá֭ẖazĕţá̇ şĕ̌mur֣wòţ ʻéyná֑⁠y ni֝pĕʻa֗mĕţi̇y wĕ⁠lò֣ʼ ʼàdabéֽ̇r׃"],[77,5,"חִשַּׁ֣בְתִּי יָמִ֣ים מִ⁠קֶּ֑דֶם שְׁ֝נ֗וֹת עוֹלָמִֽים׃","ẖişȧ֣̌bĕţi̇y yámi֣ym mi⁠qė֑dem şĕ̌֝n֗wòţ ʻwòlámiֽym׃"],[77,6,"אֶֽזְכְּרָ֥ה נְגִינָתִ֗⁠י בַּ֫⁠לָּ֥יְלָה עִם־לְבָבִ֥⁠י אָשִׂ֑יחָה וַ⁠יְחַפֵּ֥שׂ רוּחִֽ⁠י׃","ʼeֽzĕkĕ̇rá֥h nĕgiynáţi֗⁠y bȧ֫⁠lá֥̇yĕláh ʻim-lĕbábi֥⁠y ʼáşî֑yẖáh wa⁠yĕẖapé֥̇ş̂ rẇẖiֽ⁠y׃"],[77,7,"הַֽ֭⁠לְ⁠עוֹלָמִים יִזְנַ֥ח ׀ אֲדֹנָ֑⁠י וְ⁠לֹֽא־יֹסִ֖יף לִ⁠רְצ֣וֹת עֽוֹד׃","haֽ֭⁠lĕ⁠ʻwòlámiym yizĕna֥ẖ ׀ ʼàdòná֑⁠y wĕ⁠lòֽʼ-yòsi֖yp li⁠rĕẕ֣wòţ ʻֽwòd׃"],[77,8,"הֶ⁠אָפֵ֣ס לָ⁠נֶ֣צַח חַסְדּ֑⁠וֹ גָּ֥מַר אֹ֝֗מֶר לְ⁠דֹ֣ר וָ⁠דֹֽר׃","he⁠ʼápé֣s lá⁠ne֣ẕaẖ ẖasĕḋ֑⁠wò gá֥̇mar ʼò֝֗mer lĕ⁠dò֣r wá⁠dòֽr׃"],[77,9,"הֲ⁠שָׁכַ֣ח חַנּ֣וֹת אֵ֑ל אִם־קָפַ֥ץ בְּ֝⁠אַ֗ף רַחֲמָ֥י⁠ו סֶֽלָה׃","hà⁠şá̌ka֣ẖ ẖaṅ֣wòţ ʼé֑l ʼim-qápa֥ẕ bĕ̇֝⁠ʼa֗p raẖàmá֥y⁠w seֽláh׃"],[77,10,"וָ֭⁠אֹמַר חַלּ֣וֹתִ⁠י הִ֑יא שְׁ֝נ֗וֹת יְמִ֣ין עֶלְיֽוֹן׃","wá֭⁠ʼòmar ẖal֣̇wòţi⁠y hi֑yʼ şĕ̌֝n֗wòţ yĕmi֣yn ʻelĕyֽwòn׃"],[77,11,"אזכיר מַֽעַלְלֵי־יָ֑הּ כִּֽי־אֶזְכְּרָ֖ה מִ⁠קֶּ֣דֶם פִּלְאֶֽ⁠ךָ׃","ʼzkyr maֽʻalĕléy-yá֑ḣ kiֽ̇y-ʼezĕkĕ̇rá֖h mi⁠qė֣dem pi̇lĕʼeֽ⁠ká׃"],[77,12,"וְ⁠הָגִ֥יתִי בְ⁠כָל־פָּעֳלֶ֑⁠ךָ וּֽ⁠בַ⁠עֲלִ֖ילוֹתֶ֣י⁠ךָ אָשִֽׂיחָה׃","wĕ⁠hági֥yţiy bĕ⁠kál-pá̇ʻole֑⁠ká ẇֽ⁠ba⁠ʻàli֖ylwòţe֣y⁠ká ʼáşîֽyẖáh׃"],[77,13,"אֱ֭לֹהִים בַּ⁠קֹּ֣דֶשׁ דַּרְכֶּ֑⁠ךָ מִי־אֵ֥ל גָּ֝ד֗וֹל כֵּֽ⁠אלֹהִֽים׃","ʼè֭lòhiym bȧ⁠qò֣̇deş̌ dȧrĕkė֑⁠ká miy-ʼé֥l gá̇֝d֗wòl kéֽ̇⁠ʼlòhiֽym׃"],[77,14,"אַתָּ֣ה הָ֭⁠אֵל עֹ֣שֵׂה פֶ֑לֶא הוֹדַ֖עְתָּ בָ⁠עַמִּ֣ים עֻזֶּֽ⁠ךָ׃","ʼaţá֣̇h há֭⁠ʼél ʻò֣şé̂h pe֑leʼ hwòda֖ʻĕţá̇ bá⁠ʻami֣̇ym ʻuzėֽ⁠ká׃"],[77,15,"גָּאַ֣לְתָּ בִּ⁠זְר֣וֹעַ עַמֶּ֑⁠ךָ בְּנֵי־יַעֲקֹ֖ב וְ⁠יוֹסֵ֣ף סֶֽלָה׃","gá̇ʼa֣lĕţá̇ bi̇⁠zĕr֣wòʻa ʻamė֑⁠ká bĕ̇néy-yaʻàqò֖b wĕ⁠ywòsé֣p seֽláh׃"],[77,16,"רָ֘א֤וּ⁠ךָ מַּ֨יִם ׀ אֱֽלֹהִ֗ים רָא֣וּ⁠ךָ מַּ֣יִם יָחִ֑ילוּ אַ֝֗ף יִרְגְּז֥וּ תְהֹמֽוֹת׃","rá֘ʼ֤ẇ⁠ká mȧ֨yim ׀ ʼèֽlòhi֗ym ráʼ֣ẇ⁠ká mȧ֣yim yáẖi֑ylẇ ʼa֝֗p yirĕgĕ̇z֥ẇ ţĕhòmֽwòţ׃"],[77,17,"זֹ֤רְמוּ מַ֨יִם ׀ עָב֗וֹת ק֭וֹל נָתְנ֣וּ שְׁחָקִ֑ים אַף־חֲ֝צָצֶ֗י⁠ךָ יִתְהַלָּֽכוּ׃","zò֤rĕmẇ ma֨yim ׀ ʻáb֗wòţ q֭wòl náţĕn֣ẇ şĕ̌ẖáqi֑ym ʼap-ẖà֝ẕáẕe֗y⁠ká yiţĕhaláֽ̇kẇ׃"],[77,18,"ק֤וֹל רַעַמְ⁠ךָ֨ ׀ בַּ⁠גַּלְגַּ֗ל הֵאִ֣ירוּ בְרָקִ֣ים תֵּבֵ֑ל רָגְזָ֖ה וַ⁠תִּרְעַ֣שׁ הָ⁠אָֽרֶץ׃","q֤wòl raʻamĕ⁠ká֨ ׀ bȧ⁠gȧlĕgȧ֗l héʼi֣yrẇ bĕráqi֣ym ţé̇bé֑l rágĕzá֖h wa⁠ţi̇rĕʻa֣ş̌ há⁠ʼáֽreẕ׃"],[77,19,"בַּ⁠יָּ֤ם דַּרְכֶּ֗⁠ךָ ו⁠שבילי⁠ך בְּ⁠מַ֣יִם רַבִּ֑ים וְ֝⁠עִקְּבוֹתֶ֗י⁠ךָ לֹ֣א נֹדָֽעוּ׃","bȧ⁠yá֤̇m dȧrĕkė֗⁠ká w⁠şbyly⁠k bĕ̇⁠ma֣yim rabi֑̇ym wĕ֝⁠ʻiqĕ̇bwòţe֗y⁠ká lò֣ʼ nòdáֽʻẇ׃"],[77,20,"נָחִ֣יתָ כַ⁠צֹּ֣אן עַמֶּ֑⁠ךָ בְּֽ⁠יַד־מֹשֶׁ֥ה וְ⁠אַהֲרֹֽן׃","náẖi֣yţá ka⁠ẕò֣̇ʼn ʻamė֑⁠ká bĕֽ̇⁠yad-mòşě֥h wĕ⁠ʼahàròֽn׃"],[78,1,"מַשְׂכִּ֗יל לְ⁠אָ֫סָ֥ף הַאֲזִ֣ינָ⁠ה עַ֭מִּ⁠י תּוֹרָתִ֑⁠י הַטּ֥וּ אָ֝זְנְ⁠כֶ֗ם לְ⁠אִמְרֵי־פִֽ⁠י׃","maşĕ̂ki̇֗yl lĕ⁠ʼá֫sá֥p haʼàzi֣yná⁠h ʻa֭mi̇⁠y ţ̇wòráţi֑⁠y haṫ֥ẇ ʼá֝zĕnĕ⁠ke֗m lĕ⁠ʼimĕréy-piֽ⁠y׃"],[78,2,"אֶפְתְּחָ֣ה בְ⁠מָשָׁ֣ל פִּ֑⁠י אַבִּ֥יעָה חִ֝יד֗וֹת מִנִּי־קֶֽדֶם׃","ʼepĕţĕ̇ẖá֣h bĕ⁠máşá֣̌l pi֑̇⁠y ʼabi֥̇yʻáh ẖi֝yd֗wòţ mini̇y-qeֽdem׃"],[78,3,"אֲשֶׁ֣ר שָׁ֭מַעְנוּ וַ⁠נֵּדָעֵ֑⁠ם וַ֝⁠אֲבוֹתֵ֗י⁠נוּ סִפְּרוּ־לָֽ⁠נוּ׃","ʼàşě֣r şá֭̌maʻĕnẇ wa⁠né̇dáʻé֑⁠m wa֝⁠ʼàbwòţé֗y⁠nẇ sipĕ̇rẇ-láֽ⁠nẇ׃"],[78,4,"לֹ֤א נְכַחֵ֨ד ׀ מִ⁠בְּנֵי⁠הֶ֗ם לְ⁠ד֥וֹר אַחֲר֗וֹן מְֽ֭סַפְּרִים תְּהִלּ֣וֹת יְהוָ֑ה וֶ⁠עֱזוּז֥⁠וֹ וְ֝⁠נִפְלְאוֹתָ֗י⁠ו אֲשֶׁ֣ר עָשָֽׂה׃","lò֤ʼ nĕkaẖé֨d ׀ mi⁠bĕ̇néy⁠he֗m lĕ⁠d֥wòr ʼaẖàr֗wòn mĕֽ֭sapĕ̇riym ţĕ̇hil֣̇wòţ yĕhwá֑h we⁠ʻèzẇz֥⁠wò wĕ֝⁠nipĕlĕʼwòţá֗y⁠w ʼàşě֣r ʻáşáֽ̂h׃"],[78,5,"וַ⁠יָּ֤קֶם עֵד֨וּת ׀ בְּֽ⁠יַעֲקֹ֗ב וְ⁠תוֹרָה֮ שָׂ֤ם בְּ⁠יִשְׂרָ֫אֵ֥ל אֲשֶׁ֣ר צִ֭וָּה אֶת־אֲבוֹתֵ֑י⁠נוּ לְ֝⁠הוֹדִיעָ֗⁠ם לִ⁠בְנֵי⁠הֶֽם׃","wa⁠yá֤̇qem ʻéd֨ẇţ ׀ bĕֽ̇⁠yaʻàqò֗b wĕ⁠ţwòráh֮ şá֤̂m bĕ̇⁠yişĕ̂rá֫ʼé֥l ʼàşě֣r ẕi֭wá̇h ʼeţ-ʼàbwòţé֑y⁠nẇ lĕ֝⁠hwòdiyʻá֗⁠m li⁠bĕnéy⁠heֽm׃"],[78,6,"לְמַ֤עַן יֵדְע֨וּ ׀ דּ֣וֹר אַ֭חֲרוֹן בָּנִ֣ים יִוָּלֵ֑דוּ יָ֝קֻ֗מוּ וִֽ⁠יסַפְּר֥וּ לִ⁠בְנֵי⁠הֶֽם׃","lĕma֤ʻan yédĕʻ֨ẇ ׀ ḋ֣wòr ʼa֭ẖàrwòn bá̇ni֣ym yiwá̇lé֑dẇ yá֝qu֗mẇ wiֽ⁠ysapĕ̇r֥ẇ li⁠bĕnéy⁠heֽm׃"],[78,7,"וְ⁠יָשִׂ֥ימוּ בֵֽ⁠אלֹהִ֗ים כִּ֫סְלָ֥⁠ם וְ⁠לֹ֣א יִ֭שְׁכְּחוּ מַֽעַלְלֵי־אֵ֑ל וּ⁠מִצְוֺתָ֥י⁠ו יִנְצֹֽרוּ׃","wĕ⁠yáşî֥ymẇ béֽ⁠ʼlòhi֗ym ki̇֫sĕlá֥⁠m wĕ⁠lò֣ʼ yi֭şĕ̌kĕ̇ẖẇ maֽʻalĕléy-ʼé֑l ẇ⁠miẕĕwֺţá֥y⁠w yinĕẕòֽrẇ׃"],[78,8,"וְ⁠לֹ֤א יִהְי֨וּ ׀ כַּ⁠אֲבוֹתָ֗⁠ם דּוֹר֮ סוֹרֵ֪ר וּ⁠מֹ֫רֶ֥ה דּ֭וֹר לֹא־הֵכִ֣ין לִבּ֑⁠וֹ וְ⁠לֹא־נֶאֶמְנָ֖ה אֶת־אֵ֣ל רוּחֽ⁠וֹ׃","wĕ⁠lò֤ʼ yihĕy֨ẇ ׀ kȧ⁠ʼàbwòţá֗⁠m ḋwòr֮ swòré֪r ẇ⁠mò֫re֥h ḋ֭wòr lòʼ-héki֣yn liḃ֑⁠wò wĕ⁠lòʼ-neʼemĕná֖h ʼeţ-ʼé֣l rẇẖֽ⁠wò׃"],[78,9,"בְּֽנֵי־אֶפְרַ֗יִם נוֹשְׁקֵ֥י רוֹמֵי־קָ֑שֶׁת הָ֝פְכ֗וּ בְּ⁠י֣וֹם קְרָֽב׃","bĕֽ̇néy-ʼepĕra֗yim nwòşĕ̌qé֥y rwòméy-qá֑şěţ há֝pĕk֗ẇ bĕ̇⁠y֣wòm qĕráֽb׃"],[78,10,"לֹ֣א שָׁ֭מְרוּ בְּרִ֣ית אֱלֹהִ֑ים וּ֝⁠בְ⁠תוֹרָת֗⁠וֹ מֵאֲנ֥וּ לָ⁠לֶֽכֶת׃","lò֣ʼ şá֭̌mĕrẇ bĕ̇ri֣yţ ʼèlòhi֑ym ẇ֝⁠bĕ⁠ţwòráţ֗⁠wò méʼàn֥ẇ lá⁠leֽkeţ׃"],[78,11,"וַ⁠יִּשְׁכְּח֥וּ עֲלִילוֹתָ֑י⁠ו וְ֝⁠נִפְלְאוֹתָ֗י⁠ו אֲשֶׁ֣ר הֶרְאָֽ⁠ם׃","wa⁠yi̇şĕ̌kĕ̇ẖ֥ẇ ʻàliylwòţá֑y⁠w wĕ֝⁠nipĕlĕʼwòţá֗y⁠w ʼàşě֣r herĕʼáֽ⁠m׃"],[78,12,"נֶ֣גֶד אֲ֭בוֹתָ⁠ם עָ֣שָׂה פֶ֑לֶא בְּ⁠אֶ֖רֶץ מִצְרַ֣יִם שְׂדֵה־צֹֽעַן׃","ne֣ged ʼà֭bwòţá⁠m ʻá֣şá̂h pe֑leʼ bĕ̇⁠ʼe֖reẕ miẕĕra֣yim şĕ̂déh-ẕòֽʻan׃"],[78,13,"בָּ֣קַע יָ֭ם וַ⁠יַּֽעֲבִירֵ֑⁠ם וַֽ⁠יַּצֶּב־מַ֥יִם כְּמוֹ־נֵֽד׃","bá֣̇qaʻ yá֭m wa⁠yȧֽʻàbiyré֑⁠m waֽ⁠yȧẕėb-ma֥yim kĕ̇mwò-néֽd׃"],[78,14,"וַ⁠יַּנְחֵ֣⁠ם בֶּ⁠עָנָ֣ן יוֹמָ֑ם וְ⁠כָל־הַ֝⁠לַּ֗יְלָה בְּ⁠א֣וֹר אֵֽשׁ׃","wa⁠yȧnĕẖé֣⁠m bė⁠ʻáná֣n ywòmá֑m wĕ⁠kál-ha֝⁠lȧ֗yĕláh bĕ̇⁠ʼ֣wòr ʼéֽş̌׃"],[78,15,"יְבַקַּ֣ע צֻ֭רִים בַּ⁠מִּדְבָּ֑ר וַ֝⁠יַּ֗שְׁקְ כִּ⁠תְהֹמ֥וֹת רַבָּֽה׃","yĕbaqȧ֣ʻ ẕu֭riym bȧ⁠mi̇dĕbá֑̇r wa֝⁠yȧ֗şĕ̌qĕ ki̇⁠ţĕhòm֥wòţ rabáֽ̇h׃"],[78,16,"וַ⁠יּוֹצִ֣א נוֹזְלִ֣ים מִ⁠סָּ֑לַע וַ⁠יּ֖וֹרֶד כַּ⁠נְּהָר֣וֹת מָֽיִם׃","wa⁠ẏwòẕi֣ʼ nwòzĕli֣ym mi⁠sá֑̇laʻ wa⁠ẏ֖wòred kȧ⁠nĕ̇hár֣wòţ máֽyim׃"],[78,17,"וַ⁠יּוֹסִ֣יפוּ ע֭וֹד לַ⁠חֲטֹא־ל֑⁠וֹ לַֽ⁠מְר֥וֹת עֶ֝לְי֗וֹן בַּ⁠צִּיָּֽה׃","wa⁠ẏwòsi֣ypẇ ʻ֭wòd la⁠ẖàtòʼ-l֑⁠wò laֽ⁠mĕr֥wòţ ʻe֝lĕy֗wòn bȧ⁠ẕi̇yáֽ̇h׃"],[78,18,"וַ⁠יְנַסּוּ־אֵ֥ל בִּ⁠לְבָבָ֑⁠ם לִֽ⁠שְׁאָל־אֹ֥כֶל לְ⁠נַפְשָֽׁ⁠ם׃","wa⁠yĕnaṡẇ-ʼé֥l bi̇⁠lĕbábá֑⁠m liֽ⁠şĕ̌ʼál-ʼò֥kel lĕ⁠napĕşáֽ̌⁠m׃"],[78,19,"וַֽ⁠יְדַבְּר֗וּ בֵּֽ⁠אלֹ֫הִ֥ים אָ֭מְרוּ הֲ⁠י֣וּכַל אֵ֑ל לַ⁠עֲרֹ֥ךְ שֻׁ֝לְחָ֗ן בַּ⁠מִּדְבָּֽר׃","waֽ⁠yĕdabĕ̇r֗ẇ béֽ̇⁠ʼlò֫hi֥ym ʼá֭mĕrẇ hà⁠y֣ẇkal ʼé֑l la⁠ʻàrò֥kĕ şǔ֝lĕẖá֗n bȧ⁠mi̇dĕbáֽ̇r׃"],[78,20,"הֵ֤ן הִכָּה־צ֨וּר ׀ וַ⁠יָּז֣וּבוּ מַיִם֮ וּ⁠נְחָלִ֪ים יִ֫שְׁטֹ֥פוּ הֲ⁠גַם־לֶ֭חֶם י֣וּכַל תֵּ֑ת אִם־יָכִ֖ין שְׁאֵ֣ר לְ⁠עַמּֽ⁠וֹ׃","hé֤n hiká̇h-ẕ֨ẇr ׀ wa⁠yá̇z֣ẇbẇ mayim֮ ẇ⁠nĕẖáli֪ym yi֫şĕ̌tò֥pẇ hà⁠gam-le֭ẖem y֣ẇkal ţé֑̇ţ ʼim-yáki֖yn şĕ̌ʼé֣r lĕ⁠ʻaṁֽ⁠wò׃"],[78,21,"לָ⁠כֵ֤ן ׀ שָׁמַ֥ע יְהוָ֗ה וַֽ⁠יִּתְעַבָּ֥ר וְ֭⁠אֵשׁ נִשְּׂקָ֣ה בְ⁠יַעֲקֹ֑ב וְ⁠גַם־אַ֝֗ף עָלָ֥ה בְ⁠יִשְׂרָאֵֽל׃","lá⁠ké֤n ׀ şá̌ma֥ʻ yĕhwá֗h waֽ⁠yi̇ţĕʻabá֥̇r wĕ֭⁠ʼéş̌ nişĕ̇̂qá֣h bĕ⁠yaʻàqò֑b wĕ⁠gam-ʼa֝֗p ʻálá֥h bĕ⁠yişĕ̂ráʼéֽl׃"],[78,22,"כִּ֤י לֹ֣א הֶ֭אֱמִינוּ בֵּ⁠אלֹהִ֑ים וְ⁠לֹ֥א בָ֝טְח֗וּ בִּֽ⁠ישׁוּעָתֽ⁠וֹ׃","ki֤̇y lò֣ʼ he֭ʼèmiynẇ bé̇⁠ʼlòhi֑ym wĕ⁠lò֥ʼ bá֝tĕẖ֗ẇ biֽ̇⁠yş̌ẇʻáţֽ⁠wò׃"],[78,23,"וַ⁠יְצַ֣ו שְׁחָקִ֣ים מִ⁠מָּ֑עַל וְ⁠דַלְתֵ֖י שָׁמַ֣יִם פָּתָֽח׃","wa⁠yĕẕa֣w şĕ̌ẖáqi֣ym mi⁠má֑̇ʻal wĕ⁠dalĕţé֖y şá̌ma֣yim pá̇ţáֽẖ׃"],[78,24,"וַ⁠יַּמְטֵ֬ר עֲלֵי⁠הֶ֣ם מָ֣ן לֶ⁠אֱכֹ֑ל וּ⁠דְגַן־שָׁ֝מַ֗יִם נָ֣תַן לָֽ⁠מוֹ׃","wa⁠yȧmĕté֬r ʻàléy⁠he֣m má֣n le⁠ʼèkò֑l ẇ⁠dĕgan-şá̌֝ma֗yim ná֣ţan láֽ⁠mwò׃"],[78,25,"לֶ֣חֶם אַ֭בִּירִים אָ֣כַל אִ֑ישׁ צֵידָ֬ה שָׁלַ֖ח לָ⁠הֶ֣ם לָ⁠שֹֽׂבַע׃","le֣ẖem ʼa֭bi̇yriym ʼá֣kal ʼi֑yş̌ ẕéydá֬h şá̌la֖ẖ lá⁠he֣m lá⁠şòֽ̂baʻ׃"],[78,26,"יַסַּ֣ע קָ֭דִים בַּ⁠שָּׁמָ֑יִם וַ⁠יְנַהֵ֖ג בְּ⁠עֻזּ֣⁠וֹ תֵימָֽן׃","yasȧ֣ʻ qá֭diym bȧ⁠şá̇̌má֑yim wa⁠yĕnahé֖g bĕ̇⁠ʻuż֣⁠wò ţéymáֽn׃"],[78,27,"וַ⁠יַּמְטֵ֬ר עֲלֵי⁠הֶ֣ם כֶּ⁠עָפָ֣ר שְׁאֵ֑ר וּֽ⁠כְ⁠ח֥וֹל יַ֝מִּ֗ים ע֣וֹף כָּנָֽף׃","wa⁠yȧmĕté֬r ʻàléy⁠he֣m kė⁠ʻápá֣r şĕ̌ʼé֑r ẇֽ⁠kĕ⁠ẖ֥wòl ya֝mi̇֗ym ʻ֣wòp ká̇náֽp׃"],[78,28,"וַ֭⁠יַּפֵּל בְּ⁠קֶ֣רֶב מַחֲנֵ֑⁠הוּ סָ֝בִ֗יב לְ⁠מִשְׁכְּנֹתָֽי⁠ו׃","wa֭⁠yȧpé̇l bĕ̇⁠qe֣reb maẖàné֑⁠hẇ sá֝bi֗yb lĕ⁠mişĕ̌kĕ̇nòţáֽy⁠w׃"],[78,29,"וַ⁠יֹּאכְל֣וּ וַ⁠יִּשְׂבְּע֣וּ מְאֹ֑ד וְ֝⁠תַֽאֲוָתָ֗⁠ם יָבִ֥א לָ⁠הֶֽם׃","wa⁠yò̇ʼkĕl֣ẇ wa⁠yi̇şĕ̂bĕ̇ʻ֣ẇ mĕʼò֑d wĕ֝⁠ţaֽʼàwáţá֗⁠m yábi֥ʼ lá⁠heֽm׃"],[78,30,"לֹא־זָר֥וּ מִ⁠תַּאֲוָתָ֑⁠ם ע֝֗וֹד אָכְלָ֥⁠ם בְּ⁠פִי⁠הֶֽם׃","lòʼ-zár֥ẇ mi⁠ţȧʼàwáţá֑⁠m ʻ֝֗wòd ʼákĕlá֥⁠m bĕ̇⁠piy⁠heֽm׃"],[78,31,"וְ⁠אַ֤ף אֱלֹהִ֨ים ׀ עָ֘לָ֤ה בָ⁠הֶ֗ם וַֽ֭⁠יַּהֲרֹג בְּ⁠מִשְׁמַנֵּי⁠הֶ֑ם וּ⁠בַחוּרֵ֖י יִשְׂרָאֵ֣ל הִכְרִֽיעַ׃","wĕ⁠ʼa֤p ʼèlòhi֨ym ׀ ʻá֘lá֤h bá⁠he֗m waֽ֭⁠yȧhàròg bĕ̇⁠mişĕ̌mané̇y⁠he֑m ẇ⁠baẖẇré֖y yişĕ̂ráʼé֣l hikĕriֽyʻa׃"],[78,32,"בְּ⁠כָל־זֹ֭את חָֽטְאוּ־ע֑וֹד וְ⁠לֹֽא־הֶ֝אֱמִ֗ינוּ בְּ⁠נִפְלְאוֹתָֽי⁠ו׃","bĕ̇⁠kál-zò֭ʼţ ẖáֽtĕʼẇ-ʻ֑wòd wĕ⁠lòֽʼ-he֝ʼèmi֗ynẇ bĕ̇⁠nipĕlĕʼwòţáֽy⁠w׃"],[78,33,"וַ⁠יְכַל־בַּ⁠הֶ֥בֶל יְמֵי⁠הֶ֑ם וּ֝⁠שְׁנוֹתָ֗⁠ם בַּ⁠בֶּהָלָֽה׃","wa⁠yĕkal-bȧ⁠he֥bel yĕméy⁠he֑m ẇ֝⁠şĕ̌nwòţá֗⁠m bȧ⁠bėháláֽh׃"],[78,34,"אִם־הֲרָגָ֥⁠ם וּ⁠דְרָשׁ֑וּ⁠הוּ וְ֝⁠שָׁ֗בוּ וְ⁠שִֽׁחֲרוּ־אֵֽל׃","ʼim-hàrágá֥⁠m ẇ⁠dĕráş֑̌ẇ⁠hẇ wĕ֝⁠şá̌֗bẇ wĕ⁠şǐֽẖàrẇ-ʼéֽl׃"],[78,35,"וַֽ֭⁠יִּזְכְּרוּ כִּֽי־אֱלֹהִ֣ים צוּרָ֑⁠ם וְ⁠אֵ֥ל עֶ֝לְיוֹן גֹּאֲלָֽ⁠ם׃","waֽ֭⁠yi̇zĕkĕ̇rẇ kiֽ̇y-ʼèlòhi֣ym ẕẇrá֑⁠m wĕ⁠ʼé֥l ʻe֝lĕywòn gò̇ʼàláֽ⁠m׃"],[78,36,"וַ⁠יְפַתּ֥וּ⁠הוּ בְּ⁠פִי⁠הֶ֑ם וּ֝⁠בִ⁠לְשׁוֹנָ֗⁠ם יְכַזְּבוּ־לֽ⁠וֹ׃","wa⁠yĕpaţ֥̇ẇ⁠hẇ bĕ̇⁠piy⁠he֑m ẇ֝⁠bi⁠lĕş̌wòná֗⁠m yĕkazĕ̇bẇ-lֽ⁠wò׃"],[78,37,"וְ֭⁠לִבָּ⁠ם לֹא־נָכ֣וֹן עִמּ֑⁠וֹ וְ⁠לֹ֥א נֶ֝אֶמְנ֗וּ בִּ⁠בְרִיתֽ⁠וֹ׃","wĕ֭⁠libá̇⁠m lòʼ-nák֣wòn ʻiṁ֑⁠wò wĕ⁠lò֥ʼ ne֝ʼemĕn֗ẇ bi̇⁠bĕriyţֽ⁠wò׃"],[78,38,"וְ⁠ה֤וּא רַח֨וּם ׀ יְכַפֵּ֥ר עָוֺן֮ וְֽ⁠לֹא־יַ֫שְׁחִ֥ית וְ֭⁠הִרְבָּה לְ⁠הָשִׁ֣יב אַפּ֑⁠וֹ וְ⁠לֹֽא־יָ֝עִיר כָּל־חֲמָתֽ⁠וֹ׃","wĕ⁠h֤ẇʼ raẖ֨ẇm ׀ yĕkapé֥̇r ʻáwֺn֮ wĕֽ⁠lòʼ-ya֫şĕ̌ẖi֥yţ wĕ֭⁠hirĕbá̇h lĕ⁠háşǐ֣yb ʼaṗ֑⁠wò wĕ⁠lòֽʼ-yá֝ʻiyr ká̇l-ẖàmáţֽ⁠wò׃"],[78,39,"וַ֭⁠יִּזְכֹּר כִּי־בָשָׂ֣ר הֵ֑מָּה ר֥וּחַ ה֝וֹלֵ֗ךְ וְ⁠לֹ֣א יָשֽׁוּב׃","wa֭⁠yi̇zĕkò̇r ki̇y-báşá֣̂r hé֑má̇h r֥ẇẖa h֝wòlé֗kĕ wĕ⁠lò֣ʼ yáşֽ̌ẇb׃"],[78,40,"כַּ֭⁠מָּה יַמְר֣וּ⁠הוּ בַ⁠מִּדְבָּ֑ר יַ֝עֲצִיב֗וּ⁠הוּ בִּֽ⁠ישִׁימֽוֹן׃","kȧ֭⁠má̇h yamĕr֣ẇ⁠hẇ ba⁠mi̇dĕbá֑̇r ya֝ʻàẕiyb֗ẇ⁠hẇ biֽ̇⁠yşǐymֽwòn׃"],[78,41,"וַ⁠יָּשׁ֣וּבוּ וַ⁠יְנַסּ֣וּ אֵ֑ל וּ⁠קְד֖וֹשׁ יִשְׂרָאֵ֣ל הִתְווּ׃","wa⁠yá̇ş֣̌ẇbẇ wa⁠yĕnaṡ֣ẇ ʼé֑l ẇ⁠qĕd֖wòş̌ yişĕ̂ráʼé֣l hiţĕwẇ׃"],[78,42,"לֹא־זָכְר֥וּ אֶת־יָד֑⁠וֹ י֝֗וֹם אֲֽשֶׁר־פָּדָ֥⁠ם מִנִּי־צָֽר׃","lòʼ-zákĕr֥ẇ ʼeţ-yád֑⁠wò y֝֗wòm ʼàֽşěr-pá̇dá֥⁠m mini̇y-ẕáֽr׃"],[78,43,"אֲשֶׁר־שָׂ֣ם בְּ֭⁠מִצְרַיִם אֹֽתוֹתָ֑י⁠ו וּ֝⁠מוֹפְתָ֗י⁠ו בִּ⁠שְׂדֵה־צֹֽעַן׃","ʼàşěr-şá֣̂m bĕ֭̇⁠miẕĕrayim ʼòֽţwòţá֑y⁠w ẇ֝⁠mwòpĕţá֗y⁠w bi̇⁠şĕ̂déh-ẕòֽʻan׃"],[78,44,"וַ⁠יַּהֲפֹ֣ךְ לְ֭⁠דָם יְאֹרֵי⁠הֶ֑ם וְ֝⁠נֹזְלֵי⁠הֶ֗ם בַּל־יִשְׁתָּיֽוּ⁠ן׃","wa⁠yȧhàpò֣kĕ lĕ֭⁠dám yĕʼòréy⁠he֑m wĕ֝⁠nòzĕléy⁠he֗m bȧl-yişĕ̌ţá̇yֽẇ⁠n׃"],[78,45,"יְשַׁלַּ֬ח בָּ⁠הֶ֣ם עָ֭רֹב וַ⁠יֹּאכְלֵ֑⁠ם וּ֝⁠צְפַרְדֵּ֗עַ וַ⁠תַּשְׁחִיתֵֽ⁠ם׃","yĕşǎlȧ֬ẖ bá̇⁠he֣m ʻá֭ròb wa⁠yò̇ʼkĕlé֑⁠m ẇ֝⁠ẕĕparĕdé̇֗ʻa wa⁠ţȧşĕ̌ẖiyţéֽ⁠m׃"],[78,46,"וַ⁠יִּתֵּ֣ן לֶ⁠חָסִ֣יל יְבוּלָ֑⁠ם וִֽ֝⁠יגִיעָ֗⁠ם לָ⁠אַרְבֶּֽה׃","wa⁠yi̇ţé֣̇n le⁠ẖási֣yl yĕbẇlá֑⁠m wiֽ֝⁠ygiyʻá֗⁠m lá⁠ʼarĕbėֽh׃"],[78,47,"יַהֲרֹ֣ג בַּ⁠בָּרָ֣ד גַּפְנָ֑⁠ם וְ֝⁠שִׁקְמוֹתָ֗⁠ם בַּֽ⁠חֲנָמַֽל׃","yahàrò֣g bȧ⁠bá̇rá֣d gȧpĕná֑⁠m wĕ֝⁠şǐqĕmwòţá֗⁠m bȧֽ⁠ẖànámaֽl׃"],[78,48,"וַ⁠יַּסְגֵּ֣ר לַ⁠בָּרָ֣ד בְּעִירָ֑⁠ם וּ֝⁠מִקְנֵי⁠הֶ֗ם לָ⁠רְשָׁפִֽים׃","wa⁠yȧsĕgé֣̇r la⁠bá̇rá֣d bĕ̇ʻiyrá֑⁠m ẇ֝⁠miqĕnéy⁠he֗m lá⁠rĕşá̌piֽym׃"],[78,49,"יְשַׁלַּח־בָּ֨⁠ם ׀ חֲר֬וֹן אַפּ֗⁠וֹ עֶבְרָ֣ה וָ⁠זַ֣עַם וְ⁠צָרָ֑ה מִ֝שְׁלַ֗חַת מַלְאֲכֵ֥י רָעִֽים׃","yĕşǎlȧẖ-bá̇֨⁠m ׀ ẖàr֬wòn ʼaṗ֗⁠wò ʻebĕrá֣h wá⁠za֣ʻam wĕ⁠ẕárá֑h mi֝şĕ̌la֗ẖaţ malĕʼàké֥y ráʻiֽym׃"],[78,50,"יְפַלֵּ֥ס נָתִ֗יב לְ⁠אַ֫פּ֥⁠וֹ לֹא־חָשַׂ֣ךְ מִ⁠מָּ֣וֶת נַפְשָׁ֑⁠ם וְ֝⁠חַיָּתָ֗⁠ם לַ⁠דֶּ֥בֶר הִסְגִּֽיר׃","yĕpalé֥̇s náţi֗yb lĕ⁠ʼa֫ṗ֥⁠wò lòʼ-ẖáşâ֣kĕ mi⁠má֣̇weţ napĕşá֑̌⁠m wĕ֝⁠ẖayá̇ţá֗⁠m la⁠dė֥ber hisĕgiֽ̇yr׃"],[78,51,"וַ⁠יַּ֣ךְ כָּל־בְּכ֣וֹר בְּ⁠מִצְרָ֑יִם רֵאשִׁ֥ית א֝וֹנִ֗ים בְּ⁠אָהֳלֵי־חָֽם׃","wa⁠yȧ֣kĕ ká̇l-bĕ̇k֣wòr bĕ̇⁠miẕĕrá֑yim réʼşǐ֥yţ ʼ֝wòni֗ym bĕ̇⁠ʼáholéy-ẖáֽm׃"],[78,52,"וַ⁠יַּסַּ֣ע כַּ⁠צֹּ֣אן עַמּ֑⁠וֹ וַֽ⁠יְנַהֲגֵ֥⁠ם כַּ֝⁠עֵ֗דֶר בַּ⁠מִּדְבָּֽר׃","wa⁠yȧsȧ֣ʻ kȧ⁠ẕò֣̇ʼn ʻaṁ֑⁠wò waֽ⁠yĕnahàgé֥⁠m kȧ֝⁠ʻé֗der bȧ⁠mi̇dĕbáֽ̇r׃"],[78,53,"וַ⁠יַּנְחֵ֣⁠ם לָ֭⁠בֶטַח וְ⁠לֹ֣א פָחָ֑דוּ וְ⁠אֶת־א֝וֹיְבֵי⁠הֶ֗ם כִּסָּ֥ה הַ⁠יָּֽם׃","wa⁠yȧnĕẖé֣⁠m lá֭⁠betaẖ wĕ⁠lò֣ʼ páẖá֑dẇ wĕ⁠ʼeţ-ʼ֝wòyĕbéy⁠he֗m ki̇sá֥̇h ha⁠yáֽ̇m׃"],[78,54,"וַ֭⁠יְבִיאֵ⁠ם אֶל־גְּב֣וּל קָדְשׁ֑⁠וֹ הַר־זֶ֝֗ה קָנְתָ֥ה יְמִינֽ⁠וֹ׃","wa֭⁠yĕbiyʼé⁠m ʼel-gĕ̇b֣ẇl qádĕş֑̌⁠wò har-ze֝֗h qánĕţá֥h yĕmiynֽ⁠wò׃"],[78,55,"וַ⁠יְגָ֤רֶשׁ מִ⁠פְּנֵי⁠הֶ֨ם ׀ גּוֹיִ֗ם וַֽ֭⁠יַּפִּילֵ⁠ם בְּ⁠חֶ֣בֶל נַחֲלָ֑ה וַ⁠יַּשְׁכֵּ֥ן בְּ֝⁠אָהֳלֵי⁠הֶ֗ם שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wa⁠yĕgá֤reş̌ mi⁠pĕ̇néy⁠he֨m ׀ ġwòyi֗m waֽ֭⁠yȧpi̇ylé⁠m bĕ̇⁠ẖe֣bel naẖàlá֑h wa⁠yȧşĕ̌ké֥̇n bĕ̇֝⁠ʼáholéy⁠he֗m şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[78,56,"וַ⁠יְנַסּ֣וּ וַ֭⁠יַּמְרוּ אֶת־אֱלֹהִ֣ים עֶלְי֑וֹן וְ֝⁠עֵדוֹתָ֗י⁠ו לֹ֣א שָׁמָֽרוּ׃","wa⁠yĕnaṡ֣ẇ wa֭⁠yȧmĕrẇ ʼeţ-ʼèlòhi֣ym ʻelĕy֑wòn wĕ֝⁠ʻédwòţá֗y⁠w lò֣ʼ şá̌máֽrẇ׃"],[78,57,"וַ⁠יִּסֹּ֣גוּ וַֽ֭⁠יִּבְגְּדוּ כַּ⁠אֲבוֹתָ֑⁠ם נֶ֝הְפְּכ֗וּ כְּ⁠קֶ֣שֶׁת רְמִיָּֽה׃","wa⁠yi̇sò֣̇gẇ waֽ֭⁠yi̇bĕgĕ̇dẇ kȧ⁠ʼàbwòţá֑⁠m ne֝hĕpĕ̇k֗ẇ kĕ̇⁠qe֣şěţ rĕmiyáֽ̇h׃"],[78,58,"וַ⁠יַּכְעִיס֥וּ⁠הוּ בְּ⁠בָמוֹתָ֑⁠ם וּ֝⁠בִ⁠פְסִילֵי⁠הֶ֗ם יַקְנִיאֽוּ⁠הוּ׃","wa⁠yȧkĕʻiys֥ẇ⁠hẇ bĕ̇⁠bámwòţá֑⁠m ẇ֝⁠bi⁠pĕsiyléy⁠he֗m yaqĕniyʼֽẇ⁠hẇ׃"],[78,59,"שָׁמַ֣ע אֱ֭לֹהִים וַֽ⁠יִּתְעַבָּ֑ר וַ⁠יִּמְאַ֥ס מְ֝אֹ֗ד בְּ⁠יִשְׂרָאֵֽל׃","şá̌ma֣ʻ ʼè֭lòhiym waֽ⁠yi̇ţĕʻabá֑̇r wa⁠yi̇mĕʼa֥s mĕ֝ʼò֗d bĕ̇⁠yişĕ̂ráʼéֽl׃"],[78,60,"וַ֭⁠יִּטֹּשׁ מִשְׁכַּ֣ן שִׁל֑וֹ אֹ֝֗הֶל שִׁכֵּ֥ן בָּ⁠אָדָֽם׃","wa֭⁠yi̇tò̇ş̌ mişĕ̌kȧ֣n şǐl֑wò ʼò֝֗hel şǐké֥̇n bá̇⁠ʼádáֽm׃"],[78,61,"וַ⁠יִּתֵּ֣ן לַ⁠שְּׁבִ֣י עֻזּ֑⁠וֹ וְֽ⁠תִפְאַרְתּ֥⁠וֹ בְ⁠יַד־צָֽר׃","wa⁠yi̇ţé֣̇n la⁠şĕ̇̌bi֣y ʻuż֑⁠wò wĕֽ⁠ţipĕʼarĕţ֥̇⁠wò bĕ⁠yad-ẕáֽr׃"],[78,62,"וַ⁠יַּסְגֵּ֣ר לַ⁠חֶ֣רֶב עַמּ֑⁠וֹ וּ֝⁠בְ⁠נַחֲלָת֗⁠וֹ הִתְעַבָּֽר׃","wa⁠yȧsĕgé֣̇r la⁠ẖe֣reb ʻaṁ֑⁠wò ẇ֝⁠bĕ⁠naẖàláţ֗⁠wò hiţĕʻabáֽ̇r׃"],[78,63,"בַּחוּרָ֥י⁠ו אָֽכְלָה־אֵ֑שׁ וּ֝⁠בְתוּלֹתָ֗י⁠ו לֹ֣א הוּלָּֽלוּ׃","bȧẖẇrá֥y⁠w ʼáֽkĕláh-ʼé֑ş̌ ẇ֝⁠bĕţẇlòţá֗y⁠w lò֣ʼ hẇláֽ̇lẇ׃"],[78,64,"כֹּ֭הֲנָי⁠ו בַּ⁠חֶ֣רֶב נָפָ֑לוּ וְ֝⁠אַלְמְנֹתָ֗י⁠ו לֹ֣א תִבְכֶּֽינָה׃","kò֭̇hànáy⁠w bȧ⁠ẖe֣reb nápá֑lẇ wĕ֝⁠ʼalĕmĕnòţá֗y⁠w lò֣ʼ ţibĕkėֽynáh׃"],[78,65,"וַ⁠יִּקַ֖ץ כְּ⁠יָשֵׁ֥ן ׀ אֲדֹנָ֑⁠י כְּ֝⁠גִבּ֗וֹר מִתְרוֹנֵ֥ן מִ⁠יָּֽיִן׃","wa⁠yi̇qa֖ẕ kĕ̇⁠yáşé֥̌n ׀ ʼàdòná֑⁠y kĕ̇֝⁠giḃ֗wòr miţĕrwòné֥n mi⁠yáֽ̇yin׃"],[78,66,"וַ⁠יַּךְ־צָרָ֥י⁠ו אָח֑וֹר חֶרְפַּ֥ת ע֝וֹלָ֗ם נָ֣תַן לָֽ⁠מוֹ׃","wa⁠yȧkĕ-ẕárá֥y⁠w ʼáẖ֑wòr ẖerĕpȧ֥ţ ʻ֝wòlá֗m ná֣ţan láֽ⁠mwò׃"],[78,67,"וַ֭⁠יִּמְאַס בְּ⁠אֹ֣הֶל יוֹסֵ֑ף וּֽ⁠בְ⁠שֵׁ֥בֶט אֶ֝פְרַ֗יִם לֹ֣א בָחָֽר׃","wa֭⁠yi̇mĕʼas bĕ̇⁠ʼò֣hel ywòsé֑p ẇֽ⁠bĕ⁠şé֥̌bet ʼe֝pĕra֗yim lò֣ʼ báẖáֽr׃"],[78,68,"וַ֭⁠יִּבְחַר אֶת־שֵׁ֣בֶט יְהוּדָ֑ה אֶֽת־הַ֥ר צִ֝יּ֗וֹן אֲשֶׁ֣ר אָהֵֽב׃","wa֭⁠yi̇bĕẖar ʼeţ-şé֣̌bet yĕhẇdá֑h ʼeֽţ-ha֥r ẕi֝ẏ֗wòn ʼàşě֣r ʼáhéֽb׃"],[78,69,"וַ⁠יִּ֣בֶן כְּמוֹ־רָ֭מִים מִקְדָּשׁ֑⁠וֹ כְּ֝⁠אֶ֗רֶץ יְסָדָ֥⁠הּ לְ⁠עוֹלָֽם׃","wa⁠yi֣̇ben kĕ̇mwò-rá֭miym miqĕdá̇ş֑̌⁠wò kĕ̇֝⁠ʼe֗reẕ yĕsádá֥⁠ḣ lĕ⁠ʻwòláֽm׃"],[78,70,"וַ֭⁠יִּבְחַר בְּ⁠דָוִ֣ד עַבְדּ֑⁠וֹ וַ֝⁠יִּקָּחֵ֗⁠הוּ מִֽ⁠מִּכְלְאֹ֥ת צֹֽאן׃","wa֭⁠yi̇bĕẖar bĕ̇⁠dáwi֣d ʻabĕḋ֑⁠wò wa֝⁠yi̇qá̇ẖé֗⁠hẇ miֽ⁠mi̇kĕlĕʼò֥ţ ẕòֽʼn׃"],[78,71,"מֵ⁠אַחַ֥ר עָל֗וֹת הֱ֫בִיא֥⁠וֹ לִ֭⁠רְעוֹת בְּ⁠יַעֲקֹ֣ב עַמּ֑⁠וֹ וּ֝⁠בְ⁠יִשְׂרָאֵ֗ל נַחֲלָתֽ⁠וֹ׃","mé⁠ʼaẖa֥r ʻál֗wòţ hè֫biyʼ֥⁠wò li֭⁠rĕʻwòţ bĕ̇⁠yaʻàqò֣b ʻaṁ֑⁠wò ẇ֝⁠bĕ⁠yişĕ̂ráʼé֗l naẖàláţֽ⁠wò׃"],[78,72,"וַ֭⁠יִּרְעֵ⁠ם כְּ⁠תֹ֣ם לְבָב֑⁠וֹ וּ⁠בִ⁠תְבוּנ֖וֹת כַּפָּ֣י⁠ו יַנְחֵֽ⁠ם׃","wa֭⁠yi̇rĕʻé⁠m kĕ̇⁠ţò֣m lĕbáb֑⁠wò ẇ⁠bi⁠ţĕbẇn֖wòţ kȧpá֣̇y⁠w yanĕẖéֽ⁠m׃"],[79,1,"מִזְמ֗וֹר לְ⁠אָ֫סָ֥ף אֱֽלֹהִ֡ים בָּ֤אוּ גוֹיִ֨ם ׀ בְּֽ⁠נַחֲלָתֶ֗⁠ךָ טִ֭מְּאוּ אֶת־הֵיכַ֣ל קָדְשֶׁ֑⁠ךָ שָׂ֖מוּ אֶת־יְרוּשָׁלִַ֣ם לְ⁠עִיִּֽים׃","mizĕm֗wòr lĕ⁠ʼá֫sá֥p ʼèֽlòhi֡ym bá֤̇ʼẇ gwòyi֨m ׀ bĕֽ̇⁠naẖàláţe֗⁠ká ti֭mĕ̇ʼẇ ʼeţ-héyka֣l qádĕşě֑⁠ká şá֖̂mẇ ʼeţ-yĕrẇşá̌lia֣m lĕ⁠ʻiyiֽ̇ym׃"],[79,2,"נָֽתְנ֡וּ אֶת־נִבְלַ֬ת עֲבָדֶ֗י⁠ךָ מַ֭אֲכָל לְ⁠ע֣וֹף הַ⁠שָּׁמָ֑יִם בְּשַׂ֥ר חֲ֝סִידֶ֗י⁠ךָ לְ⁠חַיְת⁠וֹ־אָֽרֶץ׃","náֽţĕn֡ẇ ʼeţ-nibĕla֬ţ ʻàbáde֗y⁠ká ma֭ʼàkál lĕ⁠ʻ֣wòp ha⁠şá̇̌má֑yim bĕ̇şâ֥r ẖà֝siyde֗y⁠ká lĕ⁠ẖayĕţ⁠wò-ʼáֽreẕ׃"],[79,3,"שָׁפְכ֬וּ דָמָ֨⁠ם ׀ כַּ⁠מַּ֗יִם סְֽבִ֘יב֤וֹת יְֽרוּשָׁלִָ֗ם וְ⁠אֵ֣ין קוֹבֵֽר׃","şá̌pĕk֬ẇ dámá֨⁠m ׀ kȧ⁠mȧ֗yim sĕֽbi֘yb֤wòţ yĕֽrẇşá̌liá֗m wĕ⁠ʼé֣yn qwòbéֽr׃"],[79,4,"הָיִ֣ינוּ חֶ֭רְפָּה לִ⁠שְׁכֵנֵ֑י⁠נוּ לַ֥עַג וָ֝⁠קֶ֗לֶס לִ⁠סְבִיבוֹתֵֽי⁠נוּ׃","háyi֣ynẇ ẖe֭rĕpá̇h li⁠şĕ̌kéné֑y⁠nẇ la֥ʻag wá֝⁠qe֗les li⁠sĕbiybwòţéֽy⁠nẇ׃"],[79,5,"עַד־מָ֣ה יְ֭הוָה תֶּאֱנַ֣ף לָ⁠נֶ֑צַח תִּבְעַ֥ר כְּמוֹ־אֵ֝֗שׁ קִנְאָתֶֽ⁠ךָ׃","ʻad-má֣h yĕ֭hwáh ţėʼèna֣p lá⁠ne֑ẕaẖ ţi̇bĕʻa֥r kĕ̇mwò-ʼé֝֗ş̌ qinĕʼáţeֽ⁠ká׃"],[79,6,"שְׁפֹ֤ךְ חֲמָתְ⁠ךָ֨ אֶֽל־הַ⁠גּוֹיִם֮ אֲשֶׁ֪ר לֹא־יְדָ֫ע֥וּ⁠ךָ וְ⁠עַ֥ל מַמְלָכ֑וֹת אֲשֶׁ֥ר בְּ֝⁠שִׁמְ⁠ךָ֗ לֹ֣א קָרָֽאוּ׃","şĕ̌pò֤kĕ ẖàmáţĕ⁠ká֨ ʼeֽl-ha⁠ġwòyim֮ ʼàşě֪r lòʼ-yĕdá֫ʻ֥ẇ⁠ká wĕ⁠ʻa֥l mamĕlák֑wòţ ʼàşě֥r bĕ̇֝⁠şǐmĕ⁠ká֗ lò֣ʼ qáráֽʼẇ׃"],[79,7,"כִּ֭י אָכַ֣ל אֶֽת־יַעֲקֹ֑ב וְֽ⁠אֶת־נָוֵ֥⁠הוּ הֵשַֽׁמּוּ׃","ki֭̇y ʼáka֣l ʼeֽţ-yaʻàqò֑b wĕֽ⁠ʼeţ-náwé֥⁠hẇ héşǎֽṁẇ׃"],[79,8,"אַֽל־תִּזְכָּר־לָ⁠נוּ֮ עֲוֺנֹ֪ת רִאשֹׁ֫נִ֥ים מַ֭הֵר יְקַדְּמ֣וּ⁠נוּ רַחֲמֶ֑י⁠ךָ כִּ֖י דַלּ֣וֹנוּ מְאֹֽד׃","ʼaֽl-ţi̇zĕká̇r-lá⁠nẇ֮ ʻàwֺnò֪ţ riʼşò̌֫ni֥ym ma֭hér yĕqadĕ̇m֣ẇ⁠nẇ raẖàme֑y⁠ká ki֖̇y dal֣̇wònẇ mĕʼòֽd׃"],[79,9,"עָזְרֵ֤⁠נוּ ׀ אֱלֹ֘הֵ֤י יִשְׁעֵ֗⁠נוּ עַל־דְּבַ֥ר כְּבֽוֹד־שְׁמֶ֑⁠ךָ וְ⁠הַצִּילֵ֥⁠נוּ וְ⁠כַפֵּ֥ר עַל־חַ֝טֹּאתֵ֗י⁠נוּ לְמַ֣עַן שְׁמֶֽ⁠ךָ׃","ʻázĕré֤⁠nẇ ׀ ʼèlò֘hé֤y yişĕ̌ʻé֗⁠nẇ ʻal-dĕ̇ba֥r kĕ̇bֽwòd-şĕ̌me֑⁠ká wĕ⁠haẕi̇ylé֥⁠nẇ wĕ⁠kapé֥̇r ʻal-ẖa֝tò̇ʼţé֗y⁠nẇ lĕma֣ʻan şĕ̌meֽ⁠ká׃"],[79,10,"לָ֤⁠מָּה ׀ יֹאמְר֣וּ הַ⁠גּוֹיִם֮ אַיֵּ֪ה אֱֽלֹהֵ֫י⁠הֶ֥ם יִוָּדַ֣ע ב⁠גיים לְ⁠עֵינֵ֑י⁠נוּ נִ֝קְמַ֗ת דַּֽם־עֲבָדֶ֥י⁠ךָ הַ⁠שָּׁפֽוּךְ׃","lá֤⁠má̇h ׀ yòʼmĕr֣ẇ ha⁠ġwòyim֮ ʼayé֪̇h ʼèֽlòhé֫y⁠he֥m yiwá̇da֣ʻ b⁠gyym lĕ⁠ʻéyné֑y⁠nẇ ni֝qĕma֗ţ dȧֽm-ʻàbáde֥y⁠ká ha⁠şá̇̌pֽẇkĕ׃"],[79,11,"תָּ֤ב֣וֹא לְ⁠פָנֶי⁠ךָ֮ אֶנְקַ֪ת אָ֫סִ֥יר כְּ⁠גֹ֥דֶל זְרוֹעֲ⁠ךָ֑ ה֝וֹתֵ֗ר בְּנֵ֣י תְמוּתָֽה׃","ţá֤̇b֣wòʼ lĕ⁠páney⁠ká֮ ʼenĕqa֪ţ ʼá֫si֥yr kĕ̇⁠gò֥del zĕrwòʻà⁠ká֑ h֝wòţé֗r bĕ̇né֣y ţĕmẇţáֽh׃"],[79,12,"וְ⁠הָ֘שֵׁ֤ב לִ⁠שְׁכֵנֵ֣י⁠נוּ שִׁ֭בְעָתַיִם אֶל־חֵיקָ֑⁠ם חֶרְפָּ֘תָ֤⁠ם אֲשֶׁ֖ר חֵרְפ֣וּ⁠ךָ אֲדֹנָֽ⁠י׃","wĕ⁠há֘şé֤̌b li⁠şĕ̌kéné֣y⁠nẇ şǐ֭bĕʻáţayim ʼel-ẖéyqá֑⁠m ẖerĕpá̇֘ţá֤⁠m ʼàşě֖r ẖérĕp֣ẇ⁠ká ʼàdònֽá⁠y׃"],[79,13,"וַ⁠אֲנַ֤חְנוּ עַמְּ⁠ךָ֨ ׀ וְ⁠צֹ֥אן מַרְעִיתֶ⁠ךָ֮ נ֤וֹדֶ֥ה לְּ⁠ךָ֗ לְ⁠ע֫וֹלָ֥ם לְ⁠דֹ֥ר וָ⁠דֹ֑ר נְ֝סַפֵּ֗ר תְּהִלָּתֶֽ⁠ךָ׃","wa⁠ʼàna֤ẖĕnẇ ʻamĕ̇⁠ká֨ ׀ wĕ⁠ẕò֥ʼn marĕʻiyţe⁠ká֮ n֤wòde֥h lĕ̇⁠ká֗ lĕ⁠ʻ֫wòlá֥m lĕ⁠dò֥r wá⁠dò֑r nĕ֝sapé̇֗r ţĕ̇hilá̇ţeֽ⁠ká׃"],[80,1,"רֹ֘עֵ֤ה יִשְׂרָאֵ֨ל ׀ הַאֲזִ֗ינָ⁠ה נֹהֵ֣ג כַּ⁠צֹּ֣אן יוֹסֵ֑ף יֹשֵׁ֖ב הַ⁠כְּרוּבִ֣ים הוֹפִֽיעָ⁠ה׃","rò֘ʻé֤h yişĕ̂ráʼé֨l ׀ haʼàzi֗yná⁠h nòhé֣g kȧ⁠ẕò֣̇ʼn ywòsé֑p yòşé֖̌b ha⁠kĕ̇rẇbi֣ym hwòpiֽyʻá⁠h׃"],[80,2,"לִ⁠פְנֵ֤י אֶפְרַ֨יִם ׀ וּ⁠בִנְיָ֘מִ֤ן וּ⁠מְנַשֶּׁ֗ה עוֹרְרָ֥⁠ה אֶת־גְּבֽוּרָתֶ֑⁠ךָ וּ⁠לְכָ֖⁠ה לִ⁠ישֻׁעָ֣תָ⁠ה לָּֽ⁠נוּ׃","li⁠pĕné֤y ʼepĕra֨yim ׀ ẇ⁠binĕyá֘mi֤n ẇ⁠mĕnaşė̌֗h ʻwòrĕrá֥⁠h ʼeţ-gĕ̇bֽẇráţe֑⁠ká ẇ⁠lĕká֖⁠h li⁠yşǔʻá֣ţá⁠h láֽ̇⁠nẇ׃"],[80,3,"אֱלֹהִ֥ים הֲשִׁיבֵ֑⁠נוּ וְ⁠הָאֵ֥ר פָּ֝נֶ֗י⁠ךָ וְ⁠נִוָּשֵֽׁעָה׃","ʼèlòhi֥ym hàşǐybé֑⁠nẇ wĕ⁠háʼé֥r pá̇֝ne֗y⁠ká wĕ⁠niwá̇şéֽ̌ʻáh׃"],[80,4,"יְהוָ֣ה אֱלֹהִ֣ים צְבָא֑וֹת עַד־מָתַ֥י עָ֝שַׁ֗נְתָּ בִּ⁠תְפִלַּ֥ת עַמֶּֽ⁠ךָ׃","yĕhwá֣h ʼèlòhi֣ym ẕĕbáʼ֑wòţ ʻad-máţa֥y ʻá֝şǎ֗nĕţá̇ bi̇⁠ţĕpilȧ֥ţ ʻamėֽ⁠ká׃"],[80,5,"הֶ֭אֱכַלְתָּ⁠ם לֶ֣חֶם דִּמְעָ֑ה וַ֝⁠תַּשְׁקֵ֗⁠מוֹ בִּ⁠דְמָע֥וֹת שָׁלִֽישׁ׃","he֭ʼèkalĕţá̇⁠m le֣ẖem di̇mĕʻá֑h wa֝⁠ţȧşĕ̌qé֗⁠mwò bi̇⁠dĕmáʻ֥wòţ şá̌liֽyş̌׃"],[80,6,"תְּשִׂימֵ֣⁠נוּ מָ֭דוֹן לִ⁠שְׁכֵנֵ֑י⁠נוּ וְ֝⁠אֹיְבֵ֗י⁠נוּ יִלְעֲגוּ־לָֽ⁠מוֹ׃","ţĕ̇şîymé֣⁠nẇ má֭dwòn li⁠şĕ̌kéné֑y⁠nẇ wĕ֝⁠ʼòyĕbé֗y⁠nẇ yilĕʻàgẇ-láֽ⁠mwò׃"],[80,7,"אֱלֹהִ֣ים צְבָא֣וֹת הֲשִׁיבֵ֑⁠נוּ וְ⁠הָאֵ֥ר פָּ֝נֶ֗י⁠ךָ וְ⁠נִוָּשֵֽׁעָה׃","ʼèlòhi֣ym ẕĕbáʼ֣wòţ hàşǐybé֑⁠nẇ wĕ⁠háʼé֥r pá̇֝ne֗y⁠ká wĕ⁠niwá̇şéֽ̌ʻáh׃"],[80,8,"גֶּ֭פֶן מִ⁠מִּצְרַ֣יִם תַּסִּ֑יעַ תְּגָרֵ֥שׁ גּ֝וֹיִ֗ם וַ⁠תִּטָּעֶֽ⁠הָ׃","gė֭pen mi⁠mi̇ẕĕra֣yim ţȧsi֑̇yʻa ţĕ̇gáré֥ş̌ ġ֝wòyi֗m wa⁠ţi̇tá̇ʻeֽ⁠há׃"],[80,9,"פִּנִּ֥יתָ לְ⁠פָנֶ֑י⁠הָ וַ⁠תַּשְׁרֵ֥שׁ שָׁ֝רָשֶׁ֗י⁠הָ וַ⁠תְּמַלֵּא־אָֽרֶץ׃","pi̇ni֥̇yţá lĕ⁠páne֑y⁠há wa⁠ţȧşĕ̌ré֥ş̌ şá̌֝ráşě֗y⁠há wa⁠ţĕ̇malé̇ʼ-ʼáֽreẕ׃"],[80,10,"כָּסּ֣וּ הָרִ֣ים צִלָּ֑⁠הּ וַ֝⁠עֲנָפֶ֗י⁠הָ אַֽרְזֵי־אֵֽל׃","ká̇ṡ֣ẇ hári֣ym ẕilá֑̇⁠ḣ wa֝⁠ʻànápe֗y⁠há ʼaֽrĕzéy-ʼéֽl׃"],[80,11,"תְּשַׁלַּ֣ח קְצִירֶ֣⁠הָ עַד־יָ֑ם וְ⁠אֶל־נָ֝הָ֗ר יֽוֹנְקוֹתֶֽי⁠הָ׃","ţĕ̇şǎlȧ֣ẖ qĕẕiyre֣⁠há ʻad-yá֑m wĕ⁠ʼel-ná֝há֗r yֽwònĕqwòţeֽy⁠há׃"],[80,12,"לָ֭⁠מָּה פָּרַ֣צְתָּ גְדֵרֶ֑י⁠הָ וְ֝⁠אָר֗וּ⁠הָ כָּל־עֹ֥בְרֵי דָֽרֶךְ׃","lá֭⁠má̇h pá̇ra֣ẕĕţá̇ gĕdére֑y⁠há wĕ֝⁠ʼár֗ẇ⁠há ká̇l-ʻò֥bĕréy dáֽrekĕ׃"],[80,13,"יְכַרְסְמֶ֣⁠נָּֽה חֲזִ֣יר מִיָּ֑עַר וְ⁠זִ֖יז שָׂדַ֣י יִרְעֶֽ⁠נָּה׃","yĕkarĕsĕme֣⁠náֽ̇h ẖàzi֣yr miyá֑̇ʻar wĕ⁠zi֖yz şá̂da֣y yirĕʻeֽ⁠ná̇h׃"],[80,14,"אֱלֹהִ֣ים צְבָאוֹת֮ שֽׁ֫וּב־נָ֥א הַבֵּ֣ט מִ⁠שָּׁמַ֣יִם וּ⁠רְאֵ֑ה וּ֝⁠פְקֹ֗ד גֶּ֣פֶן זֹֽאת׃","ʼèlòhi֣ym ẕĕbáʼwòţ֮ şֽ̌֫ẇb-ná֥ʼ habé֣̇t mi⁠şá̇̌ma֣yim ẇ⁠rĕʼé֑h ẇ֝⁠pĕqò֗d gė֣pen zòֽʼţ׃"],[80,15,"וְ֭⁠כַנָּה אֲשֶׁר־נָטְעָ֣ה יְמִינֶ֑⁠ךָ וְ⁠עַל־בֵּ֝֗ן אִמַּ֥צְתָּה לָּֽ⁠ךְ׃","wĕ֭⁠kaná̇h ʼàşěr-nátĕʻá֣h yĕmiyne֑⁠ká wĕ⁠ʻal-bé̇֝֗n ʼimȧ֥ẕĕţá̇h láֽ̇⁠kĕ׃"],[80,16,"שְׂרֻפָ֣ה בָ⁠אֵ֣שׁ כְּסוּחָ֑ה מִ⁠גַּעֲרַ֖ת פָּנֶ֣י⁠ךָ יֹאבֵֽדוּ׃","şĕ̂rupá֣h bá⁠ʼé֣ş̌ kĕ̇sẇẖá֑h mi⁠gȧʻàra֖ţ pá̇ne֣y⁠ká yòʼbéֽdẇ׃"],[80,17,"תְּֽהִי־יָ֭דְ⁠ךָ עַל־אִ֣ישׁ יְמִינֶ֑⁠ךָ עַל־בֶּן־אָ֝דָ֗ם אִמַּ֥צְתָּ לָּֽ⁠ךְ׃","ţĕֽ̇hiy-yá֭dĕ⁠ká ʻal-ʼi֣yş̌ yĕmiyne֑⁠ká ʻal-bėn-ʼá֝dá֗m ʼimȧ֥ẕĕţá̇ láֽ̇⁠kĕ׃"],[80,18,"וְ⁠לֹא־נָס֥וֹג מִמֶּ֑⁠ךָּ תְּ֝חַיֵּ֗⁠נוּ וּ⁠בְ⁠שִׁמְ⁠ךָ֥ נִקְרָֽא׃","wĕ⁠lòʼ-nás֥wòg mimė֑⁠ká̇ ţĕ̇֝ẖayé̇֗⁠nẇ ẇ⁠bĕ⁠şǐmĕ⁠ká֥ niqĕráֽʼ׃"],[80,19,"יְה֘וָ֤ה אֱלֹהִ֣ים צְבָא֣וֹת הֲשִׁיבֵ֑⁠נוּ הָאֵ֥ר פָּ֝נֶ֗י⁠ךָ וְ⁠נִוָּשֵֽׁעָה׃","yĕh֘wá֤h ʼèlòhi֣ym ẕĕbáʼ֣wòţ hàşǐybé֑⁠nẇ háʼé֥r pá̇֝ne֗y⁠ká wĕ⁠niwá̇şéֽ̌ʻáh׃"],[81,1,"הַ֭רְנִינוּ לֵ⁠אלֹהִ֣ים עוּזֵּ֑⁠נוּ הָ֝רִ֗יעוּ לֵ⁠אלֹהֵ֥י יַעֲקֹֽב׃","ha֭rĕniynẇ lé⁠ʼlòhi֣ym ʻẇzé֑̇⁠nẇ há֝ri֗yʻẇ lé⁠ʼlòhé֥y yaʻàqòֽb׃"],[81,2,"שְֽׂאוּ־זִ֭מְרָה וּ⁠תְנוּ־תֹ֑ף כִּנּ֖וֹר נָעִ֣ים עִם־נָֽבֶל׃","şĕֽ̂ʼẇ-zi֭mĕráh ẇ⁠ţĕnẇ-ţò֑p ki̇ṅ֖wòr náʻi֣ym ʻim-náֽbel׃"],[81,3,"תִּקְע֣וּ בַ⁠חֹ֣דֶשׁ שׁוֹפָ֑ר בַּ֝⁠כֵּ֗סֶה לְ⁠י֣וֹם חַגֵּֽ⁠נוּ׃","ţi̇qĕʻ֣ẇ ba⁠ẖò֣deş̌ ş̌wòpá֑r bȧ֝⁠ké̇֗seh lĕ⁠y֣wòm ẖagéֽ̇⁠nẇ׃"],[81,4,"כִּ֤י חֹ֣ק לְ⁠יִשְׂרָאֵ֣ל ה֑וּא מִ֝שְׁפָּ֗ט לֵ⁠אלֹהֵ֥י יַעֲקֹֽב׃","ki֤̇y ẖò֣q lĕ⁠yişĕ̂ráʼé֣l h֑ẇʼ mi֝şĕ̌pá̇֗t lé⁠ʼlòhé֥y yaʻàqòֽb׃"],[81,5,"עֵ֤דוּת ׀ בִּֽ⁠יה֘וֹסֵ֤ף שָׂמ֗⁠וֹ בְּ֭⁠צֵאת⁠וֹ עַל־אֶ֣רֶץ מִצְרָ֑יִם שְׂפַ֖ת לֹא־יָדַ֣עְתִּי אֶשְׁמָֽע׃","ʻé֤dẇţ ׀ biֽ̇⁠yh֘wòsé֤p şá̂m֗⁠wò bĕ֭̇⁠ẕéʼţ⁠wò ʻal-ʼe֣reẕ miẕĕrá֑yim şĕ̂pa֖ţ lòʼ-yáda֣ʻĕţi̇y ʼeşĕ̌máֽʻ׃"],[81,6,"הֲסִיר֣וֹתִי מִ⁠סֵּ֣בֶל שִׁכְמ֑⁠וֹ כַּ֝פָּ֗י⁠ו מִ⁠דּ֥וּד תַּעֲבֹֽרְנָה׃","hàsiyr֣wòţiy mi⁠sé֣̇bel şǐkĕm֑⁠wò kȧ֝pá̇֗y⁠w mi⁠ḋ֥ẇd ţȧʻàbòֽrĕnáh׃"],[81,7,"בַּ⁠צָּרָ֥ה קָרָ֗אתָ וָ⁠אֲחַ֫לְּצֶ֥⁠ךָּ אֶ֭עֶנְ⁠ךָ בְּ⁠סֵ֣תֶר רַ֑עַם אֶבְחָֽנְ⁠ךָ֨ עַל־מֵ֖י מְרִיבָ֣ה סֶֽלָה׃","bȧ⁠ẕá̇rá֥h qárá֗ʼţá wá⁠ʼàẖa֫lĕ̇ẕe֥⁠ká̇ ʼe֭ʻenĕ⁠ká bĕ̇⁠sé֣ţer ra֑ʻam ʼebĕẖáֽnĕ⁠ká֨ ʻal-mé֖y mĕriybá֣h seֽláh׃"],[81,8,"שְׁמַ֣ע עַ֭מִּ⁠י וְ⁠אָעִ֣ידָה בָּ֑⁠ךְ יִ֝שְׂרָאֵ֗ל אִם־תִּֽשְׁמַֽע־לִֽ⁠י׃","şĕ̌ma֣ʻ ʻa֭mi̇⁠y wĕ⁠ʼáʻi֣ydáh bá֑̇⁠kĕ yi֝şĕ̂ráʼé֗l ʼim-ţiֽ̇şĕ̌maֽʻ-liֽ⁠y׃"],[81,9,"לֹֽא־יִהְיֶ֣ה בְ֭⁠ךָ אֵ֣ל זָ֑ר וְ⁠לֹ֥א תִ֝שְׁתַּחֲוֶ֗ה לְ⁠אֵ֣ל נֵכָֽר׃","lòֽʼ-yihĕye֣h bĕ֭⁠ká ʼé֣l zá֑r wĕ⁠lò֥ʼ ţi֝şĕ̌ţȧẖàwe֗h lĕ⁠ʼé֣l nékáֽr׃"],[81,10,"אָנֹכִ֨י ׀ יְה֘וָ֤ה אֱלֹהֶ֗י⁠ךָ הַֽ֭⁠מַּעַלְ⁠ךָ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם הַרְחֶב־פִּ֝֗י⁠ךָ וַ⁠אֲמַלְאֵֽ⁠הוּ׃","ʼánòki֨y ׀ yĕh֘wá֤h ʼèlòhe֗y⁠ká haֽ֭⁠mȧʻalĕ⁠ká mé⁠ʼe֣reẕ miẕĕrá֑yim harĕẖeb-pi̇֝֗y⁠ká wa⁠ʼàmalĕʼéֽ⁠hẇ׃"],[81,11,"וְ⁠לֹא־שָׁמַ֣ע עַמִּ֣⁠י לְ⁠קוֹלִ֑⁠י וְ֝⁠יִשְׂרָאֵ֗ל לֹא־אָ֥בָה לִֽ⁠י׃","wĕ⁠lòʼ-şá̌ma֣ʻ ʻami֣̇⁠y lĕ⁠qwòli֑⁠y wĕ֝⁠yişĕ̂ráʼé֗l lòʼ-ʼá֥báh liֽ⁠y׃"],[81,12,"וָֽ֭⁠אֲשַׁלְּחֵ⁠הוּ בִּ⁠שְׁרִיר֣וּת לִבָּ֑⁠ם יֵ֝לְכ֗וּ בְּֽ⁠מוֹעֲצוֹתֵי⁠הֶֽם׃","wáֽ֭⁠ʼàşǎlĕ̇ẖé⁠hẇ bi̇⁠şĕ̌riyr֣ẇţ libá֑̇⁠m yé֝lĕk֗ẇ bĕֽ̇⁠mwòʻàẕwòţéy⁠heֽm׃"],[81,13,"ל֗וּ עַ֭מִּ⁠י שֹׁמֵ֣עַֽ לִ֑⁠י יִ֝שְׂרָאֵ֗ל בִּ⁠דְרָכַ֥⁠י יְהַלֵּֽכוּ׃","l֗ẇ ʻa֭mi̇⁠y şò̌mé֣ʻaֽ li֑⁠y yi֝şĕ̂ráʼé֗l bi̇⁠dĕráka֥⁠y yĕhaléֽ̇kẇ׃"],[81,14,"כִּ֭⁠מְעַט אוֹיְבֵי⁠הֶ֣ם אַכְנִ֑יעַ וְ⁠עַ֥ל צָ֝רֵי⁠הֶ֗ם אָשִׁ֥יב יָדִֽ⁠י׃","ki֭̇⁠mĕʻat ʼwòyĕbéy⁠he֣m ʼakĕni֑yʻa wĕ⁠ʻa֥l ẕá֝réy⁠he֗m ʼáşǐ֥yb yádiֽ⁠y׃"],[81,15,"מְשַׂנְאֵ֣י יְ֭הוָה יְכַֽחֲשׁוּ־ל֑⁠וֹ וִ⁠יהִ֖י עִתָּ֣⁠ם לְ⁠עוֹלָֽם׃","mĕşânĕʼé֣y yĕ֭hwáh yĕkaֽẖàş̌ẇ-l֑⁠wò wi⁠yhi֖y ʻiţá֣̇⁠m lĕ⁠ʻwòláֽm׃"],[81,16,"וַֽ֭⁠יַּאֲכִילֵ⁠הוּ מֵ⁠חֵ֣לֶב חִטָּ֑ה וּ֝⁠מִ⁠צּ֗וּר דְּבַ֣שׁ אַשְׂבִּיעֶֽ⁠ךָ׃","wֽa֭⁠yȧʼàkiylé⁠hẇ mé⁠ẖé֣leb ẖitá֑̇h ẇ֝⁠mi⁠ẕ̇֗ẇr dĕ̇ba֣ş̌ ʼaşĕ̂bi̇yʻeֽ⁠ká׃"],[82,1,"מִזְמ֗וֹר לְ⁠אָ֫סָ֥ף אֱֽלֹהִ֗ים נִצָּ֥ב בַּ⁠עֲדַת־אֵ֑ל בְּ⁠קֶ֖רֶב אֱלֹהִ֣ים יִשְׁפֹּֽט׃","mizĕm֗wòr lĕ⁠ʼá֫sá֥p ʼèֽlòhi֗ym niẕá֥̇b bȧ⁠ʻàdaţ-ʼé֑l bĕ̇⁠qe֖reb ʼèlòhi֣ym yişĕ̌pòֽ̇t׃"],[82,2,"עַד־מָתַ֥י תִּשְׁפְּטוּ־עָ֑וֶל וּ⁠פְנֵ֥י רְ֝שָׁעִ֗ים תִּשְׂאוּ־סֶֽלָה׃","ʻad-máţa֥y ţi̇şĕ̌pĕ̇tẇ-ʻá֑wel ẇ⁠pĕné֥y rĕ֝şá̌ʻi֗ym ţi̇şĕ̂ʼẇ-seֽláh׃"],[82,3,"שִׁפְטוּ־דַ֥ל וְ⁠יָת֑וֹם עָנִ֖י וָ⁠רָ֣שׁ הַצְדִּֽיקוּ׃","şǐpĕtẇ-da֥l wĕ⁠yáţ֑wòm ʻáni֖y wá⁠rá֣ş̌ haẕĕdiֽ̇yqẇ׃"],[82,4,"פַּלְּטוּ־דַ֥ל וְ⁠אֶבְי֑וֹן מִ⁠יַּ֖ד רְשָׁעִ֣ים הַצִּֽילוּ׃","pȧlĕ̇tẇ-da֥l wĕ⁠ʼebĕy֑wòn mi⁠yȧ֖d rĕşá̌ʻi֣ym haẕiֽ̇ylẇ׃"],[82,5,"לֹ֤א יָֽדְע֨וּ ׀ וְ⁠לֹ֥א יָבִ֗ינוּ בַּ⁠חֲשֵׁכָ֥ה יִתְהַלָּ֑כוּ יִ֝מּ֗וֹטוּ כָּל־מ֥וֹסְדֵי אָֽרֶץ׃","lò֤ʼ yáֽdĕʻ֨ẇ ׀ wĕ⁠lò֥ʼ yábi֗ynẇ bȧ⁠ẖàşé̌ká֥h yiţĕhalá֑̇kẇ yi֝ṁ֗wòtẇ ká̇l-m֥wòsĕdéy ʼáֽreẕ׃"],[82,6,"אֲֽנִי־אָ֭מַרְתִּי אֱלֹהִ֣ים אַתֶּ֑ם וּ⁠בְנֵ֖י עֶלְי֣וֹן כֻּלְּ⁠כֶֽם׃","ʼàֽniy-ʼá֭marĕţi̇y ʼèlòhi֣ym ʼaţė֑m ẇ⁠bĕné֖y ʻelĕy֣wòn ku̇lĕ̇⁠keֽm׃"],[82,7,"אָ֭כֵן כְּ⁠אָדָ֣ם תְּמוּת֑וּ⁠ן וּ⁠כְ⁠אַחַ֖ד הַ⁠שָּׂרִ֣ים תִּפֹּֽלוּ׃","ʼá֭kén kĕ̇⁠ʼádá֣m ţĕ̇mẇţ֑ẇ⁠n ẇ⁠kĕ⁠ʼaẖa֖d ha⁠şá̇̂ri֣ym ţi̇pòֽ̇lẇ׃"],[82,8,"קוּמָ֣⁠ה אֱ֭לֹהִים שָׁפְטָ֣⁠ה הָ⁠אָ֑רֶץ כִּֽי־אַתָּ֥ה תִ֝נְחַ֗ל בְּ⁠כָל־הַ⁠גּוֹיִֽם׃","qẇmá֣⁠h ʼè֭lòhiym şá̌pĕtá֣⁠h há⁠ʼá֑reẕ kiֽ̇y-ʼaţá֥̇h ţi֝nĕẖa֗l bĕ̇⁠kál-ha⁠ġwòyiֽm׃"],[83,1,"אֱלֹהִ֥ים אַל־דֳּמִי־לָ֑⁠ךְ אַל־תֶּחֱרַ֖שׁ וְ⁠אַל־תִּשְׁקֹ֣ט אֵֽל׃","ʼèlòhi֥ym ʼal-dȯmiy-lá֑⁠kĕ ʼal-ţėẖèra֖ş̌ wĕ⁠ʼal-ţi̇şĕ̌qò֣t ʼéֽl׃"],[83,2,"כִּֽי־הִנֵּ֣ה א֭וֹיְבֶי⁠ךָ יֶהֱמָי֑וּ⁠ן וּ֝⁠מְשַׂנְאֶ֗י⁠ךָ נָ֣שְׂאוּ רֹֽאשׁ׃","kiֽ̇y-hiné֣̇h ʼ֭wòyĕbey⁠ká yehèmáy֑ẇ⁠n ẇ֝⁠mĕşânĕʼe֗y⁠ká ná֣şĕ̂ʼẇ ròֽʼş̌׃"],[83,3,"עַֽל־עַ֭מְּ⁠ךָ יַעֲרִ֣ימוּ ס֑וֹד וְ֝⁠יִתְיָעֲצ֗וּ עַל־צְפוּנֶֽי⁠ךָ׃","ʻaֽl-ʻa֭mĕ̇⁠ká yaʻàri֣ymẇ s֑wòd wĕ֝⁠yiţĕyáʻàẕ֗ẇ ʻal-ẕĕpẇneֽy⁠ká׃"],[83,4,"אָמְר֗וּ לְ֭כוּ וְ⁠נַכְחִידֵ֣⁠ם מִ⁠גּ֑וֹי וְ⁠לֹֽא־יִזָּכֵ֖ר שֵֽׁם־יִשְׂרָאֵ֣ל עֽוֹד׃","ʼámĕr֗ẇ lĕ֭kẇ wĕ⁠nakĕẖiydé֣⁠m mi⁠ġ֑wòy wĕ⁠lòֽʼ-yizá̇ké֖r şéֽ̌m-yişĕ̂ráʼé֣l ʻֽwòd׃"],[83,5,"כִּ֤י נוֹעֲצ֣וּ לֵ֣ב יַחְדָּ֑ו עָ֝לֶ֗י⁠ךָ בְּרִ֣ית יִכְרֹֽתוּ׃","ki֤̇y nwòʻàẕ֣ẇ lé֣b yaẖĕdá֑̇w ʻá֝le֗y⁠ká bĕ̇ri֣yţ yikĕròֽţẇ׃"],[83,6,"אָהֳלֵ֣י אֱ֭דוֹם וְ⁠יִשְׁמְעֵאלִ֗ים מוֹאָ֥ב וְ⁠הַגְרִֽים׃","ʼáholé֣y ʼè֭dwòm wĕ⁠yişĕ̌mĕʻéʼli֗ym mwòʼá֥b wĕ⁠hagĕrֽiym׃"],[83,7,"גְּבָ֣ל וְ֭⁠עַמּוֹן וַ⁠עֲמָלֵ֑ק פְּ֝לֶ֗שֶׁת עִם־יֹ֥שְׁבֵי צֽוֹר׃","gĕ̇bá֣l wĕ֭⁠ʻaṁwòn wa⁠ʻàmálé֑q pĕ̇֝le֗şěţ ʻim-yò֥şĕ̌béy ẕֽwòr׃"],[83,8,"גַּם־אַ֭שּׁוּר נִלְוָ֣ה עִמָּ֑⁠ם הָ֤י֥וּ זְר֖וֹעַ לִ⁠בְנֵי־ל֣וֹט סֶֽלָה׃","gȧm-ʼa֭ş̇̌ẇr nilĕwá֣h ʻimá֑̇⁠m há֤y֥ẇ zĕr֖wòʻa li⁠bĕnéy-l֣wòt seֽláh׃"],[83,9,"עֲשֵֽׂה־לָ⁠הֶ֥ם כְּ⁠מִדְיָ֑ן כְּֽ⁠סִֽיסְרָ֥א כְ֝⁠יָבִ֗ין בְּ⁠נַ֣חַל קִישֽׁוֹן׃","ʻàşéֽ̂h-lá⁠he֥m kĕ̇⁠midĕyá֑n kĕֽ̇⁠siֽysĕrá֥ʼ kĕ֝⁠yábi֗yn bĕ̇⁠na֣ẖal qiyşֽ̌wòn׃"],[83,10,"נִשְׁמְד֥וּ בְֽ⁠עֵין־דֹּ֑אר הָ֥יוּ דֹּ֝֗מֶן לָ⁠אֲדָמָֽה׃","nişĕ̌mĕd֥ẇ bĕֽ⁠ʻéyn-dò֑̇ʼr há֥yẇ dò̇֝֗men lá⁠ʼàdámáֽh׃"],[83,11,"שִׁיתֵ֣⁠מוֹ נְ֭דִיבֵ⁠מוֹ כְּ⁠עֹרֵ֣ב וְ⁠כִ⁠זְאֵ֑ב וּֽ⁠כְ⁠זֶ֥בַח וּ֝⁠כְ⁠צַלְמֻנָּ֗ע כָּל־נְסִיכֵֽ⁠מוֹ׃","şǐyţé֣⁠mwò nĕ֭diybé⁠mwò kĕ̇⁠ʻòré֣b wĕ⁠ki⁠zĕʼé֑b ẇֽ⁠kĕ⁠ze֥baẖ ẇ֝⁠kĕ⁠ẕalĕmuná̇֗ʻ ká̇l-nĕsiykéֽ⁠mwò׃"],[83,12,"אֲשֶׁ֣ר אָ֭מְרוּ נִ֣ירֲשָׁה לָּ֑⁠נוּ אֵ֝֗ת נְא֣וֹת אֱלֹהִֽים׃","ʼàşě֣r ʼá֭mĕrẇ ni֣yràşá̌h lá֑̇⁠nẇ ʼé֝֗ţ nĕʼ֣wòţ ʼèlòhiֽym׃"],[83,13,"אֱֽלֹהַ֗⁠י שִׁיתֵ֥⁠מוֹ כַ⁠גַּלְגַּ֑ל כְּ֝⁠קַ֗שׁ לִ⁠פְנֵי־רֽוּחַ׃","ʼèֽlòha֗⁠y şǐyţé֥⁠mwò ka⁠gȧlĕgȧ֑l kĕ̇֝⁠qa֗ş̌ li⁠pĕnéy-rֽẇẖa׃"],[83,14,"כְּ⁠אֵ֥שׁ תִּבְעַר־יָ֑עַר וּ֝⁠כְ⁠לֶהָבָ֗ה תְּלַהֵ֥ט הָרִֽים׃","kĕ̇⁠ʼé֥ş̌ ţi̇bĕʻar-yá֑ʻar ẇ֝⁠kĕ⁠lehábá֗h ţĕ̇lahé֥t háriֽym׃"],[83,15,"כֵּ֭ן תִּרְדְּפֵ֣⁠ם בְּ⁠סַעֲרֶ֑⁠ךָ וּ⁠בְ⁠סוּפָתְ⁠ךָ֥ תְבַהֲלֵֽ⁠ם׃","ké֭̇n ţi̇rĕdĕ̇pé֣⁠m bĕ̇⁠saʻàre֑⁠ká ẇ⁠bĕ⁠sẇpáţĕ⁠ká֥ ţĕbahàléֽ⁠m׃"],[83,16,"מַלֵּ֣א פְנֵי⁠הֶ֣ם קָל֑וֹן וִֽ⁠יבַקְשׁ֖וּ שִׁמְ⁠ךָ֣ יְהוָֽה׃","malé֣̇ʼ pĕnéy⁠he֣m qál֑wòn wiֽ⁠ybaqĕş֖̌ẇ şǐmĕ⁠ká֣ yĕhwáֽh׃"],[83,17,"יֵבֹ֖שׁוּ וְ⁠יִבָּהֲל֥וּ עֲדֵי־עַ֗ד וְֽ⁠יַחְפְּר֥וּ וְ⁠יֹאבֵֽדוּ׃","yébò֖ş̌ẇ wĕ⁠yibá̇hàl֥ẇ ʻàdéy-ʻa֗d wĕֽ⁠yaẖĕpĕ̇r֥ẇ wĕ⁠yòʼbéֽdẇ׃"],[83,18,"וְֽ⁠יֵדְע֗וּ כִּֽי־אַתָּ֬ה שִׁמְ⁠ךָ֣ יְהוָ֣ה לְ⁠בַדֶּ֑⁠ךָ עֶ֝לְי֗וֹן עַל־כָּל־הָ⁠אָֽרֶץ׃","wֽĕ⁠yédĕʻ֗ẇ kiֽ̇y-ʼaţá̇֬h şǐmĕ⁠ká֣ yĕhwá֣h lĕ⁠badė֑⁠ká ʻe֝lĕy֗wòn ʻal-ká̇l-há⁠ʼáֽreẕ׃"],[84,1,"מַה־יְּדִיד֥וֹת מִשְׁכְּנוֹתֶ֗י⁠ךָ יְהוָ֥ה צְבָאֽוֹת׃","mah-yĕ̇diyd֥wòţ mişĕ̌kĕ̇nwòţe֗y⁠ká yĕhwá֥h ẕĕbáʼֽwòţ׃"],[84,2,"נִכְסְפָ֬ה וְ⁠גַם־כָּלְתָ֨ה ׀ נַפְשִׁ⁠י֮ לְ⁠חַצְר֪וֹת יְה֫וָ֥ה לִבִּ֥⁠י וּ⁠בְשָׂרִ֑⁠י יְ֝רַנְּנ֗וּ אֶ֣ל אֵֽל־חָֽי׃","nikĕsĕpá֬h wĕ⁠gam-ká̇lĕţá֨h ׀ napĕşǐ⁠y֮ lĕ⁠ẖaẕĕr֪wòţ yĕh֫wá֥h libi֥̇⁠y ẇ⁠bĕşá̂ri֑⁠y yĕ֝ranĕ̇n֗ẇ ʼe֣l ʼéֽl-ẖáֽy׃"],[84,3,"גַּם־צִפּ֨וֹר ׀ מָ֪צְאָה בַ֡יִת וּ⁠דְר֤וֹר ׀ קֵ֥ן לָ⁠הּ֮ אֲשֶׁר־שָׁ֪תָה אֶפְרֹ֫חֶ֥י⁠הָ אֶֽת־מִ֭זְבְּחוֹתֶי⁠ךָ יְהוָ֣ה צְבָא֑וֹת מַ֝לְכִּ֗⁠י וֵ⁠אלֹהָֽ⁠י׃","gȧm-ẕiṗ֨wòr ׀ má֪ẕĕʼáh ba֡yiţ ẇ⁠dĕr֤wòr ׀ qé֥n lá⁠ḣ֮ ʼàşěr-şá֪̌ţáh ʼepĕrò֫ẖe֥y⁠há ʼeֽţ-mi֭zĕbĕ̇ẖwòţey⁠ká yĕhwá֣h ẕĕbáʼ֑wòţ ma֝lĕki̇֗⁠y wé⁠ʼlòháֽ⁠y׃"],[84,4,"אַ֭שְׁרֵי יוֹשְׁבֵ֣י בֵיתֶ֑⁠ךָ ע֝֗וֹד יְֽהַלְל֥וּ⁠ךָ סֶּֽלָה׃","ʼa֭şĕ̌réy ywòşĕ̌bé֣y béyţe֑⁠ká ʻ֝֗wòd yĕֽhalĕl֥ẇ⁠ká sėֽláh׃"],[84,5,"אַשְׁרֵ֣י אָ֭דָם עֽוֹז־ל֥⁠וֹ בָ֑⁠ךְ מְ֝סִלּ֗וֹת בִּ⁠לְבָבָֽ⁠ם׃","ʼaşĕ̌ré֣y ʼá֭dám ʻֽwòz-l֥⁠wò bá֑⁠kĕ mĕ֝sil̇֗wòţ bi̇⁠lĕbábáֽ⁠m׃"],[84,6,"עֹבְרֵ֤י ׀ בְּ⁠עֵ֣מֶק הַ֭⁠בָּכָא מַעְיָ֣ן יְשִׁית֑וּ⁠הוּ גַּם־בְּ֝רָכ֗וֹת יַעְטֶ֥ה מוֹרֶֽה׃","ʻòbĕré֤y ׀ bĕ̇⁠ʻé֣meq ha֭⁠bá̇káʼ maʻĕyá֣n yĕşǐyţ֑ẇ⁠hẇ gȧm-bĕ̇֝rák֗wòţ yaʻĕte֥h mwòreֽh׃"],[84,7,"יֵ֭לְכוּ מֵ⁠חַ֣יִל אֶל־חָ֑יִל יֵרָאֶ֖ה אֶל־אֱלֹהִ֣ים בְּ⁠צִיּֽוֹן׃","yé֭lĕkẇ mé⁠ẖa֣yil ʼel-ẖá֑yil yéráʼe֖h ʼel-ʼèlòhi֣ym bĕ̇⁠ẕiẏֽwòn׃"],[84,8,"יְה֘וָ֤ה אֱלֹהִ֣ים צְ֭בָאוֹת שִׁמְעָ֣⁠ה תְפִלָּתִ֑⁠י הַאֲזִ֨ינָ⁠ה אֱלֹהֵ֖י יַעֲקֹ֣ב סֶֽלָה׃","yĕh֘wá֤h ʼèlòhi֣ym ẕĕ֭báʼwòţ şǐmĕʻá֣⁠h ţĕpilá̇ţi֑⁠y haʼàzi֨yná⁠h ʼèlòhé֖y yaʻàqò֣b seֽláh׃"],[84,9,"מָ֭גִנֵּ⁠נוּ רְאֵ֣ה אֱלֹהִ֑ים וְ֝⁠הַבֵּ֗ט פְּנֵ֣י מְשִׁיחֶֽ⁠ךָ׃","má֭giné̇⁠nẇ rĕʼé֣h ʼèlòhi֑ym wĕ֝⁠habé̇֗t pĕ̇né֣y mĕşǐyẖeֽ⁠ká׃"],[84,10,"כִּ֤י טֽוֹב־י֥וֹם בַּ⁠חֲצֵרֶ֗י⁠ךָ מֵ֫⁠אָ֥לֶף בָּחַ֗רְתִּי הִ֭סְתּוֹפֵף בְּ⁠בֵ֣ית אֱלֹהַ֑⁠י מִ֝⁠דּ֗וּר בְּ⁠אָהֳלֵי־רֶֽשַׁע׃","ki֤̇y tֽwòb-y֥wòm bȧ⁠ẖàẕére֗y⁠ká mé֫⁠ʼá֥lep bá̇ẖa֗rĕţi̇y hi֭sĕţ̇wòpép bĕ̇⁠bé֣yţ ʼèlòha֑⁠y mi֝⁠ḋ֗ẇr bĕ̇⁠ʼáholéy-reֽşǎʻ׃"],[84,11,"כִּ֤י שֶׁ֨מֶשׁ ׀ וּ⁠מָגֵן֮ יְהוָ֪ה אֱלֹ֫הִ֥ים חֵ֣ן וְ֭⁠כָבוֹד יִתֵּ֣ן יְהוָ֑ה לֹ֥א יִמְנַע־ט֝֗וֹב לַֽ⁠הֹלְכִ֥ים בְּ⁠תָמִֽים׃","ki֤̇y şě֨meş̌ ׀ ẇ⁠mágén֮ yĕhwá֪h ʼèlò֫hi֥ym ẖé֣n wĕ֭⁠kábwòd yiţé֣̇n yĕhwá֑h lò֥ʼ yimĕnaʻ-t֝֗wòb laֽ⁠hòlĕki֥ym bĕ̇⁠ţámiֽym׃"],[84,12,"יְהוָ֥ה צְבָא֑וֹת אַֽשְׁרֵ֥י אָ֝דָ֗ם בֹּטֵ֥חַ בָּֽ⁠ךְ׃","yĕhwá֥h ẕĕbáʼ֑wòţ ʼaֽşĕ̌ré֥y ʼá֝dá֗m bò̇té֥ẖa báֽ̇⁠kĕ׃"],[85,1,"רָצִ֣יתָ יְהוָ֣ה אַרְצֶ֑⁠ךָ שַׁ֝֗בְתָּ שבות יַעֲקֹֽב׃","ráẕi֣yţá yĕhwá֣h ʼarĕẕe֑⁠ká şǎ֝֗bĕţá̇ şbwţ yaʻàqòֽb׃"],[85,2,"נָ֭שָׂאתָ עֲוֺ֣ן עַמֶּ֑⁠ךָ כִּסִּ֖יתָ כָל־חַטָּאתָ֣⁠ם סֶֽלָה׃","ná֭şá̂ʼţá ʻàwֺ֣n ʻamė֑⁠ká ki̇si֖̇yţá kál-ẖatá̇ʼţá֣⁠m seֽláh׃"],[85,3,"אָסַ֥פְתָּ כָל־עֶבְרָתֶ֑⁠ךָ הֱ֝שִׁיב֗וֹתָ מֵ⁠חֲר֥וֹן אַפֶּֽ⁠ךָ׃","ʼása֥pĕţá̇ kál-ʻebĕráţe֑⁠ká hè֝şǐyb֗wòţá mé⁠ẖàr֥wòn ʼapėֽ⁠ká׃"],[85,4,"שׁ֭וּבֵ⁠נוּ אֱלֹהֵ֣י יִשְׁעֵ֑⁠נוּ וְ⁠הָפֵ֖ר כַּֽעַסְ⁠ךָ֣ עִמָּֽ⁠נוּ׃","ş֭̌ẇbé⁠nẇ ʼèlòhé֣y yişĕ̌ʻé֑⁠nẇ wĕ⁠hápé֖r kȧֽʻasĕ⁠ká֣ ʻimáֽ̇⁠nẇ׃"],[85,5,"הַ⁠לְ⁠עוֹלָ֥ם תֶּֽאֱנַף־בָּ֑⁠נוּ תִּמְשֹׁ֥ךְ אַ֝פְּ⁠ךָ֗ לְ⁠דֹ֣ר וָ⁠דֹֽר׃","ha⁠lĕ⁠ʻwòlá֥m ţėֽʼènap-bá֑̇⁠nẇ ţi̇mĕşò֥̌kĕ ʼa֝pĕ̇⁠ká֗ lĕ⁠dò֣r wá⁠dòֽr׃"],[85,6,"הֲֽ⁠לֹא־אַ֭תָּה תָּשׁ֣וּב תְּחַיֵּ֑⁠נוּ וְ֝⁠עַמְּ⁠ךָ֗ יִשְׂמְחוּ־בָֽ⁠ךְ׃","hֽà⁠lòʼ-ʼa֭ţá̇h ţá̇ş֣̌ẇb ţĕ̇ẖayé֑̇⁠nẇ wĕ֝⁠ʻamĕ̇⁠ká֗ yişĕ̂mĕẖẇ-báֽ⁠kĕ׃"],[85,7,"הַרְאֵ֣⁠נוּ יְהוָ֣ה חַסְדֶּ֑⁠ךָ וְ֝⁠יֶשְׁעֲ⁠ךָ֗ תִּתֶּן־לָֽ⁠נוּ׃","harĕʼé֣⁠nẇ yĕhwá֣h ẖasĕdė֑⁠ká wĕ֝⁠yeşĕ̌ʻà⁠ká֗ ţi̇ţėn-láֽ⁠nẇ׃"],[85,8,"אֶשְׁמְעָ֗ה מַה־יְדַבֵּר֮ הָ⁠אֵ֪ל ׀ יְה֫וָ֥ה כִּ֤י ׀ יְדַבֵּ֬ר שָׁל֗וֹם אֶל־עַמּ֥⁠וֹ וְ⁠אֶל־חֲסִידָ֑י⁠ו וְֽ⁠אַל־יָשׁ֥וּבוּ לְ⁠כִסְלָֽה׃","ʼeşĕ̌mĕʻá֗h mah-yĕdabé̇r֮ há⁠ʼé֪l ׀ yĕh֫wá֥h ki֤̇y ׀ yĕdabé̇֬r şá̌l֗wòm ʼel-ʻaṁ֥⁠wò wĕ⁠ʼel-ẖàsiydá֑y⁠w wĕֽ⁠ʼal-yáş֥̌ẇbẇ lĕ⁠kisĕláֽh׃"],[85,9,"אַ֤ךְ ׀ קָר֣וֹב לִ⁠ירֵאָ֣י⁠ו יִשְׁע֑⁠וֹ לִ⁠שְׁכֹּ֖ן כָּב֣וֹד בְּ⁠אַרְצֵֽ⁠נוּ׃","ʼa֤kĕ ׀ qár֣wòb li⁠yréʼá֣y⁠w yişĕ̌ʻ֑⁠wò li⁠şĕ̌kò֖̇n ká̇b֣wòd bĕ̇⁠ʼarĕẕéֽ⁠nẇ׃"],[85,10,"חֶֽסֶד־וֶ⁠אֱמֶ֥ת נִפְגָּ֑שׁוּ צֶ֖דֶק וְ⁠שָׁל֣וֹם נָשָֽׁקוּ׃","ẖeֽsed-we⁠ʼème֥ţ nipĕgá֑̇ş̌ẇ ẕe֖deq wĕ⁠şá̌l֣wòm náşáֽ̌qẇ׃"],[85,11,"אֱ֭מֶת מֵ⁠אֶ֣רֶץ תִּצְמָ֑ח וְ֝⁠צֶ֗דֶק מִ⁠שָּׁמַ֥יִם נִשְׁקָֽף׃","ʼè֭meţ mé⁠ʼe֣reẕ ţi̇ẕĕmá֑ẖ wĕ֝⁠ẕe֗deq mi⁠şá̇̌ma֥yim nişĕ̌qáֽp׃"],[85,12,"גַּם־יְ֭הוָה יִתֵּ֣ן הַ⁠טּ֑וֹב וְ֝⁠אַרְצֵ֗⁠נוּ תִּתֵּ֥ן יְבוּלָֽ⁠הּ׃","gȧm-yĕ֭hwáh yiţé֣̇n ha⁠ṫ֑wòb wĕ֝⁠ʼarĕẕé֗⁠nẇ ţi̇ţé֥̇n yĕbẇláֽ⁠ḣ׃"],[85,13,"צֶ֭דֶק לְ⁠פָנָ֣י⁠ו יְהַלֵּ֑ךְ וְ⁠יָשֵׂ֖ם לְ⁠דֶ֣רֶךְ פְּעָמָֽי⁠ו׃","ẕe֭deq lĕ⁠páná֣y⁠w yĕhalé֑̇kĕ wĕ⁠yáşé֖̂m lĕ⁠de֣rekĕ pĕ̇ʻámáֽy⁠w׃"],[86,1,"תְּפִלָּ֗ה לְ⁠דָ֫וִ֥ד הַטֵּֽה־יְהוָ֣ה אָזְנְ⁠ךָ֣ עֲנֵ֑⁠נִי כִּֽי־עָנִ֖י וְ⁠אֶבְי֣וֹן אָֽנִי׃","ţĕ̇pilá̇֗h lĕ⁠dá֫wi֥d hatéֽ̇h-yĕhwá֣h ʼázĕnĕ⁠ká֣ ʻàné֑⁠niy kiֽ̇y-ʻáni֖y wĕ⁠ʼebĕy֣wòn ʼáֽniy׃"],[86,2,"שָֽׁמְרָ֣⁠ה נַפְשִׁ⁠י֮ כִּֽי־חָסִ֪יד אָ֥נִי הוֹשַׁ֣ע עַ֭בְדְּ⁠ךָ אַתָּ֣ה אֱלֹהַ֑⁠י הַ⁠בּוֹטֵ֥חַ אֵלֶֽי⁠ךָ׃","şáֽ̌mĕrá֣⁠h napĕşǐ⁠y֮ kiֽ̇y-ẖási֪yd ʼá֥niy hwòşǎ֣ʻ ʻa֭bĕdĕ̇⁠ká ʼaţá֣̇h ʼèlòha֑⁠y ha⁠ḃwòté֥ẖa ʼéleֽy⁠ká׃"],[86,3,"חָנֵּ֥⁠נִי אֲדֹנָ֑⁠י כִּ֥י אֵלֶ֥י⁠ךָ אֶ֝קְרָ֗א כָּל־הַ⁠יּֽוֹם׃","ẖáné֥̇⁠niy ʼàdòná֑⁠y ki֥̇y ʼéle֥y⁠ká ʼe֝qĕrá֗ʼ ká̇l-ha⁠ẏֽwòm׃"],[86,4,"שַׂ֭מֵּחַ נֶ֣פֶשׁ עַבְדֶּ֑⁠ךָ כִּ֥י אֵלֶ֥י⁠ךָ אֲ֝דֹנָ֗⁠י נַפְשִׁ֥⁠י אֶשָּֽׂא׃","şâ֭mé̇ẖa ne֣peş̌ ʻabĕdė֑⁠ká ki֥̇y ʼéle֥y⁠ká ʼà֝dòná֗⁠y napĕşǐ֥⁠y ʼeşáֽ̇̂ʼ׃"],[86,5,"כִּֽי־אַתָּ֣ה אֲ֭דֹנָ⁠י ט֣וֹב וְ⁠סַלָּ֑ח וְ⁠רַב־חֶ֝֗סֶד לְ⁠כָל־קֹרְאֶֽי⁠ךָ׃","kiֽ̇y-ʼaţá֣̇h ʼà֭dòná⁠y t֣wòb wĕ⁠salá֑̇ẖ wĕ⁠rab-ẖe֝֗sed lĕ⁠kál-qòrĕʼeֽy⁠ká׃"],[86,6,"הַאֲזִ֣ינָ⁠ה יְ֭הוָה תְּפִלָּתִ֑⁠י וְ֝⁠הַקְשִׁ֗יבָ⁠ה בְּ⁠ק֣וֹל תַּחֲנוּנוֹתָֽ⁠י׃","haʼàzi֣yná⁠h yĕ֭hwáh ţĕ̇pilá̇ţi֑⁠y wĕ֝⁠haqĕşǐ֗ybá⁠h bĕ̇⁠q֣wòl ţȧẖànẇnwòţáֽ⁠y׃"],[86,7,"בְּ⁠י֣וֹם צָ֭רָתִ֥⁠י אֶקְרָאֶ֗⁠ךָּ כִּ֣י תַעֲנֵֽ⁠נִי׃","bĕ̇⁠y֣wòm ẕá֭ráţi֥⁠y ʼeqĕráʼe֗⁠ká̇ ki֣̇y ţaʻànéֽ⁠niy׃"],[86,8,"אֵין־כָּמ֖וֹ⁠ךָ בָ⁠אֱלֹהִ֥ים ׀ אֲדֹנָ֗⁠י וְ⁠אֵ֣ין כְּֽ⁠מַעֲשֶֽׂי⁠ךָ׃","ʼéyn-ká̇m֖wò⁠ká bá⁠ʼèlòhi֥ym ׀ ʼàdòná֗⁠y wĕ⁠ʼé֣yn kĕֽ̇⁠maʻàşêֽy⁠ká׃"],[86,9,"כָּל־גּוֹיִ֤ם ׀ אֲשֶׁ֥ר עָשִׂ֗יתָ יָב֤וֹאוּ ׀ וְ⁠יִשְׁתַּחֲו֣וּ לְ⁠פָנֶ֣י⁠ךָ אֲדֹנָ֑⁠י וִֽ⁠יכַבְּד֣וּ לִ⁠שְׁמֶֽ⁠ךָ׃","ká̇l-ġwòyi֤m ׀ ʼàşě֥r ʻáşî֗yţá yáb֤wòʼẇ ׀ wĕ⁠yişĕ̌ţȧẖàw֣ẇ lĕ⁠páne֣y⁠ká ʼàdòná֑⁠y wiֽ⁠ykabĕ̇d֣ẇ li⁠şĕ̌meֽ⁠ká׃"],[86,10,"כִּֽי־גָד֣וֹל אַ֭תָּה וְ⁠עֹשֵׂ֣ה נִפְלָא֑וֹת אַתָּ֖ה אֱלֹהִ֣ים לְ⁠בַדֶּֽ⁠ךָ׃","kiֽ̇y-gád֣wòl ʼa֭ţá̇h wĕ⁠ʻòşé֣̂h nipĕláʼ֑wòţ ʼaţá֖̇h ʼèlòhi֣ym lĕ⁠badėֽ⁠ká׃"],[86,11,"ה֘וֹרֵ֤⁠נִי יְהוָ֨ה ׀ דַּרְכֶּ֗⁠ךָ אֲהַלֵּ֥ךְ בַּ⁠אֲמִתֶּ֑⁠ךָ יַחֵ֥ד לְ֝בָבִ֗⁠י לְ⁠יִרְאָ֥ה שְׁמֶֽ⁠ךָ׃","h֘wòré֤⁠niy yĕhwá֨h ׀ dȧrĕkė֗⁠ká ʼàhalé֥̇kĕ bȧ⁠ʼàmiţė֑⁠ká yaẖé֥d lĕ֝bábi֗⁠y lĕ⁠yirĕʼá֥h şĕ̌meֽ⁠ká׃"],[86,12,"אוֹדְ⁠ךָ֤ ׀ אֲדֹנָ֣⁠י אֱ֭לֹהַ⁠י בְּ⁠כָל־לְבָבִ֑⁠י וַ⁠אֲכַבְּדָ֖ה שִׁמְ⁠ךָ֣ לְ⁠עוֹלָֽם׃","ʼwòdĕ⁠ká֤ ׀ ʼàdòná֣⁠y ʼè֭lòha⁠y bĕ̇⁠kál-lĕbábi֑⁠y wa⁠ʼàkabĕ̇dá֖h şǐmĕ⁠ká֣ lĕ⁠ʻwòláֽm׃"],[86,13,"כִּֽי־חַ֭סְדְּ⁠ךָ גָּד֣וֹל עָלָ֑⁠י וְ⁠הִצַּ֥לְתָּ נַ֝פְשִׁ֗⁠י מִ⁠שְּׁא֥וֹל תַּחְתִּיָּֽה׃","kiֽ̇y-ẖa֭sĕdĕ̇⁠ká gá̇d֣wòl ʻálá֑⁠y wĕ⁠hiẕȧ֥lĕţá̇ na֝pĕşǐ֗⁠y mi⁠şĕ̇̌ʼ֥wòl ţȧẖĕţi̇ẏֽáh׃"],[86,14,"אֱלֹהִ֤ים ׀ זֵ֘דִ֤ים קָֽמוּ־עָלַ֗⁠י וַ⁠עֲדַ֣ת עָ֭רִיצִים בִּקְשׁ֣וּ נַפְשִׁ֑⁠י וְ⁠לֹ֖א שָׂמ֣וּ⁠ךָ לְ⁠נֶגְדָּֽ⁠ם׃","ʼèlòhi֤ym ׀ zé֘di֤ym qáֽmẇ-ʻála֗⁠y wa⁠ʻàda֣ţ ʻá֭riyẕiym bi̇qĕş֣̌ẇ napĕşǐ֑⁠y wĕ⁠lò֖ʼ şá̂m֣ẇ⁠ká lĕ⁠negĕdáֽ̇⁠m׃"],[86,15,"וְ⁠אַתָּ֣ה אֲ֭דֹנָ⁠י אֵל־רַח֣וּם וְ⁠חַנּ֑וּן אֶ֥רֶךְ אַ֝פַּ֗יִם וְ⁠רַב־חֶ֥סֶד וֶ⁠אֱמֶֽת׃","wĕ⁠ʼaţá֣̇h ʼà֭dòná⁠y ʼél-raẖ֣ẇm wĕ⁠ẖaṅ֑ẇn ʼe֥rekĕ ʼa֝pȧ֗yim wĕ⁠rab-ẖe֥sed we⁠ʼèmeֽţ׃"],[86,16,"פְּנֵ֥ה אֵלַ֗⁠י וְ⁠חָ֫נֵּ֥⁠נִי תְּנָֽ⁠ה־עֻזְּ⁠ךָ֥ לְ⁠עַבְדֶּ֑⁠ךָ וְ֝⁠הוֹשִׁ֗יעָ⁠ה לְ⁠בֶן־אֲמָתֶֽ⁠ךָ׃","pĕ̇né֥h ʼéla֗⁠y wĕ⁠ẖá֫né֥̇⁠niy ţĕ̇náֽ⁠h-ʻuzĕ̇⁠ká֥ lĕ⁠ʻabĕdė֑⁠ká wĕ֝⁠hwòşǐ֗yʻá⁠h lĕ⁠ben-ʼàmáţeֽ⁠ká׃"],[86,17,"עֲשֵֽׂה־עִמִּ֥⁠י א֗וֹת לְ⁠ט֫וֹבָ֥ה וְ⁠יִרְא֣וּ שֹׂנְאַ֣⁠י וְ⁠יֵבֹ֑שׁוּ כִּֽי־אַתָּ֥ה יְ֝הוָ֗ה עֲזַרְתַּ֥⁠נִי וְ⁠נִחַמְתָּֽ⁠נִי׃","ʻàşéֽ̂h-ʻimi֥̇⁠y ʼ֗wòţ lĕ⁠t֫wòbá֥h wĕ⁠yirĕʼ֣ẇ şò̂nĕʼa֣⁠y wĕ⁠yébò֑ş̌ẇ kiֽ̇y-ʼaţá֥̇h yĕ֝hwá֗h ʻàzarĕţȧ֥⁠niy wĕ⁠niẖamĕţáֽ̇⁠niy׃"],[87,1,"לִ⁠בְנֵי־קֹ֭רַח מִזְמ֣וֹר שִׁ֑יר יְ֝סוּדָת֗⁠וֹ בְּ⁠הַרְרֵי־קֹֽדֶשׁ׃","li⁠bĕnéy-qò֭raẖ mizĕm֣wòr şǐ֑yr yĕ֝sẇdáţ֗⁠wò bĕ̇⁠harĕréy-qòֽdeş̌׃"],[87,2,"אֹהֵ֣ב יְ֭הוָה שַׁעֲרֵ֣י צִיּ֑וֹן מִ֝⁠כֹּ֗ל מִשְׁכְּנ֥וֹת יַעֲקֹֽב׃","ʼòhé֣b yĕ֭hwáh şǎʻàré֣y ẕiẏ֑wòn mi֝⁠kò̇֗l mişĕ̌kĕ̇n֥wòţ yaʻàqòֽb׃"],[87,3,"נִ֭כְבָּדוֹת מְדֻבָּ֣ר בָּ֑⁠ךְ עִ֖יר הָ⁠אֱלֹהִ֣ים סֶֽלָה׃","ni֭kĕbá̇dwòţ mĕdubá֣̇r bá֑̇⁠kĕ ʻi֖yr há⁠ʼèlòhi֣ym seֽláh׃"],[87,4,"אַזְכִּ֤יר ׀ רַ֥הַב וּ⁠בָבֶ֗ל לְֽ⁠יֹ֫דְעָ֥⁠י הִנֵּ֤ה פְלֶ֣שֶׁת וְ⁠צ֣וֹר עִם־כּ֑וּשׁ זֶ֝֗ה יֻלַּד־שָֽׁם׃","ʼazĕki֤̇yr ׀ ra֥hab ẇ⁠bábe֗l lĕֽ⁠yò֫dĕʻá֥⁠y hiné֤̇h pĕle֣şěţ wĕ⁠ẕ֣wòr ʻim-k֑̇ẇş̌ ze֝֗h yulȧd-şáֽ̌m׃"],[87,5,"וּֽ⁠לֲ⁠צִיּ֨וֹן ׀ יֵאָמַ֗ר אִ֣ישׁ וְ֭⁠אִישׁ יֻלַּד־בָּ֑⁠הּ וְ⁠ה֖וּא יְכוֹנְנֶ֣⁠הָ עֶלְיֽוֹן׃","ẇֽ⁠là⁠ẕiẏ֨wòn ׀ yéʼáma֗r ʼi֣yş̌ wĕ֭⁠ʼiyş̌ yulȧd-bá֑̇⁠ḣ wĕ⁠h֖ẇʼ yĕkwònĕne֣⁠há ʻelĕyֽwòn׃"],[87,6,"יְֽהוָ֗ה יִ֭סְפֹּר בִּ⁠כְת֣וֹב עַמִּ֑ים זֶ֖ה יֻלַּד־שָׁ֣ם סֶֽלָה׃","yĕֽhwá֗h yi֭sĕpò̇r bi̇⁠kĕţ֣wòb ʻami֑̇ym ze֖h yulȧd-şá֣̌m seֽláh׃"],[87,7,"וְ⁠שָׁרִ֥ים כְּ⁠חֹלְלִ֑ים כָּֽל־מַעְיָנַ֥⁠י בָּֽ⁠ךְ׃","wĕ⁠şá̌ri֥ym kĕ̇⁠ẖòlĕli֑ym káֽ̇l-maʻĕyána֥⁠y báֽ̇⁠kĕ׃"],[88,1,"יְ֭הוָה אֱלֹהֵ֣י יְשׁוּעָתִ֑⁠י יוֹם־צָעַ֖קְתִּי בַ⁠לַּ֣יְלָה נֶגְדֶּֽ⁠ךָ׃","yĕ֭hwáh ʼèlòhé֣y yĕş̌ẇʻáţi֑⁠y ywòm-ẕáʻa֖qĕţi̇y ba⁠lȧ֣yĕláh negĕdėֽ⁠ká׃"],[88,2,"תָּב֣וֹא לְ֭⁠פָנֶי⁠ךָ תְּפִלָּתִ֑⁠י הַטֵּֽה־אָ֝זְנְ⁠ךָ֗ לְ⁠רִנָּתִֽ⁠י׃","ţá̇b֣wòʼ lĕ֭⁠páney⁠ká ţĕ̇pilá̇ţi֑⁠y hatéֽ̇h-ʼá֝zĕnĕ⁠ká֗ lĕ⁠riná̇ţiֽ⁠y׃"],[88,3,"כִּֽי־שָֽׂבְעָ֣ה בְ⁠רָע֣וֹת נַפְשִׁ֑⁠י וְ⁠חַיַּ֗⁠י לִ⁠שְׁא֥וֹל הִגִּֽיעוּ׃","kiֽ̇y-şáֽ̂bĕʻá֣h bĕ⁠ráʻ֣wòţ napĕşǐ֑⁠y wĕ⁠ẖayȧ֗⁠y li⁠şĕ̌ʼ֥wòl higiֽ̇yʻẇ׃"],[88,4,"נֶ֭חְשַׁבְתִּי עִם־י֣וֹרְדֵי ב֑וֹר הָ֝יִ֗יתִי כְּ⁠גֶ֣בֶר אֵֽין־אֱיָֽל׃","ne֭ẖĕşǎbĕţi̇y ʻim-y֣wòrĕdéy b֑wòr há֝yi֗yţiy kĕ̇⁠ge֣ber ʼéֽyn-ʼèyáֽl׃"],[88,5,"בַּ⁠מֵּתִ֗ים חָ֫פְשִׁ֥י כְּמ֤וֹ חֲלָלִ֨ים ׀ שֹׁ֥כְבֵי קֶ֗בֶר אֲשֶׁ֤ר לֹ֣א זְכַרְתָּ֣⁠ם ע֑וֹד וְ֝⁠הֵ֗מָּה מִ⁠יָּדְ⁠ךָ֥ נִגְזָֽרוּ׃","bȧ⁠mé̇ţi֗ym ẖá֫pĕşǐ֥y kĕ̇m֤wò ẖàláli֨ym ׀ şò֥̌kĕbéy qe֗ber ʼàşě֤r lò֣ʼ zĕkarĕţá֣̇⁠m ʻ֑wòd wĕ֝⁠hé֗má̇h mi⁠yá̇dĕ⁠ká֥ nigĕzáֽrẇ׃"],[88,6,"שַׁ֭תַּ⁠נִי בְּ⁠ב֣וֹר תַּחְתִּיּ֑וֹת בְּ֝⁠מַחֲשַׁכִּ֗ים בִּ⁠מְצֹלֽוֹת׃","şǎ֭ţȧ⁠niy bĕ̇⁠b֣wòr ţȧẖĕţi̇ẏ֑wòţ bĕ̇֝⁠maẖàşǎki̇֗ym bi̇⁠mĕẕòlֽwòţ׃"],[88,7,"עָ֭לַ⁠י סָמְכָ֣ה חֲמָתֶ֑⁠ךָ וְ⁠כָל־מִ֝שְׁבָּרֶ֗י⁠ךָ עִנִּ֥יתָ סֶּֽלָה׃","ʻá֭la⁠y sámĕká֣h ẖàmáţe֑⁠ká wĕ⁠kál-mi֝şĕ̌bá̇re֗y⁠ká ʻini֥̇yţá sėֽláh׃"],[88,8,"הִרְחַ֥קְתָּ מְיֻדָּעַ֗⁠י מִ֫מֶּ֥⁠נִּי שַׁתַּ֣⁠נִי תוֹעֵב֣וֹת לָ֑⁠מוֹ כָּ֝לֻ֗א וְ⁠לֹ֣א אֵצֵֽא׃","hirĕẖa֥qĕţá̇ mĕyudá̇ʻa֗⁠y mi֫mė֥⁠ni̇y şǎţȧ֣⁠niy ţwòʻéb֣wòţ lá֑⁠mwò ká̇֝lu֗ʼ wĕ⁠lò֣ʼ ʼéẕéֽʼ׃"],[88,9,"עֵינִ֥⁠י דָאֲבָ֗ה מִנִּ֫י עֹ֥נִי קְרָאתִ֣י⁠ךָ יְהוָ֣ה בְּ⁠כָל־י֑וֹם שִׁטַּ֖חְתִּי אֵלֶ֣י⁠ךָ כַפָּֽ⁠י׃","ʻéyni֥⁠y dáʼàbá֗h mini̇֫y ʻò֥niy qĕráʼţi֣y⁠ká yĕhwá֣h bĕ̇⁠kál-y֑wòm şǐtȧ֖ẖĕţi̇y ʼéle֣y⁠ká kapáֽ̇⁠y׃"],[88,10,"הֲ⁠לַ⁠מֵּתִ֥ים תַּעֲשֶׂה־פֶּ֑לֶא אִם־רְ֝פָאִ֗ים יָק֤וּמוּ ׀ יוֹד֬וּ⁠ךָ סֶּֽלָה׃","hà⁠la⁠mé̇ţi֥ym ţȧʻàşêh-pė֑leʼ ʼim-rĕ֝páʼi֗ym yáq֤ẇmẇ ׀ ywòd֬ẇ⁠ká sėֽláh׃"],[88,11,"הַ⁠יְסֻפַּ֣ר בַּ⁠קֶּ֣בֶר חַסְדֶּ֑⁠ךָ אֱ֝מֽוּנָתְ⁠ךָ֗ בָּ⁠אֲבַדּֽוֹן׃","ha⁠yĕsupȧ֣r bȧ⁠qė֣ber ẖasĕdė֑⁠ká ʼè֝mֽẇnáţĕ⁠ká֗ bá̇⁠ʼàbaḋֽwòn׃"],[88,12,"הֲ⁠יִוָּדַ֣ע בַּ⁠חֹ֣שֶׁךְ פִּלְאֶ֑⁠ךָ וְ֝⁠צִדְקָתְ⁠ךָ֗ בְּ⁠אֶ֣רֶץ נְשִׁיָּֽה׃","hà⁠yiwá̇da֣ʻ bȧ⁠ẖò֣şěkĕ pi̇lĕʼe֑⁠ká wĕ֝⁠ẕidĕqáţĕ⁠ká֗ bĕ̇⁠ʼe֣reẕ nĕşǐyáֽ̇h׃"],[88,13,"וַ⁠אֲנִ֤י ׀ אֵלֶ֣י⁠ךָ יְהוָ֣ה שִׁוַּ֑עְתִּי וּ֝⁠בַ⁠בֹּ֗קֶר תְּֽפִלָּתִ֥⁠י תְקַדְּמֶֽ⁠ךָּ׃","wa⁠ʼàni֤y ׀ ʼéle֣y⁠ká yĕhwá֣h şǐwȧ֑ʻĕţi̇y ẇ֝⁠ba⁠bò̇֗qer ţĕֽ̇pilá̇ţi֥⁠y ţĕqadĕ̇meֽ⁠ká̇׃"],[88,14,"לָ⁠מָ֣ה יְ֭הוָה תִּזְנַ֣ח נַפְשִׁ֑⁠י תַּסְתִּ֖יר פָּנֶ֣י⁠ךָ מִמֶּֽ⁠נִּי׃","lá⁠má֣h yĕ֭hwáh ţi̇zĕna֣ẖ napĕşǐ֑⁠y ţȧsĕţi֖̇yr pá̇ne֣y⁠ká mimėֽ⁠ni̇y׃"],[88,15,"עָ֘נִ֤י אֲנִ֣י וְ⁠גֹוֵ֣עַ מִ⁠נֹּ֑עַר נָשָׂ֖אתִי אֵמֶ֣י⁠ךָ אָפֽוּנָה׃","ʻá֘ni֤y ʼàni֣y wĕ⁠gòwé֣ʻa mi⁠nò֑̇ʻar náşá֖̂ʼţiy ʼéme֣y⁠ká ʼápֽẇnáh׃"],[88,16,"עָ֭לַ⁠י עָבְר֣וּ חֲרוֹנֶ֑י⁠ךָ בִּ֝עוּתֶ֗י⁠ךָ צִמְּתוּתֻֽ⁠נִי׃","ʻá֭la⁠y ʻábĕr֣ẇ ẖàrwòne֑y⁠ká bi̇֝ʻẇţe֗y⁠ká ẕimĕ̇ţẇţuֽ⁠niy׃"],[88,17,"סַבּ֣וּ⁠נִי כַ֭⁠מַּיִם כָּל־הַ⁠יּ֑וֹם הִקִּ֖יפוּ עָלַ֣⁠י יָֽחַד׃","saḃ֣ẇ⁠niy ka֭⁠mȧyim ká̇l-ha⁠ẏ֑wòm hiqi֖̇ypẇ ʻála֣⁠y yáֽẖad׃"],[88,18,"הִרְחַ֣קְתָּ מִ֭מֶּ⁠נִּי אֹהֵ֣ב וָ⁠רֵ֑עַ מְֽיֻדָּעַ֥⁠י מַחְשָֽׁךְ׃","hirĕẖa֣qĕţá̇ mi֭mė⁠ni̇y ʼòhé֣b wá⁠ré֑ʻa mĕֽyudá̇ʻa֥⁠y maẖĕşáֽ̌kĕ׃"],[89,1,"חַֽסְדֵ֣י יְ֭הוָה עוֹלָ֣ם אָשִׁ֑ירָה לְ⁠דֹ֥ר וָ⁠דֹ֓ר ׀ אוֹדִ֖יעַ אֱמוּנָתְ⁠ךָ֣ בְּ⁠פִֽ⁠י׃","ẖaֽsĕdé֣y yĕ֭hwáh ʻwòlá֣m ʼáşǐ֑yráh lĕ⁠dò֥r wá⁠dò֓r ׀ ʼwòdi֖yʻa ʼèmẇnáţĕ⁠ká֣ bĕ̇⁠piֽ⁠y׃"],[89,2,"כִּֽי־אָמַ֗רְתִּי ע֭וֹלָם חֶ֣סֶד יִבָּנֶ֑ה שָׁמַ֓יִם ׀ תָּכִ֖ן אֱמוּנָתְ⁠ךָ֣ בָ⁠הֶֽם׃","kiֽ̇y-ʼáma֗rĕţi̇y ʻ֭wòlám ẖe֣sed yibá̇ne֑h şá̌ma֓yim ׀ ţá̇ki֖n ʼèmẇnáţĕ⁠ká֣ bá⁠heֽm׃"],[89,3,"כָּרַ֣תִּֽי בְ֭רִית לִ⁠בְחִירִ֑⁠י נִ֝שְׁבַּ֗עְתִּי לְ⁠דָוִ֥ד עַבְדִּֽ⁠י׃","ká̇ra֣ţiֽ̇y bĕ֭riyţ li⁠bĕẖiyri֑⁠y ni֝şĕ̌bȧ֗ʻĕţi̇y lĕ⁠dáwi֥d ʻabĕdiֽ̇⁠y׃"],[89,4,"עַד־ע֭וֹלָם אָכִ֣ין זַרְעֶ֑⁠ךָ וּ⁠בָנִ֨יתִי לְ⁠דֹר־וָ⁠ד֖וֹר כִּסְאֲ⁠ךָ֣ סֶֽלָה׃","ʻad-ʻ֭wòlám ʼáki֣yn zarĕʻe֑⁠ká ẇ⁠báni֨yţiy lĕ⁠dòr-wá⁠d֖wòr ki̇sĕʼà⁠ká֣ seֽláh׃"],[89,5,"וְ⁠י֘וֹד֤וּ שָׁמַ֣יִם פִּלְאֲ⁠ךָ֣ יְהוָ֑ה אַף־אֱ֝מֽוּנָתְ⁠ךָ֗ בִּ⁠קְהַ֥ל קְדֹשִֽׁים׃","wĕ⁠y֘wòd֤ẇ şá̌ma֣yim pi̇lĕʼà⁠ká֣ yĕhwá֑h ʼap-ʼè֝mֽẇnáţĕ⁠ká֗ bi̇⁠qĕha֥l qĕdòşǐֽym׃"],[89,6,"כִּ֤י מִ֣י בַ֭⁠שַּׁחַק יַעֲרֹ֣ךְ לַ⁠יהוָ֑ה יִדְמֶ֥ה לַ֝⁠יהוָ֗ה בִּ⁠בְנֵ֥י אֵלִים׃","ki֤̇y mi֣y ba֭⁠şȧ̌ẖaq yaʻàrò֣kĕ la⁠yhwá֑h yidĕme֥h la֝⁠yhwá֗h bi̇⁠bĕné֥y ʼéliym׃"],[89,7,"אֵ֣ל נַ֭עֲרָץ בְּ⁠סוֹד־קְדֹשִׁ֣ים רַבָּ֑ה וְ֝⁠נוֹרָ֗א עַל־כָּל־סְבִיבָֽי⁠ו׃","ʼé֣l na֭ʻàráẕ bĕ̇⁠swòd-qĕdòşǐ֣ym rabá֑̇h wĕ֝⁠nwòrá֗ʼ ʻal-ká̇l-sĕbiybáֽy⁠w׃"],[89,8,"יְהוָ֤ה ׀ אֱלֹ֘הֵ֤י צְבָא֗וֹת מִֽי־כָֽמ֖וֹ⁠ךָ חֲסִ֥ין ׀ יָ֑הּ וֶ֝⁠אֱמֽוּנָתְ⁠ךָ֗ סְבִיבוֹתֶֽי⁠ךָ׃","yĕhwá֤h ׀ ʼèlò֘hé֤y ẕĕbáʼ֗wòţ miֽy-káֽm֖wò⁠ká ẖàsi֥yn ׀ yá֑ḣ we֝⁠ʼèmֽẇnáţĕ⁠ká֗ sĕbiybwòţeֽy⁠ká׃"],[89,9,"אַתָּ֣ה מ֭וֹשֵׁל בְּ⁠גֵא֣וּת הַ⁠יָּ֑ם בְּ⁠שׂ֥וֹא גַ֝לָּ֗י⁠ו אַתָּ֥ה תְשַׁבְּחֵֽ⁠ם׃","ʼaţá֣̇h m֭wòşé̌l bĕ̇⁠géʼ֣ẇţ ha⁠yá֑̇m bĕ̇⁠ş֥̂wòʼ ga֝lá̇֗y⁠w ʼaţá֥̇h ţĕşǎbĕ̇ẖéֽ⁠m׃"],[89,10,"אַתָּ֤ה דִכִּ֣אתָ כֶ⁠חָלָ֣ל רָ֑הַב בִּ⁠זְר֥וֹעַ עֻ֝זְּ⁠ךָ֗ פִּזַּ֥רְתָּ אוֹיְבֶֽי⁠ךָ׃","ʼaţá֤̇h diki֣̇ʼţá ke⁠ẖálá֣l rá֑hab bi̇⁠zĕr֥wòʻa ʻu֝zĕ̇⁠ká֗ pi̇zȧ֥rĕţá̇ ʼwòyĕbeֽy⁠ká׃"],[89,11,"לְ⁠ךָ֣ שָׁ֭מַיִם אַף־לְ⁠ךָ֥ אָ֑רֶץ תֵּבֵ֥ל וּ֝⁠מְלֹאָ֗⁠הּ אַתָּ֥ה יְסַדְתָּֽ⁠ם׃","lĕ⁠ká֣ şá֭̌mayim ʼap-lĕ⁠ká֥ ʼá֑reẕ ţé̇bé֥l ẇ֝⁠mĕlòʼá֗⁠ḣ ʼaţá֥̇h yĕsadĕţáֽ̇⁠m׃"],[89,12,"צָפ֣וֹן וְ֭⁠יָמִין אַתָּ֣ה בְרָאתָ֑⁠ם תָּב֥וֹר וְ֝⁠חֶרְמ֗וֹן בְּ⁠שִׁמְ⁠ךָ֥ יְרַנֵּֽנוּ׃","ẕáp֣wòn wĕ֭⁠yámiyn ʼaţá֣̇h bĕráʼţá֑⁠m ţá̇b֥wòr wĕ֝⁠ẖerĕm֗wòn bĕ̇⁠şǐmĕ⁠ká֥ yĕranéֽ̇nẇ׃"],[89,13,"לְ⁠ךָ֣ זְ֭רוֹעַ עִם־גְּבוּרָ֑ה תָּעֹ֥ז יָ֝דְ⁠ךָ֗ תָּר֥וּם יְמִינֶֽ⁠ךָ׃","lĕ⁠ká֣ zĕ֭rwòʻa ʻim-gĕ̇bẇrá֑h ţá̇ʻò֥z yá֝dĕ⁠ká֗ ţá̇r֥ẇm yĕmiyneֽ⁠ká׃"],[89,14,"צֶ֣דֶק וּ֭⁠מִשְׁפָּט מְכ֣וֹן כִּסְאֶ֑⁠ךָ חֶ֥סֶד וֶ֝⁠אֱמֶ֗ת יְֽקַדְּמ֥וּ פָנֶֽי⁠ךָ׃","ẕe֣deq ẇ֭⁠mişĕ̌pá̇t mĕk֣wòn ki̇sĕʼe֑⁠ká ẖe֥sed we֝⁠ʼème֗ţ yĕֽqadĕ̇m֥ẇ páneֽy⁠ká׃"],[89,15,"אַשְׁרֵ֣י הָ֭⁠עָם יוֹדְעֵ֣י תְרוּעָ֑ה יְ֝הוָ֗ה בְּֽ⁠אוֹר־פָּנֶ֥י⁠ךָ יְהַלֵּכֽוּ⁠ן׃","ʼaşĕ̌ré֣y há֭⁠ʻám ywòdĕʻé֣y ţĕrẇʻá֑h yĕ֝hwá֗h bĕֽ̇⁠ʼwòr-pá̇ne֥y⁠ká yĕhalé̇kֽẇ⁠n׃"],[89,16,"בְּ֭⁠שִׁמְ⁠ךָ יְגִיל֣וּ⁠ן כָּל־הַ⁠יּ֑וֹם וּ⁠בְ⁠צִדְקָתְ⁠ךָ֥ יָרֽוּמוּ׃","bĕ֭̇⁠şǐmĕ⁠ká yĕgiyl֣ẇ⁠n ká̇l-ha⁠ẏ֑wòm ẇ⁠bĕ⁠ẕidĕqáţĕ⁠ká֥ yárֽẇmẇ׃"],[89,17,"כִּֽי־תִפְאֶ֣רֶת עֻזָּ֣⁠מוֹ אָ֑תָּה וּ֝⁠בִ⁠רְצֹנְ⁠ךָ֗ תרים קַרְנֵֽ⁠נוּ׃","kiֽ̇y-ţipĕʼe֣reţ ʻuzá֣̇⁠mwò ʼá֑ţá̇h ẇ֝⁠bi⁠rĕẕònĕ⁠ká֗ ţrym qarĕnéֽ⁠nẇ׃"],[89,18,"כִּ֣י לַֽ֭⁠יהוָה מָֽגִנֵּ֑⁠נוּ וְ⁠לִ⁠קְד֖וֹשׁ יִשְׂרָאֵ֣ל מַלְכֵּֽ⁠נוּ׃","ki֣̇y laֽ֭⁠yhwáh máֽginé֑̇⁠nẇ wĕ⁠li⁠qĕd֖wòş̌ yişĕ̂ráʼé֣l malĕkéֽ̇⁠nẇ׃"],[89,19,"אָ֤ז דִּבַּ֥רְתָּֽ־בְ⁠חָ֡זוֹן לַֽ⁠חֲסִידֶ֗י⁠ךָ וַ⁠תֹּ֗אמֶר שִׁוִּ֣יתִי עֵ֭זֶר עַל־גִּבּ֑וֹר הֲרִימ֖וֹתִי בָח֣וּר מֵ⁠עָֽם׃","ʼá֤z di̇bȧ֥rĕţáֽ̇-bĕ⁠ẖá֡zwòn laֽ⁠ẖàsiyde֗y⁠ká wa⁠ţò̇֗ʼmer şǐwi֣̇yţiy ʻé֭zer ʻal-gi̇ḃ֑wòr hàriym֖wòţiy báẖ֣ẇr mé⁠ʻáֽm׃"],[89,20,"מָ֭צָאתִי דָּוִ֣ד עַבְדִּ֑⁠י בְּ⁠שֶׁ֖מֶן קָדְשִׁ֣⁠י מְשַׁחְתִּֽי⁠ו׃","má֭ẕáʼţiy dá̇wi֣d ʻabĕdi֑̇⁠y bĕ̇⁠şě֖men qádĕşǐ֣⁠y mĕşǎẖĕţiֽ̇y⁠w׃"],[89,21,"אֲשֶׁ֣ר יָ֭דִ⁠י תִּכּ֣וֹן עִמּ֑⁠וֹ אַף־זְרוֹעִ֥⁠י תְאַמְּצֶֽ⁠נּוּ׃","ʼàşě֣r yá֭di⁠y ţi̇k֣̇wòn ʻiṁ֑⁠wò ʼap-zĕrwòʻi֥⁠y ţĕʼamĕ̇ẕeֽ⁠ṅẇ׃"],[89,22,"לֹֽא־יַשִּׁ֣א אוֹיֵ֣ב בּ֑⁠וֹ וּ⁠בֶן־עַ֝וְלָ֗ה לֹ֣א יְעַנֶּֽ⁠נּוּ׃","lòֽʼ-yaşi֣̇̌ʼ ʼwòyé֣b ḃ֑⁠wò ẇ⁠ben-ʻa֝wĕlá֗h lò֣ʼ yĕʻanėֽ⁠ṅẇ׃"],[89,23,"וְ⁠כַתּוֹתִ֣י מִ⁠פָּנָ֣י⁠ו צָרָ֑י⁠ו וּ⁠מְשַׂנְאָ֥י⁠ו אֶגּֽוֹף׃","wĕ⁠kaţ̇wòţi֣y mi⁠pá̇ná֣y⁠w ẕárá֑y⁠w ẇ⁠mĕşânĕʼá֥y⁠w ʼeġֽwòp׃"],[89,24,"וֶֽ⁠אֶֽמוּנָתִ֣⁠י וְ⁠חַסְדִּ֣⁠י עִמּ֑⁠וֹ וּ֝⁠בִ⁠שְׁמִ֗⁠י תָּר֥וּם קַרְנֽ⁠וֹ׃","weֽ⁠ʼeֽmẇnáţi֣⁠y wĕ⁠ẖasĕdi֣̇⁠y ʻiṁ֑⁠wò ẇ֝⁠bi⁠şĕ̌mi֗⁠y ţá̇r֥ẇm qarĕnֽ⁠wò׃"],[89,25,"וְ⁠שַׂמְתִּ֣י בַ⁠יָּ֣ם יָד֑⁠וֹ וּֽ⁠בַ⁠נְּהָר֥וֹת יְמִינֽ⁠וֹ׃","wĕ⁠şâmĕţi֣̇y ba⁠yá֣̇m yád֑⁠wò ẇֽ⁠ba⁠nĕ̇hár֥wòţ yĕmiynֽ⁠wò׃"],[89,26,"ה֣וּא יִ֭קְרָאֵ⁠נִי אָ֣בִ⁠י אָ֑תָּה אֵ֝לִ֗⁠י וְ⁠צ֣וּר יְשׁוּעָתִֽ⁠י׃","h֣ẇʼ yi֭qĕráʼé⁠niy ʼá֣bi⁠y ʼá֑ţá̇h ʼé֝li֗⁠y wĕ⁠ẕ֣ẇr yĕş̌ẇʻáţiֽ⁠y׃"],[89,27,"אַף־אָ֭נִי בְּכ֣וֹר אֶתְּנֵ֑⁠הוּ עֶ֝לְי֗וֹן לְ⁠מַלְכֵי־אָֽרֶץ׃","ʼap-ʼá֭niy bĕ̇k֣wòr ʼeţĕ̇né֑⁠hẇ ʻe֝lĕy֗wòn lĕ⁠malĕkéy-ʼáֽreẕ׃"],[89,28,"לְ֭⁠עוֹלָ֗ם אשמור־ל֣⁠וֹ חַסְדִּ֑⁠י וּ֝⁠בְרִיתִ֗⁠י נֶאֱמֶ֥נֶת לֽ⁠וֹ׃","lĕ֭⁠ʻwòlá֗m ʼşmwr-l֣⁠wò ẖasĕdi֑̇⁠y ẇ֝⁠bĕriyţi֗⁠y neʼème֥neţ lֽ⁠wò׃"],[89,29,"וְ⁠שַׂמְתִּ֣י לָ⁠עַ֣ד זַרְע֑⁠וֹ וְ֝⁠כִסְא֗⁠וֹ כִּ⁠ימֵ֥י שָׁמָֽיִם׃","wĕ⁠şâmĕţi֣̇y lá⁠ʻa֣d zarĕʻ֑⁠wò wĕ֝⁠kisĕʼ֗⁠wò ki̇⁠ymé֥y şá̌máֽyim׃"],[89,30,"אִם־יַֽעַזְב֣וּ בָ֭נָי⁠ו תּוֹרָתִ֑⁠י וּ֝⁠בְ⁠מִשְׁפָּטַ֗⁠י לֹ֣א יֵלֵכֽוּ⁠ן׃","ʼim-yaֽʻazĕb֣ẇ bá֭náy⁠w ţ̇wòráţi֑⁠y ẇ֝⁠bĕ⁠mişĕ̌pá̇ta֗⁠y lò֣ʼ yélékֽẇ⁠n׃"],[89,31,"אִם־חֻקֹּתַ֥⁠י יְחַלֵּ֑לוּ וּ֝⁠מִצְוֺתַ֗⁠י לֹ֣א יִשְׁמֹֽרוּ׃","ʼim-ẖuqò̇ţa֥⁠y yĕẖalé֑̇lẇ ẇ֝⁠miẕĕwֺţa֗⁠y lò֣ʼ yişĕ̌mòֽrẇ׃"],[89,32,"וּ⁠פָקַדְתִּ֣י בְ⁠שֵׁ֣בֶט פִּשְׁעָ֑⁠ם וּ⁠בִ⁠נְגָעִ֥ים עֲוֺנָֽ⁠ם׃","ẇ⁠páqadĕţi֣̇y bĕ⁠şé֣̌bet pi̇şĕ̌ʻá֑⁠m ẇ⁠bi⁠nĕgáʻi֥ym ʻàwֺnáֽ⁠m׃"],[89,33,"וְ֭⁠חַסְדִּ⁠י לֹֽא־אָפִ֣יר מֵֽ⁠עִמּ֑⁠וֹ וְ⁠לֹֽא־אֲ֝שַׁקֵּ֗ר בֶּ⁠אֱמוּנָתִֽ⁠י׃","wĕ֭⁠ẖasĕdi̇⁠y lòֽʼ-ʼápi֣yr méֽ⁠ʻiṁ֑⁠wò wĕ⁠lòֽʼ-ʼà֝şǎqé̇֗r bė⁠ʼèmẇnáţiֽ⁠y׃"],[89,34,"לֹא־אֲחַלֵּ֥ל בְּרִיתִ֑⁠י וּ⁠מוֹצָ֥א שְׂ֝פָתַ֗⁠י לֹ֣א אֲשַׁנֶּֽה׃","lòʼ-ʼàẖalé֥̇l bĕ̇riyţi֑⁠y ẇ⁠mwòẕá֥ʼ şĕ̂֝páţa֗⁠y lò֣ʼ ʼàşǎnėֽh׃"],[89,35,"אַ֭חַת נִשְׁבַּ֣עְתִּי בְ⁠קָדְשִׁ֑⁠י אִֽם־לְ⁠דָוִ֥ד אֲכַזֵּֽב׃","ʼa֭ẖaţ nişĕ̌bȧ֣ʻĕţi̇y bĕ⁠qádĕşǐ֑⁠y ʼiֽm-lĕ⁠dáwi֥d ʼàkazéֽ̇b׃"],[89,36,"זַ֭רְע⁠וֹ לְ⁠עוֹלָ֣ם יִהְיֶ֑ה וְ⁠כִסְא֖⁠וֹ כַ⁠שֶּׁ֣מֶשׁ נֶגְדִּֽ⁠י׃","za֭rĕʻ⁠wò lĕ⁠ʻwòlá֣m yihĕye֑h wĕ⁠kisĕʼ֖⁠wò ka⁠şė֣̌meş̌ negĕdiֽ̇⁠y׃"],[89,37,"כְּ֭⁠יָרֵחַ יִכּ֣וֹן עוֹלָ֑ם וְ⁠עֵ֥ד בַּ֝⁠שַּׁ֗חַק נֶאֱמָ֥ן סֶֽלָה׃","kĕ֭̇⁠yáréẖa yik֣̇wòn ʻwòlá֑m wĕ⁠ʻé֥d bȧ֝⁠şȧ̌֗ẖaq neʼèmá֥n seֽláh׃"],[89,38,"וְ⁠אַתָּ֣ה זָ֭נַחְתָּ וַ⁠תִּמְאָ֑ס הִ֝תְעַבַּ֗רְתָּ עִם־מְשִׁיחֶֽ⁠ךָ׃","wĕ⁠ʼaţá֣̇h zá֭naẖĕţá̇ wa⁠ţi̇mĕʼá֑s hi֝ţĕʻabȧ֗rĕţá̇ ʻim-mĕşǐyẖeֽ⁠ká׃"],[89,39,"נֵ֭אַרְתָּה בְּרִ֣ית עַבְדֶּ֑⁠ךָ חִלַּ֖לְתָּ לָ⁠אָ֣רֶץ נִזְרֽ⁠וֹ׃","né֭ʼarĕţá̇h bĕ̇ri֣yţ ʻabĕdė֑⁠ká ẖilȧ֖lĕţá̇ lá⁠ʼá֣reẕ nizĕrֽ⁠wò׃"],[89,40,"פָּרַ֥צְתָּ כָל־גְּדֵרֹתָ֑י⁠ו שַׂ֖מְתָּ מִבְצָרָ֣י⁠ו מְחִתָּה׃","pá̇ra֥ẕĕţá̇ kál-gĕ̇déròţá֑y⁠w şâ֖mĕţá̇ mibĕẕárá֣y⁠w mĕẖiţá̇h׃"],[89,41,"שַׁ֭סֻּ⁠הוּ כָּל־עֹ֣בְרֵי דָ֑רֶךְ הָיָ֥ה חֶ֝רְפָּ֗ה לִ⁠שְׁכֵנָֽי⁠ו׃","şǎ֭su̇⁠hẇ ká̇l-ʻò֣bĕréy dá֑rekĕ háyá֥h ẖe֝rĕpá̇֗h li⁠şĕ̌kénֽáy⁠w׃"],[89,42,"הֲ֭רִימוֹתָ יְמִ֣ין צָרָ֑י⁠ו הִ֝שְׂמַ֗חְתָּ כָּל־אוֹיְבָֽי⁠ו׃","hà֭riymwòţá yĕmi֣yn ẕárá֑y⁠w hi֝şĕ̂ma֗ẖĕţá̇ ká̇l-ʼwòyĕbáֽy⁠w׃"],[89,43,"אַף־תָּ֭שִׁיב צ֣וּר חַרְבּ֑⁠וֹ וְ⁠לֹ֥א הֲ֝קֵימֹת֗⁠וֹ בַּ⁠מִּלְחָמָֽה׃","ʼap-ţá֭̇şǐyb ẕ֣ẇr ẖarĕḃ֑⁠wò wĕ⁠lò֥ʼ hà֝qéymòţ֗⁠wò bȧ⁠mi̇lĕẖámáֽh׃"],[89,44,"הִשְׁבַּ֥תָּ מִ⁠טְּהָר֑⁠וֹ וְ֝⁠כִסְא֗⁠וֹ לָ⁠אָ֥רֶץ מִגַּֽרְתָּה׃","hişĕ̌bȧ֥ţá̇ mi⁠tĕ̇hár֑⁠wò wĕ֝⁠kisĕʼ֗⁠wò lá⁠ʼá֥reẕ migȧֽrĕţá̇h׃"],[89,45,"הִ֭קְצַרְתָּ יְמֵ֣י עֲלוּמָ֑י⁠ו הֶֽעֱטִ֨יתָ עָלָ֖י⁠ו בּוּשָׁ֣ה סֶֽלָה׃","hi֭qĕẕarĕţá̇ yĕmé֣y ʻàlẇmá֑y⁠w heֽʻèti֨yţá ʻálá֖y⁠w ḃẇşá֣̌h seֽláh׃"],[89,46,"עַד־מָ֣ה יְ֭הוָה תִּסָּתֵ֣ר לָ⁠נֶ֑צַח תִּבְעַ֖ר כְּמוֹ־אֵ֣שׁ חֲמָתֶֽ⁠ךָ׃","ʻad-má֣h yĕ֭hwáh ţi̇sá̇ţé֣r lá⁠ne֑ẕaẖ ţi̇bĕʻa֖r kĕ̇mwò-ʼé֣ş̌ ẖàmáţeֽ⁠ká׃"],[89,47,"זְכָר־אֲנִ֥י מֶה־חָ֑לֶד עַל־מַה־שָּׁ֝֗וְא בָּרָ֥אתָ כָל־בְּנֵי־אָדָֽם׃","zĕkár-ʼàni֥y meh-ẖá֑led ʻal-mah-şá̇̌֝֗wĕʼ bá̇rá֥ʼţá kál-bĕ̇néy-ʼádáֽm׃"],[89,48,"מִ֤י גֶ֣בֶר יִֽ֭חְיֶה וְ⁠לֹ֣א יִרְאֶה־מָּ֑וֶת יְמַלֵּ֨ט נַפְשׁ֖⁠וֹ מִ⁠יַּד־שְׁא֣וֹל סֶֽלָה׃","mi֤y ge֣ber yiֽ֭ẖĕyeh wĕ⁠lò֣ʼ yirĕʼeh-má֑̇weţ yĕmalé̇֨t napĕş֖̌⁠wò mi⁠yȧd-şĕ̌ʼ֣wòl seֽláh׃"],[89,49,"אַיֵּ֤ה ׀ חֲסָדֶ֖י⁠ךָ הָ⁠רִאשֹׁנִ֥ים ׀ אֲדֹנָ֑⁠י נִשְׁבַּ֥עְתָּ לְ֝⁠דָוִ֗ד בֶּ⁠אֱמוּנָתֶֽ⁠ךָ׃","ʼayé֤̇h ׀ ẖàsáde֖y⁠ká há⁠riʼşò̌ni֥ym ׀ ʼàdòná֑⁠y nişĕ̌bȧ֥ʻĕţá̇ lĕ֝⁠dáwi֗d bė⁠ʼèmẇnáţeֽ⁠ká׃"],[89,50,"זְכֹ֣ר אֲ֭דֹנָ⁠י חֶרְפַּ֣ת עֲבָדֶ֑י⁠ךָ שְׂאֵתִ֥⁠י בְ֝⁠חֵיקִ֗⁠י כָּל־רַבִּ֥ים עַמִּֽים׃","zĕkò֣r ʼà֭dòná⁠y ẖerĕpȧ֣ţ ʻàbáde֑y⁠ká şĕ̂ʼéţi֥⁠y bĕ֝⁠ẖéyqi֗⁠y ká̇l-rabi֥̇ym ʻamiֽ̇ym׃"],[89,51,"אֲשֶׁ֤ר חֵרְפ֖וּ אוֹיְבֶ֥י⁠ךָ ׀ יְהוָ֑ה אֲשֶׁ֥ר חֵ֝רְפ֗וּ עִקְּב֥וֹת מְשִׁיחֶֽ⁠ךָ׃","ʼàşě֤r ẖérĕp֖ẇ ʼwòyĕbe֥y⁠ká ׀ yĕhwá֑h ʼàşě֥r ẖé֝rĕp֗ẇ ʻiqĕ̇b֥wòţ mĕşǐyẖeֽ⁠ká׃"],[89,52,"בָּר֖וּךְ יְהוָ֥ה לְ֝⁠עוֹלָ֗ם אָ֘מֵ֥ן ׀ וְ⁠אָמֵֽן׃","bá̇r֖ẇkĕ yĕhwá֥h lĕ֝⁠ʻwòlá֗m ʼá֘mé֥n ׀ wĕ⁠ʼáméֽn׃"],[90,1,"אֲֽדֹנָ֗⁠י מָע֣וֹן אַ֭תָּה הָיִ֥יתָ לָּ֗⁠נוּ בְּ⁠דֹ֣ר וָ⁠דֹֽר׃","ʼàֽdòná֗⁠y máʻ֣wòn ʼa֭ţá̇h háyi֥yţá lá̇֗⁠nẇ bĕ̇⁠dò֣r wá⁠dòֽr׃"],[90,2,"בְּ⁠טֶ֤רֶם ׀ הָ֘רִ֤ים יֻלָּ֗דוּ וַ⁠תְּח֣וֹלֵֽל אֶ֣רֶץ וְ⁠תֵבֵ֑ל וּֽ⁠מֵ⁠עוֹלָ֥ם עַד־ע֝וֹלָ֗ם אַתָּ֥ה אֵֽל׃","bĕ̇⁠te֤rem ׀ há֘ri֤ym yulá̇֗dẇ wa⁠ţĕ̇ẖ֣wòléֽl ʼe֣reẕ wĕ⁠ţébé֑l ẇֽ⁠mé⁠ʻwòlá֥m ʻad-ʻ֝wòlá֗m ʼaţá֥̇h ʼéֽl׃"],[90,3,"תָּשֵׁ֣ב אֱ֭נוֹשׁ עַד־דַּכָּ֑א וַ֝⁠תֹּ֗אמֶר שׁ֣וּבוּ בְנֵי־אָדָֽם׃","ţá̇şé֣̌b ʼè֭nwòş̌ ʻad-dȧká֑̇ʼ wa֝⁠ţò̇֗ʼmer ş֣̌ẇbẇ bĕnéy-ʼádáֽm׃"],[90,4,"כִּ֤י אֶ֪לֶף שָׁנִ֡ים בְּֽ⁠עֵינֶ֗י⁠ךָ כְּ⁠י֣וֹם אֶ֭תְמוֹל כִּ֣י יַעֲבֹ֑ר וְ⁠אַשְׁמוּרָ֥ה בַ⁠לָּֽיְלָה׃","ki֤̇y ʼe֪lep şá̌ni֡ym bĕֽ̇⁠ʻéyne֗y⁠ká kĕ̇⁠y֣wòm ʼe֭ţĕmwòl ki֣̇y yaʻàbò֑r wĕ⁠ʼaşĕ̌mẇrá֥h ba⁠láֽ̇yĕláh׃"],[90,5,"זְ֭רַמְתָּ⁠ם שֵׁנָ֣ה יִהְי֑וּ בַּ֝⁠בֹּ֗קֶר כֶּ⁠חָצִ֥יר יַחֲלֹֽף׃","zĕ֭ramĕţá̇⁠m şé̌ná֣h yihĕy֑ẇ bȧ֝⁠bò̇֗qer kė⁠ẖáẕi֥yr yaẖàlòֽp׃"],[90,6,"בַּ֭⁠בֹּקֶר יָצִ֣יץ וְ⁠חָלָ֑ף לָ֝⁠עֶ֗רֶב יְמוֹלֵ֥ל וְ⁠יָבֵֽשׁ׃","bȧ֭⁠bò̇qer yáẕi֣yẕ wĕ⁠ẖálá֑p lá֝⁠ʻe֗reb yĕmwòlé֥l wĕ⁠yábéֽş̌׃"],[90,7,"כִּֽי־כָלִ֥ינוּ בְ⁠אַפֶּ֑⁠ךָ וּֽ⁠בַ⁠חֲמָתְ⁠ךָ֥ נִבְהָֽלְנוּ׃","kiֽ̇y-káli֥ynẇ bĕ⁠ʼapė֑⁠ká ẇֽ⁠ba⁠ẖàmáţĕ⁠ká֥ nibĕháֽlĕnẇ׃"],[90,8,"שת עֲוֺנֹתֵ֣י⁠נוּ לְ⁠נֶגְדֶּ֑⁠ךָ עֲ֝לֻמֵ֗⁠נוּ לִ⁠מְא֥וֹר פָּנֶֽי⁠ךָ׃","şţ ʻàwֺnòţé֣y⁠nẇ lĕ⁠negĕdė֑⁠ká ʻà֝lumé֗⁠nẇ li⁠mĕʼ֥wòr pá̇neֽy⁠ká׃"],[90,9,"כִּ֣י כָל־יָ֭מֵי⁠נוּ פָּנ֣וּ בְ⁠עֶבְרָתֶ֑⁠ךָ כִּלִּ֖ינוּ שָׁנֵ֣י⁠נוּ כְמוֹ־הֶֽגֶה׃","ki֣̇y kál-yá֭méy⁠nẇ pá̇n֣ẇ bĕ⁠ʻebĕráţe֑⁠ká ki̇li֖̇ynẇ şá̌né֣y⁠nẇ kĕmwò-heֽgeh׃"],[90,10,"יְמֵֽי־שְׁנוֹתֵ֨י⁠נוּ בָ⁠הֶ֥ם שִׁבְעִ֪ים שָׁנָ֡ה וְ⁠אִ֤ם בִּ⁠גְבוּרֹ֨ת ׀ שְׁמ֘וֹנִ֤ים שָׁנָ֗ה וְ֭⁠רָהְבָּ⁠ם עָמָ֣ל וָ⁠אָ֑וֶן כִּי־גָ֥ז חִ֝֗ישׁ וַ⁠נָּעֻֽפָ⁠ה׃","yĕméֽy-şĕ̌nwòţé֨y⁠nẇ bá⁠he֥m şǐbĕʻi֪ym şá̌ná֡h wĕ⁠ʼi֤m bi̇⁠gĕbẇrò֨ţ ׀ şĕ̌m֘wòni֤ym şá̌ná֗h wĕ֭⁠ráhĕbá̇⁠m ʻámá֣l wá⁠ʼá֑wen ki̇y-gá֥z ẖi֝֗yş̌ wa⁠ná̇ʻuֽpá⁠h׃"],[90,11,"מִֽי־י֭וֹדֵעַ עֹ֣ז אַפֶּ֑⁠ךָ וּ֝⁠כְ⁠יִרְאָתְ⁠ךָ֗ עֶבְרָתֶֽ⁠ךָ׃","miֽy-y֭wòdéʻa ʻò֣z ʼapė֑⁠ká ẇ֝⁠kĕ⁠yirĕʼáţĕ⁠ká֗ ʻebĕráţeֽ⁠ká׃"],[90,12,"לִ⁠מְנ֣וֹת יָ֭מֵי⁠נוּ כֵּ֣ן הוֹדַ֑ע וְ֝⁠נָבִ֗א לְבַ֣ב חָכְמָֽה׃","li⁠mĕn֣wòţ yá֭méy⁠nẇ ké֣̇n hwòda֑ʻ wĕ֝⁠nábi֗ʼ lĕba֣b ẖákĕmáֽh׃"],[90,13,"שׁוּבָ֣⁠ה יְ֭הוָה עַד־מָתָ֑י וְ֝⁠הִנָּחֵ֗ם עַל־עֲבָדֶֽי⁠ךָ׃","ş̌ẇbá֣⁠h yĕ֭hwáh ʻad-máţá֑y wĕ֝⁠hiná̇ẖé֗m ʻal-ʻàbádeֽy⁠ká׃"],[90,14,"שַׂבְּעֵ֣⁠נוּ בַ⁠בֹּ֣קֶר חַסְדֶּ֑⁠ךָ וּֽ⁠נְרַנְּנָ֥ה וְ֝⁠נִשְׂמְחָ֗ה בְּ⁠כָל־יָמֵֽי⁠נוּ׃","şâbĕ̇ʻé֣⁠nẇ ba⁠bò֣̇qer ẖasĕdė֑⁠ká ẇֽ⁠nĕranĕ̇ná֥h wĕ֝⁠nişĕ̂mĕẖá֗h bĕ̇⁠kál-yáméֽy⁠nẇ׃"],[90,15,"שַׂ֭מְּחֵ⁠נוּ כִּ⁠ימ֣וֹת עִנִּיתָ֑⁠נוּ שְׁ֝נ֗וֹת רָאִ֥ינוּ רָעָֽה׃","şâ֭mĕ̇ẖé⁠nẇ ki̇⁠ym֣wòţ ʻini̇yţá֑⁠nẇ şĕ̌֝n֗wòţ ráʼi֥ynẇ ráʻáֽh׃"],[90,16,"יֵרָאֶ֣ה אֶל־עֲבָדֶ֣י⁠ךָ פָעֳלֶ֑⁠ךָ וַ֝⁠הֲדָרְ⁠ךָ֗ עַל־בְּנֵי⁠הֶֽם׃","yéráʼe֣h ʼel-ʻàbáde֣y⁠ká páʻole֑⁠ká wa֝⁠hàdárĕ⁠ká֗ ʻal-bĕ̇néy⁠heֽm׃"],[90,17,"וִ⁠יהִ֤י ׀ נֹ֤עַם אֲדֹנָ֥⁠י אֱלֹהֵ֗י⁠נוּ עָ֫לֵ֥י⁠נוּ וּ⁠מַעֲשֵׂ֣ה יָ֭דֵי⁠נוּ כּוֹנְנָ֥⁠ה עָלֵ֑י⁠נוּ וּֽ⁠מַעֲשֵׂ֥ה יָ֝דֵ֗י⁠נוּ כּוֹנְנֵֽ⁠הוּ׃","wi⁠yhi֤y ׀ nò֤ʻam ʼàdòná֥⁠y ʼèlòhé֗y⁠nẇ ʻá֫lé֥y⁠nẇ ẇ⁠maʻàşé֣̂h yá֭déy⁠nẇ k̇wònĕná֥⁠h ʻálé֑y⁠nẇ ẇֽ⁠maʻàşé֥̂h yá֝dé֗y⁠nẇ k̇wònĕnéֽ⁠hẇ׃"],[91,1,"יֹ֭שֵׁב בְּ⁠סֵ֣תֶר עֶלְי֑וֹן בְּ⁠צֵ֥ל שַׁ֝דַּ֗י יִתְלוֹנָֽן׃","yò֭şé̌b bĕ̇⁠sé֣ţer ʻelĕy֑wòn bĕ̇⁠ẕé֥l şǎ֝dȧ֗y yiţĕlwònáֽn׃"],[91,2,"אֹמַ֗ר לַֽ֭⁠יהוָה מַחְסִ֣⁠י וּ⁠מְצוּדָתִ֑⁠י אֱ֝לֹהַ֗⁠י אֶבְטַח־בּֽ⁠וֹ׃","ʼòma֗r laֽ֭⁠yhwáh maẖĕsi֣⁠y ẇ⁠mĕẕẇdáţi֑⁠y ʼè֝lòha֗⁠y ʼebĕtaẖ-ḃֽ⁠wò׃"],[91,3,"כִּ֤י ה֣וּא יַ֭צִּֽילְ⁠ךָ מִ⁠פַּ֥ח יָק֗וּשׁ מִ⁠דֶּ֥בֶר הַוּֽוֹת׃","ki֤̇y h֣ẇʼ ya֭ẕiֽ̇ylĕ⁠ká mi⁠pȧ֥ẖ yáq֗ẇş̌ mi⁠dė֥ber haẇֽwòţ׃"],[91,4,"בְּ⁠אֶבְרָת֨⁠וֹ ׀ יָ֣סֶךְ לָ֭⁠ךְ וְ⁠תַֽחַת־כְּנָפָ֣י⁠ו תֶּחְסֶ֑ה צִנָּ֖ה וְֽ⁠סֹחֵרָ֣ה אֲמִתּֽ⁠וֹ׃","bĕ̇⁠ʼebĕráţ֨⁠wò ׀ yá֣sekĕ lá֭⁠kĕ wĕ⁠ţaֽẖaţ-kĕ̇nápá֣y⁠w ţėẖĕse֑h ẕiná֖̇h wĕֽ⁠sòẖérá֣h ʼàmiţֽ̇⁠wò׃"],[91,5,"לֹא־תִ֭ירָא מִ⁠פַּ֣חַד לָ֑יְלָה מֵ֝⁠חֵ֗ץ יָע֥וּף יוֹמָֽם׃","lòʼ-ţi֭yráʼ mi⁠pȧ֣ẖad lá֑yĕláh mé֝⁠ẖé֗ẕ yáʻ֥ẇp ywòmáֽm׃"],[91,6,"מִ֭⁠דֶּבֶר בָּ⁠אֹ֣פֶל יַהֲלֹ֑ךְ מִ֝⁠קֶּ֗טֶב יָשׁ֥וּד צָהֳרָֽיִם׃","mi֭⁠dėber bá̇⁠ʼò֣pel yahàlò֑kĕ mi֝⁠qė֗teb yáş֥̌ẇd ẕáhoráֽyim׃"],[91,7,"יִפֹּ֤ל מִ⁠צִּדְּ⁠ךָ֨ ׀ אֶ֗לֶף וּ⁠רְבָבָ֥ה מִ⁠ימִינֶ֑⁠ךָ אֵ֝לֶ֗י⁠ךָ לֹ֣א יִגָּֽשׁ׃","yipò֤̇l mi⁠ẕi̇dĕ̇⁠ká֨ ׀ ʼe֗lep ẇ⁠rĕbábá֥h mi⁠ymiyne֑⁠ká ʼé֝le֗y⁠ká lò֣ʼ yigáֽ̇ş̌׃"],[91,8,"רַ֭ק בְּ⁠עֵינֶ֣י⁠ךָ תַבִּ֑יט וְ⁠שִׁלֻּמַ֖ת רְשָׁעִ֣ים תִּרְאֶֽה׃","ra֭q bĕ̇⁠ʻéyne֣y⁠ká ţabi֑̇yt wĕ⁠şǐlu̇ma֖ţ rĕşá̌ʻi֣ym ţi̇rĕʼeֽh׃"],[91,9,"כִּֽי־אַתָּ֣ה יְהוָ֣ה מַחְסִ֑⁠י עֶ֝לְי֗וֹן שַׂ֣מְתָּ מְעוֹנֶֽ⁠ךָ׃","kiֽ̇y-ʼaţá֣̇h yĕhwá֣h maẖĕsi֑⁠y ʻe֝lĕy֗wòn şâ֣mĕţá̇ mĕʻwòneֽ⁠ká׃"],[91,10,"לֹֽא־תְאֻנֶּ֣ה אֵלֶ֣י⁠ךָ רָעָ֑ה וְ֝⁠נֶ֗גַע לֹא־יִקְרַ֥ב בְּ⁠אָהֳלֶֽ⁠ךָ׃","lòֽʼ-ţĕʼunė֣h ʼéle֣y⁠ká ráʻá֑h wĕ֝⁠ne֗gaʻ lòʼ-yiqĕra֥b bĕ̇⁠ʼáholeֽ⁠ká׃"],[91,11,"כִּ֣י מַ֭לְאָכָי⁠ו יְצַוֶּה־לָּ֑⁠ךְ לִ֝⁠שְׁמָרְ⁠ךָ֗ בְּ⁠כָל־דְּרָכֶֽי⁠ךָ׃","ki֣̇y ma֭lĕʼákáy⁠w yĕẕawėh-lá֑̇⁠kĕ li֝⁠şĕ̌márĕ⁠ká֗ bĕ̇⁠kál-dĕ̇rákeֽy⁠ká׃"],[91,12,"עַל־כַּפַּ֥יִם יִשָּׂא֑וּ⁠נְ⁠ךָ פֶּן־תִּגֹּ֖ף בָּ⁠אֶ֣בֶן רַגְלֶֽ⁠ךָ׃","ʻal-kȧpȧ֥yim yişá̇̂ʼ֑ẇ⁠nĕ⁠ká pėn-ţi̇gò֖̇p bá̇⁠ʼe֣ben ragĕleֽ⁠ká׃"],[91,13,"עַל־שַׁ֣חַל וָ⁠פֶ֣תֶן תִּדְרֹ֑ךְ תִּרְמֹ֖ס כְּפִ֣יר וְ⁠תַנִּֽין׃","ʻal-şǎ֣ẖal wá⁠pe֣ţen ţi̇dĕrò֑kĕ ţi̇rĕmò֖s kĕ̇pi֣yr wĕ⁠ţaniֽ̇yn׃"],[91,14,"כִּ֤י בִ֣⁠י חָ֭שַׁק וַ⁠אֲפַלְּטֵ֑⁠הוּ אֲ֝שַׂגְּבֵ֗⁠הוּ כִּֽי־יָדַ֥ע שְׁמִֽ⁠י׃","ki֤̇y bi֣⁠y ẖá֭şǎq wa⁠ʼàpalĕ̇té֑⁠hẇ ʼà֝şâgĕ̇bé֗⁠hẇ kiֽ̇y-yáda֥ʻ şĕ̌miֽ⁠y׃"],[91,15,"יִקְרָאֵ֨⁠נִי ׀ וְֽ⁠אֶעֱנֵ֗⁠הוּ עִמּֽ⁠וֹ־אָנֹכִ֥י בְ⁠צָרָ֑ה אֲ֝חַלְּצֵ֗⁠הוּ וַֽ⁠אֲכַבְּדֵֽ⁠הוּ׃","yiqĕráʼé֨⁠niy ׀ wĕֽ⁠ʼeʻèné֗⁠hẇ ʻiṁֽ⁠wò-ʼánòki֥y bĕ⁠ẕárá֑h ʼà֝ẖalĕ̇ẕé֗⁠hẇ waֽ⁠ʼàkabĕ̇déֽ⁠hẇ׃"],[91,16,"אֹ֣רֶךְ יָ֭מִים אַשְׂבִּיעֵ֑⁠הוּ וְ֝⁠אַרְאֵ֗⁠הוּ בִּֽ⁠ישׁוּעָתִֽ⁠י׃","ʼò֣rekĕ yá֭miym ʼaşĕ̂bi̇yʻé֑⁠hẇ wĕ֝⁠ʼarĕʼé֗⁠hẇ biֽ̇⁠yş̌ẇʻáţiֽ⁠y׃"],[92,1,"ט֗וֹב לְ⁠הֹד֥וֹת לַ⁠יהוָ֑ה וּ⁠לְ⁠זַמֵּ֖ר לְ⁠שִׁמְ⁠ךָ֣ עֶלְיֽוֹן׃","t֗wòb lĕ⁠hòd֥wòţ la⁠yhwá֑h ẇ⁠lĕ⁠zamé֖̇r lĕ⁠şǐmĕ⁠ká֣ ʻelĕyֽwòn׃"],[92,2,"לְ⁠הַגִּ֣יד בַּ⁠בֹּ֣קֶר חַסְֽדֶּ֑⁠ךָ וֶ֝⁠אֱמֽוּנָתְ⁠ךָ֗ בַּ⁠לֵּילֽוֹת׃","lĕ⁠hagi֣̇yd bȧ⁠bò֣̇qer ẖasĕֽdė֑⁠ká we֝⁠ʼèmֽẇnáţĕ⁠ká֗ bȧ⁠lé̇ylֽwòţ׃"],[92,3,"עֲֽלֵי־עָ֭שׂוֹר וַ⁠עֲלֵי־נָ֑בֶל עֲלֵ֖י הִגָּי֣וֹן בְּ⁠כִנּֽוֹר׃","ʻàֽléy-ʻá֭ş̂wòr wa⁠ʻàléy-ná֑bel ʻàlé֖y higá̇y֣wòn bĕ̇⁠kiṅֽwòr׃"],[92,4,"כִּ֤י שִׂמַּחְתַּ֣⁠נִי יְהוָ֣ה בְּ⁠פָעֳלֶ֑⁠ךָ בְּֽ⁠מַעֲשֵׂ֖י יָדֶ֣י⁠ךָ אֲרַנֵּֽן׃","ki֤̇y şîmȧẖĕţȧ֣⁠niy yĕhwá֣h bĕ̇⁠páʻole֑⁠ká bĕֽ̇⁠maʻàşé֖̂y yáde֣y⁠ká ʼàranéֽ̇n׃"],[92,5,"מַה־גָּדְל֣וּ מַעֲשֶׂ֣י⁠ךָ יְהוָ֑ה מְ֝אֹ֗ד עָמְק֥וּ מַחְשְׁבֹתֶֽי⁠ךָ׃","mah-gá̇dĕl֣ẇ maʻàşê֣y⁠ká yĕhwá֑h mĕ֝ʼò֗d ʻámĕq֥ẇ maẖĕşĕ̌bòţeֽy⁠ká׃"],[92,6,"אִֽישׁ־בַּ֭עַר לֹ֣א יֵדָ֑ע וּ֝⁠כְסִ֗יל לֹא־יָבִ֥ין אֶת־זֹֽאת׃","ʼiֽyş̌-bȧ֭ʻar lò֣ʼ yédá֑ʻ ẇ֝⁠kĕsi֗yl lòʼ-yábi֥yn ʼeţ-zòֽʼţ׃"],[92,7,"בִּ⁠פְרֹ֤חַ רְשָׁעִ֨ים ׀ כְּמ֥וֹ עֵ֗שֶׂב וַ֭⁠יָּצִיצוּ כָּל־פֹּ֣עֲלֵי אָ֑וֶן לְ⁠הִשָּֽׁמְדָ֥⁠ם עֲדֵי־עַֽד׃","bi̇⁠pĕrò֤ẖa rĕşá̌ʻi֨ym ׀ kĕ̇m֥wò ʻé֗şêb wa֭⁠yá̇ẕiyẕẇ ká̇l-pò֣̇ʻàléy ʼá֑wen lĕ⁠hişáֽ̇̌mĕdá֥⁠m ʻàdéy-ʻaֽd׃"],[92,8,"וְ⁠אַתָּ֥ה מָר֗וֹם לְ⁠עֹלָ֥ם יְהוָֽה׃","wĕ⁠ʼaţá֥̇h már֗wòm lĕ⁠ʻòlá֥m yĕhwáֽh׃"],[92,9,"כִּ֤י הִנֵּ֪ה אֹיְבֶ֡י⁠ךָ ׀ יְֽהוָ֗ה כִּֽי־הִנֵּ֣ה אֹיְבֶ֣י⁠ךָ יֹאבֵ֑דוּ יִ֝תְפָּרְד֗וּ כָּל־פֹּ֥עֲלֵי אָֽוֶן׃","ki֤̇y hiné֪̇h ʼòyĕbe֡y⁠ká ׀ yĕֽhwá֗h kiֽ̇y-hiné֣̇h ʼòyĕbe֣y⁠ká yòʼbé֑dẇ yi֝ţĕpá̇rĕd֗ẇ ká̇l-pò֥̇ʻàléy ʼáֽwen׃"],[92,10,"וַ⁠תָּ֣רֶם כִּ⁠רְאֵ֣ים קַרְנִ֑⁠י בַּ֝לֹּתִ֗י בְּ⁠שֶׁ֣מֶן רַעֲנָֽן׃","wa⁠ţá֣̇rem ki̇⁠rĕʼé֣ym qarĕni֑⁠y bȧ֝lò̇ţi֗y bĕ̇⁠şě֣men raʻànáֽn׃"],[92,11,"וַ⁠תַּבֵּ֥ט עֵינִ֗⁠י בְּ⁠שׁ֫וּרָ֥⁠י בַּ⁠קָּמִ֖ים עָלַ֥⁠י מְרֵעִ֗ים תִּשְׁמַ֥עְנָה אָזְנָֽ⁠י׃","wa⁠ţȧbé֥̇t ʻéyni֗⁠y bĕ̇⁠ş̌֫ẇrá֥⁠y bȧ⁠qá̇mi֖ym ʻála֥⁠y mĕréʻi֗ym ţi̇şĕ̌ma֥ʻĕnáh ʼázĕnáֽ⁠y׃"],[92,12,"צַ֭דִּיק כַּ⁠תָּמָ֣ר יִפְרָ֑ח כְּ⁠אֶ֖רֶז בַּ⁠לְּבָנ֣וֹן יִשְׂגֶּֽה׃","ẕa֭di̇yq kȧ⁠ţá̇má֣r yipĕrá֑ẖ kĕ̇⁠ʼe֖rez bȧ⁠lĕ̇bán֣wòn yişĕ̂gėֽh׃"],[92,13,"שְׁ֭תוּלִים בְּ⁠בֵ֣ית יְהוָ֑ה בְּ⁠חַצְר֖וֹת אֱלֹהֵ֣י⁠נוּ יַפְרִֽיחוּ׃","şĕ֭̌ţẇliym bĕ̇⁠bé֣yţ yĕhwá֑h bĕ̇⁠ẖaẕĕr֖wòţ ʼèlòhé֣y⁠nẇ yapĕriֽyẖẇ׃"],[92,14,"ע֭וֹד יְנוּב֣וּ⁠ן בְּ⁠שֵׂיבָ֑ה דְּשֵׁנִ֖ים וְ⁠רַֽעֲנַנִּ֣ים יִהְיֽוּ׃","ʻ֭wòd yĕnẇb֣ẇ⁠n bĕ̇⁠şé̂ybá֑h dĕ̇şé̌ni֖ym wĕ⁠raֽʻànani֣̇ym yihĕyֽẇ׃"],[92,15,"לְ֭⁠הַגִּיד כִּֽי־יָשָׁ֣ר יְהוָ֑ה צ֝וּרִ֗⁠י וְֽ⁠לֹא־עלת⁠ה בּֽ⁠וֹ׃","lĕ֭⁠hagi̇yd kiֽ̇y-yáşá֣̌r yĕhwá֑h ẕ֝ẇri֗⁠y wĕֽ⁠lòʼ-ʻlţ⁠h ḃֽ⁠wò׃"],[93,1,"יְהוָ֣ה מָלָךְ֮ גֵּא֪וּת לָ֫בֵ֥שׁ לָבֵ֣שׁ יְ֭הוָה עֹ֣ז הִתְאַזָּ֑ר אַף־תִּכּ֥וֹן תֵּ֝בֵ֗ל בַּל־תִּמּֽוֹט׃","yĕhwá֣h málákĕ֮ gé̇ʼ֪ẇţ lá֫bé֥ş̌ lábé֣ş̌ yĕ֭hwáh ʻò֣z hiţĕʼazá֑̇r ʼap-ţi̇k֥̇wòn ţé̇֝bé֗l bȧl-ţi̇ṁֽwòt׃"],[93,2,"נָכ֣וֹן כִּסְאֲ⁠ךָ֣ מֵ⁠אָ֑ז מֵֽ⁠עוֹלָ֣ם אָֽתָּה׃","nák֣wòn ki̇sĕʼà⁠ká֣ mé⁠ʼá֑z méֽ⁠ʻwòlá֣m ʼáֽţá̇h׃"],[93,3,"נָשְׂא֤וּ נְהָר֨וֹת ׀ יְֽהוָ֗ה נָשְׂא֣וּ נְהָר֣וֹת קוֹלָ֑⁠ם יִשְׂא֖וּ נְהָר֣וֹת דָּכְיָֽ⁠ם׃","náşĕ̂ʼ֤ẇ nĕhár֨wòţ ׀ yĕֽhwá֗h náşĕ̂ʼ֣ẇ nĕhár֣wòţ qwòlá֑⁠m yişĕ̂ʼ֖ẇ nĕhár֣wòţ dá̇kĕyáֽ⁠m׃"],[93,4,"מִ⁠קֹּל֨וֹת ׀ מַ֤יִם רַבִּ֗ים אַדִּירִ֣ים מִשְׁבְּרֵי־יָ֑ם אַדִּ֖יר בַּ⁠מָּר֣וֹם יְהוָֽה׃","mi⁠qò̇l֨wòţ ׀ ma֤yim rabi̇֗ym ʼadi̇yri֣ym mişĕ̌bĕ̇réy-yá֑m ʼadi֖̇yr bȧ⁠má̇r֣wòm yĕhwáֽh׃"],[93,5,"עֵֽדֹתֶ֨י⁠ךָ ׀ נֶאֶמְנ֬וּ מְאֹ֗ד לְ⁠בֵיתְ⁠ךָ֥ נַאֲוָה־קֹ֑דֶשׁ יְ֝הוָ֗ה לְ⁠אֹ֣רֶךְ יָמִֽים׃","ʻéֽdòţe֨y⁠ká ׀ neʼemĕn֬ẇ mĕʼò֗d lĕ⁠béyţĕ⁠ká֥ naʼàwáh-qò֑deş̌ yĕ֝hwá֗h lĕ⁠ʼò֣rekĕ yámiֽym׃"],[94,1,"אֵל־נְקָמ֥וֹת יְהוָ֑ה אֵ֖ל נְקָמ֣וֹת הוֹפִֽיַע׃","ʼél-nĕqám֥wòţ yĕhwá֑h ʼé֖l nĕqám֣wòţ hwòpiֽyaʻ׃"],[94,2,"הִ֭נָּשֵׂא שֹׁפֵ֣ט הָ⁠אָ֑רֶץ הָשֵׁ֥ב גְּ֝מ֗וּל עַל־גֵּאִֽים׃","hi֭ná̇şé̂ʼ şò̌pé֣t há⁠ʼá֑reẕ háşé֥̌b gĕ̇֝m֗ẇl ʻal-gé̇ʼiֽym׃"],[94,3,"עַד־מָתַ֖י רְשָׁעִ֥ים ׀ יְהוָ֑ה עַד־מָ֝תַ֗י רְשָׁעִ֥ים יַעֲלֹֽזוּ׃","ʻad-máţa֖y rĕşá̌ʻi֥ym ׀ yĕhwá֑h ʻad-má֝ţa֗y rĕşá̌ʻi֥ym yaʻàlòֽzẇ׃"],[94,4,"יַבִּ֣יעוּ יְדַבְּר֣וּ עָתָ֑ק יִֽ֝תְאַמְּר֗וּ כָּל־פֹּ֥עֲלֵי אָֽוֶן׃","yabi֣̇yʻẇ yĕdabĕ̇r֣ẇ ʻáţá֑q yiֽ֝ţĕʼamĕ̇r֗ẇ ká̇l-pò֥̇ʻàléy ʼáֽwen׃"],[94,5,"עַמְּ⁠ךָ֣ יְהוָ֣ה יְדַכְּא֑וּ וְֽ⁠נַחֲלָתְ⁠ךָ֥ יְעַנּֽוּ׃","ʻamĕ̇⁠ká֣ yĕhwá֣h yĕdakĕ̇ʼ֑ẇ wĕֽ⁠naẖàláţĕ⁠ká֥ yĕʻaṅֽẇ׃"],[94,6,"אַ֭לְמָנָה וְ⁠גֵ֣ר יַהֲרֹ֑גוּ וִֽ⁠יתוֹמִ֣ים יְרַצֵּֽחוּ׃","ʼa֭lĕmánáh wĕ⁠gé֣r yahàrò֑gẇ wiֽ⁠yţwòmi֣ym yĕraẕéֽ̇ẖẇ׃"],[94,7,"וַ֭⁠יֹּ֣אמְרוּ לֹ֣א יִרְאֶה־יָּ֑הּ וְ⁠לֹא־יָ֝בִ֗ין אֱלֹהֵ֥י יַעֲקֹֽב׃","wa֭⁠yò֣̇ʼmĕrẇ lò֣ʼ yirĕʼeh-yá֑̇ḣ wĕ⁠lòʼ-yá֝bi֗yn ʼèlòhé֥y yaʻàqòֽb׃"],[94,8,"בִּ֭ינוּ בֹּעֲרִ֣ים בָּ⁠עָ֑ם וּ֝⁠כְסִילִ֗ים מָתַ֥י תַּשְׂכִּֽילוּ׃","bi֭̇ynẇ bò̇ʻàri֣ym bá̇⁠ʻá֑m ẇ֝⁠kĕsiyli֗ym máţa֥y ţȧşĕ̂kiֽ̇ylẇ׃"],[94,9,"הֲ⁠נֹ֣טַֽע אֹ֭זֶן הֲ⁠לֹ֣א יִשְׁמָ֑ע אִֽם־יֹ֥צֵֽר עַ֝֗יִן הֲ⁠לֹ֣א יַבִּֽיט׃","hà⁠nò֣taֽʻ ʼò֭zen hà⁠lò֣ʼ yişĕ̌má֑ʻ ʼiֽm-yò֥ẕéֽr ʻa֝֗yin hà⁠lò֣ʼ yabiֽ̇yt׃"],[94,10,"הֲ⁠יֹסֵ֣ר גּ֭וֹיִם הֲ⁠לֹ֣א יוֹכִ֑יחַ הַֽ⁠מְלַמֵּ֖ד אָדָ֣ם דָּֽעַת׃","hà⁠yòsé֣r ġ֭wòyim hà⁠lò֣ʼ ywòki֑yẖa haֽ⁠mĕlamé֖̇d ʼádá֣m dáֽ̇ʻaţ׃"],[94,11,"יְֽהוָ֗ה יֹ֭דֵעַ מַחְשְׁב֣וֹת אָדָ֑ם כִּי־הֵ֥מָּה הָֽבֶל׃","yĕֽhwá֗h yò֭déʻa maẖĕşĕ̌b֣wòţ ʼádá֑m ki̇y-hé֥má̇h háֽbel׃"],[94,12,"אַשְׁרֵ֤י ׀ הַ⁠גֶּ֣בֶר אֲשֶׁר־תְּיַסְּרֶ֣⁠נּוּ יָּ֑הּ וּֽ⁠מִ⁠תּוֹרָתְ⁠ךָ֥ תְלַמְּדֶֽ⁠נּוּ׃","ʼaşĕ̌ré֤y ׀ ha⁠gė֣ber ʼàşěr-ţĕ̇yasĕ̇re֣⁠ṅẇ yá֑̇ḣ ẇֽ⁠mi⁠ţ̇wòráţĕ⁠ká֥ ţĕlamĕ̇deֽ⁠ṅẇ׃"],[94,13,"לְ⁠הַשְׁקִ֣יט ל֭⁠וֹ מִ֣⁠ימֵי רָ֑ע עַ֤ד יִכָּרֶ֖ה לָ⁠רָשָׁ֣ע שָֽׁחַת׃","lĕ⁠haşĕ̌qi֣yt l֭⁠wò mi֣⁠yméy rá֑ʻ ʻa֤d yiká̇re֖h lá⁠ráşá֣̌ʻ şáֽ̌ẖaţ׃"],[94,14,"כִּ֤י ׀ לֹא־יִטֹּ֣שׁ יְהוָ֣ה עַמּ֑⁠וֹ וְ֝⁠נַחֲלָת֗⁠וֹ לֹ֣א יַעֲזֹֽב׃","ki֤̇y ׀ lòʼ-yitò֣̇ş̌ yĕhwá֣h ʻaṁ֑⁠wò wĕ֝⁠naẖàláţ֗⁠wò lò֣ʼ yaʻàzòֽb׃"],[94,15,"כִּֽי־עַד־צֶ֭דֶק יָשׁ֣וּב מִשְׁפָּ֑ט וְ֝⁠אַחֲרָ֗י⁠ו כָּל־יִשְׁרֵי־לֵֽב׃","kiֽ̇y-ʻad-ẕe֭deq yáş֣̌ẇb mişĕ̌pá֑̇t wĕ֝⁠ʼaẖàrá֗y⁠w ká̇l-yişĕ̌réy-léֽb׃"],[94,16,"מִֽי־יָק֣וּם לִ֭⁠י עִם־מְרֵעִ֑ים מִֽי־יִתְיַצֵּ֥ב לִ֝⁠י עִם־פֹּ֥עֲלֵי אָֽוֶן׃","miֽy-yáq֣ẇm li֭⁠y ʻim-mĕréʻi֑ym miֽy-yiţĕyaẕé֥̇b li֝⁠y ʻim-pò֥̇ʻàléy ʼáֽwen׃"],[94,17,"לוּלֵ֣י יְ֭הוָה עֶזְרָ֣תָ⁠ה לִּ֑⁠י כִּ⁠מְעַ֓ט ׀ שָֽׁכְנָ֖ה דוּמָ֣ה נַפְשִֽׁ⁠י׃","lẇlé֣y yĕ֭hwáh ʻezĕrá֣ţá⁠h li֑̇⁠y ki̇⁠mĕʻa֓t ׀ şáֽ̌kĕná֖h dẇmá֣h napĕşǐֽ⁠y׃"],[94,18,"אִם־אָ֭מַרְתִּי מָ֣טָה רַגְלִ֑⁠י חַסְדְּ⁠ךָ֥ יְ֝הוָ֗ה יִסְעָדֵֽ⁠נִי׃","ʼim-ʼá֭marĕţi̇y má֣táh ragĕli֑⁠y ẖasĕdĕ̇⁠ká֥ yĕ֝hwá֗h yisĕʻádéֽ⁠niy׃"],[94,19,"בְּ⁠רֹ֣ב שַׂרְעַפַּ֣⁠י בְּ⁠קִרְבִּ֑⁠י תַּ֝נְחוּמֶ֗י⁠ךָ יְֽשַׁעַשְׁע֥וּ נַפְשִֽׁ⁠י׃","bĕ̇⁠rò֣b şârĕʻapȧ֣⁠y bĕ̇⁠qirĕbi֑̇⁠y ţȧ֝nĕẖẇme֗y⁠ká yĕֽşǎʻaşĕ̌ʻ֥ẇ napĕşǐֽ⁠y׃"],[94,20,"הַֽ֭⁠יְחָבְרְ⁠ךָ כִּסֵּ֣א הַוּ֑וֹת יֹצֵ֖ר עָמָ֣ל עֲלֵי־חֹֽק׃","haֽ֭⁠yĕẖábĕrĕ⁠ká ki̇sé֣̇ʼ haẇ֑wòţ yòẕé֖r ʻámá֣l ʻàléy-ẖòֽq׃"],[94,21,"יָ֭גוֹדּוּ עַל־נֶ֣פֶשׁ צַדִּ֑יק וְ⁠דָ֖ם נָקִ֣י יַרְשִֽׁיעוּ׃","yá֭gwòḋẇ ʻal-ne֣peş̌ ẕadi֑̇yq wĕ⁠dá֖m náqi֣y yarĕşǐֽyʻẇ׃"],[94,22,"וַ⁠יְהִ֬י יְהוָ֣ה לִ֣⁠י לְ⁠מִשְׂגָּ֑ב וֵ֝⁠אלֹהַ֗⁠י לְ⁠צ֣וּר מַחְסִֽ⁠י׃","wa⁠yĕhi֬y yĕhwá֣h li֣⁠y lĕ⁠mişĕ̂gá֑̇b wé֝⁠ʼlòha֗⁠y lĕ⁠ẕ֣ẇr maẖĕsiֽ⁠y׃"],[94,23,"וַ⁠יָּ֤שֶׁב עֲלֵי⁠הֶ֨ם ׀ אֶת־אוֹנָ֗⁠ם וּ⁠בְ⁠רָעָתָ֥⁠ם יַצְמִיתֵ֑⁠ם יַ֝צְמִיתֵ֗⁠ם יְהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","wa⁠yá֤̇şěb ʻàléy⁠he֨m ׀ ʼeţ-ʼwòná֗⁠m ẇ⁠bĕ⁠ráʻáţá֥⁠m yaẕĕmiyţé֑⁠m ya֝ẕĕmiyţé֗⁠m yĕhwá֥h ʼèlòhéֽy⁠nẇ׃"],[95,1,"לְ֭כוּ נְרַנְּנָ֣ה לַ⁠יהוָ֑ה נָ֝רִ֗יעָה לְ⁠צ֣וּר יִשְׁעֵֽ⁠נוּ׃","lĕ֭kẇ nĕranĕ̇ná֣h la⁠yhwá֑h ná֝ri֗yʻáh lĕ⁠ẕ֣ẇr yişĕ̌ʻéֽ⁠nẇ׃"],[95,2,"נְקַדְּמָ֣ה פָנָ֣י⁠ו בְּ⁠תוֹדָ֑ה בִּ֝⁠זְמִר֗וֹת נָרִ֥יעַֽ לֽ⁠וֹ׃","nĕqadĕ̇má֣h páná֣y⁠w bĕ̇⁠ţwòdá֑h bi̇֝⁠zĕmir֗wòţ nári֥yʻaֽ lֽ⁠wò׃"],[95,3,"כִּ֤י אֵ֣ל גָּד֣וֹל יְהוָ֑ה וּ⁠מֶ֥לֶךְ גָּ֝ד֗וֹל עַל־כָּל־אֱלֹהִֽים׃","ki֤̇y ʼé֣l gá̇d֣wòl yĕhwá֑h ẇ⁠me֥lekĕ gá̇֝d֗wòl ʻal-ká̇l-ʼèlòhiֽym׃"],[95,4,"אֲשֶׁ֣ר בְּ֭⁠יָד⁠וֹ מֶחְקְרֵי־אָ֑רֶץ וְ⁠תוֹעֲפ֖וֹת הָרִ֣ים לֽ⁠וֹ׃","ʼàşě֣r bĕ֭̇⁠yád⁠wò meẖĕqĕréy-ʼá֑reẕ wĕ⁠ţwòʻàp֖wòţ hári֣ym lֽ⁠wò׃"],[95,5,"אֲשֶׁר־ל֣⁠וֹ הַ֭⁠יָּם וְ⁠ה֣וּא עָשָׂ֑⁠הוּ וְ֝⁠יַבֶּ֗שֶׁת יָדָ֥י⁠ו יָצָֽרוּ׃","ʼàşěr-l֣⁠wò ha֭⁠yá̇m wĕ⁠h֣ẇʼ ʻáşá֑̂⁠hẇ wĕ֝⁠yabė֗şěţ yádá֥y⁠w yáẕáֽrẇ׃"],[95,6,"בֹּ֭אוּ נִשְׁתַּחֲוֶ֣ה וְ⁠נִכְרָ֑עָה נִ֝בְרְכָ֗ה לִֽ⁠פְנֵי־יְהוָ֥ה עֹשֵֽׂ⁠נוּ׃","bò֭̇ʼẇ nişĕ̌ţȧẖàwe֣h wĕ⁠nikĕrá֑ʻáh ni֝bĕrĕká֗h liֽ⁠pĕnéy-yĕhwá֥h ʻòşéֽ̂⁠nẇ׃"],[95,7,"כִּ֘י ה֤וּא אֱלֹהֵ֗י⁠נוּ וַ⁠אֲנַ֤חְנוּ עַ֣ם מַ֭רְעִית⁠וֹ וְ⁠צֹ֣אן יָד֑⁠וֹ הַ֝⁠יּ֗וֹם אִֽם־בְּ⁠קֹל֥⁠וֹ תִשְׁמָֽעוּ׃","ki̇֘y h֤ẇʼ ʼèlòhé֗y⁠nẇ wa⁠ʼàna֤ẖĕnẇ ʻa֣m ma֭rĕʻiyţ⁠wò wĕ⁠ẕò֣ʼn yád֑⁠wò ha֝⁠ẏ֗wòm ʼiֽm-bĕ̇⁠qòl֥⁠wò ţişĕ̌máֽʻẇ׃"],[95,8,"אַל־תַּקְשׁ֣וּ לְ֭בַבְ⁠כֶם כִּ⁠מְרִיבָ֑ה כְּ⁠י֥וֹם מַ֝סָּ֗ה בַּ⁠מִּדְבָּֽר׃","ʼal-ţȧqĕş֣̌ẇ lĕ֭babĕ⁠kem ki̇⁠mĕriybá֑h kĕ̇⁠y֥wòm ma֝sá̇֗h bȧ⁠mi̇dĕbáֽ̇r׃"],[95,9,"אֲשֶׁ֣ר נִ֭סּוּ⁠נִי אֲבוֹתֵי⁠כֶ֑ם בְּ֝חָנ֗וּ⁠נִי גַּם־רָא֥וּ פָעֳלִֽ⁠י׃","ʼàşě֣r ni֭ṡẇ⁠niy ʼàbwòţéy⁠ke֑m bĕ̇֝ẖán֗ẇ⁠niy gȧm-ráʼ֥ẇ páʻolֽi⁠y׃"],[95,10,"אַרְבָּ֘עִ֤ים שָׁנָ֨ה ׀ אָ֘ק֤וּט בְּ⁠ד֗וֹר וָ⁠אֹמַ֗ר עַ֤ם תֹּעֵ֣י לֵבָ֣ב הֵ֑ם וְ֝⁠הֵ֗ם לֹא־יָדְע֥וּ דְרָכָֽ⁠י׃","ʼarĕbá̇֘ʻi֤ym şá̌ná֨h ׀ ʼá֘q֤ẇt bĕ̇⁠d֗wòr wá⁠ʼòma֗r ʻa֤m ţò̇ʻé֣y lébá֣b hé֑m wĕ֝⁠hé֗m lòʼ-yádĕʻ֥ẇ dĕrákáֽ⁠y׃"],[95,11,"אֲשֶׁר־נִשְׁבַּ֥עְתִּי בְ⁠אַפִּ֑⁠י אִם־יְ֝בֹא֗וּ⁠ן אֶל־מְנוּחָתִֽ⁠י׃","ʼàşěr-nişĕ̌bȧ֥ʻĕţi̇y bĕ⁠ʼapi֑̇⁠y ʼim-yĕ֝bòʼ֗ẇ⁠n ʼel-mĕnẇẖáţiֽ⁠y׃"],[96,1,"שִׁ֣ירוּ לַ֭⁠יהוָה שִׁ֣יר חָדָ֑שׁ שִׁ֥ירוּ לַ֝⁠יהוָ֗ה כָּל־הָ⁠אָֽרֶץ׃","şǐ֣yrẇ la֭⁠yhwáh şǐ֣yr ẖádá֑ş̌ şǐ֥yrẇ la֝⁠yhwá֗h ká̇l-há⁠ʼáֽreẕ׃"],[96,2,"שִׁ֣ירוּ לַ֭⁠יהוָה בָּרֲכ֣וּ שְׁמ֑⁠וֹ בַּשְּׂר֥וּ מִ⁠יּֽוֹם־לְ֝⁠י֗וֹם יְשׁוּעָתֽ⁠וֹ׃","şǐ֣yrẇ la֭⁠yhwáh bá̇ràk֣ẇ şĕ̌m֑⁠wò bȧşĕ̇̂r֥ẇ mi⁠ẏֽwòm-lĕ֝⁠y֗wòm yĕş̌ẇʻáţֽ⁠wò׃"],[96,3,"סַפְּר֣וּ בַ⁠גּוֹיִ֣ם כְּבוֹד֑⁠וֹ בְּ⁠כָל־הָֽ֝⁠עַמִּ֗ים נִפְלְאוֹתָֽי⁠ו׃","sapĕ̇r֣ẇ ba⁠ġwòyi֣m kĕ̇bwòd֑⁠wò bĕ̇⁠kál-háֽ֝⁠ʻami̇֗ym nipĕlĕʼwòţáֽy⁠w׃"],[96,4,"כִּ֥י גָ֘ד֤וֹל יְהוָ֣ה וּ⁠מְהֻלָּ֣ל מְאֹ֑ד נוֹרָ֥א ה֝֗וּא עַל־כָּל־אֱלֹהִֽים׃","ki֥̇y gá֘d֤wòl yĕhwá֣h ẇ⁠mĕhulá֣̇l mĕʼò֑d nwòrá֥ʼ h֝֗ẇʼ ʻal-ká̇l-ʼèlòhiֽym׃"],[96,5,"כִּ֤י ׀ כָּל־אֱלֹהֵ֣י הָ⁠עַמִּ֣ים אֱלִילִ֑ים וַֽ֝⁠יהוָ֗ה שָׁמַ֥יִם עָשָֽׂה׃","ki֤̇y ׀ ká̇l-ʼèlòhé֣y há⁠ʻami֣̇ym ʼèliyli֑ym waֽ֝⁠yhwá֗h şá̌ma֥yim ʻáşáֽ̂h׃"],[96,6,"הוֹד־וְ⁠הָדָ֥ר לְ⁠פָנָ֑י⁠ו עֹ֥ז וְ֝⁠תִפְאֶ֗רֶת בְּ⁠מִקְדָּשֽׁ⁠וֹ׃","hwòd-wĕ⁠hádá֥r lĕ⁠páná֑y⁠w ʻò֥z wĕ֝⁠ţipĕʼe֗reţ bĕ̇⁠miqĕdá̇şֽ̌⁠wò׃"],[96,7,"הָב֣וּ לַ֭⁠יהוָה מִשְׁפְּח֣וֹת עַמִּ֑ים הָב֥וּ לַ֝⁠יהוָ֗ה כָּב֥וֹד וָ⁠עֹֽז׃","háb֣ẇ la֭⁠yhwáh mişĕ̌pĕ̇ẖ֣wòţ ʻami֑̇ym háb֥ẇ la֝⁠yhwá֗h ká̇b֥wòd wá⁠ʻòֽz׃"],[96,8,"הָב֣וּ לַ֭⁠יהוָה כְּב֣וֹד שְׁמ֑⁠וֹ שְׂאֽוּ־מִ֝נְחָ֗ה וּ⁠בֹ֥אוּ לְ⁠חַצְרוֹתָֽי⁠ו׃","háb֣ẇ la֭⁠yhwáh kĕ̇b֣wòd şĕ̌m֑⁠wò şĕ̂ʼֽẇ-mi֝nĕẖá֗h ẇ⁠bò֥ʼẇ lĕ⁠ẖaẕĕrwòţáֽy⁠w׃"],[96,9,"הִשְׁתַּחֲו֣וּ לַ֭⁠יהוָה בְּ⁠הַדְרַת־קֹ֑דֶשׁ חִ֥ילוּ מִ֝⁠פָּנָ֗י⁠ו כָּל־הָ⁠אָֽרֶץ׃","hişĕ̌ţȧẖàw֣ẇ la֭⁠yhwáh bĕ̇⁠hadĕraţ-qò֑deş̌ ẖi֥ylẇ mi֝⁠pá̇ná֗y⁠w ká̇l-há⁠ʼáֽreẕ׃"],[96,10,"אִמְר֤וּ בַ⁠גּוֹיִ֨ם ׀ יְה֘וָ֤ה מָלָ֗ךְ אַף־תִּכּ֣וֹן תֵּ֭בֵל בַּל־תִּמּ֑וֹט יָדִ֥ין עַ֝מִּ֗ים בְּ⁠מֵישָׁרִֽים׃","ʼimĕr֤ẇ ba⁠ġwòyi֨m ׀ yĕh֘wá֤h málá֗kĕ ʼap-ţi̇k֣̇wòn ţé֭̇bél bȧl-ţi̇ṁ֑wòt yádi֥yn ʻa֝mi̇֗ym bĕ̇⁠méyşá̌riֽym׃"],[96,11,"יִשְׂמְח֣וּ הַ֭⁠שָּׁמַיִם וְ⁠תָגֵ֣ל הָ⁠אָ֑רֶץ יִֽרְעַ֥ם הַ֝⁠יָּ֗ם וּ⁠מְלֹאֽ⁠וֹ׃","yişĕ̂mĕẖ֣ẇ ha֭⁠şá̇̌mayim wĕ⁠ţágé֣l há⁠ʼá֑reẕ yiֽrĕʻa֥m ha֝⁠yá̇֗m ẇ⁠mĕlòʼֽ⁠wò׃"],[96,12,"יַעֲלֹ֣ז שָׂ֭דַי וְ⁠כָל־אֲשֶׁר־בּ֑⁠וֹ אָ֥ז יְ֝רַנְּנ֗וּ כָּל־עֲצֵי־יָֽעַר׃","yaʻàlò֣z şá֭̂day wĕ⁠kál-ʼàşěr-ḃ֑⁠wò ʼá֥z yĕ֝ranĕ̇n֗ẇ ká̇l-ʻàẕéy-yáֽʻar׃"],[96,13,"לִ⁠פְנֵ֤י יְהוָ֨ה ׀ כִּ֬י בָ֗א כִּ֥י בָא֮ לִ⁠שְׁפֹּ֪ט הָ֫⁠אָ֥רֶץ יִשְׁפֹּֽט־תֵּבֵ֥ל בְּ⁠צֶ֑דֶק וְ֝⁠עַמִּ֗ים בֶּ⁠אֱמוּנָתֽ⁠וֹ׃","li⁠pĕné֤y yĕhwá֨h ׀ ki̇֬y bá֗ʼ ki֥̇y báʼ֮ li⁠şĕ̌pò֪̇t há֫⁠ʼá֥reẕ yişĕ̌pòֽ̇t-ţé̇bé֥l bĕ̇⁠ẕe֑deq wĕ֝⁠ʻami̇֗ym bė⁠ʼèmẇnáţֽ⁠wò׃"],[97,1,"יְהוָ֣ה מָ֭לָךְ תָּגֵ֣ל הָ⁠אָ֑רֶץ יִ֝שְׂמְח֗וּ אִיִּ֥ים רַבִּֽים׃","yĕhwá֣h má֭lákĕ ţá̇gé֣l há⁠ʼá֑reẕ yi֝şĕ̂mĕẖ֗ẇ ʼiyi֥̇ym rabiֽ̇ym׃"],[97,2,"עָנָ֣ן וַ⁠עֲרָפֶ֣ל סְבִיבָ֑י⁠ו צֶ֥דֶק וּ֝⁠מִשְׁפָּ֗ט מְכ֣וֹן כִּסְאֽ⁠וֹ׃","ʻáná֣n wa⁠ʻàrápe֣l sĕbiybá֑y⁠w ẕe֥deq ẇ֝⁠mişĕ̌pá̇֗t mĕk֣wòn ki̇sĕʼֽ⁠wò׃"],[97,3,"אֵ֭שׁ לְ⁠פָנָ֣י⁠ו תֵּלֵ֑ךְ וּ⁠תְלַהֵ֖ט סָבִ֣יב צָרָֽי⁠ו׃","ʼé֭ş̌ lĕ⁠páná֣y⁠w ţé̇lé֑kĕ ẇ⁠ţĕlahé֖t sábi֣yb ẕáráֽy⁠w׃"],[97,4,"הֵאִ֣ירוּ בְרָקָ֣י⁠ו תֵּבֵ֑ל רָאֲתָ֖ה וַ⁠תָּחֵ֣ל הָ⁠אָֽרֶץ׃","héʼi֣yrẇ bĕráqá֣y⁠w ţé̇bé֑l ráʼàţá֖h wa⁠ţá̇ẖé֣l há⁠ʼáֽreẕ׃"],[97,5,"הָרִ֗ים כַּ⁠דּוֹנַ֗ג נָ֭מַסּוּ מִ⁠לִּ⁠פְנֵ֣י יְהוָ֑ה מִ֝⁠לִּ⁠פְנֵ֗י אֲד֣וֹן כָּל־הָ⁠אָֽרֶץ׃","hári֗ym kȧ⁠ḋwòna֗g ná֭maṡẇ mi⁠li̇⁠pĕné֣y yĕhwá֑h mi֝⁠li̇⁠pĕné֗y ʼàd֣wòn ká̇l-há⁠ʼáֽreẕ׃"],[97,6,"הִגִּ֣ידוּ הַ⁠שָּׁמַ֣יִם צִדְק֑⁠וֹ וְ⁠רָא֖וּ כָל־הָ⁠עַמִּ֣ים כְּבוֹדֽ⁠וֹ׃","higi֣̇ydẇ ha⁠şá̇̌ma֣yim ẕidĕq֑⁠wò wĕ⁠ráʼ֖ẇ kál-há⁠ʻami֣̇ym kĕ̇bwòdֽ⁠wò׃"],[97,7,"יֵבֹ֤שׁוּ ׀ כָּל־עֹ֬בְדֵי פֶ֗סֶל הַ⁠מִּֽתְהַלְלִ֥ים בָּ⁠אֱלִילִ֑ים הִשְׁתַּחֲווּ־ל֝⁠וֹ כָּל־אֱלֹהִֽים׃","yébò֤ş̌ẇ ׀ ká̇l-ʻò֬bĕdéy pe֗sel ha⁠miֽ̇ţĕhalĕli֥ym bá̇⁠ʼèliyli֑ym hişĕ̌ţȧẖàwẇ-l֝⁠wò ká̇l-ʼèlòhiֽym׃"],[97,8,"שָׁמְעָ֬ה וַ⁠תִּשְׂמַ֨ח ׀ צִיּ֗וֹן וַ֭⁠תָּגֵלְנָה בְּנ֣וֹת יְהוּדָ֑ה לְמַ֖עַן מִשְׁפָּטֶ֣י⁠ךָ יְהוָֽה׃","şá̌mĕʻá֬h wa⁠ţi̇şĕ̂ma֨ẖ ׀ ẕiẏ֗wòn wa֭⁠ţá̇gélĕnáh bĕ̇n֣wòţ yĕhẇdá֑h lĕma֖ʻan mişĕ̌pá̇te֣y⁠ká yĕhwáֽh׃"],[97,9,"כִּֽי־אַתָּ֤ה יְהוָ֗ה עֶלְי֥וֹן עַל־כָּל־הָ⁠אָ֑רֶץ מְאֹ֥ד נַ֝עֲלֵ֗יתָ עַל־כָּל־אֱלֹהִֽים׃","kiֽ̇y-ʼaţá֤̇h yĕhwá֗h ʻelĕy֥wòn ʻal-ká̇l-há⁠ʼá֑reẕ mĕʼò֥d na֝ʻàlé֗yţá ʻal-ká̇l-ʼèlòhiֽym׃"],[97,10,"אֹהֲבֵ֥י יְהוָ֗ה שִׂנְא֫וּ רָ֥ע שֹׁ֭מֵר נַפְשׁ֣וֹת חֲסִידָ֑י⁠ו מִ⁠יַּ֥ד רְ֝שָׁעִ֗ים יַצִּילֵֽ⁠ם׃","ʼòhàbé֥y yĕhwá֗h şînĕʼ֫ẇ rá֥ʻ şò֭̌mér napĕş֣̌wòţ ẖàsiydá֑y⁠w mi⁠yȧ֥d rĕ֝şá̌ʻi֗ym yaẕi̇yléֽ⁠m׃"],[97,11,"א֭וֹר זָרֻ֣עַ לַ⁠צַּדִּ֑יק וּֽ⁠לְ⁠יִשְׁרֵי־לֵ֥ב שִׂמְחָֽה׃","ʼ֭wòr záru֣ʻa la⁠ẕȧdi֑̇yq ẇֽ⁠lĕ⁠yişĕ̌réy-lé֥b şîmĕẖáֽh׃"],[97,12,"שִׂמְח֣וּ צַ֭דִּיקִים בַּֽ⁠יהוָ֑ה וְ֝⁠הוֹד֗וּ לְ⁠זֵ֣כֶר קָדְשֽׁ⁠וֹ׃","şîmĕẖ֣ẇ ẕa֭di̇yqiym bȧֽ⁠yhwá֑h wĕ֝⁠hwòd֗ẇ lĕ⁠zé֣ker qádĕşֽ̌⁠wò׃"],[98,1,"מִזְמ֡וֹר שִׁ֤ירוּ לַֽ⁠יהוָ֨ה ׀ שִׁ֣יר חָ֭דָשׁ כִּֽי־נִפְלָא֣וֹת עָשָׂ֑ה הוֹשִֽׁיעָה־לּ֥⁠וֹ יְ֝מִינ֗⁠וֹ וּ⁠זְר֥וֹעַ קָדְשֽׁ⁠וֹ׃","mizĕm֡wòr şǐ֤yrẇ laֽ⁠yhwá֨h ׀ şǐ֣yr ẖá֭dáş̌ kiֽ̇y-nipĕláʼ֣wòţ ʻáşá֑̂h hwòşǐֽyʻáh-l֥̇⁠wò yĕ֝miyn֗⁠wò ẇ⁠zĕr֥wòʻa qádĕşֽ̌⁠wò׃"],[98,2,"הוֹדִ֣יעַ יְ֭הוָה יְשׁוּעָת֑⁠וֹ לְ⁠עֵינֵ֥י הַ֝⁠גּוֹיִ֗ם גִּלָּ֥ה צִדְקָתֽ⁠וֹ׃","hwòdi֣yʻa yĕ֭hwáh yĕş̌ẇʻáţ֑⁠wò lĕ⁠ʻéyné֥y ha֝⁠ġwòyi֗m gi̇lá֥̇h ẕidĕqáţֽ⁠wò׃"],[98,3,"זָ֘כַ֤ר חַסְדּ֨⁠וֹ ׀ וֶֽ⁠אֱֽמוּנָת⁠וֹ֮ לְ⁠בֵ֪ית יִשְׂרָ֫אֵ֥ל רָא֥וּ כָל־אַפְסֵי־אָ֑רֶץ אֵ֝֗ת יְשׁוּעַ֥ת אֱלֹהֵֽי⁠נוּ׃","zá֘ka֤r ẖasĕḋ֨⁠wò ׀ weֽ⁠ʼèֽmẇnáţ⁠wò֮ lĕ⁠bé֪yţ yişĕ̂rá֫ʼé֥l ráʼ֥ẇ kál-ʼapĕséy-ʼá֑reẕ ʼé֝֗ţ yĕş̌ẇʻa֥ţ ʼèlòhéֽy⁠nẇ׃"],[98,4,"הָרִ֣יעוּ לַֽ֭⁠יהוָה כָּל־הָ⁠אָ֑רֶץ פִּצְח֖וּ וְ⁠רַנְּנ֣וּ וְ⁠זַמֵּֽרוּ׃","hári֣yʻẇ laֽ֭⁠yhwáh ká̇l-há⁠ʼá֑reẕ pi̇ẕĕẖ֖ẇ wĕ⁠ranĕ̇n֣ẇ wĕ⁠zaméֽ̇rẇ׃"],[98,5,"זַמְּר֣וּ לַ⁠יהוָ֣ה בְּ⁠כִנּ֑וֹר בְּ֝⁠כִנּ֗וֹר וְ⁠ק֣וֹל זִמְרָֽה׃","zamĕ̇r֣ẇ la⁠yhwá֣h bĕ̇⁠kiṅ֑wòr bĕ̇֝⁠kiṅ֗wòr wĕ⁠q֣wòl zimĕráֽh׃"],[98,6,"בַּ֭⁠חֲצֹ֣צְרוֹת וְ⁠ק֣וֹל שׁוֹפָ֑ר הָ֝רִ֗יעוּ לִ⁠פְנֵ֤י ׀ הַ⁠מֶּ֬לֶךְ יְהוָֽה׃","bȧ֭⁠ẖàẕò֣ẕĕrwòţ wĕ⁠q֣wòl ş̌wòpá֑r há֝ri֗yʻẇ li⁠pĕné֤y ׀ ha⁠mė֬lekĕ yĕhwáֽh׃"],[98,7,"יִרְעַ֣ם הַ֭⁠יָּם וּ⁠מְלֹא֑⁠וֹ תֵּ֝בֵ֗ל וְ⁠יֹ֣שְׁבֵי בָֽ⁠הּ׃","yirĕʻa֣m ha֭⁠yá̇m ẇ⁠mĕlòʼ֑⁠wò ţé̇֝bé֗l wĕ⁠yò֣şĕ̌béy báֽ⁠ḣ׃"],[98,8,"נְהָר֥וֹת יִמְחֲאוּ־כָ֑ף יַ֝֗חַד הָרִ֥ים יְרַנֵּֽנוּ׃","nĕhár֥wòţ yimĕẖàʼẇ-ká֑p ya֝֗ẖad hári֥ym yĕranéֽ̇nẇ׃"],[98,9,"לִֽ⁠פְֽנֵי־יְהוָ֗ה כִּ֥י בָא֮ לִ⁠שְׁפֹּ֪ט הָ֫⁠אָ֥רֶץ יִשְׁפֹּֽט־תֵּבֵ֥ל בְּ⁠צֶ֑דֶק וְ֝⁠עַמִּ֗ים בְּ⁠מֵישָׁרִֽים׃","liֽ⁠pĕֽnéy-yĕhwá֗h ki֥̇y báʼ֮ li⁠şĕ̌pò֪̇t há֫⁠ʼá֥reẕ yişĕ̌pòֽ̇t-ţé̇bé֥l bĕ̇⁠ẕe֑deq wĕ֝⁠ʻami̇֗ym bĕ̇⁠méyşá̌riֽym׃"],[99,1,"יְהוָ֣ה מָ֭לָךְ יִרְגְּז֣וּ עַמִּ֑ים יֹשֵׁ֥ב כְּ֝רוּבִ֗ים תָּנ֥וּט הָ⁠אָֽרֶץ׃","yĕhwá֣h má֭lákĕ yirĕgĕ̇z֣ẇ ʻami֑̇ym yòşé֥̌b kĕ̇֝rẇbi֗ym ţá̇n֥ẇt há⁠ʼáֽreẕ׃"],[99,2,"יְ֭הוָה בְּ⁠צִיּ֣וֹן גָּד֑וֹל וְ⁠רָ֥ם ה֝֗וּא עַל־כָּל־הָֽ⁠עַמִּֽים׃","yĕ֭hwáh bĕ̇⁠ẕiẏ֣wòn gá̇d֑wòl wĕ⁠rá֥m h֝֗ẇʼ ʻal-ká̇l-háֽ⁠ʻamiֽ̇ym׃"],[99,3,"יוֹד֣וּ שִׁ֭מְ⁠ךָ גָּד֥וֹל וְ⁠נוֹרָ֗א קָד֥וֹשׁ הֽוּא׃","ywòd֣ẇ şǐ֭mĕ⁠ká gá̇d֥wòl wĕ⁠nwòrá֗ʼ qád֥wòş̌ hֽẇʼ׃"],[99,4,"וְ⁠עֹ֥ז מֶלֶךְ֮ מִשְׁפָּ֪ט אָ֫הֵ֥ב אַ֭תָּה כּוֹנַ֣נְתָּ מֵישָׁרִ֑ים מִשְׁפָּ֥ט וּ֝⁠צְדָקָ֗ה בְּ⁠יַעֲקֹ֤ב ׀ אַתָּ֬ה עָשִֽׂיתָ׃","wĕ⁠ʻò֥z melekĕ֮ mişĕ̌pá֪̇t ʼá֫hé֥b ʼa֭ţá̇h k̇wòna֣nĕţá̇ méyşá̌ri֑ym mişĕ̌pá֥̇t ẇ֝⁠ẕĕdáqá֗h bĕ̇⁠yaʻàqò֤b ׀ ʼaţá̇֬h ʻáşîֽyţá׃"],[99,5,"רֽוֹמְמ֡וּ יְה֘וָ֤ה אֱלֹהֵ֗י⁠נוּ וְֽ֭⁠הִשְׁתַּחֲווּ לַ⁠הֲדֹ֥ם רַגְלָ֗י⁠ו קָד֥וֹשׁ הֽוּא׃","rֽwòmĕm֡ẇ yĕh֘wá֤h ʼèlòhé֗y⁠nẇ wĕֽ֭⁠hişĕ̌ţȧẖàwẇ la⁠hàdò֥m ragĕlá֗y⁠w qád֥wòş̌ hֽẇʼ׃"],[99,6,"מֹ֘שֶׁ֤ה וְ⁠אַהֲרֹ֨ן ׀ בְּֽ⁠כֹהֲנָ֗י⁠ו וּ֭⁠שְׁמוּאֵל בְּ⁠קֹרְאֵ֣י שְׁמ֑⁠וֹ קֹרִ֥אים אֶל־יְ֝הוָ֗ה וְ⁠ה֣וּא יַעֲנֵֽ⁠ם׃","mò֘şě֤h wĕ⁠ʼahàrò֨n ׀ bĕֽ̇⁠kòhàná֗y⁠w ẇ֭⁠şĕ̌mẇʼél bĕ̇⁠qòrĕʼé֣y şĕ̌m֑⁠wò qòri֥ʼym ʼel-yĕ֝hwá֗h wĕ⁠h֣ẇʼ yaʻànéֽ⁠m׃"],[99,7,"בְּ⁠עַמּ֣וּד עָ֭נָן יְדַבֵּ֣ר אֲלֵי⁠הֶ֑ם שָׁמְר֥וּ עֵ֝דֹתָ֗י⁠ו וְ⁠חֹ֣ק נָֽתַן־לָֽ⁠מוֹ׃","bĕ̇⁠ʻaṁ֣ẇd ʻá֭nán yĕdabé֣̇r ʼàléy⁠he֑m şá̌mĕr֥ẇ ʻé֝dòţá֗y⁠w wĕ⁠ẖò֣q náֽţan-láֽ⁠mwò׃"],[99,8,"יְהוָ֣ה אֱלֹהֵי⁠נוּ֮ אַתָּ֪ה עֲנִ֫יתָ֥⁠ם אֵ֣ל נֹ֭שֵׂא הָיִ֣יתָ לָ⁠הֶ֑ם וְ֝⁠נֹקֵ֗ם עַל־עֲלִילוֹתָֽ⁠ם׃","yĕhwá֣h ʼèlòhéy⁠nẇ֮ ʼaţá֪̇h ʻàni֫yţá֥⁠m ʼé֣l nò֭şé̂ʼ háyi֣yţá lá⁠he֑m wĕ֝⁠nòqé֗m ʻal-ʻàliylwòţáֽ⁠m׃"],[99,9,"רֽוֹמְמ֡וּ יְה֘וָ֤ה אֱלֹהֵ֗י⁠נוּ וְ֭⁠הִֽשְׁתַּחֲווּ לְ⁠הַ֣ר קָדְשׁ֑⁠וֹ כִּֽי־קָ֝ד֗וֹשׁ יְהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","rֽwòmĕm֡ẇ yĕh֘wá֤h ʼèlòhé֗y⁠nẇ wĕ֭⁠hiֽşĕ̌ţȧẖàwẇ lĕ⁠ha֣r qádĕş֑̌⁠wò kiֽ̇y-qá֝d֗wòş̌ yĕhwá֥h ʼèlòhéֽy⁠nẇ׃"],[100,1,"מִזְמ֥וֹר לְ⁠תוֹדָ֑ה הָרִ֥יעוּ לַ֝⁠יהוָ֗ה כָּל־הָ⁠אָֽרֶץ׃","mizĕm֥wòr lĕ⁠ţwòdá֑h hári֥yʻẇ la֝⁠yhwá֗h ká̇l-há⁠ʼáֽreẕ׃"],[100,2,"עִבְד֣וּ אֶת־יְהוָ֣ה בְּ⁠שִׂמְחָ֑ה בֹּ֥אוּ לְ֝⁠פָנָ֗י⁠ו בִּ⁠רְנָנָֽה׃","ʻibĕd֣ẇ ʼeţ-yĕhwá֣h bĕ̇⁠şîmĕẖá֑h bò֥̇ʼẇ lĕ֝⁠páná֗y⁠w bi̇⁠rĕnánáֽh׃"],[100,3,"דְּע֗וּ כִּֽי־יְהוָה֮ ה֤וּא אֱלֹ֫הִ֥ים הֽוּא־עָ֭שָׂ⁠נוּ ו⁠לא אֲנַ֑חְנוּ עַ֝מּ֗⁠וֹ וְ⁠צֹ֣אן מַרְעִיתֽ⁠וֹ׃","dĕ̇ʻ֗ẇ kiֽ̇y-yĕhwáh֮ h֤ẇʼ ʼèlò֫hi֥ym hֽẇʼ-ʻá֭şá̂⁠nẇ w⁠lʼ ʼàna֑ẖĕnẇ ʻa֝ṁ֗⁠wò wĕ⁠ẕò֣ʼn marĕʻiyţֽ⁠wò׃"],[100,4,"בֹּ֤אוּ שְׁעָרָ֨י⁠ו ׀ בְּ⁠תוֹדָ֗ה חֲצֵרֹתָ֥י⁠ו בִּ⁠תְהִלָּ֑ה הֽוֹדוּ־ל֝֗⁠וֹ בָּרֲכ֥וּ שְׁמֽ⁠וֹ׃","bò֤̇ʼẇ şĕ̌ʻárá֨y⁠w ׀ bĕ̇⁠ţwòdá֗h ẖàẕéròţá֥y⁠w bi̇⁠ţĕhilá֑̇h hֽwòdẇ-l֝֗⁠wò bá̇ràk֥ẇ şĕ̌mֽ⁠wò׃"],[100,5,"כִּי־ט֣וֹב יְ֭הֹוָה לְ⁠עוֹלָ֣ם חַסְדּ֑⁠וֹ וְ⁠עַד־דֹּ֥ר וָ֝⁠דֹ֗ר אֱמוּנָתֽ⁠וֹ׃","ki̇y-t֣wòb yĕ֭hòwáh lĕ⁠ʻwòlá֣m ẖasĕḋ֑⁠wò wĕ⁠ʻad-dò֥̇r wá֝⁠dò֗r ʼèmẇnáţֽ⁠wò׃"],[101,1,"לְ⁠דָוִ֗ד מִ֫זְמ֥וֹר חֶֽסֶד־וּ⁠מִשְׁפָּ֥ט אָשִׁ֑ירָה לְ⁠ךָ֖ יְהוָ֣ה אֲזַמֵּֽרָה׃","lĕ⁠dáwi֗d mi֫zĕm֥wòr ẖeֽsed-ẇ⁠mişĕ̌pá֥̇t ʼáşǐ֑yráh lĕ⁠ká֖ yĕhwá֣h ʼàzaméֽ̇ráh׃"],[101,2,"אַשְׂכִּ֤ילָה ׀ בְּ⁠דֶ֬רֶךְ תָּמִ֗ים מָ֭תַי תָּב֣וֹא אֵלָ֑⁠י אֶתְהַלֵּ֥ךְ בְּ⁠תָם־לְ֝בָבִ֗⁠י בְּ⁠קֶ֣רֶב בֵּיתִֽ⁠י׃","ʼaşĕ̂ki֤̇yláh ׀ bĕ̇⁠de֬rekĕ ţá̇mi֗ym má֭ţay ţá̇b֣wòʼ ʼélá֑⁠y ʼeţĕhalé֥̇kĕ bĕ̇⁠ţám-lĕ֝bábi֗⁠y bĕ̇⁠qe֣reb bé̇yţiֽ⁠y׃"],[101,3,"לֹֽא־אָשִׁ֨ית ׀ לְ⁠נֶ֥גֶד עֵינַ֗⁠י דְּֽבַר־בְּלִ֫יָּ֥עַל עֲשֹֽׂה־סֵטִ֥ים שָׂנֵ֑אתִי לֹ֖א יִדְבַּ֣ק בִּֽ⁠י׃","lòֽʼ-ʼáşǐ֨yţ ׀ lĕ⁠ne֥ged ʻéyna֗⁠y dĕֽ̇bar-bĕ̇li֫yá֥̇ʻal ʻàşòֽ̂h-séti֥ym şá̂né֑ʼţiy lò֖ʼ yidĕbȧ֣q biֽ̇⁠y׃"],[101,4,"לֵבָ֣ב עִ֭קֵּשׁ יָס֣וּר מִמֶּ֑⁠נִּי רָ֝֗ע לֹ֣א אֵדָֽע׃","lébá֣b ʻi֭qé̇ş̌ yás֣ẇr mimė֑⁠ni̇y rá֝֗ʻ lò֣ʼ ʼédáֽʻ׃"],[101,5,"מלושני בַ⁠סֵּ֨תֶר ׀ רֵעֵ⁠הוּ֮ אוֹת֪⁠וֹ אַ֫צְמִ֥ית גְּֽבַהּ־עֵ֭ינַיִם וּ⁠רְחַ֣ב לֵבָ֑ב אֹ֝ת֗⁠וֹ לֹ֣א אוּכָֽל׃","mlwşny ba⁠sé̇֨ţer ׀ réʻé⁠hẇ֮ ʼwòţ֪⁠wò ʼa֫ẕĕmi֥yţ gĕֽ̇baḣ-ʻé֭ynayim ẇ⁠rĕẖa֣b lébá֑b ʼò֝ţ֗⁠wò lò֣ʼ ʼẇkáֽl׃"],[101,6,"עֵינַ֤⁠י ׀ בְּ⁠נֶֽאֶמְנֵי־אֶרֶץ֮ לָ⁠שֶׁ֪בֶת עִמָּ֫דִ֥⁠י הֹ֭לֵךְ בְּ⁠דֶ֣רֶךְ תָּמִ֑ים ה֝֗וּא יְשָׁרְתֵֽ⁠נִי׃","ʻéyna֤⁠y ׀ bĕ̇⁠neֽʼemĕnéy-ʼereẕ֮ lá⁠şě֪beţ ʻimá̇֫di֥⁠y hò֭lékĕ bĕ̇⁠de֣rekĕ ţá̇mi֑ym h֝֗ẇʼ yĕşá̌rĕţéֽ⁠niy׃"],[101,7,"לֹֽא־יֵשֵׁ֨ב ׀ בְּ⁠קֶ֥רֶב בֵּיתִ⁠י֮ עֹשֵׂ֪ה רְמִ֫יָּ֥ה דֹּבֵ֥ר שְׁקָרִ֑ים לֹֽא־יִ֝כּ֗וֹן לְ⁠נֶ֣גֶד עֵינָֽ⁠י׃","lòֽʼ-yéşé̌֨b ׀ bĕ̇⁠qe֥reb bé̇yţi⁠y֮ ʻòşé֪̂h rĕmi֫yá֥̇h dò̇bé֥r şĕ̌qári֑ym lòֽʼ-yi֝k̇֗wòn lĕ⁠ne֣ged ʻéynáֽ⁠y׃"],[101,8,"לַ⁠בְּקָרִ֗ים אַצְמִ֥ית כָּל־רִשְׁעֵי־אָ֑רֶץ לְ⁠הַכְרִ֥ית מֵֽ⁠עִיר־יְ֝הוָ֗ה כָּל־פֹּ֥עֲלֵי אָֽוֶן׃","la⁠bĕ̇qári֗ym ʼaẕĕmi֥yţ ká̇l-rişĕ̌ʻéy-ʼá֑reẕ lĕ⁠hakĕri֥yţ méֽ⁠ʻiyr-yĕ֝hwá֗h ká̇l-pò֥̇ʻàléy ʼáֽwen׃"],[102,1,"יְ֭הוָה שִׁמְעָ֣⁠ה תְפִלָּתִ֑⁠י וְ֝⁠שַׁוְעָתִ֗⁠י אֵלֶ֥י⁠ךָ תָבֽוֹא׃","yĕ֭hwáh şǐmĕʻá֣⁠h ţĕpilá̇ţi֑⁠y wĕ֝⁠şǎwĕʻáţi֗⁠y ʼéle֥y⁠ká ţábֽwòʼ׃"],[102,2,"אַל־תַּסְתֵּ֬ר פָּנֶ֨י⁠ךָ ׀ מִמֶּ⁠נִּי֮ בְּ⁠י֪וֹם צַ֫ר לִ֥⁠י הַטֵּֽה־אֵלַ֥⁠י אָזְנֶ֑⁠ךָ בְּ⁠י֥וֹם אֶ֝קְרָ֗א מַהֵ֥ר עֲנֵֽ⁠נִי׃","ʼal-ţȧsĕţé̇֬r pá̇ne֨y⁠ká ׀ mimė⁠ni̇y֮ bĕ̇⁠y֪wòm ẕa֫r li֥⁠y hatéֽ̇h-ʼéla֥⁠y ʼázĕne֑⁠ká bĕ̇⁠y֥wòm ʼe֝qĕrá֗ʼ mahé֥r ʻànéֽ⁠niy׃"],[102,3,"כִּֽי־כָל֣וּ בְ⁠עָשָׁ֣ן יָמָ֑⁠י וְ֝⁠עַצְמוֹתַ֗⁠י כְּ⁠מוֹ־קֵ֥ד נִחָֽרוּ׃","kiֽ̇y-kál֣ẇ bĕ⁠ʻáşá֣̌n yámá֑⁠y wĕ֝⁠ʻaẕĕmwòţa֗⁠y kĕ̇⁠mwò-qé֥d niẖáֽrẇ׃"],[102,4,"הוּכָּֽה־כָ֭⁠עֵשֶׂב וַ⁠יִּבַ֣שׁ לִבִּ֑⁠י כִּֽי־שָׁ֝כַ֗חְתִּי מֵ⁠אֲכֹ֥ל לַחְמִֽ⁠י׃","hẇkáֽ̇h-ká֭⁠ʻéşêb wa⁠yi̇ba֣ş̌ libi֑̇⁠y kiֽ̇y-şá̌֝ka֗ẖĕţi̇y mé⁠ʼàkò֥l laẖĕmiֽ⁠y׃"],[102,5,"מִ⁠קּ֥וֹל אַנְחָתִ֑⁠י דָּבְקָ֥ה עַ֝צְמִ֗⁠י לִ⁠בְשָׂרִֽ⁠י׃","mi⁠q֥̇wòl ʼanĕẖáţi֑⁠y dá̇bĕqá֥h ʻa֝ẕĕmi֗⁠y li⁠bĕşá̂riֽ⁠y׃"],[102,6,"דָּ֭מִיתִי לִ⁠קְאַ֣ת מִדְבָּ֑ר הָ֝יִ֗יתִי כְּ⁠כ֣וֹס חֳרָבֽוֹת׃","dá֭̇miyţiy li⁠qĕʼa֣ţ midĕbá֑̇r há֝yi֗yţiy kĕ̇⁠k֣wòs ẖorábֽwòţ׃"],[102,7,"שָׁקַ֥דְתִּי וָ⁠אֶֽהְיֶ֑ה כְּ֝⁠צִפּ֗וֹר בּוֹדֵ֥ד עַל־גָּֽג׃","şá̌qa֥dĕţi̇y wá⁠ʼeֽhĕye֑h kĕ̇֝⁠ẕiṗ֗wòr ḃwòdé֥d ʻal-gáֽ̇g׃"],[102,8,"כָּל־הַ֭⁠יּוֹם חֵרְפ֣וּ⁠נִי אוֹיְבָ֑⁠י מְ֝הוֹלָלַ֗⁠י בִּ֣⁠י נִשְׁבָּֽעוּ׃","ká̇l-ha֭⁠ẏwòm ẖérĕp֣ẇ⁠niy ʼwòyĕbá֑⁠y mĕ֝hwòlála֗⁠y bi֣̇⁠y nişĕ̌báֽ̇ʻẇ׃"],[102,9,"כִּי־אֵ֭פֶר כַּ⁠לֶּ֣חֶם אָכָ֑לְתִּי וְ֝⁠שִׁקֻּוַ֗⁠י בִּ⁠בְכִ֥י מָסָֽכְתִּי׃","ki̇y-ʼé֭per kȧ⁠lė֣ẖem ʼáká֑lĕţi̇y wĕ֝⁠şǐqu̇wa֗⁠y bi̇⁠bĕki֥y másáֽkĕţi̇y׃"],[102,10,"מִ⁠פְּנֵֽי־זַֽעַמְ⁠ךָ֥ וְ⁠קִצְפֶּ֑⁠ךָ כִּ֥י נְ֝שָׂאתַ֗⁠נִי וַ⁠תַּשְׁלִיכֵֽ⁠נִי׃","mi⁠pĕ̇néֽy-zaֽʻamĕ⁠ká֥ wĕ⁠qiẕĕpė֑⁠ká ki֥̇y nĕ֝şá̂ʼţa֗⁠niy wa⁠ţȧşĕ̌liykéֽ⁠niy׃"],[102,11,"יָ֭מַ⁠י כְּ⁠צֵ֣ל נָט֑וּי וַ֝⁠אֲנִ֗י כָּ⁠עֵ֥שֶׂב אִיבָֽשׁ׃","yá֭ma⁠y kĕ̇⁠ẕé֣l nát֑ẇy wa֝⁠ʼàni֗y ká̇⁠ʻé֥şêb ʼiybáֽş̌׃"],[102,12,"וְ⁠אַתָּ֣ה יְ֭הוָה לְ⁠עוֹלָ֣ם תֵּשֵׁ֑ב וְ֝⁠זִכְרְ⁠ךָ֗ לְ⁠דֹ֣ר וָ⁠דֹֽר׃","wĕ⁠ʼaţá֣̇h yĕ֭hwáh lĕ⁠ʻwòlá֣m ţé̇şé֑̌b wĕ֝⁠zikĕrĕ⁠ká֗ lĕ⁠dò֣r wá⁠dòֽr׃"],[102,13,"אַתָּ֣ה תָ֭קוּם תְּרַחֵ֣ם צִיּ֑וֹן כִּי־עֵ֥ת לְ֝⁠חֶֽנְנָ֗⁠הּ כִּי־בָ֥א מוֹעֵֽד׃","ʼaţá֣̇h ţá֭qẇm ţĕ̇raẖé֣m ẕiẏ֑wòn ki̇y-ʻé֥ţ lĕ֝⁠ẖeֽnĕná֗⁠ḣ ki̇y-bá֥ʼ mwòʻéֽd׃"],[102,14,"כִּֽי־רָצ֣וּ עֲ֭בָדֶי⁠ךָ אֶת־אֲבָנֶ֑י⁠הָ וְֽ⁠אֶת־עֲפָרָ֥⁠הּ יְחֹנֵֽנוּ׃","kiֽ̇y-ráẕ֣ẇ ʻà֭bádey⁠ká ʼeţ-ʼàbáne֑y⁠há wĕֽ⁠ʼeţ-ʻàpárá֥⁠ḣ yĕẖònéֽnẇ׃"],[102,15,"וְ⁠יִֽירְא֣וּ ג֭וֹיִם אֶת־שֵׁ֣ם יְהוָ֑ה וְֽ⁠כָל־מַלְכֵ֥י הָ֝⁠אָ֗רֶץ אֶת־כְּבוֹדֶֽ⁠ךָ׃","wĕ⁠yiֽyrĕʼ֣ẇ g֭wòyim ʼeţ-şé֣̌m yĕhwá֑h wĕֽ⁠kál-malĕké֥y há֝⁠ʼá֗reẕ ʼeţ-kĕ̇bwòdeֽ⁠ká׃"],[102,16,"כִּֽי־בָנָ֣ה יְהוָ֣ה צִיּ֑וֹן נִ֝רְאָ֗ה בִּ⁠כְבוֹדֽ⁠וֹ׃","kiֽ̇y-báná֣h yĕhwá֣h ẕiẏ֑wòn ni֝rĕʼá֗h bi̇⁠kĕbwòdֽ⁠wò׃"],[102,17,"פָּ֭נָה אֶל־תְּפִלַּ֣ת הָ⁠עַרְעָ֑ר וְ⁠לֹֽא־בָ֝זָ֗ה אֶת־תְּפִלָּתָֽ⁠ם׃","pá֭̇náh ʼel-ţĕ̇pilȧ֣ţ há⁠ʻarĕʻá֑r wĕ⁠lòֽʼ-bá֝zá֗h ʼeţ-ţĕ̇pilá̇ţáֽ⁠m׃"],[102,18,"תִּכָּ֣תֶב זֹ֭את לְ⁠ד֣וֹר אַחֲר֑וֹן וְ⁠עַ֥ם נִ֝בְרָ֗א יְהַלֶּל־יָֽהּ׃","ţi̇ká֣̇ţeb zò֭ʼţ lĕ⁠d֣wòr ʼaẖàr֑wòn wĕ⁠ʻa֥m ni֝bĕrá֗ʼ yĕhalėl-yáֽḣ׃"],[102,19,"כִּֽי־הִ֭שְׁקִיף מִ⁠מְּר֣וֹם קָדְשׁ֑⁠וֹ יְ֝הוָ֗ה מִ⁠שָּׁמַ֤יִם ׀ אֶל־אֶ֬רֶץ הִבִּֽיט׃","kiֽ̇y-hi֭şĕ̌qiyp mi⁠mĕ̇r֣wòm qádĕş֑̌⁠wò yĕ֝hwá֗h mi⁠şá̇̌ma֤yim ׀ ʼel-ʼe֬reẕ hibiֽ̇yt׃"],[102,20,"לִ֭⁠שְׁמֹעַ אֶנְקַ֣ת אָסִ֑יר לְ֝⁠פַתֵּ֗חַ בְּנֵ֣י תְמוּתָֽה׃","li֭⁠şĕ̌mòʻa ʼenĕqa֣ţ ʼási֑yr lĕ֝⁠paţé̇֗ẖa bĕ̇né֣y ţĕmẇţáֽh׃"],[102,21,"לְ⁠סַפֵּ֣ר בְּ֭⁠צִיּוֹן שֵׁ֣ם יְהוָ֑ה וּ֝⁠תְהִלָּת֗⁠וֹ בִּ⁠ירוּשָׁלִָֽם׃","lĕ⁠sapé֣̇r bĕ֭̇⁠ẕiẏwòn şé֣̌m yĕhwá֑h ẇ֝⁠ţĕhilá̇ţ֗⁠wò bi̇⁠yrẇşá̌liáֽm׃"],[102,22,"בְּ⁠הִקָּבֵ֣ץ עַמִּ֣ים יַחְדָּ֑ו וּ֝⁠מַמְלָכ֗וֹת לַ⁠עֲבֹ֥ד אֶת־יְהוָֽה׃","bĕ̇⁠hiqá̇bé֣ẕ ʻami֣̇ym yaẖĕdá֑̇w ẇ֝⁠mamĕlák֗wòţ la⁠ʻàbò֥d ʼeţ-yĕhwáֽh׃"],[102,23,"עִנָּ֖ה בַ⁠דֶּ֥רֶךְ כח⁠ו קִצַּ֥ר יָמָֽ⁠י׃","ʻiná֖̇h ba⁠dė֥rekĕ kẖ⁠w qiẕȧ֥r yámáֽ⁠y׃"],[102,24,"אֹמַ֗ר אֵלִ֗⁠י אַֽל־תַּ֭עֲלֵ⁠נִי בַּ⁠חֲצִ֣י יָמָ֑⁠י בְּ⁠ד֖וֹר דּוֹרִ֣ים שְׁנוֹתֶֽי⁠ךָ׃","ʼòma֗r ʼéli֗⁠y ʼaֽl-ţȧ֭ʻàlé⁠niy bȧ⁠ẖàẕi֣y yámá֑⁠y bĕ̇⁠d֖wòr ḋwòri֣ym şĕ̌nwòţeֽy⁠ká׃"],[102,25,"לְ֭⁠פָנִים הָ⁠אָ֣רֶץ יָסַ֑דְתָּ וּֽ⁠מַעֲשֵׂ֖ה יָדֶ֣י⁠ךָ שָׁמָֽיִם׃","lĕ֭⁠pániym há⁠ʼá֣reẕ yása֑dĕţá̇ ẇֽ⁠maʻàşé֖̂h yáde֣y⁠ká şá̌máֽyim׃"],[102,26,"הֵ֤מָּה ׀ יֹאבֵדוּ֮ וְ⁠אַתָּ֪ה תַ֫עֲמֹ֥ד וְ֭⁠כֻלָּ⁠ם כַּ⁠בֶּ֣גֶד יִבְל֑וּ כַּ⁠לְּב֖וּשׁ תַּחֲלִיפֵ֣⁠ם וְֽ⁠יַחֲלֹֽפוּ׃","hé֤má̇h ׀ yòʼbédẇ֮ wĕ⁠ʼaţá֪̇h ţa֫ʻàmò֥d wĕ֭⁠kulá̇⁠m kȧ⁠bė֣ged yibĕl֑ẇ kȧ⁠lĕ̇b֖ẇş̌ ţȧẖàliypé֣⁠m wֽĕ⁠yaẖàlòֽpẇ׃"],[102,27,"וְ⁠אַתָּה־ה֑וּא וּ֝⁠שְׁנוֹתֶ֗י⁠ךָ לֹ֣א יִתָּֽמּוּ׃","wĕ⁠ʼaţá̇h-h֑ẇʼ ẇ֝⁠şĕ̌nwòţe֗y⁠ká lò֣ʼ yiţáֽ̇ṁẇ׃"],[102,28,"בְּנֵֽי־עֲבָדֶ֥י⁠ךָ יִשְׁכּ֑וֹנוּ וְ֝⁠זַרְעָ֗⁠ם לְ⁠פָנֶ֥י⁠ךָ יִכּֽוֹן׃","bĕ̇néֽy-ʻàbáde֥y⁠ká yişĕ̌k֑̇wònẇ wĕ֝⁠zarĕʻá֗⁠m lĕ⁠páne֥y⁠ká yikֽ̇wòn׃"],[103,1,"לְ⁠דָוִ֨ד ׀ בָּרֲכִ֣י נַ֭פְשִׁ⁠י אֶת־יְהוָ֑ה וְ⁠כָל־קְ֝רָבַ֗⁠י אֶת־שֵׁ֥ם קָדְשֽׁ⁠וֹ׃","lĕ⁠dáwi֨d ׀ bá̇ràki֣y na֭pĕşǐ⁠y ʼeţ-yĕhwá֑h wĕ⁠kál-qĕ֝rába֗⁠y ʼeţ-şé֥̌m qádĕşֽ̌⁠wò׃"],[103,2,"בָּרֲכִ֣י נַ֭פְשִׁ⁠י אֶת־יְהוָ֑ה וְ⁠אַל־תִּ֝שְׁכְּחִ֗י כָּל־גְּמוּלָֽי⁠ו׃","bá̇ràki֣y na֭pĕşǐ⁠y ʼeţ-yĕhwá֑h wĕ⁠ʼal-ţi̇֝şĕ̌kĕ̇ẖi֗y ká̇l-gĕ̇mẇláֽy⁠w׃"],[103,3,"הַ⁠סֹּלֵ֥חַ לְ⁠כָל־עֲוֺנֵ֑⁠כִי הָ֝⁠רֹפֵ֗א לְ⁠כָל־תַּחֲלֻאָֽיְ⁠כִי׃","ha⁠sò̇lé֥ẖa lĕ⁠kál-ʻàwֺné֑⁠kiy há֝⁠ròpé֗ʼ lĕ⁠kál-ţȧẖàluʼáֽyĕ⁠kiy׃"],[103,4,"הַ⁠גּוֹאֵ֣ל מִ⁠שַּׁ֣חַת חַיָּ֑יְ⁠כִי הַֽ֝⁠מְעַטְּרֵ֗⁠כִי חֶ֣סֶד וְ⁠רַחֲמִֽים׃","ha⁠ġwòʼé֣l mi⁠şȧ֣̌ẖaţ ẖayá֑̇yĕ⁠kiy haֽ֝⁠mĕʻatĕ̇ré֗⁠kiy ẖe֣sed wĕ⁠raẖàmiֽym׃"],[103,5,"הַ⁠מַּשְׂבִּ֣יַע בַּ⁠טּ֣וֹב עֶדְיֵ֑⁠ךְ תִּתְחַדֵּ֖שׁ כַּ⁠נֶּ֣שֶׁר נְעוּרָֽיְ⁠כִי׃","ha⁠mȧşĕ̂bi֣̇yaʻ bȧ⁠ṫ֣wòb ʻedĕyé֑⁠kĕ ţi̇ţĕẖadé֖̇ş̌ kȧ⁠nė֣şěr nĕʻẇráֽyĕ⁠kiy׃"],[103,6,"עֹשֵׂ֣ה צְדָק֣וֹת יְהוָ֑ה וּ֝⁠מִשְׁפָּטִ֗ים לְ⁠כָל־עֲשׁוּקִֽים׃","ʻòşé֣̂h ẕĕdáq֣wòţ yĕhwá֑h ẇ֝⁠mişĕ̌pá̇ti֗ym lĕ⁠kál-ʻàş̌ẇqiֽym׃"],[103,7,"יוֹדִ֣יעַ דְּרָכָ֣י⁠ו לְ⁠מֹשֶׁ֑ה לִ⁠בְנֵ֥י יִ֝שְׂרָאֵ֗ל עֲלִילֽוֹתָי⁠ו׃","ywòdi֣yʻa dĕ̇ráká֣y⁠w lĕ⁠mòşě֑h li⁠bĕné֥y yi֝şĕ̂ráʼé֗l ʻàliylֽwòţáy⁠w׃"],[103,8,"רַח֣וּם וְ⁠חַנּ֣וּן יְהוָ֑ה אֶ֖רֶךְ אַפַּ֣יִם וְ⁠רַב־חָֽסֶד׃","raẖ֣ẇm wĕ⁠ẖaṅ֣ẇn yĕhwá֑h ʼe֖rekĕ ʼapȧ֣yim wĕ⁠rab-ẖáֽsed׃"],[103,9,"לֹֽא־לָ⁠נֶ֥צַח יָרִ֑יב וְ⁠לֹ֖א לְ⁠עוֹלָ֣ם יִטּֽוֹר׃","lòֽʼ-lá⁠ne֥ẕaẖ yári֑yb wĕ⁠lò֖ʼ lĕ⁠ʻwòlá֣m yiṫֽwòr׃"],[103,10,"לֹ֣א כַ֭⁠חֲטָאֵי⁠נוּ עָ֣שָׂה לָ֑⁠נוּ וְ⁠לֹ֥א כַ֝⁠עֲוֺנֹתֵ֗י⁠נוּ גָּמַ֥ל עָלֵֽי⁠נוּ׃","lò֣ʼ ka֭⁠ẖàtáʼéy⁠nẇ ʻá֣şá̂h lá֑⁠nẇ wĕ⁠lò֥ʼ ka֝⁠ʻàwֺnòţé֗y⁠nẇ gá̇ma֥l ʻáléֽy⁠nẇ׃"],[103,11,"כִּ֤י כִ⁠גְבֹ֣הַּ שָׁ֭מַיִם עַל־הָ⁠אָ֑רֶץ גָּבַ֥ר חַ֝סְדּ֗⁠וֹ עַל־יְרֵאָֽי⁠ו׃","ki֤̇y ki⁠gĕbò֣hȧ şá֭̌mayim ʻal-há⁠ʼá֑reẕ gá̇ba֥r ẖa֝sĕḋ֗⁠wò ʻal-yĕréʼáֽy⁠w׃"],[103,12,"כִּ⁠רְחֹ֣ק מִ֭זְרָח מִֽ⁠מַּֽעֲרָ֑ב הִֽרְחִ֥יק מִ֝מֶּ֗⁠נּוּ אֶת־פְּשָׁעֵֽי⁠נוּ׃","ki̇⁠rĕẖò֣q mi֭zĕráẖ miֽ⁠mȧֽʻàrá֑b hiֽrĕẖi֥yq mi֝mė֗⁠ṅẇ ʼeţ-pĕ̇şá̌ʻéֽy⁠nẇ׃"],[103,13,"כְּ⁠רַחֵ֣ם אָ֭ב עַל־בָּנִ֑ים רִחַ֥ם יְ֝הוָ֗ה עַל־יְרֵאָֽי⁠ו׃","kĕ̇⁠raẖé֣m ʼá֭b ʻal-bá̇ni֑ym riẖa֥m yĕ֝hwá֗h ʻal-yĕréʼáֽy⁠w׃"],[103,14,"כִּי־ה֖וּא יָדַ֣ע יִצְרֵ֑⁠נוּ זָ֝כ֗וּר כִּי־עָפָ֥ר אֲנָֽחְנוּ׃","ki̇y-h֖ẇʼ yáda֣ʻ yiẕĕré֑⁠nẇ zá֝k֗ẇr ki̇y-ʻápá֥r ʼànáֽẖĕnẇ׃"],[103,15,"אֱ֭נוֹשׁ כֶּ⁠חָצִ֣יר יָמָ֑י⁠ו כְּ⁠צִ֥יץ הַ֝⁠שָּׂדֶ֗ה כֵּ֣ן יָצִֽיץ׃","ʼè֭nwòş̌ kė⁠ẖáẕi֣yr yámá֑y⁠w kĕ̇⁠ẕi֥yẕ ha֝⁠şá̇̂de֗h ké֣̇n yáẕiֽyẕ׃"],[103,16,"כִּ֤י ר֣וּחַ עָֽבְרָה־בּ֣⁠וֹ וְ⁠אֵינֶ֑⁠נּוּ וְ⁠לֹא־יַכִּירֶ֖⁠נּוּ ע֣וֹד מְקוֹמֽ⁠וֹ׃","ki֤̇y r֣ẇẖa ʻáֽbĕráh-ḃ֣⁠wò wĕ⁠ʼéyne֑⁠ṅẇ wĕ⁠lòʼ-yaki̇yre֖⁠ṅẇ ʻ֣wòd mĕqwòmֽ⁠wò׃"],[103,17,"וְ⁠חֶ֤סֶד יְהוָ֨ה ׀ מֵ⁠עוֹלָ֣ם וְ⁠עַד־ע֭וֹלָם עַל־יְרֵאָ֑י⁠ו וְ֝⁠צִדְקָת֗⁠וֹ לִ⁠בְנֵ֥י בָנִֽים׃","wĕ⁠ẖe֤sed yĕhwá֨h ׀ mé⁠ʻwòlá֣m wĕ⁠ʻad-ʻ֭wòlám ʻal-yĕréʼá֑y⁠w wĕ֝⁠ẕidĕqáţ֗⁠wò li⁠bĕné֥y bániֽym׃"],[103,18,"לְ⁠שֹׁמְרֵ֥י בְרִית֑⁠וֹ וּ⁠לְ⁠זֹכְרֵ֥י פִ֝קֻּדָ֗י⁠ו לַ⁠עֲשׂוֹתָֽ⁠ם׃","lĕ⁠şò̌mĕré֥y bĕriyţ֑⁠wò ẇ⁠lĕ⁠zòkĕré֥y pi֝qu̇dá֗y⁠w la⁠ʻàş̂wòţáֽ⁠m׃"],[103,19,"יְֽהוָ֗ה בַּ֭⁠שָּׁמַיִם הֵכִ֣ין כִּסְא֑⁠וֹ וּ֝⁠מַלְכוּת֗⁠וֹ בַּ⁠כֹּ֥ל מָשָֽׁלָה׃","yĕֽhwá֗h bȧ֭⁠şá̇̌mayim héki֣yn ki̇sĕʼ֑⁠wò ẇ֝⁠malĕkẇţ֗⁠wò bȧ⁠kò֥̇l máşáֽ̌láh׃"],[103,20,"בָּרֲכ֥וּ יְהוָ֗ה מַלְאָ֫כָ֥י⁠ו גִּבֹּ֣רֵי כֹ֭חַ עֹשֵׂ֣י דְבָר֑⁠וֹ לִ֝⁠שְׁמֹ֗עַ בְּ⁠ק֣וֹל דְּבָרֽ⁠וֹ׃","bá̇ràk֥ẇ yĕhwá֗h malĕʼá֫ká֥y⁠w gi̇bò֣̇réy kò֭ẖa ʻòşé֣̂y dĕbár֑⁠wò li֝⁠şĕ̌mò֗ʻa bĕ̇⁠q֣wòl dĕ̇bárֽ⁠wò׃"],[103,21,"בָּרֲכ֣וּ יְ֭הוָה כָּל־צְבָאָ֑י⁠ו מְ֝שָׁרְתָ֗י⁠ו עֹשֵׂ֥י רְצוֹנֽ⁠וֹ׃","bá̇ràk֣ẇ yĕ֭hwáh ká̇l-ẕĕbáʼá֑y⁠w mĕ֝şá̌rĕţá֗y⁠w ʻòşé֥̂y rĕẕwònֽ⁠wò׃"],[103,22,"בָּרֲכ֤וּ יְהוָ֨ה ׀ כָּֽל־מַעֲשָׂ֗י⁠ו בְּ⁠כָל־מְקֹמ֥וֹת מֶמְשַׁלְתּ֑⁠וֹ בָּרֲכִ֥י נַ֝פְשִׁ֗⁠י אֶת־יְהוָֽה׃","bá̇ràk֤ẇ yĕhwá֨h ׀ káֽ̇l-maʻàşá̂֗y⁠w bĕ̇⁠kál-mĕqòm֥wòţ memĕşǎlĕţ֑̇⁠wò bá̇ràki֥y na֝pĕşǐ֗⁠y ʼeţ-yĕhwáֽh׃"],[104,1,"בָּרֲכִ֥י נַפְשִׁ֗⁠י אֶת־יְה֫וָ֥ה יְהוָ֣ה אֱ֭לֹהַ⁠י גָּדַ֣לְתָּ מְּאֹ֑ד ה֭וֹד וְ⁠הָדָ֣ר לָבָֽשְׁתָּ׃","bá̇ràki֥y napĕşǐ֗⁠y ʼeţ-yĕh֫wá֥h yĕhwá֣h ʼè֭lòha⁠y gá̇da֣lĕţá̇ mĕ̇ʼò֑d h֭wòd wĕ⁠hádá֣r lábáֽşĕ̌ţá̇׃"],[104,2,"עֹֽטֶה־א֭וֹר כַּ⁠שַּׂלְמָ֑ה נוֹטֶ֥ה שָׁ֝מַ֗יִם כַּ⁠יְרִיעָֽה׃","ʻòֽteh-ʼ֭wòr kȧ⁠şȧ̂lĕmá֑h nwòte֥h şá̌֝ma֗yim kȧ⁠yĕriyʻáֽh׃"],[104,3,"הַ֥⁠מְקָרֶֽה בַ⁠מַּ֗יִם עֲֽלִיּ֫וֹתָ֥י⁠ו הַ⁠שָּׂם־עָבִ֥ים רְכוּב֑⁠וֹ הַֽ֝⁠מְהַלֵּ֗ךְ עַל־כַּנְפֵי־רֽוּחַ׃","ha֥⁠mĕqáreֽh ba⁠mȧ֗yim ʻàֽliẏ֫wòţá֥y⁠w ha⁠şá̇̂m-ʻábi֥ym rĕkẇb֑⁠wò haֽ֝⁠mĕhalé̇֗kĕ ʻal-kȧnĕpéy-rֽẇẖa׃"],[104,4,"עֹשֶׂ֣ה מַלְאָכָ֣י⁠ו רוּח֑וֹת מְ֝שָׁרְתָ֗י⁠ו אֵ֣שׁ לֹהֵֽט׃","ʻòşê֣h malĕʼáká֣y⁠w rẇẖ֑wòţ mĕ֝şá̌rĕţá֗y⁠w ʼé֣ş̌ lòhéֽt׃"],[104,5,"יָֽסַד־אֶ֭רֶץ עַל־מְכוֹנֶ֑י⁠הָ בַּל־תִּ֝מּ֗וֹט עוֹלָ֥ם וָ⁠עֶֽד׃","yáֽsad-ʼe֭reẕ ʻal-mĕkwòne֑y⁠há bȧl-ţi̇֝ṁ֗wòt ʻwòlá֥m wá⁠ʻeֽd׃"],[104,6,"תְּ֭הוֹם כַּ⁠לְּב֣וּשׁ כִּסִּית֑⁠וֹ עַל־הָ֝רִ֗ים יַֽעַמְדוּ־מָֽיִם׃","ţĕ֭̇hwòm kȧ⁠lĕ̇b֣ẇş̌ ki̇si̇yţ֑⁠wò ʻal-há֝ri֗ym yaֽʻamĕdẇ-máֽyim׃"],[104,7,"מִן־גַּעֲרָ֣תְ⁠ךָ֣ יְנוּס֑וּ⁠ן מִן־ק֥וֹל רַֽ֝עַמְ⁠ךָ֗ יֵחָפֵזֽוּ⁠ן׃","min-gȧʻàrá֣ţĕ⁠ká֣ yĕnẇs֑ẇ⁠n min-q֥wòl raֽ֝ʻamĕ⁠ká֗ yéẖápézֽẇ⁠n׃"],[104,8,"יַעֲל֣וּ הָ֭רִים יֵרְד֣וּ בְקָע֑וֹת אֶל־מְ֝ק֗וֹם זֶ֤ה ׀ יָסַ֬דְתָּ לָ⁠הֶֽם׃","yaʻàl֣ẇ há֭riym yérĕd֣ẇ bĕqáʻ֑wòţ ʼel-mĕ֝q֗wòm ze֤h ׀ yása֬dĕţá̇ lá⁠heֽm׃"],[104,9,"גְּֽבוּל־שַׂ֭מְתָּ בַּל־יַֽעֲבֹר֑וּ⁠ן בַּל־יְ֝שׁוּב֗וּ⁠ן לְ⁠כַסּ֥וֹת הָ⁠אָֽרֶץ׃","gĕֽ̇bẇl-şâ֭mĕţá̇ bȧl-yֽaʻàbòr֑ẇ⁠n bȧl-yĕ֝ş̌ẇb֗ẇ⁠n lĕ⁠kaṡ֥wòţ há⁠ʼáֽreẕ׃"],[104,10,"הַֽ⁠מְשַׁלֵּ֣חַ מַ֭עְיָנִים בַּ⁠נְּחָלִ֑ים בֵּ֥ין הָ֝רִ֗ים יְהַלֵּכֽוּ⁠ן׃","haֽ⁠mĕşǎlé֣̇ẖa ma֭ʻĕyániym bȧ⁠nĕ̇ẖáli֑ym bé֥̇yn há֝ri֗ym yĕhalé̇kֽẇ⁠n׃"],[104,11,"יַ֭שְׁקוּ כָּל־חַיְת֣⁠וֹ שָׂדָ֑י יִשְׁבְּר֖וּ פְרָאִ֣ים צְמָאָֽ⁠ם׃","ya֭şĕ̌qẇ ká̇l-ẖayĕţ֣⁠wò şá̂dá֑y yişĕ̌bĕ̇r֖ẇ pĕráʼi֣ym ẕĕmáʼáֽ⁠m׃"],[104,12,"עֲ֭לֵי⁠הֶם עוֹף־הַ⁠שָּׁמַ֣יִם יִשְׁכּ֑וֹן מִ⁠בֵּ֥ין עֳ֝פָאיִ֗ם יִתְּנוּ־קֽוֹל׃","ʻà֭léy⁠hem ʻwòp-ha⁠şá̇̌ma֣yim yişĕ̌k֑̇wòn mi⁠bé֥̇yn ʻo֝páʼyi֗m yiţĕ̇nẇ-qֽwòl׃"],[104,13,"מַשְׁקֶ֣ה הָ֭רִים מֵ⁠עֲלִיּוֹתָ֑י⁠ו מִ⁠פְּרִ֥י מַ֝עֲשֶׂ֗י⁠ךָ תִּשְׂבַּ֥ע הָ⁠אָֽרֶץ׃","maşĕ̌qe֣h há֭riym mé⁠ʻàliẏwòţá֑y⁠w mi⁠pĕ̇ri֥y ma֝ʻàşê֗y⁠ká ţi̇şĕ̂bȧ֥ʻ há⁠ʼáֽreẕ׃"],[104,14,"מַצְמִ֤יחַ חָצִ֨יר ׀ לַ⁠בְּהֵמָ֗ה וְ֭⁠עֵשֶׂב לַ⁠עֲבֹדַ֣ת הָ⁠אָדָ֑ם לְ⁠ה֥וֹצִיא לֶ֝֗חֶם מִן־הָ⁠אָֽרֶץ׃","maẕĕmi֤yẖa ẖáẕi֨yr ׀ la⁠bĕ̇hémá֗h wĕ֭⁠ʻéşêb la⁠ʻàbòda֣ţ há⁠ʼádá֑m lĕ⁠h֥wòẕiyʼ le֝֗ẖem min-há⁠ʼáֽreẕ׃"],[104,15,"וְ⁠יַ֤יִן ׀ יְשַׂמַּ֬ח לְֽבַב־אֱנ֗וֹשׁ לְ⁠הַצְהִ֣יל פָּנִ֣ים מִ⁠שָּׁ֑מֶן וְ֝⁠לֶ֗חֶם לְֽבַב־אֱנ֥וֹשׁ יִסְעָֽד׃","wĕ⁠ya֤yin ׀ yĕşâmȧ֬ẖ lĕֽbab-ʼèn֗wòş̌ lĕ⁠haẕĕhi֣yl pá̇ni֣ym mi⁠şá֑̇̌men wĕ֝⁠le֗ẖem lĕֽbab-ʼèn֥wòş̌ yisĕʻáֽd׃"],[104,16,"יִ֭שְׂבְּעוּ עֲצֵ֣י יְהוָ֑ה אַֽרְזֵ֥י לְ֝בָנ֗וֹן אֲשֶׁ֣ר נָטָֽע׃","yi֭şĕ̂bĕ̇ʻẇ ʻàẕé֣y yĕhwá֑h ʼaֽrĕzé֥y lĕ֝bán֗wòn ʼàşě֣r nátáֽʻ׃"],[104,17,"אֲשֶׁר־שָׁ֭ם צִפֳּרִ֣ים יְקַנֵּ֑נוּ חֲ֝סִידָ֗ה בְּרוֹשִׁ֥ים בֵּיתָֽ⁠הּ׃","ʼàşěr-şá֭̌m ẕipȯri֣ym yĕqané֑̇nẇ ẖà֝siydá֗h bĕ̇rwòşǐ֥ym bé̇yţáֽ⁠ḣ׃"],[104,18,"הָרִ֣ים הַ֭⁠גְּבֹהִים לַ⁠יְּעֵלִ֑ים סְ֝לָעִ֗ים מַחְסֶ֥ה לַֽ⁠שְׁפַנִּֽים׃","hári֣ym ha֭⁠gĕ̇bòhiym la⁠yĕ̇ʻéli֑ym sĕ֝láʻi֗ym maẖĕse֥h laֽ⁠şĕ̌paniֽ̇ym׃"],[104,19,"עָשָׂ֣ה יָ֭רֵחַ לְ⁠מוֹעֲדִ֑ים שֶׁ֝֗מֶשׁ יָדַ֥ע מְבוֹאֽ⁠וֹ׃","ʻáşá֣̂h yá֭réẖa lĕ⁠mwòʻàdi֑ym şě֝֗meş̌ yáda֥ʻ mĕbwòʼֽ⁠wò׃"],[104,20,"תָּֽשֶׁת־חֹ֭שֶׁךְ וִ֣⁠יהִי לָ֑יְלָה בּֽ⁠וֹ־תִ֝רְמֹ֗שׂ כָּל־חַיְת⁠וֹ־יָֽעַר׃","ţáֽ̇şěţ-ẖò֭şěkĕ wi֣⁠yhiy lá֑yĕláh ḃֽ⁠wò-ţi֝rĕmò֗ş̂ ká̇l-ẖayĕţ⁠wò-yáֽʻar׃"],[104,21,"הַ֭⁠כְּפִירִים שֹׁאֲגִ֣ים לַ⁠טָּ֑רֶף וּ⁠לְ⁠בַקֵּ֖שׁ מֵ⁠אֵ֣ל אָכְלָֽ⁠ם׃","ha֭⁠kĕ̇piyriym şò̌ʼàgi֣ym la⁠tá֑̇rep ẇ⁠lĕ⁠baqé֖̇ş̌ mé⁠ʼé֣l ʼákĕláֽ⁠m׃"],[104,22,"תִּזְרַ֣ח הַ֭⁠שֶּׁמֶשׁ יֵאָסֵפ֑וּ⁠ן וְ⁠אֶל־מְ֝עוֹנֹתָ֗⁠ם יִרְבָּצֽוּ⁠ן׃","ţi̇zĕra֣ẖ ha֭⁠şė̌meş̌ yéʼásép֑ẇ⁠n wĕ⁠ʼel-mĕ֝ʻwònòţá֗⁠m yirĕbá̇ẕֽẇ⁠n׃"],[104,23,"יֵצֵ֣א אָדָ֣ם לְ⁠פָעֳל֑⁠וֹ וְֽ⁠לַ⁠עֲבֹ֖דָת֣⁠וֹ עֲדֵי־עָֽרֶב׃","yéẕé֣ʼ ʼádá֣m lĕ⁠páʻol֑⁠wò wĕֽ⁠la⁠ʻàbò֖dáţ֣⁠wò ʻàdéy-ʻáֽreb׃"],[104,24,"מָֽה־רַבּ֬וּ מַעֲשֶׂ֨י⁠ךָ ׀ יְֽהוָ֗ה כֻּ֭לָּ⁠ם בְּ⁠חָכְמָ֣ה עָשִׂ֑יתָ מָלְאָ֥ה הָ֝⁠אָ֗רֶץ קִנְיָנֶֽ⁠ךָ׃","máֽh-raḃ֬ẇ maʻàşê֨y⁠ká ׀ yĕֽhwá֗h ku֭̇lá̇⁠m bĕ̇⁠ẖákĕmá֣h ʻáşî֑yţá málĕʼá֥h há֝⁠ʼá֗reẕ qinĕyáneֽ⁠ká׃"],[104,25,"זֶ֤ה ׀ הַ⁠יָּ֥ם גָּדוֹל֮ וּ⁠רְחַ֪ב יָ֫דָ֥יִם שָֽׁם־רֶ֭מֶשׂ וְ⁠אֵ֣ין מִסְפָּ֑ר חַיּ֥וֹת קְ֝טַנּ֗וֹת עִם־גְּדֹלֽוֹת׃","ze֤h ׀ ha⁠yá֥̇m gá̇dwòl֮ ẇ⁠rĕẖa֪b yá֫dá֥yim şáֽ̌m-re֭meş̂ wĕ⁠ʼé֣yn misĕpá֑̇r ẖaẏ֥wòţ qĕ֝taṅ֗wòţ ʻim-gĕ̇dòlֽwòţ׃"],[104,26,"שָׁ֭ם אֳנִיּ֣וֹת יְהַלֵּכ֑וּ⁠ן לִ֝וְיָתָ֗ן זֶֽה־יָצַ֥רְתָּ לְ⁠שַֽׂחֶק־בּֽ⁠וֹ׃","şá֭̌m ʼoniẏ֣wòţ yĕhalé̇k֑ẇ⁠n li֝wĕyáţá֗n zeֽh-yáẕa֥rĕţá̇ lĕ⁠şâֽẖeq-ḃֽ⁠wò׃"],[104,27,"כֻּ֭לָּ⁠ם אֵלֶ֣י⁠ךָ יְשַׂבֵּר֑וּ⁠ן לָ⁠תֵ֖ת אָכְלָ֣⁠ם בְּ⁠עִתּֽ⁠וֹ׃","ku֭̇lá̇⁠m ʼéle֣y⁠ká yĕşâbé̇r֑ẇ⁠n lá⁠ţé֖ţ ʼákĕlá֣⁠m bĕ̇⁠ʻiţֽ̇⁠wò׃"],[104,28,"תִּתֵּ֣ן לָ֭⁠הֶם יִלְקֹט֑וּ⁠ן תִּפְתַּ֥ח יָֽ֝דְ⁠ךָ֗ יִשְׂבְּע֥וּ⁠ן טֽוֹב׃","ţi̇ţé֣̇n lá֭⁠hem yilĕqòt֑ẇ⁠n ţi̇pĕţȧ֥ẖ yáֽ֝dĕ⁠ká֗ yişĕ̂bĕ̇ʻ֥ẇ⁠n tֽwòb׃"],[104,29,"תַּסְתִּ֥יר פָּנֶי⁠ךָ֮ יִֽבָּהֵ֫ל֥וּ⁠ן תֹּסֵ֣ף ר֭וּחָ⁠ם יִגְוָע֑וּ⁠ן וְֽ⁠אֶל־עֲפָרָ֥⁠ם יְשׁוּבֽוּ⁠ן׃","ţȧsĕţi֥̇yr pá̇ney⁠ká֮ yiֽbá̇hé֫l֥ẇ⁠n ţò̇sé֣p r֭ẇẖá⁠m yigĕwáʻ֑ẇ⁠n wĕֽ⁠ʼel-ʻàpárá֥⁠m yĕş̌ẇbֽẇ⁠n׃"],[104,30,"תְּשַׁלַּ֣ח ר֭וּחֲ⁠ךָ יִבָּרֵא֑וּ⁠ן וּ֝⁠תְחַדֵּ֗שׁ פְּנֵ֣י אֲדָמָֽה׃","ţĕ̇şǎlȧ֣ẖ r֭ẇẖà⁠ká yibá̇réʼ֑ẇ⁠n ẇ֝⁠ţĕẖadé̇֗ş̌ pĕ̇né֣y ʼàdámáֽh׃"],[104,31,"יְהִ֤י כְב֣וֹד יְהוָ֣ה לְ⁠עוֹלָ֑ם יִשְׂמַ֖ח יְהוָ֣ה בְּ⁠מַעֲשָֽׂי⁠ו׃","yĕhi֤y kĕb֣wòd yĕhwá֣h lĕ⁠ʻwòlá֑m yişĕ̂ma֖ẖ yĕhwá֣h bĕ̇⁠maʻàşáֽ̂y⁠w׃"],[104,32,"הַ⁠מַּבִּ֣יט לָ֭⁠אָרֶץ וַ⁠תִּרְעָ֑ד יִגַּ֖ע בֶּ⁠הָרִ֣ים וְֽ⁠יֶעֱשָֽׁנוּ׃","ha⁠mȧbi֣̇yt lá֭⁠ʼáreẕ wa⁠ţi̇rĕʻá֑d yigȧ֖ʻ bė⁠hári֣ym wֽĕ⁠yeʻèşáֽ̌nẇ׃"],[104,33,"אָשִׁ֣ירָה לַ⁠יהוָ֣ה בְּ⁠חַיָּ֑⁠י אֲזַמְּרָ֖ה לֵ⁠אלֹהַ֣⁠י בְּ⁠עוֹדִֽ⁠י׃","ʼáşǐ֣yráh la⁠yhwá֣h bĕ̇⁠ẖayá֑̇⁠y ʼàzamĕ̇rá֖h lé⁠ʼlòha֣⁠y bĕ̇⁠ʻwòdiֽ⁠y׃"],[104,34,"יֶעֱרַ֣ב עָלָ֣י⁠ו שִׂיחִ֑⁠י אָ֝נֹכִ֗י אֶשְׂמַ֥ח בַּ⁠יהוָֽה׃","yeʻèra֣b ʻálá֣y⁠w şîyẖi֑⁠y ʼá֝nòki֗y ʼeşĕ̂ma֥ẖ bȧ⁠yhwáֽh׃"],[104,35,"יִתַּ֤מּוּ חַטָּאִ֨ים ׀ מִן־הָ⁠אָ֡רֶץ וּ⁠רְשָׁעִ֤ים ׀ ע֤וֹד אֵינָ֗⁠ם בָּרֲכִ֣י נַ֭פְשִׁ⁠י אֶת־יְהוָ֗ה הַֽלְלוּ־יָֽהּ׃","yiţȧ֤ṁẇ ẖatá̇ʼi֨ym ׀ min-há⁠ʼá֡reẕ ẇ⁠rĕşá̌ʻi֤ym ׀ ʻ֤wòd ʼéyná֗⁠m bá̇ràki֣y na֭pĕşǐ⁠y ʼeţ-yĕhwá֗h haֽlĕlẇ-yáֽḣ׃"],[105,1,"הוֹד֣וּ לַ֭⁠יהוָה קִרְא֣וּ בִּ⁠שְׁמ֑⁠וֹ הוֹדִ֥יעוּ בָ֝⁠עַמִּ֗ים עֲלִילוֹתָֽי⁠ו׃","hwòd֣ẇ la֭⁠yhwáh qirĕʼ֣ẇ bi̇⁠şĕ̌m֑⁠wò hwòdi֥yʻẇ bá֝⁠ʻami̇֗ym ʻàliylwòţáֽy⁠w׃"],[105,2,"שִֽׁירוּ־ל֭⁠וֹ זַמְּרוּ־ל֑⁠וֹ שִׂ֝֗יחוּ בְּ⁠כָל־נִפְלְאוֹתָֽי⁠ו׃","şǐֽyrẇ-l֭⁠wò zamĕ̇rẇ-l֑⁠wò şî֝֗yẖẇ bĕ̇⁠kál-nipĕlĕʼwòţáֽy⁠w׃"],[105,3,"הִֽ֭תְהַלְלוּ בְּ⁠שֵׁ֣ם קָדְשׁ֑⁠וֹ יִ֝שְׂמַ֗ח לֵ֤ב ׀ מְבַקְשֵׁ֬י יְהוָֽה׃","hiֽ֭ţĕhalĕlẇ bĕ̇⁠şé֣̌m qádĕş֑̌⁠wò yi֝şĕ̂ma֗ẖ lé֤b ׀ mĕbaqĕşé̌֬y yĕhwáֽh׃"],[105,4,"דִּרְשׁ֣וּ יְהוָ֣ה וְ⁠עֻזּ֑⁠וֹ בַּקְּשׁ֖וּ פָנָ֣י⁠ו תָּמִֽיד׃","di̇rĕş֣̌ẇ yĕhwá֣h wĕ⁠ʻuż֑⁠wò bȧqĕ̇ş֖̌ẇ páná֣y⁠w ţá̇miֽyd׃"],[105,5,"זִכְר֗וּ נִפְלְאוֹתָ֥י⁠ו אֲשֶׁר־עָשָׂ֑ה מֹ֝פְתָ֗י⁠ו וּ⁠מִשְׁפְּטֵי־פִֽי⁠ו׃","zikĕr֗ẇ nipĕlĕʼwòţá֥y⁠w ʼàşěr-ʻáşá֑̂h mò֝pĕţá֗y⁠w ẇ⁠mişĕ̌pĕ̇téy-piֽy⁠w׃"],[105,6,"זֶ֭רַע אַבְרָהָ֣ם עַבְדּ֑⁠וֹ בְּנֵ֖י יַעֲקֹ֣ב בְּחִירָֽי⁠ו׃","ze֭raʻ ʼabĕráhá֣m ʻabĕḋ֑⁠wò bĕ̇né֖y yaʻàqò֣b bĕ̇ẖiyráֽy⁠w׃"],[105,7,"ה֭וּא יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ בְּ⁠כָל־הָ֝⁠אָ֗רֶץ מִשְׁפָּטָֽי⁠ו׃","h֭ẇʼ yĕhwá֣h ʼèlòhé֑y⁠nẇ bĕ̇⁠kál-há֝⁠ʼá֗reẕ mişĕ̌pá̇táֽy⁠w׃"],[105,8,"זָכַ֣ר לְ⁠עוֹלָ֣ם בְּרִית֑⁠וֹ דָּבָ֥ר צִ֝וָּ֗ה לְ⁠אֶ֣לֶף דּֽוֹר׃","záka֣r lĕ⁠ʻwòlá֣m bĕ̇riyţ֑⁠wò dá̇bá֥r ẕi֝wá̇֗h lĕ⁠ʼe֣lep ḋֽwòr׃"],[105,9,"אֲשֶׁ֣ר כָּ֭רַת אֶת־אַבְרָהָ֑ם וּ⁠שְׁב֖וּעָת֣⁠וֹ לְ⁠יִשְׂחָֽק׃","ʼàşě֣r ká֭̇raţ ʼeţ-ʼabĕráhá֑m ẇ⁠şĕ̌b֖ẇʻáţ֣⁠wò lĕ⁠yişĕ̂ẖáֽq׃"],[105,10,"וַ⁠יַּֽעֲמִידֶ֣⁠הָ לְ⁠יַעֲקֹ֣ב לְ⁠חֹ֑ק לְ֝⁠יִשְׂרָאֵ֗ל בְּרִ֣ית עוֹלָֽם׃","wa⁠yȧֽʻàmiyde֣⁠há lĕ⁠yaʻàqò֣b lĕ⁠ẖò֑q lĕ֝⁠yişĕ̂ráʼé֗l bĕ̇ri֣yţ ʻwòláֽm׃"],[105,11,"לֵ⁠אמֹ֗ר לְ⁠ךָ֗ אֶתֵּ֥ן אֶת־אֶֽרֶץ־כְּנָ֑עַן חֶ֝֗בֶל נַחֲלַתְ⁠כֶֽם׃","lé⁠ʼmò֗r lĕ⁠ká֗ ʼeţé֥̇n ʼeţ-ʼeֽreẕ-kĕ̇ná֑ʻan ẖe֝֗bel naẖàlaţĕ⁠keֽm׃"],[105,12,"בִּֽ֭⁠הְיוֹתָ⁠ם מְתֵ֣י מִסְפָּ֑ר כִּ֝⁠מְעַ֗ט וְ⁠גָרִ֥ים בָּֽ⁠הּ׃","biֽ֭̇⁠hĕywòţá⁠m mĕţé֣y misĕpá֑̇r ki̇֝⁠mĕʻa֗t wĕ⁠gári֥ym báֽ̇⁠ḣ׃"],[105,13,"וַֽ֭⁠יִּתְהַלְּכוּ מִ⁠גּ֣וֹי אֶל־גּ֑וֹי מִ֝⁠מַּמְלָכָ֗ה אֶל־עַ֥ם אַחֵֽר׃","waֽ֭⁠yi̇ţĕhalĕ̇kẇ mi⁠ġ֣wòy ʼel-ġ֑wòy mi֝⁠mȧmĕláká֗h ʼel-ʻa֥m ʼaẖéֽr׃"],[105,14,"לֹֽא־הִנִּ֣יחַ אָדָ֣ם לְ⁠עָשְׁקָ֑⁠ם וַ⁠יּ֖וֹכַח עֲלֵי⁠הֶ֣ם מְלָכִֽים׃","lòֽʼ-hini֣̇yẖa ʼádá֣m lĕ⁠ʻáşĕ̌qá֑⁠m wa⁠ẏ֖wòkaẖ ʻàléy⁠he֣m mĕlákiֽym׃"],[105,15,"אַֽל־תִּגְּע֥וּ בִ⁠מְשִׁיחָ֑⁠י וְ֝⁠לִ⁠נְבִיאַ⁠י אַל־תָּרֵֽעוּ׃","ʼaֽl-ţi̇gĕ̇ʻ֥ẇ bi⁠mĕşǐyẖá֑⁠y wĕ֝⁠li⁠nĕbiyʼa⁠y ʼal-ţá̇réֽʻẇ׃"],[105,16,"וַ⁠יִּקְרָ֣א רָ֭עָב עַל־הָ⁠אָ֑רֶץ כָּֽל־מַטֵּה־לֶ֥חֶם שָׁבָֽר׃","wa⁠yi̇qĕrá֣ʼ rá֭ʻáb ʻal-há⁠ʼá֑reẕ káֽ̇l-maté̇h-le֥ẖem şá̌báֽr׃"],[105,17,"שָׁלַ֣ח לִ⁠פְנֵי⁠הֶ֣ם אִ֑ישׁ לְ֝⁠עֶ֗בֶד נִמְכַּ֥ר יוֹסֵֽף׃","şá̌la֣ẖ li⁠pĕnéy⁠he֣m ʼi֑yş̌ lĕ֝⁠ʻe֗bed nimĕkȧ֥r ywòséֽp׃"],[105,18,"עִנּ֣וּ בַ⁠כֶּ֣בֶל רגלי⁠ו בַּ֝רְזֶ֗ל בָּ֣אָה נַפְשֽׁ⁠וֹ׃","ʻiṅ֣ẇ ba⁠kė֣bel rgly⁠w bȧ֝rĕze֗l bá֣̇ʼáh napĕşֽ̌⁠wò׃"],[105,19,"עַד־עֵ֥ת בֹּֽא־דְבָר֑⁠וֹ אִמְרַ֖ת יְהוָ֣ה צְרָפָֽתְ⁠הוּ׃","ʻad-ʻé֥ţ bòֽ̇ʼ-dĕbár֑⁠wò ʼimĕra֖ţ yĕhwá֣h ẕĕrápáֽţĕ⁠hẇ׃"],[105,20,"שָׁ֣לַח מֶ֭לֶךְ וַ⁠יַּתִּירֵ֑⁠הוּ מֹשֵׁ֥ל עַ֝מִּ֗ים וַֽ⁠יְפַתְּחֵֽ⁠הוּ׃","şá֣̌laẖ me֭lekĕ wa⁠yȧţi̇yré֑⁠hẇ mòşé֥̌l ʻa֝mi̇֗ym waֽ⁠yĕpaţĕ̇ẖéֽ⁠hẇ׃"],[105,21,"שָׂמ֣⁠וֹ אָד֣וֹן לְ⁠בֵית֑⁠וֹ וּ֝⁠מֹשֵׁ֗ל בְּ⁠כָל־קִנְיָנֽ⁠וֹ׃","şá̂m֣⁠wò ʼád֣wòn lĕ⁠béyţ֑⁠wò ẇ֝⁠mòşé̌֗l bĕ̇⁠kál-qinĕyánֽ⁠wò׃"],[105,22,"לֶ⁠אְסֹ֣ר שָׂרָ֣י⁠ו בְּ⁠נַפְשׁ֑⁠וֹ וּ⁠זְקֵנָ֥י⁠ו יְחַכֵּֽם׃","le⁠ʼĕsò֣r şá̂rá֣y⁠w bĕ̇⁠napĕş֑̌⁠wò ẇ⁠zĕqéná֥y⁠w yĕẖakéֽ̇m׃"],[105,23,"וַ⁠יָּבֹ֣א יִשְׂרָאֵ֣ל מִצְרָ֑יִם וְ֝⁠יַעֲקֹ֗ב גָּ֣ר בְּ⁠אֶֽרֶץ־חָֽם׃","wa⁠yá̇bò֣ʼ yişĕ̂ráʼé֣l miẕĕrá֑yim wĕ֝⁠yaʻàqò֗b gá֣̇r bĕ̇⁠ʼeֽreẕ-ẖáֽm׃"],[105,24,"וַ⁠יֶּ֣פֶר אֶת־עַמּ֣⁠וֹ מְאֹ֑ד וַ֝⁠יַּֽעֲצִמֵ⁠הוּ מִ⁠צָּרָֽי⁠ו׃","wa⁠yė֣per ʼeţ-ʻaṁ֣⁠wò mĕʼò֑d wa֝⁠yȧֽʻàẕimé⁠hẇ mi⁠ẕá̇ráֽy⁠w׃"],[105,25,"הָפַ֣ךְ לִ֭בָּ⁠ם לִ⁠שְׂנֹ֣א עַמּ֑⁠וֹ לְ֝⁠הִתְנַכֵּ֗ל בַּ⁠עֲבָדָֽי⁠ו׃","hápa֣kĕ li֭bá̇⁠m li⁠şĕ̂nò֣ʼ ʻaṁ֑⁠wò lĕ֝⁠hiţĕnaké̇֗l bȧ⁠ʻàbádáֽy⁠w׃"],[105,26,"שָׁ֭לַח מֹשֶׁ֣ה עַבְדּ֑⁠וֹ אַ֝הֲרֹ֗ן אֲשֶׁ֣ר בָּֽחַר־בּֽ⁠וֹ׃","şá֭̌laẖ mòşě֣h ʻabĕḋ֑⁠wò ʼa֝hàrò֗n ʼàşě֣r báֽ̇ẖar-ḃֽ⁠wò׃"],[105,27,"שָֽׂמוּ־בָ֭⁠ם דִּבְרֵ֣י אֹתוֹתָ֑י⁠ו וּ֝⁠מֹפְתִ֗ים בְּ⁠אֶ֣רֶץ חָֽם׃","şáֽ̂mẇ-bá֭⁠m di̇bĕré֣y ʼòţwòţá֑y⁠w ẇ֝⁠mòpĕţi֗ym bĕ̇⁠ʼe֣reẕ ẖáֽm׃"],[105,28,"שָׁ֣לַֽח חֹ֭שֶׁךְ וַ⁠יַּחְשִׁ֑ךְ וְ⁠לֹֽא־מָ֝ר֗וּ אֶת־דברו⁠ו׃","şá֣̌laֽẖ ẖò֭şěkĕ wa⁠yȧẖĕşǐ֑kĕ wĕ⁠lòֽʼ-má֝r֗ẇ ʼeţ-dbrw⁠w׃"],[105,29,"הָפַ֣ךְ אֶת־מֵימֵי⁠הֶ֣ם לְ⁠דָ֑ם וַ֝⁠יָּ֗מֶת אֶת־דְּגָתָֽ⁠ם׃","hápa֣kĕ ʼeţ-méyméy⁠he֣m lĕ⁠dá֑m wa֝⁠yá̇֗meţ ʼeţ-dĕ̇gáţáֽ⁠m׃"],[105,30,"שָׁרַ֣ץ אַרְצָ֣⁠ם צְפַרְדְּעִ֑ים בְּ֝⁠חַדְרֵ֗י מַלְכֵי⁠הֶֽם׃","şá̌ra֣ẕ ʼarĕẕá֣⁠m ẕĕparĕdĕ̇ʻi֑ym bĕ̇֝⁠ẖadĕré֗y malĕkéy⁠heֽm׃"],[105,31,"אָ֭מַר וַ⁠יָּבֹ֣א עָרֹ֑ב כִּ֝נִּ֗ים בְּ⁠כָל־גְּבוּלָֽ⁠ם׃","ʼá֭mar wa⁠yá̇bò֣ʼ ʻárò֑b ki̇֝ni̇֗ym bĕ̇⁠kál-gĕ̇bẇláֽ⁠m׃"],[105,32,"נָתַ֣ן גִּשְׁמֵי⁠הֶ֣ם בָּרָ֑ד אֵ֖שׁ לֶהָב֣וֹת בְּ⁠אַרְצָֽ⁠ם׃","náţa֣n gi̇şĕ̌méy⁠he֣m bá̇rá֑d ʼé֖ş̌ leháb֣wòţ bĕ̇⁠ʼarĕẕáֽ⁠m׃"],[105,33,"וַ⁠יַּ֣ךְ גַּ֭פְנָ⁠ם וּ⁠תְאֵנָתָ֑⁠ם וַ֝⁠יְשַׁבֵּ֗ר עֵ֣ץ גְּבוּלָֽ⁠ם׃","wa⁠yȧ֣kĕ gȧ֭pĕná⁠m ẇ⁠ţĕʼénáţá֑⁠m wa֝⁠yĕşǎbé̇֗r ʻé֣ẕ gĕ̇bẇláֽ⁠m׃"],[105,34,"אָ֭מַר וַ⁠יָּבֹ֣א אַרְבֶּ֑ה וְ֝⁠יֶ֗לֶק וְ⁠אֵ֣ין מִסְפָּֽר׃","ʼá֭mar wa⁠yá̇bò֣ʼ ʼarĕbė֑h wĕ֝⁠ye֗leq wĕ⁠ʼé֣yn misĕpáֽ̇r׃"],[105,35,"וַ⁠יֹּ֣אכַל כָּל־עֵ֣שֶׂב בְּ⁠אַרְצָ֑⁠ם וַ֝⁠יֹּ֗אכַל פְּרִ֣י אַדְמָתָֽ⁠ם׃","wa⁠yò֣̇ʼkal ká̇l-ʻé֣şêb bĕ̇⁠ʼarĕẕá֑⁠m wa֝⁠yò̇֗ʼkal pĕ̇ri֣y ʼadĕmáţáֽ⁠m׃"],[105,36,"וַ⁠יַּ֣ךְ כָּל־בְּכ֣וֹר בְּ⁠אַרְצָ֑⁠ם רֵ֝אשִׁ֗ית לְ⁠כָל־אוֹנָֽ⁠ם׃","wa⁠yȧ֣kĕ ká̇l-bĕ̇k֣wòr bĕ̇⁠ʼarĕẕá֑⁠m ré֝ʼşǐ֗yţ lĕ⁠kál-ʼwònáֽ⁠m׃"],[105,37,"וַֽ֭⁠יּוֹצִיאֵ⁠ם בְּ⁠כֶ֣סֶף וְ⁠זָהָ֑ב וְ⁠אֵ֖ין בִּ⁠שְׁבָטָ֣י⁠ו כּוֹשֵֽׁל׃","waֽ֭⁠ẏwòẕiyʼé⁠m bĕ̇⁠ke֣sep wĕ⁠záhá֑b wĕ⁠ʼé֖yn bi̇⁠şĕ̌bátá֣y⁠w k̇wòşéֽ̌l׃"],[105,38,"שָׂמַ֣ח מִצְרַ֣יִם בְּ⁠צֵאתָ֑⁠ם כִּֽי־נָפַ֖ל פַּחְדָּ֣⁠ם עֲלֵי⁠הֶֽם׃","şá̂ma֣ẖ miẕĕra֣yim bĕ̇⁠ẕéʼţá֑⁠m kiֽ̇y-nápa֖l pȧẖĕdá֣̇⁠m ʻàléy⁠heֽm׃"],[105,39,"פָּרַ֣שׂ עָנָ֣ן לְ⁠מָסָ֑ךְ וְ֝⁠אֵ֗שׁ לְ⁠הָאִ֥יר לָֽיְלָה׃","pá̇ra֣ş̂ ʻáná֣n lĕ⁠másá֑kĕ wĕ֝⁠ʼé֗ş̌ lĕ⁠háʼi֥yr láֽyĕláh׃"],[105,40,"שָׁאַ֣ל וַ⁠יָּבֵ֣א שְׂלָ֑ו וְ⁠לֶ֥חֶם שָׁ֝מַ֗יִם יַשְׂבִּיעֵֽ⁠ם׃","şá̌ʼa֣l wa⁠yá̇bé֣ʼ şĕ̂lá֑w wĕ⁠le֥ẖem şá̌֝ma֗yim yaşĕ̂bi̇yʻéֽ⁠m׃"],[105,41,"פָּ֣תַח צ֭וּר וַ⁠יָּז֣וּבוּ מָ֑יִם הָ֝לְכ֗וּ בַּ⁠צִּיּ֥וֹת נָהָֽר׃","pá֣̇ţaẖ ẕ֭ẇr wa⁠yá̇z֣ẇbẇ má֑yim há֝lĕk֗ẇ bȧ⁠ẕi̇ẏ֥wòţ náháֽr׃"],[105,42,"כִּֽי־זָ֭כַר אֶת־דְּבַ֣ר קָדְשׁ֑⁠וֹ אֶֽת־אַבְרָהָ֥ם עַבְדּֽ⁠וֹ׃","kiֽ̇y-zá֭kar ʼeţ-dĕ̇ba֣r qádĕş֑̌⁠wò ʼeֽţ-ʼabĕráhá֥m ʻabĕḋֽ⁠wò׃"],[105,43,"וַ⁠יּוֹצִ֣א עַמּ֣⁠וֹ בְ⁠שָׂשׂ֑וֹן בְּ֝⁠רִנָּ֗ה אֶת־בְּחִירָֽי⁠ו׃","wa⁠ẏwòẕi֣ʼ ʻaṁ֣⁠wò bĕ⁠şá̂ş֑̂wòn bĕ̇֝⁠riná̇֗h ʼeţ-bĕ̇ẖiyráֽy⁠w׃"],[105,44,"וַ⁠יִּתֵּ֣ן לָ֭⁠הֶם אַרְצ֣וֹת גּוֹיִ֑ם וַ⁠עֲמַ֖ל לְאֻמִּ֣ים יִירָֽשׁוּ׃","wa⁠yi̇ţé֣̇n lá֭⁠hem ʼarĕẕ֣wòţ ġwòyi֑m wa⁠ʻàma֖l lĕʼumi֣̇ym yiyráֽş̌ẇ׃"],[105,45,"בַּ⁠עֲב֤וּר ׀ יִשְׁמְר֣וּ חֻ֭קָּי⁠ו וְ⁠תוֹרֹתָ֥י⁠ו יִנְצֹ֗רוּ הַֽלְלוּ־יָֽהּ׃","bȧ⁠ʻàb֤ẇr ׀ yişĕ̌mĕr֣ẇ ẖu֭qá̇y⁠w wĕ⁠ţwòròţá֥y⁠w yinĕẕò֗rẇ haֽlĕlẇ-yáֽḣ׃"],[106,1,"הַֽלְלוּ יָ֨הּ ׀ הוֹד֣וּ לַ⁠יהוָ֣ה כִּי־ט֑וֹב כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","haֽlĕlẇ yá֨ḣ ׀ hwòd֣ẇ la⁠yhwá֣h ki̇y-t֑wòb ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[106,2,"מִ֗י יְ֭מַלֵּל גְּבוּר֣וֹת יְהוָ֑ה יַ֝שְׁמִ֗יעַ כָּל־תְּהִלָּתֽ⁠וֹ׃","mi֗y yĕ֭malé̇l gĕ̇bẇr֣wòţ yĕhwá֑h ya֝şĕ̌mi֗yʻa ká̇l-ţĕ̇hilá̇ţֽ⁠wò׃"],[106,3,"אַ֭שְׁרֵי שֹׁמְרֵ֣י מִשְׁפָּ֑ט עֹשֵׂ֖ה צְדָקָ֣ה בְ⁠כָל־עֵֽת׃","ʼa֭şĕ̌réy şò̌mĕré֣y mişĕ̌pá֑̇t ʻòşé֖̂h ẕĕdáqá֣h bĕ⁠kál-ʻéֽţ׃"],[106,4,"זָכְרֵ֣⁠נִי יְ֭הוָה בִּ⁠רְצ֣וֹן עַמֶּ֑⁠ךָ פָּ֝קְדֵ֗⁠נִי בִּ⁠ישׁוּעָתֶֽ⁠ךָ׃","zákĕré֣⁠niy yĕ֭hwáh bi̇⁠rĕẕ֣wòn ʻamė֑⁠ká pá̇֝qĕdé֗⁠niy bi̇⁠yş̌ẇʻáţeֽ⁠ká׃"],[106,5,"לִ⁠רְא֤וֹת ׀ בְּ⁠ט֘וֹבַ֤ת בְּחִירֶ֗י⁠ךָ לִ֭⁠שְׂמֹחַ בְּ⁠שִׂמְחַ֣ת גּוֹיֶ֑⁠ךָ לְ֝⁠הִתְהַלֵּ֗ל עִם־נַחֲלָתֶֽ⁠ךָ׃","li⁠rĕʼ֤wòţ ׀ bĕ̇⁠t֘wòba֤ţ bĕ̇ẖiyre֗y⁠ká li֭⁠şĕ̂mòẖa bĕ̇⁠şîmĕẖa֣ţ ġwòye֑⁠ká lĕ֝⁠hiţĕhalé̇֗l ʻim-naẖàláţeֽ⁠ká׃"],[106,6,"חָטָ֥אנוּ עִם־אֲבוֹתֵ֗י⁠נוּ הֶעֱוִ֥ינוּ הִרְשָֽׁעְנוּ׃","ẖátá֥ʼnẇ ʻim-ʼàbwòţé֗y⁠nẇ heʻèwi֥ynẇ hirĕşáֽ̌ʻĕnẇ׃"],[106,7,"אֲב֘וֹתֵ֤י⁠נוּ בְ⁠מִצְרַ֨יִם ׀ לֹא־הִשְׂכִּ֬ילוּ נִפְלְאוֹתֶ֗י⁠ךָ לֹ֣א זָ֭כְרוּ אֶת־רֹ֣ב חֲסָדֶ֑י⁠ךָ וַ⁠יַּמְר֖וּ עַל־יָ֣ם בְּ⁠יַם־סֽוּף׃","ʼàb֘wòţé֤y⁠nẇ bĕ⁠miẕĕra֨yim ׀ lòʼ-hişĕ̂ki̇֬ylẇ nipĕlĕʼwòţe֗y⁠ká lò֣ʼ zá֭kĕrẇ ʼeţ-rò֣b ẖàsáde֑y⁠ká wa⁠yȧmĕr֖ẇ ʻal-yá֣m bĕ̇⁠yam-sֽẇp׃"],[106,8,"וַֽ֭⁠יּוֹשִׁיעֵ⁠ם לְמַ֣עַן שְׁמ֑⁠וֹ לְ֝⁠הוֹדִ֗יעַ אֶת־גְּבוּרָתֽ⁠וֹ׃","waֽ֭⁠ẏwòşǐyʻé⁠m lĕma֣ʻan şĕ̌m֑⁠wò lĕ֝⁠hwòdi֗yʻa ʼeţ-gĕ̇bẇráţֽ⁠wò׃"],[106,9,"וַ⁠יִּגְעַ֣ר בְּ⁠יַם־ס֭וּף וַֽ⁠יֶּחֱרָ֑ב וַ⁠יּוֹלִיכֵ֥⁠ם בַּ֝⁠תְּהֹמ֗וֹת כַּ⁠מִּדְבָּֽר׃","wa⁠yi̇gĕʻa֣r bĕ̇⁠yam-s֭ẇp wֽa⁠yėẖèrá֑b wa⁠ẏwòliyké֥⁠m bȧ֝⁠ţĕ̇hòm֗wòţ kȧ⁠mi̇dĕbáֽ̇r׃"],[106,10,"וַֽ֭⁠יּוֹשִׁיעֵ⁠ם מִ⁠יַּ֣ד שׂוֹנֵ֑א וַ֝⁠יִּגְאָלֵ֗⁠ם מִ⁠יַּ֥ד אוֹיֵֽב׃","waֽ֭⁠ẏwòşǐyʻé⁠m mi⁠yȧ֣d ş̂wòné֑ʼ wa֝⁠yi̇gĕʼálé֗⁠m mi⁠yȧ֥d ʼwòyéֽb׃"],[106,11,"וַ⁠יְכַסּוּ־מַ֥יִם צָרֵי⁠הֶ֑ם אֶחָ֥ד מֵ֝⁠הֶ֗ם לֹ֣א נוֹתָֽר׃","wa⁠yĕkaṡẇ-ma֥yim ẕáréy⁠he֑m ʼeẖá֥d mé֝⁠he֗m lò֣ʼ nwòţáֽr׃"],[106,12,"וַ⁠יַּאֲמִ֥ינוּ בִ⁠דְבָרָ֑י⁠ו יָ֝שִׁ֗ירוּ תְּהִלָּתֽ⁠וֹ׃","wa⁠yȧʼàmi֥ynẇ bi⁠dĕbárá֑y⁠w yá֝şǐ֗yrẇ ţĕ̇hilá̇ţֽ⁠wò׃"],[106,13,"מִֽ֭הֲרוּ שָׁכְח֣וּ מַעֲשָׂ֑י⁠ו לֹֽא־חִ֝כּ֗וּ לַ⁠עֲצָתֽ⁠וֹ׃","miֽ֭hàrẇ şá̌kĕẖ֣ẇ maʻàşá֑̂y⁠w lòֽʼ-ẖi֝k̇֗ẇ la⁠ʻàẕáţֽ⁠wò׃"],[106,14,"וַ⁠יִּתְאַוּ֣וּ תַ֭אֲוָה בַּ⁠מִּדְבָּ֑ר וַ⁠יְנַסּוּ־אֵ֝֗ל בִּֽ⁠ישִׁימֽוֹן׃","wa⁠yi̇ţĕʼaẇ֣ẇ ţa֭ʼàwáh bȧ⁠mi̇dĕbá֑̇r wa⁠yĕnaṡẇ-ʼé֝֗l biֽ̇⁠yşǐymֽwòn׃"],[106,15,"וַ⁠יִּתֵּ֣ן לָ֭⁠הֶם שֶׁאֱלָתָ֑⁠ם וַ⁠יְשַׁלַּ֖ח רָז֣וֹן בְּ⁠נַפְשָֽׁ⁠ם׃","wa⁠yi̇ţé֣̇n lá֭⁠hem şěʼèláţá֑⁠m wa⁠yĕşǎlȧ֖ẖ ráz֣wòn bĕ̇⁠napĕşáֽ̌⁠m׃"],[106,16,"וַ⁠יְקַנְא֣וּ לְ֭⁠מֹשֶׁה בַּֽ⁠מַּחֲנֶ֑ה לְ֝⁠אַהֲרֹ֗ן קְד֣וֹשׁ יְהוָֽה׃","wa⁠yĕqanĕʼ֣ẇ lĕ֭⁠mòşěh bȧֽ⁠mȧẖàne֑h lĕ֝⁠ʼahàrò֗n qĕd֣wòş̌ yĕhwáֽh׃"],[106,17,"תִּפְתַּח־אֶ֭רֶץ וַ⁠תִּבְלַ֣ע דָּתָ֑ן וַ֝⁠תְּכַ֗ס עַל־עֲדַ֥ת אֲבִירָֽם׃","ţi̇pĕţȧẖ-ʼe֭reẕ wa⁠ţi̇bĕla֣ʻ dá̇ţá֑n wa֝⁠ţĕ̇ka֗s ʻal-ʻàda֥ţ ʼàbiyráֽm׃"],[106,18,"וַ⁠תִּבְעַר־אֵ֥שׁ בַּ⁠עֲדָתָ֑⁠ם לֶ֝הָבָ֗ה תְּלַהֵ֥ט רְשָׁעִֽים׃","wa⁠ţi̇bĕʻar-ʼé֥ş̌ bȧ⁠ʻàdáţá֑⁠m le֝hábá֗h ţĕ̇lahé֥t rĕşá̌ʻiֽym׃"],[106,19,"יַעֲשׂוּ־עֵ֥גֶל בְּ⁠חֹרֵ֑ב וַ֝⁠יִּשְׁתַּחֲו֗וּ לְ⁠מַסֵּכָֽה׃","yaʻàş̂ẇ-ʻé֥gel bĕ̇⁠ẖòré֑b wa֝⁠yi̇şĕ̌ţȧẖàw֗ẇ lĕ⁠masé̇káֽh׃"],[106,20,"וַ⁠יָּמִ֥ירוּ אֶת־כְּבוֹדָ֑⁠ם בְּ⁠תַבְנִ֥ית שׁ֝֗וֹר אֹכֵ֥ל עֵֽשֶׂב׃","wa⁠yá̇mi֥yrẇ ʼeţ-kĕ̇bwòdá֑⁠m bĕ̇⁠ţabĕni֥yţ ş̌֝֗wòr ʼòké֥l ʻéֽşêb׃"],[106,21,"שָׁ֭כְחוּ אֵ֣ל מוֹשִׁיעָ֑⁠ם עֹשֶׂ֖ה גְדֹל֣וֹת בְּ⁠מִצְרָֽיִם׃","şá֭̌kĕẖẇ ʼé֣l mwòşǐyʻá֑⁠m ʻòşê֖h gĕdòl֣wòţ bĕ̇⁠miẕĕráֽyim׃"],[106,22,"נִ֭פְלָאוֹת בְּ⁠אֶ֣רֶץ חָ֑ם נ֝וֹרָא֗וֹת עַל־יַם־סֽוּף׃","ni֭pĕláʼwòţ bĕ̇⁠ʼe֣reẕ ẖá֑m n֝wòráʼ֗wòţ ʻal-yam-sֽẇp׃"],[106,23,"וַ⁠יֹּ֗אמֶר לְֽ⁠הַשְׁמִ֫ידָ֥⁠ם לוּלֵ֡י מֹ֘שֶׁ֤ה בְחִיר֗⁠וֹ עָמַ֣ד בַּ⁠פֶּ֣רֶץ לְ⁠פָנָ֑י⁠ו לְ⁠הָשִׁ֥יב חֲ֝מָת֗⁠וֹ מֵֽ⁠הַשְׁחִֽית׃","wa⁠yò̇֗ʼmer lĕֽ⁠haşĕ̌mi֫ydá֥⁠m lẇlé֡y mò֘şě֤h bĕẖiyr֗⁠wò ʻáma֣d bȧ⁠pė֣reẕ lĕ⁠páná֑y⁠w lĕ⁠háşǐ֥yb ẖà֝máţ֗⁠wò méֽ⁠haşĕ̌ẖiֽyţ׃"],[106,24,"וַֽ֭⁠יִּמְאֲסוּ בְּ⁠אֶ֣רֶץ חֶמְדָּ֑ה לֹֽא־הֶ֝אֱמִ֗ינוּ לִ⁠דְבָרֽ⁠וֹ׃","waֽ֭⁠yi̇mĕʼàsẇ bĕ̇⁠ʼe֣reẕ ẖemĕdá֑̇h lòֽʼ-he֝ʼèmi֗ynẇ li⁠dĕbárֽ⁠wò׃"],[106,25,"וַ⁠יֵּרָגְנ֥וּ בְ⁠אָהֳלֵי⁠הֶ֑ם לֹ֥א שָׁ֝מְע֗וּ בְּ⁠ק֣וֹל יְהוָֽה׃","wa⁠yé̇rágĕn֥ẇ bĕ⁠ʼáholéy⁠he֑m lò֥ʼ şá̌֝mĕʻ֗ẇ bĕ̇⁠q֣wòl yĕhwáֽh׃"],[106,26,"וַ⁠יִּשָּׂ֣א יָד֣⁠וֹ לָ⁠הֶ֑ם לְ⁠הַפִּ֥יל א֝וֹתָ֗⁠ם בַּ⁠מִּדְבָּֽר׃","wa⁠yi̇şá֣̇̂ʼ yád֣⁠wò lá⁠he֑m lĕ⁠hapi֥̇yl ʼ֝wòţá֗⁠m bȧ⁠mi̇dĕbáֽ̇r׃"],[106,27,"וּ⁠לְ⁠הַפִּ֣יל זַ֭רְעָ⁠ם בַּ⁠גּוֹיִ֑ם וּ֝⁠לְ⁠זָרוֹתָ֗⁠ם בָּ⁠אֲרָצֽוֹת׃","ẇ⁠lĕ⁠hapi֣̇yl za֭rĕʻá⁠m bȧ⁠ġwòyi֑m ẇ֝⁠lĕ⁠zárwòţá֗⁠m bá̇⁠ʼàráẕֽwòţ׃"],[106,28,"וַ֭⁠יִּצָּ֣מְדוּ לְ⁠בַ֣עַל פְּע֑וֹר וַ֝⁠יֹּאכְל֗וּ זִבְחֵ֥י מֵתִֽים׃","wa֭⁠yi̇ẕá֣̇mĕdẇ lĕ⁠ba֣ʻal pĕ̇ʻ֑wòr wa֝⁠yò̇ʼkĕl֗ẇ zibĕẖé֥y méţiֽym׃"],[106,29,"וַ֭⁠יַּכְעִיסוּ בְּ⁠מַֽעַלְלֵי⁠הֶ֑ם וַ⁠תִּפְרָץ־בָּ֝֗⁠ם מַגֵּפָֽה׃","wa֭⁠yȧkĕʻiysẇ bĕ̇⁠maֽʻalĕléy⁠he֑m wa⁠ţi̇pĕráẕ-bá̇֝֗⁠m magé̇páֽh׃"],[106,30,"וַ⁠יַּעֲמֹ֣ד פִּֽ֭ינְחָס וַ⁠יְפַלֵּ֑ל וַ֝⁠תֵּעָצַ֗ר הַ⁠מַּגֵּפָֽה׃","wa⁠yȧʻàmò֣d piֽ֭̇ynĕẖás wa⁠yĕpalé֑̇l wa֝⁠ţé̇ʻáẕa֗r ha⁠mȧgé̇páֽh׃"],[106,31,"וַ⁠תֵּחָ֣שֶׁב ל֭⁠וֹ לִ⁠צְדָקָ֑ה לְ⁠דֹ֥ר וָ֝⁠דֹ֗ר עַד־עוֹלָֽם׃","wa⁠ţé̇ẖá֣şěb l֭⁠wò li⁠ẕĕdáqá֑h lĕ⁠dò֥r wá֝⁠dò֗r ʻad-ʻwòláֽm׃"],[106,32,"וַ֭⁠יַּקְצִיפוּ עַל־מֵ֥י מְרִיבָ֑ה וַ⁠יֵּ֥רַע לְ֝⁠מֹשֶׁ֗ה בַּ⁠עֲבוּרָֽ⁠ם׃","wa֭⁠yȧqĕẕiypẇ ʻal-mé֥y mĕriybá֑h wa⁠yé֥̇raʻ lĕ֝⁠mòşě֗h bȧ⁠ʻàbẇráֽ⁠m׃"],[106,33,"כִּֽי־הִמְר֥וּ אֶת־רוּח֑⁠וֹ וַ֝⁠יְבַטֵּ֗א בִּ⁠שְׂפָתָֽי⁠ו׃","kiֽ̇y-himĕr֥ẇ ʼeţ-rẇẖ֑⁠wò wa֝⁠yĕbaté̇֗ʼ bi̇⁠şĕ̂páţáֽy⁠w׃"],[106,34,"לֹֽא־הִ֭שְׁמִידוּ אֶת־הָֽ⁠עַמִּ֑ים אֲשֶׁ֤ר אָמַ֖ר יְהוָ֣ה לָ⁠הֶֽם׃","lòֽʼ-hi֭şĕ̌miydẇ ʼeţ-háֽ⁠ʻami֑̇ym ʼàşě֤r ʼáma֖r yĕhwá֣h lá⁠heֽm׃"],[106,35,"וַ⁠יִּתְעָרְב֥וּ בַ⁠גּוֹיִ֑ם וַֽ֝⁠יִּלְמְד֗וּ מַֽעֲשֵׂי⁠הֶֽם׃","wa⁠yi̇ţĕʻárĕb֥ẇ ba⁠ġwòyi֑m waֽ֝⁠yi̇lĕmĕd֗ẇ maֽʻàşé̂y⁠heֽm׃"],[106,36,"וַ⁠יַּעַבְד֥וּ אֶת־עֲצַבֵּי⁠הֶ֑ם וַ⁠יִּהְי֖וּ לָ⁠הֶ֣ם לְ⁠מוֹקֵֽשׁ׃","wa⁠yȧʻabĕd֥ẇ ʼeţ-ʻàẕabé̇y⁠he֑m wa⁠yi̇hĕy֖ẇ lá⁠he֣m lĕ⁠mwòqéֽş̌׃"],[106,37,"וַ⁠יִּזְבְּח֣וּ אֶת־בְּ֭נֵי⁠הֶם וְ⁠אֶת־בְּנֽוֹתֵי⁠הֶ֗ם לַ⁠שֵּֽׁדִים׃","wa⁠yi̇zĕbĕ̇ẖ֣ẇ ʼeţ-bĕ֭̇néy⁠hem wĕ⁠ʼeţ-bĕ̇nֽwòţéy⁠he֗m la⁠şéֽ̇̌diym׃"],[106,38,"וַ⁠יִּֽשְׁפְּכ֨וּ דָ֪ם נָקִ֡י דַּם־בְּנֵ֘י⁠הֶ֤ם וּֽ⁠בְנוֹתֵי⁠הֶ֗ם אֲשֶׁ֣ר זִ֭בְּחוּ לַ⁠עֲצַבֵּ֣י כְנָ֑עַן וַ⁠תֶּחֱנַ֥ף הָ֝⁠אָ֗רֶץ בַּ⁠דָּמִֽים׃","wa⁠yiֽ̇şĕ̌pĕ̇k֨ẇ dá֪m náqi֡y dȧm-bĕ̇né֘y⁠he֤m ẇֽ⁠bĕnwòţéy⁠he֗m ʼàşě֣r zi֭bĕ̇ẖẇ la⁠ʻàẕabé֣̇y kĕná֑ʻan wa⁠ţėẖèna֥p há֝⁠ʼá֗reẕ bȧ⁠dá̇miֽym׃"],[106,39,"וַ⁠יִּטְמְא֥וּ בְ⁠מַעֲשֵׂי⁠הֶ֑ם וַ֝⁠יִּזְנוּ֗ בְּ⁠מַֽעַלְלֵי⁠הֶֽם׃","wa⁠yi̇tĕmĕʼ֥ẇ bĕ⁠maʻàşé̂y⁠he֑m wa֝⁠yi̇zĕnẇ֗ bĕ̇⁠maֽʻalĕléy⁠heֽm׃"],[106,40,"וַ⁠יִּֽחַר־אַ֣ף יְהוָ֣ה בְּ⁠עַמּ֑⁠וֹ וַ֝⁠יְתָעֵ֗ב אֶת־נַחֲלָתֽ⁠וֹ׃","wa⁠yiֽ̇ẖar-ʼa֣p yĕhwá֣h bĕ̇⁠ʻaṁ֑⁠wò wa֝⁠yĕţáʻé֗b ʼeţ-naẖàláţֽ⁠wò׃"],[106,41,"וַ⁠יִּתְּנֵ֥⁠ם בְּ⁠יַד־גּוֹיִ֑ם וַֽ⁠יִּמְשְׁל֥וּ בָ֝⁠הֶ֗ם שֹׂנְאֵי⁠הֶֽם׃","wa⁠yi̇ţĕ̇né֥⁠m bĕ̇⁠yad-ġwòyi֑m waֽ⁠yi̇mĕşĕ̌l֥ẇ bá֝⁠he֗m şò̂nĕʼéy⁠heֽm׃"],[106,42,"וַ⁠יִּלְחָצ֥וּ⁠ם אוֹיְבֵי⁠הֶ֑ם וַ֝⁠יִּכָּנְע֗וּ תַּ֣חַת יָדָֽ⁠ם׃","wa⁠yi̇lĕẖáẕ֥ẇ⁠m ʼwòyĕbéy⁠he֑m wa֝⁠yi̇ká̇nĕʻ֗ẇ ţȧ֣ẖaţ yádáֽ⁠m׃"],[106,43,"פְּעָמִ֥ים רַבּ֗וֹת יַצִּ֫ילֵ֥⁠ם וְ֭⁠הֵמָּה יַמְר֣וּ בַ⁠עֲצָתָ֑⁠ם וַ֝⁠יָּמֹ֗כּוּ בַּ⁠עֲוֺנָֽ⁠ם׃","pĕ̇ʻámi֥ym raḃ֗wòţ yaẕi̇֫ylé֥⁠m wĕ֭⁠hémá̇h yamĕr֣ẇ ba⁠ʻàẕáţá֑⁠m wa֝⁠yá̇mò֗k̇ẇ bȧ⁠ʻàwֺnáֽ⁠m׃"],[106,44,"וַ֭⁠יַּרְא בַּ⁠צַּ֣ר לָ⁠הֶ֑ם בְּ֝⁠שָׁמְע֗⁠וֹ אֶת־רִנָּתָֽ⁠ם׃","wa֭⁠yȧrĕʼ bȧ⁠ẕȧ֣r lá⁠he֑m bĕ̇֝⁠şá̌mĕʻ֗⁠wò ʼeţ-riná̇ţáֽ⁠m׃"],[106,45,"וַ⁠יִּזְכֹּ֣ר לָ⁠הֶ֣ם בְּרִית֑⁠וֹ וַ֝⁠יִּנָּחֵ֗ם כְּ⁠רֹ֣ב חסד⁠ו׃","wa⁠yi̇zĕkò֣̇r lá⁠he֣m bĕ̇riyţ֑⁠wò wa֝⁠yi̇ná̇ẖé֗m kĕ̇⁠rò֣b ẖsd⁠w׃"],[106,46,"וַ⁠יִּתֵּ֣ן אוֹתָ֣⁠ם לְ⁠רַחֲמִ֑ים לִ֝⁠פְנֵ֗י כָּל־שׁוֹבֵי⁠הֶֽם׃","wa⁠yi̇ţé֣̇n ʼwòţá֣⁠m lĕ⁠raẖàmi֑ym li֝⁠pĕné֗y ká̇l-ş̌wòbéy⁠heֽm׃"],[106,47,"הוֹשִׁיעֵ֨⁠נוּ ׀ יְה֘וָ֤ה אֱלֹהֵ֗י⁠נוּ וְ⁠קַבְּצֵ⁠נוּ֮ מִֽן־הַ⁠גּ֫וֹיִ֥ם לְ֭⁠הֹדוֹת לְ⁠שֵׁ֣ם קָדְשֶׁ֑⁠ךָ לְ֝⁠הִשְׁתַּבֵּ֗חַ בִּ⁠תְהִלָּתֶֽ⁠ךָ׃","hwòşǐyʻé֨⁠nẇ ׀ yĕh֘wá֤h ʼèlòhé֗y⁠nẇ wĕ⁠qabĕ̇ẕé⁠nẇ֮ miֽn-ha⁠ġ֫wòyi֥m lĕ֭⁠hòdwòţ lĕ⁠şé֣̌m qádĕşě֑⁠ká lĕ֝⁠hişĕ̌ţȧbé̇֗ẖa bi̇⁠ţĕhilá̇ţeֽ⁠ká׃"],[106,48,"בָּר֤וּךְ־יְהוָ֨ה אֱלֹהֵ֪י יִשְׂרָאֵ֡ל מִן־הָ֤⁠עוֹלָ֨ם ׀ וְ⁠עַ֬ד הָ⁠עוֹלָ֗ם וְ⁠אָמַ֖ר כָּל־הָ⁠עָ֥ם אָמֵ֗ן הַֽלְלוּ־יָֽהּ׃","bá̇r֤ẇkĕ-yĕhwá֨h ʼèlòhé֪y yişĕ̂ráʼé֡l min-há֤⁠ʻwòlá֨m ׀ wĕ⁠ʻa֬d há⁠ʻwòlá֗m wĕ⁠ʼáma֖r ká̇l-há⁠ʻá֥m ʼámé֗n haֽlĕlẇ-yáֽḣ׃"],[107,1,"הֹד֣וּ לַ⁠יהוָ֣ה כִּי־ט֑וֹב כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","hòd֣ẇ la⁠yhwá֣h ki̇y-t֑wòb ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[107,2,"יֹ֭אמְרוּ גְּאוּלֵ֣י יְהוָ֑ה אֲשֶׁ֥ר גְּ֝אָלָ֗⁠ם מִ⁠יַּד־צָֽר׃","yò֭ʼmĕrẇ gĕ̇ʼẇlé֣y yĕhwá֑h ʼàşě֥r gĕ̇֝ʼálá֗⁠m mi⁠yȧd-ẕáֽr׃"],[107,3,"וּֽ⁠מֵ⁠אֲרָצ֗וֹת קִ֫בְּצָ֥⁠ם מִ⁠מִּזְרָ֥ח וּ⁠מִֽ⁠מַּעֲרָ֑ב מִ⁠צָּפ֥וֹן וּ⁠מִ⁠יָּֽם׃","ẇֽ⁠mé⁠ʼàráẕ֗wòţ qi֫bĕ̇ẕá֥⁠m mi⁠mi̇zĕrá֥ẖ ẇ⁠miֽ⁠mȧʻàrá֑b mi⁠ẕá̇p֥wòn ẇ⁠mi⁠yáֽ̇m׃"],[107,4,"תָּע֣וּ בַ֭⁠מִּדְבָּר בִּ⁠ישִׁימ֣וֹן דָּ֑רֶךְ עִ֥יר מ֝וֹשָׁ֗ב לֹ֣א מָצָֽאוּ׃","ţá̇ʻ֣ẇ ba֭⁠mi̇dĕbá̇r bi̇⁠yşǐym֣wòn dá֑̇rekĕ ʻi֥yr m֝wòşá̌֗b lò֣ʼ máẕáֽʼẇ׃"],[107,5,"רְעֵבִ֥ים גַּם־צְמֵאִ֑ים נַ֝פְשָׁ֗⁠ם בָּ⁠הֶ֥ם תִּתְעַטָּֽף׃","rĕʻébi֥ym gȧm-ẕĕméʼi֑ym na֝pĕşá̌֗⁠m bá̇⁠he֥m ţi̇ţĕʻatáֽ̇p׃"],[107,6,"וַ⁠יִּצְעֲק֣וּ אֶל־יְ֭הוָה בַּ⁠צַּ֣ר לָ⁠הֶ֑ם מִ֝⁠מְּצֽוּקוֹתֵי⁠הֶ֗ם יַצִּילֵֽ⁠ם׃","wa⁠yi̇ẕĕʻàq֣ẇ ʼel-yĕ֭hwáh bȧ⁠ẕȧ֣r lá⁠he֑m mi֝⁠mĕ̇ẕֽẇqwòţéy⁠he֗m yaẕi̇yléֽ⁠m׃"],[107,7,"וַ֭⁠יַּֽדְרִיכֵ⁠ם בְּ⁠דֶ֣רֶךְ יְשָׁרָ֑ה לָ֝⁠לֶ֗כֶת אֶל־עִ֥יר מוֹשָֽׁב׃","wa֭⁠ẏֽadĕriyké⁠m bĕ̇⁠de֣rekĕ yĕşá̌rá֑h lá֝⁠le֗keţ ʼel-ʻi֥yr mwòşáֽ̌b׃"],[107,8,"יוֹד֣וּ לַ⁠יהוָ֣ה חַסְדּ֑⁠וֹ וְ֝⁠נִפְלְאוֹתָ֗י⁠ו לִ⁠בְנֵ֥י אָדָֽם׃","ywòd֣ẇ la⁠yhwá֣h ẖasĕḋ֑⁠wò wĕ֝⁠nipĕlĕʼwòţá֗y⁠w li⁠bĕné֥y ʼádáֽm׃"],[107,9,"כִּי־הִ֭שְׂבִּיעַ נֶ֣פֶשׁ שֹׁקֵקָ֑ה וְ⁠נֶ֥פֶשׁ רְ֝עֵבָה מִלֵּא־טֽוֹב׃","ki̇y-hi֭şĕ̂bi̇yʻa ne֣peş̌ şò̌qéqá֑h wĕ⁠ne֥peş̌ rĕ֝ʻébáh milé̇ʼ-tֽwòb׃"],[107,10,"יֹ֭שְׁבֵי חֹ֣שֶׁךְ וְ⁠צַלְמָ֑וֶת אֲסִירֵ֖י עֳנִ֣י וּ⁠בַרְזֶֽל׃","yò֭şĕ̌béy ẖò֣şěkĕ wĕ⁠ẕalĕmá֑weţ ʼàsiyré֖y ʻoni֣y ẇ⁠barĕzeֽl׃"],[107,11,"כִּֽי־הִמְר֥וּ אִמְרֵי־אֵ֑ל וַ⁠עֲצַ֖ת עֶלְי֣וֹן נָאָֽצוּ׃","kiֽ̇y-himĕr֥ẇ ʼimĕréy-ʼé֑l wa⁠ʻàẕa֖ţ ʻelĕy֣wòn náʼáֽẕẇ׃"],[107,12,"וַ⁠יַּכְנַ֣ע בֶּ⁠עָמָ֣ל לִבָּ֑⁠ם כָּ֝שְׁל֗וּ וְ⁠אֵ֣ין עֹזֵֽר׃","wa⁠yȧkĕna֣ʻ bė⁠ʻámá֣l libá֑̇⁠m ká̇֝şĕ̌l֗ẇ wĕ⁠ʼé֣yn ʻòzéֽr׃"],[107,13,"וַ⁠יִּזְעֲק֣וּ אֶל־יְ֭הוָה בַּ⁠צַּ֣ר לָ⁠הֶ֑ם מִ֝⁠מְּצֻֽקוֹתֵי⁠הֶ֗ם יוֹשִׁיעֵֽ⁠ם׃","wa⁠yi̇zĕʻàq֣ẇ ʼel-yĕ֭hwáh bȧ⁠ẕȧ֣r lá⁠he֑m mi֝⁠mĕ̇ẕuֽqwòţéy⁠he֗m ywòşǐyʻéֽ⁠m׃"],[107,14,"יֽ֭וֹצִיאֵ⁠ם מֵ⁠חֹ֣שֶׁךְ וְ⁠צַלְמָ֑וֶת וּ⁠מוֹסְר֖וֹתֵי⁠הֶ֣ם יְנַתֵּֽק׃","yֽ֭wòẕiyʼé⁠m mé⁠ẖò֣şěkĕ wĕ⁠ẕalĕmá֑weţ ẇ⁠mwòsĕr֖wòţéy⁠he֣m yĕnaţéֽ̇q׃"],[107,15,"יוֹד֣וּ לַ⁠יהוָ֣ה חַסְדּ֑⁠וֹ וְ֝⁠נִפְלְאוֹתָ֗י⁠ו לִ⁠בְנֵ֥י אָדָֽם׃","ywòd֣ẇ la⁠yhwá֣h ẖasĕḋ֑⁠wò wĕ֝⁠nipĕlĕʼwòţá֗y⁠w li⁠bĕné֥y ʼádáֽm׃"],[107,16,"כִּֽי־שִׁ֭בַּר דַּלְת֣וֹת נְחֹ֑שֶׁת וּ⁠בְרִיחֵ֖י בַרְזֶ֣ל גִּדֵּֽעַ׃","kiֽ̇y-şǐ֭bȧr dȧlĕţ֣wòţ nĕẖò֑şěţ ẇ⁠bĕriyẖé֖y barĕze֣l gi̇déֽ̇ʻa׃"],[107,17,"אֱ֭וִלִים מִ⁠דֶּ֣רֶךְ פִּשְׁעָ֑⁠ם וּֽ֝⁠מֵ⁠עֲוֺֽנֹתֵי⁠הֶ֗ם יִתְעַנּֽוּ׃","ʼè֭wiliym mi⁠dė֣rekĕ pi̇şĕ̌ʻá֑⁠m ẇֽ֝⁠mé⁠ʻàwֺֽnòţéy⁠he֗m yiţĕʻaṅֽẇ׃"],[107,18,"כָּל־אֹ֭כֶל תְּתַעֵ֣ב נַפְשָׁ֑⁠ם וַ֝⁠יַּגִּ֗יעוּ עַד־שַׁ֥עֲרֵי מָֽוֶת׃","ká̇l-ʼò֭kel ţĕ̇ţaʻé֣b napĕşá֑̌⁠m wa֝⁠yȧgi̇֗yʻẇ ʻad-şǎ֥ʻàréy máֽweţ׃"],[107,19,"וַ⁠יִּזְעֲק֣וּ אֶל־יְ֭הוָה בַּ⁠צַּ֣ר לָ⁠הֶ֑ם מִ֝⁠מְּצֻֽקוֹתֵי⁠הֶ֗ם יוֹשִׁיעֵֽ⁠ם׃","wa⁠yi̇zĕʻàq֣ẇ ʼel-yĕ֭hwáh bȧ⁠ẕȧ֣r lá⁠he֑m mi֝⁠mĕ̇ẕuֽqwòţéy⁠he֗m ywòşǐyʻéֽ⁠m׃"],[107,20,"יִשְׁלַ֣ח דְּ֭בָר⁠וֹ וְ⁠יִרְפָּאֵ֑⁠ם וִֽ֝⁠ימַלֵּ֗ט מִ⁠שְּׁחִיתוֹתָֽ⁠ם׃׆","yişĕ̌la֣ẖ dĕ֭̇bár⁠wò wĕ⁠yirĕpá̇ʼé֑⁠m wiֽ֝⁠ymalé̇֗t mi⁠şĕ̇̌ẖiyţwòţáֽ⁠m׃׆"],[107,21,"יוֹד֣וּ לַ⁠יהוָ֣ה חַסְדּ֑⁠וֹ וְ֝⁠נִפְלְאוֹתָ֗י⁠ו לִ⁠בְנֵ֥י אָדָֽם׃׆","ywòd֣ẇ la⁠yhwá֣h ẖasĕḋ֑⁠wò wĕ֝⁠nipĕlĕʼwòţá֗y⁠w li⁠bĕné֥y ʼádáֽm׃׆"],[107,22,"וְ֭⁠יִזְבְּחוּ זִבְחֵ֣י תוֹדָ֑ה וִֽ⁠יסַפְּר֖וּ מַעֲשָׂ֣י⁠ו בְּ⁠רִנָּֽה׃׆","wĕ֭⁠yizĕbĕ̇ẖẇ zibĕẖé֣y ţwòdá֑h wiֽ⁠ysapĕ̇r֖ẇ maʻàşá֣̂y⁠w bĕ̇⁠rináֽ̇h׃׆"],[107,23,"יוֹרְדֵ֣י הַ֭⁠יָּם בָּ⁠אֳנִיּ֑וֹת עֹשֵׂ֥י מְ֝לָאכָ֗ה בְּ⁠מַ֣יִם רַבִּֽים׃׆","ywòrĕdé֣y ha֭⁠yá̇m bá̇⁠ʼoniẏ֑wòţ ʻòşé֥̂y mĕ֝láʼká֗h bĕ̇⁠ma֣yim rabiֽ̇ym׃׆"],[107,24,"הֵ֣מָּה רָ֭אוּ מַעֲשֵׂ֣י יְהוָ֑ה וְ֝⁠נִפְלְאוֹתָ֗י⁠ו בִּ⁠מְצוּלָֽה׃׆","hé֣má̇h rá֭ʼẇ maʻàşé֣̂y yĕhwá֑h wĕ֝⁠nipĕlĕʼwòţá֗y⁠w bi̇⁠mĕẕẇláֽh׃׆"],[107,25,"וַ⁠יֹּ֗אמֶר וַֽ֭⁠יַּעֲמֵד ר֣וּחַ סְעָרָ֑ה וַ⁠תְּרוֹמֵ֥ם גַּלָּֽי⁠ו׃׆","wa⁠yò̇֗ʼmer waֽ֭⁠yȧʻàméd r֣ẇẖa sĕʻárá֑h wa⁠ţĕ̇rwòmé֥m gȧláֽ̇y⁠w׃׆"],[107,26,"יַעֲל֣וּ שָׁ֭מַיִם יֵרְד֣וּ תְהוֹמ֑וֹת נַ֝פְשָׁ֗⁠ם בְּ⁠רָעָ֥ה תִתְמוֹגָֽג׃","yaʻàl֣ẇ şá֭̌mayim yérĕd֣ẇ ţĕhwòm֑wòţ na֝pĕşá̌֗⁠m bĕ̇⁠ráʻá֥h ţiţĕmwògáֽg׃"],[107,27,"יָח֣וֹגּוּ וְ֭⁠יָנוּעוּ כַּ⁠שִּׁכּ֑וֹר וְ⁠כָל־חָ֝כְמָתָ֗⁠ם תִּתְבַּלָּֽע׃","yáẖ֣wòġẇ wĕ֭⁠yánẇʻẇ kȧ⁠şi̇̌k֑̇wòr wĕ⁠kál-ẖá֝kĕmáţá֗⁠m ţi̇ţĕbȧláֽ̇ʻ׃"],[107,28,"וַ⁠יִּצְעֲק֣וּ אֶל־יְ֭הוָה בַּ⁠צַּ֣ר לָ⁠הֶ֑ם וּֽ֝⁠מִ⁠מְּצֽוּקֹתֵי⁠הֶ֗ם יוֹצִיאֵֽ⁠ם׃","wa⁠yi̇ẕĕʻàq֣ẇ ʼel-yĕ֭hwáh bȧ⁠ẕȧ֣r lá⁠he֑m ẇֽ֝⁠mi⁠mĕ̇ẕֽẇqòţéy⁠he֗m ywòẕiyʼéֽ⁠m׃"],[107,29,"יָקֵ֣ם סְ֭עָרָה לִ⁠דְמָמָ֑ה וַ֝⁠יֶּחֱשׁ֗וּ גַּלֵּי⁠הֶֽם׃","yáqé֣m sĕ֭ʻáráh li⁠dĕmámá֑h wa֝⁠yėẖèş̌֗ẇ gȧlé̇y⁠heֽm׃"],[107,30,"וַ⁠יִּשְׂמְח֥וּ כִֽי־יִשְׁתֹּ֑קוּ וַ֝⁠יַּנְחֵ֗⁠ם אֶל־מְח֥וֹז חֶפְצָֽ⁠ם׃","wa⁠yi̇şĕ̂mĕẖ֥ẇ kiֽy-yişĕ̌ţò֑̇qẇ wa֝⁠yȧnĕẖé֗⁠m ʼel-mĕẖ֥wòz ẖepĕẕáֽ⁠m׃"],[107,31,"יוֹד֣וּ לַ⁠יהוָ֣ה חַסְדּ֑⁠וֹ וְ֝⁠נִפְלְאוֹתָ֗י⁠ו לִ⁠בְנֵ֥י אָדָֽם׃","ywòd֣ẇ la⁠yhwá֣h ẖasĕḋ֑⁠wò wĕ֝⁠nipĕlĕʼwòţá֗y⁠w li⁠bĕné֥y ʼádáֽm׃"],[107,32,"וִֽ֭⁠ירֹמְמוּ⁠הוּ בִּ⁠קְהַל־עָ֑ם וּ⁠בְ⁠מוֹשַׁ֖ב זְקֵנִ֣ים יְהַלְלֽוּ⁠הוּ׃","wiֽ֭⁠yròmĕmẇ⁠hẇ bi̇⁠qĕhal-ʻá֑m ẇ⁠bĕ⁠mwòşǎ֖b zĕqéni֣ym yĕhalĕlֽẇ⁠hẇ׃"],[107,33,"יָשֵׂ֣ם נְהָר֣וֹת לְ⁠מִדְבָּ֑ר וּ⁠מֹצָ֥אֵי מַ֝֗יִם לְ⁠צִמָּאֽוֹן׃","yáşé֣̂m nĕhár֣wòţ lĕ⁠midĕbá֑̇r ẇ⁠mòẕá֥ʼéy ma֝֗yim lĕ⁠ẕimá̇ʼֽwòn׃"],[107,34,"אֶ֣רֶץ פְּ֭רִי לִ⁠מְלֵחָ֑ה מֵ֝⁠רָעַ֗ת יֹ֣שְׁבֵי בָֽ⁠הּ׃","ʼe֣reẕ pĕ֭̇riy li⁠mĕléẖá֑h mé֝⁠ráʻa֗ţ yò֣şĕ̌béy báֽ⁠ḣ׃"],[107,35,"יָשֵׂ֣ם מִ֭דְבָּר לַֽ⁠אֲגַם־מַ֑יִם וְ⁠אֶ֥רֶץ צִ֝יָּ֗ה לְ⁠מֹצָ֥אֵי מָֽיִם׃","yáşé֣̂m mi֭dĕbá̇r laֽ⁠ʼàgam-ma֑yim wĕ⁠ʼe֥reẕ ẕi֝yá̇֗h lĕ⁠mòẕá֥ʼéy máֽyim׃"],[107,36,"וַ⁠יּ֣וֹשֶׁב שָׁ֣ם רְעֵבִ֑ים וַ֝⁠יְכוֹנְנ֗וּ עִ֣יר מוֹשָֽׁב׃","wa⁠ẏ֣wòşěb şá֣̌m rĕʻébi֑ym wa֝⁠yĕkwònĕn֗ẇ ʻi֣yr mwòşáֽ̌b׃"],[107,37,"וַ⁠יִּזְרְע֣וּ שָׂ֭דוֹת וַ⁠יִּטְּע֣וּ כְרָמִ֑ים וַ֝⁠יַּעֲשׂ֗וּ פְּרִ֣י תְבֽוּאָה׃","wa⁠yi̇zĕrĕʻ֣ẇ şá֭̂dwòţ wa⁠yi̇tĕ̇ʻ֣ẇ kĕrámi֑ym wa֝⁠yȧʻàş̂֗ẇ pĕ̇ri֣y ţĕbֽẇʼáh׃"],[107,38,"וַ⁠יְבָרֲכֵ֣⁠ם וַ⁠יִּרְבּ֣וּ מְאֹ֑ד וּ֝⁠בְהֶמְתָּ֗⁠ם לֹ֣א יַמְעִֽיט׃","wa⁠yĕbáràké֣⁠m wa⁠yi̇rĕḃ֣ẇ mĕʼò֑d ẇ֝⁠bĕhemĕţá̇֗⁠m lò֣ʼ yamĕʻiֽyt׃"],[107,39,"וַ⁠יִּמְעֲט֥וּ וַ⁠יָּשֹׁ֑חוּ מֵ⁠עֹ֖צֶר רָעָ֣ה וְ⁠יָגֽוֹן׃׆","wa⁠yi̇mĕʻàt֥ẇ wa⁠yá̇şò֑̌ẖẇ mé⁠ʻò֖ẕer ráʻá֣h wĕ⁠yágֽwòn׃׆"],[107,40,"שֹׁפֵ֣ךְ בּ֭וּז עַל־נְדִיבִ֑ים וַ֝⁠יַּתְעֵ֗⁠ם בְּ⁠תֹ֣הוּ לֹא־דָֽרֶךְ׃","şò̌pé֣kĕ ḃ֭ẇz ʻal-nĕdiybi֑ym wa֝⁠yȧţĕʻé֗⁠m bĕ̇⁠ţò֣hẇ lòʼ-dáֽrekĕ׃"],[107,41,"וַ⁠יְשַׂגֵּ֣ב אֶבְי֣וֹן מֵ⁠ע֑וֹנִי וַ⁠יָּ֥שֶׂם כַּ֝⁠צֹּ֗אן מִשְׁפָּחֽוֹת׃","wa⁠yĕşâgé֣̇b ʼebĕy֣wòn mé⁠ʻ֑wòniy wa⁠yá֥̇şêm kȧ֝⁠ẕò̇֗ʼn mişĕ̌pá̇ẖֽwòţ׃"],[107,42,"יִרְא֣וּ יְשָׁרִ֣ים וְ⁠יִשְׂמָ֑חוּ וְ⁠כָל־עַ֝וְלָ֗ה קָ֣פְצָה פִּֽי⁠הָ׃","yirĕʼ֣ẇ yĕşá̌ri֣ym wĕ⁠yişĕ̂má֑ẖẇ wĕ⁠kál-ʻa֝wĕlá֗h qá֣pĕẕáh piֽ̇y⁠há׃"],[107,43,"מִי־חָכָ֥ם וְ⁠יִשְׁמָר־אֵ֑לֶּה וְ֝⁠יִתְבּֽוֹנְנ֗וּ חַֽסְדֵ֥י יְהוָֽה׃","miy-ẖáká֥m wĕ⁠yişĕ̌már-ʼé֑lėh wĕ֝⁠yiţĕḃֽwònĕn֗ẇ ẖaֽsĕdé֥y yĕhwáֽh׃"],[108,1,"נָכ֣וֹן לִבִּ֣⁠י אֱלֹהִ֑ים אָשִׁ֥ירָה וַ֝⁠אֲזַמְּרָ֗ה אַף־כְּבוֹדִֽ⁠י׃","nák֣wòn libi֣̇⁠y ʼèlòhi֑ym ʼáşǐ֥yráh wa֝⁠ʼàzamĕ̇rá֗h ʼap-kĕ̇bwòdiֽ⁠y׃"],[108,2,"ע֭וּרָֽ⁠ה הַ⁠נֵּ֥בֶל וְ⁠כִנּ֗וֹר אָעִ֥ירָה שָּֽׁחַר׃","ʻ֭ẇráֽ⁠h ha⁠né֥̇bel wĕ⁠kiṅ֗wòr ʼáʻi֥yráh şáֽ̇̌ẖar׃"],[108,3,"אוֹדְ⁠ךָ֖ בָ⁠עַמִּ֥ים ׀ יְהוָ֑ה וַ֝⁠אֲזַמֶּרְ⁠ךָ֗ בַּל־אֻמִּֽים׃","ʼwòdĕ⁠ká֖ bá⁠ʻami֥̇ym ׀ yĕhwá֑h wa֝⁠ʼàzamėrĕ⁠ká֗ bȧl-ʼumiֽ̇ym׃"],[108,4,"כִּֽי־גָד֣וֹל מֵֽ⁠עַל־שָׁמַ֣יִם חַסְדֶּ֑⁠ךָ וְֽ⁠עַד־שְׁחָקִ֥ים אֲמִתֶּֽ⁠ךָ׃","kiֽ̇y-gád֣wòl méֽ⁠ʻal-şá̌ma֣yim ẖasĕdė֑⁠ká wĕֽ⁠ʻad-şĕ̌ẖáqi֥ym ʼàmiţėֽ⁠ká׃"],[108,5,"ר֣וּמָ⁠ה עַל־שָׁמַ֣יִם אֱלֹהִ֑ים וְ⁠עַ֖ל כָּל־הָ⁠אָ֣רֶץ כְּבוֹדֶֽ⁠ךָ׃","r֣ẇmá⁠h ʻal-şá̌ma֣yim ʼèlòhi֑ym wĕ⁠ʻa֖l ká̇l-há⁠ʼá֣reẕ kĕ̇bwòdeֽ⁠ká׃"],[108,6,"לְ֭מַעַן יֵחָלְצ֣וּ⁠ן יְדִידֶ֑י⁠ךָ הוֹשִׁ֖יעָ⁠ה יְמִֽינְ⁠ךָ֣ וַ⁠עֲנֵֽ⁠נִי׃","lĕ֭maʻan yéẖálĕẕ֣ẇ⁠n yĕdiyde֑y⁠ká hwòşǐ֖yʻá⁠h yĕmiֽynĕ⁠ká֣ wa⁠ʻànéֽ⁠niy׃"],[108,7,"אֱלֹהִ֤ים ׀ דִּבֶּ֥ר בְּ⁠קָדְשׁ֗⁠וֹ אֶעְלֹ֥זָה אֲחַלְּקָ֥ה שְׁכֶ֑ם וְ⁠עֵ֖מֶק סֻכּ֣וֹת אֲמַדֵּֽד׃","ʼèlòhi֤ym ׀ di̇bė֥r bĕ̇⁠qádĕş̌֗⁠wò ʼeʻĕlò֥záh ʼàẖalĕ̇qá֥h şĕ̌ke֑m wĕ⁠ʻé֖meq suk֣̇wòţ ʼàmadéֽ̇d׃"],[108,8,"לִ֤⁠י גִלְעָ֨ד ׀ לִ֤⁠י מְנַשֶּׁ֗ה וְ֭⁠אֶפְרַיִם מָע֣וֹז רֹאשִׁ֑⁠י יְ֝הוּדָ֗ה מְחֹקְקִֽ⁠י׃","li֤⁠y gilĕʻá֨d ׀ li֤⁠y mĕnaşė̌֗h wĕ֭⁠ʼepĕrayim máʻ֣wòz ròʼşǐ֑⁠y yĕ֝hẇdá֗h mĕẖòqĕqiֽ⁠y׃"],[108,9,"מוֹאָ֤ב ׀ סִ֬יר רַחְצִ֗⁠י עַל־אֱ֭דוֹם אַשְׁלִ֣יךְ נַעֲלִ֑⁠י עֲלֵֽי־פְ֝לֶ֗שֶׁת אֶתְרוֹעָֽע׃","mwòʼá֤b ׀ si֬yr raẖĕẕi֗⁠y ʻal-ʼè֭dwòm ʼaşĕ̌li֣ykĕ naʻàli֑⁠y ʻàléֽy-pĕ֝le֗şěţ ʼeţĕrwòʻáֽʻ׃"],[108,10,"מִ֣י יֹ֭בִלֵ⁠נִי עִ֣יר מִבְצָ֑ר מִ֖י נָחַ֣⁠נִי עַד־אֱדֽוֹם׃","mi֣y yò֭bilé⁠niy ʻi֣yr mibĕẕá֑r mi֖y náẖa֣⁠niy ʻad-ʼèdֽwòm׃"],[108,11,"הֲ⁠לֹֽא־אֱלֹהִ֥ים זְנַחְתָּ֑⁠נוּ וְֽ⁠לֹא־תֵצֵ֥א אֱ֝לֹהִ֗ים בְּ⁠צִבְאֹתֵֽי⁠נוּ׃","hà⁠lòֽʼ-ʼèlòhi֥ym zĕnaẖĕţá֑̇⁠nẇ wĕֽ⁠lòʼ-ţéẕé֥ʼ ʼè֝lòhi֗ym bĕ̇⁠ẕibĕʼòţéֽy⁠nẇ׃"],[108,12,"הָֽבָ⁠ה־לָּ֣⁠נוּ עֶזְרָ֣ת מִ⁠צָּ֑ר וְ֝⁠שָׁ֗וְא תְּשׁוּעַ֥ת אָדָֽם׃","háֽbá⁠h-lá֣̇⁠nẇ ʻezĕrá֣ţ mi⁠ẕá֑̇r wĕ֝⁠şá̌֗wĕʼ ţĕ̇ş̌ẇʻa֥ţ ʼádáֽm׃"],[108,13,"בֵּֽ⁠אלֹהִ֥ים נַעֲשֶׂה־חָ֑יִל וְ֝⁠ה֗וּא יָב֥וּס צָרֵֽי⁠נוּ׃","béֽ̇⁠ʼlòhi֥ym naʻàşêh-ẖá֑yil wĕ֝⁠h֗ẇʼ yáb֥ẇs ẕáréֽy⁠nẇ׃"],[109,1,"לַ֭⁠מְנַצֵּחַ לְ⁠דָוִ֣ד מִזְמ֑וֹר אֱלֹהֵ֥י תְ֝הִלָּתִ֗⁠י אַֽל־תֶּחֱרַֽשׁ׃","la֭⁠mĕnaẕé̇ẖa lĕ⁠dáwi֣d mizĕm֑wòr ʼèlòhé֥y ţĕ֝hilá̇ţi֗⁠y ʼaֽl-ţėẖèraֽş̌׃"],[109,2,"כִּ֤י פִ֪י רָשָׁ֡ע וּֽ⁠פִי־מִ֭רְמָה עָלַ֣⁠י פָּתָ֑חוּ דִּבְּר֥וּ אִ֝תִּ֗⁠י לְשׁ֣וֹן שָֽׁקֶר׃","ki֤̇y pi֪y ráşá̌֡ʻ ẇֽ⁠piy-mi֭rĕmáh ʻála֣⁠y pá̇ţá֑ẖẇ di̇bĕ̇r֥ẇ ʼi֝ţi̇֗⁠y lĕş֣̌wòn şáֽ̌qer׃"],[109,3,"וְ⁠דִבְרֵ֣י שִׂנְאָ֣ה סְבָב֑וּ⁠נִי וַ⁠יִּֽלָּחֲמ֥וּ⁠נִי חִנָּֽם׃","wĕ⁠dibĕré֣y şînĕʼá֣h sĕbáb֑ẇ⁠niy wa⁠yiֽ̇lá̇ẖàm֥ẇ⁠niy ẖináֽ̇m׃"],[109,4,"תַּֽחַת־אַהֲבָתִ֥⁠י יִשְׂטְנ֗וּ⁠נִי וַ⁠אֲנִ֥י תְפִלָּֽה׃","ţȧֽẖaţ-ʼahàbáţi֥⁠y yişĕ̂tĕn֗ẇ⁠niy wa⁠ʼàni֥y ţĕpiláֽ̇h׃"],[109,5,"וַ⁠יָּ֘שִׂ֤ימוּ עָלַ֣⁠י רָ֭עָה תַּ֣חַת טוֹבָ֑ה וְ֝⁠שִׂנְאָ֗ה תַּ֣חַת אַהֲבָתִֽ⁠י׃","wa⁠yá̇֘şî֤ymẇ ʻála֣⁠y rá֭ʻáh ţȧ֣ẖaţ twòbá֑h wĕ֝⁠şînĕʼá֗h ţȧ֣ẖaţ ʼahàbáţiֽ⁠y׃"],[109,6,"הַפְקֵ֣ד עָלָ֣י⁠ו רָשָׁ֑ע וְ֝⁠שָׂטָ֗ן יַעֲמֹ֥ד עַל־יְמִינֽ⁠וֹ׃","hapĕqé֣d ʻálá֣y⁠w ráşá֑̌ʻ wĕ֝⁠şá̂tá֗n yaʻàmò֥d ʻal-yĕmiynֽ⁠wò׃"],[109,7,"בְּ֭⁠הִשָּׁ֣פְט⁠וֹ יֵצֵ֣א רָשָׁ֑ע וּ֝⁠תְפִלָּת֗⁠וֹ תִּהְיֶ֥ה לַֽ⁠חֲטָאָֽה׃","bĕ֭̇⁠hişá֣̇̌pĕt⁠wò yéẕé֣ʼ ráşá֑̌ʻ ẇ֝⁠ţĕpilá̇ţ֗⁠wò ţi̇hĕye֥h laֽ⁠ẖàtáʼáֽh׃"],[109,8,"יִֽהְיֽוּ־יָמָ֥י⁠ו מְעַטִּ֑ים פְּ֝קֻדָּת֗⁠וֹ יִקַּ֥ח אַחֵֽר׃","yiֽhĕyֽẇ-yámá֥y⁠w mĕʻati֑̇ym pĕ̇֝qudá̇ţ֗⁠wò yiqȧ֥ẖ ʼaẖéֽr׃"],[109,9,"יִֽהְיוּ־בָנָ֥י⁠ו יְתוֹמִ֑ים וְ֝⁠אִשְׁתּ⁠וֹ אַלְמָנָֽה׃","yiֽhĕyẇ-báná֥y⁠w yĕţwòmi֑ym wĕ֝⁠ʼişĕ̌ţ̇⁠wò ʼalĕmánáֽh׃"],[109,10,"וְ⁠נ֤וֹעַ יָנ֣וּעוּ בָנָ֣י⁠ו וְ⁠שִׁאֵ֑לוּ וְ֝⁠דָרְשׁ֗וּ מֵ⁠חָרְבוֹתֵי⁠הֶֽם׃","wĕ⁠n֤wòʻa yán֣ẇʻẇ báná֣y⁠w wĕ⁠şǐʼé֑lẇ wĕ֝⁠dárĕş̌֗ẇ mé⁠ẖárĕbwòţéy⁠heֽm׃"],[109,11,"יְנַקֵּ֣שׁ נ֭וֹשֶׁה לְ⁠כָל־אֲשֶׁר־ל֑⁠וֹ וְ⁠יָבֹ֖זּוּ זָרִ֣ים יְגִיעֽ⁠וֹ׃","yĕnaqé֣̇ş̌ n֭wòşěh lĕ⁠kál-ʼàşěr-l֑⁠wò wĕ⁠yábò֖żẇ zári֣ym yĕgiyʻֽ⁠wò׃"],[109,12,"אַל־יְהִי־ל֭⁠וֹ מֹשֵׁ֣ךְ חָ֑סֶד וְֽ⁠אַל־יְהִ֥י ח֝וֹנֵ֗ן לִ⁠יתוֹמָֽי⁠ו׃","ʼal-yĕhiy-l֭⁠wò mòşé֣̌kĕ ẖá֑sed wĕֽ⁠ʼal-yĕhi֥y ẖ֝wòné֗n li⁠yţwòmáֽy⁠w׃"],[109,13,"יְהִֽי־אַחֲרִית֥⁠וֹ לְ⁠הַכְרִ֑ית בְּ⁠ד֥וֹר אַ֝חֵ֗ר יִמַּ֥ח שְׁמָֽ⁠ם׃","yĕhiֽy-ʼaẖàriyţ֥⁠wò lĕ⁠hakĕri֑yţ bĕ̇⁠d֥wòr ʼa֝ẖé֗r yimȧ֥ẖ şĕ̌máֽ⁠m׃"],[109,14,"יִזָּכֵ֤ר ׀ עֲוֺ֣ן אֲ֭בֹתָי⁠ו אֶל־יְהוָ֑ה וְ⁠חַטַּ֥את אִ֝מּ֗⁠וֹ אַל־תִּמָּֽח׃","yizá̇ké֤r ׀ ʻàwֺ֣n ʼà֭bòţáy⁠w ʼel-yĕhwá֑h wĕ⁠ẖatȧ֥ʼţ ʼi֝ṁ֗⁠wò ʼal-ţi̇máֽ̇ẖ׃"],[109,15,"יִהְי֣וּ נֶֽגֶד־יְהוָ֣ה תָּמִ֑יד וְ⁠יַכְרֵ֖ת מֵ⁠אֶ֣רֶץ זִכְרָֽ⁠ם׃","yihĕy֣ẇ neֽged-yĕhwá֣h ţá̇mi֑yd wĕ⁠yakĕré֖ţ mé⁠ʼe֣reẕ zikĕráֽ⁠m׃"],[109,16,"יַ֗עַן אֲשֶׁ֤ר ׀ לֹ֥א זָכַר֮ עֲשׂ֪וֹת חָ֥סֶד וַ⁠יִּרְדֹּ֡ף אִישׁ־עָנִ֣י וְ֭⁠אֶבְיוֹן וְ⁠נִכְאֵ֨ה לֵבָ֬ב לְ⁠מוֹתֵֽת׃","ya֗ʻan ʼàşě֤r ׀ lò֥ʼ zákar֮ ʻàş֪̂wòţ ẖá֥sed wa⁠yi̇rĕdò̇֡p ʼiyş̌-ʻáni֣y wĕ֭⁠ʼebĕywòn wĕ⁠nikĕʼé֨h lébá֬b lĕ⁠mwòţéֽţ׃"],[109,17,"וַ⁠יֶּאֱהַ֣ב קְ֭לָלָה וַ⁠תְּבוֹאֵ֑⁠הוּ וְֽ⁠לֹא־חָפֵ֥ץ בִּ֝⁠בְרָכָ֗ה וַ⁠תִּרְחַ֥ק מִמֶּֽ⁠נּוּ׃","wa⁠yėʼèha֣b qĕ֭láláh wa⁠ţĕ̇bwòʼé֑⁠hẇ wĕֽ⁠lòʼ-ẖápé֥ẕ bi̇֝⁠bĕráká֗h wa⁠ţi̇rĕẖa֥q mimėֽ⁠ṅẇ׃"],[109,18,"וַ⁠יִּלְבַּ֥שׁ קְלָלָ֗ה כְּ⁠מַ֫דּ֥⁠וֹ וַ⁠תָּבֹ֣א כַ⁠מַּ֣יִם בְּ⁠קִרְבּ֑⁠וֹ וְ֝⁠כַ⁠שֶּׁ֗מֶן בְּ⁠עַצְמוֹתָֽי⁠ו׃","wa⁠yi̇lĕbȧ֥ş̌ qĕlálá֗h kĕ̇⁠ma֫ḋ֥⁠wò wa⁠ţá̇bò֣ʼ ka⁠mȧ֣yim bĕ̇⁠qirĕḃ֑⁠wò wĕ֝⁠ka⁠şė̌֗men bĕ̇⁠ʻaẕĕmwòţáֽy⁠w׃"],[109,19,"תְּהִי־ל֭⁠וֹ כְּ⁠בֶ֣גֶד יַעְטֶ֑ה וּ֝⁠לְ⁠מֵ֗זַח תָּמִ֥יד יַחְגְּרֶֽ⁠הָ׃","ţĕ̇hiy-l֭⁠wò kĕ̇⁠be֣ged yaʻĕte֑h ẇ֝⁠lĕ⁠mé֗zaẖ ţá̇mi֥yd yaẖĕgĕ̇reֽ⁠há׃"],[109,20,"זֹ֤את פְּעֻלַּ֣ת שֹׂ֭טְנַ⁠י מֵ⁠אֵ֣ת יְהוָ֑ה וְ⁠הַ⁠דֹּבְרִ֥ים רָ֝֗ע עַל־נַפְשִֽׁ⁠י׃","zò֤ʼţ pĕ̇ʻulȧ֣ţ şò֭̂tĕna⁠y mé⁠ʼé֣ţ yĕhwá֑h wĕ⁠ha⁠dò̇bĕri֥ym rá֝֗ʻ ʻal-napĕşǐֽ⁠y׃"],[109,21,"וְ⁠אַתָּ֤ה ׀ יְה֘וִ֤ה אֲדֹנָ֗⁠י עֲֽשֵׂה־אִ֭תִּ⁠י לְמַ֣עַן שְׁמֶ֑⁠ךָ כִּי־ט֥וֹב חַ֝סְדְּ⁠ךָ֗ הַצִּילֵֽ⁠נִי׃","wĕ⁠ʼaţá֤̇h ׀ yĕh֘wi֤h ʼàdòná֗⁠y ʻàֽşé̂h-ʼi֭ţi̇⁠y lĕma֣ʻan şĕ̌me֑⁠ká ki̇y-t֥wòb ẖa֝sĕdĕ̇⁠ká֗ haẕi̇yléֽ⁠niy׃"],[109,22,"כִּֽי־עָנִ֣י וְ⁠אֶבְי֣וֹן אָנֹ֑כִי וְ֝⁠לִבִּ֗⁠י חָלַ֥ל בְּ⁠קִרְבִּֽ⁠י׃","kiֽ̇y-ʻáni֣y wĕ⁠ʼebĕy֣wòn ʼánò֑kiy wĕ֝⁠libi̇֗⁠y ẖála֥l bĕ̇⁠qirĕbiֽ̇⁠y׃"],[109,23,"כְּ⁠צֵל־כִּ⁠נְטוֹת֥⁠וֹ נֶהֱלָ֑כְתִּי נִ֝נְעַ֗רְתִּי כָּֽ⁠אַרְבֶּֽה׃","kĕ̇⁠ẕél-ki̇⁠nĕtwòţ֥⁠wò nehèlá֑kĕţi̇y ni֝nĕʻa֗rĕţi̇y káֽ̇⁠ʼarĕbėֽh׃"],[109,24,"בִּ֭רְכַּ⁠י כָּשְׁל֣וּ מִ⁠צּ֑וֹם וּ֝⁠בְשָׂרִ֗⁠י כָּחַ֥שׁ מִ⁠שָּֽׁמֶן׃","bi֭̇rĕkȧ⁠y ká̇şĕ̌l֣ẇ mi⁠ẕ֑̇wòm ẇ֝⁠bĕşá̂ri֗⁠y ká̇ẖa֥ş̌ mi⁠şáֽ̇̌men׃"],[109,25,"וַ⁠אֲנִ֤י ׀ הָיִ֣יתִי חֶרְפָּ֣ה לָ⁠הֶ֑ם יִ֝רְא֗וּ⁠נִי יְנִיע֥וּ⁠ן רֹאשָֽׁ⁠ם׃","wa⁠ʼàni֤y ׀ háyi֣yţiy ẖerĕpá֣̇h lá⁠he֑m yi֝rĕʼ֗ẇ⁠niy yĕniyʻ֥ẇ⁠n ròʼşáֽ̌⁠m׃"],[109,26,"עָ֭זְרֵ⁠נִי יְהוָ֣ה אֱלֹהָ֑⁠י ה֭וֹשִׁיעֵ֣⁠נִי כְ⁠חַסְדֶּֽ⁠ךָ׃","ʻá֭zĕré⁠niy yĕhwá֣h ʼèlòhá֑⁠y h֭wòşǐyʻé֣⁠niy kĕ⁠ẖasĕdėֽ⁠ká׃"],[109,27,"וְֽ֭⁠יֵדְעוּ כִּי־יָ֣דְ⁠ךָ זֹּ֑את אַתָּ֖ה יְהוָ֣ה עֲשִׂיתָֽ⁠הּ׃","wĕֽ֭⁠yédĕʻẇ ki̇y-yá֣dĕ⁠ká zò֑̇ʼţ ʼaţá֖̇h yĕhwá֣h ʻàşîyţáֽ⁠ḣ׃"],[109,28,"יְקַֽלְלוּ־הֵמָּה֮ וְ⁠אַתָּ֪ה תְבָ֫רֵ֥ךְ קָ֤מוּ ׀ וַ⁠יֵּבֹ֗שׁוּ וְֽ⁠עַבְדְּ⁠ךָ֥ יִשְׂמָֽח׃","yĕqaֽlĕlẇ-hémá̇h֮ wĕ⁠ʼaţá֪̇h ţĕbá֫ré֥kĕ qá֤mẇ ׀ wa⁠yé̇bò֗ş̌ẇ wĕֽ⁠ʻabĕdĕ̇⁠ká֥ yişĕ̂máֽẖ׃"],[109,29,"יִלְבְּשׁ֣וּ שׂוֹטְנַ֣⁠י כְּלִמָּ֑ה וְ⁠יַעֲט֖וּ כַ⁠מְעִ֣יל בָּשְׁתָּֽ⁠ם׃","yilĕbĕ̇ş֣̌ẇ ş̂wòtĕna֣⁠y kĕ̇limá֑̇h wĕ⁠yaʻàt֖ẇ ka⁠mĕʻi֣yl bá̇şĕ̌ţáֽ̇⁠m׃"],[109,30,"א֘וֹדֶ֤ה יְהוָ֣ה מְאֹ֣ד בְּ⁠פִ֑⁠י וּ⁠בְ⁠ת֖וֹךְ רַבִּ֣ים אֲהַֽלְלֶֽ⁠נּוּ׃","ʼ֘wòde֤h yĕhwá֣h mĕʼò֣d bĕ̇⁠pi֑⁠y ẇ⁠bĕ⁠ţ֖wòkĕ rabi֣̇ym ʼàhaֽlĕleֽ⁠ṅẇ׃"],[109,31,"כִּֽי־יַ֭עֲמֹד לִ⁠ימִ֣ין אֶבְי֑וֹן לְ֝⁠הוֹשִׁ֗יעַ מִ⁠שֹּׁפְטֵ֥י נַפְשֽׁ⁠וֹ׃","kiֽ̇y-ya֭ʻàmòd li⁠ymi֣yn ʼebĕy֑wòn lĕ֝⁠hwòşǐ֗yʻa mi⁠şò̇̌pĕté֥y napĕşֽ̌⁠wò׃"],[110,1,"לְ⁠דָוִ֗ד מִ֫זְמ֥וֹר נְאֻ֤ם יְהוָ֨ה ׀ לַֽ⁠אדֹנִ֗⁠י שֵׁ֥ב לִֽ⁠ימִינִ֑⁠י עַד־אָשִׁ֥ית אֹ֝יְבֶ֗י⁠ךָ הֲדֹ֣ם לְ⁠רַגְלֶֽי⁠ךָ׃","lĕ⁠dáwi֗d mi֫zĕm֥wòr nĕʼu֤m yĕhwá֨h ׀ laֽ⁠ʼdòni֗⁠y şé֥̌b liֽ⁠ymiyni֑⁠y ʻad-ʼáşǐ֥yţ ʼò֝yĕbe֗y⁠ká hàdò֣m lĕ⁠ragĕleֽy⁠ká׃"],[110,2,"מַטֵּֽה־עֻזְּ⁠ךָ֗ יִשְׁלַ֣ח יְ֭הוָה מִ⁠צִּיּ֑וֹן רְ֝דֵ֗ה בְּ⁠קֶ֣רֶב אֹיְבֶֽי⁠ךָ׃","matéֽ̇h-ʻuzĕ̇⁠ká֗ yişĕ̌la֣ẖ yĕ֭hwáh mi⁠ẕi̇ẏ֑wòn rĕ֝dé֗h bĕ̇⁠qe֣reb ʼòyĕbeֽy⁠ká׃"],[110,3,"עַמְּ⁠ךָ֣ נְדָבֹת֮ בְּ⁠י֪וֹם חֵ֫ילֶ֥⁠ךָ בְּֽ⁠הַדְרֵי־קֹ֭דֶשׁ מֵ⁠רֶ֣חֶם מִשְׁחָ֑ר לְ֝⁠ךָ֗ טַ֣ל יַלְדֻתֶֽי⁠ךָ׃","ʻamĕ̇⁠ká֣ nĕdábòţ֮ bĕ̇⁠y֪wòm ẖé֫yle֥⁠ká bĕֽ̇⁠hadĕréy-qò֭deş̌ mé⁠re֣ẖem mişĕ̌ẖá֑r lĕ֝⁠ká֗ ta֣l yalĕduţeֽy⁠ká׃"],[110,4,"נִשְׁבַּ֤ע יְהוָ֨ה ׀ וְ⁠לֹ֥א יִנָּחֵ֗ם אַתָּֽה־כֹהֵ֥ן לְ⁠עוֹלָ֑ם עַל־דִּ֝בְרָתִ֗י מַלְכִּי־צֶֽדֶק׃","nişĕ̌bȧ֤ʻ yĕhwá֨h ׀ wĕ⁠lò֥ʼ yiná̇ẖé֗m ʼaţáֽ̇h-kòhé֥n lĕ⁠ʻwòlá֑m ʻal-di̇֝bĕráţi֗y malĕki̇y-ẕeֽdeq׃"],[110,5,"אֲדֹנָ֥⁠י עַל־יְמִֽינְ⁠ךָ֑ מָחַ֖ץ בְּ⁠יוֹם־אַפּ֣⁠וֹ מְלָכִֽים׃","ʼàdòná֥⁠y ʻal-yĕmiֽynĕ⁠ká֑ máẖa֖ẕ bĕ̇⁠ywòm-ʼaṗ֣⁠wò mĕlákiֽym׃"],[110,6,"יָדִ֣ין בַּ֭⁠גּוֹיִם מָלֵ֣א גְוִיּ֑וֹת מָ֥חַץ רֹ֝֗אשׁ עַל־אֶ֥רֶץ רַבָּֽה׃","yádi֣yn bȧ֭⁠ġwòyim málé֣ʼ gĕwiẏ֑wòţ má֥ẖaẕ rò֝֗ʼş̌ ʻal-ʼe֥reẕ rabáֽ̇h׃"],[110,7,"מִ֭⁠נַּחַל בַּ⁠דֶּ֣רֶךְ יִשְׁתֶּ֑ה עַל־כֵּ֝֗ן יָרִ֥ים רֹֽאשׁ׃","mi֭⁠nȧẖal bȧ⁠dė֣rekĕ yişĕ̌ţė֑h ʻal-ké̇֝֗n yári֥ym ròֽʼş̌׃"],[111,1,"הַ֥לְלוּ יָ֨הּ ׀ אוֹדֶ֣ה יְ֭הוָה בְּ⁠כָל־לֵבָ֑ב בְּ⁠ס֖וֹד יְשָׁרִ֣ים וְ⁠עֵדָֽה׃","ha֥lĕlẇ yá֨ḣ ׀ ʼwòde֣h yĕ֭hwáh bĕ̇⁠kál-lébá֑b bĕ̇⁠s֖wòd yĕşá̌ri֣ym wĕ⁠ʻédáֽh׃"],[111,2,"גְּ֭דֹלִים מַעֲשֵׂ֣י יְהוָ֑ה דְּ֝רוּשִׁ֗ים לְ⁠כָל־חֶפְצֵי⁠הֶֽם׃","gĕ֭̇dòliym maʻàşé֣̂y yĕhwá֑h dĕ̇֝rẇşǐ֗ym lĕ⁠kál-ẖepĕẕéy⁠heֽm׃"],[111,3,"הוֹד־וְ⁠הָדָ֥ר פָּֽעֳל֑⁠וֹ וְ֝⁠צִדְקָת֗⁠וֹ עֹמֶ֥דֶת לָ⁠עַֽד׃","hwòd-wĕ⁠hádá֥r páֽ̇ʻol֑⁠wò wĕ֝⁠ẕidĕqáţ֗⁠wò ʻòme֥deţ lá⁠ʻaֽd׃"],[111,4,"זֵ֣כֶר עָ֭שָׂה לְ⁠נִפְלְאֹתָ֑י⁠ו חַנּ֖וּן וְ⁠רַח֣וּם יְהוָֽה׃","zé֣ker ʻá֭şá̂h lĕ⁠nipĕlĕʼòţá֑y⁠w ẖaṅ֖ẇn wĕ⁠raẖ֣ẇm yĕhwáֽh׃"],[111,5,"טֶ֭רֶף נָתַ֣ן לִֽ⁠ירֵאָ֑י⁠ו יִזְכֹּ֖ר לְ⁠עוֹלָ֣ם בְּרִיתֽ⁠וֹ׃","te֭rep náţa֣n liֽ⁠yréʼá֑y⁠w yizĕkò֖̇r lĕ⁠ʻwòlá֣m bĕ̇riyţֽ⁠wò׃"],[111,6,"כֹּ֣חַ מַ֭עֲשָׂי⁠ו הִגִּ֣יד לְ⁠עַמּ֑⁠וֹ לָ⁠תֵ֥ת לָ֝⁠הֶ֗ם נַחֲלַ֥ת גּוֹיִֽם׃","kò֣̇ẖa ma֭ʻàşá̂y⁠w higi֣̇yd lĕ⁠ʻaṁ֑⁠wò lá⁠ţé֥ţ lá֝⁠he֗m naẖàla֥ţ ġwòyiֽm׃"],[111,7,"מַעֲשֵׂ֣י יָ֭דָי⁠ו אֱמֶ֣ת וּ⁠מִשְׁפָּ֑ט נֶ֝אֱמָנִ֗ים כָּל־פִּקּוּדָֽי⁠ו׃","maʻàşé֣̂y yá֭dáy⁠w ʼème֣ţ ẇ⁠mişĕ̌pá֑̇t ne֝ʼèmáni֗ym ká̇l-pi̇q̇ẇdáֽy⁠w׃"],[111,8,"סְמוּכִ֣ים לָ⁠עַ֣ד לְ⁠עוֹלָ֑ם עֲ֝שׂוּיִ֗ם בֶּ⁠אֱמֶ֥ת וְ⁠יָשָֽׁר׃","sĕmẇki֣ym lá⁠ʻa֣d lĕ⁠ʻwòlá֑m ʻà֝ş̂ẇyi֗m bė⁠ʼème֥ţ wĕ⁠yáşáֽ̌r׃"],[111,9,"פְּד֤וּת ׀ שָׁ֘לַ֤ח לְ⁠עַמּ֗⁠וֹ צִוָּֽה־לְ⁠עוֹלָ֥ם בְּרִית֑⁠וֹ קָד֖וֹשׁ וְ⁠נוֹרָ֣א שְׁמֽ⁠וֹ׃","pĕ̇d֤ẇţ ׀ şá̌֘la֤ẖ lĕ⁠ʻaṁ֗⁠wò ẕiwáֽ̇h-lĕ⁠ʻwòlá֥m bĕ̇riyţ֑⁠wò qád֖wòş̌ wĕ⁠nwòrá֣ʼ şĕ̌mֽ⁠wò׃"],[111,10,"רֵ֘אשִׁ֤ית חָכְמָ֨ה ׀ יִרְאַ֬ת יְהוָ֗ה שֵׂ֣כֶל ט֭וֹב לְ⁠כָל־עֹשֵׂי⁠הֶ֑ם תְּ֝הִלָּת֗⁠וֹ עֹמֶ֥דֶת לָ⁠עַֽד׃","ré֘ʼşǐ֤yţ ẖákĕmá֨h ׀ yirĕʼa֬ţ yĕhwá֗h şé֣̂kel t֭wòb lĕ⁠kál-ʻòşé̂y⁠he֑m ţĕ̇֝hilá̇ţ֗⁠wò ʻòme֥deţ lá⁠ʻaֽd׃"],[112,1,"הַ֥לְלוּ יָ֨הּ ׀ אַשְׁרֵי־אִ֭ישׁ יָרֵ֣א אֶת־יְהוָ֑ה בְּ֝⁠מִצְוֺתָ֗י⁠ו חָפֵ֥ץ מְאֹֽד׃","ha֥lĕlẇ yá֨ḣ ׀ ʼaşĕ̌réy-ʼi֭yş̌ yáré֣ʼ ʼeţ-yĕhwá֑h bĕ̇֝⁠miẕĕwֺţá֗y⁠w ẖápé֥ẕ mĕʼòֽd׃"],[112,2,"גִּבּ֣וֹר בָּ֭⁠אָרֶץ יִהְיֶ֣ה זַרְע֑⁠וֹ דּ֭וֹר יְשָׁרִ֣ים יְבֹרָֽךְ׃","gi̇ḃ֣wòr bá֭̇⁠ʼáreẕ yihĕye֣h zarĕʻ֑⁠wò ḋ֭wòr yĕşá̌ri֣ym yĕbòráֽkĕ׃"],[112,3,"הוֹן־וָ⁠עֹ֥שֶׁר בְּ⁠בֵית֑⁠וֹ וְ֝⁠צִדְקָת֗⁠וֹ עֹמֶ֥דֶת לָ⁠עַֽד׃","hwòn-wá⁠ʻò֥şěr bĕ̇⁠béyţ֑⁠wò wĕ֝⁠ẕidĕqáţ֗⁠wò ʻòme֥deţ lá⁠ʻaֽd׃"],[112,4,"זָ֘רַ֤ח בַּ⁠חֹ֣שֶׁךְ א֭וֹר לַ⁠יְשָׁרִ֑ים חַנּ֖וּן וְ⁠רַח֣וּם וְ⁠צַדִּֽיק׃","zá֘ra֤ẖ bȧ⁠ẖò֣şěkĕ ʼ֭wòr la⁠yĕşá̌ri֑ym ẖaṅ֖ẇn wĕ⁠raẖ֣ẇm wĕ⁠ẕadiֽ̇yq׃"],[112,5,"טֽוֹב־אִ֭ישׁ חוֹנֵ֣ן וּ⁠מַלְוֶ֑ה יְכַלְכֵּ֖ל דְּבָרָ֣י⁠ו בְּ⁠מִשְׁפָּֽט׃","tֽwòb-ʼi֭yş̌ ẖwòné֣n ẇ⁠malĕwe֑h yĕkalĕké֖̇l dĕ̇bárá֣y⁠w bĕ̇⁠mişĕ̌páֽ̇t׃"],[112,6,"כִּֽי־לְ⁠עוֹלָ֥ם לֹא־יִמּ֑וֹט לְ⁠זֵ֥כֶר ע֝וֹלָ֗ם יִהְיֶ֥ה צַדִּֽיק׃","kiֽ̇y-lĕ⁠ʻwòlá֥m lòʼ-yiṁ֑wòt lĕ⁠zé֥ker ʻ֝wòlá֗m yihĕye֥h ẕadiֽ̇yq׃"],[112,7,"מִ⁠שְּׁמוּעָ֣ה רָ֭עָה לֹ֣א יִירָ֑א נָכ֥וֹן לִ֝בּ֗⁠וֹ בָּטֻ֥חַ בַּ⁠יהוָֽה׃","mi⁠şĕ̇̌mẇʻá֣h rá֭ʻáh lò֣ʼ yiyrá֑ʼ nák֥wòn li֝ḃ֗⁠wò bá̇tu֥ẖa bȧ⁠yhwáֽh׃"],[112,8,"סָמ֣וּךְ לִ֭בּ⁠וֹ לֹ֣א יִירָ֑א עַ֖ד אֲשֶׁר־יִרְאֶ֣ה בְ⁠צָרָֽי⁠ו׃","sám֣ẇkĕ li֭ḃ⁠wò lò֣ʼ yiyrá֑ʼ ʻa֖d ʼàşěr-yirĕʼe֣h bĕ⁠ẕáráֽy⁠w׃"],[112,9,"פִּזַּ֤ר ׀ נָ֘תַ֤ן לָ⁠אֶבְיוֹנִ֗ים צִ֭דְקָת⁠וֹ עֹמֶ֣דֶת לָ⁠עַ֑ד קַ֝רְנ֗⁠וֹ תָּר֥וּם בְּ⁠כָבֽוֹד׃","pi̇zȧ֤r ׀ ná֘ţa֤n lá⁠ʼebĕywòni֗ym ẕi֭dĕqáţ⁠wò ʻòme֣deţ lá⁠ʻa֑d qa֝rĕn֗⁠wò ţá̇r֥ẇm bĕ̇⁠kábֽwòd׃"],[112,10,"רָ֘שָׁ֤ע יִרְאֶ֨ה ׀ וְ⁠כָעָ֗ס שִׁנָּ֣י⁠ו יַחֲרֹ֣ק וְ⁠נָמָ֑ס תַּאֲוַ֖ת רְשָׁעִ֣ים תֹּאבֵֽד׃","rá֘şá֤̌ʻ yirĕʼe֨h ׀ wĕ⁠káʻá֗s şǐná֣̇y⁠w yaẖàrò֣q wĕ⁠námá֑s ţȧʼàwa֖ţ rĕşá̌ʻi֣ym ţò̇ʼbéֽd׃"],[113,1,"הַ֥לְלוּ יָ֨הּ ׀ הַ֭לְלוּ עַבְדֵ֣י יְהוָ֑ה הַֽ֝לְלוּ אֶת־שֵׁ֥ם יְהוָֽה׃","ha֥lĕlẇ yá֨ḣ ׀ ha֭lĕlẇ ʻabĕdé֣y yĕhwá֑h hֽa֝lĕlẇ ʼeţ-şé֥̌m yĕhwáֽh׃"],[113,2,"יְהִ֤י שֵׁ֣ם יְהוָ֣ה מְבֹרָ֑ךְ מֵֽ֝⁠עַתָּ֗ה וְ⁠עַד־עוֹלָֽם׃","yĕhi֤y şé֣̌m yĕhwá֣h mĕbòrá֑kĕ méֽ֝⁠ʻaţá̇֗h wĕ⁠ʻad-ʻwòláֽm׃"],[113,3,"מִ⁠מִּזְרַח־שֶׁ֥מֶשׁ עַד־מְבוֹא֑⁠וֹ מְ֝הֻלָּ֗ל שֵׁ֣ם יְהוָֽה׃","mi⁠mi̇zĕraẖ-şě֥meş̌ ʻad-mĕbwòʼ֑⁠wò mĕ֝hulá̇֗l şé֣̌m yĕhwáֽh׃"],[113,4,"רָ֖ם עַל־כָּל־גּוֹיִ֥ם ׀ יְהוָ֑ה עַ֖ל הַ⁠שָּׁמַ֣יִם כְּבוֹדֽ⁠וֹ׃","rá֖m ʻal-ká̇l-ġwòyi֥m ׀ yĕhwá֑h ʻa֖l ha⁠şá̇̌ma֣yim kĕ̇bwòdֽ⁠wò׃"],[113,5,"מִ֭י כַּ⁠יהוָ֣ה אֱלֹהֵ֑י⁠נוּ הַֽ⁠מַּגְבִּיהִ֥י לָ⁠שָֽׁבֶת׃","mi֭y kȧ⁠yhwá֣h ʼèlòhé֑y⁠nẇ haֽ⁠mȧgĕbi̇yhi֥y lá⁠şáֽ̌beţ׃"],[113,6,"הַֽ⁠מַּשְׁפִּילִ֥י לִ⁠רְא֑וֹת בַּ⁠שָּׁמַ֥יִם וּ⁠בָ⁠אָֽרֶץ׃","haֽ⁠mȧşĕ̌pi̇yli֥y li⁠rĕʼ֑wòţ bȧ⁠şá̇̌ma֥yim ẇ⁠bá⁠ʼáֽreẕ׃"],[113,7,"מְקִֽימִ֣י מֵ⁠עָפָ֣ר דָּ֑ל מֵֽ֝⁠אַשְׁפֹּ֗ת יָרִ֥ים אֶבְיֽוֹן׃","mĕqiֽymi֣y mé⁠ʻápá֣r dá֑̇l méֽ֝⁠ʼaşĕ̌pò̇֗ţ yári֥ym ʼebĕyֽwòn׃"],[113,8,"לְ⁠הוֹשִׁיבִ֥י עִם־נְדִיבִ֑ים עִ֝֗ם נְדִיבֵ֥י עַמּֽ⁠וֹ׃","lĕ⁠hwòşǐybi֥y ʻim-nĕdiybi֑ym ʻi֝֗m nĕdiybé֥y ʻaṁֽ⁠wò׃"],[113,9,"מֽוֹשִׁיבִ֨י ׀ עֲקֶ֬רֶת הַ⁠בַּ֗יִת אֵֽם־הַ⁠בָּנִ֥ים שְׂמֵחָ֗ה הַֽלְלוּ־יָֽהּ׃","mֽwòşǐybi֨y ׀ ʻàqe֬reţ ha⁠bȧ֗yiţ ʼéֽm-ha⁠bá̇ni֥ym şĕ̂méẖá֗h haֽlĕlẇ-yáֽḣ׃"],[114,1,"בְּ⁠צֵ֣את יִ֭שְׂרָאֵל מִ⁠מִּצְרָ֑יִם בֵּ֥ית יַ֝עֲקֹ֗ב מֵ⁠עַ֥ם לֹעֵֽז׃","bĕ̇⁠ẕé֣ʼţ yi֭şĕ̂ráʼél mi⁠mi̇ẕĕrá֑yim bé֥̇yţ ya֝ʻàqò֗b mé⁠ʻa֥m lòʻéֽz׃"],[114,2,"הָיְתָ֣ה יְהוּדָ֣ה לְ⁠קָדְשׁ֑⁠וֹ יִ֝שְׂרָאֵ֗ל מַמְשְׁלוֹתָֽי⁠ו׃","háyĕţá֣h yĕhẇdá֣h lĕ⁠qádĕş֑̌⁠wò yi֝şĕ̂ráʼé֗l mamĕşĕ̌lwòţáֽy⁠w׃"],[114,3,"הַ⁠יָּ֣ם רָ֭אָה וַ⁠יָּנֹ֑ס הַ֝⁠יַּרְדֵּ֗ן יִסֹּ֥ב לְ⁠אָחֽוֹר׃","ha⁠yá֣̇m rá֭ʼáh wa⁠yá̇nò֑s ha֝⁠yȧrĕdé̇֗n yisò֥̇b lĕ⁠ʼáẖֽwòr׃"],[114,4,"הֶֽ֭⁠הָרִים רָקְד֣וּ כְ⁠אֵילִ֑ים גְּ֝בָע֗וֹת כִּ⁠בְנֵי־צֹֽאן׃","heֽ֭⁠háriym ráqĕd֣ẇ kĕ⁠ʼéyli֑ym gĕ̇֝báʻ֗wòţ ki̇⁠bĕnéy-ẕòֽʼn׃"],[114,5,"מַה־לְּ⁠ךָ֣ הַ֭⁠יָּם כִּ֣י תָנ֑וּס הַ֝⁠יַּרְדֵּ֗ן תִּסֹּ֥ב לְ⁠אָחֽוֹר׃","mah-lĕ̇⁠ká֣ ha֭⁠yá̇m ki֣̇y ţán֑ẇs ha֝⁠yȧrĕdé̇֗n ţi̇sò֥̇b lĕ⁠ʼáẖֽwòr׃"],[114,6,"הֶֽ֭⁠הָרִים תִּרְקְד֣וּ כְ⁠אֵילִ֑ים גְּ֝בָע֗וֹת כִּ⁠בְנֵי־צֹֽאן׃","heֽ֭⁠háriym ţi̇rĕqĕd֣ẇ kĕ⁠ʼéyli֑ym gĕ̇֝báʻ֗wòţ ki̇⁠bĕnéy-ẕòֽʼn׃"],[114,7,"מִ⁠לִּ⁠פְנֵ֣י אָ֭דוֹן ח֣וּלִי אָ֑רֶץ מִ֝⁠לִּ⁠פְנֵ֗י אֱל֣וֹהַּ יַעֲקֹֽב׃","mi⁠li̇⁠pĕné֣y ʼá֭dwòn ẖ֣ẇliy ʼá֑reẕ mi֝⁠li̇⁠pĕné֗y ʼèl֣wòhȧ yaʻàqòֽb׃"],[114,8,"הַ⁠הֹפְכִ֣י הַ⁠צּ֣וּר אֲגַם־מָ֑יִם חַ֝לָּמִ֗ישׁ לְ⁠מַעְיְנ⁠וֹ־מָֽיִם׃","ha⁠hòpĕki֣y ha⁠ẕ֣̇ẇr ʼàgam-má֑yim ẖa֝lá̇mi֗yş̌ lĕ⁠maʻĕyĕn⁠wò-máֽyim׃"],[115,1,"לֹ֤א לָ֥⁠נוּ יְהוָ֗ה לֹ֫א לָ֥⁠נוּ כִּֽי־לְ֭⁠שִׁמְ⁠ךָ תֵּ֣ן כָּב֑וֹד עַל־חַ֝סְדְּ⁠ךָ֗ עַל־אֲמִתֶּֽ⁠ךָ׃","lò֤ʼ lá֥⁠nẇ yĕhwá֗h lò֫ʼ lá֥⁠nẇ kiֽ̇y-lĕ֭⁠şǐmĕ⁠ká ţé֣̇n ká̇b֑wòd ʻal-ẖa֝sĕdĕ̇⁠ká֗ ʻal-ʼàmiţėֽ⁠ká׃"],[115,2,"לָ֭⁠מָּה יֹאמְר֣וּ הַ⁠גּוֹיִ֑ם אַיֵּה־נָ֝֗א אֱלֹהֵי⁠הֶֽם׃","lá֭⁠má̇h yòʼmĕr֣ẇ ha⁠ġwòyi֑m ʼayé̇h-ná֝֗ʼ ʼèlòhéy⁠heֽm׃"],[115,3,"וֵֽ⁠אלֹהֵ֥י⁠נוּ בַ⁠שָּׁמָ֑יִם כֹּ֭ל אֲשֶׁר־חָפֵ֣ץ עָשָֽׂה׃","wéֽ⁠ʼlòhé֥y⁠nẇ ba⁠şá̇̌má֑yim kò֭̇l ʼàşěr-ẖápé֣ẕ ʻáşáֽ̂h׃"],[115,4,"עֲֽ֭צַבֵּי⁠הֶם כֶּ֣סֶף וְ⁠זָהָ֑ב מַ֝עֲשֵׂ֗ה יְדֵ֣י אָדָֽם׃","ʻàֽ֭ẕabé̇y⁠hem kė֣sep wĕ⁠záhá֑b ma֝ʻàşé̂֗h yĕdé֣y ʼádáֽm׃"],[115,5,"פֶּֽה־לָ֭⁠הֶם וְ⁠לֹ֣א יְדַבֵּ֑רוּ עֵינַ֥יִם לָ֝⁠הֶ֗ם וְ⁠לֹ֣א יִרְאֽוּ׃","pėֽh-lá֭⁠hem wĕ⁠lò֣ʼ yĕdabé֑̇rẇ ʻéyna֥yim lá֝⁠he֗m wĕ⁠lò֣ʼ yirĕʼֽẇ׃"],[115,6,"אָזְנַ֣יִם לָ֭⁠הֶם וְ⁠לֹ֣א יִשְׁמָ֑עוּ אַ֥ף לָ֝⁠הֶ֗ם וְ⁠לֹ֣א יְרִיחֽוּ⁠ן׃","ʼázĕna֣yim lá֭⁠hem wĕ⁠lò֣ʼ yişĕ̌má֑ʻẇ ʼa֥p lá֝⁠he֗m wĕ⁠lò֣ʼ yĕriyẖֽẇ⁠n׃"],[115,7,"יְדֵי⁠הֶ֤ם ׀ וְ⁠לֹ֬א יְמִישׁ֗וּ⁠ן רַ֭גְלֵי⁠הֶם וְ⁠לֹ֣א יְהַלֵּ֑כוּ לֹֽא־יֶ֝הְגּ֗וּ בִּ⁠גְרוֹנָֽ⁠ם׃","yĕdéy⁠he֤m ׀ wĕ⁠lò֬ʼ yĕmiyş̌֗ẇ⁠n ra֭gĕléy⁠hem wĕ⁠lò֣ʼ yĕhalé֑̇kẇ lòֽʼ-ye֝hĕġ֗ẇ bi̇⁠gĕrwònáֽ⁠m׃"],[115,8,"כְּ֭מוֹ⁠הֶם יִהְי֣וּ עֹשֵׂי⁠הֶ֑ם כֹּ֭ל אֲשֶׁר־בֹּטֵ֣חַ בָּ⁠הֶֽם׃","kĕ֭̇mwò⁠hem yihĕy֣ẇ ʻòşé̂y⁠he֑m kò֭̇l ʼàşěr-bò̇té֣ẖa bá̇⁠heֽm׃"],[115,9,"יִ֭שְׂרָאֵל בְּטַ֣ח בַּ⁠יהוָ֑ה עֶזְרָ֖⁠ם וּ⁠מָגִנָּ֣⁠ם הֽוּא׃","yi֭şĕ̂ráʼél bĕ̇ta֣ẖ bȧ⁠yhwá֑h ʻezĕrá֖⁠m ẇ⁠máginá֣̇⁠m hֽẇʼ׃"],[115,10,"בֵּ֣ית אַ֭הֲרֹן בִּטְח֣וּ בַ⁠יהוָ֑ה עֶזְרָ֖⁠ם וּ⁠מָגִנָּ֣⁠ם הֽוּא׃","bé֣̇yţ ʼa֭hàròn bi̇tĕẖ֣ẇ ba⁠yhwá֑h ʻezĕrá֖⁠m ẇ⁠máginá֣̇⁠m hֽẇʼ׃"],[115,11,"יִרְאֵ֣י יְ֭הוָה בִּטְח֣וּ בַ⁠יהוָ֑ה עֶזְרָ֖⁠ם וּ⁠מָגִנָּ֣⁠ם הֽוּא׃","yirĕʼé֣y yĕ֭hwáh bi̇tĕẖ֣ẇ ba⁠yhwá֑h ʻezĕrá֖⁠m ẇ⁠máginá֣̇⁠m hֽẇʼ׃"],[115,12,"יְהוָה֮ זְכָרָ֪⁠נוּ יְבָ֫רֵ֥ךְ יְ֭בָרֵךְ אֶת־בֵּ֣ית יִשְׂרָאֵ֑ל יְ֝בָרֵ֗ךְ אֶת־בֵּ֥ית אַהֲרֹֽן׃","yĕhwáh֮ zĕkárá֪⁠nẇ yĕbá֫ré֥kĕ yĕ֭bárékĕ ʼeţ-bé֣̇yţ yişĕ̂ráʼé֑l yĕ֝báré֗kĕ ʼeţ-bé֥̇yţ ʼahàròֽn׃"],[115,13,"יְ֭בָרֵךְ יִרְאֵ֣י יְהוָ֑ה הַ֝⁠קְּטַנִּ֗ים עִם־הַ⁠גְּדֹלִֽים׃","yĕ֭bárékĕ yirĕʼé֣y yĕhwá֑h ha֝⁠qĕ̇tani̇֗ym ʻim-ha⁠gĕ̇dòliֽym׃"],[115,14,"יֹסֵ֣ף יְהוָ֣ה עֲלֵי⁠כֶ֑ם עֲ֝לֵי⁠כֶ֗ם וְ⁠עַל־בְּנֵי⁠כֶֽם׃","yòsé֣p yĕhwá֣h ʻàléy⁠ke֑m ʻà֝léy⁠ke֗m wĕ⁠ʻal-bĕ̇néy⁠keֽm׃"],[115,15,"בְּרוּכִ֣ים אַ֭תֶּם לַ⁠יהוָ֑ה עֹ֝שֵׂ֗ה שָׁמַ֥יִם וָ⁠אָֽרֶץ׃","bĕ̇rẇki֣ym ʼa֭ţėm la⁠yhwá֑h ʻò֝şé̂֗h şá̌ma֥yim wá⁠ʼáֽreẕ׃"],[115,16,"הַ⁠שָּׁמַ֣יִם שָׁ֭מַיִם לַ⁠יהוָ֑ה וְ֝⁠הָ⁠אָ֗רֶץ נָתַ֥ן לִ⁠בְנֵי־אָדָֽם׃","ha⁠şá̇̌ma֣yim şá֭̌mayim la⁠yhwá֑h wĕ֝⁠há⁠ʼá֗reẕ náţa֥n li⁠bĕnéy-ʼádáֽm׃"],[115,17,"לֹ֣א הַ֭⁠מֵּתִים יְהַֽלְלוּ־יָ֑הּ וְ֝⁠לֹ֗א כָּל־יֹרְדֵ֥י דוּמָֽה׃","lò֣ʼ ha֭⁠mé̇ţiym yĕhaֽlĕlẇ-yá֑ḣ wĕ֝⁠lò֗ʼ ká̇l-yòrĕdé֥y dẇmáֽh׃"],[115,18,"וַ⁠אֲנַ֤חְנוּ ׀ נְבָ֘רֵ֤ךְ יָ֗הּ מֵֽ⁠עַתָּ֥ה וְ⁠עַד־עוֹלָ֗ם הַֽלְלוּ־יָֽהּ׃","wa⁠ʼàna֤ẖĕnẇ ׀ nĕbá֘ré֤kĕ yá֗ḣ méֽ⁠ʻaţá֥̇h wĕ⁠ʻad-ʻwòlá֗m haֽlĕlẇ-yáֽḣ׃"],[116,1,"אָ֭הַבְתִּי כִּֽי־יִשְׁמַ֥ע ׀ יְהוָ֑ה אֶת־ק֝וֹלִ֗⁠י תַּחֲנוּנָֽ⁠י׃","ʼá֭habĕţi̇y kiֽ̇y-yişĕ̌ma֥ʻ ׀ yĕhwá֑h ʼeţ-q֝wòli֗⁠y ţȧẖànẇnáֽ⁠y׃"],[116,2,"כִּֽי־הִטָּ֣ה אָזְנ֣⁠וֹ לִ֑⁠י וּ⁠בְ⁠יָמַ֥⁠י אֶקְרָֽא׃","kiֽ̇y-hitá֣̇h ʼázĕn֣⁠wò li֑⁠y ẇ⁠bĕ⁠yáma֥⁠y ʼeqĕráֽʼ׃"],[116,3,"אֲפָפ֤וּ⁠נִי ׀ חֶבְלֵי־מָ֗וֶת וּ⁠מְצָרֵ֣י שְׁא֣וֹל מְצָא֑וּ⁠נִי צָרָ֖ה וְ⁠יָג֣וֹן אֶמְצָֽא׃","ʼàpáp֤ẇ⁠niy ׀ ẖebĕléy-má֗weţ ẇ⁠mĕẕáré֣y şĕ̌ʼ֣wòl mĕẕáʼ֑ẇ⁠niy ẕárá֖h wĕ⁠yág֣wòn ʼemĕẕáֽʼ׃"],[116,4,"וּ⁠בְ⁠שֵֽׁם־יְהוָ֥ה אֶקְרָ֑א אָנָּ֥ה יְ֝הוָ֗ה מַלְּטָ֥⁠ה נַפְשִֽׁ⁠י׃","ẇ⁠bĕ⁠şéֽ̌m-yĕhwá֥h ʼeqĕrá֑ʼ ʼáná֥̇h yĕ֝hwá֗h malĕ̇tá֥⁠h napĕşǐֽ⁠y׃"],[116,5,"חַנּ֣וּן יְהֹוָ֣ה וְ⁠צַדִּ֑יק וֵ֖⁠אלֹהֵ֣י⁠נוּ מְרַחֵֽם׃","ẖaṅ֣ẇn yĕhòwá֣h wĕ⁠ẕadi֑̇yq wé֖⁠ʼlòhé֣y⁠nẇ mĕraẖéֽm׃"],[116,6,"שֹׁמֵ֣ר פְּתָאיִ֣ם יְהֹוָ֑ה דַּ֝לּוֹתִ֗י וְ⁠לִ֣⁠י יְהוֹשִֽׁיעַ׃","şò̌mé֣r pĕ̇ţáʼyi֣m yĕhòwá֑h dȧ֝l̇wòţi֗y wĕ⁠li֣⁠y yĕhwòşǐֽyʻa׃"],[116,7,"שׁוּבִ֣י נַ֭פְשִׁ⁠י לִ⁠מְנוּחָ֑יְ⁠כִי כִּֽי־יְ֝הוָ֗ה גָּמַ֥ל עָלָֽיְ⁠כִי׃","ş̌ẇbi֣y na֭pĕşǐ⁠y li⁠mĕnẇẖá֑yĕ⁠kiy kiֽ̇y-yĕ֝hwá֗h gá̇ma֥l ʻáláֽyĕ⁠kiy׃"],[116,8,"כִּ֤י חִלַּ֥צְתָּ נַפְשִׁ֗⁠י מִ֫⁠מָּ֥וֶת אֶת־עֵינִ֥⁠י מִן־דִּמְעָ֑ה אֶת־רַגְלִ֥⁠י מִ⁠דֶּֽחִי׃","ki֤̇y ẖilȧ֥ẕĕţá̇ napĕşǐ֗⁠y mi֫⁠má֥̇weţ ʼeţ-ʻéyni֥⁠y min-di̇mĕʻá֑h ʼeţ-ragĕli֥⁠y mi⁠dėֽẖiy׃"],[116,9,"אֶ֭תְהַלֵּךְ לִ⁠פְנֵ֣י יְהוָ֑ה בְּ֝⁠אַרְצ֗וֹת הַֽ⁠חַיִּֽים׃","ʼe֭ţĕhalé̇kĕ li⁠pĕné֣y yĕhwá֑h bĕ̇֝⁠ʼarĕẕ֗wòţ haֽ⁠ẖayiֽ̇ym׃"],[116,10,"הֶ֭אֱמַנְתִּי כִּ֣י אֲדַבֵּ֑ר אֲ֝נִ֗י עָנִ֥יתִי מְאֹֽד׃","he֭ʼèmanĕţi̇y ki֣̇y ʼàdabé֑̇r ʼà֝ni֗y ʻáni֥yţiy mĕʼòֽd׃"],[116,11,"אֲ֭נִי אָמַ֣רְתִּי בְ⁠חָפְזִ֑⁠י כָּֽל־הָ⁠אָדָ֥ם כֹּזֵֽב׃","ʼà֭niy ʼáma֣rĕţi̇y bĕ⁠ẖápĕzi֑⁠y káֽ̇l-há⁠ʼádá֥m kò̇zéֽb׃"],[116,12,"מָֽה־אָשִׁ֥יב לַ⁠יהוָ֑ה כָּֽל־תַּגְמוּל֥וֹ⁠הִי עָלָֽ⁠י׃","máֽh-ʼáşǐ֥yb la⁠yhwá֑h káֽ̇l-ţȧgĕmẇl֥wò⁠hiy ʻáláֽ⁠y׃"],[116,13,"כּוֹס־יְשׁוּע֥וֹת אֶשָּׂ֑א וּ⁠בְ⁠שֵׁ֖ם יְהוָ֣ה אֶקְרָֽא׃","k̇wòs-yĕş̌ẇʻ֥wòţ ʼeşá֑̇̂ʼ ẇ⁠bĕ⁠şé֖̌m yĕhwá֣h ʼeqĕráֽʼ׃"],[116,14,"נְ֭דָרַ⁠י לַ⁠יהוָ֣ה אֲשַׁלֵּ֑ם נֶגְדָ⁠ה־נָּ֝֗א לְ⁠כָל־עַמּֽ⁠וֹ׃","nĕ֭dára⁠y la⁠yhwá֣h ʼàşǎlé֑̇m negĕdá⁠h-ná̇֝֗ʼ lĕ⁠kál-ʻaṁֽ⁠wò׃"],[116,15,"יָ֭קָר בְּ⁠עֵינֵ֣י יְהוָ֑ה הַ֝⁠מָּ֗וְתָ⁠ה לַ⁠חֲסִידָֽי⁠ו׃","yá֭qár bĕ̇⁠ʻéyné֣y yĕhwá֑h ha֝⁠má̇֗wĕţá⁠h la⁠ẖàsiydáֽy⁠w׃"],[116,16,"אָֽנָּ֣ה יְהוָה֮ כִּֽי־אֲנִ֪י עַ֫בְדֶּ֥⁠ךָ אֲֽנִי־עַ֭בְדְּ⁠ךָ בֶּן־אֲמָתֶ֑⁠ךָ פִּ֝תַּ֗חְתָּ לְ⁠מוֹסֵרָֽ⁠י׃","ʼֽáná֣̇h yĕhwáh֮ kiֽ̇y-ʼàni֪y ʻa֫bĕdė֥⁠ká ʼàֽniy-ʻa֭bĕdĕ̇⁠ká bėn-ʼàmáţe֑⁠ká pi̇֝ţȧ֗ẖĕţá̇ lĕ⁠mwòséráֽ⁠y׃"],[116,17,"לְֽ⁠ךָ־אֶ֭זְבַּח זֶ֣בַח תּוֹדָ֑ה וּ⁠בְ⁠שֵׁ֖ם יְהוָ֣ה אֶקְרָֽא׃","lĕֽ⁠ká-ʼe֭zĕbȧẖ ze֣baẖ ţ̇wòdá֑h ẇ⁠bĕ⁠şé֖̌m yĕhwá֣h ʼeqĕráֽʼ׃"],[116,18,"נְ֭דָרַ⁠י לַ⁠יהוָ֣ה אֲשַׁלֵּ֑ם נֶגְדָ⁠ה־נָּ֝֗א לְ⁠כָל־עַמּֽ⁠וֹ׃","nĕ֭dára⁠y la⁠yhwá֣h ʼàşǎlé֑̇m negĕdá⁠h-ná̇֝֗ʼ lĕ⁠kál-ʻaṁֽ⁠wò׃"],[116,19,"בְּ⁠חַצְר֤וֹת ׀ בֵּ֤ית יְהוָ֗ה בְּֽ⁠ת֘וֹכֵ֤⁠כִי יְֽרוּשָׁלִָ֗ם הַֽלְלוּ־יָֽהּ׃","bĕ̇⁠ẖaẕĕr֤wòţ ׀ bé֤̇yţ yĕhwá֗h bĕֽ̇⁠ţ֘wòké֤⁠kiy yĕֽrẇşá̌liá֗m haֽlĕlẇ-yáֽḣ׃"],[117,1,"הַֽלְל֣וּ אֶת־יְ֭הוָה כָּל־גּוֹיִ֑ם שַׁ֝בְּח֗וּ⁠הוּ כָּל־הָ⁠אֻמִּֽים׃","haֽlĕl֣ẇ ʼeţ-yĕ֭hwáh ká̇l-ġwòyi֑m şǎ֝bĕ̇ẖ֗ẇ⁠hẇ ká̇l-há⁠ʼumiֽ̇ym׃"],[117,2,"כִּ֥י גָ֘בַ֤ר עָלֵ֨י⁠נוּ ׀ חַסְדּ֗⁠וֹ וֶֽ⁠אֱמֶת־יְהוָ֥ה לְ⁠עוֹלָ֗ם הַֽלְלוּ־יָֽהּ׃","ki֥̇y gá֘ba֤r ʻálé֨y⁠nẇ ׀ ẖasĕḋ֗⁠wò weֽ⁠ʼèmeţ-yĕhwá֥h lĕ⁠ʻwòlá֗m haֽlĕlẇ-yáֽḣ׃"],[118,1,"הוֹד֣וּ לַ⁠יהוָ֣ה כִּי־ט֑וֹב כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","hwòd֣ẇ la⁠yhwá֣h ki̇y-t֑wòb ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[118,2,"יֹֽאמַר־נָ֥א יִשְׂרָאֵ֑ל כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","yòֽʼmar-ná֥ʼ yişĕ̂ráʼé֑l ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[118,3,"יֹֽאמְרוּ־נָ֥א בֵֽית־אַהֲרֹ֑ן כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","yòֽʼmĕrẇ-ná֥ʼ béֽyţ-ʼahàrò֑n ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[118,4,"יֹֽאמְרוּ־נָ֭א יִרְאֵ֣י יְהוָ֑ה כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","yòֽʼmĕrẇ-ná֭ʼ yirĕʼé֣y yĕhwá֑h ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[118,5,"מִֽן־הַ֭⁠מֵּצַ֥ר קָרָ֣אתִי יָּ֑הּ עָנָ֖⁠נִי בַ⁠מֶּרְחָ֣ב יָֽהּ׃","miֽn-ha֭⁠mé̇ẕa֥r qárá֣ʼţiy yá֑̇ḣ ʻáná֖⁠niy ba⁠mėrĕẖá֣b yáֽḣ׃"],[118,6,"יְהוָ֣ה לִ֭⁠י לֹ֣א אִירָ֑א מַה־יַּעֲשֶׂ֖ה לִ֣⁠י אָדָֽם׃","yĕhwá֣h li֭⁠y lò֣ʼ ʼiyrá֑ʼ mah-yȧʻàşê֖h li֣⁠y ʼádáֽm׃"],[118,7,"יְהוָ֣ה לִ֭⁠י בְּ⁠עֹזְרָ֑⁠י וַ֝⁠אֲנִ֗י אֶרְאֶ֥ה בְ⁠שֹׂנְאָֽ⁠י׃","yĕhwá֣h li֭⁠y bĕ̇⁠ʻòzĕrá֑⁠y wa֝⁠ʼàni֗y ʼerĕʼe֥h bĕ⁠şò̂nĕʼáֽ⁠y׃"],[118,8,"ט֗וֹב לַ⁠חֲס֥וֹת בַּ⁠יהוָ֑ה מִ֝⁠בְּטֹ֗חַ בָּ⁠אָדָֽם׃","t֗wòb la⁠ẖàs֥wòţ bȧ⁠yhwá֑h mi֝⁠bĕ̇tò֗ẖa bá̇⁠ʼádáֽm׃"],[118,9,"ט֗וֹב לַ⁠חֲס֥וֹת בַּ⁠יהוָ֑ה מִ֝⁠בְּטֹ֗חַ בִּ⁠נְדִיבִֽים׃","t֗wòb la⁠ẖàs֥wòţ bȧ⁠yhwá֑h mi֝⁠bĕ̇tò֗ẖa bi̇⁠nĕdiybiֽym׃"],[118,10,"כָּל־גּוֹיִ֥ם סְבָב֑וּ⁠נִי בְּ⁠שֵׁ֥ם יְ֝הוָ֗ה כִּ֣י אֲמִילַֽ⁠ם׃","ká̇l-ġwòyi֥m sĕbáb֑ẇ⁠niy bĕ̇⁠şé֥̌m yĕ֝hwá֗h ki֣̇y ʼàmiylaֽ⁠m׃"],[118,11,"סַבּ֥וּ⁠נִי גַם־סְבָב֑וּ⁠נִי בְּ⁠שֵׁ֥ם יְ֝הוָ֗ה כִּ֣י אֲמִילַֽ⁠ם׃","saḃ֥ẇ⁠niy gam-sĕbáb֑ẇ⁠niy bĕ̇⁠şé֥̌m yĕ֝hwá֗h ki֣̇y ʼàmiylaֽ⁠m׃"],[118,12,"סַבּ֤וּ⁠נִי כִ⁠דְבוֹרִ֗ים דֹּ֭עֲכוּ כְּ⁠אֵ֣שׁ קוֹצִ֑ים בְּ⁠שֵׁ֥ם יְ֝הוָ֗ה כִּ֣י אֲמִילַֽ⁠ם׃","saḃ֤ẇ⁠niy ki⁠dĕbwòri֗ym dò֭̇ʻàkẇ kĕ̇⁠ʼé֣ş̌ qwòẕi֑ym bĕ̇⁠şé֥̌m yĕ֝hwá֗h ki֣̇y ʼàmiylaֽ⁠m׃"],[118,13,"דַּחֹ֣ה דְחִיתַ֣⁠נִי לִ⁠נְפֹּ֑ל וַ֖⁠יהוָ֣ה עֲזָרָֽ⁠נִי׃","dȧẖò֣h dĕẖiyţa֣⁠niy li⁠nĕpò֑̇l wa֖⁠yhwá֣h ʻàzáráֽ⁠niy׃"],[118,14,"עָזִּ֣⁠י וְ⁠זִמְרָ֣ת יָ֑הּ וַֽ⁠יְהִי־לִ֝֗⁠י לִֽ⁠ישׁוּעָֽה׃","ʻázi֣̇⁠y wĕ⁠zimĕrá֣ţ yá֑ḣ waֽ⁠yĕhiy-li֝֗⁠y liֽ⁠yş̌ẇʻáֽh׃"],[118,15,"ק֤וֹל ׀ רִנָּ֬ה וִֽ⁠ישׁוּעָ֗ה בְּ⁠אָהֳלֵ֥י צַדִּיקִ֑ים יְמִ֥ין יְ֝הוָה עֹ֣שָׂה חָֽיִל׃","q֤wòl ׀ riná̇֬h wiֽ⁠yş̌ẇʻá֗h bĕ̇⁠ʼáholé֥y ẕadi̇yqi֑ym yĕmi֥yn yĕ֝hwáh ʻò֣şá̂h ẖáֽyil׃"],[118,16,"יְמִ֣ין יְ֭הוָה רוֹמֵמָ֑ה יְמִ֥ין יְ֝הוָה עֹ֣שָׂה חָֽיִל׃","yĕmi֣yn yĕ֭hwáh rwòmémá֑h yĕmi֥yn yĕ֝hwáh ʻò֣şá̂h ẖáֽyil׃"],[118,17,"לֹֽא אָמ֥וּת כִּי־אֶֽחְיֶ֑ה וַ֝⁠אֲסַפֵּ֗ר מַֽעֲשֵׂ֥י יָֽהּ׃","lòֽʼ ʼám֥ẇţ ki̇y-ʼeֽẖĕye֑h wa֝⁠ʼàsapé̇֗r maֽʻàşé֥̂y yáֽḣ׃"],[118,18,"יַסֹּ֣ר יִסְּרַ֣⁠נִּי יָּ֑הּ וְ֝⁠לַ⁠מָּ֗וֶת לֹ֣א נְתָנָֽ⁠נִי׃","yasò֣̇r yisĕ̇ra֣⁠ni̇y yá֑̇ḣ wĕ֝⁠la⁠má̇֗weţ lò֣ʼ nĕţánáֽ⁠niy׃"],[118,19,"פִּתְחוּ־לִ֥⁠י שַׁעֲרֵי־צֶ֑דֶק אָֽבֹא־בָ֝⁠ם אוֹדֶ֥ה יָֽהּ׃","pi̇ţĕẖẇ-li֥⁠y şǎʻàréy-ẕe֑deq ʼáֽbòʼ-bá֝⁠m ʼwòde֥h yáֽḣ׃"],[118,20,"זֶֽה־הַ⁠שַּׁ֥עַר לַ⁠יהוָ֑ה צַ֝דִּיקִ֗ים יָבֹ֥אוּ בֽ⁠וֹ׃","zeֽh-ha⁠şȧ֥̌ʻar la⁠yhwá֑h ẕa֝di̇yqi֗ym yábò֥ʼẇ bֽ⁠wò׃"],[118,21,"א֭וֹדְ⁠ךָ כִּ֣י עֲנִיתָ֑⁠נִי וַ⁠תְּהִי־לִ֝֗⁠י לִֽ⁠ישׁוּעָֽה׃","ʼ֭wòdĕ⁠ká ki֣̇y ʻàniyţá֑⁠niy wa⁠ţĕ̇hiy-li֝֗⁠y liֽ⁠yş̌ẇʻáֽh׃"],[118,22,"אֶ֭בֶן מָאֲס֣וּ הַ⁠בּוֹנִ֑ים הָ֝יְתָ֗ה לְ⁠רֹ֣אשׁ פִּנָּֽה׃","ʼe֭ben máʼàs֣ẇ ha⁠ḃwòni֑ym há֝yĕţá֗h lĕ⁠rò֣ʼş̌ pi̇náֽ̇h׃"],[118,23,"מֵ⁠אֵ֣ת יְ֭הוָה הָ֣יְתָה זֹּ֑את הִ֖יא נִפְלָ֣את בְּ⁠עֵינֵֽי⁠נוּ׃","mé⁠ʼé֣ţ yĕ֭hwáh há֣yĕţáh zò֑̇ʼţ hi֖yʼ nipĕlá֣ʼţ bĕ̇⁠ʻéynéֽy⁠nẇ׃"],[118,24,"זֶה־הַ֭⁠יּוֹם עָשָׂ֣ה יְהוָ֑ה נָגִ֖ילָה וְ⁠נִשְׂמְחָ֣ה בֽ⁠וֹ׃","zeh-ha֭⁠ẏwòm ʻáşá֣̂h yĕhwá֑h nági֖yláh wĕ⁠nişĕ̂mĕẖá֣h bֽ⁠wò׃"],[118,25,"אָנָּ֣א יְ֭הוָה הוֹשִׁ֘יעָ֥⁠ה נָּ֑א אָֽנָּ֥א יְ֝הוָ֗ה הַצְלִ֘יחָ֥⁠ה נָּֽא׃","ʼáná֣̇ʼ yĕ֭hwáh hwòşǐ֘yʻá֥⁠h ná֑̇ʼ ʼáֽná֥̇ʼ yĕ֝hwá֗h haẕĕli֘yẖá֥⁠h náֽ̇ʼ׃"],[118,26,"בָּר֣וּךְ הַ֭⁠בָּא בְּ⁠שֵׁ֣ם יְהוָ֑ה בֵּ֝רַֽכְנוּ⁠כֶ֗ם מִ⁠בֵּ֥ית יְהוָֽה׃","bá̇r֣ẇkĕ ha֭⁠bá̇ʼ bĕ̇⁠şé֣̌m yĕhwá֑h bé̇֝raֽkĕnẇ⁠ke֗m mi⁠bé֥̇yţ yĕhwáֽh׃"],[118,27,"אֵ֤ל ׀ יְהוָה֮ וַ⁠יָּ֪אֶר לָ֥⁠נוּ אִסְרוּ־חַ֥ג בַּ⁠עֲבֹתִ֑ים עַד־קַ֝רְנ֗וֹת הַ⁠מִּזְבֵּֽחַ׃","ʼé֤l ׀ yĕhwáh֮ wa⁠yá֪̇ʼer lá֥⁠nẇ ʼisĕrẇ-ẖa֥g bȧ⁠ʻàbòţi֑ym ʻad-qa֝rĕn֗wòţ ha⁠mi̇zĕbéֽ̇ẖa׃"],[118,28,"אֵלִ֣⁠י אַתָּ֣ה וְ⁠אוֹדֶ֑⁠ךָּ אֱ֝לֹהַ֗⁠י אֲרוֹמְמֶֽ⁠ךָּ׃","ʼéli֣⁠y ʼaţá֣̇h wĕ⁠ʼwòde֑⁠ká̇ ʼè֝lòha֗⁠y ʼàrwòmĕmeֽ⁠ká̇׃"],[118,29,"הוֹד֣וּ לַ⁠יהוָ֣ה כִּי־ט֑וֹב כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","hwòd֣ẇ la⁠yhwá֣h ki̇y-t֑wòb ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[119,1,"אַשְׁרֵ֥י תְמִֽימֵי־דָ֑רֶךְ הַֽ֝⁠הֹלְכִ֗ים בְּ⁠תוֹרַ֥ת יְהוָֽה׃","ʼaşĕ̌ré֥y ţĕmiֽyméy-dá֑rekĕ haֽ֝⁠hòlĕki֗ym bĕ̇⁠ţwòra֥ţ yĕhwáֽh׃"],[119,2,"אַ֭שְׁרֵי נֹצְרֵ֥י עֵדֹתָ֗י⁠ו בְּ⁠כָל־לֵ֥ב יִדְרְשֽׁוּ⁠הוּ׃","ʼa֭şĕ̌réy nòẕĕré֥y ʻédòţá֗y⁠w bĕ̇⁠kál-lé֥b yidĕrĕşֽ̌ẇ⁠hẇ׃"],[119,3,"אַ֭ף לֹֽא־פָעֲל֣וּ עַוְלָ֑ה בִּ⁠דְרָכָ֥י⁠ו הָלָֽכוּ׃","ʼa֭p lòֽʼ-páʻàl֣ẇ ʻawĕlá֑h bi̇⁠dĕráká֥y⁠w háláֽkẇ׃"],[119,4,"אַ֭תָּה צִוִּ֥יתָה פִקֻּדֶ֗י⁠ךָ לִ⁠שְׁמֹ֥ר מְאֹֽד׃","ʼa֭ţá̇h ẕiwi֥̇yţáh piqu̇de֗y⁠ká li⁠şĕ̌mò֥r mĕʼòֽd׃"],[119,5,"אַ֭חֲלַי יִכֹּ֥נוּ דְרָכָ֗⁠י לִ⁠שְׁמֹ֥ר חֻקֶּֽי⁠ךָ׃","ʼa֭ẖàlay yikò֥̇nẇ dĕráká֗⁠y li⁠şĕ̌mò֥r ẖuqėֽy⁠ká׃"],[119,6,"אָ֥ז לֹא־אֵב֑וֹשׁ בְּ֝⁠הַבִּיטִ֗⁠י אֶל־כָּל־מִצְוֺתֶֽי⁠ךָ׃","ʼá֥z lòʼ-ʼéb֑wòş̌ bĕ̇֝⁠habi̇yti֗⁠y ʼel-ká̇l-miẕĕwֺţeֽy⁠ká׃"],[119,7,"א֭וֹדְ⁠ךָ בְּ⁠יֹ֣שֶׁר לֵבָ֑ב בְּ֝⁠לָמְדִ֗⁠י מִשְׁפְּטֵ֥י צִדְקֶֽ⁠ךָ׃","ʼ֭wòdĕ⁠ká bĕ̇⁠yò֣şěr lébá֑b bĕ̇֝⁠lámĕdi֗⁠y mişĕ̌pĕ̇té֥y ẕidĕqeֽ⁠ká׃"],[119,8,"אֶת־חֻקֶּ֥י⁠ךָ אֶשְׁמֹ֑ר אַֽל־תַּעַזְבֵ֥⁠נִי עַד־מְאֹֽד׃","ʼeţ-ẖuqė֥y⁠ká ʼeşĕ̌mò֑r ʼaֽl-ţȧʻazĕbé֥⁠niy ʻad-mĕʼòֽd׃"],[119,9,"בַּ⁠מֶּ֣ה יְזַכֶּה־נַּ֭עַר אֶת־אָרְח֑⁠וֹ לִ֝⁠שְׁמֹ֗ר כִּ⁠דְבָרֶֽ⁠ךָ׃","bȧ⁠mė֣h yĕzakėh-nȧ֭ʻar ʼeţ-ʼárĕẖ֑⁠wò li֝⁠şĕ̌mò֗r ki̇⁠dĕbáreֽ⁠ká׃"],[119,10,"בְּ⁠כָל־לִבִּ֥⁠י דְרַשְׁתִּ֑י⁠ךָ אַל־תַּ֝שְׁגֵּ֗⁠נִי מִ⁠מִּצְוֺתֶֽי⁠ךָ׃","bĕ̇⁠kál-libi֥̇⁠y dĕraşĕ̌ţi֑̇y⁠ká ʼal-ţȧ֝şĕ̌gé̇֗⁠niy mi⁠mi̇ẕĕwֺţeֽy⁠ká׃"],[119,11,"בְּ֭⁠לִבִּ⁠י צָפַ֣נְתִּי אִמְרָתֶ֑⁠ךָ לְ֝מַ֗עַן לֹ֣א אֶֽחֱטָא־לָֽ⁠ךְ׃","bĕ֭̇⁠libi̇⁠y ẕápa֣nĕţi̇y ʼimĕráţe֑⁠ká lĕ֝ma֗ʻan lò֣ʼ ʼeֽẖètáʼ-láֽ⁠kĕ׃"],[119,12,"בָּר֖וּךְ אַתָּ֥ה יְהוָ֗ה לַמְּדֵ֥⁠נִי חֻקֶּֽי⁠ךָ׃","bá̇r֖ẇkĕ ʼaţá֥̇h yĕhwá֗h lamĕ̇dé֥⁠niy ẖuqėֽy⁠ká׃"],[119,13,"בִּ⁠שְׂפָתַ֥⁠י סִפַּ֑רְתִּי כֹּ֝֗ל מִשְׁפְּטֵי־פִֽי⁠ךָ׃","bi̇⁠şĕ̂páţa֥⁠y sipȧ֑rĕţi̇y kò̇֝֗l mişĕ̌pĕ̇téy-piֽy⁠ká׃"],[119,14,"בְּ⁠דֶ֖רֶךְ עֵדְוֺתֶ֥י⁠ךָ שַׂ֗שְׂתִּי כְּ⁠עַ֣ל כָּל־הֽוֹן׃","bĕ̇⁠de֖rekĕ ʻédĕwֺţe֥y⁠ká şâ֗şĕ̂ţi̇y kĕ̇⁠ʻa֣l ká̇l-hֽwòn׃"],[119,15,"בְּ⁠פִקֻּדֶ֥י⁠ךָ אָשִׂ֑יחָה וְ֝⁠אַבִּ֗יטָה אֹרְחֹתֶֽי⁠ךָ׃","bĕ̇⁠piqu̇de֥y⁠ká ʼáşî֑yẖáh wĕ֝⁠ʼabi̇֗ytáh ʼòrĕẖòţeֽy⁠ká׃"],[119,16,"בְּ⁠חֻקֹּתֶ֥י⁠ךָ אֶֽשְׁתַּעֲשָׁ֑ע לֹ֭א אֶשְׁכַּ֣ח דְּבָרֶֽ⁠ךָ׃","bĕ̇⁠ẖuqò̇ţe֥y⁠ká ʼeֽşĕ̌ţȧʻàşá֑̌ʻ lò֭ʼ ʼeşĕ̌kȧ֣ẖ dĕ̇báreֽ⁠ká׃"],[119,17,"גְּמֹ֖ל עַֽל־עַבְדְּ⁠ךָ֥ אֶֽחְיֶ֗ה וְ⁠אֶשְׁמְרָ֥ה דְבָרֶֽ⁠ךָ׃","gĕ̇mò֖l ʻaֽl-ʻabĕdĕ̇⁠ká֥ ʼeֽẖĕye֗h wĕ⁠ʼeşĕ̌mĕrá֥h dĕbáreֽ⁠ká׃"],[119,18,"גַּל־עֵינַ֥⁠י וְ⁠אַבִּ֑יטָה נִ֝פְלָא֗וֹת מִ⁠תּוֹרָתֶֽ⁠ךָ׃","gȧl-ʻéyna֥⁠y wĕ⁠ʼabi֑̇ytáh ni֝pĕláʼ֗wòţ mi⁠ţ̇wòráţeֽ⁠ká׃"],[119,19,"גֵּ֣ר אָנֹכִ֣י בָ⁠אָ֑רֶץ אַל־תַּסְתֵּ֥ר מִ֝מֶּ֗⁠נִּי מִצְוֺתֶֽי⁠ךָ׃","gé֣̇r ʼánòki֣y bá⁠ʼá֑reẕ ʼal-ţȧsĕţé֥̇r mi֝mė֗⁠ni̇y miẕĕwֺţeֽy⁠ká׃"],[119,20,"גָּרְסָ֣ה נַפְשִׁ֣⁠י לְ⁠תַאֲבָ֑ה אֶֽל־מִשְׁפָּטֶ֥י⁠ךָ בְ⁠כָל־עֵֽת׃","gá̇rĕsá֣h napĕşǐ֣⁠y lĕ⁠ţaʼàbá֑h ʼeֽl-mişĕ̌pá̇te֥y⁠ká bĕ⁠kál-ʻéֽţ׃"],[119,21,"גָּ֭עַרְתָּ זֵדִ֣ים אֲרוּרִ֑ים הַ֝⁠שֹּׁגִים מִ⁠מִּצְוֺתֶֽי⁠ךָ׃","gá֭̇ʻarĕţá̇ zédi֣ym ʼàrẇri֑ym ha֝⁠şò̇̌giym mi⁠mi̇ẕĕwֺţeֽy⁠ká׃"],[119,22,"גַּ֣ל מֵֽ֭⁠עָלַ⁠י חֶרְפָּ֣ה וָ⁠ב֑וּז כִּ֖י עֵדֹתֶ֣י⁠ךָ נָצָֽרְתִּי׃","gȧ֣l méֽ֭⁠ʻála⁠y ẖerĕpá֣̇h wá⁠b֑ẇz ki֖̇y ʻédòţe֣y⁠ká náẕáֽrĕţi̇y׃"],[119,23,"גַּ֤ם יָֽשְׁב֣וּ שָׂ֭רִים בִּ֣⁠י נִדְבָּ֑רוּ עַ֝בְדְּ⁠ךָ֗ יָשִׂ֥יחַ בְּ⁠חֻקֶּֽי⁠ךָ׃","gȧ֤m yáֽşĕ̌b֣ẇ şá֭̂riym bi֣̇⁠y nidĕbá֑̇rẇ ʻa֝bĕdĕ̇⁠ká֗ yáşî֥yẖa bĕ̇⁠ẖuqėֽy⁠ká׃"],[119,24,"גַּֽם־עֵ֭דֹתֶי⁠ךָ שַׁעֲשֻׁעָ֗⁠י אַנְשֵׁ֥י עֲצָתִֽ⁠י׃","gȧֽm-ʻé֭dòţey⁠ká şǎʻàşǔʻá֗⁠y ʼanĕşé֥̌y ʻàẕáţiֽ⁠y׃"],[119,25,"דָּֽבְקָ֣ה לֶ⁠עָפָ֣ר נַפְשִׁ֑⁠י חַ֝יֵּ֗⁠נִי כִּ⁠דְבָרֶֽ⁠ךָ׃","dáֽ̇bĕqá֣h le⁠ʻápá֣r napĕşǐ֑⁠y ẖa֝yé̇֗⁠niy ki̇⁠dĕbáreֽ⁠ká׃"],[119,26,"דְּרָכַ֣⁠י סִ֭פַּרְתִּי וַֽ⁠תַּעֲנֵ֗⁠נִי לַמְּדֵ֥⁠נִי חֻקֶּֽי⁠ךָ׃","dĕ̇ráka֣⁠y si֭pȧrĕţi̇y waֽ⁠ţȧʻàné֗⁠niy lamĕ̇dé֥⁠niy ẖuqėֽy⁠ká׃"],[119,27,"דֶּֽרֶךְ־פִּקּוּדֶ֥י⁠ךָ הֲבִינֵ֑⁠נִי וְ֝⁠אָשִׂ֗יחָה בְּ⁠נִפְלְאוֹתֶֽי⁠ךָ׃","dėֽrekĕ-pi̇q̇ẇde֥y⁠ká hàbiyné֑⁠niy wĕ֝⁠ʼáşî֗yẖáh bĕ̇⁠nipĕlĕʼwòţeֽy⁠ká׃"],[119,28,"דָּלְפָ֣ה נַ֭פְשִׁ⁠י מִ⁠תּוּגָ֑ה קַ֝יְּמֵ֗⁠נִי כִּ⁠דְבָרֶֽ⁠ךָ׃","dá̇lĕpá֣h na֭pĕşǐ⁠y mi⁠ţ̇ẇgá֑h qa֝yĕ̇mé֗⁠niy ki̇⁠dĕbáreֽ⁠ká׃"],[119,29,"דֶּֽרֶךְ־שֶׁ֭קֶר הָסֵ֣ר מִמֶּ֑⁠נִּי וְֽ⁠תוֹרָתְ⁠ךָ֥ חָנֵּֽ⁠נִי׃","dėֽrekĕ-şě֭qer hásé֣r mimė֑⁠ni̇y wĕֽ⁠ţwòráţĕ⁠ká֥ ẖánéֽ̇⁠niy׃"],[119,30,"דֶּֽרֶךְ־אֱמוּנָ֥ה בָחָ֑רְתִּי מִשְׁפָּטֶ֥י⁠ךָ שִׁוִּֽיתִי׃","dėֽrekĕ-ʼèmẇná֥h báẖá֑rĕţi̇y mişĕ̌pá̇te֥y⁠ká şǐwiֽ̇yţiy׃"],[119,31,"דָּבַ֥קְתִּי בְ⁠עֵֽדְוֺתֶ֑י⁠ךָ יְ֝הוָ֗ה אַל־תְּבִישֵֽׁ⁠נִי׃","dá̇ba֥qĕţi̇y bĕ⁠ʻéֽdĕwֺţe֑y⁠ká yĕ֝hwá֗h ʼal-ţĕ̇biyşéֽ̌⁠niy׃"],[119,32,"דֶּֽרֶךְ־מִצְוֺתֶ֥י⁠ךָ אָר֑וּץ כִּ֖י תַרְחִ֣יב לִבִּֽ⁠י׃","dėֽrekĕ-miẕĕwֺţe֥y⁠ká ʼár֑ẇẕ ki֖̇y ţarĕẖi֣yb libiֽ̇⁠y׃"],[119,33,"הוֹרֵ֣⁠נִי יְ֭הוָה דֶּ֥רֶךְ חֻקֶּ֗י⁠ךָ וְ⁠אֶצְּרֶ֥⁠נָּה עֵֽקֶב׃","hwòré֣⁠niy yĕ֭hwáh dė֥rekĕ ẖuqė֗y⁠ká wĕ⁠ʼeẕĕ̇re֥⁠ná̇h ʻéֽqeb׃"],[119,34,"הֲ֭בִינֵ⁠נִי וְ⁠אֶצְּרָ֥ה תֽוֹרָתֶ֗⁠ךָ וְ⁠אֶשְׁמְרֶ֥⁠נָּה בְ⁠כָל־לֵֽב׃","hà֭biyné⁠niy wĕ⁠ʼeẕĕ̇rá֥h ţֽwòráţe֗⁠ká wĕ⁠ʼeşĕ̌mĕre֥⁠ná̇h bĕ⁠kál-léֽb׃"],[119,35,"הַ֭דְרִיכֵ⁠נִי בִּ⁠נְתִ֣יב מִצְוֺתֶ֑י⁠ךָ כִּי־ב֥⁠וֹ חָפָֽצְתִּי׃","ha֭dĕriyké⁠niy bi̇⁠nĕţi֣yb miẕĕwֺţe֑y⁠ká ki̇y-b֥⁠wò ẖápáֽẕĕţi̇y׃"],[119,36,"הַט־לִ֭בִּ⁠י אֶל־עֵדְוֺתֶ֗י⁠ךָ וְ⁠אַ֣ל אֶל־בָּֽצַע׃","hat-li֭bi̇⁠y ʼel-ʻédĕwֺţe֗y⁠ká wĕ⁠ʼa֣l ʼel-báֽ̇ẕaʻ׃"],[119,37,"הַעֲבֵ֣ר עֵ֭ינַ⁠י מֵ⁠רְא֣וֹת שָׁ֑וְא בִּ⁠דְרָכֶ֥⁠ךָ חַיֵּֽ⁠נִי׃","haʻàbé֣r ʻé֭yna⁠y mé⁠rĕʼ֣wòţ şá֑̌wĕʼ bi̇⁠dĕráke֥⁠ká ẖayéֽ̇⁠niy׃"],[119,38,"הָקֵ֣ם לְ֭⁠עַבְדְּ⁠ךָ אִמְרָתֶ֑⁠ךָ אֲ֝שֶׁ֗ר לְ⁠יִרְאָתֶֽ⁠ךָ׃","háqé֣m lĕ֭⁠ʻabĕdĕ̇⁠ká ʼimĕráţe֑⁠ká ʼà֝şě֗r lĕ⁠yirĕʼáţeֽ⁠ká׃"],[119,39,"הַעֲבֵ֣ר חֶ֭רְפָּתִ⁠י אֲשֶׁ֣ר יָגֹ֑רְתִּי כִּ֖י מִשְׁפָּטֶ֣י⁠ךָ טוֹבִֽים׃","haʻàbé֣r ẖe֭rĕpá̇ţi⁠y ʼàşě֣r yágò֑rĕţi̇y ki֖̇y mişĕ̌pá̇te֣y⁠ká twòbiֽym׃"],[119,40,"הִ֭נֵּה תָּאַ֣בְתִּי לְ⁠פִקֻּדֶ֑י⁠ךָ בְּ⁠צִדְקָתְ⁠ךָ֥ חַיֵּֽ⁠נִי׃","hi֭né̇h ţá̇ʼa֣bĕţi̇y lĕ⁠piqu̇de֑y⁠ká bĕ̇⁠ẕidĕqáţĕ⁠ká֥ ẖayéֽ̇⁠niy׃"],[119,41,"וִֽ⁠יבֹאֻ֣⁠נִי חֲסָדֶ֣⁠ךָ יְהוָ֑ה תְּ֝שֽׁוּעָתְ⁠ךָ֗ כְּ⁠אִמְרָתֶֽ⁠ךָ׃","wiֽ⁠ybòʼu֣⁠niy ẖàsáde֣⁠ká yĕhwá֑h ţĕ̇֝şֽ̌ẇʻáţĕ⁠ká֗ kĕ̇⁠ʼimĕráţeֽ⁠ká׃"],[119,42,"וְ⁠אֶֽעֱנֶ֣ה חֹרְפִ֣⁠י דָבָ֑ר כִּֽי־בָ֝טַחְתִּי בִּ⁠דְבָרֶֽ⁠ךָ׃","wĕ⁠ʼeֽʻène֣h ẖòrĕpi֣⁠y dábá֑r kiֽ̇y-bá֝taẖĕţi̇y bi̇⁠dĕbáreֽ⁠ká׃"],[119,43,"וְֽ⁠אַל־תַּצֵּ֬ל מִ⁠פִּ֣⁠י דְבַר־אֱמֶ֣ת עַד־מְאֹ֑ד כִּ֖י לְ⁠מִשְׁפָּטֶ֣⁠ךָ יִחָֽלְתִּי׃","wĕֽ⁠ʼal-ţȧẕé̇֬l mi⁠pi֣̇⁠y dĕbar-ʼème֣ţ ʻad-mĕʼò֑d ki֖̇y lĕ⁠mişĕ̌pá̇te֣⁠ká yiẖáֽlĕţi̇y׃"],[119,44,"וְ⁠אֶשְׁמְרָ֖ה תוֹרָתְ⁠ךָ֥ תָמִ֗יד לְ⁠עוֹלָ֥ם וָ⁠עֶֽד׃","wĕ⁠ʼeşĕ̌mĕrá֖h ţwòráţĕ⁠ká֥ ţámi֗yd lĕ⁠ʻwòlá֥m wá⁠ʻeֽd׃"],[119,45,"וְ⁠אֶתְהַלְּכָ֥ה בָ⁠רְחָבָ֑ה כִּ֖י פִקֻּדֶ֣י⁠ךָ דָרָֽשְׁתִּי׃","wĕ⁠ʼeţĕhalĕ̇ká֥h bá⁠rĕẖábá֑h ki֖̇y piqu̇de֣y⁠ká dáráֽşĕ̌ţi̇y׃"],[119,46,"וַ⁠אֲדַבְּרָ֣ה בְ֭⁠עֵדֹתֶי⁠ךָ נֶ֥גֶד מְלָכִ֗ים וְ⁠לֹ֣א אֵבֽוֹשׁ׃","wa⁠ʼàdabĕ̇rá֣h bĕ֭⁠ʻédòţey⁠ká ne֥ged mĕláki֗ym wĕ⁠lò֣ʼ ʼébֽwòş̌׃"],[119,47,"וְ⁠אֶשְׁתַּֽעֲשַׁ֥ע בְּ⁠מִצְוֺתֶ֗י⁠ךָ אֲשֶׁ֣ר אָהָֽבְתִּי׃","wĕ⁠ʼeşĕ̌ţȧֽʻàşǎ֥ʻ bĕ̇⁠miẕĕwֺţe֗y⁠ká ʼàşě֣r ʼáháֽbĕţi̇y׃"],[119,48,"וְ⁠אֶשָּֽׂא־כַפַּ֗⁠י אֶֽל־מִ֭צְוֺתֶי⁠ךָ אֲשֶׁ֥ר אָהָ֗בְתִּי וְ⁠אָשִׂ֥יחָה בְ⁠חֻקֶּֽי⁠ךָ׃","wĕ⁠ʼeşáֽ̇̂ʼ-kapȧ֗⁠y ʼeֽl-mi֭ẕĕwֺţey⁠ká ʼàşě֥r ʼáhá֗bĕţi̇y wĕ⁠ʼáşî֥yẖáh bĕ⁠ẖuqėֽy⁠ká׃"],[119,49,"זְכֹר־דָּבָ֥ר לְ⁠עַבְדֶּ֑⁠ךָ עַ֝֗ל אֲשֶׁ֣ר יִֽחַלְתָּֽ⁠נִי׃","zĕkòr-dá̇bá֥r lĕ⁠ʻabĕdė֑⁠ká ʻa֝֗l ʼàşě֣r yiֽẖalĕţáֽ̇⁠niy׃"],[119,50,"זֹ֣את נֶחָמָתִ֣⁠י בְ⁠עָנְיִ֑⁠י כִּ֖י אִמְרָתְ⁠ךָ֣ חִיָּֽתְ⁠נִי׃","zò֣ʼţ neẖámáţi֣⁠y bĕ⁠ʻánĕyi֑⁠y ki֖̇y ʼimĕráţĕ⁠ká֣ ẖiyáֽ̇ţĕ⁠niy׃"],[119,51,"זֵ֭דִים הֱלִיצֻ֣⁠נִי עַד־מְאֹ֑ד מִ֝⁠תּֽוֹרָתְ⁠ךָ֗ לֹ֣א נָטִֽיתִי׃","zé֭diym hèliyẕu֣⁠niy ʻad-mĕʼò֑d mi֝⁠ţֽ̇wòráţĕ⁠ká֗ lò֣ʼ nátiֽyţiy׃"],[119,52,"זָ֘כַ֤רְתִּי מִשְׁפָּטֶ֖י⁠ךָ מֵ⁠עוֹלָ֥ם ׀ יְהוָ֗ה וָֽ⁠אֶתְנֶחָֽם׃","zá֘ka֤rĕţi̇y mişĕ̌pá̇te֖y⁠ká mé⁠ʻwòlá֥m ׀ yĕhwá֗h wáֽ⁠ʼeţĕneẖáֽm׃"],[119,53,"זַלְעָפָ֣ה אֲ֭חָזַתְ⁠נִי מֵ⁠רְשָׁעִ֑ים עֹ֝זְבֵ֗י תּוֹרָתֶֽ⁠ךָ׃","zalĕʻápá֣h ʼà֭ẖázaţĕ⁠niy mé⁠rĕşá̌ʻi֑ym ʻò֝zĕbé֗y ţ̇wòráţeֽ⁠ká׃"],[119,54,"זְ֭מִרוֹת הָֽיוּ־לִ֥⁠י חֻקֶּ֗י⁠ךָ בְּ⁠בֵ֣ית מְגוּרָֽ⁠י׃","zĕ֭mirwòţ háֽyẇ-li֥⁠y ẖuqė֗y⁠ká bĕ̇⁠bé֣yţ mĕgẇráֽ⁠y׃"],[119,55,"זָ֘כַ֤רְתִּי בַ⁠לַּ֣יְלָה שִׁמְ⁠ךָ֣ יְהוָ֑ה וָֽ֝⁠אֶשְׁמְרָ֗⁠ה תּוֹרָתֶֽ⁠ךָ׃","zá֘ka֤rĕţi̇y ba⁠lȧ֣yĕláh şǐmĕ⁠ká֣ yĕhwá֑h wáֽ֝⁠ʼeşĕ̌mĕrá֗⁠h ţ̇wòráţeֽ⁠ká׃"],[119,56,"זֹ֥את הָֽיְתָה־לִּ֑⁠י כִּ֖י פִקֻּדֶ֣י⁠ךָ נָצָֽרְתִּי׃","zò֥ʼţ háֽyĕţáh-li֑̇⁠y ki֖̇y piqu̇de֣y⁠ká náẕáֽrĕţi̇y׃"],[119,57,"חֶלְקִ֖⁠י יְהוָ֥ה אָמַ֗רְתִּי לִ⁠שְׁמֹ֥ר דְּבָרֶֽי⁠ךָ׃","ẖelĕqi֖⁠y yĕhwá֥h ʼáma֗rĕţi̇y li⁠şĕ̌mò֥r dĕ̇báreֽy⁠ká׃"],[119,58,"חִלִּ֣יתִי פָנֶ֣י⁠ךָ בְ⁠כָל־לֵ֑ב חָ֝נֵּ֗⁠נִי כְּ⁠אִמְרָתֶֽ⁠ךָ׃","ẖili֣̇yţiy páne֣y⁠ká bĕ⁠kál-lé֑b ẖá֝né̇֗⁠niy kĕ̇⁠ʼimĕráţeֽ⁠ká׃"],[119,59,"חִשַּׁ֥בְתִּי דְרָכָ֑⁠י וָ⁠אָשִׁ֥יבָ⁠ה רַ֝גְלַ֗⁠י אֶל־עֵדֹתֶֽי⁠ךָ׃","ẖişȧ֥̌bĕţi̇y dĕráká֑⁠y wá⁠ʼáşǐ֥ybá⁠h ra֝gĕla֗⁠y ʼel-ʻédòţeֽy⁠ká׃"],[119,60,"חַ֭שְׁתִּי וְ⁠לֹ֣א הִתְמַהְמָ֑הְתִּי לִ֝⁠שְׁמֹ֗ר מִצְוֺתֶֽי⁠ךָ׃","ẖa֭şĕ̌ţi̇y wĕ⁠lò֣ʼ hiţĕmahĕmá֑hĕţi̇y li֝⁠şĕ̌mò֗r miẕĕwֺţeֽy⁠ká׃"],[119,61,"חֶבְלֵ֣י רְשָׁעִ֣ים עִוְּדֻ֑⁠נִי תּֽ֝וֹרָתְ⁠ךָ֗ לֹ֣א שָׁכָֽחְתִּי׃","ẖebĕlé֣y rĕşá̌ʻi֣ym ʻiwĕ̇du֑⁠niy ţֽ̇֝wòráţĕ⁠ká֗ lò֣ʼ şá̌káֽẖĕţi̇y׃"],[119,62,"חֲצֽוֹת־לַ֗יְלָה אָ֭קוּם לְ⁠הוֹד֣וֹת לָ֑⁠ךְ עַ֝֗ל מִשְׁפְּטֵ֥י צִדְקֶֽ⁠ךָ׃","ẖàẕֽwòţ-la֗yĕláh ʼá֭qẇm lĕ⁠hwòd֣wòţ lá֑⁠kĕ ʻa֝֗l mişĕ̌pĕ̇té֥y ẕidĕqeֽ⁠ká׃"],[119,63,"חָבֵ֣ר אָ֭נִי לְ⁠כָל־אֲשֶׁ֣ר יְרֵא֑וּ⁠ךָ וּ֝⁠לְ⁠שֹׁמְרֵ֗י פִּקּוּדֶֽי⁠ךָ׃","ẖábé֣r ʼá֭niy lĕ⁠kál-ʼàşě֣r yĕréʼ֑ẇ⁠ká ẇ֝⁠lĕ⁠şò̌mĕré֗y pi̇q̇ẇdeֽy⁠ká׃"],[119,64,"חַסְדְּ⁠ךָ֣ יְ֭הוָה מָלְאָ֥ה הָ⁠אָ֗רֶץ חֻקֶּ֥י⁠ךָ לַמְּדֵֽ⁠נִי׃","ẖasĕdĕ̇⁠ká֣ yĕ֭hwáh málĕʼá֥h há⁠ʼá֗reẕ ẖuqė֥y⁠ká lamĕ̇déֽ⁠niy׃"],[119,65,"ט֭וֹב עָשִׂ֣יתָ עִֽם־עַבְדְּ⁠ךָ֑ יְ֝הוָ֗ה כִּ⁠דְבָרֶֽ⁠ךָ׃","t֭wòb ʻáşî֣yţá ʻiֽm-ʻabĕdĕ̇⁠ká֑ yĕ֝hwá֗h ki̇⁠dĕbáreֽ⁠ká׃"],[119,66,"ט֤וּב טַ֣עַם וָ⁠דַ֣עַת לַמְּדֵ֑⁠נִי כִּ֖י בְ⁠מִצְוֺתֶ֣י⁠ךָ הֶאֱמָֽנְתִּי׃","t֤ẇb ta֣ʻam wá⁠da֣ʻaţ lamĕ̇dé֑⁠niy ki֖̇y bĕ⁠miẕĕwֺţe֣y⁠ká heʼèmáֽnĕţi̇y׃"],[119,67,"טֶ֣רֶם אֶ֭עֱנֶה אֲנִ֣י שֹׁגֵ֑ג וְ֝⁠עַתָּ֗ה אִמְרָתְ⁠ךָ֥ שָׁמָֽרְתִּי׃","te֣rem ʼe֭ʻèneh ʼàni֣y şò̌gé֑g wĕ֝⁠ʻaţá̇֗h ʼimĕráţĕ⁠ká֥ şá̌máֽrĕţi̇y׃"],[119,68,"טוֹב־אַתָּ֥ה וּ⁠מֵטִ֗יב לַמְּדֵ֥⁠נִי חֻקֶּֽי⁠ךָ׃","twòb-ʼaţá֥̇h ẇ⁠méti֗yb lamĕ̇dé֥⁠niy ẖuqėֽy⁠ká׃"],[119,69,"טָפְל֬וּ עָלַ֣⁠י שֶׁ֣קֶר זֵדִ֑ים אֲ֝נִ֗י בְּ⁠כָל־לֵ֤ב ׀ אֱצֹּ֬ר פִּקּוּדֶֽי⁠ךָ׃","tápĕl֬ẇ ʻála֣⁠y şě֣qer zédi֑ym ʼà֝ni֗y bĕ̇⁠kál-lé֤b ׀ ʼèẕò̇֬r pi̇q̇ẇdeֽy⁠ká׃"],[119,70,"טָפַ֣שׁ כַּ⁠חֵ֣לֶב לִבָּ֑⁠ם אֲ֝נִ֗י תּוֹרָתְ⁠ךָ֥ שִֽׁעֲשָֽׁעְתִּי׃","tápa֣ş̌ kȧ⁠ẖé֣leb libá֑̇⁠m ʼà֝ni֗y ţ̇wòráţĕ⁠ká֥ şǐֽʻàşáֽ̌ʻĕţi̇y׃"],[119,71,"טֽוֹב־לִ֥⁠י כִֽי־עֻנֵּ֑יתִי לְ֝מַ֗עַן אֶלְמַ֥ד חֻקֶּֽי⁠ךָ׃","tֽwòb-li֥⁠y kiֽy-ʻuné֑̇yţiy lĕ֝ma֗ʻan ʼelĕma֥d ẖuqėֽy⁠ká׃"],[119,72,"טֽוֹב־לִ֥⁠י תֽוֹרַת־פִּ֑י⁠ךָ מֵ֝⁠אַלְפֵ֗י זָהָ֥ב וָ⁠כָֽסֶף׃","tֽwòb-li֥⁠y ţֽwòraţ-pi֑̇y⁠ká mé֝⁠ʼalĕpé֗y záhá֥b wá⁠káֽsep׃"],[119,73,"יָדֶ֣י⁠ךָ עָ֭שׂוּ⁠נִי וַֽ⁠יְכוֹנְנ֑וּ⁠נִי הֲ֝בִינֵ֗⁠נִי וְ⁠אֶלְמְדָ֥ה מִצְוֺתֶֽי⁠ךָ׃","yáde֣y⁠ká ʻá֭ş̂ẇ⁠niy waֽ⁠yĕkwònĕn֑ẇ⁠niy hà֝biyné֗⁠niy wĕ⁠ʼelĕmĕdá֥h miẕĕwֺţeֽy⁠ká׃"],[119,74,"יְ֭רֵאֶי⁠ךָ יִרְא֣וּ⁠נִי וְ⁠יִשְׂמָ֑חוּ כִּ֖י לִ⁠דְבָרְ⁠ךָ֣ יִחָֽלְתִּי׃","yĕ֭réʼey⁠ká yirĕʼ֣ẇ⁠niy wĕ⁠yişĕ̂má֑ẖẇ ki֖̇y li⁠dĕbárĕ⁠ká֣ yiẖáֽlĕţi̇y׃"],[119,75,"יָדַ֣עְתִּי יְ֭הוָה כִּי־צֶ֣דֶק מִשְׁפָּטֶ֑י⁠ךָ וֶ֝⁠אֱמוּנָ֗ה עִנִּיתָֽ⁠נִי׃","yáda֣ʻĕţi̇y yĕ֭hwáh ki̇y-ẕe֣deq mişĕ̌pá̇te֑y⁠ká we֝⁠ʼèmẇná֗h ʻini̇yţáֽ⁠niy׃"],[119,76,"יְהִי־נָ֣א חַסְדְּ⁠ךָ֣ לְ⁠נַחֲמֵ֑⁠נִי כְּ⁠אִמְרָתְ⁠ךָ֥ לְ⁠עַבְדֶּֽ⁠ךָ׃","yĕhiy-ná֣ʼ ẖasĕdĕ̇⁠ká֣ lĕ⁠naẖàmé֑⁠niy kĕ̇⁠ʼimĕráţĕ⁠ká֥ lĕ⁠ʻabĕdėֽ⁠ká׃"],[119,77,"יְבֹא֣וּ⁠נִי רַחֲמֶ֣י⁠ךָ וְ⁠אֶֽחְיֶ֑ה כִּי־תֽ֝וֹרָתְ⁠ךָ֗ שַֽׁעֲשֻׁעָֽ⁠י׃","yĕbòʼ֣ẇ⁠niy raẖàme֣y⁠ká wĕ⁠ʼeֽẖĕye֑h ki̇y-ţֽ֝wòráţĕ⁠ká֗ şǎֽʻàşǔʻáֽ⁠y׃"],[119,78,"יֵבֹ֣שׁוּ זֵ֭דִים כִּי־שֶׁ֣קֶר עִוְּת֑וּ⁠נִי אֲ֝נִ֗י אָשִׂ֥יחַ בְּ⁠פִקּוּדֶֽי⁠ךָ׃","yébò֣ş̌ẇ zé֭diym ki̇y-şě֣qer ʻiwĕ̇ţ֑ẇ⁠niy ʼà֝ni֗y ʼáşî֥yẖa bĕ̇⁠piq̇ẇdeֽy⁠ká׃"],[119,79,"יָשׁ֣וּבוּ לִ֣⁠י יְרֵאֶ֑י⁠ךָ ו⁠ידעו עֵדֹתֶֽי⁠ךָ׃","yáş֣̌ẇbẇ li֣⁠y yĕréʼe֑y⁠ká w⁠ydʻw ʻédòţeֽy⁠ká׃"],[119,80,"יְהִֽי־לִבִּ֣⁠י תָמִ֣ים בְּ⁠חֻקֶּ֑י⁠ךָ לְ֝מַ֗עַן לֹ֣א אֵבֽוֹשׁ׃","yĕhiֽy-libi֣̇⁠y ţámi֣ym bĕ̇⁠ẖuqė֑y⁠ká lĕ֝ma֗ʻan lò֣ʼ ʼébֽwòş̌׃"],[119,81,"כָּלְתָ֣ה לִ⁠תְשׁוּעָתְ⁠ךָ֣ נַפְשִׁ֑⁠י לִ⁠דְבָרְ⁠ךָ֥ יִחָֽלְתִּי׃","ká̇lĕţá֣h li⁠ţĕş̌ẇʻáţĕ⁠ká֣ napĕşǐ֑⁠y li⁠dĕbárĕ⁠ká֥ yiẖáֽlĕţi̇y׃"],[119,82,"כָּל֣וּ עֵ֭ינַ⁠י לְ⁠אִמְרָתֶ֑⁠ךָ לֵ֝⁠אמֹ֗ר מָתַ֥י תְּֽנַחֲמֵֽ⁠נִי׃","ká̇l֣ẇ ʻé֭yna⁠y lĕ⁠ʼimĕráţe֑⁠ká lé֝⁠ʼmò֗r máţa֥y ţĕֽ̇naẖàméֽ⁠niy׃"],[119,83,"כִּֽי־הָ֭יִיתִי כְּ⁠נֹ֣אד בְּ⁠קִיט֑וֹר חֻ֝קֶּ֗י⁠ךָ לֹ֣א שָׁכָֽחְתִּי׃","kiֽ̇y-há֭yiyţiy kĕ̇⁠nò֣ʼd bĕ̇⁠qiyt֑wòr ẖu֝qė֗y⁠ká lò֣ʼ şá̌káֽẖĕţi̇y׃"],[119,84,"כַּ⁠מָּ֥ה יְמֵֽי־עַבְדֶּ֑⁠ךָ מָתַ֬י תַּעֲשֶׂ֖ה בְ⁠רֹדְפַ֣⁠י מִשְׁפָּֽט׃","kȧ⁠má֥̇h yĕméֽy-ʻabĕdė֑⁠ká máţa֬y ţȧʻàşê֖h bĕ⁠ròdĕpa֣⁠y mişĕ̌páֽ̇t׃"],[119,85,"כָּֽרוּ־לִ֣⁠י זֵדִ֣ים שִׁיח֑וֹת אֲ֝שֶׁ֗ר לֹ֣א כְ⁠תוֹרָתֶֽ⁠ךָ׃","káֽ̇rẇ-li֣⁠y zédi֣ym şǐyẖ֑wòţ ʼà֝şě֗r lò֣ʼ kĕ⁠ţwòráţeֽ⁠ká׃"],[119,86,"כָּל־מִצְוֺתֶ֥י⁠ךָ אֱמוּנָ֑ה שֶׁ֖קֶר רְדָפ֣וּ⁠נִי עָזְרֵֽ⁠נִי׃","ká̇l-miẕĕwֺţe֥y⁠ká ʼèmẇná֑h şě֖qer rĕdáp֣ẇ⁠niy ʻázĕréֽ⁠niy׃"],[119,87,"כִּ֭⁠מְעַט כִּלּ֣וּ⁠נִי בָ⁠אָ֑רֶץ וַ֝⁠אֲנִ֗י לֹא־עָזַ֥בְתִּי פִקֻּודֶֽי⁠ךָ׃","ki֭̇⁠mĕʻat ki̇l֣̇ẇ⁠niy bá⁠ʼá֑reẕ wa֝⁠ʼàni֗y lòʼ-ʻáza֥bĕţi̇y piqu̇wdeֽy⁠ká׃"],[119,88,"כְּ⁠חַסְדְּ⁠ךָ֥ חַיֵּ֑⁠נִי וְ֝⁠אֶשְׁמְרָ֗ה עֵד֥וּת פִּֽי⁠ךָ׃","kĕ̇⁠ẖasĕdĕ̇⁠ká֥ ẖayé֑̇⁠niy wĕ֝⁠ʼeşĕ̌mĕrá֗h ʻéd֥ẇţ piֽ̇y⁠ká׃"],[119,89,"לְ⁠עוֹלָ֥ם יְהוָ֑ה דְּ֝בָרְ⁠ךָ֗ נִצָּ֥ב בַּ⁠שָּׁמָֽיִם׃","lĕ⁠ʻwòlá֥m yĕhwá֑h dĕ̇֝bárĕ⁠ká֗ niẕá֥̇b bȧ⁠şá̇̌máֽyim׃"],[119,90,"לְ⁠דֹ֣ר וָ֭⁠דֹר אֱמֽוּנָתֶ֑⁠ךָ כּוֹנַ֥נְתָּ אֶ֝֗רֶץ וַֽ⁠תַּעֲמֹֽד׃","lĕ⁠dò֣r wá֭⁠dòr ʼèmֽẇnáţe֑⁠ká k̇wòna֥nĕţá̇ ʼe֝֗reẕ waֽ⁠ţȧʻàmòֽd׃"],[119,91,"לְֽ֭⁠מִשְׁפָּטֶי⁠ךָ עָמְד֣וּ הַ⁠יּ֑וֹם כִּ֖י הַ⁠כֹּ֣ל עֲבָדֶֽי⁠ךָ׃","lĕֽ֭⁠mişĕ̌pá̇tey⁠ká ʻámĕd֣ẇ ha⁠ẏ֑wòm ki֖̇y ha⁠kò֣̇l ʻàbádeֽy⁠ká׃"],[119,92,"לוּלֵ֣י ת֭וֹרָתְ⁠ךָ שַׁעֲשֻׁעָ֑⁠י אָ֝֗ז אָבַ֥דְתִּי בְ⁠עָנְיִֽ⁠י׃","lẇlé֣y ţ֭wòráţĕ⁠ká şǎʻàşǔʻá֑⁠y ʼá֝֗z ʼába֥dĕţi̇y bĕ⁠ʻánĕyiֽ⁠y׃"],[119,93,"לְ֭⁠עוֹלָם לֹא־אֶשְׁכַּ֣ח פִּקּוּדֶ֑י⁠ךָ כִּ֥י בָ֝֗⁠ם חִיִּיתָֽ⁠נִי׃","lĕ֭⁠ʻwòlám lòʼ-ʼeşĕ̌kȧ֣ẖ pi̇q̇ẇde֑y⁠ká ki֥̇y bá֝֗⁠m ẖiyi̇yţáֽ⁠niy׃"],[119,94,"לְֽ⁠ךָ־אֲ֭נִי הוֹשִׁיעֵ֑⁠נִי כִּ֖י פִקּוּדֶ֣י⁠ךָ דָרָֽשְׁתִּי׃","lĕֽ⁠ká-ʼà֭niy hwòşǐyʻé֑⁠niy ki֖̇y piq̇ẇde֣y⁠ká dáráֽşĕ̌ţi̇y׃"],[119,95,"לִ֤⁠י קִוּ֣וּ רְשָׁעִ֣ים לְ⁠אַבְּדֵ֑⁠נִי עֵ֝דֹתֶ֗י⁠ךָ אֶתְבּוֹנָֽן׃","li֤⁠y qiẇ֣ẇ rĕşá̌ʻi֣ym lĕ⁠ʼabĕ̇dé֑⁠niy ʻé֝dòţe֗y⁠ká ʼeţĕḃwònáֽn׃"],[119,96,"לְֽ⁠כָל תִּ֭כְלָה רָאִ֣יתִי קֵ֑ץ רְחָבָ֖ה מִצְוָתְ⁠ךָ֣ מְאֹֽד׃","lĕֽ⁠kál ţi֭̇kĕláh ráʼi֣yţiy qé֑ẕ rĕẖábá֖h miẕĕwáţĕ⁠ká֣ mĕʼòֽd׃"],[119,97,"מָֽה־אָהַ֥בְתִּי תוֹרָתֶ֑⁠ךָ כָּל־הַ֝⁠יּ֗וֹם הִ֣יא שִׂיחָתִֽ⁠י׃","máֽh-ʼáha֥bĕţi̇y ţwòráţe֑⁠ká ká̇l-ha֝⁠ẏ֗wòm hi֣yʼ şîyẖáţiֽ⁠y׃"],[119,98,"מֵ֭⁠אֹ֣יְבַ⁠י תְּחַכְּמֵ֣⁠נִי מִצְוֺתֶ֑⁠ךָ כִּ֖י לְ⁠עוֹלָ֣ם הִיא־לִֽ⁠י׃","mé֭⁠ʼò֣yĕba⁠y ţĕ̇ẖakĕ̇mé֣⁠niy miẕĕwֺţe֑⁠ká ki֖̇y lĕ⁠ʻwòlá֣m hiyʼ-liֽ⁠y׃"],[119,99,"מִ⁠כָּל־מְלַמְּדַ֥⁠י הִשְׂכַּ֑לְתִּי כִּ֥י עֵ֝דְוֺתֶ֗י⁠ךָ שִׂ֣יחָה לִֽֿ⁠י׃","mi⁠ká̇l-mĕlamĕ̇da֥⁠y hişĕ̂kȧ֑lĕţi̇y ki֥̇y ʻé֝dĕwֺţe֗y⁠ká şî֣yẖáh līֽ⁠y׃"],[119,100,"מִ⁠זְּקֵנִ֥ים אֶתְבּוֹנָ֑ן כִּ֖י פִקּוּדֶ֣י⁠ךָ נָצָֽרְתִּי׃","mi⁠zĕ̇qéni֥ym ʼeţĕḃwòná֑n ki֖̇y piq̇ẇde֣y⁠ká náẕáֽrĕţi̇y׃"],[119,101,"מִ⁠כָּל־אֹ֣רַח רָ֭ע כָּלִ֣אתִי רַגְלָ֑⁠י לְ֝מַ֗עַן אֶשְׁמֹ֥ר דְּבָרֶֽ⁠ךָ׃","mi⁠ká̇l-ʼò֣raẖ rá֭ʻ ká̇li֣ʼţiy ragĕlá֑⁠y lĕ֝ma֗ʻan ʼeşĕ̌mò֥r dĕ̇báreֽ⁠ká׃"],[119,102,"מִ⁠מִּשְׁפָּטֶ֥י⁠ךָ לֹא־סָ֑רְתִּי כִּֽי־אַ֝תָּ֗ה הוֹרֵתָֽ⁠נִי׃","mi⁠mi̇şĕ̌pá̇te֥y⁠ká lòʼ-sá֑rĕţi̇y kiֽ̇y-ʼa֝ţá̇֗h hwòréţáֽ⁠niy׃"],[119,103,"מַה־נִּמְלְצ֣וּ לְ֭⁠חִכִּ⁠י אִמְרָתֶ֗⁠ךָ מִ⁠דְּבַ֥שׁ לְ⁠פִֽ⁠י׃","mah-ni̇mĕlĕẕ֣ẇ lĕ֭⁠ẖiki̇⁠y ʼimĕráţe֗⁠ká mi⁠dĕ̇ba֥ş̌ lĕ⁠piֽ⁠y׃"],[119,104,"מִ⁠פִּקּוּדֶ֥י⁠ךָ אֶתְבּוֹנָ֑ן עַל־כֵּ֝֗ן שָׂנֵ֤אתִי ׀ כָּל־אֹ֬רַח שָֽׁקֶר׃","mi⁠pi̇q̇ẇde֥y⁠ká ʼeţĕḃwòná֑n ʻal-ké̇֝֗n şá̂né֤ʼţiy ׀ ká̇l-ʼò֬raẖ şáֽ̌qer׃"],[119,105,"נֵר־לְ⁠רַגְלִ֥⁠י דְבָרֶ֑⁠ךָ וְ֝⁠א֗וֹר לִ⁠נְתִיבָתִֽ⁠י׃","nér-lĕ⁠ragĕli֥⁠y dĕbáre֑⁠ká wĕ֝⁠ʼ֗wòr li⁠nĕţiybáţiֽ⁠y׃"],[119,106,"נִשְׁבַּ֥עְתִּי וָ⁠אֲקַיֵּ֑מָ⁠ה לִ֝⁠שְׁמֹ֗ר מִשְׁפְּטֵ֥י צִדְקֶֽ⁠ךָ׃","nişĕ̌bȧ֥ʻĕţi̇y wá⁠ʼàqayé֑̇má⁠h li֝⁠şĕ̌mò֗r mişĕ̌pĕ̇té֥y ẕidĕqeֽ⁠ká׃"],[119,107,"נַעֲנֵ֥יתִי עַד־מְאֹ֑ד יְ֝הוָ֗ה חַיֵּ֥⁠נִי כִ⁠דְבָרֶֽ⁠ךָ׃","naʻàné֥yţiy ʻad-mĕʼò֑d yĕ֝hwá֗h ẖayé֥̇⁠niy ki⁠dĕbáreֽ⁠ká׃"],[119,108,"נִדְב֣וֹת פִּ֭⁠י רְצֵה־נָ֣א יְהוָ֑ה וּֽ⁠מִשְׁפָּטֶ֥י⁠ךָ לַמְּדֵֽ⁠נִי׃","nidĕb֣wòţ pi֭̇⁠y rĕẕéh-ná֣ʼ yĕhwá֑h ẇֽ⁠mişĕ̌pá̇te֥y⁠ká lamĕ̇déֽ⁠niy׃"],[119,109,"נַפְשִׁ֣⁠י בְ⁠כַפִּ֣⁠י תָמִ֑יד וְ֝⁠תֽוֹרָתְ⁠ךָ֗ לֹ֣א שָׁכָֽחְתִּי׃","napĕşǐ֣⁠y bĕ⁠kapi֣̇⁠y ţámi֑yd wĕ֝⁠ţֽwòráţĕ⁠ká֗ lò֣ʼ şá̌káֽẖĕţi̇y׃"],[119,110,"נָתְנ֬וּ רְשָׁעִ֣ים פַּ֣ח לִ֑⁠י וּ֝⁠מִ⁠פִּקּוּדֶ֗י⁠ךָ לֹ֣א תָעִֽיתִי׃","náţĕn֬ẇ rĕşá̌ʻi֣ym pȧ֣ẖ li֑⁠y ẇ֝⁠mi⁠pi̇q̇ẇde֗y⁠ká lò֣ʼ ţáʻiֽyţiy׃"],[119,111,"נָחַ֣לְתִּי עֵדְוֺתֶ֣י⁠ךָ לְ⁠עוֹלָ֑ם כִּֽי־שְׂשׂ֖וֹן לִבִּ֣⁠י הֵֽמָּה׃","náẖa֣lĕţi̇y ʻédĕwֺţe֣y⁠ká lĕ⁠ʻwòlá֑m kiֽ̇y-şĕ̂ş֖̂wòn libi֣̇⁠y héֽmá̇h׃"],[119,112,"נָטִ֣יתִי לִ֭בִּ⁠י לַ⁠עֲשׂ֥וֹת חֻקֶּ֗י⁠ךָ לְ⁠עוֹלָ֥ם עֵֽקֶב׃","náti֣yţiy li֭bi̇⁠y la⁠ʻàş֥̂wòţ ẖuqė֗y⁠ká lĕ⁠ʻwòlá֥m ʻéֽqeb׃"],[119,113,"סֵעֲפִ֥ים שָׂנֵ֑אתִי וְֽ⁠תוֹרָתְ⁠ךָ֥ אָהָֽבְתִּי׃","séʻàpi֥ym şá̂né֑ʼţiy wĕֽ⁠ţwòráţĕ⁠ká֥ ʼáháֽbĕţi̇y׃"],[119,114,"סִתְרִ֣⁠י וּ⁠מָגִנִּ֣⁠י אָ֑תָּה לִ⁠דְבָרְ⁠ךָ֥ יִחָֽלְתִּי׃","siţĕri֣⁠y ẇ⁠mágini֣̇⁠y ʼá֑ţá̇h li⁠dĕbárĕ⁠ká֥ yiẖáֽlĕţi̇y׃"],[119,115,"סֽוּרוּ־מִמֶּ֥⁠נִּי מְרֵעִ֑ים וְ֝⁠אֶצְּרָ֗ה מִצְוֺ֥ת אֱלֹהָֽ⁠י׃","sֽẇrẇ-mimė֥⁠ni̇y mĕréʻi֑ym wĕ֝⁠ʼeẕĕ̇rá֗h miẕĕwֺ֥ţ ʼèlòháֽ⁠y׃"],[119,116,"סָמְכֵ֣⁠נִי כְ⁠אִמְרָתְ⁠ךָ֣ וְ⁠אֶֽחְיֶ֑ה וְ⁠אַל־תְּ֝בִישֵׁ֗⁠נִי מִ⁠שִּׂבְרִֽ⁠י׃","sámĕké֣⁠niy kĕ⁠ʼimĕráţĕ⁠ká֣ wĕ⁠ʼeֽẖĕye֑h wĕ⁠ʼal-ţĕ̇֝biyşé̌֗⁠niy mi⁠şi̇̂bĕriֽ⁠y׃"],[119,117,"סְעָדֵ֥⁠נִי וְ⁠אִוָּשֵׁ֑עָה וְ⁠אֶשְׁעָ֖ה בְ⁠חֻקֶּ֣י⁠ךָ תָמִֽיד׃","sĕʻádé֥⁠niy wĕ⁠ʼiwá̇şé֑̌ʻáh wĕ⁠ʼeşĕ̌ʻá֖h bĕ⁠ẖuqė֣y⁠ká ţámiֽyd׃"],[119,118,"סָ֭לִיתָ כָּל־שׁוֹגִ֣ים מֵ⁠חֻקֶּ֑י⁠ךָ כִּי־שֶׁ֝֗קֶר תַּרְמִיתָֽ⁠ם׃","sá֭liyţá ká̇l-ş̌wògi֣ym mé⁠ẖuqė֑y⁠ká ki̇y-şě֝֗qer ţȧrĕmiyţáֽ⁠m׃"],[119,119,"סִגִ֗ים הִשְׁבַּ֥תָּ כָל־רִשְׁעֵי־אָ֑רֶץ לָ֝⁠כֵ֗ן אָהַ֥בְתִּי עֵדֹתֶֽי⁠ךָ׃","sigi֗ym hişĕ̌bȧ֥ţá̇ kál-rişĕ̌ʻéy-ʼá֑reẕ lá֝⁠ké֗n ʼáha֥bĕţi̇y ʻédòţeֽy⁠ká׃"],[119,120,"סָמַ֣ר מִ⁠פַּחְדְּ⁠ךָ֣ בְשָׂרִ֑⁠י וּֽ⁠מִ⁠מִּשְׁפָּטֶ֥י⁠ךָ יָרֵֽאתִי׃","sáma֣r mi⁠pȧẖĕdĕ̇⁠ká֣ bĕşá̂ri֑⁠y ẇֽ⁠mi⁠mi̇şĕ̌pá̇te֥y⁠ká yáréֽʼţiy׃"],[119,121,"עָ֭שִׂיתִי מִשְׁפָּ֣ט וָ⁠צֶ֑דֶק בַּל־תַּ֝נִּיחֵ֗⁠נִי לְ⁠עֹֽשְׁקָֽ⁠י׃","ʻá֭şîyţiy mişĕ̌pá֣̇t wá⁠ẕe֑deq bȧl-ţȧ֝ni̇yẖé֗⁠niy lĕ⁠ʻòֽşĕ̌qáֽ⁠y׃"],[119,122,"עֲרֹ֣ב עַבְדְּ⁠ךָ֣ לְ⁠ט֑וֹב אַֽל־יַעַשְׁקֻ֥⁠נִי זֵדִֽים׃","ʻàrò֣b ʻabĕdĕ̇⁠ká֣ lĕ⁠t֑wòb ʼaֽl-yaʻaşĕ̌qu֥⁠niy zédiֽym׃"],[119,123,"עֵ֭ינַ⁠י כָּל֣וּ לִֽ⁠ישׁוּעָתֶ֑⁠ךָ וּ⁠לְ⁠אִמְרַ֥ת צִדְקֶֽ⁠ךָ׃","ʻé֭yna⁠y ká̇l֣ẇ liֽ⁠yş̌ẇʻáţe֑⁠ká ẇ⁠lĕ⁠ʼimĕra֥ţ ẕidĕqeֽ⁠ká׃"],[119,124,"עֲשֵׂ֖ה עִם־עַבְדְּ⁠ךָ֥ כְ⁠חַסְדֶּ֗⁠ךָ וְ⁠חֻקֶּ֥י⁠ךָ לַמְּדֵֽ⁠נִי׃","ʻàşé֖̂h ʻim-ʻabĕdĕ̇⁠ká֥ kĕ⁠ẖasĕdė֗⁠ká wĕ⁠ẖuqė֥y⁠ká lamĕ̇déֽ⁠niy׃"],[119,125,"עַבְדְּ⁠ךָ־אָ֥נִי הֲבִינֵ֑⁠נִי וְ֝⁠אֵדְעָ֗ה עֵדֹתֶֽי⁠ךָ׃","ʻabĕdĕ̇⁠ká-ʼá֥niy hàbiyné֑⁠niy wĕ֝⁠ʼédĕʻá֗h ʻédòţeֽy⁠ká׃"],[119,126,"עֵ֭ת לַ⁠עֲשׂ֣וֹת לַ⁠יהוָ֑ה הֵ֝פֵ֗רוּ תּוֹרָתֶֽ⁠ךָ׃","ʻé֭ţ la⁠ʻàş֣̂wòţ la⁠yhwá֑h hé֝pé֗rẇ ţ̇wòráţeֽ⁠ká׃"],[119,127,"עַל־כֵּ֭ן אָהַ֣בְתִּי מִצְוֺתֶ֑י⁠ךָ מִ⁠זָּהָ֥ב וּ⁠מִ⁠פָּֽז׃","ʻal-ké֭̇n ʼáha֣bĕţi̇y miẕĕwֺţe֑y⁠ká mi⁠zá̇há֥b ẇ⁠mi⁠páֽ̇z׃"],[119,128,"עַל־כֵּ֤ן ׀ כָּל־פִּקּ֣וּדֵי כֹ֣ל יִשָּׁ֑רְתִּי כָּל־אֹ֖רַח שֶׁ֣קֶר שָׂנֵֽאתִי׃","ʻal-ké֤̇n ׀ ká̇l-pi̇q֣̇ẇdéy kò֣l yişá֑̇̌rĕţi̇y ká̇l-ʼò֖raẖ şě֣qer şá̂néֽʼţiy׃"],[119,129,"פְּלָא֥וֹת עֵדְוֺתֶ֑י⁠ךָ עַל־כֵּ֝֗ן נְצָרָ֥תַ⁠ם נַפְשִֽׁ⁠י׃","pĕ̇láʼ֥wòţ ʻédĕwֺţe֑y⁠ká ʻal-ké̇֝֗n nĕẕárá֥ţa⁠m napĕşǐֽ⁠y׃"],[119,130,"פֵּ֖תַח דְּבָרֶ֥י⁠ךָ יָאִ֗יר מֵבִ֥ין פְּתָיִֽים׃","pé֖̇ţaẖ dĕ̇báre֥y⁠ká yáʼi֗yr mébi֥yn pĕ̇ţáyiֽym׃"],[119,131,"פִּֽ⁠י־פָ֭עַרְתִּי וָ⁠אֶשְׁאָ֑פָ⁠ה כִּ֖י לְ⁠מִצְוֺתֶ֣י⁠ךָ יָאָֽבְתִּי׃","piֽ̇⁠y-pá֭ʻarĕţi̇y wá⁠ʼeşĕ̌ʼá֑pá⁠h ki֖̇y lĕ⁠miẕĕwֺţe֣y⁠ká yáʼáֽbĕţi̇y׃"],[119,132,"פְּנֵה־אֵלַ֥⁠י וְ⁠חָנֵּ֑⁠נִי כְּ֝⁠מִשְׁפָּ֗ט לְ⁠אֹהֲבֵ֥י שְׁמֶֽ⁠ךָ׃","pĕ̇néh-ʼéla֥⁠y wĕ⁠ẖáné֑̇⁠niy kĕ̇֝⁠mişĕ̌pá̇֗t lĕ⁠ʼòhàbé֥y şĕ̌meֽ⁠ká׃"],[119,133,"פְּ֭עָמַ⁠י הָכֵ֣ן בְּ⁠אִמְרָתֶ֑⁠ךָ וְֽ⁠אַל־תַּשְׁלֶט־בִּ֥⁠י כָל־אָֽוֶן׃","pĕ֭̇ʻáma⁠y háké֣n bĕ̇⁠ʼimĕráţe֑⁠ká wĕֽ⁠ʼal-ţȧşĕ̌let-bi֥̇⁠y kál-ʼáֽwen׃"],[119,134,"פְּ֭דֵ⁠נִי מֵ⁠עֹ֣שֶׁק אָדָ֑ם וְ֝⁠אֶשְׁמְרָ֗ה פִּקּוּדֶֽי⁠ךָ׃","pĕ֭̇dé⁠niy mé⁠ʻò֣şěq ʼádá֑m wĕ֝⁠ʼeşĕ̌mĕrá֗h pi̇q̇ẇdeֽy⁠ká׃"],[119,135,"פָּ֭נֶי⁠ךָ הָאֵ֣ר בְּ⁠עַבְדֶּ֑⁠ךָ וְ֝⁠לַמְּדֵ֗⁠נִי אֶת־חֻקֶּֽי⁠ךָ׃","pá֭̇ney⁠ká háʼé֣r bĕ̇⁠ʻabĕdė֑⁠ká wĕ֝⁠lamĕ̇dé֗⁠niy ʼeţ-ẖuqėֽy⁠ká׃"],[119,136,"פַּלְגֵי־מַ֭יִם יָרְד֣וּ עֵינָ֑⁠י עַ֝֗ל לֹא־שָׁמְר֥וּ תוֹרָתֶֽ⁠ךָ׃","pȧlĕgéy-ma֭yim yárĕd֣ẇ ʻéyná֑⁠y ʻa֝֗l lòʼ-şá̌mĕr֥ẇ ţwòráţeֽ⁠ká׃"],[119,137,"צַדִּ֣יק אַתָּ֣ה יְהוָ֑ה וְ֝⁠יָשָׁ֗ר מִשְׁפָּטֶֽי⁠ךָ׃","ẕadi֣̇yq ʼaţá֣̇h yĕhwá֑h wĕ֝⁠yáşá̌֗r mişĕ̌pá̇teֽy⁠ká׃"],[119,138,"צִ֭וִּיתָ צֶ֣דֶק עֵדֹתֶ֑י⁠ךָ וֶֽ⁠אֱמוּנָ֥ה מְאֹֽד׃","ẕi֭wi̇yţá ẕe֣deq ʻédòţe֑y⁠ká weֽ⁠ʼèmẇná֥h mĕʼòֽd׃"],[119,139,"צִמְּתַ֥תְ⁠נִי קִנְאָתִ֑⁠י כִּֽי־שָׁכְח֖וּ דְבָרֶ֣י⁠ךָ צָרָֽ⁠י׃","ẕimĕ̇ţa֥ţĕ⁠niy qinĕʼáţi֑⁠y kiֽ̇y-şá̌kĕẖ֖ẇ dĕbáre֣y⁠ká ẕáráֽ⁠y׃"],[119,140,"צְרוּפָ֖ה אִמְרָתְ⁠ךָ֥ מְאֹ֗ד וְֽ⁠עַבְדְּ⁠ךָ֥ אֲהֵבָֽ⁠הּ׃","ẕĕrẇpá֖h ʼimĕráţĕ⁠ká֥ mĕʼò֗d wĕֽ⁠ʻabĕdĕ̇⁠ká֥ ʼàhébáֽ⁠ḣ׃"],[119,141,"צָעִ֣יר אָנֹכִ֣י וְ⁠נִבְזֶ֑ה פִּ֝קֻּדֶ֗י⁠ךָ לֹ֣א שָׁכָֽחְתִּי׃","ẕáʻi֣yr ʼánòki֣y wĕ⁠nibĕze֑h pi̇֝qu̇de֗y⁠ká lò֣ʼ şá̌káֽẖĕţi̇y׃"],[119,142,"צִדְקָתְ⁠ךָ֣ צֶ֣דֶק לְ⁠עוֹלָ֑ם וְֽ⁠תוֹרָתְ⁠ךָ֥ אֱמֶֽת׃","ẕidĕqáţĕ⁠ká֣ ẕe֣deq lĕ⁠ʻwòlá֑m wĕֽ⁠ţwòráţĕ⁠ká֥ ʼèmeֽţ׃"],[119,143,"צַר־וּ⁠מָצ֥וֹק מְצָא֑וּ⁠נִי מִ֝צְוֺתֶ֗י⁠ךָ שַׁעֲשֻׁעָֽ⁠י׃","ẕar-ẇ⁠máẕ֥wòq mĕẕáʼ֑ẇ⁠niy mi֝ẕĕwֺţe֗y⁠ká şǎʻàşǔʻáֽ⁠y׃"],[119,144,"צֶ֖דֶק עֵדְוֺתֶ֥י⁠ךָ לְ⁠עוֹלָ֗ם הֲבִינֵ֥⁠נִי וְ⁠אֶחְיֶֽה׃","ẕe֖deq ʻédĕwֺţe֥y⁠ká lĕ⁠ʻwòlá֗m hàbiyné֥⁠niy wĕ⁠ʼeẖĕyeֽh׃"],[119,145,"קָרָ֣אתִי בְ⁠כָל־לֵ֭ב עֲנֵ֥⁠נִי יְהוָ֗ה חֻקֶּ֥י⁠ךָ אֶצֹּֽרָה׃","qárá֣ʼţiy bĕ⁠kál-lé֭b ʻàné֥⁠niy yĕhwá֗h ẖuqė֥y⁠ká ʼeẕòֽ̇ráh׃"],[119,146,"קְרָאתִ֥י⁠ךָ הוֹשִׁיעֵ֑⁠נִי וְ֝⁠אֶשְׁמְרָ֗ה עֵדֹתֶֽי⁠ךָ׃","qĕráʼţi֥y⁠ká hwòşǐyʻé֑⁠niy wĕ֝⁠ʼeşĕ̌mĕrá֗h ʻédòţeֽy⁠ká׃"],[119,147,"קִדַּ֣מְתִּי בַ֭⁠נֶּשֶׁף וָ⁠אֲשַׁוֵּ֑עָ⁠ה ל⁠דברי⁠ך יִחָֽלְתִּי׃","qidȧ֣mĕţi̇y ba֭⁠nėşěp wá⁠ʼàşǎwé֑̇ʻá⁠h l⁠dbry⁠k yiẖáֽlĕţi̇y׃"],[119,148,"קִדְּמ֣וּ עֵ֭ינַ⁠י אַשְׁמֻר֑וֹת לָ֝⁠שִׂ֗יחַ בְּ⁠אִמְרָתֶֽ⁠ךָ׃","qidĕ̇m֣ẇ ʻé֭yna⁠y ʼaşĕ̌mur֑wòţ lá֝⁠şî֗yẖa bĕ̇⁠ʼimĕráţeֽ⁠ká׃"],[119,149,"ק֭וֹלִ⁠י שִׁמְעָ֣⁠ה כְ⁠חַסְדֶּ֑⁠ךָ יְ֝הוָ֗ה כְּֽ⁠מִשְׁפָּטֶ֥⁠ךָ חַיֵּֽ⁠נִי׃","q֭wòli⁠y şǐmĕʻá֣⁠h kĕ⁠ẖasĕdė֑⁠ká yĕ֝hwá֗h kĕֽ̇⁠mişĕ̌pá̇te֥⁠ká ẖayéֽ̇⁠niy׃"],[119,150,"קָ֭רְבוּ רֹדְפֵ֣י זִמָּ֑ה מִ⁠תּוֹרָתְ⁠ךָ֥ רָחָֽקוּ׃","qá֭rĕbẇ ròdĕpé֣y zimá֑̇h mi⁠ţ̇wòráţĕ⁠ká֥ ráẖáֽqẇ׃"],[119,151,"קָר֣וֹב אַתָּ֣ה יְהוָ֑ה וְֽ⁠כָל־מִצְוֺתֶ֥י⁠ךָ אֱמֶֽת׃","qár֣wòb ʼaţá֣̇h yĕhwá֑h wĕֽ⁠kál-miẕĕwֺţe֥y⁠ká ʼèmeֽţ׃"],[119,152,"קֶ֣דֶם יָ֭דַעְתִּי מֵ⁠עֵדֹתֶ֑י⁠ךָ כִּ֖י לְ⁠עוֹלָ֣ם יְסַדְתָּֽ⁠ם׃","qe֣dem yá֭daʻĕţi̇y mé⁠ʻédòţe֑y⁠ká ki֖̇y lĕ⁠ʻwòlá֣m yĕsadĕţáֽ̇⁠m׃"],[119,153,"רְאֵֽה־עָנְיִ֥⁠י וְ⁠חַלְּצֵ֑⁠נִי כִּי־תֽ֝וֹרָתְ⁠ךָ֗ לֹ֣א שָׁכָֽחְתִּי׃","rĕʼéֽh-ʻánĕyi֥⁠y wĕ⁠ẖalĕ̇ẕé֑⁠niy ki̇y-ţֽ֝wòráţĕ⁠ká֗ lò֣ʼ şá̌káֽẖĕţi̇y׃"],[119,154,"רִיבָ֣⁠ה רִ֭יבִ⁠י וּ⁠גְאָלֵ֑⁠נִי לְ⁠אִמְרָתְ⁠ךָ֥ חַיֵּֽ⁠נִי׃","riybá֣⁠h ri֭ybi⁠y ẇ⁠gĕʼálé֑⁠niy lĕ⁠ʼimĕráţĕ⁠ká֥ ẖayéֽ̇⁠niy׃"],[119,155,"רָח֣וֹק מֵ⁠רְשָׁעִ֣ים יְשׁוּעָ֑ה כִּֽי־חֻ֝קֶּי⁠ךָ לֹ֣א דָרָֽשׁוּ׃","ráẖ֣wòq mé⁠rĕşá̌ʻi֣ym yĕş̌ẇʻá֑h kiֽ̇y-ẖu֝qėy⁠ká lò֣ʼ dáráֽş̌ẇ׃"],[119,156,"רַחֲמֶ֖י⁠ךָ רַבִּ֥ים ׀ יְהוָ֑ה כְּֽ⁠מִשְׁפָּטֶ֥י⁠ךָ חַיֵּֽ⁠נִי׃","raẖàme֖y⁠ká rabi֥̇ym ׀ yĕhwá֑h kĕֽ̇⁠mişĕ̌pá̇te֥y⁠ká ẖayéֽ̇⁠niy׃"],[119,157,"רַ֭בִּים רֹדְפַ֣⁠י וְ⁠צָרָ֑⁠י מֵ֝⁠עֵדְוֺתֶ֗י⁠ךָ לֹ֣א נָטִֽיתִי׃","ra֭bi̇ym ròdĕpa֣⁠y wĕ⁠ẕárá֑⁠y mé֝⁠ʻédĕwֺţe֗y⁠ká lò֣ʼ nátiֽyţiy׃"],[119,158,"רָאִ֣יתִי בֹ֭גְדִים וָֽ⁠אֶתְקוֹטָ֑טָ⁠ה אֲשֶׁ֥ר אִ֝מְרָתְ⁠ךָ֗ לֹ֣א שָׁמָֽרוּ׃","ráʼi֣yţiy bò֭gĕdiym wáֽ⁠ʼeţĕqwòtá֑tá⁠h ʼàşě֥r ʼi֝mĕráţĕ⁠ká֗ lò֣ʼ şá̌máֽrẇ׃"],[119,159,"רְ֭אֵה כִּי־פִקּוּדֶ֣י⁠ךָ אָהָ֑בְתִּי יְ֝הוָ֗ה כְּֽ⁠חַסְדְּ⁠ךָ֥ חַיֵּֽ⁠נִי׃","rĕ֭ʼéh ki̇y-piq̇ẇde֣y⁠ká ʼáhá֑bĕţi̇y yĕ֝hwá֗h kĕֽ̇⁠ẖasĕdĕ̇⁠ká֥ ẖayéֽ̇⁠niy׃"],[119,160,"רֹאשׁ־דְּבָרְ⁠ךָ֥ אֱמֶ֑ת וּ֝⁠לְ⁠עוֹלָ֗ם כָּל־מִשְׁפַּ֥ט צִדְקֶֽ⁠ךָ׃","ròʼş̌-dĕ̇bárĕ⁠ká֥ ʼème֑ţ ẇ֝⁠lĕ⁠ʻwòlá֗m ká̇l-mişĕ̌pȧ֥t ẕidĕqeֽ⁠ká׃"],[119,161,"שָׂ֭רִים רְדָפ֣וּ⁠נִי חִנָּ֑ם ו⁠מ⁠דברי⁠ך פָּחַ֥ד לִבִּֽ⁠י׃","şá֭̂riym rĕdáp֣ẇ⁠niy ẖiná֑̇m w⁠m⁠dbry⁠k pá̇ẖa֥d libiֽ̇⁠y׃"],[119,162,"שָׂ֣שׂ אָ֭נֹכִֽי עַל־אִמְרָתֶ֑⁠ךָ כְּ֝⁠מוֹצֵ֗א שָׁלָ֥ל רָֽב׃","şá֣̂ş̂ ʼá֭nòkiֽy ʻal-ʼimĕráţe֑⁠ká kĕ̇֝⁠mwòẕé֗ʼ şá̌lá֥l ráֽb׃"],[119,163,"שֶׁ֣קֶר שָׂ֭נֵאתִי וַ⁠אֲתַעֵ֑בָה תּוֹרָתְ⁠ךָ֥ אָהָֽבְתִּי׃","şě֣qer şá֭̂néʼţiy wa⁠ʼàţaʻé֑báh ţ̇wòráţĕ⁠ká֥ ʼáháֽbĕţi̇y׃"],[119,164,"שֶׁ֣בַע בַּ֭⁠יּוֹם הִלַּלְתִּ֑י⁠ךָ עַ֝֗ל מִשְׁפְּטֵ֥י צִדְקֶֽ⁠ךָ׃","şě֣baʻ bȧ֭⁠ẏwòm hilȧlĕţi֑̇y⁠ká ʻa֝֗l mişĕ̌pĕ̇té֥y ẕidĕqeֽ⁠ká׃"],[119,165,"שָׁל֣וֹם רָ֭ב לְ⁠אֹהֲבֵ֣י תוֹרָתֶ֑⁠ךָ וְ⁠אֵֽין־לָ֥⁠מוֹ מִכְשֽׁוֹל׃","şá̌l֣wòm rá֭b lĕ⁠ʼòhàbé֣y ţwòráţe֑⁠ká wĕ⁠ʼéֽyn-lá֥⁠mwò mikĕşֽ̌wòl׃"],[119,166,"שִׂבַּ֣רְתִּי לִֽ⁠ישׁוּעָתְ⁠ךָ֣ יְהוָ֑ה וּֽ⁠מִצְוֺתֶ֥י⁠ךָ עָשִֽׂיתִי׃","şîbȧ֣rĕţi̇y liֽ⁠yş̌ẇʻáţĕ⁠ká֣ yĕhwá֑h ẇֽ⁠miẕĕwֺţe֥y⁠ká ʻáşîֽyţiy׃"],[119,167,"שָֽׁמְרָ֣ה נַ֭פְשִׁ⁠י עֵדֹתֶ֑י⁠ךָ וָ⁠אֹהֲבֵ֥⁠ם מְאֹֽד׃","şáֽ̌mĕrá֣h na֭pĕşǐ⁠y ʻédòţe֑y⁠ká wá⁠ʼòhàbé֥⁠m mĕʼòֽd׃"],[119,168,"שָׁמַ֣רְתִּי פִ֭קּוּדֶי⁠ךָ וְ⁠עֵדֹתֶ֑י⁠ךָ כִּ֖י כָל־דְּרָכַ֣⁠י נֶגְדֶּֽ⁠ךָ׃","şá̌ma֣rĕţi̇y pi֭q̇ẇdey⁠ká wĕ⁠ʻédòţe֑y⁠ká ki֖̇y kál-dĕ̇ráka֣⁠y negĕdėֽ⁠ká׃"],[119,169,"תִּקְרַ֤ב רִנָּתִ֣⁠י לְ⁠פָנֶ֣י⁠ךָ יְהוָ֑ה כִּ⁠דְבָרְ⁠ךָ֥ הֲבִינֵֽ⁠נִי׃","ţi̇qĕra֤b riná̇ţi֣⁠y lĕ⁠páne֣y⁠ká yĕhwá֑h ki̇⁠dĕbárĕ⁠ká֥ hàbiynéֽ⁠niy׃"],[119,170,"תָּב֣וֹא תְּחִנָּתִ֣⁠י לְ⁠פָנֶ֑י⁠ךָ כְּ֝⁠אִמְרָתְ⁠ךָ֗ הַצִּילֵֽ⁠נִי׃","ţá̇b֣wòʼ ţĕ̇ẖiná̇ţi֣⁠y lĕ⁠páne֑y⁠ká kĕ̇֝⁠ʼimĕráţĕ⁠ká֗ haẕi̇yléֽ⁠niy׃"],[119,171,"תַּבַּ֣עְנָה שְׂפָתַ֣⁠י תְּהִלָּ֑ה כִּ֖י תְלַמְּדֵ֣⁠נִי חֻקֶּֽי⁠ךָ׃","ţȧbȧ֣ʻĕnáh şĕ̂páţa֣⁠y ţĕ̇hilá֑̇h ki֖̇y ţĕlamĕ̇dé֣⁠niy ẖuqėֽy⁠ká׃"],[119,172,"תַּ֣עַן לְ֭שׁוֹנִ⁠י אִמְרָתֶ֑⁠ךָ כִּ֖י כָל־מִצְוֺתֶ֣י⁠ךָ צֶּֽדֶק׃","ţȧ֣ʻan lĕ֭ş̌wòni⁠y ʼimĕráţe֑⁠ká ki֖̇y kál-miẕĕwֺţe֣y⁠ká ẕėֽdeq׃"],[119,173,"תְּהִֽי־יָדְ⁠ךָ֥ לְ⁠עָזְרֵ֑⁠נִי כִּ֖י פִקּוּדֶ֣י⁠ךָ בָחָֽרְתִּי׃","ţĕ̇hiֽy-yádĕ⁠ká֥ lĕ⁠ʻázĕré֑⁠niy ki֖̇y piq̇ẇde֣y⁠ká báẖáֽrĕţi̇y׃"],[119,174,"תָּאַ֣בְתִּי לִֽ⁠ישׁוּעָתְ⁠ךָ֣ יְהוָ֑ה וְ֝⁠תֽוֹרָתְ⁠ךָ֗ שַׁעֲשֻׁעָֽ⁠י׃","ţá̇ʼa֣bĕţi̇y liֽ⁠yş̌ẇʻáţĕ⁠ká֣ yĕhwá֑h wĕ֝⁠ţֽwòráţĕ⁠ká֗ şǎʻàşǔʻáֽ⁠y׃"],[119,175,"תְּֽחִי־נַ֭פְשִׁ⁠י וּֽ⁠תְהַֽלְלֶ֑⁠ךָּ וּֽ⁠מִשְׁפָּטֶ֥⁠ךָ יַעֲזְרֻֽ⁠נִי׃","ţĕֽ̇ẖiy-na֭pĕşǐ⁠y ẇֽ⁠ţĕhaֽlĕle֑⁠ká̇ ẇֽ⁠mişĕ̌pá̇te֥⁠ká yaʻàzĕruֽ⁠niy׃"],[119,176,"תָּעִ֗יתִי כְּ⁠שֶׂ֣ה אֹ֭בֵד בַּקֵּ֣שׁ עַבְדֶּ֑⁠ךָ כִּ֥י מִ֝צְוֺתֶ֗י⁠ךָ לֹ֣א שָׁכָֽחְתִּי׃","ţá̇ʻi֗yţiy kĕ̇⁠şê֣h ʼò֭béd bȧqé֣̇ş̌ ʻabĕdė֑⁠ká ki֥̇y mi֝ẕĕwֺţe֗y⁠ká lò֣ʼ şá̌káֽẖĕţi̇y׃"],[120,1,"שִׁ֗יר הַֽ⁠מַּ֫עֲל֥וֹת אֶל־יְ֭הוָה בַּ⁠צָּרָ֣תָ⁠ה לִּ֑⁠י קָ֝רָ֗אתִי וַֽ⁠יַּעֲנֵֽ⁠נִי׃","şǐ֗yr haֽ⁠mȧ֫ʻàl֥wòţ ʼel-yĕ֭hwáh bȧ⁠ẕá̇rá֣ţá⁠h li֑̇⁠y qá֝rá֗ʼţiy wֽa⁠yȧʻànéֽ⁠niy׃"],[120,2,"יְֽהוָ֗ה הַצִּ֣ילָ⁠ה נַ֭פְשִׁ⁠י מִ⁠שְּׂפַת־שֶׁ֑קֶר מִ⁠לָּשׁ֥וֹן רְמִיָּֽה׃","yĕֽhwá֗h haẕi֣̇ylá⁠h na֭pĕşǐ⁠y mi⁠şĕ̇̂paţ-şě֑qer mi⁠lá̇ş֥̌wòn rĕmiyáֽ̇h׃"],[120,3,"מַה־יִּתֵּ֣ן לְ֭⁠ךָ וּ⁠מַה־יֹּסִ֥יף לָ֗⁠ךְ לָשׁ֥וֹן רְמִיָּֽה׃","mah-yi̇ţé֣̇n lĕ֭⁠ká ẇ⁠mah-yò̇si֥yp lá֗⁠kĕ láş֥̌wòn rĕmiyáֽ̇h׃"],[120,4,"חִצֵּ֣י גִבּ֣וֹר שְׁנוּנִ֑ים עִ֝֗ם גַּחֲלֵ֥י רְתָמִֽים׃","ẖiẕé֣̇y giḃ֣wòr şĕ̌nẇni֑ym ʻi֝֗m gȧẖàlé֥y rĕţámiֽym׃"],[120,5,"אֽוֹיָה־לִ֭⁠י כִּי־גַ֣רְתִּי מֶ֑שֶׁךְ שָׁ֝כַ֗נְתִּי עִֽם־אָהֳלֵ֥י קֵדָֽר׃","ʼֽwòyáh-li֭⁠y ki̇y-ga֣rĕţi̇y me֑şěkĕ şá̌֝ka֗nĕţi̇y ʻiֽm-ʼáholé֥y qédáֽr׃"],[120,6,"רַ֭בַּת שָֽׁכְנָה־לָּ֣⁠הּ נַפְשִׁ֑⁠י עִ֝֗ם שׂוֹנֵ֥א שָׁלֽוֹם׃","ra֭bȧţ şáֽ̌kĕnáh-lá֣̇⁠ḣ napĕşǐ֑⁠y ʻi֝֗m ş̂wòné֥ʼ şá̌lֽwòm׃"],[120,7,"אֲֽנִי־שָׁ֭לוֹם וְ⁠כִ֣י אֲדַבֵּ֑ר הֵ֝֗מָּה לַ⁠מִּלְחָמָֽה׃","ʼàֽniy-şá֭̌lwòm wĕ⁠ki֣y ʼàdabé֑̇r hé֝֗má̇h la⁠mi̇lĕẖámáֽh׃"],[121,1,"שִׁ֗יר לַֽ⁠מַּ֫עֲל֥וֹת אֶשָּׂ֣א עֵ֭ינַ⁠י אֶל־הֶ⁠הָרִ֑ים מֵ֝⁠אַ֗יִן יָבֹ֥א עֶזְרִֽ⁠י׃","şǐ֗yr laֽ⁠mȧ֫ʻàl֥wòţ ʼeşá֣̇̂ʼ ʻé֭yna⁠y ʼel-he⁠hári֑ym mé֝⁠ʼa֗yin yábò֥ʼ ʻezĕriֽ⁠y׃"],[121,2,"עֶ֭זְרִ⁠י מֵ⁠עִ֣ם יְהוָ֑ה עֹ֝שֵׂ֗ה שָׁמַ֥יִם וָ⁠אָֽרֶץ׃","ʻe֭zĕri⁠y mé⁠ʻi֣m yĕhwá֑h ʻò֝şé̂֗h şá̌ma֥yim wá⁠ʼáֽreẕ׃"],[121,3,"אַל־יִתֵּ֣ן לַ⁠מּ֣וֹט רַגְלֶ֑⁠ךָ אַל־יָ֝נ֗וּם שֹֽׁמְרֶֽ⁠ךָ׃","ʼal-yiţé֣̇n la⁠ṁ֣wòt ragĕle֑⁠ká ʼal-yá֝n֗ẇm şòֽ̌mĕreֽ⁠ká׃"],[121,4,"הִנֵּ֣ה לֹֽא־יָ֭נוּם וְ⁠לֹ֣א יִישָׁ֑ן שׁ֝וֹמֵ֗ר יִשְׂרָאֵֽל׃","hiné֣̇h lòֽʼ-yá֭nẇm wĕ⁠lò֣ʼ yiyşá֑̌n ş̌֝wòmé֗r yişĕ̂ráʼéֽl׃"],[121,5,"יְהוָ֥ה שֹׁמְרֶ֑⁠ךָ יְהוָ֥ה צִ֝לְּ⁠ךָ֗ עַל־יַ֥ד יְמִינֶֽ⁠ךָ׃","yĕhwá֥h şò̌mĕre֑⁠ká yĕhwá֥h ẕi֝lĕ̇⁠ká֗ ʻal-ya֥d yĕmiyneֽ⁠ká׃"],[121,6,"יוֹמָ֗ם הַ⁠שֶּׁ֥מֶשׁ לֹֽא־יַכֶּ֗⁠כָּה וְ⁠יָרֵ֥חַ בַּ⁠לָּֽיְלָה׃","ywòmá֗m ha⁠şė֥̌meş̌ lòֽʼ-yakė֗⁠ká̇h wĕ⁠yáré֥ẖa bȧ⁠láֽ̇yĕláh׃"],[121,7,"יְֽהוָ֗ה יִשְׁמָרְ⁠ךָ֥ מִ⁠כָּל־רָ֑ע יִ֝שְׁמֹ֗ר אֶת־נַפְשֶֽׁ⁠ךָ׃","yĕֽhwá֗h yişĕ̌márĕ⁠ká֥ mi⁠ká̇l-rá֑ʻ yi֝şĕ̌mò֗r ʼeţ-napĕşěֽ⁠ká׃"],[121,8,"יְֽהוָ֗ה יִשְׁמָר־צֵאתְ⁠ךָ֥ וּ⁠בוֹאֶ֑⁠ךָ מֵֽ֝⁠עַתָּ֗ה וְ⁠עַד־עוֹלָֽם׃","yĕֽhwá֗h yişĕ̌már-ẕéʼţĕ⁠ká֥ ẇ⁠bwòʼe֑⁠ká méֽ֝⁠ʻaţá̇֗h wĕ⁠ʻad-ʻwòláֽm׃"],[122,1,"שִׁ֥יר הַֽ⁠מַּעֲל֗וֹת לְ⁠דָ֫וִ֥ד שָׂ֭מַחְתִּי בְּ⁠אֹמְרִ֣ים לִ֑⁠י בֵּ֖ית יְהוָ֣ה נֵלֵֽךְ׃","şǐ֥yr haֽ⁠mȧʻàl֗wòţ lĕ⁠dá֫wi֥d şá֭̂maẖĕţi̇y bĕ̇⁠ʼòmĕri֣ym li֑⁠y bé֖̇yţ yĕhwá֣h néléֽkĕ׃"],[122,2,"עֹ֭מְדוֹת הָי֣וּ רַגְלֵ֑י⁠נוּ בִּ֝⁠שְׁעָרַ֗יִ⁠ךְ יְרוּשָׁלִָֽם׃","ʻò֭mĕdwòţ háy֣ẇ ragĕlé֑y⁠nẇ bi̇֝⁠şĕ̌ʻára֗yi⁠kĕ yĕrẇşá̌liáֽm׃"],[122,3,"יְרוּשָׁלִַ֥ם הַ⁠בְּנוּיָ֑ה כְּ֝⁠עִ֗יר שֶׁ⁠חֻבְּרָה־לָּ֥⁠הּ יַחְדָּֽו׃","yĕrẇşá̌lia֥m ha⁠bĕ̇nẇyá֑h kĕ̇֝⁠ʻi֗yr şě⁠ẖubĕ̇ráh-lá֥̇⁠ḣ yaẖĕdáֽ̇w׃"],[122,4,"שֶׁ⁠שָּׁ֨ם עָל֪וּ שְׁבָטִ֡ים שִׁבְטֵי־יָ֭הּ עֵד֣וּת לְ⁠יִשְׂרָאֵ֑ל לְ֝⁠הֹד֗וֹת לְ⁠שֵׁ֣ם יְהוָֽה׃","şě⁠şá̇̌֨m ʻál֪ẇ şĕ̌báti֡ym şǐbĕtéy-yá֭ḣ ʻéd֣ẇţ lĕ⁠yişĕ̂ráʼé֑l lĕ֝⁠hòd֗wòţ lĕ⁠şé֣̌m yĕhwáֽh׃"],[122,5,"כִּ֤י שָׁ֨מָּ⁠ה ׀ יָשְׁב֣וּ כִסְא֣וֹת לְ⁠מִשְׁפָּ֑ט כִּ֝סְא֗וֹת לְ⁠בֵ֣ית דָּוִֽיד׃","ki֤̇y şá̌֨má̇⁠h ׀ yáşĕ̌b֣ẇ kisĕʼ֣wòţ lĕ⁠mişĕ̌pá֑̇t ki̇֝sĕʼ֗wòţ lĕ⁠bé֣yţ dá̇wiֽyd׃"],[122,6,"שַׁ֭אֲלוּ שְׁל֣וֹם יְרוּשָׁלִָ֑ם יִ֝שְׁלָ֗יוּ אֹהֲבָֽיִ⁠ךְ׃","şǎ֭ʼàlẇ şĕ̌l֣wòm yĕrẇşá̌liá֑m yi֝şĕ̌lá֗yẇ ʼòhàbáֽyi⁠kĕ׃"],[122,7,"יְהִֽי־שָׁל֥וֹם בְּ⁠חֵילֵ֑⁠ךְ שַׁ֝לְוָ֗ה בְּ⁠אַרְמְנוֹתָֽיִ⁠ךְ׃","yĕhiֽy-şá̌l֥wòm bĕ̇⁠ẖéylé֑⁠kĕ şǎ֝lĕwá֗h bĕ̇⁠ʼarĕmĕnwòţáֽyi⁠kĕ׃"],[122,8,"לְ֭מַעַן אַחַ֣⁠י וְ⁠רֵעָ֑⁠י אֲדַבְּרָה־נָּ֖א שָׁל֣וֹם בָּֽ⁠ךְ׃","lĕ֭maʻan ʼaẖa֣⁠y wĕ⁠réʻá֑⁠y ʼàdabĕ̇ráh-ná֖̇ʼ şá̌l֣wòm báֽ̇⁠kĕ׃"],[122,9,"לְ֭מַעַן בֵּית־יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ אֲבַקְשָׁ֖ה ט֣וֹב לָֽ⁠ךְ׃","lĕ֭maʻan bé̇yţ-yĕhwá֣h ʼèlòhé֑y⁠nẇ ʼàbaqĕşá֖̌h t֣wòb láֽ⁠kĕ׃"],[123,1,"שִׁ֗יר הַֽ⁠מַּ֫עֲל֥וֹת אֵ֭לֶי⁠ךָ נָשָׂ֣אתִי אֶת־עֵינַ֑⁠י הַ֝⁠יֹּשְׁבִ֗י בַּ⁠שָּׁמָֽיִם׃","şǐ֗yr haֽ⁠mȧ֫ʻàl֥wòţ ʼé֭ley⁠ká náşá֣̂ʼţiy ʼeţ-ʻéyna֑⁠y ha֝⁠yò̇şĕ̌bi֗y bȧ⁠şá̇̌máֽyim׃"],[123,2,"הִנֵּ֨ה כְ⁠עֵינֵ֪י עֲבָדִ֡ים אֶל־יַ֤ד אֲֽדוֹנֵי⁠הֶ֗ם כְּ⁠עֵינֵ֣י שִׁפְחָה֮ אֶל־יַ֪ד גְּבִ֫רְתָּ֥⁠הּ כֵּ֣ן עֵ֭ינֵי⁠נוּ אֶל־יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ עַ֝֗ד שֶׁ⁠יְּחָנֵּֽ⁠נוּ׃","hiné̇֨h kĕ⁠ʻéyné֪y ʻàbádi֡ym ʼel-ya֤d ʼàֽdwònéy⁠he֗m kĕ̇⁠ʻéyné֣y şǐpĕẖáh֮ ʼel-ya֪d gĕ̇bi֫rĕţá֥̇⁠ḣ ké֣̇n ʻé֭ynéy⁠nẇ ʼel-yĕhwá֣h ʼèlòhé֑y⁠nẇ ʻa֝֗d şě⁠yĕ̇ẖánéֽ̇⁠nẇ׃"],[123,3,"חָנֵּ֣⁠נוּ יְהוָ֣ה חָנֵּ֑⁠נוּ כִּֽי־רַ֝֗ב שָׂבַ֥עְנוּ בֽוּז׃","ẖáné֣̇⁠nẇ yĕhwá֣h ẖáné֑̇⁠nẇ kiֽ̇y-ra֝֗b şá̂ba֥ʻĕnẇ bֽẇz׃"],[123,4,"רַבַּת֮ שָֽׂבְעָה־לָּ֪⁠הּ נַ֫פְשֵׁ֥⁠נוּ הַ⁠לַּ֥עַג הַ⁠שַּׁאֲנַנִּ֑ים הַ֝⁠בּ֗וּז לִ⁠גְאֵ֥יוֹנִֽים׃","rabȧţ֮ şáֽ̂bĕʻáh-lá֪̇⁠ḣ na֫pĕşé֥̌⁠nẇ ha⁠lȧ֥ʻag ha⁠şȧ̌ʼànani֑̇ym ha֝⁠ḃ֗ẇz li⁠gĕʼé֥ywòniֽym׃"],[124,1,"שִׁ֥יר הַֽ⁠מַּעֲל֗וֹת לְ⁠דָ֫וִ֥ד לוּלֵ֣י יְ֭הוָה שֶׁ⁠הָ֣יָה לָ֑⁠נוּ יֹֽאמַר־נָ֝א יִשְׂרָאֵֽל׃","şǐ֥yr haֽ⁠mȧʻàl֗wòţ lĕ⁠dá֫wi֥d lẇlé֣y yĕ֭hwáh şě⁠há֣yáh lá֑⁠nẇ yòֽʼmar-ná֝ʼ yişĕ̂ráʼéֽl׃"],[124,2,"לוּלֵ֣י יְ֭הוָה שֶׁ⁠הָ֣יָה לָ֑⁠נוּ בְּ⁠ק֖וּם עָלֵ֣י⁠נוּ אָדָֽם׃","lẇlé֣y yĕ֭hwáh şě⁠há֣yáh lá֑⁠nẇ bĕ̇⁠q֖ẇm ʻálé֣y⁠nẇ ʼádáֽm׃"],[124,3,"אֲ֭זַי חַיִּ֣ים בְּלָע֑וּ⁠נוּ בַּ⁠חֲר֖וֹת אַפָּ֣⁠ם בָּֽ⁠נוּ׃","ʼà֭zay ẖayi֣̇ym bĕ̇láʻ֑ẇ⁠nẇ bȧ⁠ẖàr֖wòţ ʼapá֣̇⁠m báֽ̇⁠nẇ׃"],[124,4,"אֲ֭זַי הַ⁠מַּ֣יִם שְׁטָפ֑וּ⁠נוּ נַ֗֜חְלָ⁠ה עָבַ֥ר עַל־נַפְשֵֽׁ⁠נוּ׃","ʼà֭zay ha⁠mȧ֣yim şĕ̌táp֑ẇ⁠nẇ na֗֜ẖĕlá⁠h ʻába֥r ʻal-napĕşéֽ̌⁠nẇ׃"],[124,5,"אֲ֭זַי עָבַ֣ר עַל־נַפְשֵׁ֑⁠נוּ הַ֝⁠מַּ֗יִם הַ⁠זֵּֽידוֹנִֽים׃","ʼà֭zay ʻába֣r ʻal-napĕşé֑̌⁠nẇ ha֝⁠mȧ֗yim ha⁠zéֽ̇ydwòniֽym׃"],[124,6,"בָּר֥וּךְ יְהוָ֑ה שֶׁ⁠לֹּ֥א נְתָנָ֥⁠נוּ טֶ֝֗רֶף לְ⁠שִׁנֵּי⁠הֶֽם׃","bá̇r֥ẇkĕ yĕhwá֑h şě⁠lò֥̇ʼ nĕţáná֥⁠nẇ te֝֗rep lĕ⁠şǐné̇y⁠heֽm׃"],[124,7,"נַפְשֵׁ֗⁠נוּ כְּ⁠צִפּ֥וֹר נִמְלְטָה֮ מִ⁠פַּ֪ח י֫וֹקְשִׁ֥ים הַ⁠פַּ֥ח נִשְׁבָּ֗ר וַ⁠אֲנַ֥חְנוּ נִמְלָֽטְנוּ׃","napĕşé̌֗⁠nẇ kĕ̇⁠ẕiṗ֥wòr nimĕlĕtáh֮ mi⁠pȧ֪ẖ y֫wòqĕşǐ֥ym ha⁠pȧ֥ẖ nişĕ̌bá̇֗r wa⁠ʼàna֥ẖĕnẇ nimĕláֽtĕnẇ׃"],[124,8,"עֶ֭זְרֵ⁠נוּ בְּ⁠שֵׁ֣ם יְהוָ֑ה עֹ֝שֵׂ֗ה שָׁמַ֥יִם וָ⁠אָֽרֶץ׃","ʻe֭zĕré⁠nẇ bĕ̇⁠şé֣̌m yĕhwá֑h ʻò֝şé̂֗h şá̌ma֥yim wá⁠ʼáֽreẕ׃"],[125,1,"שִׁ֗יר הַֽ⁠מַּ֫עֲל֥וֹת הַ⁠בֹּטְחִ֥ים בַּ⁠יהוָ֑ה כְּֽ⁠הַר־צִיּ֥וֹן לֹא־יִ֝מּ֗וֹט לְ⁠עוֹלָ֥ם יֵשֵֽׁב׃","şǐ֗yr haֽ⁠mȧ֫ʻàl֥wòţ ha⁠bò̇tĕẖi֥ym bȧ⁠yhwá֑h kĕֽ̇⁠har-ẕiẏ֥wòn lòʼ-yi֝ṁ֗wòt lĕ⁠ʻwòlá֥m yéşéֽ̌b׃"],[125,2,"יְֽרוּשָׁלִַ֗ם הָרִים֮ סָבִ֪יב לָ֥⁠הּ וַ֭⁠יהוָה סָבִ֣יב לְ⁠עַמּ֑⁠וֹ מֵ֝⁠עַתָּ֗ה וְ⁠עַד־עוֹלָֽם׃","yĕֽrẇşá̌lia֗m háriym֮ sábi֪yb lá֥⁠ḣ wa֭⁠yhwáh sábi֣yb lĕ⁠ʻaṁ֑⁠wò mé֝⁠ʻaţá̇֗h wĕ⁠ʻad-ʻwòláֽm׃"],[125,3,"כִּ֤י לֹ֪א יָנ֡וּחַ שֵׁ֤בֶט הָ⁠רֶ֗שַׁע עַל֮ גּוֹרַ֪ל הַֽ⁠צַּדִּ֫יקִ֥ים לְמַ֡עַן לֹא־יִשְׁלְח֖וּ הַ⁠צַּדִּיקִ֨ים בְּ⁠עַוְלָ֬תָ⁠ה יְדֵי⁠הֶֽם׃","ki֤̇y lò֪ʼ yán֡ẇẖa şé֤̌bet há⁠re֗şǎʻ ʻal֮ ġwòra֪l haֽ⁠ẕȧdi̇֫yqi֥ym lĕma֡ʻan lòʼ-yişĕ̌lĕẖ֖ẇ ha⁠ẕȧdi̇yqi֨ym bĕ̇⁠ʻawĕlá֬ţá⁠h yĕdéy⁠heֽm׃"],[125,4,"הֵיטִ֣יבָ⁠ה יְ֭הוָה לַ⁠טּוֹבִ֑ים וְ֝⁠לִֽ⁠ישָׁרִ֗ים בְּ⁠לִבּוֹתָֽ⁠ם׃","héyti֣ybá⁠h yĕ֭hwáh la⁠ṫwòbi֑ym wĕ֝⁠liֽ⁠yşá̌ri֗ym bĕ̇⁠liḃwòţáֽ⁠m׃"],[125,5,"וְ⁠הַ⁠מַּטִּ֤ים עַֽקַלְקַלּוֹתָ֗⁠ם יוֹלִיכֵ֣⁠ם יְ֭הוָה אֶת־פֹּעֲלֵ֣י הָ⁠אָ֑וֶן שָׁ֝ל֗וֹם עַל־יִשְׂרָאֵֽל׃","wĕ⁠ha⁠mȧti֤̇ym ʻaֽqalĕqal̇wòţá֗⁠m ywòliyké֣⁠m yĕ֭hwáh ʼeţ-pò̇ʻàlé֣y há⁠ʼá֑wen şá̌֝l֗wòm ʻal-yişĕ̂ráʼéֽl׃"],[126,1,"שִׁ֗יר הַֽ⁠מַּ֫עֲל֥וֹת בְּ⁠שׁ֣וּב יְ֭הוָה אֶת־שִׁיבַ֣ת צִיּ֑וֹן הָ֝יִ֗ינוּ כְּ⁠חֹלְמִֽים׃","şǐ֗yr haֽ⁠mȧ֫ʻàl֥wòţ bĕ̇⁠ş֣̌ẇb yĕ֭hwáh ʼeţ-şǐyba֣ţ ẕiẏ֑wòn há֝yi֗ynẇ kĕ̇⁠ẖòlĕmiֽym׃"],[126,2,"אָ֤ז יִמָּלֵ֪א שְׂח֡וֹק פִּי⁠נוּ֮ וּ⁠לְשׁוֹנֵ֪⁠נוּ רִ֫נָּ֥ה אָ֭ז יֹאמְר֣וּ בַ⁠גּוֹיִ֑ם הִגְדִּ֥יל יְ֝הוָ֗ה לַ⁠עֲשׂ֥וֹת עִם־אֵֽלֶּה׃","ʼá֤z yimá̇lé֪ʼ şĕ̂ẖ֡wòq pi̇y⁠nẇ֮ ẇ⁠lĕş̌wòné֪⁠nẇ ri֫ná֥̇h ʼá֭z yòʼmĕr֣ẇ ba⁠ġwòyi֑m higĕdi֥̇yl yĕ֝hwá֗h la⁠ʻàş֥̂wòţ ʻim-ʼéֽlėh׃"],[126,3,"הִגְדִּ֣יל יְ֭הוָה לַ⁠עֲשׂ֥וֹת עִמָּ֗⁠נוּ הָיִ֥ינוּ שְׂמֵחִֽים׃","higĕdi֣̇yl yĕ֭hwáh la⁠ʻàş֥̂wòţ ʻimá̇֗⁠nẇ háyi֥ynẇ şĕ̂méẖiֽym׃"],[126,4,"שׁוּבָ֣⁠ה יְ֭הוָה אֶת־שבות⁠נו כַּ⁠אֲפִיקִ֥ים בַּ⁠נֶּֽגֶב׃","ş̌ẇbá֣⁠h yĕ֭hwáh ʼeţ-şbwţ⁠nw kȧ⁠ʼàpiyqi֥ym bȧ⁠nėֽgeb׃"],[126,5,"הַ⁠זֹּרְעִ֥ים בְּ⁠דִמְעָ֗ה בְּ⁠רִנָּ֥ה יִקְצֹֽרוּ׃","ha⁠zò̇rĕʻi֥ym bĕ̇⁠dimĕʻá֗h bĕ̇⁠riná֥̇h yiqĕẕòֽrẇ׃"],[126,6,"הָ֘ל֤וֹךְ יֵלֵ֨ךְ ׀ וּ⁠בָכֹה֮ נֹשֵׂ֪א מֶֽשֶׁךְ־הַ֫⁠זָּ֥רַע בֹּֽ֬א־יָב֥וֹא בְ⁠רִנָּ֑ה נֹ֝שֵׂ֗א אֲלֻמֹּתָֽי⁠ו׃","há֘l֤wòkĕ yélé֨kĕ ׀ ẇ⁠bákòh֮ nòşé֪̂ʼ meֽşěkĕ-ha֫⁠zá֥̇raʻ bòֽ̇֬ʼ-yáb֥wòʼ bĕ⁠riná֑̇h nò֝şé̂֗ʼ ʼàlumò̇ţáֽy⁠w׃"],[127,1,"שִׁ֥יר הַֽ⁠מַּֽעֲל֗וֹת לִ⁠שְׁלֹ֫מֹ֥ה אִם־יְהוָ֤ה ׀ לֹא־יִבְנֶ֬ה בַ֗יִת שָׁ֤וְא ׀ עָמְל֣וּ בוֹנָ֣י⁠ו בּ֑⁠וֹ אִם־יְהוָ֥ה לֹֽא־יִשְׁמָר־עִ֝֗יר שָׁ֤וְא ׀ שָׁקַ֬ד שׁוֹמֵֽר׃","şǐ֥yr haֽ⁠mȧֽʻàl֗wòţ li⁠şĕ̌lò֫mò֥h ʼim-yĕhwá֤h ׀ lòʼ-yibĕne֬h ba֗yiţ şá֤̌wĕʼ ׀ ʻámĕl֣ẇ bwòná֣y⁠w ḃ֑⁠wò ʼim-yĕhwá֥h lòֽʼ-yişĕ̌már-ʻi֝֗yr şá֤̌wĕʼ ׀ şá̌qa֬d ş̌wòméֽr׃"],[127,2,"שָׁ֤וְא לָ⁠כֶ֨ם ׀ מַשְׁכִּ֪ימֵי ק֡וּם מְאַֽחֲרֵי־שֶׁ֗בֶת אֹ֭כְלֵי לֶ֣חֶם הָ⁠עֲצָבִ֑ים כֵּ֤ן יִתֵּ֖ן לִֽ⁠ידִיד֣⁠וֹ שֵׁנָֽא׃","şá֤̌wĕʼ lá⁠ke֨m ׀ maşĕ̌ki֪̇yméy q֡ẇm mĕʼaֽẖàréy-şě֗beţ ʼò֭kĕléy le֣ẖem há⁠ʻàẕábi֑ym ké֤̇n yiţé֖̇n liֽ⁠ydiyd֣⁠wò şé̌náֽʼ׃"],[127,3,"הִנֵּ֤ה נַחֲלַ֣ת יְהוָ֣ה בָּנִ֑ים שָׂ֝כָ֗ר פְּרִ֣י הַ⁠בָּֽטֶן׃","hiné֤̇h naẖàla֣ţ yĕhwá֣h bá̇ni֑ym şá̂֝ká֗r pĕ̇ri֣y ha⁠báֽ̇ten׃"],[127,4,"כְּ⁠חִצִּ֥ים בְּ⁠יַד־גִּבּ֑וֹר כֵּ֝֗ן בְּנֵ֣י הַ⁠נְּעוּרִֽים׃","kĕ̇⁠ẖiẕi֥̇ym bĕ̇⁠yad-gi̇ḃ֑wòr ké̇֝֗n bĕ̇né֣y ha⁠nĕ̇ʻẇriֽym׃"],[127,5,"אַשְׁרֵ֤י הַ⁠גֶּ֗בֶר אֲשֶׁ֤ר מִלֵּ֥א אֶת־אַשְׁפָּת֗⁠וֹ מֵ֫⁠הֶ֥ם לֹֽא־יֵבֹ֑שׁוּ כִּֽי־יְדַבְּר֖וּ אֶת־אוֹיְבִ֣ים בַּ⁠שָּֽׁעַר׃","ʼaşĕ̌ré֤y ha⁠gė֗ber ʼàşě֤r milé֥̇ʼ ʼeţ-ʼaşĕ̌pá̇ţ֗⁠wò mé֫⁠he֥m lòֽʼ-yébò֑ş̌ẇ kiֽ̇y-yĕdabĕ̇r֖ẇ ʼeţ-ʼwòyĕbi֣ym bȧ⁠şáֽ̇̌ʻar׃"],[128,1,"שִׁ֗יר הַֽ⁠מַּ֫עֲל֥וֹת אַ֭שְׁרֵי כָּל־יְרֵ֣א יְהוָ֑ה הַ֝⁠הֹלֵ֗ךְ בִּ⁠דְרָכָֽי⁠ו׃","şǐ֗yr haֽ⁠mȧ֫ʻàl֥wòţ ʼa֭şĕ̌réy ká̇l-yĕré֣ʼ yĕhwá֑h ha֝⁠hòlé֗kĕ bi̇⁠dĕrákáֽy⁠w׃"],[128,2,"יְגִ֣יעַ כַּ֭פֶּי⁠ךָ כִּ֣י תֹאכֵ֑ל אַ֝שְׁרֶ֗י⁠ךָ וְ⁠ט֣וֹב לָֽ⁠ךְ׃","yĕgi֣yʻa kȧ֭pėy⁠ká ki֣̇y ţòʼké֑l ʼa֝şĕ̌re֗y⁠ká wĕ⁠t֣wòb láֽ⁠kĕ׃"],[128,3,"אֶשְׁתְּ⁠ךָ֤ ׀ כְּ⁠גֶ֥פֶן פֹּרִיָּה֮ בְּ⁠יַרְכְּתֵ֪י בֵ֫יתֶ֥⁠ךָ בָּ֭נֶי⁠ךָ כִּ⁠שְׁתִלֵ֣י זֵיתִ֑ים סָ֝בִ֗יב לְ⁠שֻׁלְחָנֶֽ⁠ךָ׃","ʼeşĕ̌ţĕ̇⁠ká֤ ׀ kĕ̇⁠ge֥pen pò̇riyá̇h֮ bĕ̇⁠yarĕkĕ̇ţé֪y bé֫yţe֥⁠ká bá֭̇ney⁠ká ki̇⁠şĕ̌ţilé֣y zéyţi֑ym sá֝bi֗yb lĕ⁠şǔlĕẖáneֽ⁠ká׃"],[128,4,"הִנֵּ֣ה כִי־כֵ֭ן יְבֹ֥רַךְ גָּ֗בֶר יְרֵ֣א יְהוָֽה׃","hiné֣̇h kiy-ké֭n yĕbò֥rakĕ gá̇֗ber yĕré֣ʼ yĕhwáֽh׃"],[128,5,"יְבָרֶכְ⁠ךָ֥ יְהוָ֗ה מִ⁠צִּ֫יּ֥וֹן וּ֭⁠רְאֵה בְּ⁠ט֣וּב יְרוּשָׁלִָ֑ם כֹּ֝֗ל יְמֵ֣י חַיֶּֽי⁠ךָ׃","yĕbárekĕ⁠ká֥ yĕhwá֗h mi⁠ẕi̇֫ẏ֥wòn ẇ֭⁠rĕʼéh bĕ̇⁠t֣ẇb yĕrẇşá̌liá֑m kò̇֝֗l yĕmé֣y ẖayėֽy⁠ká׃"],[128,6,"וּ⁠רְאֵֽה־בָנִ֥ים לְ⁠בָנֶ֑י⁠ךָ שָׁ֝ל֗וֹם עַל־יִשְׂרָאֵֽל׃","ẇ⁠rĕʼéֽh-báni֥ym lĕ⁠báne֑y⁠ká şá̌֝l֗wòm ʻal-yişĕ̂ráʼéֽl׃"],[129,1,"שִׁ֗יר הַֽ⁠מַּ֫עֲל֥וֹת רַ֭בַּת צְרָר֣וּ⁠נִי מִ⁠נְּעוּרַ֑⁠י יֹֽאמַר־נָ֝א יִשְׂרָאֵֽל׃","şǐ֗yr haֽ⁠mȧ֫ʻàl֥wòţ ra֭bȧţ ẕĕrár֣ẇ⁠niy mi⁠nĕ̇ʻẇra֑⁠y yòֽʼmar-ná֝ʼ yişĕ̂ráʼéֽl׃"],[129,2,"רַ֭בַּת צְרָר֣וּ⁠נִי מִ⁠נְּעוּרָ֑⁠י גַּ֝ם לֹא־יָ֥כְלוּ לִֽ⁠י׃","ra֭bȧţ ẕĕrár֣ẇ⁠niy mi⁠nĕ̇ʻẇrá֑⁠y gȧ֝m lòʼ-yá֥kĕlẇ liֽ⁠y׃"],[129,3,"עַל־גַּ֭בִּ⁠י חָרְשׁ֣וּ חֹרְשִׁ֑ים הֶ֝אֱרִ֗יכוּ ל⁠מענות⁠ם׃","ʻal-gȧ֭bi̇⁠y ẖárĕş֣̌ẇ ẖòrĕşǐ֑ym he֝ʼèri֗ykẇ l⁠mʻnwţ⁠m׃"],[129,4,"יְהוָ֥ה צַדִּ֑יק קִ֝צֵּ֗ץ עֲב֣וֹת רְשָׁעִֽים׃","yĕhwá֥h ẕadi֑̇yq qi֝ẕé̇֗ẕ ʻàb֣wòţ rĕşá̌ʻiֽym׃"],[129,5,"יֵ֭בֹשׁוּ וְ⁠יִסֹּ֣גוּ אָח֑וֹר כֹּ֝֗ל שֹׂנְאֵ֥י צִיּֽוֹן׃","yé֭bòş̌ẇ wĕ⁠yisò֣̇gẇ ʼáẖ֑wòr kò̇֝֗l şò̂nĕʼé֥y ẕiẏֽwòn׃"],[129,6,"יִ֭הְיוּ כַּ⁠חֲצִ֣יר גַּגּ֑וֹת שֶׁ⁠קַּדְמַ֖ת שָׁלַ֣ף יָבֵֽשׁ׃","yi֭hĕyẇ kȧ⁠ẖàẕi֣yr gȧġ֑wòţ şě⁠qȧdĕma֖ţ şá̌la֣p yábéֽş̌׃"],[129,7,"שֶׁ⁠לֹּ֤א מִלֵּ֖א כַפּ֥⁠וֹ קוֹצֵ֗ר וְ⁠חִצְנ֥⁠וֹ מְעַמֵּֽר׃","şě⁠lò֤̇ʼ milé֖̇ʼ kaṗ֥⁠wò qwòẕé֗r wĕ⁠ẖiẕĕn֥⁠wò mĕʻaméֽ̇r׃"],[129,8,"וְ⁠לֹ֤א אָֽמְר֨וּ ׀ הָ⁠עֹבְרִ֗ים בִּרְכַּֽת־יְהוָ֥ה אֲלֵי⁠כֶ֑ם בֵּרַ֥כְנוּ אֶ֝תְ⁠כֶ֗ם בְּ⁠שֵׁ֣ם יְהוָֽה׃","wĕ⁠lò֤ʼ ʼáֽmĕr֨ẇ ׀ há⁠ʻòbĕri֗ym bi̇rĕkȧֽţ-yĕhwá֥h ʼàléy⁠ke֑m bé̇ra֥kĕnẇ ʼe֝ţĕ⁠ke֗m bĕ̇⁠şé֣̌m yĕhwáֽh׃"],[130,1,"שִׁ֥יר הַֽ⁠מַּעֲל֑וֹת מִ⁠מַּעֲמַקִּ֖ים קְרָאתִ֣י⁠ךָ יְהוָֽה׃","şǐ֥yr haֽ⁠mȧʻàl֑wòţ mi⁠mȧʻàmaqi֖̇ym qĕráʼţi֣y⁠ká yĕhwáֽh׃"],[130,2,"אֲדֹנָ⁠י֮ שִׁמְעָ֪⁠ה בְ⁠ק֫וֹלִ֥⁠י תִּהְיֶ֣ינָה אָ֭זְנֶי⁠ךָ קַשֻּׁב֑וֹת לְ֝⁠ק֗וֹל תַּחֲנוּנָֽ⁠י׃","ʼàdòná⁠y֮ şǐmĕʻá֪⁠h bĕ⁠q֫wòli֥⁠y ţi̇hĕye֣ynáh ʼá֭zĕney⁠ká qaşu̇̌b֑wòţ lĕ֝⁠q֗wòl ţȧẖànẇnáֽ⁠y׃"],[130,3,"אִם־עֲוֺנ֥וֹת תִּשְׁמָר־יָ֑הּ אֲ֝דֹנָ֗⁠י מִ֣י יַעֲמֹֽד׃","ʼim-ʻàwֺn֥wòţ ţi̇şĕ̌már-yá֑ḣ ʼà֝dòná֗⁠y mi֣y yaʻàmòֽd׃"],[130,4,"כִּֽי־עִמְּ⁠ךָ֥ הַ⁠סְּלִיחָ֑ה לְ֝מַ֗עַן תִּוָּרֵֽא׃","kiֽ̇y-ʻimĕ̇⁠ká֥ ha⁠sĕ̇liyẖá֑h lĕ֝ma֗ʻan ţi̇wá̇réֽʼ׃"],[130,5,"קִוִּ֣יתִי יְ֭הוָה קִוְּתָ֣ה נַפְשִׁ֑⁠י וְֽ⁠לִ⁠דְבָר֥⁠וֹ הוֹחָֽלְתִּי׃","qiwi֣̇yţiy yĕ֭hwáh qiwĕ̇ţá֣h napĕşǐ֑⁠y wĕֽ⁠li⁠dĕbár֥⁠wò hwòẖáֽlĕţi̇y׃"],[130,6,"נַפְשִׁ֥⁠י לַֽ⁠אדֹנָ֑⁠י מִ⁠שֹּׁמְרִ֥ים לַ֝⁠בֹּ֗קֶר שֹׁמְרִ֥ים לַ⁠בֹּֽקֶר׃","napĕşǐ֥⁠y laֽ⁠ʼdòná֑⁠y mi⁠şò̇̌mĕri֥ym la֝⁠bò̇֗qer şò̌mĕri֥ym la⁠bòֽ̇qer׃"],[130,7,"יַחֵ֥ל יִשְׂרָאֵ֗ל אֶל־יְה֫וָה כִּֽי־עִם־יְהוָ֥ה הַ⁠חֶ֑סֶד וְ⁠הַרְבֵּ֖ה עִמּ֣⁠וֹ פְדֽוּת׃","yaẖé֥l yişĕ̂ráʼé֗l ʼel-yĕh֫wáh kiֽ̇y-ʻim-yĕhwá֥h ha⁠ẖe֑sed wĕ⁠harĕbé֖̇h ʻiṁ֣⁠wò pĕdֽẇţ׃"],[130,8,"וְ֭⁠הוּא יִפְדֶּ֣ה אֶת־יִשְׂרָאֵ֑ל מִ֝⁠כֹּ֗ל עֲוֺנֹתָֽי⁠ו׃","wĕ֭⁠hẇʼ yipĕdė֣h ʼeţ-yişĕ̂ráʼé֑l mi֝⁠kò̇֗l ʻàwֺnòţáֽy⁠w׃"],[131,1,"שִׁ֥יר הַֽ⁠מַּֽעֲל֗וֹת לְ⁠דָ֫וִ֥ד יְהוָ֤ה ׀ לֹא־גָבַ֣הּ לִ֭בִּ⁠י וְ⁠לֹא־רָמ֣וּ עֵינַ֑⁠י וְ⁠לֹֽא־הִלַּ֓כְתִּי ׀ בִּ⁠גְדֹל֖וֹת וּ⁠בְ⁠נִפְלָא֣וֹת מִמֶּֽ⁠נִּי׃","şǐ֥yr haֽ⁠mȧֽʻàl֗wòţ lĕ⁠dá֫wi֥d yĕhwá֤h ׀ lòʼ-gába֣ḣ li֭bi̇⁠y wĕ⁠lòʼ-rám֣ẇ ʻéyna֑⁠y wĕ⁠lòֽʼ-hilȧ֓kĕţi̇y ׀ bi̇⁠gĕdòl֖wòţ ẇ⁠bĕ⁠nipĕláʼ֣wòţ mimėֽ⁠ni̇y׃"],[131,2,"אִם־לֹ֤א שִׁוִּ֨יתִי ׀ וְ⁠דוֹמַ֗מְתִּי נַ֫פְשִׁ֥⁠י כְּ֭⁠גָמֻל עֲלֵ֣י אִמּ֑⁠וֹ כַּ⁠גָּמֻ֖ל עָלַ֣⁠י נַפְשִֽׁ⁠י׃","ʼim-lò֤ʼ şǐwi̇֨yţiy ׀ wĕ⁠dwòma֗mĕţi̇y na֫pĕşǐ֥⁠y kĕ֭̇⁠gámul ʻàlé֣y ʼiṁ֑⁠wò kȧ⁠gá̇mu֖l ʻála֣⁠y napĕşǐֽ⁠y׃"],[131,3,"יַחֵ֣ל יִ֭שְׂרָאֵל אֶל־יְהוָ֑ה מֵֽ֝⁠עַתָּ֗ה וְ⁠עַד־עוֹלָֽם׃","yaẖé֣l yi֭şĕ̂ráʼél ʼel-yĕhwá֑h méֽ֝⁠ʻaţá̇֗h wĕ⁠ʻad-ʻwòláֽm׃"],[132,1,"שִׁ֗יר הַֽ⁠מַּ֫עֲל֥וֹת זְכוֹר־יְהוָ֥ה לְ⁠דָוִ֑ד אֵ֝ת כָּל־עֻנּוֹתֽ⁠וֹ׃","şǐ֗yr haֽ⁠mȧ֫ʻàl֥wòţ zĕkwòr-yĕhwá֥h lĕ⁠dáwi֑d ʼé֝ţ ká̇l-ʻuṅwòţֽ⁠wò׃"],[132,2,"אֲשֶׁ֣ר נִ֭שְׁבַּע לַ⁠יהוָ֑ה נָ֝דַ֗ר לַ⁠אֲבִ֥יר יַעֲקֹֽב׃","ʼàşě֣r ni֭şĕ̌bȧʻ la⁠yhwá֑h ná֝da֗r la⁠ʼàbi֥yr yaʻàqòֽb׃"],[132,3,"אִם־אָ֭בֹא בְּ⁠אֹ֣הֶל בֵּיתִ֑⁠י אִם־אֶ֝עֱלֶ֗ה עַל־עֶ֥רֶשׂ יְצוּעָֽ⁠י׃","ʼim-ʼá֭bòʼ bĕ̇⁠ʼò֣hel bé̇yţi֑⁠y ʼim-ʼe֝ʻèle֗h ʻal-ʻe֥reş̂ yĕẕẇʻáֽ⁠y׃"],[132,4,"אִם־אֶתֵּ֣ן שְׁנַ֣ת לְ⁠עֵינָ֑⁠י לְֽ⁠עַפְעַפַּ֥⁠י תְּנוּמָֽה׃","ʼim-ʼeţé֣̇n şĕ̌na֣ţ lĕ⁠ʻéyná֑⁠y lĕֽ⁠ʻapĕʻapȧ֥⁠y ţĕ̇nẇmáֽh׃"],[132,5,"עַד־אֶמְצָ֣א מָ֭קוֹם לַ⁠יהוָ֑ה מִ֝שְׁכָּנ֗וֹת לַ⁠אֲבִ֥יר יַעֲקֹֽב׃","ʻad-ʼemĕẕá֣ʼ má֭qwòm la⁠yhwá֑h mi֝şĕ̌ká̇n֗wòţ la⁠ʼàbi֥yr yaʻàqòֽb׃"],[132,6,"הִנֵּֽה־שְׁמַֽעֲנ֥וּ⁠הָ בְ⁠אֶפְרָ֑תָה מְ֝צָאנ֗וּ⁠הָ בִּ⁠שְׂדֵי־יָֽעַר׃","hinéֽ̇h-şĕ̌maֽʻàn֥ẇ⁠há bĕ⁠ʼepĕrá֑ţáh mĕ֝ẕáʼn֗ẇ⁠há bi̇⁠şĕ̂déy-yáֽʻar׃"],[132,7,"נָב֥וֹאָה לְ⁠מִשְׁכְּנוֹתָ֑י⁠ו נִ֝שְׁתַּחֲוֶ֗ה לַ⁠הֲדֹ֥ם רַגְלָֽי⁠ו׃","náb֥wòʼáh lĕ⁠mişĕ̌kĕ̇nwòţá֑y⁠w ni֝şĕ̌ţȧẖàwe֗h la⁠hàdò֥m ragĕláֽy⁠w׃"],[132,8,"קוּמָ֣⁠ה יְ֭הוָה לִ⁠מְנוּחָתֶ֑⁠ךָ אַ֝תָּ֗ה וַ⁠אֲר֥וֹן עֻזֶּֽ⁠ךָ׃","qẇmá֣⁠h yĕ֭hwáh li⁠mĕnẇẖáţe֑⁠ká ʼa֝ţá̇֗h wa⁠ʼàr֥wòn ʻuzėֽ⁠ká׃"],[132,9,"כֹּהֲנֶ֥י⁠ךָ יִלְבְּשׁוּ־צֶ֑דֶק וַ⁠חֲסִידֶ֥י⁠ךָ יְרַנֵּֽנוּ׃","kò̇hàne֥y⁠ká yilĕbĕ̇ş̌ẇ-ẕe֑deq wa⁠ẖàsiyde֥y⁠ká yĕranéֽ̇nẇ׃"],[132,10,"בַּ֭⁠עֲבוּר דָּוִ֣ד עַבְדֶּ֑⁠ךָ אַל־תָּ֝שֵׁ֗ב פְּנֵ֣י מְשִׁיחֶֽ⁠ךָ׃","bȧ֭⁠ʻàbẇr dá̇wi֣d ʻabĕdė֑⁠ká ʼal-ţá̇֝şé̌֗b pĕ̇né֣y mĕşǐyẖeֽ⁠ká׃"],[132,11,"נִשְׁבַּֽע־יְהוָ֨ה ׀ לְ⁠דָוִ֡ד אֱמֶת֮ לֹֽא־יָשׁ֪וּב מִ֫מֶּ֥⁠נָּה מִ⁠פְּרִ֥י בִטְנְ⁠ךָ֑ אָ֝שִׁ֗ית לְ⁠כִסֵּא־לָֽ⁠ךְ׃","nişĕ̌bȧֽʻ-yĕhwá֨h ׀ lĕ⁠dáwi֡d ʼèmeţ֮ lòֽʼ-yáş֪̌ẇb mi֫mė֥⁠ná̇h mi⁠pĕ̇ri֥y bitĕnĕ⁠ká֑ ʼá֝şǐ֗yţ lĕ⁠kisé̇ʼ-láֽ⁠kĕ׃"],[132,12,"אִֽם־יִשְׁמְר֬וּ בָנֶ֨י⁠ךָ ׀ בְּרִיתִ⁠י֮ וְ⁠עֵדֹתִ֥⁠י ז֗וֹ אֲלַ֫מְּדֵ֥⁠ם גַּם־בְּנֵי⁠הֶ֥ם עֲדֵי־עַ֑ד יֵ֝שְׁב֗וּ לְ⁠כִסֵּא־לָֽ⁠ךְ׃","ʼiֽm-yişĕ̌mĕr֬ẇ báne֨y⁠ká ׀ bĕ̇riyţi⁠y֮ wĕ⁠ʻédòţi֥⁠y z֗wò ʼàla֫mĕ̇dé֥⁠m gȧm-bĕ̇néy⁠he֥m ʻàdéy-ʻa֑d yé֝şĕ̌b֗ẇ lĕ⁠kisé̇ʼ-láֽ⁠kĕ׃"],[132,13,"כִּֽי־בָחַ֣ר יְהוָ֣ה בְּ⁠צִיּ֑וֹן אִ֝וָּ֗⁠הּ לְ⁠מוֹשָׁ֥ב לֽ⁠וֹ׃","kiֽ̇y-báẖa֣r yĕhwá֣h bĕ̇⁠ẕiẏ֑wòn ʼi֝wá̇֗⁠ḣ lĕ⁠mwòşá֥̌b lֽ⁠wò׃"],[132,14,"זֹאת־מְנוּחָתִ֥⁠י עֲדֵי־עַ֑ד פֹּֽה־אֵ֝שֵׁ֗ב כִּ֣י אִוִּתִֽי⁠הָ׃","zòʼţ-mĕnẇẖáţi֥⁠y ʻàdéy-ʻa֑d pòֽ̇h-ʼé֝şé̌֗b ki֣̇y ʼiwi̇ţiֽy⁠há׃"],[132,15,"צֵ֭ידָ⁠הּ בָּרֵ֣ךְ אֲבָרֵ֑ךְ אֶ֝בְיוֹנֶ֗י⁠הָ אַשְׂבִּ֥יעַֽ לָֽחֶם׃","ẕé֭ydá⁠ḣ bá̇ré֣kĕ ʼàbáré֑kĕ ʼe֝bĕywòne֗y⁠há ʼaşĕ̂bi֥̇yʻaֽ láֽẖem׃"],[132,16,"וְֽ֭⁠כֹהֲנֶי⁠הָ אַלְבִּ֣ישׁ יֶ֑שַׁע וַ֝⁠חֲסִידֶ֗י⁠הָ רַנֵּ֥ן יְרַנֵּֽנוּ׃","wĕֽ֭⁠kòhàney⁠há ʼalĕbi֣̇yş̌ ye֑şǎʻ wa֝⁠ẖàsiyde֗y⁠há rané֥̇n yĕranéֽ̇nẇ׃"],[132,17,"שָׁ֤ם אַצְמִ֣יחַ קֶ֣רֶן לְ⁠דָוִ֑ד עָרַ֥כְתִּי נֵ֝֗ר לִ⁠מְשִׁיחִֽ⁠י׃","şá֤̌m ʼaẕĕmi֣yẖa qe֣ren lĕ⁠dáwi֑d ʻára֥kĕţi̇y né֝֗r li⁠mĕşǐyẖiֽ⁠y׃"],[132,18,"א֭וֹיְבָי⁠ו אַלְבִּ֣ישׁ בֹּ֑שֶׁת וְ֝⁠עָלָ֗י⁠ו יָצִ֥יץ נִזְרֽ⁠וֹ׃","ʼ֭wòyĕbáy⁠w ʼalĕbi֣̇yş̌ bò֑̇şěţ wĕ֝⁠ʻálá֗y⁠w yáẕi֥yẕ nizĕrֽ⁠wò׃"],[133,1,"שִׁ֥יר הַֽ⁠מַּעֲל֗וֹת לְ⁠דָ֫וִ֥ד הִנֵּ֣ה מַה־טּ֭וֹב וּ⁠מַה־נָּעִ֑ים שֶׁ֖בֶת אַחִ֣ים גַּם־יָֽחַד׃","şǐ֥yr haֽ⁠mȧʻàl֗wòţ lĕ⁠dá֫wi֥d hiné֣̇h mah-ṫ֭wòb ẇ⁠mah-ná̇ʻi֑ym şě֖beţ ʼaẖi֣ym gȧm-yáֽẖad׃"],[133,2,"כַּ⁠שֶּׁ֤מֶן הַ⁠טּ֨וֹב ׀ עַל־הָ⁠רֹ֗אשׁ יֹרֵ֗ד עַֽל־הַ⁠זָּקָ֥ן זְקַֽן־אַהֲרֹ֑ן שֶׁ֝⁠יֹּרֵ֗ד עַל־פִּ֥י מִדּוֹתָֽי⁠ו׃","kȧ⁠şė֤̌men ha⁠ṫ֨wòb ׀ ʻal-há⁠rò֗ʼş̌ yòré֗d ʻaֽl-ha⁠zá̇qá֥n zĕqaֽn-ʼahàrò֑n şě֝⁠yò̇ré֗d ʻal-pi֥̇y miḋwòţáֽy⁠w׃"],[133,3,"כְּ⁠טַל־חֶרְמ֗וֹן שֶׁ⁠יֹּרֵד֮ עַל־הַרְרֵ֪י צִ֫יּ֥וֹן כִּ֤י שָׁ֨ם ׀ צִוָּ֣ה יְ֭הוָה אֶת־הַ⁠בְּרָכָ֑ה חַ֝יִּ֗ים עַד־הָ⁠עוֹלָֽם׃","kĕ̇⁠tal-ẖerĕm֗wòn şě⁠yò̇réd֮ ʻal-harĕré֪y ẕi֫ẏ֥wòn ki֤̇y şá̌֨m ׀ ẕiwá֣̇h yĕ֭hwáh ʼeţ-ha⁠bĕ̇ráká֑h ẖa֝yi̇֗ym ʻad-há⁠ʻwòláֽm׃"],[134,1,"שִׁ֗יר הַֽ⁠מַּ֫עֲל֥וֹת הִנֵּ֤ה ׀ בָּרֲכ֣וּ אֶת־יְ֭הוָה כָּל־עַבְדֵ֣י יְהוָ֑ה הָ⁠עֹמְדִ֥ים בְּ⁠בֵית־יְ֝הוָ֗ה בַּ⁠לֵּילֽוֹת׃","şǐ֗yr haֽ⁠mȧ֫ʻàl֥wòţ hiné֤̇h ׀ bá̇ràk֣ẇ ʼeţ-yĕ֭hwáh ká̇l-ʻabĕdé֣y yĕhwá֑h há⁠ʻòmĕdi֥ym bĕ̇⁠béyţ-yĕ֝hwá֗h bȧ⁠lé̇ylֽwòţ׃"],[134,2,"שְׂאֽוּ־יְדֵ⁠כֶ֥ם קֹ֑דֶשׁ וּ֝⁠בָרֲכוּ אֶת־יְהוָֽה׃","şĕ̂ʼֽẇ-yĕdé⁠ke֥m qò֑deş̌ ẇ֝⁠báràkẇ ʼeţ-yĕhwáֽh׃"],[134,3,"יְבָרֶכְ⁠ךָ֣ יְ֭הוָה מִ⁠צִּיּ֑וֹן עֹ֝שֵׂ֗ה שָׁמַ֥יִם וָ⁠אָֽרֶץ׃","yĕbárekĕ⁠ká֣ yĕ֭hwáh mi⁠ẕi̇ẏ֑wòn ʻò֝şé̂֗h şá̌ma֥yim wá⁠ʼáֽreẕ׃"],[135,1,"הַ֥לְלוּ יָ֨הּ ׀ הַֽ֭לְלוּ אֶת־שֵׁ֣ם יְהוָ֑ה הַֽ֝לְלוּ עַבְדֵ֥י יְהוָֽה׃","ha֥lĕlẇ yá֨ḣ ׀ haֽ֭lĕlẇ ʼeţ-şé֣̌m yĕhwá֑h hֽa֝lĕlẇ ʻabĕdé֥y yĕhwáֽh׃"],[135,2,"שֶׁ֣֭⁠עֹֽמְדִים בְּ⁠בֵ֣ית יְהוָ֑ה בְּ֝⁠חַצְר֗וֹת בֵּ֣ית אֱלֹהֵֽי⁠נוּ׃","şě֣֭⁠ʻòֽmĕdiym bĕ̇⁠bé֣yţ yĕhwá֑h bĕ̇֝⁠ẖaẕĕr֗wòţ bé֣̇yţ ʼèlòhéֽy⁠nẇ׃"],[135,3,"הַֽ֭לְלוּ־יָהּ כִּי־ט֣וֹב יְהוָ֑ה זַמְּר֥וּ לִ֝⁠שְׁמ֗⁠וֹ כִּ֣י נָעִֽים׃","haֽ֭lĕlẇ-yáḣ ki̇y-t֣wòb yĕhwá֑h zamĕ̇r֥ẇ li֝⁠şĕ̌m֗⁠wò ki֣̇y náʻiֽym׃"],[135,4,"כִּֽי־יַעֲקֹ֗ב בָּחַ֣ר ל֣⁠וֹ יָ֑הּ יִ֝שְׂרָאֵ֗ל לִ⁠סְגֻלָּתֽ⁠וֹ׃","kiֽ̇y-yaʻàqò֗b bá̇ẖa֣r l֣⁠wò yá֑ḣ yi֝şĕ̂ráʼé֗l li⁠sĕgulá̇ţֽ⁠wò׃"],[135,5,"כִּ֤י אֲנִ֣י יָ֭דַעְתִּי כִּי־גָד֣וֹל יְהוָ֑ה וַ֝⁠אֲדֹנֵ֗י⁠נוּ מִ⁠כָּל־אֱלֹהִֽים׃","ki֤̇y ʼàni֣y yá֭daʻĕţi̇y ki̇y-gád֣wòl yĕhwá֑h wa֝⁠ʼàdòné֗y⁠nẇ mi⁠ká̇l-ʼèlòhiֽym׃"],[135,6,"כֹּ֤ל אֲשֶׁר־חָפֵ֥ץ יְהוָ֗ה עָ֫שָׂ֥ה בַּ⁠שָּׁמַ֥יִם וּ⁠בָ⁠אָ֑רֶץ בַּ֝⁠יַּמִּ֗ים וְ⁠כָל־תְּהוֹמֽוֹת׃","kò֤̇l ʼàşěr-ẖápé֥ẕ yĕhwá֗h ʻá֫şá֥̂h bȧ⁠şá̇̌ma֥yim ẇ⁠bá⁠ʼá֑reẕ bȧ֝⁠yȧmi̇֗ym wĕ⁠kál-ţĕ̇hwòmֽwòţ׃"],[135,7,"מַֽעֲלֶ֣ה נְשִׂאִים֮ מִ⁠קְצֵ֪ה הָ֫⁠אָ֥רֶץ בְּרָקִ֣ים לַ⁠מָּטָ֣ר עָשָׂ֑ה מֽוֹצֵא־ר֝וּחַ מֵ⁠אֽוֹצְרוֹתָֽי⁠ו׃","maֽʻàle֣h nĕşîʼiym֮ mi⁠qĕẕé֪h há֫⁠ʼá֥reẕ bĕ̇ráqi֣ym la⁠má̇tá֣r ʻáşá֑̂h mֽwòẕéʼ-r֝ẇẖa mé⁠ʼֽwòẕĕrwòţáֽy⁠w׃"],[135,8,"שֶֽׁ֭⁠הִכָּה בְּכוֹרֵ֣י מִצְרָ֑יִם מֵ֝⁠אָדָ֗ם עַד־בְּהֵמָֽה׃","şěֽ֭⁠hiká̇h bĕ̇kwòré֣y miẕĕrá֑yim mé֝⁠ʼádá֗m ʻad-bĕ̇hémáֽh׃"],[135,9,"שָׁלַ֤ח ׀ אֹת֣וֹת וּ֭⁠מֹפְתִים בְּ⁠תוֹכֵ֣⁠כִי מִצְרָ֑יִם בְּ֝⁠פַרְעֹ֗ה וּ⁠בְ⁠כָל־עֲבָדָֽי⁠ו׃","şá̌la֤ẖ ׀ ʼòţ֣wòţ ẇ֭⁠mòpĕţiym bĕ̇⁠ţwòké֣⁠kiy miẕĕrá֑yim bĕ̇֝⁠parĕʻò֗h ẇ⁠bĕ⁠kál-ʻàbádáֽy⁠w׃"],[135,10,"שֶֽׁ֭⁠הִכָּה גּוֹיִ֣ם רַבִּ֑ים וְ֝⁠הָרַ֗ג מְלָכִ֥ים עֲצוּמִֽים׃","şěֽ֭⁠hiká̇h ġwòyi֣m rabi֑̇ym wĕ֝⁠hára֗g mĕláki֥ym ʻàẕẇmiֽym׃"],[135,11,"לְ⁠סִיח֤וֹן ׀ מֶ֤לֶךְ הָ⁠אֱמֹרִ֗י וּ֭⁠לְ⁠עוֹג מֶ֣לֶךְ הַ⁠בָּשָׁ֑ן וּ֝⁠לְ⁠כֹ֗ל מַמְלְכ֥וֹת כְּנָֽעַן׃","lĕ⁠siyẖ֤wòn ׀ me֤lekĕ há⁠ʼèmòri֗y ẇ֭⁠lĕ⁠ʻwòg me֣lekĕ ha⁠bá̇şá֑̌n ẇ֝⁠lĕ⁠kò֗l mamĕlĕk֥wòţ kĕ̇náֽʻan׃"],[135,12,"וְ⁠נָתַ֣ן אַרְצָ֣⁠ם נַחֲלָ֑ה נַ֝חֲלָ֗ה לְ⁠יִשְׂרָאֵ֥ל עַמּֽ⁠וֹ׃","wĕ⁠náţa֣n ʼarĕẕá֣⁠m naẖàlá֑h na֝ẖàlá֗h lĕ⁠yişĕ̂ráʼé֥l ʻaṁֽ⁠wò׃"],[135,13,"יְ֭הוָה שִׁמְ⁠ךָ֣ לְ⁠עוֹלָ֑ם יְ֝הוָ֗ה זִכְרְ⁠ךָ֥ לְ⁠דֹר־וָ⁠דֹֽר׃","yĕ֭hwáh şǐmĕ⁠ká֣ lĕ⁠ʻwòlá֑m yĕ֝hwá֗h zikĕrĕ⁠ká֥ lĕ⁠dòr-wá⁠dòֽr׃"],[135,14,"כִּֽי־יָדִ֣ין יְהוָ֣ה עַמּ֑⁠וֹ וְ⁠עַל־עֲ֝בָדָ֗י⁠ו יִתְנֶחָֽם׃","kiֽ̇y-yádi֣yn yĕhwá֣h ʻaṁ֑⁠wò wĕ⁠ʻal-ʻà֝bádá֗y⁠w yiţĕneẖáֽm׃"],[135,15,"עֲצַבֵּ֣י הַ֭⁠גּוֹיִם כֶּ֣סֶף וְ⁠זָהָ֑ב מַ֝עֲשֵׂ֗ה יְדֵ֣י אָדָֽם׃","ʻàẕabé֣̇y ha֭⁠ġwòyim kė֣sep wĕ⁠záhá֑b ma֝ʻàşé̂֗h yĕdé֣y ʼádáֽm׃"],[135,16,"פֶּֽה־לָ֭⁠הֶם וְ⁠לֹ֣א יְדַבֵּ֑רוּ עֵינַ֥יִם לָ֝⁠הֶ֗ם וְ⁠לֹ֣א יִרְאֽוּ׃","pėֽh-lá֭⁠hem wĕ⁠lò֣ʼ yĕdabé֑̇rẇ ʻéyna֥yim lá֝⁠he֗m wĕ⁠lò֣ʼ yirĕʼֽẇ׃"],[135,17,"אָזְנַ֣יִם לָ֭⁠הֶם וְ⁠לֹ֣א יַאֲזִ֑ינוּ אַ֝֗ף אֵין־יֶשׁ־ר֥וּחַ בְּ⁠פִי⁠הֶֽם׃","ʼázĕna֣yim lá֭⁠hem wĕ⁠lò֣ʼ yaʼàzi֑ynẇ ʼa֝֗p ʼéyn-yeş̌-r֥ẇẖa bĕ̇⁠piy⁠heֽm׃"],[135,18,"כְּ֭מוֹ⁠הֶם יִהְי֣וּ עֹשֵׂי⁠הֶ֑ם כֹּ֭ל אֲשֶׁר־בֹּטֵ֣חַ בָּ⁠הֶֽם׃","kĕ֭̇mwò⁠hem yihĕy֣ẇ ʻòşé̂y⁠he֑m kò֭̇l ʼàşěr-bò̇té֣ẖa bá̇⁠heֽm׃"],[135,19,"בֵּ֣ית יִ֭שְׂרָאֵל בָּרֲכ֣וּ אֶת־יְהוָ֑ה בֵּ֥ית אַ֝הֲרֹ֗ן בָּרֲכ֥וּ אֶת־יְהוָֽה׃","bé֣̇yţ yi֭şĕ̂ráʼél bá̇ràk֣ẇ ʼeţ-yĕhwá֑h bé֥̇yţ ʼa֝hàrò֗n bá̇ràk֥ẇ ʼeţ-yĕhwáֽh׃"],[135,20,"בֵּ֣ית הַ֭⁠לֵּוִי בָּרֲכ֣וּ אֶת־יְהוָ֑ה יִֽרְאֵ֥י יְ֝הוָ֗ה בָּרֲכ֥וּ אֶת־יְהוָֽה׃","bé֣̇yţ ha֭⁠lé̇wiy bá̇ràk֣ẇ ʼeţ-yĕhwá֑h yiֽrĕʼé֥y yĕ֝hwá֗h bá̇ràk֥ẇ ʼeţ-yĕhwáֽh׃"],[135,21,"בָּ֘ר֤וּךְ יְהוָ֨ה ׀ מִ⁠צִּיּ֗וֹן שֹׁ֘כֵ֤ן יְֽרוּשָׁלִָ֗ם הַֽלְלוּ־יָֽהּ׃","bá̇֘r֤ẇkĕ yĕhwá֨h ׀ mi⁠ẕi̇ẏ֗wòn şò̌֘ké֤n yĕֽrẇşá̌liá֗m haֽlĕlẇ-yáֽḣ׃"],[136,1,"הוֹד֣וּ לַ⁠יהוָ֣ה כִּי־ט֑וֹב כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","hwòd֣ẇ la⁠yhwá֣h ki̇y-t֑wòb ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,2,"ה֭וֹדוּ לֵֽ⁠אלֹהֵ֣י הָ⁠אֱלֹהִ֑ים כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","h֭wòdẇ léֽ⁠ʼlòhé֣y há⁠ʼèlòhi֑ym ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,3,"ה֭וֹדוּ לַ⁠אֲדֹנֵ֣י הָ⁠אֲדֹנִ֑ים כִּ֖י לְ⁠עֹלָ֣ם חַסְדּֽ⁠וֹ׃","h֭wòdẇ la⁠ʼàdòné֣y há⁠ʼàdòni֑ym ki֖̇y lĕ⁠ʻòlá֣m ẖasĕḋֽ⁠wò׃"],[136,4,"לְ⁠עֹ֘שֵׂ֤ה נִפְלָא֣וֹת גְּדֹל֣וֹת לְ⁠בַדּ֑⁠וֹ כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ⁠ʻò֘şé֤̂h nipĕláʼ֣wòţ gĕ̇dòl֣wòţ lĕ⁠baḋ֑⁠wò ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,5,"לְ⁠עֹשֵׂ֣ה הַ֭⁠שָּׁמַיִם בִּ⁠תְבוּנָ֑ה כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ⁠ʻòşé֣̂h ha֭⁠şá̇̌mayim bi̇⁠ţĕbẇná֑h ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,6,"לְ⁠רֹקַ֣ע הָ֭⁠אָרֶץ עַל־הַ⁠מָּ֑יִם כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ⁠ròqa֣ʻ há֭⁠ʼáreẕ ʻal-ha⁠má֑̇yim ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,7,"לְ֭⁠עֹשֵׂה אוֹרִ֣ים גְּדֹלִ֑ים כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ֭⁠ʻòşé̂h ʼwòri֣ym gĕ̇dòli֑ym ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,8,"אֶת־הַ֭⁠שֶּׁמֶשׁ לְ⁠מֶמְשֶׁ֣לֶת בַּ⁠יּ֑וֹם כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","ʼeţ-ha֭⁠şė̌meş̌ lĕ⁠memĕşě֣leţ bȧ⁠ẏ֑wòm ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,9,"אֶת־הַ⁠יָּרֵ֣חַ וְ֭⁠כוֹכָבִים לְ⁠מֶמְשְׁל֣וֹת בַּ⁠לָּ֑יְלָה כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","ʼeţ-ha⁠yá̇ré֣ẖa wĕ֭⁠kwòkábiym lĕ⁠memĕşĕ̌l֣wòţ bȧ⁠lá֑̇yĕláh ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,10,"לְ⁠מַכֵּ֣ה מִ֭צְרַיִם בִּ⁠בְכוֹרֵי⁠הֶ֑ם כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ⁠maké֣̇h mi֭ẕĕrayim bi̇⁠bĕkwòréy⁠he֑m ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,11,"וַ⁠יּוֹצֵ֣א יִ֭שְׂרָאֵל מִ⁠תּוֹכָ֑⁠ם כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","wa⁠ẏwòẕé֣ʼ yi֭şĕ̂ráʼél mi⁠ţ̇wòká֑⁠m ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,12,"בְּ⁠יָ֣ד חֲ֭זָקָה וּ⁠בִ⁠זְר֣וֹעַ נְטוּיָ֑ה כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","bĕ̇⁠yá֣d ẖà֭záqáh ẇ⁠bi⁠zĕr֣wòʻa nĕtẇyá֑h ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,13,"לְ⁠גֹזֵ֣ר יַם־ס֭וּף לִ⁠גְזָרִ֑ים כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ⁠gòzé֣r yam-s֭ẇp li⁠gĕzári֑ym ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,14,"וְ⁠הֶעֱבִ֣יר יִשְׂרָאֵ֣ל בְּ⁠תוֹכ֑⁠וֹ כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","wĕ⁠heʻèbi֣yr yişĕ̂ráʼé֣l bĕ̇⁠ţwòk֑⁠wò ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,15,"וְ⁠נִ֘עֵ֤ר פַּרְעֹ֣ה וְ⁠חֵיל֣⁠וֹ בְ⁠יַם־ס֑וּף כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","wĕ⁠ni֘ʻé֤r pȧrĕʻò֣h wĕ⁠ẖéyl֣⁠wò bĕ⁠yam-s֑ẇp ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,16,"לְ⁠מוֹלִ֣יךְ עַ֭מּ⁠וֹ בַּ⁠מִּדְבָּ֑ר כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ⁠mwòli֣ykĕ ʻa֭ṁ⁠wò bȧ⁠mi̇dĕbá֑̇r ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,17,"לְ֭⁠מַכֵּה מְלָכִ֣ים גְּדֹלִ֑ים כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ֭⁠maké̇h mĕláki֣ym gĕ̇dòli֑ym ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,18,"וַֽ֭⁠יַּהֲרֹג מְלָכִ֣ים אַדִּירִ֑ים כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","wֽa֭⁠yȧhàròg mĕláki֣ym ʼadi̇yri֑ym ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,19,"לְ֭⁠סִיחוֹן מֶ֣לֶךְ הָ⁠אֱמֹרִ֑י כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","lĕ֭⁠siyẖwòn me֣lekĕ há⁠ʼèmòri֑y ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,20,"וּ֭⁠לְ⁠עוֹג מֶ֣לֶךְ הַ⁠בָּשָׁ֑ן כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","ẇ֭⁠lĕ⁠ʻwòg me֣lekĕ ha⁠bá̇şá֑̌n ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,21,"וְ⁠נָתַ֣ן אַרְצָ֣⁠ם לְ⁠נַחֲלָ֑ה כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","wĕ⁠náţa֣n ʼarĕẕá֣⁠m lĕ⁠naẖàlá֑h ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,22,"נַ֭חֲלָה לְ⁠יִשְׂרָאֵ֣ל עַבְדּ֑⁠וֹ כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","na֭ẖàláh lĕ⁠yişĕ̂ráʼé֣l ʻabĕḋ֑⁠wò ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,23,"שֶׁ֭⁠בְּ⁠שִׁפְלֵ⁠נוּ זָ֣כַר לָ֑⁠נוּ כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","şě֭⁠bĕ̇⁠şǐpĕlé⁠nẇ zá֣kar lá֑⁠nẇ ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,24,"וַ⁠יִּפְרְקֵ֥⁠נוּ מִ⁠צָּרֵ֑י⁠נוּ כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","wa⁠yi̇pĕrĕqé֥⁠nẇ mi⁠ẕá̇ré֑y⁠nẇ ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,25,"נֹתֵ֣ן לֶ֭חֶם לְ⁠כָל־בָּשָׂ֑ר כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","nòţé֣n le֭ẖem lĕ⁠kál-bá̇şá֑̂r ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[136,26,"ה֭וֹדוּ לְ⁠אֵ֣ל הַ⁠שָּׁמָ֑יִם כִּ֖י לְ⁠עוֹלָ֣ם חַסְדּֽ⁠וֹ׃","h֭wòdẇ lĕ⁠ʼé֣l ha⁠şá̇̌má֑yim ki֖̇y lĕ⁠ʻwòlá֣m ẖasĕḋֽ⁠wò׃"],[137,1,"עַ֥ל נַהֲר֨וֹת ׀ בָּבֶ֗ל שָׁ֣ם יָ֭שַׁבְנוּ גַּם־בָּכִ֑ינוּ בְּ֝⁠זָכְרֵ֗⁠נוּ אֶת־צִיּֽוֹן׃","ʻa֥l nahàr֨wòţ ׀ bá̇be֗l şá֣̌m yá֭şǎbĕnẇ gȧm-bá̇ki֑ynẇ bĕ̇֝⁠zákĕré֗⁠nẇ ʼeţ-ẕiẏֽwòn׃"],[137,2,"עַֽל־עֲרָבִ֥ים בְּ⁠תוֹכָ֑⁠הּ תָּ֝לִ֗ינוּ כִּנֹּרוֹתֵֽי⁠נוּ׃","ʻaֽl-ʻàrábi֥ym bĕ̇⁠ţwòká֑⁠ḣ ţá̇֝li֗ynẇ ki̇nò̇rwòţéֽy⁠nẇ׃"],[137,3,"כִּ֤י שָׁ֨ם שְֽׁאֵל֪וּ⁠נוּ שׁוֹבֵ֡י⁠נוּ דִּבְרֵי־שִׁ֭יר וְ⁠תוֹלָלֵ֣י⁠נוּ שִׂמְחָ֑ה שִׁ֥ירוּ לָ֝֗⁠נוּ מִ⁠שִּׁ֥יר צִיּֽוֹן׃","ki֤̇y şá̌֨m şĕֽ̌ʼél֪ẇ⁠nẇ ş̌wòbé֡y⁠nẇ di̇bĕréy-şǐ֭yr wĕ⁠ţwòlálé֣y⁠nẇ şîmĕẖá֑h şǐ֥yrẇ lá֝֗⁠nẇ mi⁠şi֥̇̌yr ẕiẏֽwòn׃"],[137,4,"אֵ֗יךְ נָשִׁ֥יר אֶת־שִׁיר־יְהוָ֑ה עַ֝֗ל אַדְמַ֥ת נֵכָֽר׃","ʼé֗ykĕ náşǐ֥yr ʼeţ-şǐyr-yĕhwá֑h ʻa֝֗l ʼadĕma֥ţ nékáֽr׃"],[137,5,"אִֽם־אֶשְׁכָּחֵ֥⁠ךְ יְֽרוּשָׁלִָ֗ם תִּשְׁכַּ֥ח יְמִינִֽ⁠י׃","ʼiֽm-ʼeşĕ̌ká̇ẖé֥⁠kĕ yĕֽrẇşá̌liá֗m ţi̇şĕ̌kȧ֥ẖ yĕmiynֽi⁠y׃"],[137,6,"תִּדְבַּ֥ק־לְשׁוֹנִ֨⁠י ׀ לְ⁠חִכִּ⁠י֮ אִם־לֹ֪א אֶ֫זְכְּרֵ֥⁠כִי אִם־לֹ֣א אַ֭עֲלֶה אֶת־יְרוּשָׁלִַ֑ם עַ֝֗ל רֹ֣אשׁ שִׂמְחָתִֽ⁠י׃","ţi̇dĕbȧ֥q-lĕş̌wòni֨⁠y ׀ lĕ⁠ẖiki̇⁠y֮ ʼim-lò֪ʼ ʼe֫zĕkĕ̇ré֥⁠kiy ʼim-lò֣ʼ ʼa֭ʻàleh ʼeţ-yĕrẇşá̌lia֑m ʻa֝֗l rò֣ʼş̌ şîmĕẖáţֽi⁠y׃"],[137,7,"זְכֹ֤ר יְהוָ֨ה ׀ לִ⁠בְנֵ֬י אֱד֗וֹם אֵת֮ י֤וֹם יְֽרוּשָׁ֫לִָ֥ם הָ֭⁠אֹ֣מְרִים עָ֤רוּ ׀ עָ֑רוּ עַ֝֗ד הַ⁠יְס֥וֹד בָּֽ⁠הּ׃","zĕkò֤r yĕhwá֨h ׀ li⁠bĕné֬y ʼèd֗wòm ʼéţ֮ y֤wòm yĕֽrẇşá̌֫liá֥m há֭⁠ʼò֣mĕriym ʻá֤rẇ ׀ ʻá֑rẇ ʻa֝֗d ha⁠yĕs֥wòd báֽ̇⁠ḣ׃"],[137,8,"בַּת־בָּבֶ֗ל הַ⁠שְּׁד֫וּדָ֥ה אַשְׁרֵ֥י שֶׁ⁠יְשַׁלֶּם־לָ֑⁠ךְ אֶת־גְּ֝מוּלֵ֗⁠ךְ שֶׁ⁠גָּמַ֥לְתְּ לָֽ⁠נוּ׃","bȧţ-bá̇be֗l ha⁠şĕ̇̌d֫ẇdá֥h ʼaşĕ̌ré֥y şě⁠yĕşǎlėm-lá֑⁠kĕ ʼeţ-gĕ̇֝mẇlé֗⁠kĕ şě⁠gá̇ma֥lĕţĕ̇ láֽ⁠nẇ׃"],[137,9,"אַשְׁרֵ֤י ׀ שֶׁ⁠יֹּאחֵ֓ז וְ⁠נִפֵּ֬ץ אֶֽת־עֹ֝לָלַ֗יִ⁠ךְ אֶל־הַ⁠סָּֽלַע׃","ʼaşĕ̌ré֤y ׀ şě⁠yò̇ʼẖé֓z wĕ⁠nipé̇֬ẕ ʼeֽţ-ʻò֝lála֗yi⁠kĕ ʼel-ha⁠sáֽ̇laʻ׃"],[138,1,"לְ⁠דָוִ֨ד ׀ אוֹדְ⁠ךָ֥ בְ⁠כָל־לִבִּ֑⁠י נֶ֖גֶד אֱלֹהִ֣ים אֲזַמְּרֶֽ⁠ךָּ׃","lĕ⁠dáwi֨d ׀ ʼwòdĕ⁠ká֥ bĕ⁠kál-libi֑̇⁠y ne֖ged ʼèlòhi֣ym ʼàzamĕ̇reֽ⁠ká̇׃"],[138,2,"אֶשְׁתַּחֲוֶ֨ה אֶל־הֵיכַ֪ל קָדְשְׁ⁠ךָ֡ וְ⁠א֘וֹדֶ֤ה אֶת־שְׁמֶ֗⁠ךָ עַל־חַסְדְּ⁠ךָ֥ וְ⁠עַל־אֲמִתֶּ֑⁠ךָ כִּֽי־הִגְדַּ֥לְתָּ עַל־כָּל־שִׁ֝מְ⁠ךָ֗ אִמְרָתֶֽ⁠ךָ׃","ʼeşĕ̌ţȧẖàwe֨h ʼel-héyka֪l qádĕşĕ̌⁠ká֡ wĕ⁠ʼ֘wòde֤h ʼeţ-şĕ̌me֗⁠ká ʻal-ẖasĕdĕ̇⁠ká֥ wĕ⁠ʻal-ʼàmiţė֑⁠ká kiֽ̇y-higĕdȧ֥lĕţá̇ ʻal-ká̇l-şǐ֝mĕ⁠ká֗ ʼimĕráţeֽ⁠ká׃"],[138,3,"בְּ⁠י֣וֹם קָ֭רָֽאתִי וַֽ⁠תַּעֲנֵ֑⁠נִי תַּרְהִבֵ֖⁠נִי בְ⁠נַפְשִׁ֣⁠י עֹֽז׃","bĕ̇⁠y֣wòm qá֭ráֽʼţiy waֽ⁠ţȧʻàné֑⁠niy ţȧrĕhibé֖⁠niy bĕ⁠napĕşǐ֣⁠y ʻòֽz׃"],[138,4,"יוֹד֣וּ⁠ךָ יְ֭הוָה כָּל־מַלְכֵי־אָ֑רֶץ כִּ֥י שָׁ֝מְע֗וּ אִמְרֵי־פִֽי⁠ךָ׃","ywòd֣ẇ⁠ká yĕ֭hwáh ká̇l-malĕkéy-ʼá֑reẕ ki֥̇y şá̌֝mĕʻ֗ẇ ʼimĕréy-piֽy⁠ká׃"],[138,5,"וְ֭⁠יָשִׁירוּ בְּ⁠דַרְכֵ֣י יְהוָ֑ה כִּ֥י גָ֝ד֗וֹל כְּב֣וֹד יְהוָֽה׃","wĕ֭⁠yáşǐyrẇ bĕ̇⁠darĕké֣y yĕhwá֑h ki֥̇y gá֝d֗wòl kĕ̇b֣wòd yĕhwáֽh׃"],[138,6,"כִּי־רָ֣ם יְ֭הוָה וְ⁠שָׁפָ֣ל יִרְאֶ֑ה וְ֝⁠גָבֹ֗הַּ מִ⁠מֶּרְחָ֥ק יְיֵדָֽע׃","ki̇y-rá֣m yĕ֭hwáh wĕ⁠şá̌pá֣l yirĕʼe֑h wĕ֝⁠gábò֗hȧ mi⁠mėrĕẖá֥q yĕyédáֽʻ׃"],[138,7,"אִם־אֵלֵ֤ךְ ׀ בְּ⁠קֶ֥רֶב צָרָ֗ה תְּחַ֫יֵּ֥⁠נִי עַ֤ל אַ֣ף אֹ֭יְבַ⁠י תִּשְׁלַ֣ח יָדֶ֑⁠ךָ וְ⁠ת֖וֹשִׁיעֵ֣⁠נִי יְמִינֶֽ⁠ךָ׃","ʼim-ʼélé֤kĕ ׀ bĕ̇⁠qe֥reb ẕárá֗h ţĕ̇ẖa֫yé֥̇⁠niy ʻa֤l ʼa֣p ʼò֭yĕba⁠y ţi̇şĕ̌la֣ẖ yáde֑⁠ká wĕ⁠ţ֖wòşǐyʻé֣⁠niy yĕmiyneֽ⁠ká׃"],[138,8,"יְהוָה֮ יִגְמֹ֪ר בַּ֫עֲדִ֥⁠י יְ֭הוָה חַסְדְּ⁠ךָ֣ לְ⁠עוֹלָ֑ם מַעֲשֵׂ֖י יָדֶ֣י⁠ךָ אַל־תֶּֽרֶף׃","yĕhwáh֮ yigĕmò֪r bȧ֫ʻàdi֥⁠y yĕ֭hwáh ẖasĕdĕ̇⁠ká֣ lĕ⁠ʻwòlá֑m maʻàşé֖̂y yáde֣y⁠ká ʼal-ţėֽrep׃"],[139,1,"לַ֭⁠מְנַצֵּחַ לְ⁠דָוִ֣ד מִזְמ֑וֹר יְהוָ֥ה חֲ֝קַרְתַּ֗⁠נִי וַ⁠תֵּדָֽע׃","la֭⁠mĕnaẕé̇ẖa lĕ⁠dáwi֣d mizĕm֑wòr yĕhwá֥h ẖà֝qarĕţȧ֗⁠niy wa⁠ţé̇dáֽʻ׃"],[139,2,"אַתָּ֣ה יָ֭דַעְתָּ שִׁבְתִּ֣⁠י וְ⁠קוּמִ֑⁠י בַּ֥נְתָּה לְ֝⁠רֵעִ֗⁠י מֵ⁠רָחֽוֹק׃","ʼaţá֣̇h yá֭daʻĕţá̇ şǐbĕţi֣̇⁠y wĕ⁠qẇmi֑⁠y bȧ֥nĕţá̇h lĕ֝⁠réʻi֗⁠y mé⁠ráẖֽwòq׃"],[139,3,"אָרְחִ֣⁠י וְ⁠רִבְעִ֣⁠י זֵרִ֑יתָ וְֽ⁠כָל־דְּרָכַ֥⁠י הִסְכַּֽנְתָּה׃","ʼárĕẖi֣⁠y wĕ⁠ribĕʻi֣⁠y zéri֑yţá wĕֽ⁠kál-dĕ̇ráka֥⁠y hisĕkȧֽnĕţá̇h׃"],[139,4,"כִּ֤י אֵ֣ין מִ֭לָּה בִּ⁠לְשׁוֹנִ֑⁠י הֵ֥ן יְ֝הוָ֗ה יָדַ֥עְתָּ כֻלָּֽ⁠הּ׃","ki֤̇y ʼé֣yn mi֭lá̇h bi̇⁠lĕş̌wòni֑⁠y hé֥n yĕ֝hwá֗h yáda֥ʻĕţá̇ kuláֽ̇⁠ḣ׃"],[139,5,"אָח֣וֹר וָ⁠קֶ֣דֶם צַרְתָּ֑⁠נִי וַ⁠תָּ֖שֶׁת עָלַ֣⁠י כַּפֶּֽ⁠כָה׃","ʼáẖ֣wòr wá⁠qe֣dem ẕarĕţá֑̇⁠niy wa⁠ţá֖̇şěţ ʻála֣⁠y kȧpėֽ⁠káh׃"],[139,6,"פלאיה דַ֣עַת מִמֶּ֑⁠נִּי נִ֝שְׂגְּבָ֗ה לֹא־א֥וּכַֽל לָֽ⁠הּ׃","plʼyh da֣ʻaţ mimė֑⁠ni̇y ni֝şĕ̂gĕ̇bá֗h lòʼ-ʼ֥ẇkaֽl láֽ⁠ḣ׃"],[139,7,"אָ֭נָ֥ה אֵלֵ֣ךְ מֵ⁠רוּחֶ֑⁠ךָ וְ֝⁠אָ֗נָה מִ⁠פָּנֶ֥י⁠ךָ אֶבְרָֽח׃","ʼá֭ná֥h ʼélé֣kĕ mé⁠rẇẖe֑⁠ká wĕ֝⁠ʼá֗náh mi⁠pá̇ne֥y⁠ká ʼebĕráֽẖ׃"],[139,8,"אִם־אֶסַּ֣ק שָׁ֭מַיִם שָׁ֣ם אָ֑תָּה וְ⁠אַצִּ֖יעָה שְּׁא֣וֹל הִנֶּֽ⁠ךָּ׃","ʼim-ʼesȧ֣q şá֭̌mayim şá֣̌m ʼá֑ţá̇h wĕ⁠ʼaẕi֖̇yʻáh şĕ̇̌ʼ֣wòl hinėֽ⁠ká̇׃"],[139,9,"אֶשָּׂ֥א כַנְפֵי־שָׁ֑חַר אֶ֝שְׁכְּנָ֗ה בְּ⁠אַחֲרִ֥ית יָֽם׃","ʼeşá֥̇̂ʼ kanĕpéy-şá֑̌ẖar ʼe֝şĕ̌kĕ̇ná֗h bĕ̇⁠ʼaẖàri֥yţ yáֽm׃"],[139,10,"גַּם־שָׁ֭ם יָדְ⁠ךָ֣ תַנְחֵ֑⁠נִי וְֽ⁠תֹאחֲזֵ֥⁠נִי יְמִינֶֽ⁠ךָ׃","gȧm-şá֭̌m yádĕ⁠ká֣ ţanĕẖé֑⁠niy wĕֽ⁠ţòʼẖàzé֥⁠niy yĕmiyneֽ⁠ká׃"],[139,11,"וָ֭⁠אֹמַר אַךְ־חֹ֣שֶׁךְ יְשׁוּפֵ֑⁠נִי וְ֝⁠לַ֗יְלָה א֣וֹר בַּעֲדֵֽ⁠נִי׃","wá֭⁠ʼòmar ʼakĕ-ẖò֣şěkĕ yĕş̌ẇpé֑⁠niy wĕ֝⁠la֗yĕláh ʼ֣wòr bȧʻàdéֽ⁠niy׃"],[139,12,"גַּם־חֹשֶׁךְ֮ לֹֽא־יַחְשִׁ֪יךְ מִ֫מֶּ֥⁠ךָ וְ֭⁠לַיְלָה כַּ⁠יּ֣וֹם יָאִ֑יר כַּ֝⁠חֲשֵׁיכָ֗ה כָּ⁠אוֹרָֽה׃","gȧm-ẖòşěkĕ֮ lòֽʼ-yaẖĕşǐ֪ykĕ mi֫mė֥⁠ká wĕ֭⁠layĕláh kȧ⁠ẏ֣wòm yáʼi֑yr kȧ֝⁠ẖàşé̌yká֗h ká̇⁠ʼwòráֽh׃"],[139,13,"כִּֽי־אַ֭תָּה קָנִ֣יתָ כִלְיֹתָ֑⁠י תְּ֝סֻכֵּ֗⁠נִי בְּ⁠בֶ֣טֶן אִמִּֽ⁠י׃","kiֽ̇y-ʼa֭ţá̇h qáni֣yţá kilĕyòţá֑⁠y ţĕ̇֝suké̇֗⁠niy bĕ̇⁠be֣ten ʼimiֽ̇⁠y׃"],[139,14,"אֽוֹדְ⁠ךָ֗ עַ֤ל כִּ֥י נוֹרָא֗וֹת נִ֫פְלֵ֥יתִי נִפְלָאִ֥ים מַעֲשֶׂ֑י⁠ךָ וְ֝⁠נַפְשִׁ֗⁠י יֹדַ֥עַת מְאֹֽד׃","ʼֽwòdĕ⁠ká֗ ʻa֤l ki֥̇y nwòráʼ֗wòţ ni֫pĕlé֥yţiy nipĕláʼi֥ym maʻàşê֑y⁠ká wĕ֝⁠napĕşǐ֗⁠y yòda֥ʻaţ mĕʼòֽd׃"],[139,15,"לֹא־נִכְחַ֥ד עָצְמִ֗⁠י מִ֫מֶּ֥⁠ךָּ אֲשֶׁר־עֻשֵּׂ֥יתִי בַ⁠סֵּ֑תֶר רֻ֝קַּ֗מְתִּי בְּֽ⁠תַחְתִּיּ֥וֹת אָֽרֶץ׃","lòʼ-nikĕẖa֥d ʻáẕĕmi֗⁠y mi֫mė֥⁠ká̇ ʼàşěr-ʻuşé֥̇̂yţiy ba⁠sé֑̇ţer ru֝qȧ֗mĕţi̇y bĕֽ̇⁠ţaẖĕţi̇ẏ֥wòţ ʼáֽreẕ׃"],[139,16,"גָּלְמִ֤⁠י ׀ רָ֘א֤וּ עֵינֶ֗י⁠ךָ וְ⁠עַֽל־סִפְרְ⁠ךָ֮ כֻּלָּ֪⁠ם יִכָּ֫תֵ֥בוּ יָמִ֥ים יֻצָּ֑רוּ ו⁠לא אֶחָ֣ד בָּ⁠הֶֽם׃","gá̇lĕmi֤⁠y ׀ rá֘ʼ֤ẇ ʻéyne֗y⁠ká wĕ⁠ʻaֽl-sipĕrĕ⁠ká֮ ku̇lá֪̇⁠m yiká̇֫ţé֥bẇ yámi֥ym yuẕá֑̇rẇ w⁠lʼ ʼeẖá֣d bá̇⁠heֽm׃"],[139,17,"וְ⁠לִ֗⁠י מַה־יָּקְר֣וּ רֵעֶ֣י⁠ךָ אֵ֑ל מֶ֥ה עָ֝צְמוּ רָאשֵׁי⁠הֶֽם׃","wĕ⁠li֗⁠y mah-yá̇qĕr֣ẇ réʻe֣y⁠ká ʼé֑l me֥h ʻá֝ẕĕmẇ ráʼşé̌y⁠heֽm׃"],[139,18,"אֶ֭סְפְּרֵ⁠ם מֵ⁠ח֣וֹל יִרְבּ֑וּ⁠ן הֱ֝קִיצֹ֗תִי וְ⁠עוֹדִ֥⁠י עִמָּֽ⁠ךְ׃","ʼe֭sĕpĕ̇ré⁠m mé⁠ẖ֣wòl yirĕḃ֑ẇ⁠n hè֝qiyẕò֗ţiy wĕ⁠ʻwòdi֥⁠y ʻimáֽ̇⁠kĕ׃"],[139,19,"אִם־תִּקְטֹ֖ל אֱל֥וֹהַּ ׀ רָשָׁ֑ע וְ⁠אַנְשֵׁ֥י דָ֝מִ֗ים ס֣וּרוּ מֶֽ⁠נִּי׃","ʼim-ţi̇qĕtò֖l ʼèl֥wòhȧ ׀ ráşá֑̌ʻ wĕ⁠ʼanĕşé֥̌y dá֝mi֗ym s֣ẇrẇ meֽ⁠ni̇y׃"],[139,20,"אֲשֶׁ֣ר יֹ֭אמְרֻ⁠ךָ לִ⁠מְזִמָּ֑ה נָשֻׂ֖א לַ⁠שָּׁ֣וְא עָרֶֽי⁠ךָ׃","ʼàşě֣r yò֭ʼmĕru⁠ká li⁠mĕzimá֑̇h náşû֖ʼ la⁠şá֣̇̌wĕʼ ʻáreֽy⁠ká׃"],[139,21,"הֲ⁠לֽוֹא־מְשַׂנְאֶ֖י⁠ךָ יְהוָ֥ה ׀ אֶשְׂנָ֑א וּ֝⁠בִ⁠תְקוֹמְמֶ֗י⁠ךָ אֶתְקוֹטָֽט׃","hà⁠lֽwòʼ-mĕşânĕʼe֖y⁠ká yĕhwá֥h ׀ ʼeşĕ̂ná֑ʼ ẇ֝⁠bi⁠ţĕqwòmĕme֗y⁠ká ʼeţĕqwòtáֽt׃"],[139,22,"תַּכְלִ֣ית שִׂנְאָ֣ה שְׂנֵאתִ֑י⁠ם לְ֝⁠אוֹיְבִ֗ים הָ֣יוּ לִֽ⁠י׃","ţȧkĕli֣yţ şînĕʼá֣h şĕ̂néʼţi֑y⁠m lĕ֝⁠ʼwòyĕbi֗ym há֣yẇ liֽ⁠y׃"],[139,23,"חָקְרֵ֣⁠נִי אֵ֭ל וְ⁠דַ֣ע לְבָבִ֑⁠י בְּ֝חָנֵ֗⁠נִי וְ⁠דַ֣ע שַׂרְעַפָּֽ⁠י׃","ẖáqĕré֣⁠niy ʼé֭l wĕ⁠da֣ʻ lĕbábi֑⁠y bĕ̇֝ẖáné֗⁠niy wĕ⁠da֣ʻ şârĕʻapáֽ̇⁠y׃"],[139,24,"וּ⁠רְאֵ֗ה אִם־דֶּֽרֶךְ־עֹ֥צֶב בִּ֑⁠י וּ֝⁠נְחֵ֗⁠נִי בְּ⁠דֶ֣רֶךְ עוֹלָֽם׃","ẇ⁠rĕʼé֗h ʼim-dėֽrekĕ-ʻò֥ẕeb bi֑̇⁠y ẇ֝⁠nĕẖé֗⁠niy bĕ̇⁠de֣rekĕ ʻwòláֽm׃"],[140,1,"חַלְּצֵ֣⁠נִי יְ֭הוָה מֵ⁠אָדָ֣ם רָ֑ע מֵ⁠אִ֖ישׁ חֲמָסִ֣ים תִּנְצְרֵֽ⁠נִי׃","ẖalĕ̇ẕé֣⁠niy yĕ֭hwáh mé⁠ʼádá֣m rá֑ʻ mé⁠ʼi֖yş̌ ẖàmási֣ym ţi̇nĕẕĕréֽ⁠niy׃"],[140,2,"אֲשֶׁ֤ר חָשְׁב֣וּ רָע֣וֹת בְּ⁠לֵ֑ב כָּל־י֝֗וֹם יָג֥וּרוּ מִלְחָמֽוֹת׃","ʼàşě֤r ẖáşĕ̌b֣ẇ ráʻ֣wòţ bĕ̇⁠lé֑b ká̇l-y֝֗wòm yág֥ẇrẇ milĕẖámֽwòţ׃"],[140,3,"שָֽׁנֲנ֣וּ לְשׁוֹנָ⁠ם֮ כְּֽמוֹ־נָ֫חָ֥שׁ חֲמַ֥ת עַכְשׁ֑וּב תַּ֖חַת שְׂפָתֵ֣י⁠מוֹ סֶֽלָה׃","şáֽ̌nàn֣ẇ lĕş̌wòná⁠m֮ kĕֽ̇mwò-ná֫ẖá֥ş̌ ẖàma֥ţ ʻakĕş֑̌ẇb ţȧ֖ẖaţ şĕ̂páţé֣y⁠mwò seֽláh׃"],[140,4,"שָׁמְרֵ֤⁠נִי יְהוָ֨ה ׀ מִ֘⁠ידֵ֤י רָשָׁ֗ע מֵ⁠אִ֣ישׁ חֲמָסִ֣ים תִּנְצְרֵ֑⁠נִי אֲשֶׁ֥ר חָ֝שְׁב֗וּ לִ⁠דְח֥וֹת פְּעָמָֽ⁠י׃","şá̌mĕré֤⁠niy yĕhwá֨h ׀ mi֘⁠ydé֤y ráşá̌֗ʻ mé⁠ʼi֣yş̌ ẖàmási֣ym ţi̇nĕẕĕré֑⁠niy ʼàşě֥r ẖá֝şĕ̌b֗ẇ li⁠dĕẖ֥wòţ pĕ̇ʻámáֽ⁠y׃"],[140,5,"טָֽמְנֽוּ־גֵאִ֨ים ׀ פַּ֡ח לִ֗⁠י וַ⁠חֲבָלִ֗ים פָּ֣רְשׂוּ רֶ֭שֶׁת לְ⁠יַד־מַעְגָּ֑ל מֹקְשִׁ֖ים שָֽׁתוּ־לִ֣⁠י סֶֽלָה׃","táֽmĕnֽẇ-géʼi֨ym ׀ pȧ֡ẖ li֗⁠y wa⁠ẖàbáli֗ym pá֣̇rĕş̂ẇ re֭şěţ lĕ⁠yad-maʻĕgá֑̇l mòqĕşǐ֖ym şáֽ̌ţẇ-li֣⁠y seֽláh׃"],[140,6,"אָמַ֣רְתִּי לַ֭⁠יהוָה אֵ֣לִ⁠י אָ֑תָּה הַאֲזִ֥ינָ⁠ה יְ֝הוָ֗ה ק֣וֹל תַּחֲנוּנָֽ⁠י׃","ʼáma֣rĕţi̇y la֭⁠yhwáh ʼé֣li⁠y ʼá֑ţá̇h haʼàzi֥yná⁠h yĕ֝hwá֗h q֣wòl ţȧẖànẇnáֽ⁠y׃"],[140,7,"יְהֹוִ֣ה אֲ֭דֹנָ⁠י עֹ֣ז יְשׁוּעָתִ֑⁠י סַכֹּ֥תָה לְ֝⁠רֹאשִׁ֗⁠י בְּ⁠י֣וֹם נָֽשֶׁק׃","yĕhòwi֣h ʼà֭dòná⁠y ʻò֣z yĕş̌ẇʻáţi֑⁠y sakò֥̇ţáh lĕ֝⁠ròʼşǐ֗⁠y bĕ̇⁠y֣wòm náֽşěq׃"],[140,8,"אַל־תִּתֵּ֣ן יְ֭הוָה מַאֲוַיֵּ֣י רָשָׁ֑ע זְמָמ֥⁠וֹ אַל־תָּ֝פֵ֗ק יָר֥וּמוּ סֶֽלָה׃","ʼal-ţi̇ţé֣̇n yĕ֭hwáh maʼàwayé֣̇y ráşá֑̌ʻ zĕmám֥⁠wò ʼal-ţá̇֝pé֗q yár֥ẇmẇ seֽláh׃"],[140,9,"רֹ֥אשׁ מְסִבָּ֑⁠י עֲמַ֖ל שְׂפָתֵ֣י⁠מוֹ יכסו⁠מו׃","rò֥ʼş̌ mĕsibá֑̇⁠y ʻàma֖l şĕ̂páţé֣y⁠mwò yksw⁠mw׃"],[140,10,"ימיטו עֲלֵי⁠הֶ֗ם גֶּֽחָ֫לִ֥ים בָּ⁠אֵ֥שׁ יַפִּלֵ֑⁠ם בְּ֝⁠מַהֲמֹר֗וֹת בַּֽל־יָקֽוּמוּ׃","ymytw ʻàléy⁠he֗m gėֽẖá֫li֥ym bá̇⁠ʼé֥ş̌ yapi̇lé֑⁠m bĕ̇֝⁠mahàmòr֗wòţ bȧֽl-yáqֽẇmẇ׃"],[140,11,"אִ֥ישׁ לָשׁוֹן֮ בַּל־יִכּ֪וֹן בָּ֫⁠אָ֥רֶץ אִישׁ־חָמָ֥ס רָ֑ע יְ֝צוּדֶ֗⁠נּוּ לְ⁠מַדְחֵפֹֽת׃","ʼi֥yş̌ láş̌wòn֮ bȧl-yik֪̇wòn bá̇֫⁠ʼá֥reẕ ʼiyş̌-ẖámá֥s rá֑ʻ yĕ֝ẕẇde֗⁠ṅẇ lĕ⁠madĕẖépòֽţ׃"],[140,12,"ידעת כִּֽי־יַעֲשֶׂ֣ה יְ֭הוָה דִּ֣ין עָנִ֑י מִ֝שְׁפַּ֗ט אֶבְיֹנִֽים׃","ydʻţ kiֽ̇y-yaʻàşê֣h yĕ֭hwáh di֣̇yn ʻáni֑y mi֝şĕ̌pȧ֗t ʼebĕyòniֽym׃"],[140,13,"אַ֣ךְ צַ֭דִּיקִים יוֹד֣וּ לִ⁠שְׁמֶ֑⁠ךָ יֵשְׁב֥וּ יְ֝שָׁרִ֗ים אֶת־פָּנֶֽי⁠ךָ׃","ʼa֣kĕ ẕa֭di̇yqiym ywòd֣ẇ li⁠şĕ̌me֑⁠ká yéşĕ̌b֥ẇ yĕ֝şá̌ri֗ym ʼeţ-pá̇neֽy⁠ká׃"],[141,1,"מִזְמ֗וֹר לְ⁠דָ֫וִ֥ד יְהוָ֣ה קְ֭רָאתִי⁠ךָ ח֣וּשָׁ⁠ה לִּ֑⁠י הַאֲזִ֥ינָ⁠ה ק֝וֹלִ֗⁠י בְּ⁠קָרְאִ⁠י־לָֽ⁠ךְ׃","mizĕm֗wòr lĕ⁠dá֫wi֥d yĕhwá֣h qĕ֭ráʼţiy⁠ká ẖ֣ẇşá̌⁠h li֑̇⁠y haʼàzi֥yná⁠h q֝wòli֗⁠y bĕ̇⁠qárĕʼi⁠y-láֽ⁠kĕ׃"],[141,2,"תִּכּ֤וֹן תְּפִלָּתִ֣⁠י קְטֹ֣רֶת לְ⁠פָנֶ֑י⁠ךָ מַֽשְׂאַ֥ת כַּ֝פַּ֗⁠י מִנְחַת־עָֽרֶב׃","ţi̇k֤̇wòn ţĕ̇pilá̇ţi֣⁠y qĕtò֣reţ lĕ⁠páne֑y⁠ká maֽşĕ̂ʼa֥ţ kȧ֝pȧ֗⁠y minĕẖaţ-ʻáֽreb׃"],[141,3,"שִׁיתָ֣⁠ה יְ֭הוָה שָׁמְרָ֣ה לְ⁠פִ֑⁠י נִ֝צְּרָ֗⁠ה עַל־דַּ֥ל שְׂפָתָֽ⁠י׃","şǐyţá֣⁠h yĕ֭hwáh şá̌mĕrá֣h lĕ⁠pi֑⁠y ni֝ẕĕ̇rá֗⁠h ʻal-dȧ֥l şĕ̂páţáֽ⁠y׃"],[141,4,"אַל־תַּט־לִבִּ֨⁠י לְ⁠דָבָ֪ר ׀ רָ֡ע לְ⁠הִתְע֘וֹלֵ֤ל עֲלִל֨וֹת ׀ בְּ⁠רֶ֗שַׁע אֶת־אִישִׁ֥ים פֹּֽעֲלֵי־אָ֑וֶן וּ⁠בַל־אֶ֝לְחַ֗ם בְּ⁠מַנְעַמֵּי⁠הֶֽם׃","ʼal-ţȧt-libi̇֨⁠y lĕ⁠dábá֪r ׀ rá֡ʻ lĕ⁠hiţĕʻ֘wòlé֤l ʻàlil֨wòţ ׀ bĕ̇⁠re֗şǎʻ ʼeţ-ʼiyşǐ֥ym pòֽ̇ʻàléy-ʼá֑wen ẇ⁠bal-ʼe֝lĕẖa֗m bĕ̇⁠manĕʻamé̇y⁠heֽm׃"],[141,5,"יֶֽהֶלְמֵֽ⁠נִי־צַדִּ֨יק ׀ חֶ֡סֶד וְֽ⁠יוֹכִיחֵ֗⁠נִי שֶׁ֣מֶן רֹ֭אשׁ אַל־יָנִ֣י רֹאשִׁ֑⁠י כִּי־ע֥וֹד וּ֝⁠תְפִלָּתִ֗⁠י בְּ⁠רָעוֹתֵי⁠הֶֽם׃","yeֽhelĕméֽ⁠niy-ẕadi̇֨yq ׀ ẖe֡sed wĕֽ⁠ywòkiyẖé֗⁠niy şě֣men rò֭ʼş̌ ʼal-yáni֣y ròʼşǐ֑⁠y ki̇y-ʻ֥wòd ẇ֝⁠ţĕpilá̇ţi֗⁠y bĕ̇⁠ráʻwòţéy⁠heֽm׃"],[141,6,"נִשְׁמְט֣וּ בִֽ⁠ידֵי־סֶ֭לַע שֹׁפְטֵי⁠הֶ֑ם וְ⁠שָׁמְע֥וּ אֲ֝מָרַ֗⁠י כִּ֣י נָעֵֽמוּ׃","nişĕ̌mĕt֣ẇ biֽ⁠ydéy-se֭laʻ şò̌pĕtéy⁠he֑m wĕ⁠şá̌mĕʻ֥ẇ ʼà֝mára֗⁠y ki֣̇y náʻéֽmẇ׃"],[141,7,"כְּמ֤וֹ פֹלֵ֣חַ וּ⁠בֹקֵ֣עַ בָּ⁠אָ֑רֶץ נִפְזְר֥וּ עֲ֝צָמֵ֗י⁠נוּ לְ⁠פִ֣י שְׁאֽוֹל׃","kĕ̇m֤wò pòlé֣ẖa ẇ⁠bòqé֣ʻa bá̇⁠ʼá֑reẕ nipĕzĕr֥ẇ ʻà֝ẕámé֗y⁠nẇ lĕ⁠pi֣y şĕ̌ʼֽwòl׃"],[141,8,"כִּ֤י אֵלֶ֨י⁠ךָ ׀ יְהֹוִ֣ה אֲדֹנָ֣⁠י עֵינָ֑⁠י בְּ⁠כָ֥ה חָ֝סִ֗יתִי אַל־תְּעַ֥ר נַפְשִֽׁ⁠י׃","ki֤̇y ʼéle֨y⁠ká ׀ yĕhòwi֣h ʼàdòná֣⁠y ʻéyná֑⁠y bĕ̇⁠ká֥h ẖá֝si֗yţiy ʼal-ţĕ̇ʻa֥r napĕşǐֽ⁠y׃"],[141,9,"שָׁמְרֵ֗⁠נִי מִ֣⁠ידֵי פַ֭ח יָ֣קְשׁוּ לִ֑⁠י וּ֝⁠מֹקְשׁ֗וֹת פֹּ֣עֲלֵי אָֽוֶן׃","şá̌mĕré֗⁠niy mi֣⁠ydéy pa֭ẖ yá֣qĕş̌ẇ li֑⁠y ẇ֝⁠mòqĕş̌֗wòţ pò֣̇ʻàléy ʼáֽwen׃"],[141,10,"יִפְּל֣וּ בְ⁠מַכְמֹרָ֣י⁠ו רְשָׁעִ֑ים יַ֥חַד אָ֝נֹכִ֗י עַֽד־אֶעֱבֽוֹר׃","yipĕ̇l֣ẇ bĕ⁠makĕmòrá֣y⁠w rĕşá̌ʻi֑ym ya֥ẖad ʼá֝nòki֗y ʻaֽd-ʼeʻèbֽwòr׃"],[142,1,"ק֭וֹלִ⁠י אֶל־יְהוָ֣ה אֶזְעָ֑ק ק֝וֹלִ֗⁠י אֶל־יְהוָ֥ה אֶתְחַנָּֽן׃","q֭wòli⁠y ʼel-yĕhwá֣h ʼezĕʻá֑q q֝wòli֗⁠y ʼel-yĕhwá֥h ʼeţĕẖanáֽ̇n׃"],[142,2,"אֶשְׁפֹּ֣ךְ לְ⁠פָנָ֣י⁠ו שִׂיחִ֑⁠י צָ֝רָתִ֗⁠י לְ⁠פָנָ֥י⁠ו אַגִּֽיד׃","ʼeşĕ̌pò֣̇kĕ lĕ⁠páná֣y⁠w şîyẖi֑⁠y ẕá֝ráţi֗⁠y lĕ⁠páná֥y⁠w ʼagiֽ̇yd׃"],[142,3,"בְּ⁠הִתְעַטֵּ֬ף עָלַ֨⁠י ׀ רוּחִ֗⁠י וְ⁠אַתָּה֮ יָדַ֪עְתָּ נְֽתִיבָ֫תִ֥⁠י בְּ⁠אֹֽרַח־ז֥וּ אֲהַלֵּ֑ךְ טָמְנ֖וּ פַ֣ח לִֽ⁠י׃","bĕ̇⁠hiţĕʻaté̇֬p ʻála֨⁠y ׀ rẇẖi֗⁠y wĕ⁠ʼaţá̇h֮ yáda֪ʻĕţá̇ nĕֽţiybá֫ţi֥⁠y bĕ̇⁠ʼòֽraẖ-z֥ẇ ʼàhalé֑̇kĕ támĕn֖ẇ pa֣ẖ liֽ⁠y׃"],[142,4,"הַבֵּ֤יט יָמִ֨ין ׀ וּ⁠רְאֵה֮ וְ⁠אֵֽין־לִ֪⁠י מַ֫כִּ֥יר אָבַ֣ד מָנ֣וֹס מִמֶּ֑⁠נִּי אֵ֖ין דּוֹרֵ֣שׁ לְ⁠נַפְשִֽׁ⁠י׃","habé֤̇yt yámi֨yn ׀ ẇ⁠rĕʼéh֮ wĕ⁠ʼéֽyn-li֪⁠y ma֫ki֥̇yr ʼába֣d mán֣wòs mimė֑⁠ni̇y ʼé֖yn ḋwòré֣ş̌ lĕ⁠napĕşǐֽ⁠y׃"],[142,5,"זָעַ֥קְתִּי אֵלֶ֗י⁠ךָ יְה֫וָ֥ה אָ֭מַרְתִּי אַתָּ֣ה מַחְסִ֑⁠י חֶ֝לְקִ֗⁠י בְּ⁠אֶ֣רֶץ הַֽ⁠חַיִּים׃","záʻa֥qĕţi̇y ʼéle֗y⁠ká yĕh֫wá֥h ʼá֭marĕţi̇y ʼaţá֣̇h maẖĕsi֑⁠y ẖe֝lĕqi֗⁠y bĕ̇⁠ʼe֣reẕ haֽ⁠ẖayi̇ym׃"],[142,6,"הַקְשִׁ֤יבָ⁠ה ׀ אֶֽל־רִנָּתִ⁠י֮ כִּֽי־דַלּ֪וֹתִ֫י מְאֹ֥ד הַצִּילֵ֥⁠נִי מֵ⁠רֹדְפַ֑⁠י כִּ֖י אָמְצ֣וּ מִמֶּֽ⁠נִּי׃","haqĕşǐ֤ybá⁠h ׀ ʼeֽl-riná̇ţi⁠y֮ kiֽ̇y-dal֪̇wòţi֫y mĕʼò֥d haẕi̇ylé֥⁠niy mé⁠ròdĕpa֑⁠y ki֖̇y ʼámĕẕ֣ẇ mimėֽ⁠ni̇y׃"],[142,7,"ה֘וֹצִ֤יאָ⁠ה מִ⁠מַּסְגֵּ֨ר ׀ נַפְשִׁ⁠י֮ לְ⁠הוֹד֪וֹת אֶת־שְׁ֫מֶ֥⁠ךָ בִּ֭⁠י יַכְתִּ֣רוּ צַדִּיקִ֑ים כִּ֖י תִגְמֹ֣ל עָלָֽ⁠י׃","h֘wòẕi֤yʼá⁠h mi⁠mȧsĕgé̇֨r ׀ napĕşǐ⁠y֮ lĕ⁠hwòd֪wòţ ʼeţ-şĕ̌֫me֥⁠ká bi֭̇⁠y yakĕţi֣̇rẇ ẕadi̇yqi֑ym ki֖̇y ţigĕmò֣l ʻálֽá⁠y׃"],[143,1,"מִזְמ֗וֹר לְ⁠דָ֫וִ֥ד יְהוָ֤ה ׀ שְׁמַ֬ע תְּפִלָּתִ֗⁠י הַאֲזִ֥ינָ⁠ה אֶל־תַּחֲנוּנַ֑⁠י בֶּ⁠אֱמֻנָתְ⁠ךָ֥ עֲ֝נֵ֗⁠נִי בְּ⁠צִדְקָתֶֽ⁠ךָ׃","mizĕm֗wòr lĕ⁠dá֫wi֥d yĕhwá֤h ׀ şĕ̌ma֬ʻ ţĕ̇pilá̇ţi֗⁠y haʼàzi֥yná⁠h ʼel-ţȧẖànẇna֑⁠y bė⁠ʼèmunáţĕ⁠ká֥ ʻà֝né֗⁠niy bĕ̇⁠ẕidĕqáţeֽ⁠ká׃"],[143,2,"וְ⁠אַל־תָּב֣וֹא בְ֭⁠מִשְׁפָּט אֶת־עַבְדֶּ֑⁠ךָ כִּ֤י לֹֽא־יִצְדַּ֖ק לְ⁠פָנֶ֣י⁠ךָ כָל־חָֽי׃","wĕ⁠ʼal-ţá̇b֣wòʼ bĕ֭⁠mişĕ̌pá̇t ʼeţ-ʻabĕdė֑⁠ká ki֤̇y lòֽʼ-yiẕĕdȧ֖q lĕ⁠páne֣y⁠ká kál-ẖáֽy׃"],[143,3,"כִּ֥י רָ֘דַ֤ף אוֹיֵ֨ב ׀ נַפְשִׁ֗⁠י דִּכָּ֣א לָ֭⁠אָרֶץ חַיָּתִ֑⁠י הוֹשִׁיבַ֥⁠נִי בְ֝⁠מַחֲשַׁכִּ֗ים כְּ⁠מֵתֵ֥י עוֹלָֽם׃","ki֥̇y rá֘da֤p ʼwòyé֨b ׀ napĕşǐ֗⁠y di̇ká֣̇ʼ lá֭⁠ʼáreẕ ẖayá̇ţi֑⁠y hwòşǐyba֥⁠niy bĕ֝⁠maẖàşǎki̇֗ym kĕ̇⁠méţé֥y ʻwòláֽm׃"],[143,4,"וַ⁠תִּתְעַטֵּ֣ף עָלַ֣⁠י רוּחִ֑⁠י בְּ֝⁠תוֹכִ֗⁠י יִשְׁתּוֹמֵ֥ם לִבִּֽ⁠י׃","wa⁠ţi̇ţĕʻaté֣̇p ʻála֣⁠y rẇẖi֑⁠y bĕ̇֝⁠ţwòki֗⁠y yişĕ̌ţ̇wòmé֥m libiֽ̇⁠y׃"],[143,5,"זָ֘כַ֤רְתִּי יָמִ֨ים ׀ מִ⁠קֶּ֗דֶם הָגִ֥יתִי בְ⁠כָל־פָּעֳלֶ֑⁠ךָ בְּֽ⁠מַעֲשֵׂ֖ה יָדֶ֣י⁠ךָ אֲשׂוֹחֵֽחַ׃","zá֘ka֤rĕţi̇y yámi֨ym ׀ mi⁠qė֗dem hági֥yţiy bĕ⁠kál-pá̇ʻole֑⁠ká bĕֽ̇⁠maʻàşé֖̂h yáde֣y⁠ká ʼàş̂wòẖéֽẖa׃"],[143,6,"פֵּרַ֣שְׂתִּי יָדַ֣⁠י אֵלֶ֑י⁠ךָ נַפְשִׁ֓⁠י ׀ כְּ⁠אֶֽרֶץ־עֲיֵפָ֖ה לְ⁠ךָ֣ סֶֽלָה׃","pé̇ra֣şĕ̂ţi̇y yáda֣⁠y ʼéle֑y⁠ká napĕşǐ֓⁠y ׀ kĕ̇⁠ʼeֽreẕ-ʻàyépá֖h lĕ⁠ká֣ seֽláh׃"],[143,7,"מַ֘הֵ֤ר עֲנֵ֨⁠נִי ׀ יְהוָה֮ כָּלְתָ֪ה ר֫וּחִ֥⁠י אַל־תַּסְתֵּ֣ר פָּנֶ֣י⁠ךָ מִמֶּ֑⁠נִּי וְ֝⁠נִמְשַׁ֗לְתִּי עִם־יֹ֥רְדֵי בֽוֹר׃","ma֘hé֤r ʻàné֨⁠niy ׀ yĕhwáh֮ ká̇lĕţá֪h r֫ẇẖi֥⁠y ʼal-ţȧsĕţé֣̇r pá̇ne֣y⁠ká mimė֑⁠ni̇y wĕ֝⁠nimĕşǎ֗lĕţi̇y ʻim-yò֥rĕdéy bֽwòr׃"],[143,8,"הַשְׁמִ֘יעֵ֤⁠נִי בַ⁠בֹּ֨קֶר ׀ חַסְדֶּ⁠ךָ֮ כִּֽי־בְ⁠ךָ֪ בָ֫טָ֥חְתִּי הוֹדִיעֵ֗⁠נִי דֶּֽרֶךְ־ז֥וּ אֵלֵ֑ךְ כִּֽי־אֵ֝לֶי⁠ךָ נָשָׂ֥אתִי נַפְשִֽׁ⁠י׃","haşĕ̌mi֘yʻé֤⁠niy ba⁠bò̇֨qer ׀ ẖasĕdė⁠ká֮ kiֽ̇y-bĕ⁠ká֪ bá֫tá֥ẖĕţi̇y hwòdiyʻé֗⁠niy dėֽrekĕ-z֥ẇ ʼélé֑kĕ kiֽ̇y-ʼé֝ley⁠ká náşá֥̂ʼţiy napĕşǐֽ⁠y׃"],[143,9,"הַצִּילֵ֖⁠נִי מֵ⁠אֹיְבַ֥⁠י ׀ יְהוָ֗ה אֵלֶ֥י⁠ךָ כִסִּֽתִי׃","haẕi̇ylé֖⁠niy mé⁠ʼòyĕba֥⁠y ׀ yĕhwá֗h ʼéle֥y⁠ká kisiֽ̇ţiy׃"],[143,10,"לַמְּדֵ֤⁠נִי ׀ לַֽ⁠עֲשׂ֣וֹת רְצוֹנֶ⁠ךָ֮ כִּֽי־אַתָּ֪ה אֱל֫וֹהָ֥⁠י רוּחֲ⁠ךָ֥ טוֹבָ֑ה תַּ֝נְחֵ֗⁠נִי בְּ⁠אֶ֣רֶץ מִישֽׁוֹר׃","lamĕ̇dé֤⁠niy ׀ laֽ⁠ʻàş֣̂wòţ rĕẕwòne⁠ká֮ kiֽ̇y-ʼaţá֪̇h ʼèl֫wòhá֥⁠y rẇẖà⁠ká֥ twòbá֑h ţȧ֝nĕẖé֗⁠niy bĕ̇⁠ʼe֣reẕ miyşֽ̌wòr׃"],[143,11,"לְמַֽעַן־שִׁמְ⁠ךָ֣ יְהוָ֣ה תְּחַיֵּ֑⁠נִי בְּ⁠צִדְקָתְ⁠ךָ֓ ׀ תוֹצִ֖יא מִ⁠צָּרָ֣ה נַפְשִֽׁ⁠י׃","lĕmaֽʻan-şǐmĕ⁠ká֣ yĕhwá֣h ţĕ̇ẖayé֑̇⁠niy bĕ̇⁠ẕidĕqáţĕ⁠ká֓ ׀ ţwòẕi֖yʼ mi⁠ẕá̇rá֣h napĕşǐֽ⁠y׃"],[143,12,"וּֽ⁠בְ⁠חַסְדְּ⁠ךָ֮ תַּצְמִ֪ית אֹ֫יְבָ֥⁠י וְֽ֭⁠הַאֲבַדְתָּ כָּל־צֹרֲרֵ֣י נַפְשִׁ֑⁠י כִּ֝֗י אֲנִ֣י עַבְדֶּֽ⁠ךָ׃","ẇֽ⁠bĕ⁠ẖasĕdĕ̇⁠ká֮ ţȧẕĕmi֪yţ ʼò֫yĕbá֥⁠y wĕֽ֭⁠haʼàbadĕţá̇ ká̇l-ẕòràré֣y napĕşǐ֑⁠y ki̇֝֗y ʼàni֣y ʻabĕdėֽ⁠ká׃"],[144,1,"לְ⁠דָוִ֨ד ׀ בָּ֘ר֤וּךְ יְהוָ֨ה ׀ צוּרִ֗⁠י הַֽ⁠מְלַמֵּ֣ד יָדַ֣⁠י לַ⁠קְרָ֑ב אֶ֝צְבְּעוֹתַ֗⁠י לַ⁠מִּלְחָמָֽה׃","lĕ⁠dáwi֨d ׀ bá̇֘r֤ẇkĕ yĕhwá֨h ׀ ẕẇri֗⁠y haֽ⁠mĕlamé֣̇d yáda֣⁠y la⁠qĕrá֑b ʼe֝ẕĕbĕ̇ʻwòţa֗⁠y la⁠mi̇lĕẖámáֽh׃"],[144,2,"חַסְדִּ֥⁠י וּ⁠מְצוּדָתִ⁠י֮ מִשְׂגַּבִּ֪⁠י וּֽ⁠מְפַלְטִ֫⁠י לִ֥⁠י מָ֭גִנִּ⁠י וּ⁠ב֣⁠וֹ חָסִ֑יתִי הָ⁠רוֹדֵ֖ד עַמִּ֣⁠י תַחְתָּֽ⁠י׃","ẖasĕdi֥̇⁠y ẇ⁠mĕẕẇdáţi⁠y֮ mişĕ̂gȧbi֪̇⁠y ẇֽ⁠mĕpalĕti֫⁠y li֥⁠y má֭gini̇⁠y ẇ⁠b֣⁠wò ẖási֑yţiy há⁠rwòdé֖d ʻami֣̇⁠y ţaẖĕţáֽ̇⁠y׃"],[144,3,"יְֽהוָ֗ה מָה־אָ֭דָם וַ⁠תֵּדָעֵ֑⁠הוּ בֶּן־אֱ֝נ֗וֹשׁ וַֽ⁠תְּחַשְּׁבֵֽ⁠הוּ׃","yĕֽhwá֗h máh-ʼá֭dám wa⁠ţé̇dáʻé֑⁠hẇ bėn-ʼè֝n֗wòş̌ waֽ⁠ţĕ̇ẖaşĕ̇̌béֽ⁠hẇ׃"],[144,4,"אָ֭דָם לַ⁠הֶ֣בֶל דָּמָ֑ה יָ֝מָ֗י⁠ו כְּ⁠צֵ֣ל עוֹבֵֽר׃","ʼá֭dám la⁠he֣bel dá̇má֑h yá֝má֗y⁠w kĕ̇⁠ẕé֣l ʻwòbéֽr׃"],[144,5,"יְ֭הוָה הַט־שָׁמֶ֣י⁠ךָ וְ⁠תֵרֵ֑ד גַּ֖ע בֶּ⁠הָרִ֣ים וְֽ⁠יֶעֱשָֽׁנוּ׃","yĕ֭hwáh hat-şá̌me֣y⁠ká wĕ⁠ţéré֑d gȧ֖ʻ bė⁠hári֣ym wֽĕ⁠yeʻèşáֽ̌nẇ׃"],[144,6,"בְּר֣וֹק בָּ֭רָק וּ⁠תְפִיצֵ֑⁠ם שְׁלַ֥ח חִ֝צֶּ֗י⁠ךָ וּ⁠תְהֻמֵּֽ⁠ם׃","bĕ̇r֣wòq bá֭̇ráq ẇ⁠ţĕpiyẕé֑⁠m şĕ̌la֥ẖ ẖi֝ẕė֗y⁠ká ẇ⁠ţĕhuméֽ̇⁠m׃"],[144,7,"שְׁלַ֥ח יָדֶ֗י⁠ךָ מִ⁠מָּ֫ר֥וֹם פְּצֵ֣⁠נִי וְ֭⁠הַצִּילֵ⁠נִי מִ⁠מַּ֣יִם רַבִּ֑ים מִ֝⁠יַּ֗ד בְּנֵ֣י נֵכָֽר׃","şĕ̌la֥ẖ yáde֗y⁠ká mi⁠má̇֫r֥wòm pĕ̇ẕé֣⁠niy wĕ֭⁠haẕi̇ylé⁠niy mi⁠mȧ֣yim rabi֑̇ym mi֝⁠yȧ֗d bĕ̇né֣y nékáֽr׃"],[144,8,"אֲשֶׁ֣ר פִּ֭י⁠הֶם דִּבֶּר־שָׁ֑וְא וִֽ֝⁠ימִינָ֗⁠ם יְמִ֣ין שָֽׁקֶר׃","ʼàşě֣r pi֭̇y⁠hem di̇bėr-şá֑̌wĕʼ wiֽ֝⁠ymiyná֗⁠m yĕmi֣yn şáֽ̌qer׃"],[144,9,"אֱֽלֹהִ֗ים שִׁ֣יר חָ֭דָשׁ אָשִׁ֣ירָה לָּ֑⁠ךְ בְּ⁠נֵ֥בֶל עָ֝שׂ֗וֹר אֲזַמְּרָה־לָּֽ⁠ךְ׃","ʼèֽlòhi֗ym şǐ֣yr ẖá֭dáş̌ ʼáşǐ֣yráh lá֑̇⁠kĕ bĕ̇⁠né֥bel ʻá֝ş̂֗wòr ʼàzamĕ̇ráh-láֽ̇⁠kĕ׃"],[144,10,"הַ⁠נּוֹתֵ֥ן תְּשׁוּעָ֗ה לַ⁠מְּלָ֫כִ֥ים הַ֭⁠פּוֹצֶה אֶת־דָּוִ֥ד עַבְדּ֗⁠וֹ מֵ⁠חֶ֥רֶב רָעָֽה׃","ha⁠ṅwòţé֥n ţĕ̇ş̌ẇʻá֗h la⁠mĕ̇lá֫ki֥ym ha֭⁠ṗwòẕeh ʼeţ-dá̇wi֥d ʻabĕḋ֗⁠wò mé⁠ẖe֥reb ráʻáֽh׃"],[144,11,"פְּצֵ֥⁠נִי וְ⁠הַצִּילֵ⁠נִי֮ מִ⁠יַּ֪ד בְּֽנֵי־נֵ֫כָ֥ר אֲשֶׁ֣ר פִּ֭י⁠הֶם דִּבֶּר־שָׁ֑וְא וִֽ֝⁠ימִינָ֗⁠ם יְמִ֣ין שָֽׁקֶר׃","pĕ̇ẕé֥⁠niy wĕ⁠haẕi̇ylé⁠niy֮ mi⁠yȧ֪d bĕֽ̇néy-né֫ká֥r ʼàşě֣r pi֭̇y⁠hem di̇bėr-şá֑̌wĕʼ wiֽ֝⁠ymiyná֗⁠m yĕmi֣yn şáֽ̌qer׃"],[144,12,"אֲשֶׁ֤ר בָּנֵ֨י⁠נוּ ׀ כִּ⁠נְטִעִים֮ מְגֻדָּלִ֪ים בִּֽ⁠נְעוּרֵ֫י⁠הֶ֥ם בְּנוֹתֵ֥י⁠נוּ כְ⁠זָוִיֹּ֑ת מְ֝חֻטָּב֗וֹת תַּבְנִ֥ית הֵיכָֽל׃","ʼàşě֤r bá̇né֨y⁠nẇ ׀ ki̇⁠nĕtiʻiym֮ mĕgudá̇li֪ym biֽ̇⁠nĕʻẇré֫y⁠he֥m bĕ̇nwòţé֥y⁠nẇ kĕ⁠záwiyò֑̇ţ mĕ֝ẖutá̇b֗wòţ ţȧbĕni֥yţ héykáֽl׃"],[144,13,"מְזָוֵ֣י⁠נוּ מְלֵאִים֮ מְפִיקִ֥ים מִ⁠זַּ֗ן אֶ֫ל־זַ֥ן צֹאונֵ֣⁠נוּ מַ֭אֲלִיפוֹת מְרֻבָּב֗וֹת בְּ⁠חוּצוֹתֵֽי⁠נוּ׃","mĕzáwé֣y⁠nẇ mĕléʼiym֮ mĕpiyqi֥ym mi⁠zȧ֗n ʼe֫l-za֥n ẕòʼwné֣⁠nẇ ma֭ʼàliypwòţ mĕrubá̇b֗wòţ bĕ̇⁠ẖẇẕwòţéֽy⁠nẇ׃"],[144,14,"אַלּוּפֵ֗י⁠נוּ מְֽסֻבָּ֫לִ֥ים אֵֽין־פֶּ֭רֶץ וְ⁠אֵ֣ין יוֹצֵ֑את וְ⁠אֵ֥ין צְ֝וָחָ֗ה בִּ⁠רְחֹבֹתֵֽי⁠נוּ׃","ʼal̇ẇpé֗y⁠nẇ mĕֽsubá̇֫li֥ym ʼéֽyn-pė֭reẕ wĕ⁠ʼé֣yn ywòẕé֑ʼţ wĕ⁠ʼé֥yn ẕĕ֝wáẖá֗h bi̇⁠rĕẖòbòţéֽy⁠nẇ׃"],[144,15,"אַשְׁרֵ֣י הָ֭⁠עָם שֶׁ⁠כָּ֣כָה לּ֑⁠וֹ אַֽשְׁרֵ֥י הָ֝⁠עָ֗ם שֶׁ⁠יֲהוָ֥ה אֱלֹהָֽי⁠ו׃","ʼaşĕ̌ré֣y há֭⁠ʻám şě⁠ká֣̇káh l֑̇⁠wò ʼaֽşĕ̌ré֥y há֝⁠ʻá֗m şě⁠yàhwá֥h ʼèlòháֽy⁠w׃"],[145,1,"תְּהִלָּ֗ה לְ⁠דָ֫וִ֥ד אֲרוֹמִמְ⁠ךָ֣ אֱלוֹהַ֣⁠י הַ⁠מֶּ֑לֶךְ וַ⁠אֲבָרֲכָ֥ה שִׁ֝מְ⁠ךָ֗ לְ⁠עוֹלָ֥ם וָ⁠עֶֽד׃","ţĕ̇hilá̇֗h lĕ⁠dá֫wi֥d ʼàrwòmimĕ⁠ká֣ ʼèlwòha֣⁠y ha⁠mė֑lekĕ wa⁠ʼàbáràká֥h şǐ֝mĕ⁠ká֗ lĕ⁠ʻwòlá֥m wá⁠ʻeֽd׃"],[145,2,"בְּ⁠כָל־י֥וֹם אֲבָרֲכֶ֑⁠ךָּ וַ⁠אֲהַלְלָ֥ה שִׁ֝מְ⁠ךָ֗ לְ⁠עוֹלָ֥ם וָ⁠עֶֽד׃","bĕ̇⁠kál-y֥wòm ʼàbáràke֑⁠ká̇ wa⁠ʼàhalĕlá֥h şǐ֝mĕ⁠ká֗ lĕ⁠ʻwòlá֥m wá⁠ʻeֽd׃"],[145,3,"גָּ֘ד֤וֹל יְהוָ֣ה וּ⁠מְהֻלָּ֣ל מְאֹ֑ד וְ֝⁠לִ⁠גְדֻלָּת֗⁠וֹ אֵ֣ין חֵֽקֶר׃","gá̇֘d֤wòl yĕhwá֣h ẇ⁠mĕhulá֣̇l mĕʼò֑d wĕ֝⁠li⁠gĕdulá̇ţ֗⁠wò ʼé֣yn ẖéֽqer׃"],[145,4,"דּ֣וֹר לְ֭⁠דוֹר יְשַׁבַּ֣ח מַעֲשֶׂ֑י⁠ךָ וּ⁠גְב֖וּרֹתֶ֣י⁠ךָ יַגִּֽידוּ׃","ḋ֣wòr lĕ֭⁠dwòr yĕşǎbȧ֣ẖ maʻàşê֑y⁠ká ẇ⁠gĕb֖ẇròţe֣y⁠ká yagiֽ̇ydẇ׃"],[145,5,"הֲ֭דַר כְּב֣וֹד הוֹדֶ֑⁠ךָ וְ⁠דִבְרֵ֖י נִפְלְאוֹתֶ֣י⁠ךָ אָשִֽׂיחָה׃","hà֭dar kĕ̇b֣wòd hwòde֑⁠ká wĕ⁠dibĕré֖y nipĕlĕʼwòţe֣y⁠ká ʼáşîֽyẖáh׃"],[145,6,"וֶ⁠עֱז֣וּז נוֹרְאֹתֶ֣י⁠ךָ יֹאמֵ֑רוּ ו⁠גדולתי⁠ך אֲסַפְּרֶֽ⁠נָּה׃","we⁠ʻèz֣ẇz nwòrĕʼòţe֣y⁠ká yòʼmé֑rẇ w⁠gdwlţy⁠k ʼàsapĕ̇reֽ⁠ná̇h׃"],[145,7,"זֵ֣כֶר רַב־טוּבְ⁠ךָ֣ יַבִּ֑יעוּ וְ⁠צִדְקָתְ⁠ךָ֥ יְרַנֵּֽנוּ׃","zé֣ker rab-tẇbĕ⁠ká֣ yabi֑̇yʻẇ wĕ⁠ẕidĕqáţĕ⁠ká֥ yĕranéֽ̇nẇ׃"],[145,8,"חַנּ֣וּן וְ⁠רַח֣וּם יְהוָ֑ה אֶ֥רֶךְ אַ֝פַּ֗יִם וּ⁠גְדָל־חָֽסֶד׃","ẖaṅ֣ẇn wĕ⁠raẖ֣ẇm yĕhwá֑h ʼe֥rekĕ ʼa֝pȧ֗yim ẇ⁠gĕdál-ẖáֽsed׃"],[145,9,"טוֹב־יְהוָ֥ה לַ⁠כֹּ֑ל וְ֝⁠רַחֲמָ֗י⁠ו עַל־כָּל־מַעֲשָֽׂי⁠ו׃","twòb-yĕhwá֥h la⁠kò֑̇l wĕ֝⁠raẖàmá֗y⁠w ʻal-ká̇l-maʻàşáֽ̂y⁠w׃"],[145,10,"יוֹד֣וּ⁠ךָ יְ֭הוָה כָּל־מַעֲשֶׂ֑י⁠ךָ וַ֝⁠חֲסִידֶ֗י⁠ךָ יְבָרֲכֽוּ⁠כָה׃","ywòd֣ẇ⁠ká yĕ֭hwáh ká̇l-maʻàşê֑y⁠ká wa֝⁠ẖàsiyde֗y⁠ká yĕbáràkֽẇ⁠káh׃"],[145,11,"כְּב֣וֹד מַלְכוּתְ⁠ךָ֣ יֹאמֵ֑רוּ וּ⁠גְבוּרָתְ⁠ךָ֥ יְדַבֵּֽרוּ׃","kĕ̇b֣wòd malĕkẇţĕ⁠ká֣ yòʼmé֑rẇ ẇ⁠gĕbẇráţĕ⁠ká֥ yĕdabéֽ̇rẇ׃"],[145,12,"לְ⁠הוֹדִ֤יעַ ׀ לִ⁠בְנֵ֣י הָ֭⁠אָדָם גְּבוּרֹתָ֑י⁠ו וּ֝⁠כְב֗וֹד הֲדַ֣ר מַלְכוּתֽ⁠וֹ׃","lĕ⁠hwòdi֤yʻa ׀ li⁠bĕné֣y há֭⁠ʼádám gĕ̇bẇròţá֑y⁠w ẇ֝⁠kĕb֗wòd hàda֣r malĕkẇţֽ⁠wò׃"],[145,13,"מַֽלְכוּתְ⁠ךָ֗ מַלְכ֥וּת כָּל־עֹֽלָמִ֑ים וּ֝⁠מֶֽמְשֶׁלְתְּ⁠ךָ֗ בְּ⁠כָל־דּ֥וֹר וָ⁠דֽוֹר׃","maֽlĕkẇţĕ⁠ká֗ malĕk֥ẇţ ká̇l-ʻòֽlámi֑ym ẇ֝⁠meֽmĕşělĕţĕ̇⁠ká֗ bĕ̇⁠kál-ḋ֥wòr wá⁠dֽwòr׃"],[145,14,"סוֹמֵ֣ךְ יְ֭הוָה לְ⁠כָל־הַ⁠נֹּפְלִ֑ים וְ֝⁠זוֹקֵ֗ף לְ⁠כָל־הַ⁠כְּפוּפִֽים׃","swòmé֣kĕ yĕ֭hwáh lĕ⁠kál-ha⁠nò̇pĕli֑ym wĕ֝⁠zwòqé֗p lĕ⁠kál-ha⁠kĕ̇pẇpiֽym׃"],[145,15,"עֵֽינֵי־כֹ֭ל אֵלֶ֣י⁠ךָ יְשַׂבֵּ֑רוּ וְ⁠אַתָּ֤ה נֽוֹתֵן־לָ⁠הֶ֖ם אֶת־אָכְלָ֣⁠ם בְּ⁠עִתּֽ⁠וֹ׃","ʻéֽynéy-kò֭l ʼéle֣y⁠ká yĕşâbé֑̇rẇ wĕ⁠ʼaţá֤̇h nֽwòţén-lá⁠he֖m ʼeţ-ʼákĕlá֣⁠m bĕ̇⁠ʻiţֽ̇⁠wò׃"],[145,16,"פּוֹתֵ֥חַ אֶת־יָדֶ֑⁠ךָ וּ⁠מַשְׂבִּ֖יעַ לְ⁠כָל־חַ֣י רָצֽוֹן׃","ṗwòţé֥ẖa ʼeţ-yáde֑⁠ká ẇ⁠maşĕ̂bi֖̇yʻa lĕ⁠kál-ẖa֣y ráẕֽwòn׃"],[145,17,"צַדִּ֣יק יְ֭הוָה בְּ⁠כָל־דְּרָכָ֑י⁠ו וְ֝⁠חָסִ֗יד בְּ⁠כָל־מַעֲשָֽׂי⁠ו׃","ẕadi֣̇yq yĕ֭hwáh bĕ̇⁠kál-dĕ̇ráká֑y⁠w wĕ֝⁠ẖási֗yd bĕ̇⁠kál-maʻàşáֽ̂y⁠w׃"],[145,18,"קָר֣וֹב יְ֭הוָה לְ⁠כָל־קֹרְאָ֑י⁠ו לְ⁠כֹ֤ל אֲשֶׁ֖ר יִקְרָאֻ֣⁠הוּ בֶ⁠אֱמֶֽת׃","qár֣wòb yĕ֭hwáh lĕ⁠kál-qòrĕʼá֑y⁠w lĕ⁠kò֤l ʼàşě֖r yiqĕráʼu֣⁠hẇ be⁠ʼèmeֽţ׃"],[145,19,"רְצוֹן־יְרֵאָ֥י⁠ו יַעֲשֶׂ֑ה וְֽ⁠אֶת־שַׁוְעָתָ֥⁠ם יִ֝שְׁמַ֗ע וְ⁠יוֹשִׁיעֵֽ⁠ם׃","rĕẕwòn-yĕréʼá֥y⁠w yaʻàşê֑h wĕֽ⁠ʼeţ-şǎwĕʻáţá֥⁠m yi֝şĕ̌ma֗ʻ wĕ⁠ywòşǐyʻéֽ⁠m׃"],[145,20,"שׁוֹמֵ֣ר יְ֭הוָה אֶת־כָּל־אֹהֲבָ֑י⁠ו וְ⁠אֵ֖ת כָּל־הָ⁠רְשָׁעִ֣ים יַשְׁמִֽיד׃","ş̌wòmé֣r yĕ֭hwáh ʼeţ-ká̇l-ʼòhàbá֑y⁠w wĕ⁠ʼé֖ţ ká̇l-há⁠rĕşá̌ʻi֣ym yaşĕ̌miֽyd׃"],[145,21,"תְּהִלַּ֥ת יְהוָ֗ה יְֽדַבֶּ֫ר־פִּ֥⁠י וִ⁠יבָרֵ֣ךְ כָּל־בָּ֭שָׂר שֵׁ֥ם קָדְשׁ֗⁠וֹ לְ⁠עוֹלָ֥ם וָ⁠עֶֽד׃","ţĕ̇hilȧ֥ţ yĕhwá֗h yĕֽdabė֫r-pi֥̇⁠y wi⁠ybáré֣kĕ ká̇l-bá֭̇şá̂r şé֥̌m qádĕş̌֗⁠wò lĕ⁠ʻwòlá֥m wá⁠ʻeֽd׃"],[146,1,"הַֽלְלוּ־יָ֡הּ הַלְלִ֥י נַ֝פְשִׁ֗⁠י אֶת־יְהוָֽה׃","haֽlĕlẇ-yá֡ḣ halĕli֥y na֝pĕşǐ֗⁠y ʼeţ-yĕhwáֽh׃"],[146,2,"אֲהַלְלָ֣ה יְהוָ֣ה בְּ⁠חַיָּ֑⁠י אֲזַמְּרָ֖ה לֵֽ⁠אלֹהַ֣⁠י בְּ⁠עוֹדִֽ⁠י׃","ʼàhalĕlá֣h yĕhwá֣h bĕ̇⁠ẖayá֑̇⁠y ʼàzamĕ̇rá֖h léֽ⁠ʼlòha֣⁠y bĕ̇⁠ʻwòdiֽ⁠y׃"],[146,3,"אַל־תִּבְטְח֥וּ בִ⁠נְדִיבִ֑ים בְּ⁠בֶן־אָדָ֓ם ׀ שֶׁ֤⁠אֵֽין ל֥⁠וֹ תְשׁוּעָֽה׃","ʼal-ţi̇bĕtĕẖ֥ẇ bi⁠nĕdiybi֑ym bĕ̇⁠ben-ʼádá֓m ׀ şě֤⁠ʼéֽyn l֥⁠wò ţĕş̌ẇʻáֽh׃"],[146,4,"תֵּצֵ֣א ר֭וּח⁠וֹ יָשֻׁ֣ב לְ⁠אַדְמָת֑⁠וֹ בַּ⁠יּ֥וֹם הַ֝⁠ה֗וּא אָבְד֥וּ עֶשְׁתֹּנֹתָֽי⁠ו׃","ţé̇ẕé֣ʼ r֭ẇẖ⁠wò yáşǔ֣b lĕ⁠ʼadĕmáţ֑⁠wò bȧ⁠ẏ֥wòm ha֝⁠h֗ẇʼ ʼábĕd֥ẇ ʻeşĕ̌ţò̇nòţáֽy⁠w׃"],[146,5,"אַשְׁרֵ֗י שֶׁ֤⁠אֵ֣ל יַעֲקֹ֣ב בְּ⁠עֶזְר֑⁠וֹ שִׂ֝בְר֗⁠וֹ עַל־יְהוָ֥ה אֱלֹהָֽי⁠ו׃","ʼaşĕ̌ré֗y şě֤⁠ʼé֣l yaʻàqò֣b bĕ̇⁠ʻezĕr֑⁠wò şî֝bĕr֗⁠wò ʻal-yĕhwá֥h ʼèlòháֽy⁠w׃"],[146,6,"עֹשֶׂ֤ה ׀ שָׁ֘מַ֤יִם וָ⁠אָ֗רֶץ אֶת־הַ⁠יָּ֥ם וְ⁠אֶת־כָּל־אֲשֶׁר־בָּ֑⁠ם הַ⁠שֹּׁמֵ֖ר אֱמֶ֣ת לְ⁠עוֹלָֽם׃","ʻòşê֤h ׀ şá̌֘ma֤yim wá⁠ʼá֗reẕ ʼeţ-ha⁠yá֥̇m wĕ⁠ʼeţ-ká̇l-ʼàşěr-bá֑̇⁠m ha⁠şò̇̌mé֖r ʼème֣ţ lĕ⁠ʻwòláֽm׃"],[146,7,"עֹשֶׂ֤ה מִשְׁפָּ֨ט ׀ לָ⁠עֲשׁוּקִ֗ים נֹתֵ֣ן לֶ֭חֶם לָ⁠רְעֵבִ֑ים יְ֝הוָ֗ה מַתִּ֥יר אֲסוּרִֽים׃","ʻòşê֤h mişĕ̌pá̇֨t ׀ lá⁠ʻàş̌ẇqi֗ym nòţé֣n le֭ẖem lá⁠rĕʻébi֑ym yĕ֝hwá֗h maţi֥̇yr ʼàsẇriֽym׃"],[146,8,"יְהוָ֤ה ׀ פֹּ֘קֵ֤חַ עִוְרִ֗ים יְ֭הוָה זֹקֵ֣ף כְּפוּפִ֑ים יְ֝הוָ֗ה אֹהֵ֥ב צַדִּיקִֽים׃","yĕhwá֤h ׀ pò̇֘qé֤ẖa ʻiwĕri֗ym yĕ֭hwáh zòqé֣p kĕ̇pẇpi֑ym yĕ֝hwá֗h ʼòhé֥b ẕadi̇yqiֽym׃"],[146,9,"יְהוָ֤ה ׀ שֹׁ֘מֵ֤ר אֶת־גֵּרִ֗ים יָת֣וֹם וְ⁠אַלְמָנָ֣ה יְעוֹדֵ֑ד וְ⁠דֶ֖רֶךְ רְשָׁעִ֣ים יְעַוֵּֽת׃","yĕhwá֤h ׀ şò̌֘mé֤r ʼeţ-gé̇ri֗ym yáţ֣wòm wĕ⁠ʼalĕmáná֣h yĕʻwòdé֑d wĕ⁠de֖rekĕ rĕşá̌ʻi֣ym yĕʻawéֽ̇ţ׃"],[146,10,"יִמְלֹ֤ךְ יְהוָ֨ה ׀ לְ⁠עוֹלָ֗ם אֱלֹהַ֣יִ⁠ךְ צִ֭יּוֹן לְ⁠דֹ֥ר וָ⁠דֹ֗ר הַֽלְלוּ־יָֽהּ׃","yimĕlò֤kĕ yĕhwá֨h ׀ lĕ⁠ʻwòlá֗m ʼèlòha֣yi⁠kĕ ẕi֭ẏwòn lĕ⁠dò֥r wá⁠dò֗r haֽlĕlẇ-yáֽḣ׃"],[147,1,"הַ֥לְלוּ יָ֨הּ ׀ כִּי־ט֭וֹב זַמְּרָ֣ה אֱלֹהֵ֑י⁠נוּ כִּֽי־נָ֝עִים נָאוָ֥ה תְהִלָּֽה׃","ha֥lĕlẇ yá֨ḣ ׀ ki̇y-t֭wòb zamĕ̇rá֣h ʼèlòhé֑y⁠nẇ kiֽ̇y-ná֝ʻiym náʼwá֥h ţĕhiláֽ̇h׃"],[147,2,"בּוֹנֵ֣ה יְרוּשָׁלִַ֣ם יְהוָ֑ה נִדְחֵ֖י יִשְׂרָאֵ֣ל יְכַנֵּֽס׃","ḃwòné֣h yĕrẇşá̌lia֣m yĕhwá֑h nidĕẖé֖y yişĕ̂ráʼé֣l yĕkanéֽ̇s׃"],[147,3,"הָ֭⁠רֹפֵא לִ⁠שְׁב֣וּרֵי לֵ֑ב וּ֝⁠מְחַבֵּ֗שׁ לְ⁠עַצְּבוֹתָֽ⁠ם׃","há֭⁠ròpéʼ li⁠şĕ̌b֣ẇréy lé֑b ẇ֝⁠mĕẖabé̇֗ş̌ lĕ⁠ʻaẕĕ̇bwòţáֽ⁠m׃"],[147,4,"מוֹנֶ֣ה מִ֭סְפָּר לַ⁠כּוֹכָבִ֑ים לְ֝⁠כֻלָּ֗⁠ם שֵׁמ֥וֹת יִקְרָֽא׃","mwòne֣h mi֭sĕpá̇r la⁠k̇wòkábi֑ym lĕ֝⁠kulá̇֗⁠m şé̌m֥wòţ yiqĕráֽʼ׃"],[147,5,"גָּד֣וֹל אֲדוֹנֵ֣י⁠נוּ וְ⁠רַב־כֹּ֑חַ לִ֝⁠תְבוּנָת֗⁠וֹ אֵ֣ין מִסְפָּֽר׃","gá̇d֣wòl ʼàdwòné֣y⁠nẇ wĕ⁠rab-kò֑̇ẖa li֝⁠ţĕbẇnáţ֗⁠wò ʼé֣yn misĕpáֽ̇r׃"],[147,6,"מְעוֹדֵ֣ד עֲנָוִ֣ים יְהוָ֑ה מַשְׁפִּ֖יל רְשָׁעִ֣ים עֲדֵי־אָֽרֶץ׃","mĕʻwòdé֣d ʻànáwi֣ym yĕhwá֑h maşĕ̌pi֖̇yl rĕşá̌ʻi֣ym ʻàdéy-ʼáֽreẕ׃"],[147,7,"עֱנ֣וּ לַ⁠יהוָ֣ה בְּ⁠תוֹדָ֑ה זַמְּר֖וּ לֵ⁠אלֹהֵ֣י⁠נוּ בְ⁠כִנּֽוֹר׃","ʻèn֣ẇ la⁠yhwá֣h bĕ̇⁠ţwòdá֑h zamĕ̇r֖ẇ lé⁠ʼlòhé֣y⁠nẇ bĕ⁠kiṅֽwòr׃"],[147,8,"הַֽ⁠מְכַסֶּ֬ה שָׁמַ֨יִם ׀ בְּ⁠עָבִ֗ים הַ⁠מֵּכִ֣ין לָ⁠אָ֣רֶץ מָטָ֑ר הַ⁠מַּצְמִ֖יחַ הָרִ֣ים חָצִֽיר׃","haֽ⁠mĕkasė֬h şá̌ma֨yim ׀ bĕ̇⁠ʻábi֗ym ha⁠mé̇ki֣yn lá⁠ʼá֣reẕ mátá֑r ha⁠mȧẕĕmi֖yẖa hári֣ym ẖáẕiֽyr׃"],[147,9,"נוֹתֵ֣ן לִ⁠בְהֵמָ֣ה לַחְמָ֑⁠הּ לִ⁠בְנֵ֥י עֹ֝רֵ֗ב אֲשֶׁ֣ר יִקְרָֽאוּ׃","nwòţé֣n li⁠bĕhémá֣h laẖĕmá֑⁠ḣ li⁠bĕné֥y ʻò֝ré֗b ʼàşě֣r yiqĕráֽʼẇ׃"],[147,10,"לֹ֤א בִ⁠גְבוּרַ֣ת הַ⁠סּ֣וּס יֶחְפָּ֑ץ לֹֽא־בְ⁠שׁוֹקֵ֖י הָ⁠אִ֣ישׁ יִרְצֶֽה׃","lò֤ʼ bi⁠gĕbẇra֣ţ ha⁠ṡ֣ẇs yeẖĕpá֑̇ẕ lòֽʼ-bĕ⁠ş̌wòqé֖y há⁠ʼi֣yş̌ yirĕẕeֽh׃"],[147,11,"רוֹצֶ֣ה יְ֭הוָה אֶת־יְרֵאָ֑י⁠ו אֶת־הַֽ⁠מְיַחֲלִ֥ים לְ⁠חַסְדּֽ⁠וֹ׃","rwòẕe֣h yĕ֭hwáh ʼeţ-yĕréʼá֑y⁠w ʼeţ-haֽ⁠mĕyaẖàli֥ym lĕ⁠ẖasĕḋֽ⁠wò׃"],[147,12,"שַׁבְּחִ֣י יְ֭רוּשָׁלִַם אֶת־יְהוָ֑ה הַֽלְלִ֖י אֱלֹהַ֣יִ⁠ךְ צִיּֽוֹן׃","şǎbĕ̇ẖi֣y yĕ֭rẇşá̌liam ʼeţ-yĕhwá֑h haֽlĕli֖y ʼèlòha֣yi⁠kĕ ẕiẏֽwòn׃"],[147,13,"כִּֽי־חִ֭זַּק בְּרִיחֵ֣י שְׁעָרָ֑יִ⁠ךְ בֵּרַ֖ךְ בָּנַ֣יִ⁠ךְ בְּ⁠קִרְבֵּֽ⁠ךְ׃","kiֽ̇y-ẖi֭zȧq bĕ̇riyẖé֣y şĕ̌ʻárá֑yi⁠kĕ bé̇ra֖kĕ bá̇na֣yi⁠kĕ bĕ̇⁠qirĕbéֽ̇⁠kĕ׃"],[147,14,"הַ⁠שָּׂם־גְּבוּלֵ֥⁠ךְ שָׁל֑וֹם חֵ֥לֶב חִ֝טִּ֗ים יַשְׂבִּיעֵֽ⁠ךְ׃","ha⁠şá̇̂m-gĕ̇bẇlé֥⁠kĕ şá̌l֑wòm ẖé֥leb ẖi֝ti̇֗ym yaşĕ̂bi̇yʻéֽ⁠kĕ׃"],[147,15,"הַ⁠שֹּׁלֵ֣חַ אִמְרָת֣⁠וֹ אָ֑רֶץ עַד־מְ֝הֵרָ֗ה יָר֥וּץ דְּבָרֽ⁠וֹ׃","ha⁠şò̇̌lé֣ẖa ʼimĕráţ֣⁠wò ʼá֑reẕ ʻad-mĕ֝hérá֗h yár֥ẇẕ dĕ̇bárֽ⁠wò׃"],[147,16,"הַ⁠נֹּתֵ֣ן שֶׁ֣לֶג כַּ⁠צָּ֑מֶר כְּ֝פ֗וֹר כָּ⁠אֵ֥פֶר יְפַזֵּֽר׃","ha⁠nò̇ţé֣n şě֣leg kȧ⁠ẕá֑̇mer kĕ̇֝p֗wòr ká̇⁠ʼé֥per yĕpazéֽ̇r׃"],[147,17,"מַשְׁלִ֣יךְ קַֽרְח֣⁠וֹ כְ⁠פִתִּ֑ים לִ⁠פְנֵ֥י קָ֝רָת֗⁠וֹ מִ֣י יַעֲמֹֽד׃","maşĕ̌li֣ykĕ qaֽrĕẖ֣⁠wò kĕ⁠piţi֑̇ym li⁠pĕné֥y qá֝ráţ֗⁠wò mi֣y yaʻàmòֽd׃"],[147,18,"יִשְׁלַ֣ח דְּבָר֣⁠וֹ וְ⁠יַמְסֵ֑⁠ם יַשֵּׁ֥ב ר֝וּח֗⁠וֹ יִזְּלוּ־מָֽיִם׃","yişĕ̌la֣ẖ dĕ̇bár֣⁠wò wĕ⁠yamĕsé֑⁠m yaşé֥̇̌b r֝ẇẖ֗⁠wò yizĕ̇lẇ-máֽyim׃"],[147,19,"מַגִּ֣יד דבר⁠ו לְ⁠יַעֲקֹ֑ב חֻקָּ֥י⁠ו וּ֝⁠מִשְׁפָּטָ֗י⁠ו לְ⁠יִשְׂרָאֵֽל׃","magi֣̇yd dbr⁠w lĕ⁠yaʻàqò֑b ẖuqá֥̇y⁠w ẇ֝⁠mişĕ̌pá̇tá֗y⁠w lĕ⁠yişĕ̂ráʼéֽl׃"],[147,20,"לֹ֘א עָ֤שָׂה כֵ֨ן ׀ לְ⁠כָל־גּ֗וֹי וּ⁠מִשְׁפָּטִ֥ים בַּל־יְדָע֗וּ⁠ם הַֽלְלוּ־יָֽהּ׃","lò֘ʼ ʻá֤şá̂h ké֨n ׀ lĕ⁠kál-ġ֗wòy ẇ⁠mişĕ̌pá̇ti֥ym bȧl-yĕdáʻ֗ẇ⁠m haֽlĕlẇ-yáֽḣ׃"],[148,1,"הַ֥לְלוּ יָ֨הּ ׀ הַֽלְל֣וּ אֶת־יְ֭הוָה מִן־הַ⁠שָּׁמַ֑יִם הַֽ֝לְל֗וּ⁠הוּ בַּ⁠מְּרוֹמִֽים׃","ha֥lĕlẇ yá֨ḣ ׀ haֽlĕl֣ẇ ʼeţ-yĕ֭hwáh min-ha⁠şá̇̌ma֑yim hֽa֝lĕl֗ẇ⁠hẇ bȧ⁠mĕ̇rwòmiֽym׃"],[148,2,"הַֽלְל֥וּ⁠הוּ כָל־מַלְאָכָ֑י⁠ו הַֽ֝לְל֗וּ⁠הוּ כָּל־צבא⁠ו׃","hֽalĕl֥ẇ⁠hẇ kál-malĕʼáká֑y⁠w haֽ֝lĕl֗ẇ⁠hẇ ká̇l-ẕbʼ⁠w׃"],[148,3,"הַֽ֭לְלוּ⁠הוּ שֶׁ֣מֶשׁ וְ⁠יָרֵ֑חַ הַ֝לְל֗וּ⁠הוּ כָּל־כּ֥וֹכְבֵי אֽוֹר׃","haֽ֭lĕlẇ⁠hẇ şě֣meş̌ wĕ⁠yáré֑ẖa ha֝lĕl֗ẇ⁠hẇ ká̇l-k֥̇wòkĕbéy ʼֽwòr׃"],[148,4,"הַֽ֭לְלוּ⁠הוּ שְׁמֵ֣י הַ⁠שָּׁמָ֑יִם וְ֝⁠הַ⁠מַּ֗יִם אֲשֶׁ֤ר ׀ מֵ⁠עַ֬ל הַ⁠שָּׁמָֽיִם׃","haֽ֭lĕlẇ⁠hẇ şĕ̌mé֣y ha⁠şá̇̌má֑yim wĕ֝⁠ha⁠mȧ֗yim ʼàşě֤r ׀ mé⁠ʻa֬l ha⁠şá̇̌máֽyim׃"],[148,5,"יְֽ֭הַֽלְלוּ אֶת־שֵׁ֣ם יְהוָ֑ה כִּ֤י ה֭וּא צִוָּ֣ה וְ⁠נִבְרָֽאוּ׃","yĕֽ֭haֽlĕlẇ ʼeţ-şé֣̌m yĕhwá֑h ki֤̇y h֭ẇʼ ẕiwá֣̇h wĕ⁠nibĕráֽʼẇ׃"],[148,6,"וַ⁠יַּעֲמִידֵ֣⁠ם לָ⁠עַ֣ד לְ⁠עוֹלָ֑ם חָק־נָ֝תַ֗ן וְ⁠לֹ֣א יַעֲבֽוֹר׃","wa⁠yȧʻàmiydé֣⁠m lá⁠ʻa֣d lĕ⁠ʻwòlá֑m ẖáq-ná֝ţa֗n wĕ⁠lò֣ʼ yaʻàbֽwòr׃"],[148,7,"הַֽלְל֣וּ אֶת־יְ֭הוָה מִן־הָ⁠אָ֑רֶץ תַּ֝נִּינִ֗ים וְ⁠כָל־תְּהֹמֽוֹת׃","haֽlĕl֣ẇ ʼeţ-yĕ֭hwáh min-há⁠ʼá֑reẕ ţȧ֝ni̇yni֗ym wĕ⁠kál-ţĕ̇hòmֽwòţ׃"],[148,8,"אֵ֣שׁ וּ֭⁠בָרָד שֶׁ֣לֶג וְ⁠קִיט֑וֹר ר֥וּחַ סְ֝עָרָ֗ה עֹשָׂ֥ה דְבָרֽ⁠וֹ׃","ʼé֣ş̌ ẇ֭⁠bárád şě֣leg wĕ⁠qiyt֑wòr r֥ẇẖa sĕ֝ʻárá֗h ʻòşá֥̂h dĕbárֽ⁠wò׃"],[148,9,"הֶ⁠הָרִ֥ים וְ⁠כָל־גְּבָע֑וֹת עֵ֥ץ פְּ֝רִ֗י וְ⁠כָל־אֲרָזִֽים׃","he⁠hári֥ym wĕ⁠kál-gĕ̇báʻ֑wòţ ʻé֥ẕ pĕ̇֝ri֗y wĕ⁠kál-ʼàráziֽym׃"],[148,10,"הַֽ⁠חַיָּ֥ה וְ⁠כָל־בְּהֵמָ֑ה רֶ֝֗מֶשׂ וְ⁠צִפּ֥וֹר כָּנָֽף׃","haֽ⁠ẖayá֥̇h wĕ⁠kál-bĕ̇hémá֑h re֝֗meş̂ wĕ⁠ẕiṗ֥wòr ká̇náֽp׃"],[148,11,"מַלְכֵי־אֶ֭רֶץ וְ⁠כָל־לְאֻמִּ֑ים שָׂ֝רִ֗ים וְ⁠כָל־שֹׁ֥פְטֵי אָֽרֶץ׃","malĕkéy-ʼe֭reẕ wĕ⁠kál-lĕʼumi֑̇ym şá̂֝ri֗ym wĕ⁠kál-şò֥̌pĕtéy ʼáֽreẕ׃"],[148,12,"בַּחוּרִ֥ים וְ⁠גַם־בְּתוּל֑וֹת זְ֝קֵנִ֗ים עִם־נְעָרִֽים׃","bȧẖẇri֥ym wĕ⁠gam-bĕ̇ţẇl֑wòţ zĕ֝qéni֗ym ʻim-nĕʻárֽiym׃"],[148,13,"יְהַלְל֤וּ ׀ אֶת־שֵׁ֬ם יְהוָ֗ה כִּֽי־נִשְׂגָּ֣ב שְׁמ֣⁠וֹ לְ⁠בַדּ֑⁠וֹ ה֝וֹד֗⁠וֹ עַל־אֶ֥רֶץ וְ⁠שָׁמָֽיִם׃","yĕhalĕl֤ẇ ׀ ʼeţ-şé̌֬m yĕhwá֗h kiֽ̇y-nişĕ̂gá֣̇b şĕ̌m֣⁠wò lĕ⁠baḋ֑⁠wò h֝wòd֗⁠wò ʻal-ʼe֥reẕ wĕ⁠şá̌máֽyim׃"],[148,14,"וַ⁠יָּ֤רֶם קֶ֨רֶן ׀ לְ⁠עַמּ֡⁠וֹ תְּהִלָּ֤ה לְֽ⁠כָל־חֲסִידָ֗י⁠ו לִ⁠בְנֵ֣י יִ֭שְׂרָאֵל עַֽם־קְרֹב֗⁠וֹ הַֽלְלוּ־יָֽהּ׃","wa⁠yá֤̇rem qe֨ren ׀ lĕ⁠ʻaṁ֡⁠wò ţĕ̇hilá֤̇h lĕֽ⁠kál-ẖàsiydá֗y⁠w li⁠bĕné֣y yi֭şĕ̂ráʼél ʻaֽm-qĕròb֗⁠wò haֽlĕlẇ-yáֽḣ׃"],[149,1,"הַ֥לְלוּ יָ֨הּ ׀ שִׁ֣ירוּ לַֽ֭⁠יהוָה שִׁ֣יר חָדָ֑שׁ תְּ֝הִלָּת֗⁠וֹ בִּ⁠קְהַ֥ל חֲסִידִֽים׃","ha֥lĕlẇ yá֨ḣ ׀ şǐ֣yrẇ laֽ֭⁠yhwáh şǐ֣yr ẖádá֑ş̌ ţĕ̇֝hilá̇ţ֗⁠wò bi̇⁠qĕha֥l ẖàsiydiֽym׃"],[149,2,"יִשְׂמַ֣ח יִשְׂרָאֵ֣ל בְּ⁠עֹשָׂ֑י⁠ו בְּנֵֽי־צִ֝יּ֗וֹן יָגִ֥ילוּ בְ⁠מַלְכָּֽ⁠ם׃","yişĕ̂ma֣ẖ yişĕ̂ráʼé֣l bĕ̇⁠ʻòşá֑̂y⁠w bĕ̇néֽy-ẕi֝ẏ֗wòn yági֥ylẇ bĕ⁠malĕkáֽ̇⁠m׃"],[149,3,"יְהַֽלְל֣וּ שְׁמ֣⁠וֹ בְ⁠מָח֑וֹל בְּ⁠תֹ֥ף וְ֝⁠כִנּ֗וֹר יְזַמְּרוּ־לֽ⁠וֹ׃","yĕhaֽlĕl֣ẇ şĕ̌m֣⁠wò bĕ⁠máẖ֑wòl bĕ̇⁠ţò֥p wĕ֝⁠kiṅ֗wòr yĕzamĕ̇rẇ-lֽ⁠wò׃"],[149,4,"כִּֽי־רוֹצֶ֣ה יְהוָ֣ה בְּ⁠עַמּ֑⁠וֹ יְפָאֵ֥ר עֲ֝נָוִ֗ים בִּ⁠ישׁוּעָֽה׃","kiֽ̇y-rwòẕe֣h yĕhwá֣h bĕ̇⁠ʻaṁ֑⁠wò yĕpáʼé֥r ʻà֝náwi֗ym bi̇⁠yş̌ẇʻáֽh׃"],[149,5,"יַעְלְז֣וּ חֲסִידִ֣ים בְּ⁠כָב֑וֹד יְ֝רַנְּנ֗וּ עַל־מִשְׁכְּבוֹתָֽ⁠ם׃","yaʻĕlĕz֣ẇ ẖàsiydi֣ym bĕ̇⁠káb֑wòd yĕ֝ranĕ̇n֗ẇ ʻal-mişĕ̌kĕ̇bwòţáֽ⁠m׃"],[149,6,"רוֹמְמ֣וֹת אֵ֭ל בִּ⁠גְרוֹנָ֑⁠ם וְ⁠חֶ֖רֶב פִּֽיפִיּ֣וֹת בְּ⁠יָדָֽ⁠ם׃","rwòmĕm֣wòţ ʼé֭l bi̇⁠gĕrwòná֑⁠m wĕ⁠ẖe֖reb piֽ̇ypiẏ֣wòţ bĕ̇⁠yádáֽ⁠m׃"],[149,7,"לַ⁠עֲשׂ֣וֹת נְ֭קָמָה בַּ⁠גּוֹיִ֑ם תּֽ֝וֹכֵחֹ֗ת בַּל־אֻמִּֽים׃","la⁠ʻàş֣̂wòţ nĕ֭qámáh bȧ⁠ġwòyi֑m ţֽ̇֝wòkéẖò֗ţ bȧl-ʼumiֽ̇ym׃"],[149,8,"לֶ⁠אְסֹ֣ר מַלְכֵי⁠הֶ֣ם בְּ⁠זִקִּ֑ים וְ֝⁠נִכְבְּדֵי⁠הֶ֗ם בְּ⁠כַבְלֵ֥י בַרְזֶֽל׃","le⁠ʼĕsò֣r malĕkéy⁠he֣m bĕ̇⁠ziqi֑̇ym wĕ֝⁠nikĕbĕ̇déy⁠he֗m bĕ̇⁠kabĕlé֥y barĕzeֽl׃"],[149,9,"לַ⁠עֲשׂ֤וֹת בָּ⁠הֶ֨ם ׀ מִשְׁפָּ֬ט כָּת֗וּב הָדָ֣ר ה֭וּא לְ⁠כָל־חֲסִידָ֗י⁠ו הַֽלְלוּ־יָֽהּ׃","la⁠ʻàş֤̂wòţ bá̇⁠he֨m ׀ mişĕ̌pá̇֬t ká̇ţ֗ẇb hádá֣r h֭ẇʼ lĕ⁠kál-ẖàsiydá֗y⁠w haֽlĕlẇ-yáֽḣ׃"],[150,1,"הַ֥לְלוּ יָ֨הּ ׀ הַֽלְלוּ־אֵ֥ל בְּ⁠קָדְשׁ֑⁠וֹ הַֽ֝לְל֗וּ⁠הוּ בִּ⁠רְקִ֥יעַ עֻזּֽ⁠וֹ׃","ha֥lĕlẇ yá֨ḣ ׀ haֽlĕlẇ-ʼé֥l bĕ̇⁠qádĕş֑̌⁠wò hֽa֝lĕl֗ẇ⁠hẇ bi̇⁠rĕqi֥yʻa ʻużֽ⁠wò׃"],[150,2,"הַֽלְל֥וּ⁠הוּ בִ⁠גְבוּרֹתָ֑י⁠ו הַֽ֝לְל֗וּ⁠הוּ כְּ⁠רֹ֣ב גֻּדְלֽ⁠וֹ׃","haֽlĕl֥ẇ⁠hẇ bi⁠gĕbẇròţá֑y⁠w hֽa֝lĕl֗ẇ⁠hẇ kĕ̇⁠rò֣b gu̇dĕlֽ⁠wò׃"],[150,3,"הַֽ֭לְלוּ⁠הוּ בְּ⁠תֵ֣קַע שׁוֹפָ֑ר הַֽ֝לְל֗וּ⁠הוּ בְּ⁠נֵ֣בֶל וְ⁠כִנּֽוֹר׃","haֽ֭lĕlẇ⁠hẇ bĕ̇⁠ţé֣qaʻ ş̌wòpá֑r haֽ֝lĕl֗ẇ⁠hẇ bĕ̇⁠né֣bel wĕ⁠kiṅֽwòr׃"],[150,4,"הַֽ֭לְלוּ⁠הוּ בְ⁠תֹ֣ף וּ⁠מָח֑וֹל הַֽ֝לְל֗וּ⁠הוּ בְּ⁠מִנִּ֥ים וְ⁠עוּגָֽב׃","haֽ֭lĕlẇ⁠hẇ bĕ⁠ţò֣p ẇ⁠máẖ֑wòl haֽ֝lĕl֗ẇ⁠hẇ bĕ̇⁠mini֥̇ym wĕ⁠ʻẇgáֽb׃"],[150,5,"הַֽלְל֥וּ⁠הוּ בְ⁠צִלְצְלֵי־שָׁ֑מַע הַֽ֝לְל֗וּ⁠הוּ בְּֽ⁠צִלְצְלֵ֥י תְרוּעָֽה׃","haֽlĕl֥ẇ⁠hẇ bĕ⁠ẕilĕẕĕléy-şá֑̌maʻ haֽ֝lĕl֗ẇ⁠hẇ bĕֽ̇⁠ẕilĕẕĕlé֥y ţĕrẇʻáֽh׃"],[150,6,"כֹּ֣ל הַ֭⁠נְּשָׁמָה תְּהַלֵּ֥ל יָ֗הּ הַֽלְלוּ־יָֽהּ׃","kò֣̇l ha֭⁠nĕ̇şá̌máh ţĕ̇halé֥̇l yá֗ḣ haֽlĕlẇ-yáֽḣ׃"]]}};